import { Scale } from "lucide-react";
import type { AutomationHook } from "../../lib/automation/model";
import {
  type AttachableRule,
  canAttachRules,
  rulesAttachedTo,
  rulesAvailableFor,
  type SameMoment,
} from "../../lib/eml/workflow-hooks";

interface WorkflowRulesProps {
  entity: string;
  hooks: AutomationHook[];
  rules: AttachableRule[];
  /** Move a rule onto a hook: the rule's event becomes the hook's. */
  onAttach: (ruleKey: string, event: string) => void;
  /** Where rules are written. They are not edited on this screen. */
  enhanceHref: string;
  /** What the link there says. */
  editLabel?: string;
  /** How a rule's event is matched to a hook's; exact unless the host says otherwise. */
  sameMoment?: SameMoment;
}

/**
 * The rules attached to each of a workflow's hooks.
 *
 * This is the only place a rule is attached. The rule itself — its table or
 * graph — is written on the Enhance step; here it is picked up and given a
 * moment to run, which is the hook it is attached to.
 */
export function WorkflowRules({
  entity,
  hooks,
  rules,
  onAttach,
  enhanceHref,
  editLabel = "Rules can also be edited in Enhance →",
  sameMoment,
}: WorkflowRulesProps) {
  const events = [...new Set(hooks.map((hook) => hook.event))];

  return (
    <section
      aria-label="Rules attached to this workflow"
      className="mt-4 rounded-xl border border-border bg-card p-4"
    >
      <div className="mb-3 flex items-center justify-between gap-3">
        <h3 className="flex items-center gap-2 text-sm font-semibold">
          <Scale className="h-4 w-4" />
          Rules attached to this workflow
        </h3>
        <a href={enhanceHref} className="text-xs font-medium text-primary hover:underline">
          {editLabel}
        </a>
      </div>

      {events.length === 0 && (
        <p className="text-xs text-muted-foreground">Add a hook above to attach rules to it.</p>
      )}

      <div className="space-y-3">
        {events.map((event) => {
          if (!canAttachRules(event)) {
            return (
              <div key={event} className="rounded-lg border border-dashed border-border px-3 py-2">
                <p className="text-sm font-medium">
                  <code className="font-mono">{event}</code>
                </p>
                <p className="text-xs text-muted-foreground">
                  Rules judge writes, so none can be attached to this hook.
                </p>
              </div>
            );
          }
          const attached = rulesAttachedTo(rules, entity, event, sameMoment);
          const available = rulesAvailableFor(rules, entity, event, sameMoment);
          return (
            <div key={event} className="rounded-lg border border-border px-3 py-2">
              <p className="text-sm font-medium">
                <code className="font-mono">{event}</code>
                <span className="ml-2 text-xs font-normal text-muted-foreground">
                  {attached.length} rule{attached.length === 1 ? "" : "s"} attached
                </span>
              </p>
              <ul className="mt-1.5 space-y-1">
                {attached.map((rule) => (
                  <li
                    key={rule.key}
                    className="flex items-center gap-2 rounded-md bg-primary/5 px-2 py-1 text-sm"
                  >
                    <Scale className="h-3.5 w-3.5 text-primary" />
                    {rule.title || rule.name}
                  </li>
                ))}
                {attached.length === 0 && (
                  <li className="text-xs text-muted-foreground">
                    Nothing attached to this hook yet.
                  </li>
                )}
              </ul>
              {available.length > 0 && (
                <label className="mt-2 flex items-center gap-2 text-xs">
                  <span className="font-medium">Attach a {entity} rule</span>
                  <select
                    aria-label={`Attach a rule to ${event}`}
                    className="rounded-md border border-border px-2 py-1 text-xs"
                    value=""
                    onChange={(e) => {
                      if (e.target.value) onAttach(e.target.value, event);
                    }}
                  >
                    <option value="">Choose a rule…</option>
                    {available.map((rule) => (
                      <option key={rule.key} value={rule.key}>
                        {rule.title || rule.name}
                      </option>
                    ))}
                  </select>
                </label>
              )}
            </div>
          );
        })}
      </div>
    </section>
  );
}

import { Workflow as WorkflowIcon } from "lucide-react";
import { useState } from "react";
import type { HookEvent } from "../../lib/automation/model";
import {
  canBindStatus,
  HOOK_CHOICES,
  type StatusChoices,
} from "../../lib/eml/workflow-hooks";

export interface NewWorkflowDraft {
  name: string;
  entity: string;
  event: HookEvent;
  /** The state whose entering move runs the workflow; unset runs on every update. */
  status?: string;
}

interface NewWorkflowPanelProps {
  entityNames: string[];
  /** What the chosen record type can be bound to; omitted means no status picker. */
  statusChoicesFor?: (entity: string) => StatusChoices;
  onCreate: (draft: NewWorkflowDraft) => void;
  onCancel?: () => void;
}

/**
 * Where a workflow begins: what it is called, which record type it watches, and
 * which hooks it listens on. The ladder, the steps and the rules attached to
 * each hook all come after, because they all hang off these choices.
 */
export function NewWorkflowPanel({
  entityNames,
  statusChoicesFor,
  onCreate,
  onCancel,
}: NewWorkflowPanelProps) {
  const [name, setName] = useState("");
  const [entity, setEntity] = useState(entityNames[0] ?? "");
  const [event, setEvent] = useState<HookEvent>("beforeCreate");
  const [status, setStatus] = useState("");
  const chosen = HOOK_CHOICES.find((choice) => choice.event === event);
  const choices = statusChoicesFor && entity ? statusChoicesFor(entity) : undefined;
  const bindable = choices !== undefined && canBindStatus(event);
  const boundStatus = bindable && choices.kind === "machine" ? status : "";

  const problem = !name.trim()
    ? "Give the workflow a name."
    : !entity
      ? "Choose the record type it watches."
      : null;

  return (
    <section
      aria-label="Create a workflow"
      className="rounded-xl border border-border bg-card p-6 shadow-sm"
    >
      <div className="mb-5 flex items-start gap-3">
        <div className="rounded-lg bg-primary/10 p-2 text-primary">
          <WorkflowIcon className="h-5 w-5" />
        </div>
        <div>
          <h2 className="text-lg font-semibold">New workflow</h2>
          <p className="text-sm text-muted-foreground">
            Start with the hook it attaches to. Rules are attached to that hook next, and steps come
            after.
          </p>
        </div>
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <label className="block">
          <span className="mb-1 block text-xs font-medium">Workflow name</span>
          <input
            className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Lead intake"
          />
        </label>
        <label className="block">
          <span className="mb-1 block text-xs font-medium">Watches</span>
          <select
            className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
            value={entity}
            onChange={(e) => {
              setEntity(e.target.value);
              setStatus("");
            }}
          >
            <option value="">Choose…</option>
            {entityNames.map((n) => (
              <option key={n} value={n}>
                {n}
              </option>
            ))}
          </select>
        </label>
      </div>

      <label className="mt-4 block">
        <span className="mb-1 block text-xs font-medium">Attach it to this hook</span>
        <select
          aria-label="Hook"
          className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
          value={event}
          onChange={(e) => setEvent(e.target.value as HookEvent)}
        >
          {(["Writes", "Reads"] as const).map((group) => (
            <optgroup key={group} label={group === "Writes" ? "Write hooks" : "Read hooks"}>
              {HOOK_CHOICES.filter((choice) => choice.group === group).map((choice) => (
                <option key={choice.event} value={choice.event}>
                  {choice.label} ({choice.event})
                </option>
              ))}
            </optgroup>
          ))}
        </select>
        {chosen && <span className="mt-1 block text-xs text-muted-foreground">{chosen.hint}</span>}
      </label>

      {bindable && choices && (
        <label className="mt-4 block">
          <span className="mb-1 block text-xs font-medium">When the status becomes</span>
          {choices.kind === "machine" ? (
            <select
              aria-label="Status"
              className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
              value={status}
              onChange={(e) => setStatus(e.target.value)}
            >
              <option value="">Any update (no status)</option>
              {choices.states.map((state) => (
                <option key={state.value} value={state.value}>
                  {state.label}
                </option>
              ))}
            </select>
          ) : (
            <select
              aria-label="Status"
              disabled
              className="w-full rounded-md border border-border px-2 py-1.5 text-sm opacity-70"
              value="final"
            >
              <option value="final">Final</option>
            </select>
          )}
          <span className="mt-1 block text-xs text-muted-foreground">
            {choices.kind === "machine"
              ? `Runs when a ${entity} is moved to this status by its button. The button first saves the form in its current status; then, in another transaction, this workflow runs and, if it succeeds, the status moves on. If any step fails the move is undone and the record stays where it was.`
              : `${entity} has no status flow. By default it has two statuses, Draft and Final. Pressing the button saves the ${entity}; another transaction then runs this workflow, which moves the status to Final. A ${entity} with a status flow works the same way: the button saves the form in its current status, then the workflows attached to the next status run, and if they succeed the status moves on, in a separate transaction.`}
          </span>
        </label>
      )}

      <div className="mt-6 flex items-center justify-end gap-3">
        {problem && <span className="mr-auto text-xs text-muted-foreground">{problem}</span>}
        {onCancel && (
          <button
            type="button"
            onClick={onCancel}
            className="rounded-md border border-border px-4 py-2 text-sm font-medium"
          >
            Cancel
          </button>
        )}
        <button
          type="button"
          disabled={problem !== null}
          onClick={() =>
            onCreate({ name: name.trim(), entity, event, ...(boundStatus ? { status: boundStatus } : {}) })
          }
          className="rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground disabled:opacity-50"
        >
          Create workflow
        </button>
      </div>
    </section>
  );
}

import { AlertCircle, Code2, Trash2 } from "lucide-react";
import { useMemo, useState } from "react";
import {
  type Automation,
  emptyAutomation,
  serializeAutomation,
  validateAutomation,
} from "../../lib/automation/model";
import {
  emitHookWorkflow,
  emitSagaFlow,
  emitStateFlow,
  emptySagaFlow,
  HOOK_HINTS,
  HOOK_TYPES,
  type SagaFlow,
  type StateFlow,
  validateHookWorkflow,
  validateSagaFlow,
  validateStateFlow,
  type WorkflowHook,
} from "../../lib/eml/workflow-flow";
import { LadderCard, LadderRung } from "../automation/LadderCard";
import { SagaLadder } from "./SagaLadder";
import { emptyStateFlow, StateFlowCanvas } from "./StateFlowCanvas";

/**
 * One workflow.
 *
 * Lifted out of the workflows step so it can sit beside the rule editor. A rule
 * decides and a process acts on what it decided; keeping them on separate
 * screens made that look like two unrelated pieces of work.
 */

export type WorkflowKind = "hook" | "state" | "saga";

export interface EditableWorkflow {
  /** Stable across renames, so React keeps the row it is editing. */
  key: string;
  name: string;
  entity: string;
  kind: WorkflowKind;
  title?: string;
  hooks: WorkflowHook[];
  states: StateFlow;
  saga: SagaFlow;
  /**
   * Set for `hook` and `saga` workflows, which are edited in the automation
   * ladder — the same builder the generated application ships. A hook workflow
   * is a list of handlers on different lifecycle events, which is the
   * multi-trigger case the ladder gained; a saga is the ordered steps it always
   * had, started by a rule rather than by an event. `hooks` and `saga` above
   * are kept only so a workflow loaded before this existed still renders.
   */
  automation?: Automation;
}

export function pascalWorkflowName(value: string): string {
  const cleaned = value.replace(/[^A-Za-z0-9]+/g, " ").trim();
  if (!cleaned) return "Workflow";
  return cleaned
    .split(" ")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join("");
}

export function emptyWorkflow(kind: WorkflowKind, key: string, entity: string): EditableWorkflow {
  return {
    key,
    name: kind === "hook" ? "NewLifecycle" : kind === "saga" ? "NewProcess" : "NewStatus",
    entity,
    kind,
    hooks: [],
    states: emptyStateFlow(),
    saga: emptySagaFlow(),
    ...(kind === "hook" || kind === "saga" ? { automation: emptyAutomation(entity, kind) } : {}),
  };
}

/** The diagram a workflow serialises to, whichever kind it is. */
export function emitWorkflowDiagram(workflow: EditableWorkflow): string {
  if (workflow.kind === "hook") {
    // The ladder owns hook workflows now. `serializeAutomation` writes the
    // same `%%hook` directives `emitHookWorkflow` does, so the artifact the
    // generator reads is unchanged; the fallback covers a workflow loaded
    // before the ladder existed.
    if (workflow.automation) return serializeAutomation(workflow.automation);
    return emitHookWorkflow(workflow.entity || "Entity", workflow.hooks);
  }
  if (workflow.kind === "saga") {
    // Body only: the wizard sends name, entity, kind, trigger and operation as
    // fields, and language/composer.ts writes the %%workflow directive from
    // them. Emitting it here too would write the header twice.
    if (workflow.automation) return serializeAutomation(workflow.automation, { header: false });
    return emitSagaFlow(workflow.saga);
  }
  return emitStateFlow(workflow.states, workflow.entity || workflow.states.entity);
}

export function validateWorkflow(workflow: EditableWorkflow): string[] {
  if (workflow.kind === "hook") {
    if (workflow.automation) {
      return validateAutomation(workflow.automation).map((problem) => problem.message);
    }
    return validateHookWorkflow(workflow.entity, workflow.hooks);
  }
  if (workflow.kind === "saga") {
    if (workflow.automation) {
      return validateAutomation(workflow.automation).map((problem) => problem.message);
    }
    return validateSagaFlow(workflow.saga);
  }
  return validateStateFlow(workflow.states);
}

let hookCounter = 0;

export interface WorkflowEditorProps {
  workflow: EditableWorkflow;
  entityNames: string[];
  /** Rules the model declares, for a Decision step that names one. */
  ruleNames: string[];
  columnsFor: (entity: string) => string[];
  onChange: (patch: Partial<EditableWorkflow>) => void;
  /**
   * For a status machine: the workflows bound to each state, keyed by the
   * state's name in the machine's own spelling. Shown read-only, because what
   * runs on entering a state is chosen on the workflow, not here.
   */
  boundWorkflows?: Record<string, string[]>;
}

export function WorkflowEditor({
  workflow,
  entityNames,
  ruleNames,
  columnsFor,
  onChange,
  boundWorkflows,
}: WorkflowEditorProps) {
  const [showSource, setShowSource] = useState(false);
  const [selectedHookId, setSelectedHookId] = useState<string | null>(
    workflow.hooks[0]?.id ?? null
  );
  const problems = useMemo(() => validateWorkflow(workflow), [workflow]);
  const pascal = pascalWorkflowName;

  const selectedHook = workflow.hooks.find((h) => h.id === selectedHookId) ?? null;

  const addHook = () => {
    const hook = {
      id: `h${hookCounter++}`,
      type: "beforeCreate",
      handler: `handler${workflow.hooks.length + 1}`,
    };
    onChange({ hooks: [...workflow.hooks, hook] });
    setSelectedHookId(hook.id);
  };

  const patchHook = (id: string, patch: Partial<WorkflowHook>) =>
    onChange({ hooks: workflow.hooks.map((h) => (h.id === id ? { ...h, ...patch } : h)) });

  const removeHook = (id: string) => {
    onChange({ hooks: workflow.hooks.filter((h) => h.id !== id) });
    if (selectedHookId === id) setSelectedHookId(null);
  };

  return (
    <>
      <div className="mb-3 grid grid-cols-2 gap-3 lg:grid-cols-3">
        <label className="block">
          <span className="mb-1 block text-xs font-medium">Name</span>
          <input
            className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
            value={workflow.title ?? workflow.name}
            onChange={(event) =>
              onChange({
                title: event.target.value,
                name: pascal(event.target.value),
              })
            }
          />
        </label>

        <label className="block">
          <span className="mb-1 block text-xs font-medium">Entity</span>
          <select
            className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
            value={workflow.entity}
            onChange={(event) => onChange({ entity: event.target.value })}
          >
            <option value="">Choose…</option>
            {entityNames.map((name) => (
              <option key={name} value={name}>
                {name}
              </option>
            ))}
          </select>
        </label>

        <div>
          <span className="mb-1 block text-xs font-medium">Kind</span>
          <p className="rounded-md border border-border bg-muted/40 px-2 py-1.5 text-sm">
            {workflow.kind === "hook"
              ? "Lifecycle handlers"
              : workflow.kind === "saga"
                ? "Multi-step process"
                : "Status state machine"}
          </p>
        </div>
      </div>

      {workflow.kind === "hook" ? (
        <div className="flex min-h-[460px] gap-4">
          {/* Jira-style ladder */}
          <div className="flex flex-1 flex-col items-center overflow-y-auto rounded-xl border border-border bg-muted/30 px-5 py-5">
            <div className="w-full max-w-[520px]">
              {workflow.hooks.length === 0 && (
                <p className="rounded-md border border-dashed border-border bg-card px-3 py-6 text-center text-xs text-muted-foreground">
                  No steps yet. Add one to run a handler on this entity&apos;s lifecycle.
                </p>
              )}

              {workflow.hooks.map((hook, index) => (
                <div key={hook.id} className="flex flex-col items-center">
                  {index > 0 && <LadderRung onAdd={addHook} />}
                  <LadderCard
                    kind="when"
                    glyph="⚡"
                    ordinal={`· step ${index + 1}`}
                    title={`${hook.type} → ${hook.handler}${hook.field ? ` · ${hook.field}` : ""}`}
                    selected={selectedHookId === hook.id}
                    onSelect={() => setSelectedHookId(hook.id)}
                    onRemove={() => removeHook(hook.id)}
                  />
                </div>
              ))}

              <div className="flex flex-col items-center">
                <LadderRung onAdd={addHook} />
              </div>
            </div>
          </div>

          {/* Inspector */}
          <div className="flex w-60 shrink-0 flex-col gap-3 rounded-xl border border-border bg-card p-4">
            {selectedHook ? (
              <>
                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                  Step
                </p>

                <label className="block">
                  <span className="mb-1 block text-xs font-medium">When</span>
                  <select
                    className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
                    value={selectedHook.type}
                    onChange={(event) => patchHook(selectedHook.id, { type: event.target.value })}
                  >
                    {HOOK_TYPES.map((type) => (
                      <option key={type} value={type}>
                        {type}
                      </option>
                    ))}
                  </select>
                </label>

                <label className="block">
                  <span className="mb-1 block text-xs font-medium">Handler</span>
                  <input
                    className="w-full rounded-md border border-border px-2 py-1.5 font-mono text-sm"
                    value={selectedHook.handler}
                    onChange={(event) =>
                      patchHook(selectedHook.id, { handler: event.target.value })
                    }
                    placeholder="hashPassword"
                  />
                  <span className="mt-1 block text-[11px] leading-snug text-muted-foreground">
                    {HOOK_HINTS[selectedHook.type] ?? ""}
                  </span>
                </label>

                <label className="block">
                  <span className="mb-1 block text-xs font-medium">Field (optional)</span>
                  <input
                    className="w-full rounded-md border border-border px-2 py-1.5 font-mono text-sm"
                    value={selectedHook.field ?? ""}
                    onChange={(event) =>
                      patchHook(selectedHook.id, { field: event.target.value || undefined })
                    }
                    placeholder="password"
                  />
                </label>

                <button
                  type="button"
                  className="mt-auto flex items-center gap-1.5 rounded-md border border-destructive/40 px-2 py-1.5 text-xs font-medium text-destructive hover:bg-destructive/10"
                  onClick={() => removeHook(selectedHook.id)}
                >
                  <Trash2 className="h-3 w-3" />
                  Remove step
                </button>
              </>
            ) : (
              <p className="text-center text-xs text-muted-foreground">
                {workflow.hooks.length > 0
                  ? "Select a step to edit it"
                  : "Add a step to get started"}
              </p>
            )}
          </div>
        </div>
      ) : workflow.kind === "saga" ? (
        <SagaLadder
          key={workflow.key}
          flow={workflow.saga}
          entityNames={entityNames}
          entityColumns={columnsFor(workflow.entity)}
          ruleNames={ruleNames}
          columnsFor={columnsFor}
          onChange={(saga) => onChange({ saga })}
        />
      ) : (
        <div className="h-[460px]">
          <StateFlowCanvas flow={workflow.states} onChange={(states) => onChange({ states })} />
        </div>
      )}

      {workflow.kind === "state" && boundWorkflows && Object.keys(boundWorkflows).length > 0 && (
        <section
          aria-label="Runs when a state is entered"
          className="mt-3 rounded-lg border border-border bg-muted/30 px-3 py-2 text-xs"
        >
          <h4 className="mb-1 font-semibold">Runs when a state is entered</h4>
          <ul className="space-y-0.5">
            {Object.entries(boundWorkflows).map(([state, names]) => (
              <li key={state}>
                <span className="font-medium">{state.replace(/_/g, " ")}</span>
                <span className="text-muted-foreground"> — {names.join(", ")}</span>
              </li>
            ))}
          </ul>
          <p className="mt-1 text-muted-foreground">
            The button saves the form, then these run in another transaction. The status moves only
            if they all succeed.
          </p>
        </section>
      )}

      {problems.length > 0 && (
        <ul className="mt-3 space-y-1 rounded-lg border border-amber-300 bg-amber-50 px-3 py-2 text-xs text-amber-900">
          {problems.map((problem) => (
            <li key={problem} className="flex items-start gap-1.5">
              <AlertCircle className="mt-0.5 h-3 w-3 shrink-0" />
              {problem}
            </li>
          ))}
        </ul>
      )}

      <button
        type="button"
        onClick={() => setShowSource((current) => !current)}
        className="mt-3 flex items-center gap-1.5 rounded-md border border-border px-3 py-1.5 text-sm font-medium"
      >
        <Code2 className="h-3.5 w-3.5" />
        {showSource ? "Hide" : "Show"} EML
      </button>

      {showSource && (
        <pre className="mt-2 max-h-56 overflow-auto rounded-lg border border-border bg-muted/40 p-3 font-mono text-[11px] leading-relaxed">
          {`%%workflow ${pascal(workflow.title ?? workflow.name)} entity: ${
            workflow.entity || "<entity>"
          } kind: ${workflow.kind}${
            workflow.kind === "saga"
              ? `${workflow.saga.trigger === "rule" ? " trigger: rule" : ""}${
                  workflow.saga.operation !== "CREATE"
                    ? ` operation: ${workflow.saga.operation}`
                    : ""
                }`
              : ""
          }${
            workflow.kind !== "state" && workflow.automation?.onStatus
              ? ` status: ${workflow.automation.onStatus}`
              : ""
          }\n${
            workflow.kind === "hook"
              ? emitHookWorkflow(workflow.entity || "Entity", workflow.hooks)
              : workflow.kind === "saga"
                ? emitSagaFlow(workflow.saga)
                : emitStateFlow(workflow.states, workflow.entity || workflow.states.entity)
          }`}
        </pre>
      )}
    </>
  );
}

import { AlertCircle, CheckCircle2, Play } from "lucide-react";
import { useMemo, useState } from "react";
import type { DryRunResult, RuleDryRun } from "../../lib/eml/dry-run-types";
import { sampleRecord } from "../../lib/eml/rule-templates";

interface RuleTryItProps {
  entity: string;
  /** How the rule is run on the server. */
  dryRun: RuleDryRun;
  entityFields: string[];
  entityEnums: Record<string, string[]>;
  /** Each field's JSON type, so the sample starts with a value of the right kind. */
  fieldTypes?: Record<string, "string" | "number" | "boolean">;
  /** The graph as it stands now, saved or not. */
  getGraph: () => string;
  /** When set, the section is exactly this tall and the textarea fills the space. */
  height?: number;
}

const KIND_STYLE: Record<string, string> = {
  blocks: "border-red-300 bg-red-50 text-red-900",
  workflow: "border-blue-300 bg-blue-50 text-blue-900",
  changes: "border-blue-300 bg-blue-50 text-blue-900",
  notifies: "border-amber-300 bg-amber-50 text-amber-900",
  cascade: "border-blue-300 bg-blue-50 text-blue-900",
  nothing: "border-emerald-300 bg-emerald-50 text-emerald-900",
  problem: "border-amber-400 bg-amber-50 text-amber-900",
};

/**
 * Try the rule on a sample record before saving it.
 *
 * The answer is a sentence about what would happen to the write, not raw JSON:
 * a rule that "does nothing" looks the same whether it did not match or never
 * said what to do, and only one of those is the author's mistake.
 */
export function RuleTryIt({
  entity,
  dryRun,
  entityFields,
  entityEnums,
  fieldTypes,
  getGraph,
  height,
}: RuleTryItProps) {
  const initial = useMemo(
    () => JSON.stringify(sampleRecord(entityFields, entityEnums, fieldTypes), null, 2),
    [entityFields, entityEnums, fieldTypes]
  );
  const [text, setText] = useState<string | null>(null);
  const [running, setRunning] = useState(false);
  const [result, setResult] = useState<DryRunResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const shown = text ?? initial;

  const run = async () => {
    setError(null);
    setResult(null);
    let record: unknown;
    try {
      record = JSON.parse(shown);
    } catch {
      setError("The sample record is not valid JSON.");
      return;
    }
    setRunning(true);
    try {
      const data = await dryRun({
        graph: getGraph(),
        record: record as Record<string, unknown>,
        entity,
      });
      setResult(data);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Could not run the rule.");
    } finally {
      setRunning(false);
    }
  };

  return (
    <section
      aria-label="Try the rule"
      style={height ? { height } : undefined}
      className={`mt-3 rounded-lg border border-border p-3${height ? " flex flex-col overflow-hidden" : ""}`}
    >
      <h3 className="text-sm font-semibold">Try it before you save</h3>
      <p className="mt-0.5 text-xs text-muted-foreground">
        Edit the sample record, then run the rule to see what it would do to the write. Nothing is
        saved.
      </p>
      <div className={`mt-2 grid gap-3 lg:grid-cols-2${height ? " flex-1 min-h-0" : ""}`}>
        <label className={height ? "flex min-h-0 flex-col" : "block"}>
          <span className="mb-1 block text-xs font-medium">Sample {entity || "record"}</span>
          <textarea
            className={`w-full rounded-md border border-border p-2 font-mono text-xs${height ? " min-h-0 flex-1 resize-none" : " h-40"}`}
            value={shown}
            onChange={(event) => setText(event.target.value)}
            spellCheck={false}
          />
        </label>
        <div aria-live="polite" className={height ? "min-h-0 overflow-y-auto" : ""}>
          <span className="mb-1 block text-xs font-medium">What would happen</span>
          {error && (
            <p className="flex items-start gap-1.5 rounded-md border border-amber-300 bg-amber-50 p-2 text-xs text-amber-900">
              <AlertCircle className="mt-0.5 h-3.5 w-3.5 shrink-0" /> {error}
            </p>
          )}
          {result && !result.ok && (
            <ul className="space-y-1">
              {result.problems.map((problem) => (
                <li
                  key={problem}
                  className="flex items-start gap-1.5 rounded-md border border-amber-300 bg-amber-50 p-2 text-xs text-amber-900"
                >
                  <AlertCircle className="mt-0.5 h-3.5 w-3.5 shrink-0" /> {problem}
                </li>
              ))}
            </ul>
          )}
          {result?.ok && (
            <>
              <ul className="space-y-1">
                {result.outcomes.map((outcome) => (
                  <li
                    key={`${outcome.kind}-${outcome.text}`}
                    className={`flex items-start gap-1.5 rounded-md border p-2 text-xs ${KIND_STYLE[outcome.kind]}`}
                  >
                    {outcome.kind === "problem" ? (
                      <AlertCircle className="mt-0.5 h-3.5 w-3.5 shrink-0" />
                    ) : (
                      <CheckCircle2 className="mt-0.5 h-3.5 w-3.5 shrink-0" />
                    )}
                    {outcome.text}
                  </li>
                ))}
              </ul>
              <details className="mt-2 text-xs">
                <summary className="cursor-pointer font-medium">How it got there</summary>
                <ol className="mt-1 list-decimal space-y-1 pl-5">
                  {result.trace.map((step, index) => (
                    // a trace is ordered and static
                    <li key={index}>
                      <span className="font-medium">{step.node || "node"}</span>
                      <code className="ml-1 break-all text-[11px] text-muted-foreground">
                        {JSON.stringify(step.output)}
                      </code>
                    </li>
                  ))}
                </ol>
              </details>
            </>
          )}
          {!error && !result && (
            <p className="text-xs text-muted-foreground">Run the rule to see the answer here.</p>
          )}
        </div>
      </div>
      <button
        type="button"
        onClick={run}
        disabled={running || !entity || entityFields.length === 0}
        className="mt-2 flex items-center gap-1.5 rounded-md border border-border px-3 py-1.5 text-sm font-medium disabled:opacity-50"
      >
        <Play className="h-3.5 w-3.5" />
        {running ? "Running…" : "Run the rule"}
      </button>
    </section>
  );
}

/**
 * An EML saga, drawn as the automation ladder.
 *
 * A saga is already an ordered list of steps — the `%%step` directives run in
 * the order the document gives them — so it gets the same top-to-bottom card
 * ladder as an automation rather than a canvas whose layout carries no meaning.
 *
 * What it does not share is the property vocabulary. A saga step's fields come
 * from `SAGA_STEP_FIELDS` and are what the EML document declares (`rule`,
 * `publish`, `as`, `targetSource` …), not the automation model's. Mapping one
 * onto the other would quietly drop the fields that do not correspond, so this
 * drives its own inspector off the EML field list and shares only the visual
 * language.
 */

import { useState } from "react";
import {
  FORMULA_OPERATIONS,
  SAGA_FIELD_LABELS,
  SAGA_STEP_FIELDS,
  SAGA_STEP_HINTS,
  SAGA_STEP_TYPES,
  type SagaFlow,
  type SagaStep,
  type SagaStepType,
} from "../../lib/eml/workflow-flow";
import { cn } from "../../lib/utils";
import { LadderCard, LadderRung } from "../automation/LadderCard";

/** The same glyphs the automation ladder uses, so a step reads alike in both. */
const STEP_GLYPHS: Record<SagaStepType, string> = {
  Decision: "▤",
  Formula: "ƒ",
  CreateEntity: "✚",
  UpdateEntity: "✎",
  DeleteEntity: "✕",
  REST: "↗",
};

const STEP_LABELS: Record<SagaStepType, string> = {
  Decision: "Look up a rule table",
  Formula: "Work out a value",
  CreateEntity: "Create a record",
  UpdateEntity: "Update a column",
  DeleteEntity: "Delete a record",
  REST: "Call a web service",
};

/** Fields that read better as a picker than as free text. */
const CHOICES: Record<string, readonly string[]> = {
  operation: FORMULA_OPERATIONS,
  method: ["POST", "PUT", "PATCH", "GET", "DELETE"],
  hard: ["false", "true"],
};

/** Fields whose value is JSON, so they get a textarea rather than one line. */
const MULTILINE = new Set(["decisionTable", "fields", "bodyTemplate", "publish"]);

const inputClass =
  "w-full rounded-lg border border-input bg-card px-3 py-2 text-sm focus-visible:outline-none focus-visible:border-primary focus-visible:ring-[3px] focus-visible:ring-primary/10";

let counter = 0;
function newStepId(): string {
  counter += 1;
  return `s${counter.toString(36)}${Date.now().toString(36)}`;
}

/** How a step reads on its card. Falls back to the type when nothing is set. */
function describeSagaStep(step: SagaStep): string {
  const p = step.props;
  switch (step.type) {
    case "Decision":
      return `Look up ${p.rule || "a rule"}`;
    case "Formula":
      return `${p.operation || "set"} ${p.target || "a variable"}${
        p.value ? ` to ${p.value}` : p.source ? ` from ${p.source}` : ""
      }`;
    case "CreateEntity":
      return `Create ${p.entity || "a record"}${p.as ? ` → ${p.as}` : ""}`;
    case "UpdateEntity":
      return `Set ${p.entity && p.field ? `${p.entity}.${p.field}` : p.field || "a column"}${
        p.value ? ` to ${p.value}` : ""
      }`;
    case "DeleteEntity":
      return `Delete ${p.entity || "a record"}`;
    case "REST":
      return `${p.method || "POST"} to ${p.url || "a URL"}`;
    default:
      return STEP_LABELS[step.type] ?? step.type;
  }
}

export interface SagaLadderProps {
  flow: SagaFlow;
  /** Entity names from the ERD, for the entity pickers. */
  entityNames: string[];
  /** Columns of the entity this workflow is triggered by. */
  entityColumns?: string[];
  /** Rules the model declares, for a Decision step that names one. */
  ruleNames?: string[];
  /** Columns per entity, so a step acting on another one still gets pickers. */
  columnsFor?: (entity: string) => string[];
  onChange: (flow: SagaFlow) => void;
}

export function SagaLadder({
  flow,
  entityNames,
  entityColumns = [],
  ruleNames = [],
  columnsFor,
  onChange,
}: SagaLadderProps) {
  const [selectedId, setSelectedId] = useState<string | null>(flow.steps[0]?.id ?? null);
  const [addingAt, setAddingAt] = useState<number | null>(null);

  const selected = flow.steps.find((s) => s.id === selectedId);
  const selectedIndex = flow.steps.findIndex((s) => s.id === selectedId);

  const setSteps = (steps: SagaStep[]) => onChange({ ...flow, steps });

  const addStep = (type: SagaStepType, at: number) => {
    const step: SagaStep = { id: newStepId(), type, label: STEP_LABELS[type], props: {} };
    const steps = [...flow.steps];
    steps.splice(at, 0, step);
    setSteps(steps);
    setSelectedId(step.id);
    setAddingAt(null);
  };

  const updateStep = (next: SagaStep) =>
    setSteps(flow.steps.map((s) => (s.id === next.id ? next : s)));

  const removeStep = (id: string) => {
    setSteps(flow.steps.filter((s) => s.id !== id));
    if (selectedId === id) setSelectedId(null);
  };

  const moveStep = (index: number, delta: number) => {
    const to = index + delta;
    if (to < 0 || to >= flow.steps.length) return;
    const steps = [...flow.steps];
    const [moved] = steps.splice(index, 1);
    if (moved) steps.splice(to, 0, moved);
    setSteps(steps);
  };

  const columnsForEntity = (entity: string) =>
    entity && columnsFor ? columnsFor(entity) : entityColumns;

  return (
    <div className="flex min-h-[460px] gap-4">
      {/* the ladder */}
      <div className="flex flex-1 flex-col items-center overflow-y-auto rounded-xl border border-border bg-muted/30 px-5 py-5">
        <div className="w-full max-w-[520px]">
          {flow.steps.length === 0 ? (
            <p className="mb-3 rounded-md border border-dashed border-border bg-card px-3 py-6 text-center text-xs text-muted-foreground">
              No steps yet. Add the first thing this saga should do.
            </p>
          ) : null}

          {flow.steps.map((step, i) => (
            <div key={step.id} className="flex flex-col items-center">
              {i > 0 ? (
                <LadderRung
                  onAdd={() => setAddingAt(addingAt === i ? null : i)}
                  active={addingAt === i}
                />
              ) : null}

              {addingAt === i ? (
                <AddMenu onPick={(type) => addStep(type, i)} onCancel={() => setAddingAt(null)} />
              ) : null}

              <LadderCard
                kind="action"
                glyph={STEP_GLYPHS[step.type]}
                ordinal={`· step ${i + 1}`}
                title={describeSagaStep(step)}
                selected={selectedId === step.id}
                onSelect={() => setSelectedId(step.id)}
                onRemove={() => removeStep(step.id)}
              />
            </div>
          ))}

          <div className="flex flex-col items-center">
            {flow.steps.length > 0 ? (
              <LadderRung
                onAdd={() => setAddingAt(addingAt === flow.steps.length ? null : flow.steps.length)}
                active={addingAt === flow.steps.length}
              />
            ) : null}

            {addingAt === flow.steps.length ? (
              <AddMenu
                onPick={(type) => addStep(type, flow.steps.length)}
                onCancel={() => setAddingAt(null)}
              />
            ) : (
              <button
                type="button"
                onClick={() => setAddingAt(flow.steps.length)}
                className="w-full rounded-xl border border-dashed border-border bg-card py-2.5 text-sm font-semibold text-muted-foreground hover:border-primary/50 hover:text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2"
              >
                ＋ <span className="text-primary">Add a step</span>
              </button>
            )}
          </div>
        </div>
      </div>

      {/* the inspector */}
      <aside className="w-[340px] shrink-0 overflow-y-auto rounded-xl border border-border bg-card p-4">
        {selected ? (
          <>
            <header className="mb-3 flex items-center gap-2.5">
              <span
                aria-hidden="true"
                className="grid h-[28px] w-[28px] shrink-0 place-items-center rounded-lg border border-primary/30 bg-primary/10 text-sm text-primary"
              >
                {STEP_GLYPHS[selected.type]}
              </span>
              <div>
                <span className="block text-[10px] font-bold uppercase tracking-[0.1em] text-primary">
                  Step {selectedIndex + 1}
                </span>
                <h3 className="text-[15px] font-bold">{STEP_LABELS[selected.type]}</h3>
              </div>
            </header>

            <p className="mb-4 text-xs leading-snug text-muted-foreground">
              {SAGA_STEP_HINTS[selected.type]}
            </p>

            <div className="mb-4 flex gap-2">
              <button
                type="button"
                onClick={() => moveStep(selectedIndex, -1)}
                disabled={selectedIndex <= 0}
                className="flex-1 rounded-lg border border-border py-1.5 text-xs font-semibold disabled:opacity-40 hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
              >
                ↑ Move up
              </button>
              <button
                type="button"
                onClick={() => moveStep(selectedIndex, 1)}
                disabled={selectedIndex < 0 || selectedIndex >= flow.steps.length - 1}
                className="flex-1 rounded-lg border border-border py-1.5 text-xs font-semibold disabled:opacity-40 hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
              >
                ↓ Move down
              </button>
            </div>

            {(SAGA_STEP_FIELDS[selected.type] ?? []).map((field) => (
              <SagaField
                key={field}
                field={field}
                value={selected.props[field] ?? ""}
                entityNames={entityNames}
                columns={columnsForEntity(selected.props.entity ?? "")}
                ruleNames={ruleNames}
                onChange={(value) =>
                  updateStep({ ...selected, props: { ...selected.props, [field]: value } })
                }
              />
            ))}
          </>
        ) : (
          <p className="grid h-full place-items-center text-center text-sm text-muted-foreground">
            Pick a step on the left to set it up.
          </p>
        )}
      </aside>
    </div>
  );
}

function SagaField({
  field,
  value,
  entityNames,
  columns,
  ruleNames,
  onChange,
}: {
  field: string;
  value: string;
  entityNames: string[];
  columns: string[];
  ruleNames: string[];
  onChange: (value: string) => void;
}) {
  const label = SAGA_FIELD_LABELS[field] ?? field;

  const options =
    field === "entity"
      ? entityNames
      : field === "rule"
        ? ruleNames
        : field === "field" || field === "targetField"
          ? columns
          : CHOICES[field];

  return (
    // the select/input is nested in the label, behind a conditional.
    <label className="mb-3.5 block">
      <span className="mb-1.5 block text-[11px] font-semibold uppercase tracking-[0.06em] text-muted-foreground">
        {label}
      </span>

      {options ? (
        <select className={inputClass} value={value} onChange={(e) => onChange(e.target.value)}>
          <option value="">Choose…</option>
          {options.map((option) => (
            <option key={option} value={option}>
              {option}
            </option>
          ))}
        </select>
      ) : MULTILINE.has(field) ? (
        <textarea
          className={cn(inputClass, "min-h-[76px] font-mono text-xs")}
          value={value}
          onChange={(e) => onChange(e.target.value)}
        />
      ) : (
        <input className={inputClass} value={value} onChange={(e) => onChange(e.target.value)} />
      )}
    </label>
  );
}

function AddMenu({
  onPick,
  onCancel,
}: {
  onPick: (type: SagaStepType) => void;
  onCancel: () => void;
}) {
  return (
    <div
      className="mb-2 w-full rounded-xl border border-primary/40 bg-card p-3 shadow-lg"
      role="menu"
      aria-label="Add a step"
    >
      <div className="mb-2 flex items-center">
        <span className="text-[10px] font-bold uppercase tracking-[0.1em] text-muted-foreground">
          Add here
        </span>
        <button
          type="button"
          onClick={onCancel}
          className="ml-auto rounded px-1.5 text-xs text-muted-foreground hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          ✕
        </button>
      </div>

      <div className="grid grid-cols-2 gap-2">
        {SAGA_STEP_TYPES.map((type) => (
          <button
            key={type}
            type="button"
            role="menuitem"
            onClick={() => onPick(type)}
            className="flex items-start gap-2.5 rounded-lg border border-border p-2.5 text-left hover:border-primary/40 hover:bg-primary/5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
          >
            <span
              aria-hidden="true"
              className="grid h-[26px] w-[26px] shrink-0 place-items-center rounded-md border border-primary/30 bg-primary/10 text-xs text-primary"
            >
              {STEP_GLYPHS[type]}
            </span>
            <span className="min-w-0">
              <strong className="block text-[12.5px]">{STEP_LABELS[type]}</strong>
              <span className="text-[11.5px] leading-snug text-muted-foreground">
                {SAGA_STEP_HINTS[type]}
              </span>
            </span>
          </button>
        ))}
      </div>
    </div>
  );
}

import { ArrowDown, GripVertical, Plus, Trash2 } from "lucide-react";
import {
  FORMULA_OPERATIONS,
  SAGA_FIELD_LABELS,
  SAGA_STEP_FIELDS,
  SAGA_STEP_HINTS,
  SAGA_STEP_TYPES,
  type SagaFlow,
  type SagaStep,
  type SagaStepType,
} from "../../lib/eml/workflow-flow";

/**
 * The step list of a saga workflow.
 *
 * Steps are an ordered list rather than a free canvas because the generated
 * executor runs a linear chain: letting someone draw a branch here would
 * promise something the runtime does not do. The flowchart and its node ids are
 * emitted from this order, so the author never has to hold an id in their head.
 */
export interface SagaStepEditorProps {
  flow: SagaFlow;
  /** Entity names from the ERD, for the entity pickers. */
  entityNames: string[];
  onChange: (flow: SagaFlow) => void;
}

let stepCounter = 0;
const nextId = () => `st${(stepCounter++).toString(36)}${Date.now().toString(36)}`;

/** Sensible starting properties, so a new step is never blank and invalid. */
function defaultsFor(type: SagaStepType, entityNames: string[]): Record<string, string> {
  if (type === "Formula") return { operation: "set", target: "", value: "" };
  if (type === "CreateEntity") return { entity: entityNames[0] ?? "", fields: "{}" };
  if (type === "UpdateEntity") return { field: "", value: "" };
  if (type === "DeleteEntity") return { hard: "false" };
  return { method: "POST", url: "" };
}

/** Which property fields this step actually shows, given its own values. */
function visibleFields(step: SagaStep): string[] {
  const fields = SAGA_STEP_FIELDS[step.type] ?? [];
  if (step.type !== "Formula") return fields;

  // The arithmetic operations read source + operand; `set` reads a literal and
  // `copy` reads a variable. Showing all five at once invited filling in the
  // three that the chosen operation ignores.
  const operation = (step.props.operation ?? "set").trim();
  if (operation === "set") return ["target", "operation", "value"];
  if (operation === "copy") return ["target", "operation", "source"];
  return ["target", "operation", "source", "operand"];
}

export function SagaStepEditor({ flow, entityNames, onChange }: SagaStepEditorProps) {
  const patchStep = (index: number, patch: Partial<SagaStep>) => {
    onChange({
      ...flow,
      steps: flow.steps.map((step, position) =>
        position === index ? { ...step, ...patch } : step
      ),
    });
  };

  const patchProp = (index: number, key: string, value: string) => {
    const step = flow.steps[index];
    if (!step) return;
    patchStep(index, { props: { ...step.props, [key]: value } });
  };

  const addStep = (type: SagaStepType) => {
    onChange({
      ...flow,
      steps: [
        ...flow.steps,
        { id: nextId(), type, label: type, props: defaultsFor(type, entityNames) },
      ],
    });
  };

  const move = (index: number, delta: number) => {
    const target = index + delta;
    if (target < 0 || target >= flow.steps.length) return;
    const steps = [...flow.steps];
    const [moved] = steps.splice(index, 1);
    steps.splice(target, 0, moved!);
    onChange({ ...flow, steps });
  };

  /** Variables an earlier step publishes — what a later one may read. */
  const publishedBefore = (index: number): string[] => {
    const names: string[] = [];
    for (const step of flow.steps.slice(0, index)) {
      if (step.type === "Formula" && step.props.target?.trim()) {
        names.push(step.props.target.trim());
      }
      if (step.type === "CreateEntity") {
        const bound =
          step.props.as?.trim() ||
          (step.props.entity?.trim() ? `${step.props.entity.trim().replace(/^bus_/, "")}Id` : "");
        if (bound) names.push(bound);
      }
    }
    return names;
  };

  return (
    <div className="rounded-lg border border-border bg-card p-3">
      <div className="mb-3 grid grid-cols-2 gap-3">
        <label className="block">
          <span className="mb-1 block text-xs font-medium">Runs when</span>
          <select
            className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
            value={flow.trigger}
            onChange={(event) =>
              onChange({ ...flow, trigger: event.target.value as SagaFlow["trigger"] })
            }
          >
            <option value="rule">Only when a business rule triggers it</option>
            <option value="automatic">On every matching write</option>
          </select>
          <span className="mt-1 block text-[11px] leading-snug text-muted-foreground">
            {flow.trigger === "rule"
              ? "The rule's condition decides. Use this when the process should not run on every save."
              : "Runs on every write of the chosen operation, whatever the record says."}
          </span>
        </label>

        <label className="block">
          <span className="mb-1 block text-xs font-medium">On</span>
          <select
            className="w-full rounded-md border border-border px-2 py-1.5 text-sm disabled:opacity-50"
            value={flow.operation}
            disabled={flow.trigger === "rule"}
            onChange={(event) =>
              onChange({ ...flow, operation: event.target.value as SagaFlow["operation"] })
            }
          >
            {["CREATE", "UPDATE", "DELETE", "ALL"].map((operation) => (
              <option key={operation} value={operation}>
                {operation}
              </option>
            ))}
          </select>
          <span className="mt-1 block text-[11px] leading-snug text-muted-foreground">
            {flow.trigger === "rule"
              ? "Not used — a rule-triggered workflow is resolved by name."
              : "Which write starts the process."}
          </span>
        </label>
      </div>

      <div className="mb-2 flex flex-wrap items-center gap-1">
        <span className="mr-1 text-xs font-medium text-muted-foreground">Add step:</span>
        {SAGA_STEP_TYPES.map((type) => (
          <button
            key={type}
            type="button"
            onClick={() => addStep(type)}
            title={SAGA_STEP_HINTS[type]}
            className="flex items-center gap-1 rounded-md border border-border px-2 py-1 text-xs font-medium hover:bg-muted"
          >
            <Plus className="h-3 w-3" />
            {type}
          </button>
        ))}
      </div>

      <div className="space-y-2">
        {flow.steps.map((step, index) => {
          const available = publishedBefore(index);
          return (
            <div key={step.id} className="rounded-md border border-border p-2">
              <div className="mb-2 flex items-center gap-2">
                <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded bg-muted text-[11px] font-semibold">
                  {index + 1}
                </span>
                <select
                  className="rounded-md border border-border px-2 py-1 text-xs font-medium"
                  value={step.type}
                  onChange={(event) => {
                    const type = event.target.value as SagaStepType;
                    patchStep(index, { type, props: defaultsFor(type, entityNames) });
                  }}
                >
                  {SAGA_STEP_TYPES.map((type) => (
                    <option key={type} value={type}>
                      {type}
                    </option>
                  ))}
                </select>
                <input
                  className="min-w-0 flex-1 rounded-md border border-border px-2 py-1 text-xs"
                  value={step.label}
                  placeholder="What this step does"
                  onChange={(event) => patchStep(index, { label: event.target.value })}
                />
                <button
                  type="button"
                  aria-label={`Move step ${index + 1} up`}
                  disabled={index === 0}
                  onClick={() => move(index, -1)}
                  className="disabled:opacity-30"
                >
                  <GripVertical className="h-3.5 w-3.5 rotate-90 text-muted-foreground" />
                </button>
                <button
                  type="button"
                  aria-label={`Move step ${index + 1} down`}
                  disabled={index === flow.steps.length - 1}
                  onClick={() => move(index, 1)}
                  className="disabled:opacity-30"
                >
                  <ArrowDown className="h-3.5 w-3.5 text-muted-foreground" />
                </button>
                <button
                  type="button"
                  aria-label={`Delete step ${index + 1}`}
                  onClick={() =>
                    onChange({
                      ...flow,
                      steps: flow.steps.filter((_step, position) => position !== index),
                    })
                  }
                >
                  <Trash2 className="h-3.5 w-3.5 text-muted-foreground hover:text-destructive" />
                </button>
              </div>

              <p className="mb-2 text-[11px] leading-snug text-muted-foreground">
                {SAGA_STEP_HINTS[step.type]}
              </p>

              <div className="grid grid-cols-1 gap-2 md:grid-cols-3">
                {visibleFields(step).map((key) => (
                  // the control is nested in the label, behind a per-field conditional.
                  <label key={key} className="block">
                    <span className="mb-1 block text-[11px] font-medium">
                      {SAGA_FIELD_LABELS[key] ?? key}
                    </span>

                    {key === "entity" ? (
                      <select
                        className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
                        value={step.props.entity ?? ""}
                        onChange={(event) => patchProp(index, "entity", event.target.value)}
                      >
                        <option value="">
                          {step.type === "CreateEntity" ? "Choose…" : "This record"}
                        </option>
                        {entityNames.map((name) => (
                          <option key={name} value={name}>
                            {name}
                          </option>
                        ))}
                      </select>
                    ) : key === "operation" ? (
                      <select
                        className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
                        value={step.props.operation ?? "set"}
                        onChange={(event) => patchProp(index, "operation", event.target.value)}
                      >
                        {FORMULA_OPERATIONS.map((operation) => (
                          <option key={operation} value={operation}>
                            {operation}
                          </option>
                        ))}
                      </select>
                    ) : key === "hard" ? (
                      <select
                        className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
                        value={step.props.hard ?? "false"}
                        onChange={(event) => patchProp(index, "hard", event.target.value)}
                      >
                        <option value="false">Soft — stamp deleted_at</option>
                        <option value="true">Hard — remove the row</option>
                      </select>
                    ) : key === "method" ? (
                      <select
                        className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
                        value={step.props.method ?? "POST"}
                        onChange={(event) => patchProp(index, "method", event.target.value)}
                      >
                        {["POST", "PUT", "PATCH", "GET"].map((method) => (
                          <option key={method} value={method}>
                            {method}
                          </option>
                        ))}
                      </select>
                    ) : key === "targetSource" || key === "source" ? (
                      <>
                        <input
                          list={`${step.id}-${key}-vars`}
                          className="w-full rounded-md border border-border px-2 py-1.5 font-mono text-sm"
                          value={step.props[key] ?? ""}
                          placeholder={available[0] ?? "variable or column"}
                          onChange={(event) => patchProp(index, key, event.target.value)}
                        />
                        <datalist id={`${step.id}-${key}-vars`}>
                          {available.map((name) => (
                            <option key={name} value={name} />
                          ))}
                        </datalist>
                      </>
                    ) : key === "fields" ? (
                      <textarea
                        className="h-16 w-full resize-none rounded-md border border-border px-2 py-1.5 font-mono text-[11px]"
                        value={step.props.fields ?? "{}"}
                        placeholder={'{"status":"open"}'}
                        onChange={(event) => patchProp(index, "fields", event.target.value)}
                      />
                    ) : (
                      <input
                        className="w-full rounded-md border border-border px-2 py-1.5 font-mono text-sm"
                        value={step.props[key] ?? ""}
                        onChange={(event) => patchProp(index, key, event.target.value)}
                      />
                    )}
                  </label>
                ))}
              </div>

              {step.type === "CreateEntity" && (
                <p className="mt-1.5 text-[11px] leading-snug text-muted-foreground">
                  Later steps reach this row through the variable its id is bound to
                  {step.props.as?.trim() ? (
                    <>
                      {" "}
                      — <code className="font-mono">{step.props.as.trim()}</code>.
                    </>
                  ) : (
                    ". Name one, or it defaults to the entity name plus Id."
                  )}
                </p>
              )}
            </div>
          );
        })}

        {!flow.steps.length && (
          <p className="rounded-md border border-dashed border-border px-2 py-6 text-center text-xs text-muted-foreground">
            No steps yet. Add one to build the process.
          </p>
        )}
      </div>
    </div>
  );
}

"use client";

/**
 * The decision-flow canvas.
 *
 * Drag steps around, join them up, label the branches. What you draw is exactly
 * what the model stores — the canvas edits the same node roles and edge labels
 * an EML `%%rule` flowchart carries, so nothing is lost on the way to the
 * generated application.
 */

import {
  applyNodeChanges,
  Background,
  type Connection,
  Controls,
  type Edge,
  type EdgeChange,
  Handle,
  MarkerType,
  type Node,
  type NodeChange,
  type NodeProps,
  Position,
  ReactFlow,
  ReactFlowProvider,
} from "@xyflow/react";
import "@xyflow/react/dist/style.css";
import { Diamond, Play, Plus, Settings2, Square, Trash2, Zap } from "lucide-react";
import type React from "react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  ROLE_HINTS,
  ROLE_LABELS,
  type RuleFlow,
  type RuleFlowNode,
  type RuleNodeRole,
} from "../../lib/eml/rule-flow";

const ROLE_STYLES: Record<RuleNodeRole, { ring: string; chip: string; icon: React.ElementType }> = {
  start: {
    ring: "border-emerald-400 bg-emerald-50",
    chip: "bg-emerald-100 text-emerald-800",
    icon: Play,
  },
  decision: {
    ring: "border-amber-400 bg-amber-50",
    chip: "bg-amber-100 text-amber-800",
    icon: Diamond,
  },
  action: { ring: "border-sky-400 bg-sky-50", chip: "bg-sky-100 text-sky-800", icon: Square },
  compute: {
    ring: "border-violet-400 bg-violet-50",
    chip: "bg-violet-100 text-violet-800",
    icon: Zap,
  },
  end: { ring: "border-slate-400 bg-slate-100", chip: "bg-slate-200 text-slate-800", icon: Square },
};

type StepData = { label: string; role: RuleNodeRole; selected?: boolean };

function StepNode({ data, selected }: NodeProps) {
  const stepData = data as StepData;
  const style = ROLE_STYLES[stepData.role];
  const Icon = style.icon;

  return (
    <div
      className={`min-w-[170px] max-w-[230px] rounded-lg border-2 px-3 py-2 shadow-sm transition ${style.ring} ${
        selected ? "ring-2 ring-offset-1 ring-primary" : ""
      } ${stepData.role === "decision" ? "rounded-2xl" : ""}`}
    >
      {stepData.role !== "start" && <Handle type="target" position={Position.Top} />}
      <div className="flex items-center gap-1.5">
        <Icon className="h-3.5 w-3.5 shrink-0 opacity-70" />
        <span className={`rounded px-1 py-0.5 text-[10px] font-medium uppercase ${style.chip}`}>
          {ROLE_LABELS[stepData.role]}
        </span>
      </div>
      <p className="mt-1 break-words text-sm font-medium leading-snug text-slate-900">
        {stepData.label || "Untitled step"}
      </p>
      {stepData.role !== "end" && <Handle type="source" position={Position.Bottom} />}
    </div>
  );
}

const NODE_TYPES = { step: StepNode };

export interface RuleFlowCanvasProps {
  flow: RuleFlow;
  onChange: (flow: RuleFlow) => void;
  /** Entity attribute names, offered as hints when labelling a condition. */
  fieldHints?: string[];
}

let idCounter = 0;
const nextId = (role: string) => `${role}_${Date.now().toString(36)}${(idCounter++).toString(36)}`;

export function RuleFlowCanvas({ flow, onChange, fieldHints = [] }: RuleFlowCanvasProps) {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  // The canvas owns positions while dragging; committing every pixel to the
  // parent would re-serialise the model on each mouse move.
  const positions = useRef(new Map<string, { x: number; y: number }>());

  useEffect(() => {
    for (const node of flow.nodes) {
      if (node.position && !positions.current.has(node.id)) {
        positions.current.set(node.id, node.position);
      }
    }
  }, [flow.nodes]);

  const nodes: Node[] = useMemo(
    () =>
      flow.nodes.map((node) => ({
        id: node.id,
        type: "step",
        position: positions.current.get(node.id) ?? node.position ?? { x: 80, y: 60 },
        data: { label: node.label, role: node.role } satisfies StepData,
      })),
    [flow.nodes]
  );

  const edges: Edge[] = useMemo(
    () =>
      flow.edges.map((edge) => ({
        id: edge.id,
        source: edge.source,
        target: edge.target,
        label: edge.label,
        labelStyle: { fontSize: 11, fontWeight: 600 },
        markerEnd: { type: MarkerType.ArrowClosed },
        style: { strokeWidth: 1.5 },
      })),
    [flow.edges]
  );

  const selectedNode = flow.nodes.find((node) => node.id === selectedId) ?? null;
  const selectedEdge = flow.edges.find((edge) => edge.id === selectedId) ?? null;

  const handleNodesChange = useCallback(
    (changes: NodeChange[]) => {
      const next = applyNodeChanges(changes, nodes);
      for (const node of next) positions.current.set(node.id, node.position);
      // Only a finished drag is worth telling the parent about.
      if (changes.some((change) => change.type === "position" && change.dragging === false)) {
        onChange({
          ...flow,
          nodes: flow.nodes.map((node) => ({
            ...node,
            position: positions.current.get(node.id) ?? node.position,
          })),
        });
      }
    },
    [flow, nodes, onChange]
  );

  const handleEdgesChange = useCallback(
    (changes: EdgeChange[]) => {
      const removed = changes.filter((change) => change.type === "remove").map((c) => c.id);
      if (!removed.length) return;
      onChange({ ...flow, edges: flow.edges.filter((edge) => !removed.includes(edge.id)) });
    },
    [flow, onChange]
  );

  const handleConnect = useCallback(
    (connection: Connection) => {
      if (!connection.source || !connection.target) return;
      if (connection.source === connection.target) return;
      const exists = flow.edges.some(
        (edge) => edge.source === connection.source && edge.target === connection.target
      );
      if (exists) return;

      const source = flow.nodes.find((node) => node.id === connection.source);
      onChange({
        ...flow,
        edges: [
          ...flow.edges,
          {
            id: nextId("edge"),
            source: connection.source,
            target: connection.target,
            // A branch needs a condition; seed it so the requirement is visible.
            label: source?.role === "decision" ? "Yes" : undefined,
          },
        ],
      });
    },
    [flow, onChange]
  );

  const addStep = (role: RuleNodeRole) => {
    const id = nextId(role);
    const row = flow.nodes.length;
    const position = { x: 80 + (row % 3) * 260, y: 60 + Math.floor(row / 3) * 130 };
    positions.current.set(id, position);
    onChange({
      ...flow,
      nodes: [...flow.nodes, { id, role, label: defaultLabel(role), position }],
    });
    setSelectedId(id);
  };

  const updateNode = (id: string, patch: Partial<RuleFlowNode>) => {
    onChange({
      ...flow,
      nodes: flow.nodes.map((node) => (node.id === id ? { ...node, ...patch } : node)),
    });
  };

  const deleteSelected = () => {
    if (selectedNode) {
      onChange({
        nodes: flow.nodes.filter((node) => node.id !== selectedNode.id),
        edges: flow.edges.filter(
          (edge) => edge.source !== selectedNode.id && edge.target !== selectedNode.id
        ),
      });
    } else if (selectedEdge) {
      onChange({ ...flow, edges: flow.edges.filter((edge) => edge.id !== selectedEdge.id) });
    }
    setSelectedId(null);
  };

  return (
    <div className="flex h-full min-h-[460px] gap-3">
      {/* The palette sits above the canvas rather than floating over it — an
          overlay hides whatever node happens to be drawn in that corner. */}
      <div className="flex min-w-0 flex-1 flex-col gap-2">
        <div className="flex flex-wrap gap-1.5">
          {(["start", "decision", "action", "compute", "end"] as RuleNodeRole[]).map((role) => {
            const Icon = ROLE_STYLES[role].icon;
            return (
              <button
                key={role}
                type="button"
                onClick={() => addStep(role)}
                title={ROLE_HINTS[role]}
                className="flex items-center gap-1 rounded-md border border-border bg-card px-2 py-1 text-xs font-medium shadow-sm hover:bg-muted"
              >
                <Plus className="h-3 w-3" />
                <Icon className="h-3 w-3 opacity-70" />
                {ROLE_LABELS[role]}
              </button>
            );
          })}
        </div>

        <div className="min-h-0 flex-1 overflow-hidden rounded-lg border border-border bg-white">
          <ReactFlowProvider>
            <ReactFlow
              nodes={nodes}
              edges={edges}
              nodeTypes={NODE_TYPES}
              onNodesChange={handleNodesChange}
              onEdgesChange={handleEdgesChange}
              onConnect={handleConnect}
              onNodeClick={(_event, node) => setSelectedId(node.id)}
              onEdgeClick={(_event, edge) => setSelectedId(edge.id)}
              onPaneClick={() => setSelectedId(null)}
              fitView
              fitViewOptions={{ padding: 0.15 }}
              proOptions={{ hideAttribution: true }}
            >
              <Background gap={16} size={1} />
              <Controls showInteractive={false} />
            </ReactFlow>
          </ReactFlowProvider>
        </div>
      </div>

      {/* Inspector */}
      <aside className="w-72 shrink-0 overflow-y-auto rounded-lg border border-border bg-card p-3">
        <div className="mb-2 flex items-center gap-1.5 text-xs font-semibold uppercase text-muted-foreground">
          <Settings2 className="h-3.5 w-3.5" />
          {selectedNode ? "Step" : selectedEdge ? "Branch" : "Nothing selected"}
        </div>

        {!selectedNode && !selectedEdge && (
          <p className="text-xs leading-relaxed text-muted-foreground">
            Add a step with the buttons above the canvas, then drag from the bottom of one step to
            the top of another to connect them. Click anything to edit it here.
          </p>
        )}

        {selectedNode && (
          <div className="space-y-3">
            <label className="block">
              <span className="mb-1 block text-xs font-medium">Label</span>
              <input
                className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
                value={selectedNode.label}
                onChange={(event) => updateNode(selectedNode.id, { label: event.target.value })}
                placeholder="What happens here?"
              />
            </label>

            <label className="block">
              <span className="mb-1 block text-xs font-medium">Kind</span>
              <select
                className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
                value={selectedNode.role}
                onChange={(event) =>
                  updateNode(selectedNode.id, { role: event.target.value as RuleNodeRole })
                }
              >
                {(Object.keys(ROLE_LABELS) as RuleNodeRole[]).map((role) => (
                  <option key={role} value={role}>
                    {ROLE_LABELS[role]}
                  </option>
                ))}
              </select>
              <span className="mt-1 block text-[11px] leading-snug text-muted-foreground">
                {ROLE_HINTS[selectedNode.role]}
              </span>
            </label>
          </div>
        )}

        {selectedEdge && (
          <div className="space-y-3">
            <label className="block">
              <span className="mb-1 block text-xs font-medium">Condition</span>
              <input
                className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
                value={selectedEdge.label ?? ""}
                onChange={(event) =>
                  onChange({
                    ...flow,
                    edges: flow.edges.map((edge) =>
                      edge.id === selectedEdge.id ? { ...edge, label: event.target.value } : edge
                    ),
                  })
                }
                placeholder="Yes / amount > 1000"
                list="rule-field-hints"
              />
              <datalist id="rule-field-hints">
                {fieldHints.map((hint) => (
                  <option key={hint} value={hint} />
                ))}
              </datalist>
              <span className="mt-1 block text-[11px] leading-snug text-muted-foreground">
                Leaving a decision, this is the branch condition.
              </span>
            </label>
          </div>
        )}

        {(selectedNode || selectedEdge) && (
          <button
            type="button"
            onClick={deleteSelected}
            className="mt-4 flex w-full items-center justify-center gap-1.5 rounded-md border border-destructive/40 px-2 py-1.5 text-xs font-medium text-destructive hover:bg-destructive/10"
          >
            <Trash2 className="h-3.5 w-3.5" />
            Delete {selectedNode ? "step" : "branch"}
          </button>
        )}
      </aside>
    </div>
  );
}

function defaultLabel(role: RuleNodeRole): string {
  switch (role) {
    case "start":
      return "Start";
    case "end":
      return "End";
    case "decision":
      return "Condition?";
    case "compute":
      return "Calculate value";
    default:
      return "Apply outcome";
  }
}

/** A blank rule that already has the two ends every decision flow needs. */
export function emptyRuleFlow(): RuleFlow {
  const start = nextId("start");
  const end = nextId("end");
  return {
    nodes: [
      { id: start, role: "start", label: "Start", position: { x: 120, y: 40 } },
      { id: end, role: "end", label: "End", position: { x: 120, y: 300 } },
    ],
    edges: [],
  };
}

"use client";

/**
 * The state-machine canvas.
 *
 * States become the entity's status enum and transitions become the moves the
 * generated application allows, so this edits the two things that matter and
 * nothing else. Start and finish are marked on the state itself rather than
 * drawn as separate nodes — `[*]` is a marker in Mermaid, not a state, and
 * showing it as a box invites people to connect things to it that cannot be.
 */

import {
  applyNodeChanges,
  Background,
  type Connection,
  Controls,
  type Edge,
  type EdgeChange,
  Handle,
  MarkerType,
  type Node,
  type NodeChange,
  type NodeProps,
  Position,
  ReactFlow,
  ReactFlowProvider,
  useReactFlow,
} from "@xyflow/react";
import "@xyflow/react/dist/style.css";
import { Flag, Play, Plus, Settings2, Trash2 } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { StateFlow } from "../../lib/eml/workflow-flow";

type StateData = { name: string; isInitial: boolean; isTerminal: boolean };

function StateNode({ data, selected }: NodeProps) {
  const stateData = data as StateData;
  return (
    <div
      className={`min-w-[140px] rounded-full border-2 px-4 py-2 text-center shadow-sm transition ${
        stateData.isInitial
          ? "border-emerald-400 bg-emerald-50"
          : stateData.isTerminal
            ? "border-slate-400 bg-slate-100"
            : "border-sky-400 bg-sky-50"
      } ${selected ? "ring-2 ring-offset-1 ring-primary" : ""}`}
    >
      <Handle type="target" position={Position.Left} />
      <div className="flex items-center justify-center gap-1.5">
        {stateData.isInitial && <Play className="h-3 w-3 text-emerald-700" />}
        {stateData.isTerminal && <Flag className="h-3 w-3 text-slate-700" />}
        <span className="font-mono text-sm font-medium">{stateData.name}</span>
      </div>
      <Handle type="source" position={Position.Right} />
    </div>
  );
}

const NODE_TYPES = { state: StateNode };

export interface StateFlowCanvasProps {
  flow: StateFlow;
  onChange: (flow: StateFlow) => void;
}

let counter = 0;
const nextId = () => `s${Date.now().toString(36)}${(counter++).toString(36)}`;

export function StateFlowCanvas({ flow, onChange }: StateFlowCanvasProps) {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const positions = useRef(new Map<string, { x: number; y: number }>());

  const nodes: Node[] = useMemo(
    () =>
      flow.states.map((state, index) => ({
        id: state.id,
        type: "state",
        position: positions.current.get(state.id) ??
          state.position ?? { x: 80 + index * 200, y: 80 },
        data: {
          name: state.name,
          isInitial: flow.initial === state.id,
          isTerminal: flow.terminal.includes(state.id),
        } satisfies StateData,
      })),
    [flow]
  );

  const edges: Edge[] = useMemo(
    () =>
      flow.transitions.map((transition) => ({
        id: transition.id,
        source: transition.from,
        target: transition.to,
        label: transition.label,
        labelStyle: { fontSize: 11, fontWeight: 600 },
        // An opaque plate, so a line crossing a label does not strike through it.
        labelShowBg: true,
        labelBgStyle: { fill: "hsl(var(--card))" },
        labelBgPadding: [4, 2] as [number, number],
        labelBgBorderRadius: 4,
        markerEnd: { type: MarkerType.ArrowClosed },
        style: { strokeWidth: 1.5 },
      })),
    [flow.transitions]
  );

  const selectedState = flow.states.find((state) => state.id === selectedId) ?? null;
  const selectedTransition = flow.transitions.find((t) => t.id === selectedId) ?? null;

  const handleNodesChange = useCallback(
    (changes: NodeChange[]) => {
      const next = applyNodeChanges(changes, nodes);
      for (const node of next) positions.current.set(node.id, node.position);
      if (changes.some((change) => change.type === "position" && change.dragging === false)) {
        onChange({
          ...flow,
          states: flow.states.map((state) => ({
            ...state,
            position: positions.current.get(state.id) ?? state.position,
          })),
        });
      }
    },
    [flow, nodes, onChange]
  );

  const handleEdgesChange = useCallback(
    (changes: EdgeChange[]) => {
      const removed = changes.filter((change) => change.type === "remove").map((c) => c.id);
      if (!removed.length) return;
      onChange({
        ...flow,
        transitions: flow.transitions.filter((t) => !removed.includes(t.id)),
      });
    },
    [flow, onChange]
  );

  const handleConnect = useCallback(
    (connection: Connection) => {
      if (!connection.source || !connection.target) return;
      const exists = flow.transitions.some(
        (t) => t.from === connection.source && t.to === connection.target
      );
      if (exists) return;
      onChange({
        ...flow,
        transitions: [
          ...flow.transitions,
          { id: nextId(), from: connection.source, to: connection.target },
        ],
      });
    },
    [flow, onChange]
  );

  const addState = () => {
    const id = nextId();
    const name = `state_${flow.states.length + 1}`;
    // Wrapped into rows rather than marching right forever: past the third
    // state a single row runs outside the canvas, and the node is added but
    // never seen.
    const position = {
      x: 80 + (flow.states.length % 3) * 200,
      y: 80 + Math.floor(flow.states.length / 3) * 130,
    };
    positions.current.set(id, position);
    onChange({
      ...flow,
      states: [...flow.states, { id, name, position }],
      initial: flow.initial ?? id,
    });
    setSelectedId(id);
  };

  const renameState = (id: string, name: string) => {
    onChange({
      ...flow,
      states: flow.states.map((state) => (state.id === id ? { ...state, name } : state)),
    });
  };

  const deleteSelected = () => {
    if (selectedState) {
      onChange({
        states: flow.states.filter((state) => state.id !== selectedState.id),
        transitions: flow.transitions.filter(
          (t) => t.from !== selectedState.id && t.to !== selectedState.id
        ),
        initial: flow.initial === selectedState.id ? undefined : flow.initial,
        terminal: flow.terminal.filter((id) => id !== selectedState.id),
      });
    } else if (selectedTransition) {
      onChange({
        ...flow,
        transitions: flow.transitions.filter((t) => t.id !== selectedTransition.id),
      });
    }
    setSelectedId(null);
  };

  return (
    <div className="flex h-full min-h-[420px] gap-3">
      <div className="flex min-w-0 flex-1 flex-col gap-2">
        <div>
          <button
            type="button"
            onClick={addState}
            className="flex items-center gap-1 rounded-md border border-border bg-card px-2 py-1 text-xs font-medium shadow-sm hover:bg-muted"
          >
            <Plus className="h-3 w-3" />
            Add state
          </button>
        </div>

        <div className="min-h-0 flex-1 overflow-hidden rounded-lg border border-border bg-white">
          <ReactFlowProvider>
            <ReactFlow
              nodes={nodes}
              edges={edges}
              nodeTypes={NODE_TYPES}
              onNodesChange={handleNodesChange}
              onEdgesChange={handleEdgesChange}
              onConnect={handleConnect}
              onNodeClick={(_event, node) => setSelectedId(node.id)}
              onEdgeClick={(_event, edge) => setSelectedId(edge.id)}
              onPaneClick={() => setSelectedId(null)}
              fitView
              fitViewOptions={{ padding: 0.15 }}
              proOptions={{ hideAttribution: true }}
            >
              <Background gap={16} size={1} />
              <Controls showInteractive={false} />
              <FitOnGrowth count={flow.states.length} />
            </ReactFlow>
          </ReactFlowProvider>
        </div>
      </div>

      <aside className="w-72 shrink-0 overflow-y-auto rounded-lg border border-border bg-card p-3">
        <div className="mb-2 flex items-center gap-1.5 text-xs font-semibold uppercase text-muted-foreground">
          <Settings2 className="h-3.5 w-3.5" />
          {selectedState ? "State" : selectedTransition ? "Transition" : "Nothing selected"}
        </div>

        {!selectedState && !selectedTransition && (
          <p className="text-xs leading-relaxed text-muted-foreground">
            Add the statuses this record moves through, then drag from the right of one to the left
            of another to allow that move. Each state becomes a value of the entity's status.
          </p>
        )}

        {selectedState && (
          <div className="space-y-3">
            <label className="block">
              <span className="mb-1 block text-xs font-medium">Status value</span>
              <input
                className="w-full rounded-md border border-border px-2 py-1.5 font-mono text-sm"
                value={selectedState.name}
                onChange={(event) => renameState(selectedState.id, event.target.value)}
                placeholder="submitted"
              />
            </label>

            <label className="flex items-center gap-2 text-sm">
              <input
                type="radio"
                checked={flow.initial === selectedState.id}
                onChange={() => onChange({ ...flow, initial: selectedState.id })}
              />
              Records start here
            </label>

            <label className="flex items-center gap-2 text-sm">
              <input
                type="checkbox"
                checked={flow.terminal.includes(selectedState.id)}
                onChange={(event) =>
                  onChange({
                    ...flow,
                    terminal: event.target.checked
                      ? [...flow.terminal, selectedState.id]
                      : flow.terminal.filter((id) => id !== selectedState.id),
                  })
                }
              />
              The process finishes here
            </label>
          </div>
        )}

        {selectedTransition && (
          <label className="block">
            <span className="mb-1 block text-xs font-medium">Trigger (optional)</span>
            <input
              className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
              value={selectedTransition.label ?? ""}
              onChange={(event) =>
                onChange({
                  ...flow,
                  transitions: flow.transitions.map((t) =>
                    t.id === selectedTransition.id ? { ...t, label: event.target.value } : t
                  ),
                })
              }
              placeholder="submit"
            />
            <span className="mt-1 block text-[11px] leading-snug text-muted-foreground">
              Names the action that moves a record along this arrow — the button's label.
            </span>
            <span className="mb-1 mt-3 block text-xs font-medium">Who may press it</span>
            <input
              className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
              aria-label="Roles that may press this move"
              value={(selectedTransition.roles ?? []).join(", ")}
              onChange={(event) =>
                onChange({
                  ...flow,
                  transitions: flow.transitions.map((t) =>
                    t.id === selectedTransition.id
                      ? {
                          ...t,
                          // Kept as typed (an empty entry lets a comma stay
                          // while the next role is written); emptied on save.
                          roles: event.target.value.split(/[,|]/).map((role) => role.trimStart()),
                        }
                      : t
                  ),
                })
              }
              placeholder="sales_manager"
            />
            <span className="mt-1 block text-[11px] leading-snug text-muted-foreground">
              Roles, separated by commas. Empty: anyone who may edit the record.
            </span>
          </label>
        )}

        {(selectedState || selectedTransition) && (
          <button
            type="button"
            onClick={deleteSelected}
            className="mt-4 flex w-full items-center justify-center gap-1.5 rounded-md border border-destructive/40 px-2 py-1.5 text-xs font-medium text-destructive hover:bg-destructive/10"
          >
            <Trash2 className="h-3.5 w-3.5" />
            Delete {selectedState ? "state" : "transition"}
          </button>
        )}
      </aside>
    </div>
  );
}

/**
 * Bring a newly added state into view.
 *
 * `fitView` as a prop only runs on the first render, so a state added later
 * stayed wherever it was placed while the viewport never moved — the node
 * existed, was selected, and was serialised, but the canvas showed nothing new
 * and the button read as broken. This has to sit inside the provider, which is
 * the only place the instance exists.
 */
function FitOnGrowth({ count }: { count: number }) {
  const instance = useReactFlow();
  const previous = useRef(count);

  useEffect(() => {
    if (count > previous.current) {
      previous.current = count;
      // The node is measured on the next frame; fitting before that uses a
      // zero-size node and lands the viewport in the wrong place.
      const frame = requestAnimationFrame(() => instance.fitView({ padding: 0.2, duration: 200 }));
      return () => cancelAnimationFrame(frame);
    }
    previous.current = count;
    return undefined;
  }, [count, instance]);

  return null;
}

/** A blank state machine with the draft state most processes start from. */
export function emptyStateFlow(): StateFlow {
  const id = nextId();
  return {
    states: [{ id, name: "draft", position: { x: 80, y: 80 } }],
    transitions: [],
    initial: id,
    terminal: [],
  };
}

import "../../lib/dayjs-plugins";
import "../../lib/monaco-local";
import "@gorules/jdm-editor/dist/style.css";
import {
  DecisionGraph,
  type DecisionGraphType,
  type DictionaryMap,
  GraphSimulator,
  JdmConfigProvider,
  type JdmUiMode,
  nodeSpecification,
  type Simulation,
  type SimulationTrace,
} from "@gorules/jdm-editor";
import { Play } from "lucide-react";
import { useMemo, useState } from "react";
import type { DecisionTable as InternalDecisionTable } from "../../lib/eml/decision-table";
import type { RuleDryRun } from "../../lib/eml/dry-run-types";
import type { RuleConstraints } from "../../lib/eml/rule-constraints";
import {
  constrainGraph,
  graphProblems,
  inputColumns,
  setInputField,
  withoutStockImport,
} from "../../lib/eml/rule-graph-constraints";
import { withNodePositions } from "../../lib/eml/graph-layout";
import { tableToGraph } from "../../lib/eml/rule-templates";

interface GoRulesEditorPanelProps {
  /** Serialised DecisionGraphType JSON, if the rule was already saved as a graph. */
  jdmGraph?: string;
  table: InternalDecisionTable;
  entityFields: string[];
  /** Enum values for entity fields, keyed by bare field name. */
  entityEnums?: Record<string, string[]>;
  /** Processes defined for the entity — all that an answer naming one may pick from. */
  entityWorkflows?: string[];
  /** Each field's JSON type, for the request schema. */
  fieldTypes?: Record<string, "string" | "number" | "boolean">;
  /** Human-readable rule name used for the initial decision table node label. */
  ruleName?: string;
  /** The entity and a starting record, for the editor's own simulator. */
  entity: string;
  /** How the Simulator reaches the server that runs the rule. */
  dryRun: RuleDryRun;
  sampleRecord: string;
  onChange: (graphJson: string) => void;
  /** Height of the graph canvas in pixels. Defaults to 640. */
  height?: number;
  /** When true, the entity's fields haven't loaded yet — Run is disabled. */
  fieldsLoading?: boolean;
}

/**
 * What a rule may answer. There is no "start a workflow" here: a rule decides,
 * and which workflow it belongs to is chosen in the workflow editor alone.
 */
const ACTION_CHOICES: DictionaryMap = {
  action: [
    { label: "Validation Error (block write)", value: "validation-error" },
    { label: "Transform Field Value", value: "transform" },
    { label: "Allow (no action)", value: "" },
  ],
};

/**
 * The request node's schema, so the fields a check can look at are the entity's
 * own. The editor reads it for the field pickers and for its completion, and a
 * name outside it is flagged rather than accepted.
 */
function withRequestSchema(
  graph: DecisionGraphType,
  fields: string[],
  values: Record<string, string[]>,
  types: Record<string, "string" | "number" | "boolean">
): DecisionGraphType {
  if (fields.length === 0) return graph;
  const schema = JSON.stringify(
    {
      type: "object",
      properties: Object.fromEntries(
        fields.map((field) => [
          field,
          // null stays in the type union so the schema never rejects a blank field
          // arriving as null from the application.  It must NOT appear in the enum
          // list: the GoRules simulator renders enum fields as a dropdown and
          // defaults to the first null-able entry, so every field shows "null"
          // before the user touches anything.
          values[field]
            ? { type: ["string", "null"], enum: values[field] }
            : { type: [types[field] ?? "string", "null"] },
        ])
      ),
    },
    null,
    2
  );
  return {
    ...graph,
    nodes: graph.nodes.map((node) =>
      node.type === "inputNode"
        ? { ...node, content: { ...(node.content as object), schema } }
        : node
    ),
  } as DecisionGraphType;
}

/**
 * Every rule starts from the record being written, not from a request, so the
 * editor's first node says "Record" — in the component palette, in the node
 * title, and on a node dragged out new. The library offers no prop for it: the
 * built-in components are not replaceable, only extendable, so its own
 * specification is renamed once, for this editor.
 */
const functionSpec = nodeSpecification.functionNode;
{
  const generate = functionSpec.generateNode;
  functionSpec.generateNode = (params) => {
    const node = generate(params);
    return { ...node, content: withoutStockImport(node.content) as typeof node.content };
  };
}

const inputSpec = nodeSpecification.inputNode;
if (inputSpec.displayName !== "Record") {
  const generate = inputSpec.generateNode;
  inputSpec.displayName = "Record";
  inputSpec.generateNode = (params) => ({ ...generate(params), name: "Record" });
}

const MODES: ReadonlyArray<{ id: JdmUiMode; label: string }> = [
  { id: "dev", label: "Developer" },
  { id: "business", label: "Business" },
];

/**
 * The GoRules decision-graph editor, with what it ships with: every node kind
 * (input, output, decision table, expression, function, switch), the graph
 * and the tabs for each node, Developer and Business views, and its simulator
 * panel with a per-run result. The simulator runs the same compiled rule the
 * application runs, through the dry-run route, and nothing is saved.
 */
export function GoRulesEditorPanel({
  jdmGraph,
  table,
  entityFields,
  entityEnums = {},
  entityWorkflows = [],
  fieldTypes = {},
  ruleName = "Decision",
  entity,
  dryRun,
  sampleRecord,
  onChange,
  height = 640,
  fieldsLoading = false,
}: GoRulesEditorPanelProps) {
  const [mode, setMode] = useState<JdmUiMode>("business");
  const [simulate, setSimulate] = useState<Simulation | undefined>();
  const [running, setRunning] = useState(false);

  const constraints = useMemo<RuleConstraints>(
    () => ({ fields: entityFields, values: entityEnums, workflowNames: entityWorkflows }),
    [entityFields, entityEnums, entityWorkflows]
  );

  const graphValue = useMemo<DecisionGraphType>(() => {
    let graph: DecisionGraphType | null = null;
    if (jdmGraph) {
      try {
        graph = JSON.parse(jdmGraph) as DecisionGraphType;
      } catch {
        // fall through to conversion
      }
    }
    graph ??= tableToGraph(table, ruleName) as unknown as DecisionGraphType;
    // A graph compiled from a `%%rule` flowchart has no node positions, and the
    // canvas cannot draw a node without one (lib/eml/graph-layout.ts).
    graph = withNodePositions(graph);
    return withRequestSchema(
      constrainGraph(graph, constraints),
      entityFields,
      entityEnums,
      fieldTypes
    );
  }, [jdmGraph, table, ruleName, entityFields, entityEnums, fieldTypes, constraints]);

  const problems = useMemo(() => graphProblems(graphValue, constraints), [graphValue, constraints]);

  // Every choice the editor offers is something that exists: the answers a rule
  // may give, the values a field may hold (its enum, or its state machine's
  // states), and the processes defined for this entity. Nothing is free text
  // where the model already says what is allowed.
  const dictionaries = useMemo<DictionaryMap>(
    () => ({
      ...ACTION_CHOICES,
      ...Object.fromEntries(
        Object.entries(entityEnums).map(([field, values]) => [
          field,
          values.map((v) => ({ label: v, value: v })),
        ])
      ),
      workflowName: entityWorkflows.map((name) => ({ label: name, value: name })),
    }),
    [entityEnums, entityWorkflows]
  );

  /** Every edit passes through the model's constraints before it is kept. */
  const commit = (next: DecisionGraphType) =>
    onChange(JSON.stringify(constrainGraph(next, constraints)));

  const columns = useMemo(() => inputColumns(graphValue as never), [graphValue]);
  const tableIds = [...new Set(columns.map((column) => column.nodeId))];
  const inputCount = columns.filter((column) => column.nodeId === tableIds[0]).length;

  /**
   * Controls that live in the editor's own tab bar, so they are part of the
   * graph and not a strip above it: the fields each decision table reads, picked
   * from the entity's own fields, and the Developer / Business view.
   */
  const tabBarExtra = (
    <div className="flex items-center gap-2 pr-2 text-xs">
      {tableIds.map((nodeId) => {
        const mine = columns.filter((column) => column.nodeId === nodeId);
        const used = new Set(mine.map((column) => column.field));
        return (
          <div
            key={nodeId}
            role="group"
            aria-label={`Inputs of ${mine[0]?.nodeName}`}
            className="flex items-center gap-1"
          >
            <span className="font-medium">Inputs</span>
            {mine.map((column) => (
              <select
                key={column.columnId}
                aria-label={`Input field ${column.field || "whole record"}`}
                className="max-w-[9rem] rounded border border-border bg-background px-1 py-0.5 text-foreground"
                value={column.field}
                onChange={(e) =>
                  commit(setInputField(graphValue, nodeId, column.columnId, e.target.value))
                }
              >
                {column.field === "" && <option value="">Whole record (formula)</option>}
                {entityFields.map((field) => (
                  <option key={field} value={field}>
                    {field}
                  </option>
                ))}
              </select>
            ))}
            <select
              aria-label="Add an input field"
              className="max-w-[9rem] rounded border border-dashed border-border bg-background px-1 py-0.5 text-foreground"
              value=""
              onChange={(e) => {
                if (e.target.value) commit(setInputField(graphValue, nodeId, null, e.target.value));
              }}
            >
              <option value="">+ field…</option>
              {entityFields
                .filter((field) => !used.has(field))
                .map((field) => (
                  <option key={field} value={field}>
                    {field}
                  </option>
                ))}
            </select>
          </div>
        );
      })}
      <div
        role="group"
        aria-label="Editor view"
        className="flex shrink-0 overflow-hidden rounded border border-border font-medium"
      >
        {MODES.map(({ id, label }) => (
          <button
            key={id}
            type="button"
            aria-pressed={mode === id}
            onClick={() => setMode(id)}
            className={`px-2 py-0.5 ${mode === id ? "bg-primary text-primary-foreground" : "hover:bg-muted"}`}
          >
            {label}
          </button>
        ))}
      </div>
    </div>
  );

  const run = async ({ graph, context }: { graph: DecisionGraphType; context: unknown }) => {
    setRunning(true);
    try {
      const data = await dryRun({ graph, record: context as Record<string, unknown>, entity });
      if (!data.ok) {
        setSimulate({
          error: { title: "The rule did not run", message: data.problems.join(" "), data: {} },
        });
        return;
      }
      // One trace entry per node, so the Simulator can show what each produced.
      // The route reports them by node name, in the order they ran.
      const steps = [...data.trace];
      const trace: Record<string, SimulationTrace> = {};
      // Index nodes by id so edges can look up their source's output.
      const nodeById = Object.fromEntries(graph.nodes.map((n) => [n.id, n]));
      for (const node of graph.nodes) {
        const own = node.type === "inputNode" ? null : steps.findIndex((s) => s.node === node.name);
        const hit = own !== null && own >= 0 ? steps.splice(own, 1)[0] : undefined;
        if (node.type !== "inputNode" && !hit) continue;
        trace[node.id] = {
          id: node.id,
          name: node.name,
          input: node.type === "inputNode" ? context : null,
          output: node.type === "inputNode" ? context : hit?.output,
          performance: "",
          traceData: null,
        };
      }
      // Wire up each node's input from its upstream neighbour's output.
      // The dry-run route only returns outputs; the graph's edges tell us
      // which node fed which, so the Simulator's Input tab shows real data.
      for (const edge of graph.edges) {
        const target = nodeById[edge.targetId];
        if (!target || target.type === "inputNode") continue;
        const sourceEntry = trace[edge.sourceId];
        const targetEntry = trace[edge.targetId];
        if (sourceEntry && targetEntry && targetEntry.input === null) {
          targetEntry.input = sourceEntry.output;
        }
      }
      setSimulate({
        result: { performance: "", result: data.result, snapshot: graph, trace },
      });
    } catch (caught) {
      setSimulate({
        error: {
          title: "The rule did not run",
          message: caught instanceof Error ? caught.message : "Could not run the rule.",
          data: {},
        },
      });
    } finally {
      setRunning(false);
    }
  };

  return (
    <div className="jdm-scope">
      {/* The editor's own provider renders an `.ant-app` that fills its parent's
          height. Inside a stretched flex column that made it as tall as the rail
          beside it and pushed everything under the editor off the screen. */}
      <style>{`
        .jdm-scope > .ant-app { height: auto !important; min-height: 0 !important; }
        /* An input is picked from the entity's fields in the editor's tab bar, not
           typed into the editor's own free-text field box. */
        .jdm-scope thead tr:first-child th:nth-child(2) .cta-wrapper { display: none; }
        .jdm-scope thead tr:nth-child(2) th:nth-child(n+3):nth-child(-n+${2 + inputCount}) .grl-field-edit {
          pointer-events: none;
        }
      `}</style>
      <JdmConfigProvider>
        <div className="overflow-hidden rounded-xl border border-border" style={{ height }}>
          <DecisionGraph
            value={graphValue}
            onChange={(next) => commit(next)}
            dictionaries={dictionaries}
            mode={mode}
            tabBarExtraContent={tabBarExtra}
            name={ruleName}
            simulate={simulate}
            // Open on the whole graph. A compiled rule is wider than the canvas,
            // and starting at 100% showed its first two nodes and nothing to say
            // there were twelve more to the right.
            onReactFlowInit={(instance) => {
              requestAnimationFrame(() => instance.fitView({ padding: 0.15, maxZoom: 1 }));
            }}
            panels={[
              {
                id: "simulator",
                title: "Simulator",
                icon: <Play className="h-4 w-4" />,
                renderPanel: () => (
                  <GraphSimulator
                    key={sampleRecord}
                    defaultRequest={sampleRecord}
                    loading={running || fieldsLoading}
                    onRun={run}
                    onClear={() => setSimulate(undefined)}
                  />
                ),
              },
            ]}
          />
        </div>
        {problems.length > 0 && (
          <ul
            aria-label="Names that do not exist"
            className="mt-2 space-y-1 rounded-lg border border-amber-300 bg-amber-50 px-3 py-2 text-xs text-amber-900"
          >
            {problems.map((problem) => (
              <li key={problem}>{problem}</li>
            ))}
          </ul>
        )}
      </JdmConfigProvider>
    </div>
  );
}

import { AlertCircle, Code2, GripHorizontal } from "lucide-react";
import { lazy, Suspense, useCallback, useMemo, useState } from "react";

// Gorules JDM editor bundles monaco-editor which cannot run in SSR —
// lazy-load so it only resolves in the browser.
const GoRulesEditorPanel = lazy(() =>
  import("./GoRulesEditorPanel").then((m) => ({ default: m.GoRulesEditorPanel }))
);

import {
  type DecisionTable,
  emptyDecisionTable,
  tableToEmlFlowchart,
  validateDecisionTable,
} from "../../lib/eml/decision-table";
import type { RuleDryRun } from "../../lib/eml/dry-run-types";
import { convertFlowchartToTable } from "../../lib/eml/flowchart-to-table";
import { sampleRecord, tableToGraph } from "../../lib/eml/rule-templates";
import { RuleTryIt } from "./RuleTryIt";

/**
 * One business rule — shown as a decision table, matching the rule editor in
 * the generated admin application so both surfaces look and behave identically.
 */

export const RULE_EVENTS = [
  "beforeCreate",
  "afterCreate",
  "beforeUpdate",
  "afterUpdate",
  "beforeDelete",
  "customValidate",
] as const;

export interface EditableRule {
  /** Stable across renames, so React keeps the row it is editing. */
  key: string;
  name: string;
  entity: string;
  event: string;
  priority?: number;
  title?: string;
  table: DecisionTable;
  /**
   * Serialised `DecisionGraphType` JSON (nodes + edges) produced by the full
   * JDM graph editor. When set, the graph editor is shown instead of the table
   * editor, and the save path writes `%%jdm-graph` instead of `%%decision-table`.
   */
  jdmGraph?: string;
  /**
   * The rule's original Mermaid, kept verbatim when it is not a decision table
   * this editor wrote — a hand-authored `%%rule` flowchart, as every checked-in
   * example model uses. `table` holds a blank table in that case, and saving
   * would otherwise replace real branching logic with it. While this is set the
   * editor shows the source read-only and the save path writes it back
   * untouched; converting clears it and hands the rule to the table editor.
   */
  sourceFlowchart?: string;
  /**
   * How the rule is stored, which decides what the editor can write back.
   * `actions` means the table was compiled from `%%action` directives and a
   * save regenerates them; `decision-table` means it is the editor's own
   * directive; `flowchart` means the rule is only a Mermaid diagram.
   */
  sourceKind?: "actions" | "decision-table" | "flowchart";
  /**
   * The rule's name in the model when it was loaded. Kept because a rename here
   * must not change the `%%action` names already written under the old rule.
   */
  sourceRuleName?: string;
}

export function slugifyRuleName(value: string): string {
  // A name that is already an identifier is kept as written. Flattening `invoiceControl` to
  // `invoicecontrol` renamed every model rule that was saved, and a process looks a rule up by
  // its name.
  const identifier = value.trim();
  if (/^[a-z][A-Za-z0-9]*$/.test(identifier)) return identifier;
  const cleaned = value
    .replace(/[^A-Za-z0-9]+/g, " ")
    .trim()
    .split(" ")
    .map((word, index) =>
      index === 0 ? word.toLowerCase() : word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()
    )
    .join("");
  return cleaned || "rule";
}

export interface RuleEditorProps {
  rule: EditableRule;
  entities: Array<{ name: string; attributes: string[] }>;
  /** How this host runs a rule against a sample record (Try it and the Simulator). */
  dryRun: RuleDryRun;
  onChange: (patch: Partial<EditableRule>) => void;
  onError: (message: string | null) => void;
  /**
   * Show an authored flowchart as the decision table it describes, when it
   * reads as one, instead of the read-only Mermaid source. Off by default so
   * the Logic step converts only on request; the enhance page turns it on to
   * match the generated application's rule editor.
   */
  autoConvertFlowchart?: boolean;
  /** Enum values for the selected entity's fields, keyed by bare field name. */
  entityEnums?: Record<string, string[]>;
  /** Processes defined for the rule's entity — all an answer may start. */
  entityWorkflows?: string[];
  /** Each field's JSON type, so the editor can complete and check what is written. */
  fieldTypes?: Record<string, "string" | "number" | "boolean">;
  /**
   * Offer the Priority field. A host whose store has nowhere to keep one (a running application
   * orders nothing by it) turns it off rather than show a field that forgets.
   */
  showPriority?: boolean;
}

const TOTAL_HEIGHT = 880;
const MIN_GRAPH = 300;
const MIN_TRY_IT = 180;
const HANDLE_HEIGHT = 10;

export function RuleEditor({
  rule,
  entities,
  onChange,
  autoConvertFlowchart = true,
  entityEnums = {},
  entityWorkflows = [],
  fieldTypes,
  showPriority = true,
  dryRun,
}: RuleEditorProps) {
  const [showSource, setShowSource] = useState(false);
  const [graphHeight, setGraphHeight] = useState(640);
  const tryItHeight = TOTAL_HEIGHT - HANDLE_HEIGHT - graphHeight;

  const startDrag = useCallback(
    (e: React.MouseEvent) => {
      e.preventDefault();
      const startY = e.clientY;
      const startGraph = graphHeight;
      const onMove = (ev: MouseEvent) => {
        const delta = ev.clientY - startY;
        const next = Math.max(
          MIN_GRAPH,
          Math.min(TOTAL_HEIGHT - HANDLE_HEIGHT - MIN_TRY_IT, startGraph + delta)
        );
        setGraphHeight(next);
      };
      const onUp = () => {
        document.removeEventListener("mousemove", onMove);
        document.removeEventListener("mouseup", onUp);
        document.body.style.cursor = "";
      };
      document.body.style.cursor = "row-resize";
      document.addEventListener("mousemove", onMove);
      document.addEventListener("mouseup", onUp);
    },
    [graphHeight]
  );

  const MAX_GRAPH = TOTAL_HEIGHT - HANDLE_HEIGHT - MIN_TRY_IT;
  /** The handle is a focusable separator, so the keyboard resizes it too: ↑ and ↓, 40px a press. */
  const resizeByKey = (e: React.KeyboardEvent) => {
    const step = e.key === "ArrowUp" ? -40 : e.key === "ArrowDown" ? 40 : 0;
    if (!step) return;
    e.preventDefault();
    setGraphHeight((h) => Math.max(MIN_GRAPH, Math.min(MAX_GRAPH, h + step)));
  };
  const entityFields = useMemo(
    () => entities.find((e) => e.name === rule.entity)?.attributes ?? [],
    [entities, rule.entity]
  );
  // When the project model hasn't loaded yet, `entityFields` is empty but
  // `fieldTypes` (from the EML constraints API) already has the field names as
  // keys — use that as a fallback so the simulator opens with real field values
  // rather than an empty object that renders as null in the trace.
  const sampleFields = useMemo(
    () => (entityFields.length > 0 ? entityFields : Object.keys(fieldTypes ?? {})),
    [entityFields, fieldTypes]
  );
  // Whether the authored flowchart can be read as a table, worked out once so
  // the editor can show it and the banner can say which it is rather than
  // warning about both.
  const conversion = useMemo(
    () => convertFlowchartToTable(rule.sourceFlowchart ?? "", entityFields),
    [rule.sourceFlowchart, entityFields]
  );

  /**
   * The table the editor shows.
   *
   * A table compiled from `%%action` or read from a `%%decision-table` directive
   * is shown directly. A rule that is only a flowchart has no table of its own,
   * so it opens read-only — or, with `autoConvertFlowchart`, as the table it
   * describes when one can be read out of it. The original Mermaid stays behind
   * "Show EML".
   */
  const showModelTable = rule.sourceKind === "actions" || rule.sourceKind === "decision-table";
  const authoredFlowchart = !showModelTable && !!rule.sourceFlowchart;
  const table = authoredFlowchart
    ? autoConvertFlowchart && conversion.ok
      ? conversion.table
      : null
    : rule.table;

  // Once the rule is a graph, the table it started from is no longer its content, and
  // checking it reported an empty "Input reads no field" for a rule that was complete.
  const problems = useMemo(
    () => (table && !rule.jdmGraph ? validateDecisionTable(table) : []),
    [table, rule.jdmGraph]
  );
  return (
    <>
      <div className="mb-3 grid grid-cols-2 gap-3 lg:grid-cols-3">
        <label className="block">
          <span className="mb-1 block text-xs font-medium">Name</span>
          <input
            className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
            value={rule.title ?? rule.name}
            onChange={(event) =>
              onChange({ title: event.target.value, name: slugifyRuleName(event.target.value) })
            }
            placeholder="Sample expiry guard"
          />
        </label>

        <label className="block">
          <span className="mb-1 block text-xs font-medium">Entity</span>
          <select
            className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
            value={rule.entity}
            onChange={(event) => onChange({ entity: event.target.value })}
          >
            <option value="">Choose…</option>
            {entities.map((entity) => (
              <option key={entity.name} value={entity.name}>
                {entity.name}
              </option>
            ))}
          </select>
        </label>

        {showPriority && (
          <label className="block">
            <span className="mb-1 block text-xs font-medium">Priority</span>
            <input
              type="number"
              step={1}
              className="w-full rounded-md border border-border px-2 py-1.5 text-sm"
              value={rule.priority ?? 100}
              // Both runtimes store it as an integer; 2.5 would be rounded silently.
              onChange={(event) =>
                onChange({ priority: Math.trunc(Number(event.target.value)) || 0 })
              }
            />
          </label>
        )}
      </div>

      {table ? (
        <>
          {authoredFlowchart && (
            <div className="mb-3 rounded-lg border border-amber-300 bg-amber-50 px-3 py-2 text-xs text-amber-900">
              <p>
                This rule came from your model as a flowchart. It is shown here as the decision
                table it describes; editing it will save that table. The Mermaid is unchanged until
                then — open "Show EML" to read it.
              </p>
              {conversion.ok && conversion.notes.length > 0 && (
                <ul className="mt-1 list-disc pl-4">
                  {conversion.notes.map((note) => (
                    <li key={note}>{note}</li>
                  ))}
                </ul>
              )}
            </div>
          )}
          <Suspense
            fallback={
              <div className="py-8 text-center text-sm text-muted-foreground">Loading editor…</div>
            }
          >
            <GoRulesEditorPanel
              jdmGraph={rule.jdmGraph}
              table={table}
              entityFields={sampleFields}
              entityEnums={entityEnums}
              entityWorkflows={entityWorkflows}
              fieldTypes={fieldTypes}
              ruleName={slugifyRuleName(rule.title ?? rule.name)}
              entity={rule.entity}
              dryRun={dryRun}
              height={graphHeight}
              fieldsLoading={sampleFields.length === 0}
              sampleRecord={JSON.stringify(
                sampleRecord(sampleFields, entityEnums, fieldTypes),
                null,
                2
              )}
              onChange={(graphJson) =>
                onChange({ jdmGraph: graphJson, sourceFlowchart: undefined })
              }
            />
          </Suspense>
          {/* Drag handle — drag up to grow the try-it panel, down to shrink it */}
          <div
            role="separator"
            tabIndex={0}
            aria-label="Resize simulator panel"
            aria-orientation="horizontal"
            aria-valuemin={MIN_GRAPH}
            aria-valuemax={MAX_GRAPH}
            aria-valuenow={graphHeight}
            onMouseDown={startDrag}
            onKeyDown={resizeByKey}
            className="mt-2 flex cursor-row-resize select-none items-center justify-center rounded border border-dashed border-border py-0.5 text-muted-foreground hover:border-primary hover:text-primary"
            style={{ height: HANDLE_HEIGHT }}
          >
            <GripHorizontal className="h-3.5 w-3.5" />
          </div>
          <RuleTryIt
            dryRun={dryRun}
            entity={rule.entity}
            entityFields={sampleFields}
            entityEnums={entityEnums}
            fieldTypes={fieldTypes}
            height={tryItHeight}
            getGraph={() =>
              rule.jdmGraph ??
              JSON.stringify(tableToGraph(table, slugifyRuleName(rule.title ?? rule.name)))
            }
          />
        </>
      ) : (
        <div className="rounded-lg border border-amber-300 bg-amber-50 p-3">
          <div className="flex items-start gap-1.5 text-xs text-amber-900">
            <AlertCircle className="mt-0.5 h-3.5 w-3.5 shrink-0" />
            {conversion.ok ? (
              <p>
                This rule came from your model as a flowchart. It is saved exactly as it is here. It
                can also be read as a table of{" "}
                <strong>
                  {conversion.table.rules.length} row
                  {conversion.table.rules.length === 1 ? "" : "s"}
                </strong>{" "}
                that decides the same thing — convert it to edit it here.
              </p>
            ) : (
              <p>
                This rule came from your model as a flowchart, and it is saved exactly as it is
                here. It cannot be read as a table: {conversion.reason}
              </p>
            )}
          </div>

          <pre className="mt-2 max-h-72 overflow-auto rounded-md border border-amber-200 bg-white/70 p-3 font-mono text-[11px] leading-relaxed">
            {rule.sourceFlowchart}
          </pre>

          {conversion.ok ? (
            <>
              {conversion.notes.map((note) => (
                <p key={note} className="mt-2 text-[11.5px] text-amber-900">
                  {note}
                </p>
              ))}
              <button
                type="button"
                onClick={() => onChange({ sourceFlowchart: undefined, table: conversion.table })}
                className="mt-2 rounded-md border border-amber-400 bg-white px-3 py-1.5 text-sm font-medium text-amber-900"
              >
                Convert to a decision table
              </button>
              <p className="mt-1.5 text-[11.5px] text-amber-900/80">
                Nothing is written until you save, and the table is shown before then.
              </p>
            </>
          ) : (
            <>
              <button
                type="button"
                onClick={() =>
                  onChange({ sourceFlowchart: undefined, table: emptyDecisionTable() })
                }
                className="mt-2 rounded-md border border-amber-400 bg-white px-3 py-1.5 text-sm font-medium text-amber-900"
              >
                Start an empty table instead
              </button>
              <p className="mt-1.5 text-[11.5px] text-amber-900/80">
                This discards the flowchart above, so you would re-enter the logic by hand.
              </p>
            </>
          )}
        </div>
      )}

      {problems.length > 0 && (
        <ul className="mt-3 space-y-1 rounded-lg border border-amber-300 bg-amber-50 px-3 py-2 text-xs text-amber-900">
          {problems.map((problem) => (
            <li key={problem} className="flex items-start gap-1.5">
              <AlertCircle className="mt-0.5 h-3 w-3 shrink-0" />
              {problem}
            </li>
          ))}
        </ul>
      )}

      <button
        type="button"
        onClick={() => setShowSource((current) => !current)}
        className="mt-3 flex items-center gap-1.5 rounded-md border border-border px-3 py-1.5 text-sm font-medium"
      >
        <Code2 className="h-3.5 w-3.5" />
        {showSource ? "Hide" : "Show"} EML
      </button>

      {showSource && (
        <pre className="mt-2 max-h-56 overflow-auto rounded-lg border border-border bg-muted/40 p-3 font-mono text-[11px] leading-relaxed">
          {`%%rule ${slugifyRuleName(rule.title ?? rule.name)} on ${
            rule.entity || "<entity>"
          } event: ${rule.event} priority: ${rule.priority ?? 100}\n${
            rule.jdmGraph
              ? `%%jdm-graph ${rule.jdmGraph}`
              : (rule.sourceFlowchart ?? tableToEmlFlowchart(rule.table))
          }`}
        </pre>
      )}
    </>
  );
}

/**
 * The right-hand panel: how a step is set up, and what it actually did.
 *
 * Putting the last run's input and output directly under the fields that
 * produced them is the one idea worth taking from a canvas-style editor. The
 * question an author has while configuring a step is almost always "did that
 * do what I meant", and answering it in the same panel removes a trip to a
 * separate run view — along with the guessing that happens on the way back.
 */

import { useMemo } from "react";
import {
  type AutomationStep,
  type AvailableValue,
  type Condition,
  LOOP_MIN_PASSES,
  type Loop,
  OPERATORS,
  operatorArity,
  STEP_FIELDS,
  STEP_GLYPHS,
  STEP_HINTS,
  STEP_LABELS,
} from "../../lib/automation/model";
import { cn } from "../../lib/utils";

/* -------------------------------------------------------------------------- */
/*  Run output                                                                 */
/* -------------------------------------------------------------------------- */

export interface StepRunResult {
  status: "ok" | "failed" | "skipped";
  durationMs?: number;
  input?: Record<string, unknown>;
  output?: Record<string, unknown>;
  /** Plain-words summary of why the step produced what it did. */
  note?: string;
  error?: string;
  /** True when the step was edited after this run, so the result is out of date. */
  stale?: boolean;
}

function ValueRows({ values }: { values: Record<string, unknown> }) {
  const entries = Object.entries(values);
  if (entries.length === 0) {
    return <div className="px-3 py-1.5 text-xs text-muted-foreground">Nothing</div>;
  }
  return (
    <>
      {entries.map(([k, v]) => (
        <div
          key={k}
          className="flex gap-3 border-t border-border/60 px-3 py-1.5 text-xs first:border-t-0"
        >
          <span className="font-mono text-[11px] text-muted-foreground">{k}</span>
          <span className="ml-auto font-semibold tabular-nums">{formatValue(v)}</span>
        </div>
      ))}
    </>
  );
}

function formatValue(v: unknown): string {
  if (typeof v === "string") return `"${v}"`;
  if (v === null || v === undefined) return "—";
  return String(v);
}

function RunOutput({
  result,
  resultName,
  onRerun,
}: {
  result: StepRunResult;
  resultName: string;
  onRerun?: () => void;
}) {
  return (
    <section className="-mx-4 mt-1 border-t border-border bg-muted/40 px-4 py-4">
      <div className="mb-3 flex items-center gap-2">
        <span
          aria-hidden="true"
          className={cn(
            "grid h-[22px] w-[22px] place-items-center rounded-md border text-[11px]",
            result.status === "ok"
              ? "border-primary/30 bg-primary/10 text-primary"
              : result.status === "failed"
                ? "border-red-200 bg-red-50 text-red-600 dark:border-red-800 dark:bg-red-950/40 dark:text-red-400"
                : "border-border bg-muted text-muted-foreground"
          )}
        >
          {result.status === "ok" ? "✓" : result.status === "failed" ? "!" : "–"}
        </span>
        <h4 className="text-[10.5px] font-bold uppercase tracking-[0.09em] text-muted-foreground">
          What this step did
        </h4>
        <span className="ml-auto text-[11px] text-muted-foreground">
          last test run
          {typeof result.durationMs === "number" ? ` · ${result.durationMs} ms` : ""}
        </span>
      </div>

      {result.status === "failed" && result.error ? (
        <p className="mb-2 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700 dark:border-red-800 dark:bg-red-950/40 dark:text-red-300">
          {result.error}
        </p>
      ) : null}

      {result.input ? (
        <div className="mb-2 overflow-hidden rounded-lg border border-border bg-card">
          <div className="border-b border-border bg-muted/50 px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
            Went in
          </div>
          <ValueRows values={result.input} />
        </div>
      ) : null}

      {result.note ? (
        <p className="mb-2 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs text-emerald-800 dark:border-emerald-800 dark:bg-emerald-950/40 dark:text-emerald-300">
          {result.note}
        </p>
      ) : null}

      {result.output ? (
        <div className="mb-2 overflow-hidden rounded-lg border border-border bg-card">
          <div className="flex border-b border-border bg-muted/50 px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
            Came out
            {resultName ? <span className="ml-auto text-primary">as {resultName}</span> : null}
          </div>
          <ValueRows values={result.output} />
        </div>
      ) : null}

      {onRerun ? (
        <button
          type="button"
          onClick={onRerun}
          className="w-full rounded-lg border border-border bg-card py-2 text-xs font-semibold hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          Run this step again
        </button>
      ) : null}

      {result.stale ? (
        <p className="mt-2 flex gap-1.5 text-[11.5px] leading-snug text-amber-700 dark:text-amber-300">
          <span aria-hidden="true">⚠</span>
          <span>You changed this step since that run. Re-run to see what it does now.</span>
        </p>
      ) : null}
    </section>
  );
}

/* -------------------------------------------------------------------------- */
/*  Field primitives                                                           */
/* -------------------------------------------------------------------------- */

function Field({
  label,
  hint,
  children,
}: {
  label: string;
  hint?: React.ReactNode;
  children: React.ReactNode;
}) {
  // A real <label> wrapping the control, not a styled <span> beside it: without
  // it the selects announce as "combobox" with no name at all, which is the
  // difference between a usable panel and an unusable one on a screen reader.
  return (
    // the control is the `children` this wrapper renders inside the label.
    <label className="mb-3.5 block">
      <span className="mb-1.5 block text-[11px] font-semibold uppercase tracking-[0.06em] text-muted-foreground">
        {label}
      </span>
      {children}
      {hint ? (
        <p className="mt-1.5 text-[11.5px] leading-snug text-muted-foreground">{hint}</p>
      ) : null}
    </label>
  );
}

const inputClass =
  "w-full rounded-lg border border-input bg-card px-3 py-2 text-sm focus-visible:outline-none focus-visible:border-primary focus-visible:ring-[3px] focus-visible:ring-primary/10";

export function Ref({ children }: { children: React.ReactNode }) {
  return (
    <code className="rounded border border-border bg-muted px-1 py-0.5 font-mono text-[11px] text-primary">
      {children}
    </code>
  );
}

/* -------------------------------------------------------------------------- */
/*  Step inspector                                                             */
/* -------------------------------------------------------------------------- */

interface StepInspectorProps {
  step: AutomationStep;
  index: number;
  available: AvailableValue[];
  ruleTables: { id: string; name: string; rowCount: number; outputs: string[] }[];
  entities: string[];
  fieldsFor: (entity: string) => string[];
  run?: StepRunResult;
  onChange: (next: AutomationStep) => void;
  onRerun?: () => void;
  onOpenRuleTable?: (name: string) => void;
  /** The record type the automation runs on — what a write naming none acts on. */
  ownEntity?: string;
}

export function StepInspector({
  step,
  index,
  available,
  ruleTables,
  entities,
  fieldsFor,
  run,
  onChange,
  onRerun,
  onOpenRuleTable,
  ownEntity = "",
}: StepInspectorProps) {
  const setProp = (key: string, value: string) =>
    onChange({ ...step, props: { ...step.props, [key]: value } });

  // An update or delete that names no record type acts on the record the
  // automation runs on — the executor's reading, the checker's, and the one the
  // model's own sagas are written in. So that is what the picker shows, and
  // choosing it stores no entity: naming it drew EML265 ("targets FeeInvoice
  // without saying which row") for a write that was never ambiguous.
  const writesOwnRecord = step.type === "UpdateEntity" || step.type === "DeleteEntity";
  const shownEntity = step.props.entity || (writesOwnRecord ? ownEntity : "");
  const setEntity = (value: string) => {
    if (writesOwnRecord && value === ownEntity) {
      const props = { ...step.props };
      delete props.entity;
      onChange({ ...step, props });
    } else setProp("entity", value);
  };

  const table = useMemo(
    () => ruleTables.find((t) => t.name === step.props.ruleTable),
    [ruleTables, step.props.ruleTable]
  );

  const fields = STEP_FIELDS[step.type] ?? [];

  return (
    <div className="flex h-full flex-col">
      <header className="flex items-center gap-3 px-4 py-3.5">
        <span
          aria-hidden="true"
          className="grid h-[30px] w-[30px] shrink-0 place-items-center rounded-lg border border-primary/30 bg-primary/10 text-sm text-primary"
        >
          {STEP_GLYPHS[step.type]}
        </span>
        <div>
          <span className="block text-[10px] font-bold uppercase tracking-[0.1em] text-primary">
            Step {index + 1} · Then do this
          </span>
          <h3 className="text-[15px] font-bold">{STEP_LABELS[step.type]}</h3>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto px-4">
        <p className="mb-4 text-xs leading-snug text-muted-foreground">{STEP_HINTS[step.type]}</p>

        {/* One list per step, not per field: every input that offers references
            points at this id, and emitting it only under some fields left the
            others with an autocomplete that quietly did nothing. */}
        <datalist id={`vals-${step.id}`}>
          {available.map((v) => (
            <option key={v.path} value={`{{${v.path}}}`} />
          ))}
        </datalist>

        {fields.includes("ruleTable") ? (
          <Field
            label="Rule table"
            hint={
              table ? (
                <>
                  {table.rowCount} rows · decides{" "}
                  {table.outputs.map((o, i) => (
                    <span key={o}>
                      {i > 0 ? " and " : ""}
                      <Ref>{o}</Ref>
                    </span>
                  ))}
                  .{" "}
                  {onOpenRuleTable ? (
                    <button
                      type="button"
                      onClick={() => onOpenRuleTable(table.name)}
                      className="font-semibold text-primary hover:underline"
                    >
                      Open table →
                    </button>
                  ) : null}
                </>
              ) : (
                "Pick the table this step should ask."
              )
            }
          >
            <select
              className={inputClass}
              value={step.props.ruleTable ?? ""}
              onChange={(e) => setProp("ruleTable", e.target.value)}
            >
              <option value="">Choose a rule table…</option>
              {ruleTables.map((t) => (
                <option key={t.id} value={t.name}>
                  {t.name}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("entity") ? (
          <Field label="Record type">
            <select
              className={inputClass}
              value={shownEntity}
              onChange={(e) => setEntity(e.target.value)}
            >
              <option value="">Choose a record type…</option>
              {entities.map((e) => (
                <option key={e} value={e}>
                  {e}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("values") ? (
          <Field
            label="Columns to set"
            hint={
              <>
                One <code className="font-mono text-[11px]">column: value</code> per line. A value
                can be a reference to an earlier step, like <Ref>{"{{tier.discount_pct}}"}</Ref>.
              </>
            }
          >
            <textarea
              className={cn(inputClass, "min-h-[76px] font-mono text-xs")}
              value={step.props.values ?? ""}
              onChange={(e) => setProp("values", e.target.value)}
              placeholder={"status: open\nraised_by: {{order.id}}"}
            />
          </Field>
        ) : null}

        {fields.includes("target") ? (
          <Field
            label="Which record"
            hint={
              step.type === "UpdateEntity" ? (
                <>
                  Only for another record type: a reference from an earlier step like{" "}
                  <Ref>{"{{invoiceId}}"}</Ref>, or the column on that record pointing back to this
                  one, like <code className="font-mono text-[11px]">order_id</code>. Leave it empty
                  to write this record.
                </>
              ) : (
                <>
                  The record to delete, usually a reference from an earlier step —{" "}
                  <Ref>{"{{invoiceId}}"}</Ref>.
                </>
              )
            }
          >
            <input
              className={inputClass}
              value={step.props.target ?? ""}
              onChange={(e) => setProp("target", e.target.value)}
              list={`vals-${step.id}`}
            />
          </Field>
        ) : null}

        {fields.includes("field") ? (
          <Field label="Field to write">
            <select
              className={inputClass}
              value={step.props.field ?? ""}
              onChange={(e) => setProp("field", e.target.value)}
            >
              <option value="">Choose a field…</option>
              {fieldsFor(shownEntity).map((f) => (
                <option key={f} value={f}>
                  {f}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("value") ? (
          <Field
            label="New value"
            hint={
              <>
                A fixed value, or a reference to an earlier step like{" "}
                <Ref>{"{{tier.discount_pct}}"}</Ref>.
              </>
            }
          >
            <input
              className={inputClass}
              value={step.props.value ?? ""}
              onChange={(e) => setProp("value", e.target.value)}
              list={`vals-${step.id}`}
              placeholder="high"
            />
          </Field>
        ) : null}

        {fields.includes("operation") ? (
          <Field label="Operation">
            <select
              className={inputClass}
              value={step.props.operation ?? "set"}
              onChange={(e) => setProp("operation", e.target.value)}
            >
              {["set", "copy", "add", "subtract", "multiply", "divide"].map((op) => (
                <option key={op} value={op}>
                  {op}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("left") ? (
          <Field label="Value to work from">
            <input
              className={inputClass}
              value={step.props.left ?? ""}
              onChange={(e) => setProp("left", e.target.value)}
              list={`vals-${step.id}`}
            />
          </Field>
        ) : null}

        {fields.includes("right") ? (
          <Field label="And this value" hint="Leave empty when the operation only needs one value.">
            <input
              className={inputClass}
              value={step.props.right ?? ""}
              onChange={(e) => setProp("right", e.target.value)}
              list={`vals-${step.id}`}
            />
          </Field>
        ) : null}

        {fields.includes("method") ? (
          <Field label="Method">
            <select
              className={inputClass}
              value={step.props.method ?? "POST"}
              onChange={(e) => setProp("method", e.target.value)}
            >
              {["POST", "PUT", "PATCH", "GET", "DELETE"].map((m) => (
                <option key={m} value={m}>
                  {m}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("url") ? (
          <Field label="URL">
            <input
              className={inputClass}
              value={step.props.url ?? ""}
              onChange={(e) => setProp("url", e.target.value)}
              placeholder="https://example.com/hooks/orders"
            />
          </Field>
        ) : null}

        {fields.includes("body") ? (
          <Field
            label="Body"
            hint={
              <>
                JSON. References like <Ref>{"{{order.id}}"}</Ref> are filled in before sending.
              </>
            }
          >
            <textarea
              className={cn(inputClass, "min-h-[76px] font-mono text-xs")}
              value={step.props.body ?? ""}
              onChange={(e) => setProp("body", e.target.value)}
            />
          </Field>
        ) : null}

        <Field
          label="Save the answer as"
          hint={
            step.resultName ? (
              <>
                Later steps can use <Ref>{`{{${step.resultName}}}`}</Ref>.
              </>
            ) : (
              "Leave empty if no later step needs this step's result."
            )
          }
        >
          <input
            className={inputClass}
            value={step.resultName}
            onChange={(e) => onChange({ ...step, resultName: e.target.value })}
            placeholder="tier"
          />
        </Field>

        {run ? <RunOutput result={run} resultName={step.resultName} onRerun={onRerun} /> : null}
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/*  Condition inspector                                                        */
/* -------------------------------------------------------------------------- */

export function ConditionInspector({
  condition,
  available,
  onChange,
}: {
  condition: Condition;
  available: AvailableValue[];
  onChange: (next: Condition) => void;
}) {
  const needsValue = operatorArity(condition.operator) === 1;

  return (
    <div className="flex h-full flex-col">
      <header className="flex items-center gap-3 px-4 py-3.5">
        <span
          aria-hidden="true"
          className="grid h-[30px] w-[30px] shrink-0 place-items-center rounded-lg border border-blue-200 bg-blue-50 text-sm text-blue-600 dark:border-blue-800 dark:bg-blue-950/40 dark:text-blue-400"
        >
          ◇
        </span>
        <div>
          <span className="block text-[10px] font-bold uppercase tracking-[0.1em] text-blue-600 dark:text-blue-400">
            Only continue if
          </span>
          <h3 className="text-[15px] font-bold">A check</h3>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto px-4">
        <p className="mb-4 text-xs leading-snug text-muted-foreground">
          Every check must pass. To run on either of two cases, build two automations — each one
          then reports its own run history.
        </p>

        <Field label="Field to look at">
          <select
            className={inputClass}
            value={condition.field}
            onChange={(e) => onChange({ ...condition, field: e.target.value })}
          >
            <option value="">Choose a field…</option>
            {available.map((v) => (
              <option key={v.path} value={v.path}>
                {v.path}
              </option>
            ))}
          </select>
        </Field>

        <Field label="Test">
          <select
            className={inputClass}
            value={condition.operator}
            onChange={(e) => onChange({ ...condition, operator: e.target.value })}
          >
            {OPERATORS.map((op) => (
              <option key={op.id} value={op.id}>
                {op.label}
              </option>
            ))}
          </select>
        </Field>

        {needsValue ? (
          <Field label="Value" hint="A fixed value, or another field to compare against.">
            <input
              className={inputClass}
              value={condition.value}
              onChange={(e) => onChange({ ...condition, value: e.target.value })}
              placeholder="1000"
            />
          </Field>
        ) : null}
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/*  Loop inspector                                                             */
/* -------------------------------------------------------------------------- */

/**
 * The panel for a repeat.
 *
 * It edits one thing — the check that ends the loop — so most of the panel is
 * spent explaining the consequences instead. A repeat is the only construct in
 * the builder that can hang a request, and the place to say so is where someone
 * is deciding what to check, not in help they would have to go looking for.
 */
export function LoopInspector({
  loop,
  stepCount,
  available,
  onChange,
}: {
  loop: Loop;
  stepCount: number;
  available: AvailableValue[];
  onChange: (next: Loop) => void;
}) {
  const needsValue = operatorArity(loop.condition.operator) === 1;
  const set = (patch: Partial<Condition>) =>
    onChange({ ...loop, condition: { ...loop.condition, ...patch } });

  return (
    <div className="flex h-full flex-col">
      <header className="flex items-center gap-3 px-4 py-3.5">
        <span
          aria-hidden="true"
          className="grid h-[30px] w-[30px] shrink-0 place-items-center rounded-lg border border-teal-200 bg-teal-50 text-sm text-teal-700 dark:border-teal-800 dark:bg-teal-950/40 dark:text-teal-300"
        >
          ↻
        </span>
        <div>
          <span className="block text-[10px] font-bold uppercase tracking-[0.1em] text-teal-700 dark:text-teal-300">
            Keep repeating
          </span>
          <h3 className="text-[15px] font-bold">A repeat</h3>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto px-4">
        <p className="mb-4 text-xs leading-snug text-muted-foreground">
          The {stepCount === 1 ? "step" : `${stepCount} steps`} inside run over and over while this
          check passes. It is re-checked before every pass, so something inside the repeat has to
          change what it looks at — otherwise it never stops.
        </p>

        <Field label="Field to look at">
          <select
            className={inputClass}
            value={loop.condition.field}
            onChange={(e) => set({ field: e.target.value })}
          >
            <option value="">Choose a field…</option>
            {available.map((v) => (
              <option key={v.path} value={v.path}>
                {v.path}
              </option>
            ))}
          </select>
        </Field>

        <Field label="Keep going while">
          <select
            className={inputClass}
            value={loop.condition.operator}
            onChange={(e) => set({ operator: e.target.value })}
          >
            {OPERATORS.map((op) => (
              <option key={op.id} value={op.id}>
                {op.label}
              </option>
            ))}
          </select>
        </Field>

        {needsValue ? (
          <Field label="Value" hint="A fixed value, or another field to compare against.">
            <input
              className={inputClass}
              value={loop.condition.value}
              onChange={(e) => set({ value: e.target.value })}
              placeholder="5"
            />
          </Field>
        ) : null}

        <Field
          label="Give up after (required)"
          hint="How many passes is obviously too many for this loop? There is no default — only you know what this work should cost."
        >
          <input
            className={inputClass}
            inputMode="numeric"
            value={loop.maxPasses}
            onChange={(e) => onChange({ ...loop, maxPasses: e.target.value })}
            placeholder="e.g. 10"
            aria-invalid={!loop.maxPasses.trim() || Number(loop.maxPasses) < LOOP_MIN_PASSES}
          />
        </Field>

        <div className="mb-4 rounded-lg border border-teal-200 bg-teal-50/60 p-3 dark:border-teal-800 dark:bg-teal-950/40">
          <p className="text-[11.5px] font-semibold text-teal-800 dark:text-teal-300">
            Inside the repeat you can use {`{{${loop.id}.iteration}}`}
          </p>
          <p className="mt-1 text-[11.5px] leading-snug text-teal-800/80 dark:text-teal-300">
            The pass number, counting from 1. Handy for writing an attempt count, or for building a
            value that changes each time round.
          </p>
        </div>

        <div className="mb-4 rounded-lg border border-amber-200 bg-amber-50/60 p-3 dark:border-amber-800 dark:bg-amber-950/40">
          <p className="text-[11.5px] font-semibold text-amber-900 dark:text-amber-200">
            If the check never fails, the run is stopped at{" "}
            {loop.maxPasses.trim() ? `${loop.maxPasses} passes` : "the limit you set"}
          </p>
          <p className="mt-1 text-[11.5px] leading-snug text-amber-900/80 dark:text-amber-200">
            An automation runs inside the save that triggered it, so a repeat that cannot end holds
            the record open. Hitting the limit marks the whole run failed rather than letting it
            look like it finished.
          </p>
        </div>
      </div>
    </div>
  );
}

/**
 * One rung of the ladder.
 *
 * Every part of an automation is the same shape on screen — a coloured glyph, a
 * kicker naming which of the three parts it is, and the clause in plain words.
 * Keeping trigger, check and step identical in form is what lets someone read
 * the whole automation top to bottom without learning three card layouts.
 */

import { cn } from "../../lib/utils";

/**
 * `action` rather than `then` because an object keyed `then` is a thenable, and
 * `await`ing or dynamically importing anything holding it behaves oddly. The
 * label the author reads is still "Then do this".
 */
export type LadderKind = "when" | "if" | "action" | "loop";

const KIND_STYLES: Record<LadderKind, { icon: string; kicker: string; label: string }> = {
  when: {
    icon: "bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-950/40 dark:text-amber-300 dark:border-amber-800",
    kicker: "text-amber-700 dark:text-amber-300",
    label: "When this happens",
  },
  if: {
    icon: "bg-blue-50 text-blue-600 border-blue-200 dark:bg-blue-950/40 dark:text-blue-400 dark:border-blue-800",
    kicker: "text-blue-600 dark:text-blue-400",
    label: "Only continue if",
  },
  action: {
    icon: "bg-primary/10 text-primary border-primary/30",
    kicker: "text-primary",
    label: "Then do this",
  },
  // Teal rather than another shade of the accent: a repeat is control flow, not
  // a fourth kind of action, and it should not read as one at a glance.
  loop: {
    icon: "bg-teal-50 text-teal-700 border-teal-200 dark:bg-teal-950/40 dark:text-teal-300 dark:border-teal-800",
    kicker: "text-teal-700 dark:text-teal-300",
    label: "Keep repeating",
  },
};

interface LadderCardProps {
  kind: LadderKind;
  glyph: string;
  /** The clause, already worded. Rendered as-is so the model owns the wording. */
  title: React.ReactNode;
  /** Shown after the kicker, e.g. "· step 2". */
  ordinal?: string;
  selected?: boolean;
  problem?: string;
  onSelect?: () => void;
  onRemove?: () => void;
}

export function LadderCard({
  kind,
  glyph,
  title,
  ordinal,
  selected = false,
  problem,
  onSelect,
  onRemove,
}: LadderCardProps) {
  const style = KIND_STYLES[kind];

  return (
    <div
      className={cn(
        "w-full rounded-xl border bg-card px-4 py-3 text-left shadow-sm transition-colors",
        selected
          ? "border-primary ring-[3px] ring-primary/10"
          : "border-border hover:border-primary/40",
        problem && !selected && "border-amber-300 dark:border-amber-800"
      )}
    >
      <div className="flex items-center gap-3">
        <button
          type="button"
          onClick={onSelect}
          aria-current={selected ? "true" : undefined}
          className="flex flex-1 items-center gap-3 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 rounded-md"
        >
          <span
            aria-hidden="true"
            className={cn(
              "grid h-[30px] w-[30px] shrink-0 place-items-center rounded-lg border text-sm",
              style.icon
            )}
          >
            {glyph}
          </span>
          <span className="min-w-0">
            <span
              className={cn("block text-[10px] font-bold uppercase tracking-[0.1em]", style.kicker)}
            >
              {style.label}
              {ordinal ? <span className="text-muted-foreground"> {ordinal}</span> : null}
            </span>
            <span className="mt-0.5 block text-sm">{title}</span>
          </span>
        </button>

        {onRemove ? (
          <button
            type="button"
            onClick={onRemove}
            aria-label="Remove this"
            className="shrink-0 rounded-md px-2 py-1 text-muted-foreground hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
          >
            ✕
          </button>
        ) : null}
      </div>

      {problem ? (
        <p className="mt-2 pl-[42px] text-xs text-amber-700 dark:text-amber-300">{problem}</p>
      ) : null}
    </div>
  );
}

/**
 * A token inside a card's clause.
 *
 * `value` tokens are the parts the author chose — a literal, a name they gave a
 * result — and carry the accent so the editable bits of the sentence stand out
 * from the fixed words around them.
 */
export function Token({ children, value = false }: { children: React.ReactNode; value?: boolean }) {
  return (
    <span
      className={cn(
        "mx-0.5 inline-block rounded-md border px-1.5 py-0.5 font-semibold",
        value
          ? "border-primary/30 bg-primary/5 text-primary"
          : "border-border bg-muted text-foreground"
      )}
    >
      {children}
    </span>
  );
}

/**
 * The bracket drawn around the steps a loop repeats.
 *
 * A repeat is the one place the ladder stops being a flat list, so it needs to
 * look like containment rather than another rung: the steps inside are indented
 * behind a rail, and the rail carries the count of what it holds. Without the
 * frame the only clue that three steps repeat would be a word on a card above
 * them, which reads as a sequence, not a cycle.
 */
export function LoopFrame({
  children,
  stepCount,
  problem,
}: {
  children: React.ReactNode;
  stepCount: number;
  problem?: boolean;
}) {
  return (
    <div
      className={cn(
        "relative rounded-xl border-l-[3px] bg-teal-50/30 py-2 pl-4 pr-1 dark:bg-teal-950/40",
        problem ? "border-l-amber-400" : "border-l-teal-300"
      )}
    >
      {children}
      <p className="mt-2 pl-1 text-[11px] text-teal-700 dark:text-teal-300">
        ↻ {stepCount === 1 ? "This step repeats" : `These ${stepCount} steps repeat`} until the
        check above fails
      </p>
    </div>
  );
}

/**
 * The connector between two cards, with the add button on it.
 *
 * The `+` lives on the rung rather than in a toolbar because that is where the
 * thing being added will end up — you point at the gap you want filled.
 */
export function LadderRung({
  onAdd,
  active = false,
  /** Overridden in hook workflows, where a rung adds a lifecycle step. */
  label,
}: {
  onAdd: () => void;
  active?: boolean;
  label?: string;
}) {
  return (
    <div className="relative h-6 w-0.5 bg-border" aria-hidden={false}>
      <button
        type="button"
        onClick={onAdd}
        aria-label={label ?? "Add a condition or an action here"}
        className={cn(
          "absolute left-1/2 top-1/2 grid h-[22px] w-[22px] -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full border text-xs leading-none transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2",
          active
            ? "border-primary bg-primary text-primary-foreground"
            : "border-border bg-card text-muted-foreground hover:border-primary hover:text-primary"
        )}
      >
        +
      </button>
    </div>
  );
}

/**
 * The left rail, paged.
 *
 * Lists are fetched 200 at a time and the rail asks for the next page only when
 * someone presses for it. Loading every automation up front was fine with a
 * dozen and stopped painting with a few thousand — and the person with the most
 * automations is exactly the one who needs the rail to work.
 *
 * The count is always shown, so "200 of 1,340" tells you there is more without
 * needing to scroll to the bottom to find out.
 */

import { cn } from "../../lib/utils";

export const PAGE_SIZE = 200;

export interface RailItem {
  id: string;
  title: string;
  subtitle: string;
  state: "live" | "draft" | "paused";
}

export interface RailSectionProps {
  heading: string;
  items: RailItem[];
  /** How many exist in total, when the server said. */
  total?: number;
  selectedId?: string;
  onSelect: (id: string) => void;
  onLoadMore?: () => void;
  loadingMore?: boolean;
  emptyText?: string;
}

export function RailSection({
  heading,
  items,
  total,
  selectedId,
  onSelect,
  onLoadMore,
  loadingMore = false,
  emptyText = "None yet.",
}: RailSectionProps) {
  const knownTotal = total ?? items.length;
  const hasMore = items.length < knownTotal;

  return (
    <>
      <h2 className="flex items-baseline gap-2 px-4 pb-1.5 pt-4 text-[11px] font-semibold uppercase tracking-[0.07em] text-muted-foreground">
        {heading}
        {knownTotal > 0 ? (
          <span className="font-normal tabular-nums">
            {items.length < knownTotal
              ? `${items.length.toLocaleString()} of ${knownTotal.toLocaleString()}`
              : knownTotal.toLocaleString()}
          </span>
        ) : null}
      </h2>

      {items.length === 0 ? (
        <p className="px-4 pb-2 text-xs text-muted-foreground">{emptyText}</p>
      ) : null}

      {items.map((item) => (
        <button
          key={item.id}
          type="button"
          onClick={() => onSelect(item.id)}
          aria-current={selectedId === item.id ? "page" : undefined}
          className={cn(
            "mx-2 flex items-start gap-2.5 rounded-lg px-2.5 py-2 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary",
            selectedId === item.id ? "bg-primary/10" : "hover:bg-muted"
          )}
        >
          <span
            aria-hidden="true"
            className={cn(
              "mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full",
              item.state === "live"
                ? "bg-emerald-500"
                : item.state === "draft"
                  ? "bg-amber-500"
                  : "bg-neutral-400"
            )}
          />
          <span className="min-w-0">
            <span
              className={cn(
                "block truncate text-[13px]",
                selectedId === item.id && "font-semibold"
              )}
            >
              {item.title}
            </span>
            <span className="block truncate text-[11.5px] text-muted-foreground">
              {item.subtitle}
            </span>
          </span>
        </button>
      ))}

      {hasMore && onLoadMore ? (
        <button
          type="button"
          onClick={onLoadMore}
          disabled={loadingMore}
          className="mx-2 mt-1 rounded-lg border border-dashed border-border px-2.5 py-2 text-[12.5px] font-semibold text-muted-foreground hover:border-primary/50 hover:text-primary disabled:opacity-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          {loadingMore
            ? "Loading…"
            : `Show ${Math.min(PAGE_SIZE, knownTotal - items.length).toLocaleString()} more`}
        </button>
      ) : null}
    </>
  );
}

/**
 * A rule table: the conditions on the left, the answer on the right.
 *
 * Rows are read top to bottom and the first one that fits wins — except in a
 * `collect` table, which is what `%%action` compiles to, where every row that
 * fits runs. Under `first` that ordering is the whole semantics, so the editor
 * makes it visible — rows are numbered,
 * draggable, and the catch-all is pinned last and worded as "Otherwise" rather
 * than left as a row of empty cells the author has to recognise.
 *
 * The two panels underneath answer the questions a table always raises: what
 * does it say for this input, and is there an input it says nothing for.
 */

import { useMemo, useState } from "react";
import { cn } from "../../lib/utils";
import {
  type DecisionColumn,
  type DecisionRow,
  type DecisionTable,
  evaluateExpression,
  expressionFields,
  getColumnOptions,
  KNOWN_OUTPUT_FIELDS,
  newRowId,
} from "../../lib/workflow/bpmn-model";

const cellClass =
  "w-full min-w-[80px] rounded-md border border-input bg-card px-2 py-1.5 text-[13px] focus-visible:outline-none focus-visible:border-primary focus-visible:ring-[3px] focus-visible:ring-primary/10";

/* -------------------------------------------------------------------------- */
/*  Evaluation — the same first-match rule the engine applies                  */
/* -------------------------------------------------------------------------- */

export interface TableTestResult {
  /** The first row that fits — under `first`, the answer. */
  rowIndex: number | null;
  outputs: Record<string, string>;
  /** Every row that fits, in order. Under `collect` each of them runs. */
  matches: Array<{ rowIndex: number; outputs: Record<string, string> }>;
}

/**
 * Which row fits, given some values.
 *
 * Deliberately a small subset of the expression language: `=`, `>`, `>=`, `<`,
 * `<=`, `!=`, and a bare value meaning equality. A blank cell means "any". This
 * runs in the browser so the author gets an answer while typing; the engine
 * remains the authority at run time, and anything this cannot parse is treated
 * as not matching rather than as matching by accident.
 */
export function evaluateTable(
  table: DecisionTable,
  values: Record<string, string>
): TableTestResult {
  const matches: TableTestResult["matches"] = [];
  for (let i = 0; i < table.rules.length; i++) {
    const row = table.rules[i];
    if (!row) continue;
    const fits = table.inputs.every((col) => {
      const cell = (row[col.id] ?? "").trim();
      if (!cell) return true;
      // An input with no field holds whole-record checks, as `%%action`
      // writes them: `status == "withdrawn" and withdrawn_on == null`.
      if (!col.field.trim()) {
        const verdict = evaluateExpression(cell, values);
        if (verdict !== undefined) return verdict;
      }
      return cellMatches(cell, values[col.field] ?? "");
    });
    if (!fits) continue;
    const outputs: Record<string, string> = {};
    for (const col of table.outputs) outputs[col.field || col.name] = unquote(row[col.id] ?? "");
    matches.push({ rowIndex: i, outputs });
    if (table.hitPolicy !== "collect") break;
  }
  const first = matches[0];
  return { rowIndex: first?.rowIndex ?? null, outputs: first?.outputs ?? {}, matches };
}

function cellMatches(cell: string, typed: string): boolean {
  const m = cell.match(/^\s*(>=|<=|!=|=|>|<)?\s*(.+)$/);
  if (!m) return false;
  const op = m[1] ?? "=";
  const raw = unquote((m[2] ?? "").trim());
  // The cell is unquoted, so the value typed to test it must be too.
  const value = unquote(typed);

  const a = Number(value);
  const b = Number(raw);
  const numeric = !Number.isNaN(a) && !Number.isNaN(b) && value.trim() !== "";

  switch (op) {
    case "=":
      return numeric ? a === b : value === raw;
    case "!=":
      return numeric ? a !== b : value !== raw;
    case ">":
      return numeric && a > b;
    case ">=":
      return numeric && a >= b;
    case "<":
      return numeric && a < b;
    case "<=":
      return numeric && a <= b;
    default:
      return false;
  }
}

function unquote(s: string): string {
  const t = s.trim();
  if (t.length >= 2 && (t.startsWith('"') || t.startsWith("'"))) {
    const q = t[0] as string;
    if (t.endsWith(q)) return t.slice(1, -1);
  }
  return t;
}

/* -------------------------------------------------------------------------- */
/*  Coverage — the two things that silently break a table                      */
/* -------------------------------------------------------------------------- */

export interface CoverageNote {
  level: "ok" | "warn";
  message: string;
}

/**
 * Report gaps and shadowed rows.
 *
 * A gap means some input reaches no row and the step quietly produces nothing.
 * A shadowed row means an earlier row already covers everything a later one
 * does, so the later row can never fire — almost always a reordering mistake
 * rather than an intention.
 */
export function checkCoverage(table: DecisionTable): CoverageNote[] {
  const notes: CoverageNote[] = [];
  // Under `collect` every row that fits runs. A row with no check is not a
  // safety net there — it runs on every record, which is worth saying loudly.
  if (table.hitPolicy === "collect") {
    const blank = table.rules.findIndex((row) =>
      table.inputs.every((c) => !(row[c.id] ?? "").trim())
    );
    return [
      blank >= 0
        ? {
            level: "warn",
            message: `Row ${blank + 1} has no check, so its action runs on every record.`,
          }
        : {
            level: "ok",
            message:
              "Each row runs on its own when its check fits. A record that no row fits passes untouched.",
          },
    ];
  }
  const hasCatchAll = table.rules.some((row) =>
    table.inputs.every((c) => !(row[c.id] ?? "").trim())
  );

  notes.push(
    hasCatchAll
      ? { level: "ok", message: "Every combination of inputs reaches a row. No gaps." }
      : {
          level: "warn",
          message:
            "No catch-all row. If nothing fits, this table returns no answer and the step produces nothing. Add a row with every check left blank.",
        }
  );

  for (let i = 0; i < table.rules.length; i++) {
    for (let j = i + 1; j < table.rules.length; j++) {
      const earlier = table.rules[i];
      const later = table.rules[j];
      if (!earlier || !later) continue;
      const shadowed = table.inputs.every((c) => {
        const e = (earlier[c.id] ?? "").trim();
        const l = (later[c.id] ?? "").trim();
        return !e || e === l;
      });
      if (shadowed) {
        notes.push({
          level: "warn",
          message: `Row ${i + 1} already covers everything row ${j + 1} does, so row ${j + 1} can never fire. Reorder if that is not what you meant.`,
        });
        return notes;
      }
    }
  }

  return notes;
}

/* -------------------------------------------------------------------------- */
/*  Editor                                                                     */
/* -------------------------------------------------------------------------- */

export interface RuleTableEditorProps {
  name: string;
  table: DecisionTable;
  onChange: (next: DecisionTable) => void;
  /** Automations that look this table up, so a change's blast radius is visible. */
  usedBy?: { name: string; where: string }[];
  /**
   * The fields an input column may read. A plain string is its own label; the
   * generated application passes `{ value, label }` — the key the engine reads
   * as the value, the field's label from the window as what is shown.
   */
  entityFields?: Array<string | { value: string; label: string }>;
}

export function RuleTableEditor({
  name,
  table,
  onChange,
  usedBy = [],
  entityFields = [],
}: RuleTableEditorProps) {
  const [testValues, setTestValues] = useState<Record<string, string>>({});

  const result = useMemo(() => evaluateTable(table, testValues), [table, testValues]);
  const coverage = useMemo(() => checkCoverage(table), [table]);
  const fieldOptions = useMemo(
    () => entityFields.map((f) => (typeof f === "string" ? { value: f, label: f } : f)),
    [entityFields]
  );
  /** What a field key is shown as: its label, when the caller gave one. */
  const fieldLabel = (key: string) => fieldOptions.find((o) => o.value === key)?.label ?? key;
  const inputLabel = (c: DecisionColumn) => (c.field ? fieldLabel(c.field) : c.name);
  // `%%action` compiles to a `collect` table: every row that fits runs, so a
  // blank row is not an "otherwise" and the order does not pick a winner.
  const collect = table.hitPolicy === "collect";
  // A whole-record input is tested through the fields its checks read.
  const testFields = useMemo(() => {
    const read = expressionFields(table);
    const own = table.inputs.filter((c) => c.field.trim() || read.length === 0);
    const label = (key: string) => fieldOptions.find((o) => o.value === key)?.label ?? key;
    return [
      ...own.map((c) => ({ key: c.field, label: c.field ? label(c.field) : c.name })),
      ...read.map((f) => ({ key: f, label: label(f) })),
    ];
  }, [table, fieldOptions]);

  const setCell = (rowIndex: number, colId: string, value: string) => {
    const rules = table.rules.map((r, i) => (i === rowIndex ? { ...r, [colId]: value } : r));
    onChange({ ...table, rules });
  };

  const addRow = () => {
    const row: DecisionRow = { _id: newRowId() };
    for (const c of [...table.inputs, ...table.outputs]) row[c.id] = "";
    onChange({ ...table, rules: [...table.rules, row] });
  };

  const removeRow = (index: number) =>
    onChange({ ...table, rules: table.rules.filter((_, i) => i !== index) });

  const moveRow = (index: number, delta: number) => {
    const to = index + delta;
    if (to < 0 || to >= table.rules.length) return;
    const rules = [...table.rules];
    const [moved] = rules.splice(index, 1);
    if (moved) rules.splice(to, 0, moved);
    onChange({ ...table, rules });
  };

  const addColumn = (side: "inputs" | "outputs") => {
    const prefix = side === "inputs" ? "i" : "o";
    const col: DecisionColumn = {
      id: `${prefix}${Date.now().toString(36)}`,
      name: side === "inputs" ? "New input" : "New outcome",
      field: "",
    };
    onChange({ ...table, [side]: [...table[side], col] });
  };

  const setColumn = (side: "inputs" | "outputs", id: string, patch: Partial<DecisionColumn>) =>
    onChange({
      ...table,
      [side]: table[side].map((c) => (c.id === id ? { ...c, ...patch } : c)),
    });

  const isCatchAll = (row: DecisionRow) => table.inputs.every((c) => !(row[c.id] ?? "").trim());
  const lastCatchAllIndex = (() => {
    if (collect) return -1;
    for (let i = table.rules.length - 1; i >= 0; i--) {
      // Narrowed rather than asserted: noUncheckedIndexedAccess types this as
      // possibly undefined, and the assertion was the file's only lint warning.
      const row = table.rules[i];
      if (row && isCatchAll(row)) return i;
    }
    return -1;
  })();

  return (
    <div className="flex-1 overflow-y-auto bg-muted/30 px-7 py-6">
      <div className="flex items-center gap-3">
        <h1 className="text-xl font-bold tracking-tight">{name}</h1>
        {usedBy.length > 0 ? (
          <span className="rounded-full border border-border bg-muted px-2.5 py-1 text-[11px] font-semibold text-muted-foreground">
            Used by {usedBy.length} automation{usedBy.length === 1 ? "" : "s"}
          </span>
        ) : null}
      </div>
      <p className="mb-4 mt-1 text-[13px] text-muted-foreground">
        {collect
          ? "Every row whose check fits runs its action. Rows are not alternatives, and their order does not change which ones run."
          : "Rows are read top to bottom. The first row where every check fits is the answer."}
      </p>

      {/* the table's declaration, as a sentence */}
      <div className="mb-4 rounded-xl border border-border bg-card px-4 py-3.5 text-[15px] leading-loose">
        Given{" "}
        {table.inputs.map((c, i) => (
          <span key={c.id}>
            {i > 0 ? " and " : ""}
            {collect && !c.field ? (
              // Its cells are whole-record checks; giving it a field would
              // turn each into an equality test against that one field.
              <b className="mx-0.5">the record</b>
            ) : entityFields.length > 0 ? (
              <select
                aria-label={`Input ${i + 1} field`}
                value={c.field}
                onChange={(e) => setColumn("inputs", c.id, { field: e.target.value })}
                className="mx-0.5 w-[9.5rem] rounded-md border border-border bg-muted px-2 py-1 text-sm font-semibold focus-visible:outline-none focus-visible:border-primary"
              >
                <option value="">— pick field —</option>
                {fieldOptions.map((f) => (
                  <option key={f.value} value={f.value}>
                    {f.label}
                  </option>
                ))}
              </select>
            ) : (
              <input
                aria-label={`Input ${i + 1} field`}
                value={c.field}
                onChange={(e) => setColumn("inputs", c.id, { field: e.target.value })}
                placeholder="Customer.tier"
                className="mx-0.5 w-[9.5rem] rounded-md border border-border bg-muted px-2 py-1 text-sm font-semibold focus-visible:outline-none focus-visible:border-primary"
              />
            )}
          </span>
        ))}
        , decide{" "}
        {table.outputs.map((c, i) => (
          <span key={c.id}>
            {i > 0 ? " and " : ""}
            <select
              aria-label={`Outcome ${i + 1} field`}
              value={c.field}
              onChange={(e) => setColumn("outputs", c.id, { field: e.target.value })}
              className="mx-0.5 w-[9.5rem] rounded-md border border-primary/30 bg-primary/5 px-2 py-1 text-sm font-semibold text-primary focus-visible:outline-none focus-visible:border-primary"
            >
              <option value="">— pick output —</option>
              {KNOWN_OUTPUT_FIELDS.map((f) => (
                <option key={f.field} value={f.field}>
                  {f.label}
                </option>
              ))}
            </select>
          </span>
        ))}
        {/* An action row's check is one expression; `%%action` has no second
            input to write a column into. Join conditions with "and" instead. */}
        {!collect && (
          <button
            type="button"
            onClick={() => addColumn("inputs")}
            className="ml-3 text-[13px] font-semibold text-primary hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
          >
            ＋ input
          </button>
        )}
        <button
          type="button"
          onClick={() => addColumn("outputs")}
          className="ml-2 text-[13px] font-semibold text-primary hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          ＋ outcome
        </button>
      </div>

      <div className="overflow-x-auto rounded-xl border border-border bg-card">
        <table className="w-full border-collapse text-[13.5px]">
          <thead>
            <tr>
              <th className="w-9 border-b border-border bg-muted/40 px-3 py-2" />
              <th
                colSpan={table.inputs.length}
                className="border-b border-border bg-muted/40 px-3 py-2 text-center text-[10.5px] font-bold uppercase tracking-[0.1em] text-blue-600 dark:text-blue-400"
              >
                ◇ When all of these fit
              </th>
              <th
                colSpan={table.outputs.length}
                className="border-b border-l-2 border-border px-3 py-2 text-center text-[10.5px] font-bold uppercase tracking-[0.1em] text-primary"
              >
                ▸ The answer is
              </th>
              <th className="w-10 border-b border-border bg-muted/40" />
            </tr>
            <tr>
              <th className="border-b border-border bg-muted/40" />
              {table.inputs.map((c) => (
                <th
                  key={c.id}
                  className="border-b border-border bg-muted/40 px-3 py-2 text-left text-[10.5px] font-bold uppercase tracking-[0.07em] text-blue-600 dark:text-blue-400"
                >
                  {inputLabel(c)}
                </th>
              ))}
              {table.outputs.map((c, i) => (
                <th
                  key={c.id}
                  className={cn(
                    "border-b border-border bg-muted/40 px-3 py-2 text-left text-[10.5px] font-bold uppercase tracking-[0.07em] text-primary",
                    i === 0 && "border-l-2"
                  )}
                >
                  {c.field || c.name}
                </th>
              ))}
              <th className="border-b border-border bg-muted/40" />
            </tr>
          </thead>
          <tbody>
            {table.rules.map((row, rowIndex) => {
              const catchAll = isCatchAll(row) && rowIndex === lastCatchAllIndex;
              return (
                <tr key={row._id} className={cn(catchAll && "bg-muted/30")}>
                  <td className="w-10 border-b border-border px-2 py-2 text-center text-xs tabular-nums text-muted-foreground">
                    {catchAll ? "↓" : rowIndex + 1}
                  </td>

                  {catchAll ? (
                    <td
                      colSpan={table.inputs.length}
                      className="border-b border-border px-3 py-2 italic text-muted-foreground"
                    >
                      Otherwise — nothing above fit
                    </td>
                  ) : (
                    table.inputs.map((c) => (
                      <td key={c.id} className="border-b border-border px-2 py-2">
                        <input
                          aria-label={`Row ${rowIndex + 1}, ${inputLabel(c)}`}
                          className={cellClass}
                          value={row[c.id] ?? ""}
                          onChange={(e) => setCell(rowIndex, c.id, e.target.value)}
                          placeholder="any"
                        />
                      </td>
                    ))
                  )}

                  {table.outputs.map((c, i) => {
                    const opts = getColumnOptions(c);
                    return (
                      <td
                        key={c.id}
                        className={cn("border-b border-border px-2 py-2", i === 0 && "border-l-2")}
                      >
                        {opts ? (
                          <select
                            aria-label={`Row ${rowIndex + 1}, ${c.field || c.name} answer`}
                            className={cn(
                              cellClass,
                              "border-primary/30 bg-primary/5 font-semibold text-primary"
                            )}
                            value={row[c.id] ?? ""}
                            onChange={(e) => setCell(rowIndex, c.id, e.target.value)}
                          >
                            <option value="">— pick —</option>
                            {opts.map((o) => (
                              <option key={o} value={o}>
                                {o}
                              </option>
                            ))}
                          </select>
                        ) : (
                          <input
                            aria-label={`Row ${rowIndex + 1}, ${c.field || c.name} answer`}
                            className={cn(
                              cellClass,
                              "border-primary/30 bg-primary/5 font-semibold text-primary"
                            )}
                            value={row[c.id] ?? ""}
                            onChange={(e) => setCell(rowIndex, c.id, e.target.value)}
                          />
                        )}
                      </td>
                    );
                  })}

                  <td className="w-24 border-b border-border px-2 py-2 text-center">
                    <div className="flex items-center justify-center gap-1">
                      <button
                        type="button"
                        aria-label={`Move row ${rowIndex + 1} up`}
                        onClick={() => moveRow(rowIndex, -1)}
                        disabled={rowIndex === 0}
                        className="inline-flex h-6 w-6 items-center justify-center rounded text-xs leading-none text-muted-foreground hover:bg-muted disabled:opacity-30 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
                      >
                        ↑
                      </button>
                      <button
                        type="button"
                        aria-label={`Move row ${rowIndex + 1} down`}
                        onClick={() => moveRow(rowIndex, 1)}
                        disabled={rowIndex === table.rules.length - 1}
                        className="inline-flex h-6 w-6 items-center justify-center rounded text-xs leading-none text-muted-foreground hover:bg-muted disabled:opacity-30 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
                      >
                        ↓
                      </button>
                      <button
                        type="button"
                        aria-label={`Remove row ${rowIndex + 1}`}
                        onClick={() => removeRow(rowIndex)}
                        className="inline-flex h-6 w-6 items-center justify-center rounded text-xs leading-none text-muted-foreground hover:bg-muted hover:text-red-600 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary dark:hover:text-red-400"
                      >
                        ✕
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="mt-3 flex items-center gap-3">
        <button
          type="button"
          onClick={addRow}
          className="rounded-lg border border-border bg-card px-3.5 py-2 text-[13px] font-semibold hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          ＋ Add row
        </button>
        <span className="text-[12.5px] text-muted-foreground">
          {collect
            ? "A row with its check left blank runs on every record."
            : "Move rows with ↑ ↓. A row with every check left blank is the catch-all — keep it last."}
        </span>
      </div>

      <div className="mt-5 grid gap-3.5 lg:grid-cols-2">
        <section className="rounded-xl border border-border bg-card p-4">
          <h2 className="mb-3 text-[10.5px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
            Test with values
          </h2>
          <div className="mb-3 grid gap-2.5 sm:grid-cols-2">
            {testFields.map((f) => (
              <label key={f.key || f.label} className="block">
                <span className="mb-1 block text-[11.5px] text-muted-foreground">{f.label}</span>
                <input
                  className={cellClass}
                  value={testValues[f.key] ?? ""}
                  onChange={(e) => setTestValues((v) => ({ ...v, [f.key]: e.target.value }))}
                />
              </label>
            ))}
          </div>
          {result.rowIndex === null ? (
            <p className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-[12.5px] text-amber-800 dark:border-amber-800 dark:bg-amber-950/40 dark:text-amber-300">
              {collect
                ? "No row fits these values, so the record passes and nothing runs."
                : "No row fits these values, so this table would return nothing."}
            </p>
          ) : collect ? (
            <div className="space-y-1.5 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-[12.5px] text-emerald-800 dark:border-emerald-800 dark:bg-emerald-950/40 dark:text-emerald-300">
              <p>
                <b>
                  {result.matches.length === 1
                    ? `Row ${result.rowIndex + 1} fits.`
                    : `Rows ${result.matches.map((m) => m.rowIndex + 1).join(", ")} fit, and each runs.`}
                </b>
              </p>
              {result.matches.map((m) => (
                <p key={m.rowIndex}>
                  Row {m.rowIndex + 1}:{" "}
                  {Object.entries(m.outputs)
                    .filter(([, v]) => v)
                    .map(([k, v]) => `${k} = ${v}`)
                    .join(", ")}
                </p>
              ))}
            </div>
          ) : (
            <p className="rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-[12.5px] text-emerald-800 dark:border-emerald-800 dark:bg-emerald-950/40 dark:text-emerald-300">
              <b>Row {result.rowIndex + 1} fits.</b>{" "}
              {/* A message usually ends in its own full stop; do not add a second. */}
              {Object.entries(result.outputs)
                .map(([k, v]) => `${k} = ${v || "(empty)"}`)
                .join(", ")
                .replace(/([^.!?])$/, "$1.")}
            </p>
          )}
        </section>

        <section className="rounded-xl border border-border bg-card p-4">
          <h2 className="mb-3 text-[10.5px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
            Coverage check
          </h2>
          {coverage.map((note) => (
            <p
              key={note.message}
              className={cn(
                "mb-2 rounded-lg border px-3 py-2 text-[12.5px] last:mb-0",
                note.level === "ok"
                  ? "border-emerald-200 bg-emerald-50 text-emerald-800 dark:border-emerald-800 dark:bg-emerald-950/40 dark:text-emerald-300"
                  : "border-amber-200 bg-amber-50 text-amber-800 dark:border-amber-800 dark:bg-amber-950/40 dark:text-amber-300"
              )}
            >
              {note.message}
            </p>
          ))}

          {usedBy.length > 0 ? (
            <>
              <h2 className="mb-2 mt-4 text-[10.5px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
                Where this is used
              </h2>
              {usedBy.map((u) => (
                <p key={`${u.name}-${u.where}`} className="text-[12.5px] leading-relaxed">
                  <span className="font-semibold text-primary">{u.name}</span>{" "}
                  <span className="text-muted-foreground">— {u.where}</span>
                </p>
              ))}
              <p className="mt-2 text-[11.5px] text-muted-foreground">
                Publishing a change affects all of them immediately.
              </p>
            </>
          ) : null}
        </section>
      </div>
    </div>
  );
}

/**
 * The automation builder.
 *
 * Three columns: the automations you have, the one you are editing drawn as a
 * ladder, and a panel for whatever is selected. The ladder reads top to bottom
 * in the order the executor runs, so what you see is the run.
 *
 * The `+` between cards is the only way to add anything. There is no palette to
 * learn and no canvas to arrange, because the model is a list — offering a
 * canvas would mean asking authors to lay out a graph that has only one shape.
 */

