/**
 * Rules and workflows, on one screen — the modelling tool's Logic step and every
 * generated application's Rules & workflows screen.
 *
 * One rail lists both. A rule decides and a process acts on what it decided, so they
 * share a screen, a Save and a vocabulary. This component owns everything an author
 * touches — the rail, creating a rule or a lifecycle, status machine or process, each
 * editor, attaching a rule to a hook, deleting, help — and **no input or output**: the
 * host says where the model comes from, what it declares, how a rule is tried and where
 * a save goes. Two hosts, one behaviour.
 */

/** Everything the screen writes, in one object: the document is edited once. */
export interface WorkbenchSave {
  rules: EditableRule[];
  workflows: EditableWorkflow[];
}

/** What the constraint reader needs to know about each workflow as it stands now. */
export interface ConstraintWorkflow {
  name: string;
  title: string;
  entity: string;
  kind: string;
  stateNames: string[];
}

export interface LogicWorkbenchProps {
  /** The model is still loading. */
  loading: boolean;
  /** Why the model could not be read, if it could not. */
  loadError?: string | null;
  /**
   * The model's rules and workflows, in the shape the editors edit; read once, when they
   * first arrive. Each host turns what it stores into these (and back) — see
   * `lib/eml/workflow-model.ts` for workflows.
   */
  rules: EditableRule[];
  workflows: EditableWorkflow[];
  /** The record types, with the fields each declares. */
  entities: Array<{ name: string; attributes: string[] }>;
  /** What a rule may name, per entity, given the workflows as they stand. */
  constraintsFor: (workflows: ConstraintWorkflow[]) => Record<string, RuleConstraints>;
  /** How this host tries a rule against a sample record. */
  dryRun: RuleDryRun;
  /** Write the model. Throw an `Error` whose message the author should read to refuse. */
  save: (payload: WorkbenchSave) => Promise<void>;
  /** Open on this rule or workflow, by slug (the host's address bar, if it has one). */
  initialSelection?: { rule?: string; workflow?: string };
  /** The author picked something; a host with an address bar records it. */
  onSelectionChange?: (selection: { rule?: string; workflow?: string }) => void;
  /** Where rules are written in full, if the host has a second place for it. */
  enhanceHref?: string;
  /** The host's own heading, shown above the screen. */
  header?: ReactNode;
  /** Buttons before and after Save. They may save first, then leave. */
  footerStart?: (api: { save: () => Promise<boolean>; busy: boolean }) => ReactNode;
  footerEnd?: (api: { save: () => Promise<boolean>; busy: boolean }) => ReactNode;
  /**
   * Workflows the author can read but not change — what a running application's model
   * declares, which its next generation rewrites. Keyed by the workflow's `key`.
   */
  lockedWorkflows?: ReadonlySet<string>;
  /** Whether the host keeps a rule's priority. Off, the field is not offered. Default on. */
  rulesHavePriority?: boolean;
  /** What a locked workflow says about itself. */
  lockedNote?: string;
  /** The names now on screen, for a host that tells an assistant about them. */
  onSummaryChange?: (summary: { ruleNames: string[]; workflowNames: string[] }) => void;
}

const nextKey = newEditorKey;

const workflowSlug = (w: EditableWorkflow) =>
  (w.title ?? w.name)
    .toLowerCase()
    .replace(/\s+/g, "-")
    .replace(/[^a-z0-9-]/g, "");

/** The workflows bound to each state of one status machine, by state. */
function boundWorkflowsFor(
  machine: EditableWorkflow,
  workflows: readonly EditableWorkflow[]
): Record<string, string[]> {
  const bound: Record<string, string[]> = {};
  if (machine.kind !== "state") return bound;
  for (const workflow of workflows) {
    const status = workflow.automation?.onStatus;
    if (workflow.kind === "state" || !status || workflow.entity !== machine.entity) continue;
    (bound[status] ??= []).push(workflow.title ?? workflow.name);
  }
  return bound;
}

export function LogicWorkbench({
  loading,
  loadError,
  rules: storedRules,
  workflows: storedWorkflows,
  entities,
  constraintsFor,
  dryRun,
  save: saveModel,
  initialSelection,
  onSelectionChange,
  enhanceHref,
  header,
  footerStart,
  footerEnd,
  lockedWorkflows,
  lockedNote,
  rulesHavePriority = true,
  onSummaryChange,
}: LogicWorkbenchProps) {
  const [rules, setRules] = useState<EditableRule[]>([]);
  const [workflows, setWorkflows] = useState<EditableWorkflow[]>([]);
  const [selectedIndex, setSelectedIndex] = useState(0);
  // A workflow starts from the hooks it attaches to, so with none yet the screen opens on
  // that, not on an empty editor.
  const [creating, setCreating] = useState(false);
  // A rule is edited here too, with no moment of its own: a workflow hook gives it one.
  const [selectedRule, setSelectedRule] = useState<number | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [savedAt, setSavedAt] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [helpOpen, setHelpOpen] = useState(false);
  const [helpTopicId, setHelpTopicId] = useState<HelpTopicId>("overview");
  const openHelp = useCallback((topic: HelpTopicId) => {
    setHelpTopicId(topic);
    setHelpOpen(true);
  }, []);
  const closeHelp = useCallback(() => setHelpOpen(false), []);

  // The model arrives once; after that the author's edits are the truth.
  const adopted = useRef(false);
  useEffect(() => {
    if (loading || adopted.current) return;
    adopted.current = true;
    const nextRules = storedRules;
    const nextWorkflows = storedWorkflows;
    setRules(nextRules);
    setWorkflows(nextWorkflows);
    const wanted = initialSelection;
    if (wanted?.rule) {
      const index = nextRules.findIndex((r) => slugifyRuleName(r.title ?? r.name) === wanted.rule);
      if (index >= 0) setSelectedRule(index);
    } else if (wanted?.workflow) {
      const index = nextWorkflows.findIndex((w) => workflowSlug(w) === wanted.workflow);
      if (index >= 0) setSelectedIndex(index);
    }
  }, [loading, storedRules, storedWorkflows, initialSelection]);

  useEffect(() => {
    if (loadError) setError(loadError);
  }, [loadError]);

  const entityNames = useMemo(() => entities.map((entity) => entity.name), [entities]);
  // What a rule may name: the entity's fields, the values its enum or state machine
  // allows, and the processes defined for it.
  const constraints = useMemo(
    () =>
      constraintsFor(
        workflows.map((workflow) => ({
          name: pascalWorkflowName(workflow.title ?? workflow.name),
          title: workflow.title ?? workflow.name,
          entity: workflow.entity,
          kind: workflow.kind,
          stateNames: workflow.kind === "state" ? workflow.states.states.map((s) => s.name) : [],
        }))
      ),
    [constraintsFor, workflows]
  );
  const columnsFor = useCallback(
    (entity: string) => entities.find((candidate) => candidate.name === entity)?.attributes ?? [],
    [entities]
  );
  /** The same fields `columnsFor` gives, in the shape the ladder takes them. */
  const entityFieldMap = useMemo(
    () => Object.fromEntries(entities.map((entity) => [entity.name, entity.attributes])),
    [entities]
  );
  // A Decision step can evaluate a rule declared here rather than carrying its own copy of
  // the same table — which is only offerable because both live on this screen.
  const ruleNames = useMemo(
    () => rules.map((rule) => slugifyRuleName(rule.title ?? rule.name)),
    [rules]
  );
  // What a "Look up a rule table" step picks from.
  const ruleTables: RuleTableSummary[] = useMemo(
    () =>
      rules.map((rule) => ({
        id: rule.key,
        name: slugifyRuleName(rule.title ?? rule.name),
        rowCount: rule.table.rules.length,
        outputs: rule.table.outputs.map((output) => output.field || output.name),
      })),
    [rules]
  );

  const workflowNames = useMemo(
    () => workflows.map((workflow) => pascalWorkflowName(workflow.title ?? workflow.name)),
    [workflows]
  );
  const summaryKey = `${ruleNames.join("|")}#${workflowNames.join("|")}`;
  // the key stands for both lists.
  useEffect(() => {
    onSummaryChange?.({ ruleNames, workflowNames });
  }, [summaryKey]);

  const activeWorkflowLocked = !!(
    !creating &&
    selectedRule === null &&
    workflows[selectedIndex] &&
    lockedWorkflows?.has((workflows[selectedIndex] as EditableWorkflow).key)
  );
  const activeRule = creating || selectedRule === null ? null : (rules[selectedRule] ?? null);
  const activeWorkflow =
    creating || selectedRule !== null ? null : (workflows[selectedIndex] ?? null);

  const patchRule = useCallback(
    (patch: Partial<EditableRule>) => {
      setRules((current) =>
        current.map((rule, index) => (index === selectedRule ? { ...rule, ...patch } : rule))
      );
      setSavedAt(null);
    },
    [selectedRule]
  );

  const addRule = () => {
    const newName = `rule${rules.length + 1}`;
    setRules((current) => [
      ...current,
      {
        key: nextKey(),
        name: newName,
        entity: entityNames[0] ?? "",
        event: "beforeCreate",
        priority: 100,
        table: emptyDecisionTable(),
      },
    ]);
    setSelectedRule(rules.length);
    setCreating(false);
    setSavedAt(null);
    onSelectionChange?.({ rule: newName });
  };

  const removeRule = (index: number) => {
    setRules((current) => current.filter((_r, i) => i !== index));
    setSelectedRule((current) =>
      current === null ? null : current === index ? null : current > index ? current - 1 : current
    );
    setSavedAt(null);
  };

  /**
   * Attaching a rule to a hook gives it that hook's event. The rule's own table is
   * untouched — it is written in the rule editor.
   */
  const attachRule = useCallback((ruleKey: string, event: string) => {
    setRules((current) =>
      current.map((rule) => (rule.key === ruleKey ? { ...rule, event } : rule))
    );
    setSavedAt(null);
  }, []);

  const patchWorkflow = useCallback(
    (patch: Partial<EditableWorkflow>) => {
      setWorkflows((current) =>
        current.map((workflow, index) =>
          index === selectedIndex ? { ...workflow, ...patch } : workflow
        )
      );
      setSavedAt(null);
    },
    [selectedIndex]
  );

  const createWorkflow = (draft: NewWorkflowDraft) => {
    const base = emptyWorkflow("hook", nextKey(), draft.entity);
    const automation = {
      ...emptyAutomation(draft.entity, "hook"),
      name: draft.name,
      hooks: [hookFor(draft.entity, draft.event)],
      ...(draft.status ? { onStatus: draft.status } : {}),
    };
    const newWorkflow = {
      ...base,
      name: pascalWorkflowName(draft.name),
      title: draft.name,
      automation,
    };
    setWorkflows((current) => [...current, newWorkflow]);
    setSelectedIndex(workflows.length);
    setSelectedRule(null);
    setCreating(false);
    setSavedAt(null);
    onSelectionChange?.({ workflow: workflowSlug(newWorkflow) });
  };

  /** A status machine or a process has no hooks to start from, so it opens blank. */
  const addWorkflow = (kind: WorkflowKind) => {
    const newWorkflow = emptyWorkflow(kind, nextKey(), entityNames[0] ?? "");
    setWorkflows((current) => [...current, newWorkflow]);
    setSelectedIndex(workflows.length);
    setSelectedRule(null);
    setCreating(false);
    setSavedAt(null);
    onSelectionChange?.({ workflow: workflowSlug(newWorkflow) });
  };

  const removeWorkflow = (index: number) => {
    const target = workflows[index];
    if (target && lockedWorkflows?.has(target.key)) return;
    setWorkflows((current) => current.filter((_w, i) => i !== index));
    setSelectedIndex((current) => (current >= index ? Math.max(0, current - 1) : current));
    setSavedAt(null);
  };

  /** One write, both halves — the document is edited once. Resolves true when it was saved. */
  const save = async (): Promise<boolean> => {
    const problems = sectionProblems(rules, workflows);
    const first = problems[0];
    if (first) {
      setError(problems.map((p) => p.message).join(" "));
      setCreating(false);
      if (first.kind === "workflow") {
        setSelectedIndex(first.index);
        setSelectedRule(null);
      } else {
        setSelectedRule(first.index);
      }
      return false;
    }
    setIsSaving(true);
    setError(null);
    try {
      await saveModel({ rules, workflows });
      setSavedAt(new Date().toLocaleTimeString());
      return true;
    } catch (saveError) {
      setError(saveError instanceof Error ? saveError.message : "Could not save");
      return false;
    } finally {
      setIsSaving(false);
    }
  };

  const kindIcon = (kind: WorkflowKind) =>
    kind === "saga" ? ListOrdered : kind === "state" ? GitBranch : WorkflowIcon;

  /** The help page for whatever the editor is showing, and how to ask for it. */
  const editorHelp: { topic: HelpTopicId; label: string } =
    activeWorkflow?.kind === "state"
      ? { topic: "status", label: "How status machines work" }
      : activeWorkflow?.kind === "hook"
        ? { topic: "lifecycle", label: "How lifecycle processes work" }
        : activeWorkflow
          ? { topic: "process", label: "How processes and their steps work" }
          : { topic: "overview", label: "Which one should I use?" };

  return (
    <div>
      {header}

      <div className="-mt-2 mb-4 flex justify-end">
        <button
          type="button"
          onClick={() => openHelp(helpOpen ? helpTopicId : "overview")}
          className="flex items-center gap-1.5 rounded-md border border-border px-3 py-1.5 text-sm font-medium hover:bg-muted"
        >
          <BookOpen className="h-4 w-4" />
          Help
        </button>
      </div>

      <HelpPanel
        open={helpOpen}
        topic={helpTopicId}
        onTopicChange={setHelpTopicId}
        onClose={closeHelp}
      />

      {error && (
        <div className="mb-4 flex items-start gap-2 rounded-lg border border-destructive/40 bg-destructive/5 px-3 py-2 text-sm text-destructive">
          <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
          <span>{error}</span>
        </div>
      )}

      {loading ? (
        <div className="flex items-center gap-2 py-16 text-sm text-muted-foreground">
          <Loader2 className="h-4 w-4 animate-spin" />
          Loading the model…
        </div>
      ) : (
        // Side by side from md up; stacked on a phone, where a 256px rail left the editor a
        // column about 70px wide.
        <div className="flex flex-col gap-4 md:flex-row">
          <aside className="max-h-80 w-full space-y-5 overflow-y-auto md:max-h-none md:w-64 md:shrink-0 md:overflow-visible">
            <div>
              <div className="mb-2 flex items-center justify-between">
                <h2 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                  Rules ({rules.length})
                </h2>
                <button
                  type="button"
                  onClick={addRule}
                  className="flex items-center gap-1 rounded-md border border-border px-2 py-1 text-xs font-medium hover:bg-muted"
                >
                  <Plus className="h-3 w-3" />
                  New rule
                </button>
              </div>
              <div className="space-y-1">
                {rules.map((rule, index) => (
                  <div
                    key={rule.key}
                    className={`group flex items-center gap-1 rounded-md border px-2 py-1.5 text-left text-sm ${
                      !creating && selectedRule === index
                        ? "border-primary bg-primary/5"
                        : "border-border hover:bg-muted"
                    }`}
                  >
                    <button
                      type="button"
                      onClick={() => {
                        setSelectedRule(index);
                        setCreating(false);
                        onSelectionChange?.({ rule: slugifyRuleName(rule.title ?? rule.name) });
                      }}
                      className="min-w-0 flex-1 text-left"
                    >
                      <span className="block truncate font-medium">{rule.title || rule.name}</span>
                      <span className="block truncate text-[11px] text-muted-foreground">
                        {rule.entity || "no entity"}
                      </span>
                    </button>
                    <button
                      type="button"
                      onClick={() => removeRule(index)}
                      aria-label={`Delete ${rule.name}`}
                      className="opacity-0 transition group-hover:opacity-100"
                    >
                      <Trash2 className="h-3.5 w-3.5 text-muted-foreground hover:text-destructive" />
                    </button>
                  </div>
                ))}
                {!rules.length && (
                  <p className="rounded-md border border-dashed border-border px-2 py-3 text-center text-xs text-muted-foreground">
                    No rules yet.
                  </p>
                )}
              </div>
            </div>

            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <h2 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                  Workflows ({workflows.length})
                </h2>
                <button
                  type="button"
                  onClick={() => {
                    setCreating(true);
                    setSelectedRule(null);
                  }}
                  className="flex items-center gap-1 rounded-md border border-border px-2 py-1 text-xs font-medium hover:bg-muted"
                >
                  <Plus className="h-3 w-3" />
                  New workflow
                </button>
              </div>

              <div className="space-y-1">
                {workflows.map((workflow, index) => {
                  const Icon = kindIcon(workflow.kind);
                  const hookCount = workflow.automation?.hooks.length ?? 0;
                  return (
                    <div
                      key={workflow.key}
                      className={`group flex items-center gap-1 rounded-md border px-2 py-1.5 text-left text-sm ${
                        !creating && selectedRule === null && selectedIndex === index
                          ? "border-primary bg-primary/5"
                          : "border-border hover:bg-muted"
                      }`}
                    >
                      <button
                        type="button"
                        onClick={() => {
                          setSelectedIndex(index);
                          setSelectedRule(null);
                          setCreating(false);
                          onSelectionChange?.({ workflow: workflowSlug(workflow) });
                        }}
                        className="flex min-w-0 flex-1 items-center gap-1.5 text-left"
                      >
                        <Icon className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
                        <span className="min-w-0">
                          <span className="block truncate font-medium">
                            {workflow.title || workflow.name}
                          </span>
                          <span className="block truncate text-[11px] text-muted-foreground">
                            {workflow.entity || "no entity"} ·{" "}
                            {workflow.kind === "hook"
                              ? `${hookCount} hook${hookCount === 1 ? "" : "s"}`
                              : workflow.kind}
                          </span>
                        </span>
                      </button>
                      {lockedWorkflows?.has(workflow.key) ? (
                        <span
                          title="Declared in the model"
                          className="rounded border border-border px-1 text-[10px] uppercase tracking-wide text-muted-foreground"
                        >
                          model
                        </span>
                      ) : (
                        <button
                          type="button"
                          onClick={() => removeWorkflow(index)}
                          aria-label={`Delete ${workflow.name}`}
                          className="opacity-0 transition group-hover:opacity-100"
                        >
                          <Trash2 className="h-3.5 w-3.5 text-muted-foreground hover:text-destructive" />
                        </button>
                      )}
                    </div>
                  );
                })}

                {!workflows.length && (
                  <p className="rounded-md border border-dashed border-border px-2 py-3 text-center text-xs text-muted-foreground">
                    No workflows yet.
                  </p>
                )}
              </div>

              <div className="border-t border-border pt-3 text-[11px] text-muted-foreground">
                Other kinds:{" "}
                <button type="button" className="underline" onClick={() => addWorkflow("state")}>
                  status machine
                </button>
                {" · "}
                <button type="button" className="underline" onClick={() => addWorkflow("saga")}>
                  process
                </button>
              </div>
            </div>
          </aside>

          <div className="min-w-0 flex-1">
            {activeRule ? (
              <>
                <div className="mb-2 flex justify-end">
                  <HelpLink onClick={() => openHelp("rules")}>How business rules work</HelpLink>
                </div>
                <RuleEditor
                  key={activeRule.key}
                  rule={activeRule}
                  entities={entities}
                  dryRun={dryRun}
                  onChange={patchRule}
                  onError={setError}
                  entityEnums={constraints[activeRule.entity]?.values}
                  entityWorkflows={constraints[activeRule.entity]?.workflowNames}
                  fieldTypes={constraints[activeRule.entity]?.fieldTypes}
                  showPriority={rulesHavePriority}
                />
              </>
            ) : creating || (!workflows.length && !activeWorkflow) ? (
              <NewWorkflowPanel
                key="new-workflow"
                entityNames={entityNames}
                statusChoicesFor={(entity) => statusChoicesFor(entity, workflows)}
                onCreate={createWorkflow}
                onCancel={workflows.length ? () => setCreating(false) : undefined}
              />
            ) : (
              <>
                <div className="mb-2 flex justify-end">
                  <HelpLink onClick={() => openHelp(editorHelp.topic)}>{editorHelp.label}</HelpLink>
                </div>
                {activeWorkflowLocked && (
                  <p
                    role="note"
                    className="mb-3 rounded-md border border-border bg-muted/50 px-3 py-2 text-xs text-muted-foreground"
                  >
                    {lockedNote ??
                      "This workflow is declared in the model. Edit the model and generate again to change it."}
                  </p>
                )}
                <div
                  // `inert` takes the whole editor out of reach of the pointer and the keyboard
                  // alike; set from a ref because React 18 and 19 spell the attribute differently.
                  ref={(element) => {
                    if (!element) return;
                    if (activeWorkflowLocked) element.setAttribute("inert", "");
                    else element.removeAttribute("inert");
                  }}
                  data-locked={activeWorkflowLocked || undefined}
                >
                  {(activeWorkflow?.kind === "hook" || activeWorkflow?.kind === "saga") &&
                  activeWorkflow.automation ? (
                    <>
                      <div className="min-h-[560px] overflow-hidden rounded-xl border border-border">
                        <AutomationBuilder
                          key={activeWorkflow.key}
                          automation={activeWorkflow.automation}
                          onChange={(automation) =>
                            patchWorkflow({
                              automation,
                              entity: automation.trigger.entity,
                              title: automation.name,
                              name: pascalWorkflowName(automation.name),
                            })
                          }
                          entities={entityNames}
                          statusChoices={statusChoicesFor(activeWorkflow.entity, workflows)}
                          entityFields={entityFieldMap}
                          ruleTables={ruleTables}
                          onOpenRuleTable={(name) => {
                            const index = rules.findIndex(
                              (rule) => slugifyRuleName(rule.title ?? rule.name) === name
                            );
                            if (index >= 0) setSelectedRule(index);
                          }}
                        />
                      </div>
                      {activeWorkflow.kind === "hook" && (
                        <WorkflowRules
                          entity={activeWorkflow.entity}
                          hooks={activeWorkflow.automation.hooks}
                          rules={rules}
                          onAttach={attachRule}
                          enhanceHref={enhanceHref ?? "#"}
                        />
                      )}
                    </>
                  ) : activeWorkflow ? (
                    <WorkflowEditor
                      key={activeWorkflow.key}
                      workflow={activeWorkflow}
                      boundWorkflows={boundWorkflowsFor(activeWorkflow, workflows)}
                      entityNames={entityNames}
                      ruleNames={ruleNames}
                      columnsFor={columnsFor}
                      onChange={patchWorkflow}
                    />
                  ) : null}
                </div>
              </>
            )}
          </div>
        </div>
      )}

      <div className="mt-6 flex items-center justify-between border-t border-border pt-4">
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          {savedAt && (
            <>
              <CheckCircle2 className="h-3.5 w-3.5 text-emerald-600" />
              Saved to the model at {savedAt}
            </>
          )}
        </div>

        <div className="flex gap-2">
          {footerStart?.({ save, busy: isSaving || loading })}
          <button
            type="button"
            onClick={() => void save()}
            disabled={isSaving || loading}
            className="flex items-center gap-1.5 rounded-md border border-border px-4 py-2 text-sm font-medium disabled:opacity-50"
          >
            {isSaving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
            Save
          </button>
          {footerEnd?.({ save, busy: isSaving || loading })}
        </div>
      </div>
    </div>
  );
}

/**
 * A slide-over that reads the help Markdown shipped with the application.
 *
 * It sits beside the editor rather than over it: the panel is narrow enough
 * that the table or ladder being explained stays in view, which is the point
 * of help that says "click the card, then fill in the field on the right".
 * No modal and no backdrop for the same reason; Escape or the close button
 * dismisses it.
 */

import { BookOpen, X } from "lucide-react";
import { type ReactNode, useEffect, useRef } from "react";
import ReactMarkdown, { type Components } from "react-markdown";
import remarkGfm from "remark-gfm";
import { HELP_TOPICS, type HelpTopicId, helpTopic } from "../../content/help";
import { cn } from "../../lib/utils";

/** Markdown elements, in this application's type and colour. */
const MARKDOWN: Components = {
  h1: ({ children }) => <h1 className="mb-3 text-xl font-bold tracking-tight">{children}</h1>,
  h2: ({ children }) => (
    <h2 className="mb-2 mt-6 border-b border-border pb-1 text-base font-semibold">{children}</h2>
  ),
  h3: ({ children }) => <h3 className="mb-1.5 mt-4 text-sm font-semibold">{children}</h3>,
  p: ({ children }) => <p className="mb-3 text-[13.5px] leading-relaxed">{children}</p>,
  ul: ({ children }) => (
    <ul className="mb-3 list-disc space-y-1 pl-5 text-[13.5px] leading-relaxed">{children}</ul>
  ),
  ol: ({ children }) => (
    <ol className="mb-3 list-decimal space-y-1 pl-5 text-[13.5px] leading-relaxed">{children}</ol>
  ),
  blockquote: ({ children }) => (
    <blockquote className="mb-3 border-l-2 border-primary/40 bg-primary/5 px-3 py-2 text-[13.5px] [&>p]:mb-0">
      {children}
    </blockquote>
  ),
  code: ({ children, className }) =>
    className ? (
      <code className={cn("font-mono text-[12px]", className)}>{children}</code>
    ) : (
      <code className="rounded bg-muted px-1 py-0.5 font-mono text-[12px]">{children}</code>
    ),
  pre: ({ children }) => (
    <pre className="mb-3 overflow-x-auto rounded-md border border-border bg-muted/50 p-3 text-[12px] leading-relaxed">
      {children}
    </pre>
  ),
  table: ({ children }) => (
    <div className="mb-3 overflow-x-auto rounded-md border border-border">
      <table className="w-full border-collapse text-left text-[12.5px]">{children}</table>
    </div>
  ),
  th: ({ children }) => (
    <th className="border-b border-border bg-muted/50 px-2 py-1.5 font-semibold">{children}</th>
  ),
  td: ({ children }) => (
    <td className="border-b border-border px-2 py-1.5 align-top last:border-b-0">{children}</td>
  ),
  a: ({ children, href }) => (
    <a href={href} target="_blank" rel="noreferrer" className="text-primary underline">
      {children}
    </a>
  ),
};

export interface HelpPanelProps {
  open: boolean;
  topic: HelpTopicId;
  onTopicChange: (topic: HelpTopicId) => void;
  onClose: () => void;
}

export function HelpPanel({ open, topic, onTopicChange, onClose }: HelpPanelProps) {
  const body = useRef<HTMLDivElement>(null);
  const current = helpTopic(topic);

  useEffect(() => {
    if (!open) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onClose]);

  // A new topic starts at its top, not wherever the last one was scrolled to.
  // the topic is the trigger
  useEffect(() => {
    body.current?.scrollTo({ top: 0 });
  }, [topic]);

  if (!open) return null;

  return (
    <>
      {/* Backdrop — clicking outside closes the panel */}
      <div className="fixed inset-0 z-40 bg-black/20" aria-hidden="true" onClick={onClose} />
      <aside
        aria-label="Help"
        className="fixed inset-y-0 right-0 z-50 flex w-full max-w-[460px] flex-col border-l border-border bg-card shadow-2xl"
      >
        <header className="flex items-center gap-2 border-b border-border px-4 py-3">
          <BookOpen className="h-4 w-4 text-primary" />
          <span className="text-sm font-semibold">Help</span>
          <div className="flex-1" />
          <button
            type="button"
            onClick={onClose}
            aria-label="Close help"
            className="rounded-md p-1 text-muted-foreground hover:bg-muted hover:text-foreground"
          >
            <X className="h-4 w-4" />
          </button>
        </header>

        <div
          role="tablist"
          aria-label="Help topics"
          className="flex flex-wrap gap-1 border-b border-border px-3 py-2"
        >
          {HELP_TOPICS.map((entry) => (
            <button
              key={entry.id}
              type="button"
              role="tab"
              aria-selected={entry.id === topic}
              onClick={() => onTopicChange(entry.id)}
              className={cn(
                "rounded-md px-2.5 py-1 text-xs font-medium",
                entry.id === topic
                  ? "bg-primary text-primary-foreground"
                  : "text-muted-foreground hover:bg-muted hover:text-foreground"
              )}
            >
              {entry.label}
            </button>
          ))}
        </div>

        <div ref={body} role="tabpanel" className="min-h-0 flex-1 overflow-y-auto px-5 py-4">
          <ReactMarkdown remarkPlugins={[remarkGfm]} components={MARKDOWN}>
            {current.markdown}
          </ReactMarkdown>
        </div>
      </aside>
    </>
  );
}

/** The small "How does this work?" link above an editor. */
export function HelpLink({ onClick, children }: { onClick: () => void; children: ReactNode }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="inline-flex items-center gap-1 text-xs font-medium text-primary hover:underline"
    >
      <BookOpen className="h-3.5 w-3.5" />
      {children}
    </button>
  );
}

/**
 * The Logic step's help, one Markdown file per editor.
 *
 * Kept as `.md` beside the application rather than as JSX so the words can be
 * read, reviewed and changed without touching a component — and so a reviewer
 * can hold them against the editors they describe. `?raw` inlines each file at
 * build time; nothing is fetched at run time, so the help works offline and in
 * the same bundle as the screen it explains.
 *
 * `help-content.test.ts` holds each page to the editor it documents: every
 * event, step type and outcome the editor offers must appear on its page, so a
 * control added to an editor without a word of help fails a test.
 */

import businessRules from "./business-rules.md?raw";
import lifecycle from "./lifecycle.md?raw";
import overview from "./overview.md?raw";
import processSteps from "./process.md?raw";
import status from "./status.md?raw";

export type HelpTopicId = "overview" | "rules" | "lifecycle" | "status" | "process";

export interface HelpTopic {
  id: HelpTopicId;
  /** The tab label. */
  label: string;
  markdown: string;
}

export const HELP_TOPICS: readonly HelpTopic[] = [
  { id: "overview", label: "Overview", markdown: overview },
  { id: "rules", label: "Business rules", markdown: businessRules },
  { id: "lifecycle", label: "Lifecycle", markdown: lifecycle },
  { id: "status", label: "Status", markdown: status },
  { id: "process", label: "Process", markdown: processSteps },
];

export function helpTopic(id: HelpTopicId): HelpTopic {
  return HELP_TOPICS.find((topic) => topic.id === id) ?? (HELP_TOPICS[0] as HelpTopic);
}

/**
 * The one helper the editors take from their host: merge Tailwind class names.
 * Kept here so the package imports nothing from the application around it.
 */

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Hold a rule graph to what the model declares.
 *
 * The GoRules editor takes a column's allowed values from its `fieldType`: a
 * string column with an inline enum is a list the cell is picked from, in place
 * of free text. This sets that on every decision table in the graph, from the
 * entity's own constraints, and reports whatever the graph names that does not
 * exist — a field the entity lacks, a status its state machine never reaches, a
 * process nobody defined. The report is the part that reaches a check written
 * as an expression, which no column type can close.
 */

import type { RuleConstraints } from "./rule-constraints";

/** What a rule may answer. Starting a process is chosen in the workflow editor. */
export const ANSWERS = ["validation-error", "transform", "allow"] as const;

interface Column {
  id?: string;
  name?: string | null;
  field?: string | null;
  fieldType?: unknown;
  outputFieldType?: unknown;
}

interface TableContent {
  inputs?: Column[];
  outputs?: Column[];
  rules?: Array<Record<string, string | undefined>>;
}

interface GraphNode {
  id?: string;
  type?: string;
  name?: string;
  content?: unknown;
}

interface Graph {
  nodes?: GraphNode[];
  edges?: Array<{ sourceId?: string; targetId?: string }>;
}

const STOCK_IMPORT = /^[ \t]*import\s+zen\s+from\s+['"]zen['"];?[ \t]*\r?\n?/m;

/** The editor's starter source for a function node, minus the import it ships with. */
export function withoutStockImport(content: unknown): unknown {
  if (typeof content === "string") return content.replace(STOCK_IMPORT, "").replace(/^\s*\n/, "");
  if (
    content &&
    typeof content === "object" &&
    typeof (content as { source?: unknown }).source === "string"
  ) {
    const source = (content as { source: string }).source;
    return { ...content, source: source.replace(STOCK_IMPORT, "").replace(/^\s*\n/, "") };
  }
  return content;
}

const choices = (values: readonly string[]) => ({
  type: "string" as const,
  enum: {
    type: "inline" as const,
    values: values.map((value) => ({ label: value, value })),
  },
});

/** The values a column may hold, or null when it is free. */
function allowedFor(
  field: string,
  kind: "input" | "output",
  constraints: RuleConstraints
): readonly string[] | null {
  if (kind === "output") {
    if (field === "action") return ANSWERS;
    if (field === "workflowName") return constraints.workflowNames;
    if (field === "field") return constraints.fields;
  }
  return constraints.values[field] ?? null;
}

/** The same graph, with each constrained column typed as a pick-list. */
export function constrainGraph<G extends Graph>(graph: G, constraints: RuleConstraints): G {
  return {
    ...graph,
    nodes: (graph.nodes ?? []).map((node) => {
      // The node every rule starts from is the record being written, so it is
      // called that — the editor's own default name for it is "Request".
      if (node.type === "inputNode") {
        return !node.name || node.name === "Request" ? { ...node, name: "Record" } : node;
      }
      // A new function node opens with `import zen from 'zen'`, a line the
      // application's own check refuses (a function may not import), so a rule
      // saved from the editor's default body could never compile.
      if (node.type === "functionNode")
        return { ...node, content: withoutStockImport(node.content) };
      if (node.type !== "decisionTableNode") return node;
      const content = (node.content ?? {}) as TableContent;
      const type = (column: Column, kind: "input" | "output") => {
        const allowed = column.field ? allowedFor(column.field, kind, constraints) : null;
        return allowed ? choices(allowed) : undefined;
      };
      return {
        ...node,
        content: {
          ...content,
          inputs: (content.inputs ?? []).map((column) => {
            const fieldType = type(column, "input");
            return fieldType ? { ...column, fieldType } : column;
          }),
          outputs: (content.outputs ?? []).map((column) => {
            const outputFieldType = type(column, "output");
            return outputFieldType ? { ...column, outputFieldType } : column;
          }),
        },
      };
    }),
  };
}

const unquote = (cell: string) => cell.trim().replace(/^["']|["']$/g, "");

/**
 * The values a cell under a constrained column names.
 *
 * "Is one of" in the table writes `["cancelled","completed"]`, "is not one of"
 * and "not equals" write `not(...)`/`!=`, and a typed list is `"a","b"`. Reading
 * the whole cell as one value reported `["cancelled"]` as "not an existing
 * status" for a rule that named a real one.
 */
export function cellValues(cell: string): string[] {
  let text = cell.trim();
  const negated = /^not\s*\(([\s\S]*)\)$/.exec(text);
  if (negated) text = (negated[1] ?? "").trim();
  text = text.replace(/^(?:==|!=|=)\s*/, "");
  const list = /^\[([\s\S]*)\]$/.exec(text);
  if (list) text = (list[1] ?? "").trim();
  const values: string[] = [];
  let current = "";
  let quote = "";
  for (const char of text) {
    if (quote) {
      current += char;
      if (char === quote) quote = "";
    } else if (char === '"' || char === "'") {
      current += char;
      quote = char;
    } else if (char === ",") {
      values.push(current);
      current = "";
    } else current += char;
  }
  values.push(current);
  return values.map(unquote).filter((value) => value !== "");
}

/**
 * The names a function's source hands on: the keys of every object it returns
 * (`return { ...input, score }`, `return { tier: "gold" }`) and every property it
 * sets on the record it was given (`input.score = 1`). Read, not run — a name
 * built at run time is not seen, which errs towards a warning, never a refusal.
 */
export function functionOutputs(content: unknown): string[] {
  const source =
    typeof content === "string"
      ? content
      : typeof (content as { source?: unknown } | null)?.source === "string"
        ? (content as { source: string }).source
        : "";
  const names = new Set<string>();
  for (const block of source.matchAll(/return\s*\{([^{}]*)\}/g)) {
    for (const part of (block[1] ?? "").split(",")) {
      const entry = part.trim();
      if (!entry || entry.startsWith("...")) continue;
      const name = /^["']?([A-Za-z_$][\w$]*)["']?\s*(?::|$)/.exec(entry)?.[1];
      if (name) names.add(name);
    }
  }
  for (const m of source.matchAll(/\b(?:input|output|result)\.([A-Za-z_$][\w$]*)\s*=(?!=)/g)) {
    names.add(m[1]!);
  }
  return [...names];
}

/** The names one node adds to what flows on: an expression's keys, a table's outputs, a function's returns. */
function producedBy(node: GraphNode): string[] {
  if (node.type === "expressionNode") {
    const rows = ((node.content ?? {}) as { expressions?: Array<{ key?: string }> }).expressions;
    return (rows ?? []).map((row) => (row.key ?? "").trim()).filter(Boolean);
  }
  if (node.type === "decisionTableNode") {
    return (((node.content ?? {}) as TableContent).outputs ?? [])
      .map((column) => (column.field ?? "").trim())
      .filter(Boolean);
  }
  if (node.type === "functionNode") return functionOutputs(node.content);
  return [];
}

/**
 * The names a node can read besides the record's own fields: whatever the nodes
 * before it produced. Found by walking the graph's lines backwards, so a value a
 * later node works out is still unknown here — as it is to the engine.
 */
export function derivedNamesBefore(graph: Graph, nodeId: string | undefined): Set<string> {
  const names = new Set<string>();
  if (!nodeId) return names;
  const byId = new Map((graph.nodes ?? []).map((node) => [node.id, node]));
  const seen = new Set<string>([nodeId]);
  const queue = [nodeId];
  while (queue.length > 0) {
    const target = queue.shift()!;
    for (const edge of graph.edges ?? []) {
      if (edge.targetId !== target || !edge.sourceId || seen.has(edge.sourceId)) continue;
      seen.add(edge.sourceId);
      queue.push(edge.sourceId);
      const source = byId.get(edge.sourceId);
      if (source) for (const name of producedBy(source)) names.add(name);
    }
  }
  return names;
}

/**
 * What the graph names that the model does not have.
 *
 * Reads the decision tables: a column's field, a cell under a constrained
 * column, and — for a whole-record check such as `status == "qualified"` — the
 * field and the value on either side of a comparison.
 */
export function graphProblems(graph: Graph, constraints: RuleConstraints): string[] {
  const problems = new Set<string>();
  const entityFields = new Set(constraints.fields);

  for (const node of graph.nodes ?? []) {
    if (node.type !== "decisionTableNode") continue;
    const content = (node.content ?? {}) as TableContent;
    // A table reads the record and whatever the nodes before it worked out: an
    // expression's keys, an earlier table's outputs, what a function returned.
    // Checking against the record alone called every one of those "not a field".
    const derived = derivedNamesBefore(graph, node.id);
    const fields = new Set([...entityFields, ...derived]);
    const columns = [
      ...(content.inputs ?? []).map((c) => ({ c, kind: "input" as const })),
      ...(content.outputs ?? []).map((c) => ({ c, kind: "output" as const })),
    ];

    for (const { c, kind } of columns) {
      if (kind === "input" && c.field && !fields.has(c.field)) {
        problems.add(`"${c.field}" is not a field of this entity.`);
      }
      const allowed = c.field ? allowedFor(c.field, kind, constraints) : null;
      if (!c.id || !c.field || !allowed) continue;
      for (const row of content.rules ?? []) {
        const cell = row[c.id];
        if (!cell || !cell.trim()) continue;
        for (const value of cellValues(cell)) {
          // zen's null-check cells ("null", "!= null") are always valid — they
          // mean "field is null / is not null", not the string literal "null".
          if (value === "null") continue;
          if (c.field === "action" && value === "trigger-workflow") {
            problems.add(
              "A rule cannot start a workflow — attach the rule to the workflow in the workflow editor."
            );
          } else if (!allowed.includes(value)) {
            const what = c.field === "workflowName" ? "process" : c.field;
            problems.add(`"${value}" is not an existing ${what} for this entity.`);
          }
        }
      }
    }

    // Whole-record checks: `status == "qualified"`, `amount > 10 and stage != "won"`.
    for (const row of content.rules ?? []) {
      for (const column of content.inputs ?? []) {
        if (column.field || !column.id) continue;
        const cell = row[column.id];
        if (!cell) continue;
        for (const m of cell.matchAll(
          /([A-Za-z_]\w*)\s*(?:==|!=|>=|<=|>|<)\s*("[^"]*"|'[^']*'|[^\s)]+)/g
        )) {
          const [, name, raw] = m as unknown as [string, string, string];
          if (!fields.has(name)) {
            problems.add(`"${name}" is not a field of this entity.`);
            continue;
          }
          const allowed = constraints.values[name];
          if (allowed && /^["']/.test(raw) && !allowed.includes(unquote(raw))) {
            problems.add(`"${unquote(raw)}" is not a ${name} this entity can have.`);
          }
        }
      }
    }
  }
  return [...problems];
}

export interface InputColumn {
  nodeId: string;
  nodeName: string;
  columnId: string;
  /** The field the column checks, or "" for a whole-record check. */
  field: string;
}

/** Every input column of every decision table in the graph. */
export function inputColumns(
  graph: Graph & { nodes?: Array<GraphNode & { id?: string }> }
): InputColumn[] {
  const columns: InputColumn[] = [];
  for (const node of graph.nodes ?? []) {
    if (node.type !== "decisionTableNode") continue;
    for (const column of ((node.content ?? {}) as TableContent).inputs ?? []) {
      columns.push({
        nodeId: node.id ?? "",
        nodeName: node.name ?? "Decision table",
        columnId: column.id ?? "",
        field: column.field ?? "",
      });
    }
  }
  return columns;
}

/**
 * Point an input column at a field, or add a column for one. A column that was a
 * whole-record check loses its cells: they were written against the whole
 * record, and under a single field they would mean something else.
 */
export function setInputField<G extends Graph>(
  graph: G,
  nodeId: string,
  columnId: string | null,
  field: string
): G {
  return {
    ...graph,
    nodes: (graph.nodes ?? []).map((node) => {
      if ((node as GraphNode & { id?: string }).id !== nodeId) return node;
      const content = (node.content ?? {}) as TableContent;
      if (columnId === null) {
        const id = `in_${Math.random().toString(36).slice(2, 8)}`;
        return {
          ...node,
          content: { ...content, inputs: [...(content.inputs ?? []), { id, name: field, field }] },
        };
      }
      const previous = (content.inputs ?? []).find((c) => c.id === columnId);
      const wasWholeRecord = !previous?.field;
      return {
        ...node,
        content: {
          ...content,
          inputs: (content.inputs ?? []).map((c) =>
            c.id === columnId ? { ...c, field, name: field, fieldType: undefined } : c
          ),
          rules: wasWholeRecord
            ? (content.rules ?? []).map((row) => ({ ...row, [columnId]: "" }))
            : content.rules,
        },
      };
    }),
  };
}

/**
 * A stored workflow, read into the shape the workflow editors edit — and written back.
 *
 * A workflow is stored as a Mermaid diagram plus the few fields that ride on the
 * `%%workflow` directive. The modelling tool keeps that in the project's EML document; a
 * generated application keeps the same text in its workflow definitions. Either host reads
 * and writes it through these two functions, so a lifecycle, a status machine or a process
 * opens the same way in both and saves the same bytes.
 */

import { emptyStateFlow } from "../../components/eml/StateFlowCanvas";
import {
  type EditableWorkflow,
  emitWorkflowDiagram,
  pascalWorkflowName,
  type WorkflowKind,
} from "../../components/eml/WorkflowEditor";
import { parseAutomation } from "../automation/model";
import { emptySagaFlow, parseHookWorkflow, parseSagaFlow, parseStateFlow } from "./workflow-flow";

/** A workflow as the model stores it. */
export interface StoredWorkflow {
  name: string;
  entity: string;
  kind: string;
  trigger?: "automatic" | "rule";
  operation?: "CREATE" | "UPDATE" | "DELETE" | "ALL";
  /** Hook and saga only: the state whose entering move runs this workflow. */
  status?: string;
  title?: string;
  diagram: string;
}

let counter = 0;
/** A key that stays with an item across renames, so React keeps the row being edited. */
export const newEditorKey = () => `k${(counter++).toString(36)}${Date.now().toString(36)}`;

export function toEditableWorkflow(workflow: StoredWorkflow): EditableWorkflow {
  const kind: WorkflowKind =
    workflow.kind === "state" || workflow.kind === "saga" ? workflow.kind : "hook";
  const saga = kind === "saga" ? parseSagaFlow(workflow.diagram) : emptySagaFlow();
  const parsed =
    kind === "hook" || kind === "saga" ? parseAutomation(workflow.diagram, workflow.entity) : null;
  return {
    key: newEditorKey(),
    name: workflow.name,
    entity: workflow.entity,
    kind,
    title: workflow.title,
    hooks: kind === "hook" ? parseHookWorkflow(workflow.diagram) : [],
    states: kind === "state" ? parseStateFlow(workflow.diagram) : emptyStateFlow(),
    // A hook workflow is many handlers on different events, which is the multi-trigger
    // shape the automation ladder carries. It reads and writes the same `%%hook`
    // directives, so this is a change of editor, not of artifact.
    ...(parsed
      ? {
          automation: {
            ...parsed,
            kind: kind as "hook" | "saga",
            name: workflow.title ?? workflow.name,
            trigger: { ...parsed.trigger, entity: workflow.entity },
            // Carried beside the diagram for a hook (its directive is composed, not drawn)
            // and inside it for a saga; either way one value reaches the editor.
            onStatus: workflow.status ?? parsed.onStatus,
            // For a saga these ride on the %%workflow directive, so they reach us beside
            // the diagram rather than inside it. Absent means automatic: the composer only
            // ever writes the token for `rule`.
            ...(kind === "saga"
              ? {
                  sagaTrigger: workflow.trigger ?? "automatic",
                  sagaOperation: workflow.operation ?? saga.operation,
                }
              : {}),
          },
        }
      : {}),
    saga: {
      ...saga,
      trigger: workflow.trigger ?? saga.trigger,
      operation: workflow.operation ?? saga.operation,
    },
  };
}

/** What a workflow is saved as. */
export function workflowForSave(workflow: EditableWorkflow): StoredWorkflow {
  return {
    name: pascalWorkflowName(workflow.title ?? workflow.name),
    entity: workflow.entity,
    kind: workflow.kind,
    title: workflow.title,
    ...(workflow.kind !== "state" && workflow.automation?.onStatus
      ? { status: workflow.automation.onStatus }
      : {}),
    ...(workflow.kind === "saga"
      ? {
          trigger: workflow.automation?.sagaTrigger ?? workflow.saga.trigger,
          operation: workflow.automation?.sagaOperation ?? workflow.saga.operation,
        }
      : {}),
    diagram: emitWorkflowDiagram(workflow),
  };
}

/**
 * What the rule editor needs around a graph: the node and edge shapes, the
 * sample record the Try-it panel opens with, and a flat decision table drawn as
 * the smallest graph that runs it.
 */

import type { DecisionRow, DecisionTable } from "./decision-table";

/** Fields the application manages itself — never a good example to check. */
const MANAGED = new Set(["id", "version", "created_at", "updated_at", "created_by", "updated_by"]);

type Node = {
  id: string;
  name: string;
  type: string;
  position: { x: number; y: number };
  content?: unknown;
};
type Edge = { id: string; type: "edge"; sourceId: string; targetId: string; sourceHandle?: string };

export interface TemplateGraph {
  nodes: Node[];
  edges: Edge[];
}

/** A believable value for a field, by its name — a starting point to edit, not a schema. */
function sampleValue(
  field: string,
  enumValues: string[] | undefined,
  type: "string" | "number" | "boolean" | undefined
): unknown {
  if (enumValues?.length) return enumValues[0];
  // The declared type wins over a guess from the name: a number field the name
  // does not hint at (`annual_revenue`) started as "" and failed the Record's
  // own schema before the rule ran.
  if (type === "number") return 0;
  if (type === "boolean") return false;
  if (/(^|_)(is|has|can)_/.test(field)) return false;
  if (/(_at|_on|date)$/.test(field)) return new Date().toISOString().slice(0, 10);
  if (/(amount|total|price|qty|quantity|count|balance|fee|credit|cost|score|age)/.test(field)) {
    return 0;
  }
  return "";
}

/** The sample record the Try-it panel opens with: one entry per editable field. */
export function sampleRecord(
  fields: string[],
  enums: Record<string, string[]> = {},
  types: Record<string, "string" | "number" | "boolean"> = {}
): Record<string, unknown> {
  return Object.fromEntries(
    fields
      .filter((f) => !MANAGED.has(f))
      .map((field) => [field, sampleValue(field, enums[field], types[field])])
  );
}

/* -------------------------------------------------------------------------- */
/*  Cell quoting for the zen decision-table engine                             */
/* -------------------------------------------------------------------------- */

/** Wrap a value as a zen single-quoted string literal. */
function zenLiteralCell(value: string): string {
  return `'${value.replace(/'/g, "\\'")}'`;
}

/** True when the value is already a zen string literal (`'…'` or `"…"`). */
function isAlreadyQuoted(value: string): boolean {
  return (
    value.length >= 2 &&
    (value.startsWith("'") || value.startsWith('"')) &&
    value.endsWith(value[0] as string)
  );
}

/** True when the value is a bare zen literal: null, true, false, or a number. */
function isBareLiteral(value: string): boolean {
  return (
    value === "true" ||
    value === "false" ||
    value === "null" ||
    (value !== "" && !Number.isNaN(Number(value)))
  );
}

/**
 * Quote an output cell value for the zen decision-table engine.
 *
 * The editor stores plain text (`validation-error`, `transform`).  Zen
 * evaluates those as identifier expressions — field references — and finds
 * nothing, so no output field is written.  Wrapping them as zen string
 * literals makes them constant values instead.
 */
function quotedOutputCell(raw: string): string {
  const value = raw.trim();
  if (!value || isAlreadyQuoted(value) || isBareLiteral(value)) return value;
  return zenLiteralCell(value);
}

/**
 * Quote an input cell value for the zen decision-table engine.
 *
 * Leading comparison operators (`>= 0`, `< 1`, `!= null`) are preserved;
 * bare string values like `submitted` are quoted to `'submitted'` so zen
 * treats them as equality checks, not field references.
 */
function quotedInputCell(raw: string): string {
  const value = raw.trim();
  if (!value) return "";
  const match = value.match(/^(>=|<=|!=|=|>|<)\s*(.*)/);
  if (match) {
    const [, op, operand] = match as [string, string, string];
    const cell = quotedOutputCell(operand);
    return op === "=" ? cell : `${op} ${cell}`;
  }
  return quotedOutputCell(value);
}

/** A flat decision table as the smallest graph that runs it: Input → Table → Output. */
export function tableToGraph(table: DecisionTable, name: string): TemplateGraph {
  const quotedRules: DecisionRow[] = table.rules.map((row) => {
    const quoted: DecisionRow = { _id: row._id };
    for (const input of table.inputs) quoted[input.id] = quotedInputCell(row[input.id] ?? "");
    for (const output of table.outputs) quoted[output.id] = quotedOutputCell(row[output.id] ?? "");
    return quoted;
  });

  return {
    nodes: [
      { id: "input-1", name: "Record", type: "inputNode", position: { x: 80, y: 200 } },
      {
        id: "dt-1",
        name: name || "Decision",
        type: "decisionTableNode",
        position: { x: 340, y: 200 },
        content: { ...table, rules: quotedRules },
      },
      { id: "output-1", name: "Response", type: "outputNode", position: { x: 680, y: 200 } },
    ],
    edges: [
      { id: "e1", type: "edge", sourceId: "input-1", targetId: "dt-1" },
      { id: "e2", type: "edge", sourceId: "dt-1", targetId: "output-1" },
    ],
  };
}

/**
 * How a workflow and the rules attached to it relate.
 *
 * A rule is written once, on the Enhance step, with no "runs when" of its own.
 * What makes it run is a workflow: the workflow names the hooks it listens on,
 * and attaching a rule to one of those hooks is what gives the rule its event.
 * The model still stores `%%rule … event: …` — that is the one thing the
 * generated application reads — so attaching is a write to the rule's `event`,
 * and "attached to" is read back as the same entity and the same event.
 */

import { type AutomationHook, type HookEvent, newHook } from "../automation/model";
import type { StateFlow } from "./workflow-flow";

/**
 * The hooks a rule can be judged at. The generated application reads a rule's
 * event only as create, update, delete or any write, so a hook outside this
 * list (a read, a list) has nowhere to run a rule.
 */
export const RULE_HOOKS = [
  "beforeCreate",
  "afterCreate",
  "beforeUpdate",
  "afterUpdate",
  "beforeDelete",
  "customValidate",
] as const satisfies readonly HookEvent[];

export type RuleHook = (typeof RULE_HOOKS)[number];

export function canAttachRules(event: string): event is RuleHook {
  return (RULE_HOOKS as readonly string[]).includes(event);
}

export interface HookChoice {
  event: HookEvent;
  label: string;
  hint: string;
  group: "Writes" | "Reads";
}

/** Every hook type a workflow can attach to, as the start dropdown lists them. */
export const HOOK_CHOICES: readonly HookChoice[] = [
  {
    event: "beforeCreate",
    label: "Before a record is created",
    hint: "Check or prepare it.",
    group: "Writes",
  },
  {
    event: "afterCreate",
    label: "After a record is created",
    hint: "React to the new record.",
    group: "Writes",
  },
  {
    event: "beforeUpdate",
    label: "Before a record is changed",
    hint: "Check the change.",
    group: "Writes",
  },
  {
    event: "afterUpdate",
    label: "After a record is changed",
    hint: "Audit or notify.",
    group: "Writes",
  },
  {
    event: "beforeDelete",
    label: "Before a record is deleted",
    hint: "Block or confirm it.",
    group: "Writes",
  },
  {
    event: "afterDelete",
    label: "After a record is deleted",
    hint: "Clean up after it.",
    group: "Writes",
  },
  {
    event: "customValidate",
    label: "On any write",
    hint: "Cross-field business checks.",
    group: "Writes",
  },
  {
    event: "beforeRead",
    label: "Before one record is read",
    hint: "Guard a single read.",
    group: "Reads",
  },
  {
    event: "afterRead",
    label: "After one record is read",
    hint: "Redact or enrich it.",
    group: "Reads",
  },
  { event: "beforeQuery", label: "Before a query runs", hint: "Scope the query.", group: "Reads" },
  {
    event: "afterQuery",
    label: "After a query runs",
    hint: "Post-process the rows.",
    group: "Reads",
  },
  {
    event: "beforeList",
    label: "Before a list is built",
    hint: "Filtering, sorting, paging.",
    group: "Reads",
  },
  {
    event: "afterList",
    label: "After a list is built",
    hint: "Post-process a page.",
    group: "Reads",
  },
];

/** `Lead` + `beforeCreate` → `leadBeforeCreate`, a valid handler name. */
export function defaultHandlerName(entity: string, event: string): string {
  const head = entity.replace(/[^A-Za-z0-9]+/g, "");
  const first = head.charAt(0).toLowerCase() + head.slice(1);
  const tail = event.charAt(0).toUpperCase() + event.slice(1);
  return `${first || "record"}${tail}`;
}

/** A new workflow attaches to one hook; more can be added on its ladder. */
export function hookFor(entity: string, event: HookEvent): AutomationHook {
  return { ...newHook(event), handler: defaultHandlerName(entity, event) };
}

export interface AttachableRule {
  key: string;
  name: string;
  title?: string;
  entity: string;
  event: string;
}

/**
 * Whether two events are the same moment for a rule. The model stores a rule's
 * exact event; an application that keeps only the write it judges (create,
 * update, delete, any) passes `sameOperation`, so a rule attached to
 * `afterCreate` is found under `beforeCreate` too.
 */
export type SameMoment = (ruleEvent: string, hookEvent: string) => boolean;

const sameEvent: SameMoment = (ruleEvent, hookEvent) => ruleEvent === hookEvent;

export type RuleOperation = "CREATE" | "UPDATE" | "DELETE" | "ALL";

/** The write a hook belongs to — what a generated application stores of "runs when". */
export function operationForEvent(event: string): RuleOperation {
  const name = event.toLowerCase();
  if (name.includes("create")) return "CREATE";
  if (name.includes("update")) return "UPDATE";
  if (name.includes("delete")) return "DELETE";
  return "ALL";
}

/** The hook a stored operation is shown at, when nothing says which of its hooks. */
export function eventForOperation(operation: string): RuleHook {
  switch (operation) {
    case "UPDATE":
      return "beforeUpdate";
    case "DELETE":
      return "beforeDelete";
    case "ALL":
      return "customValidate";
    default:
      return "beforeCreate";
  }
}

export const sameOperation: SameMoment = (ruleEvent, hookEvent) =>
  operationForEvent(ruleEvent) === operationForEvent(hookEvent);

/** The rules that run at `event` on `entity` — what is attached to that hook. */
export function rulesAttachedTo<R extends AttachableRule>(
  rules: readonly R[],
  entity: string,
  event: string,
  same: SameMoment = sameEvent
): R[] {
  return rules.filter((rule) => rule.entity === entity && same(rule.event, event));
}

/**
 * Rules of `entity` that run somewhere other than `event` — offered to attach,
 * with the hook they would be moved from, because a rule has one event.
 */
export function rulesAvailableFor<R extends AttachableRule>(
  rules: readonly R[],
  entity: string,
  event: string,
  same: SameMoment = sameEvent
): R[] {
  return rules.filter((rule) => rule.entity === entity && !same(rule.event, event));
}

/* -------------------------------------------------------------------------- */
/*  A hook and a status together                                              */
/* -------------------------------------------------------------------------- */

/**
 * The hooks a status can be bound to. A move is an update of the record, so a
 * create, delete or read has no status to enter.
 */
export const STATUS_HOOKS = ["beforeUpdate", "afterUpdate"] as const satisfies readonly HookEvent[];

export function canBindStatus(event: string): boolean {
  return (STATUS_HOOKS as readonly string[]).includes(event);
}

/** `To Be Reviewed`, `to-be-reviewed` and `to_be_reviewed` name one state. */
export function stateToken(name: string): string {
  return name.trim().toLowerCase().replace(/[\s-]+/g, "_");
}

/**
 * What a person reads for a state: `closed_won` → "Closed won", `QUALIFICATION`
 * → "Qualification". The same words the record's button shows (`moveLabel` in
 * `language/state-field.ts`, which this package cannot import), so the picker
 * names the status the way the button that enters it does.
 */
export function statusLabel(name: string): string {
  const words = name.replace(/[_-]+/g, " ").replace(/\s+/g, " ").trim();
  const text = words === words.toUpperCase() ? words.toLowerCase() : words;
  return text.charAt(0).toUpperCase() + text.slice(1);
}

/**
 * How a workflow is stored when it is bound to a state: the generated
 * application's workflow runner selects by this exact (upper-cased) operation
 * when a button moves a record into the state.
 */
export function statusOperation(status: string): string {
  return `ENTER:${stateToken(status).toUpperCase()}`;
}

/** The state a stored `ENTER:<STATE>` operation names, in the machine's own spelling. */
export function statusFromOperation(operation: string | undefined): string | undefined {
  const match = operation?.match(/^ENTER:(.+)$/i);
  return match?.[1] ? stateToken(match[1]) : undefined;
}

/**
 * What an entity can be bound to. With a status machine, the states some arrow
 * enters. Without one the entity has Draft and Final only: its update workflows
 * already run in the second transaction on the way to Final, so there is
 * nothing to choose.
 */
export type StatusChoices =
  | { kind: "machine"; states: Array<{ value: string; label: string }> }
  | { kind: "default" };

export function statusChoicesFor(
  entity: string,
  workflows: ReadonlyArray<{ entity: string; kind: string; states: StateFlow }>
): StatusChoices {
  const machines = workflows.filter((w) => w.kind === "state" && w.entity === entity);
  if (machines.length === 0) return { kind: "default" };
  const seen = new Set<string>();
  const states: Array<{ value: string; label: string }> = [];
  for (const machine of machines) {
    for (const transition of machine.states.transitions) {
      const value = stateToken(transition.to);
      if (!value || seen.has(value)) continue;
      seen.add(value);
      const named = machine.states.states.find((state) => state.id === transition.to);
      states.push({ value, label: statusLabel(named?.name || transition.to) });
    }
  }
  return { kind: "machine", states };
}

/**
 * Reading a hand-authored `%%rule` flowchart as a decision table.
 *
 * The rule editor can only edit tables it wrote itself, so every rule in the
 * checked-in example models opens read-only with an offer to convert that
 * threw the logic away and asked the author to retype it. Most of those rules
 * do not need retyping: a decision tree and a decision table say the same
 * thing, and the translation is mechanical.
 *
 * A tree becomes a table by walking every root-to-leaf path in order. Each
 * path is one row, carrying only the *positive* tests along it — under
 * `hitPolicy: "first"` the rows above already account for the negative
 * branches, which is how a person writes the table by hand. So
 *
 *     B{tier == strategic?} -->|Yes| C{type == incident?}
 *     C -->|Yes| D[Set priority critical]
 *     C -->|No|  E[Set priority high]
 *     B -->|No|  F[Set priority low]
 *
 * is three rows: (strategic, incident) → critical, (strategic) → high, and a
 * catch-all → low.
 *
 * What it will not do is guess. A leaf that does not state a field and a value
 * has no honest table cell, and `leadScoring` — which adds points across three
 * dimensions and grades the sum — is not a table at all, because a first-match
 * row cannot carry an accumulator. Those still open read-only, now saying which
 * leaf stopped the conversion rather than a blanket "branches are not carried
 * over".
 */

import {
  type DecisionColumn,
  type DecisionRow,
  type DecisionTable,
  newRowId,
} from "./decision-table";

/* -------------------------------------------------------------------------- */
/*  A very small flowchart reader                                              */
/* -------------------------------------------------------------------------- */

type Shape = "diamond" | "rect" | "stadium" | "circle" | "round";

interface Node {
  id: string;
  label: string;
  shape: Shape;
}

interface Edge {
  from: string;
  to: string;
  label?: string;
}

/**
 * Only what this conversion needs, so the client bundle does not have to pull
 * in `@appwithai/generator` — which is Node-only and externalised from it.
 */
export function readFlowchart(source: string): { nodes: Map<string, Node>; edges: Edge[] } {
  const nodes = new Map<string, Node>();
  const edges: Edge[] = [];

  const define = (id: string, body: string | undefined): void => {
    if (!body) {
      if (!nodes.has(id)) nodes.set(id, { id, label: id, shape: "rect" });
      return;
    }
    const shapes: Array<[RegExp, Shape]> = [
      [/^\(\[(.*)\]\)$/, "stadium"],
      [/^\(\((.*)\)\)$/, "circle"],
      [/^\{(.*)\}$/, "diamond"],
      [/^\[(.*)\]$/, "rect"],
      [/^\((.*)\)$/, "round"],
    ];
    for (const [pattern, shape] of shapes) {
      const match = body.match(pattern);
      if (match) {
        nodes.set(id, { id, label: (match[1] ?? "").trim(), shape });
        return;
      }
    }
    if (!nodes.has(id)) nodes.set(id, { id, label: id, shape: "rect" });
  };

  // `A[Label] -->|Yes| B{Other}` — the two node definitions and the edge label.
  const line =
    /^([A-Za-z_]\w*)\s*(\(\[.*?\]\)|\(\(.*?\)\)|\{.*?\}|\[.*?\]|\(.*?\))?\s*-->\s*(?:\|([^|]*)\|)?\s*([A-Za-z_]\w*)\s*(\(\[.*?\]\)|\(\(.*?\)\)|\{.*?\}|\[.*?\]|\(.*?\))?\s*$/;

  for (const raw of (source ?? "").split("\n")) {
    const text = raw.trim();
    if (!text || text.startsWith("%%") || /^flowchart\b/.test(text)) continue;

    const match = text.match(line);
    if (match) {
      const [, from, fromBody, edgeLabel, to, toBody] = match;
      define(from as string, fromBody);
      define(to as string, toBody);
      edges.push({ from: from as string, to: to as string, label: edgeLabel?.trim() });
      continue;
    }

    // A bare node definition on its own line.
    const alone = text.match(
      /^([A-Za-z_]\w*)\s*(\(\[.*?\]\)|\(\(.*?\)\)|\{.*?\}|\[.*?\]|\(.*?\))\s*$/
    );
    if (alone) define(alone[1] as string, alone[2]);
  }

  return { nodes, edges };
}

/* -------------------------------------------------------------------------- */
/*  Conditions                                                                 */
/* -------------------------------------------------------------------------- */

export interface ParsedCondition {
  field: string;
  /** Written the way the table editor writes it: an operator, or bare for `=`. */
  cell: string;
}

const OPERATORS = [">=", "<=", "!=", "==", "=", ">", "<"] as const;

/** `employee_count >= 1000?` → field `employee_count`, cell `>= 1000`. */
export function parseCondition(label: string): ParsedCondition | null {
  const text = label.trim().replace(/\?+$/, "").trim();
  if (!text) return null;

  for (const operator of OPERATORS) {
    const at = text.indexOf(operator);
    if (at <= 0) continue;
    const field = normalizeField(text.slice(0, at));
    const value = text.slice(at + operator.length).trim();
    if (!field || !value) return null;
    // `==` and `=` are equality, which the table writes as a bare value.
    const written = operator === "==" || operator === "=" ? value : `${operator} ${value}`;
    return { field, cell: written };
  }
  return null;
}

/** `account tier` and `Account Tier` both name the column `account_tier`. */
function normalizeField(raw: string): string {
  return raw
    .trim()
    .replace(/[^A-Za-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .toLowerCase();
}

/* -------------------------------------------------------------------------- */
/*  Outcomes                                                                   */
/* -------------------------------------------------------------------------- */

export interface ParsedOutcome {
  /** Output field → cell value, e.g. `{ field: "rating", value: "hot" }`. */
  cells: Record<string, string>;
}

/**
 * The two leaf shapes that state what they do rather than describe it.
 *
 * `Set priority critical` names a field and a value. `Reject: <why>` is a
 * validation error carrying its message. Anything else — "Route to Partner
 * Desk", "Add 35 firmographic points" — is a description, and inventing a
 * field for it would put words in the author's mouth.
 */
export function parseOutcome(label: string): ParsedOutcome | null {
  const text = label.trim();

  const reject = text.match(/^(?:Reject|Block|Refuse)\s*[:\-—]\s*(.+)$/i);
  if (reject?.[1]) {
    return { cells: { action: "validation-error", message: reject[1].trim() } };
  }

  // `Set probability 100 and category closed` — more than one assignment.
  if (/^Set\s+/i.test(text)) {
    const cells: Record<string, string> = {};
    for (const clause of text.replace(/^Set\s+/i, "").split(/\s+and\s+/i)) {
      const pair = clause.trim().match(/^([A-Za-z][\w ]*?)\s+(?:to\s+)?([\w.'"-]+)$/);
      if (!pair?.[1] || !pair[2]) return null;
      cells[normalizeField(pair[1])] = pair[2].replace(/^['"]|['"]$/g, "");
    }
    return Object.keys(cells).length ? { cells } : null;
  }

  return null;
}

/* -------------------------------------------------------------------------- */
/*  The walk                                                                   */
/* -------------------------------------------------------------------------- */

export type ConversionResult =
  | { ok: true; table: DecisionTable; notes: string[] }
  | { ok: false; reason: string };

const YES = /^(yes|y|true)$/i;
const NO = /^(no|n|false)$/i;

interface Branch {
  field: string;
  cell: string;
}

/**
 * Turn a rule's flowchart into a table, or say why it cannot be one.
 *
 * `knownFields` is the entity's columns. A test against something that is not
 * a column still converts — the author may be reading a joined value — but it
 * is reported, because a column the record does not have will never match.
 */
export function convertFlowchartToTable(
  flowchart: string,
  knownFields: string[] = []
): ConversionResult {
  const { nodes, edges } = readFlowchart(flowchart);
  if (!nodes.size) return { ok: false, reason: "There is no diagram here to read." };

  const outgoing = new Map<string, Edge[]>();
  for (const edge of edges) {
    const list = outgoing.get(edge.from) ?? [];
    list.push(edge);
    outgoing.set(edge.from, list);
  }

  const start = findStart(nodes, edges);
  if (!start) return { ok: false, reason: "The diagram has no single starting point." };

  const firstDecision = walkToDecision(start, nodes, outgoing);
  if (!firstDecision) {
    return { ok: false, reason: "The diagram asks no questions, so there is nothing to tabulate." };
  }

  const inputOrder: string[] = [];
  const rows: Array<{ branches: Branch[]; cells: Record<string, string> }> = [];
  const outputOrder: string[] = [];
  let failure: string | null = null;
  /** Depth guard: a cycle would otherwise walk forever. */
  const visiting = new Set<string>();

  const visit = (nodeId: string, branches: Branch[]): void => {
    if (failure) return;
    if (visiting.has(nodeId)) {
      failure = "The diagram loops back on itself, which a table cannot express.";
      return;
    }

    const node = nodes.get(nodeId);
    if (!node) return;

    if (node.shape === "diamond") {
      const condition = parseCondition(node.label);
      if (!condition) {
        failure = `"${node.label}" is not a comparison this can read as a column and a value.`;
        return;
      }
      if (!inputOrder.includes(condition.field)) inputOrder.push(condition.field);

      const branchEdges = outgoing.get(nodeId) ?? [];
      const yes = branchEdges.find((e) => YES.test(e.label ?? ""));
      const no = branchEdges.find((e) => NO.test(e.label ?? ""));
      if (!yes || !no) {
        failure = `"${node.label}" does not have both a Yes and a No branch.`;
        return;
      }

      visiting.add(nodeId);
      // Yes first: the table is read top to bottom, and the positive branch is
      // the more specific one, so it has to be the earlier row.
      visit(yes.to, [...branches, { field: condition.field, cell: condition.cell }]);
      visit(no.to, branches);
      visiting.delete(nodeId);
      return;
    }

    // Not a question. Either it states an outcome, or the path runs on to one.
    const outcome = parseOutcome(node.label);
    if (outcome) {
      for (const key of Object.keys(outcome.cells)) {
        if (!outputOrder.includes(key)) outputOrder.push(key);
      }
      rows.push({ branches, cells: outcome.cells });
      return;
    }

    const next = outgoing.get(nodeId) ?? [];

    // Only a Start/End marker is allowed to be walked through. Following any
    // other unreadable node would drop what it does while keeping the tests
    // around it — which is how `leadScoring` first converted to 54 confident,
    // wrong rows: each `Add 35 firmographic points` vanished, leaving a
    // `score >= 70` test against a score nothing had computed.
    if (node.shape === "stadium") {
      if (next.length === 0) return;
      if (next.length === 1 && next[0]) {
        visiting.add(nodeId);
        visit(next[0].to, branches);
        visiting.delete(nodeId);
        return;
      }
    }

    failure =
      `"${node.label}" does not say which field it sets. ` +
      `A table row has to name a column and a value.`;
  };

  visit(firstDecision, []);

  if (failure) return { ok: false, reason: failure };
  if (!rows.length) return { ok: false, reason: "No outcome in the diagram could be read." };

  const inputs: DecisionColumn[] = inputOrder.map((field, index) => ({
    id: `i${index + 1}`,
    name: field,
    field,
  }));
  const outputs: DecisionColumn[] = outputOrder.map((field, index) => ({
    id: `o${index + 1}`,
    name: field,
    field,
  }));

  const tableRows: DecisionRow[] = rows.map((row) => {
    const cells: DecisionRow = { _id: newRowId() };
    for (const column of inputs) {
      cells[column.id] = row.branches.find((b) => b.field === column.field)?.cell ?? "";
    }
    for (const column of outputs) cells[column.id] = row.cells[column.field] ?? "";
    return cells;
  });

  const notes: string[] = [];
  const unknown = inputOrder.filter((field) => knownFields.length && !knownFields.includes(field));
  if (unknown.length) {
    notes.push(
      `${unknown.join(", ")} ${unknown.length === 1 ? "is not a column" : "are not columns"} on this entity — check the name before saving.`
    );
  }
  // No coverage note here on purpose. Every diamond is walked down both arms,
  // so the all-No path always ends at a leaf carrying no positive test — the
  // last row is a catch-all by construction, and a warning about it could
  // never fire.

  return {
    ok: true,
    notes,
    table: { hitPolicy: "first", inputs, outputs, rules: tableRows },
  };
}

/** The node nothing points at — the diagram's entry. */
function findStart(nodes: Map<string, Node>, edges: Edge[]): string | null {
  const targeted = new Set(edges.map((edge) => edge.to));
  const roots = [...nodes.keys()].filter((id) => !targeted.has(id));
  return roots.length === 1 ? (roots[0] as string) : (roots[0] ?? null);
}

/** Skip the Start marker and any preamble to the first question. */
function walkToDecision(
  from: string,
  nodes: Map<string, Node>,
  outgoing: Map<string, Edge[]>
): string | null {
  let current: string | undefined = from;
  const seen = new Set<string>();

  while (current && !seen.has(current)) {
    seen.add(current);
    if (nodes.get(current)?.shape === "diamond") return current;
    const next: Edge[] = outgoing.get(current) ?? [];
    if (next.length !== 1) return null;
    current = next[0]?.to;
  }
  return null;
}

/**
 * Workflows, both directions.
 *
 * EML expresses a workflow two ways (spec/03-workflows.md):
 *
 *   hook   a flowchart annotated with `%%hook` directives binding named
 *          handlers to entity lifecycle events
 *   state  a `stateDiagram-v2` whose states become the entity's status enum
 *          and whose transitions define the allowed moves
 *
 * The hook form is a list, so it is edited as one. The state form is a graph,
 * so it gets a canvas. Both serialise back to the exact text a hand-written
 * workflow would use.
 */

import { parseHooksFromFlowchart } from "../workflow/hook-parser";

/* -------------------------------------------------------------------------- */
/*  Hook workflows                                                             */
/* -------------------------------------------------------------------------- */

/** The 13 lifecycle events, in the order they run. Matches the EML spec. */
export const HOOK_TYPES = [
  "beforeCreate",
  "afterCreate",
  "beforeUpdate",
  "afterUpdate",
  "beforeDelete",
  "afterDelete",
  "beforeRead",
  "afterRead",
  "beforeQuery",
  "afterQuery",
  "beforeList",
  "afterList",
  "customValidate",
] as const;

export type HookType = (typeof HOOK_TYPES)[number];

export const HOOK_HINTS: Record<string, string> = {
  beforeCreate: "Runs before a record is written — hash a password, set a default.",
  afterCreate: "Runs once the record exists — send a welcome email, emit an event.",
  beforeUpdate: "Validate or transform before the write.",
  afterUpdate: "Audit the change, invalidate a cache.",
  beforeDelete: "Block the delete if the record is still referenced.",
  afterDelete: "Clean up related rows or files.",
  beforeRead: "Guard a single-record read.",
  afterRead: "Redact or enrich a record on the way out.",
  beforeQuery: "Scope the query — tenant filters, injected conditions.",
  afterQuery: "Post-process the rows that came back.",
  beforeList: "Adjust filtering, sorting or pagination.",
  afterList: "Post-process a page of results.",
  customValidate: "Cross-field or business validation on any write.",
};

export interface WorkflowHook {
  id: string;
  type: HookType | string;
  /** Generated function name. */
  handler: string;
  /** Optional field the hook is scoped to. */
  field?: string;
}

/** Read the `%%hook` directives out of a hook workflow's diagram. */
export function parseHookWorkflow(diagram: string): WorkflowHook[] {
  const { hooks } = parseHooksFromFlowchart(diagram ?? "");
  return hooks.map((hook, index) => ({
    id: `h${index}_${hook.name}`,
    type: hook.type,
    handler: hook.name,
    field: hook.parameters?.find((parameter) => parameter.type === "field")?.name,
  }));
}

/**
 * Write a hook workflow.
 *
 * The flowchart is generated from the hooks, so the picture and the directives
 * can never disagree — the directives carry the meaning, and the diagram is how
 * a reader sees it. The steps are drawn as one chain in run order because that
 * is what actually happens at runtime.
 */
export function emitHookWorkflow(entity: string, hooks: WorkflowHook[]): string {
  const lines = ["flowchart TD", `    request[Request] --> validate[Validate ${entity}]`];

  let previous = "validate";
  hooks.forEach((hook, index) => {
    const id = `step${index + 1}`;
    lines.push(`    ${previous} --> ${id}[${hook.type}: ${hook.handler}]`);
    previous = id;
  });

  lines.push(
    `    ${previous} --> persist[Persist ${entity}]`,
    "    persist --> done[Response]",
    ""
  );

  for (const hook of hooks) {
    lines.push(
      `    %%hook ${hook.type} ${hook.handler} on ${entity}` +
        (hook.field ? `[field: ${hook.field}]` : "")
    );
  }

  return lines.join("\n");
}

export function validateHookWorkflow(entity: string, hooks: WorkflowHook[]): string[] {
  const problems: string[] = [];
  if (!entity) problems.push("Pick the entity this workflow runs for.");
  if (!hooks.length) problems.push("Add at least one lifecycle step.");

  const seen = new Set<string>();
  for (const hook of hooks) {
    if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(hook.handler)) {
      problems.push(`"${hook.handler || "(unnamed)"}" is not a valid handler name.`);
    }
    const key = `${hook.type}:${hook.handler}`;
    if (seen.has(key)) problems.push(`${hook.type} ${hook.handler} is listed twice.`);
    seen.add(key);
  }
  return problems;
}

/* -------------------------------------------------------------------------- */
/*  State workflows                                                            */
/* -------------------------------------------------------------------------- */

export interface StateNode {
  id: string;
  /** The state name, which becomes a status enum value. */
  name: string;
  position?: { x: number; y: number };
}

export interface StateTransition {
  id: string;
  from: string;
  to: string;
  /** Optional trigger label, e.g. `submit`. */
  label?: string;
  /**
   * The roles that may press this move — its `%%rbac role:… on <Entity>.<event>`
   * line. Empty: anyone who may update the record.
   */
  roles?: string[];
}

export interface StateFlow {
  states: StateNode[];
  transitions: StateTransition[];
  /** State the entity starts in — the `[*] --> x` transition. */
  initial?: string;
  /** States that end the process — `x --> [*]`. */
  terminal: string[];
  /** The roles that may reopen a Final record (`%%rbac … on <Entity>.reopen`). */
  reopenRoles?: string[];
  /** The entity the `%%rbac` move lines name, as read. */
  entity?: string;
  /** Any other `%%` line of the section, kept as written so a save loses nothing. */
  directives?: string[];
}

const START_MARKER = "[*]";
const RBAC_MOVE = /^%%rbac\s+(\S+)\s+on\s+([A-Za-z_]\w*)\.([A-Za-z_][\w-]*(?:->[A-Za-z_]\w*)?)\s*$/;

/** `close won`, `Close-Won` and `close_won` are one event. */
function oneToken(event: string): string {
  return event.trim().toLowerCase().replace(/[\s-]+/g, "_");
}

function rolesOf(expression: string): string[] {
  return expression
    .split("|")
    .map((part) => part.trim().replace(/^role:/i, "").trim())
    .filter(Boolean);
}

const CRUD_TARGETS = new Set(["create", "read", "update", "delete", "*", "write", "modify", "remove", "destroy", "view", "list", "get", "insert", "add", "edit"]);

/** Read a `stateDiagram-v2` into the editable model. */
export function parseStateFlow(diagram: string): StateFlow {
  const states = new Map<string, StateNode>();
  const transitions: StateTransition[] = [];
  const terminal: string[] = [];
  let initial: string | undefined;

  const ensure = (name: string) => {
    if (name === START_MARKER) return;
    if (!states.has(name)) states.set(name, { id: name, name });
  };

  let index = 0;
  const moveLines: Array<{ roles: string[]; entity: string; target: string; line: string }> = [];
  const directives: string[] = [];
  for (const rawLine of (diagram ?? "").split("\n")) {
    const line = rawLine.trim();
    if (line.startsWith("%%")) {
      const move = RBAC_MOVE.exec(line);
      if (move && !CRUD_TARGETS.has(move[3]!.toLowerCase())) {
        moveLines.push({ roles: rolesOf(move[1]!), entity: move[2]!, target: move[3]!, line });
      } else {
        directives.push(line);
      }
      continue;
    }
    if (!line || /^stateDiagram(-v2)?$/.test(line)) continue;

    // `from --> to : label`
    const match = line.match(
      /^(\[\*\]|[A-Za-z_][\w]*)\s*-->\s*(\[\*\]|[A-Za-z_][\w]*)\s*(?::\s*(.+))?$/
    );
    if (!match) continue;

    const [, from, to, label] = match as unknown as [string, string, string, string | undefined];
    ensure(from);
    ensure(to);

    if (from === START_MARKER) {
      initial = to;
      continue;
    }
    if (to === START_MARKER) {
      terminal.push(from);
      continue;
    }

    transitions.push({ id: `t${index++}_${from}_${to}`, from, to, label: label?.trim() });
  }

  // Left-to-right by reachability from the initial state, so the process reads
  // in the order it happens.
  const ordered = [...states.values()];
  const depth = new Map<string, number>();
  if (initial) depth.set(initial, 0);
  let changed = true;
  while (changed) {
    changed = false;
    for (const transition of transitions) {
      const fromDepth = depth.get(transition.from);
      if (fromDepth === undefined) continue;
      if (!depth.has(transition.to)) {
        depth.set(transition.to, fromDepth + 1);
        changed = true;
      }
    }
  }
  const perColumn = new Map<number, number>();
  for (const state of ordered) {
    const column = depth.get(state.id) ?? 0;
    const row = perColumn.get(column) ?? 0;
    perColumn.set(column, row + 1);
    // A state is ~150px wide; at 220 apart a move's label had 70px between two
    // states and ran into both ("accept_offer" over offer_made and accepted).
    state.position = { x: 80 + column * 300, y: 60 + row * 140 };
  }

  // The %%rbac move lines: each names its edges by event or `from->to`, or is
  // Reopen. A line naming no drawn move is kept as written.
  let reopenRoles: string[] | undefined;
  let entity: string | undefined;
  for (const move of moveLines) {
    entity ??= move.entity;
    const arrow = /^(\w+)->(\w+)$/.exec(move.target);
    const matched = transitions.filter((transition) =>
      arrow
        ? transition.from === arrow[1] && transition.to === arrow[2]
        : !!transition.label && oneToken(transition.label) === oneToken(move.target)
    );
    if (matched.length > 0) {
      for (const transition of matched) {
        transition.roles = [...new Set([...(transition.roles ?? []), ...move.roles])];
      }
    } else if (!arrow && oneToken(move.target) === "reopen") {
      reopenRoles = [...new Set([...(reopenRoles ?? []), ...move.roles])];
    } else {
      directives.push(move.line);
    }
  }

  return {
    states: ordered,
    transitions,
    initial,
    terminal,
    ...(reopenRoles ? { reopenRoles } : {}),
    ...(entity ? { entity } : {}),
    ...(directives.length ? { directives } : {}),
  };
}

/**
 * Write the editable model back out as a `stateDiagram-v2`, followed by the
 * `%%rbac` line of every move given to roles and any other `%%` line the
 * section carried. `entity` names the record type the move lines are about.
 */
export function emitStateFlow(flow: StateFlow, entity = flow.entity): string {
  const lines = ["stateDiagram-v2"];

  // `initial`, `terminal` and a transition's `from`/`to` all hold state *ids*,
  // not names. `parseStateFlow` sets `id === name`, so an imported diagram
  // round-trips whichever one is written — but a state added in the editor gets
  // an opaque id like `smtd05euwc`, and writing that puts the id where the
  // status enum value belongs. Resolve to the name on the way out.
  const nameOf = new Map(flow.states.map((state) => [state.id, state.name] as const));
  const named = (ref: string) => nameOf.get(ref) ?? ref;

  if (flow.initial) lines.push(`    ${START_MARKER} --> ${named(flow.initial)}`);
  for (const transition of flow.transitions) {
    const label = transition.label?.trim();
    lines.push(
      `    ${named(transition.from)} --> ${named(transition.to)}${label ? ` : ${label}` : ""}`
    );
  }
  for (const state of flow.terminal) lines.push(`    ${named(state)} --> ${START_MARKER}`);

  // A state with no transitions at all would vanish; name it so it survives.
  const mentioned = new Set<string>();
  if (flow.initial) mentioned.add(flow.initial);
  for (const transition of flow.transitions) {
    mentioned.add(transition.from);
    mentioned.add(transition.to);
  }
  for (const state of flow.terminal) mentioned.add(state);
  for (const state of flow.states) {
    if (!mentioned.has(state.id)) lines.push(`    ${state.name}`);
  }

  // Who may press each move. Edges sharing an event share its line.
  const owner = entity?.trim();
  const moves = new Map<string, Set<string>>();
  for (const transition of flow.transitions) {
    const given = (transition.roles ?? []).map((role) => role.trim()).filter(Boolean);
    if (!given.length) continue;
    const label = transition.label?.trim();
    const target = label ? oneToken(label) : `${named(transition.from)}->${named(transition.to)}`;
    const roles = moves.get(target) ?? new Set<string>();
    for (const role of given) roles.add(role);
    moves.set(target, roles);
  }
  if (flow.reopenRoles?.length) moves.set("reopen", new Set(flow.reopenRoles));
  const extra = [
    ...(owner
      ? [...moves].map(([target, roles]) => `    %%rbac role:${[...roles].join("|")} on ${owner}.${target}`)
      : []),
    ...(flow.directives ?? []).map((line) => `    ${line}`),
  ];
  if (extra.length) lines.push("", ...extra);

  return lines.join("\n");
}

export function validateStateFlow(flow: StateFlow): string[] {
  const problems: string[] = [];
  if (!flow.states.length) return ["No states yet — add the first one."];
  if (!flow.initial) problems.push("No starting state — mark the state the entity begins in.");
  if (!flow.terminal.length) problems.push("No finishing state — mark at least one as an end.");

  for (const state of flow.states) {
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(state.name)) {
      problems.push(`"${state.name}" is not a valid status value (letters, digits, underscore).`);
    }
  }
  // Two states with one value are one node in the saved diagram: the second
  // one's transitions would silently join the first.
  const seen = new Set<string>();
  for (const state of flow.states) {
    if (seen.has(state.name)) {
      problems.push(`Two states are called "${state.name}" — give each state its own value.`);
    }
    seen.add(state.name);
  }
  return problems;
}

/* -------------------------------------------------------------------------- */
/*  Saga workflows — multi-step processes                                      */
/* -------------------------------------------------------------------------- */

/**
 * A saga is a flowchart whose nodes are bound to executable steps by `%%step`
 * directives. The generated executor runs them in the order the edges give, so
 * this editor keeps them as an ordered list and emits a straight chain: the
 * node ids are bookkeeping the author should never have to hold in their head.
 *
 * The vocabulary mirrors `workflowConstructs.stepNodes` in
 * `language/appwithai-language.json`, which is the canonical declaration.
 */
export const SAGA_STEP_TYPES = [
  "Decision",
  "Formula",
  "CreateEntity",
  "UpdateEntity",
  "DeleteEntity",
  "REST",
] as const;

export type SagaStepType = (typeof SAGA_STEP_TYPES)[number];

export const SAGA_STEP_HINTS: Record<SagaStepType, string> = {
  Decision: "Run a decision table and publish what it decides for later steps.",
  Formula: "Work out a value — or stage a literal — for a later step to use.",
  CreateEntity: "Insert a row. Name the variable its id lands in so a later step can reach it.",
  UpdateEntity: "Write one column, on this record or on a related one.",
  DeleteEntity: "Delete a record. Soft by default, so the audit trail still resolves.",
  REST: "Call an external endpoint.",
};

export const FORMULA_OPERATIONS = ["set", "copy", "multiply", "divide", "add", "subtract"] as const;

/** Which property fields each step type shows, in the order they read. */
export const SAGA_STEP_FIELDS: Record<SagaStepType, string[]> = {
  Decision: ["rule", "publish", "decisionTable"],
  Formula: ["target", "operation", "value", "source", "operand"],
  CreateEntity: ["entity", "fields", "as"],
  UpdateEntity: ["entity", "targetField", "targetSource", "field", "value", "source"],
  DeleteEntity: ["entity", "targetField", "targetSource", "hard"],
  REST: ["url", "method", "bodyTemplate"],
};

export const SAGA_FIELD_LABELS: Record<string, string> = {
  rule: "Evaluate the saved rule",
  publish: "Publish only these outputs",
  decisionTable: "Decision table (JSON)",
  entity: "Entity",
  field: "Column to write",
  value: "Literal value",
  source: "Read from variable",
  target: "Store in variable",
  targetField: "Match rows on column",
  targetSource: "…against this variable",
  operation: "Operation",
  operand: "Operand",
  as: "Bind new row id to",
  hard: "Hard delete",
  fields: "Columns to set (JSON)",
  url: "URL",
  method: "Method",
  bodyTemplate: "Body template",
};

export interface SagaStep {
  /** Stable across renames, so React keeps the row being edited. */
  id: string;
  type: SagaStepType;
  /** Node label, shown on the flowchart. */
  label: string;
  props: Record<string, string>;
}

export interface SagaFlow {
  steps: SagaStep[];
  /** `rule` means a business rule decides when this runs. */
  trigger: "automatic" | "rule";
  operation: "CREATE" | "UPDATE" | "DELETE" | "ALL";
}

export function emptySagaFlow(): SagaFlow {
  return { steps: [], trigger: "rule", operation: "CREATE" };
}

let sagaStepCounter = 0;
const nextSagaStepId = () => `s${(sagaStepCounter++).toString(36)}${Date.now().toString(36)}`;

/** Node id for the nth step. Positional, because the editor owns the order. */
function stepNodeId(index: number): string {
  return `S${index + 1}`;
}

/** `key: value` pairs, each value running to the next `key:` token. */
function parseStepProps(rest: string): Record<string, string> {
  const props: Record<string, string> = {};
  const trimmed = rest.trim();
  if (!trimmed) return props;
  for (const chunk of trimmed.split(/\s+(?=[A-Za-z_]\w*:)/)) {
    const at = chunk.indexOf(":");
    if (at <= 0) continue;
    const key = chunk.slice(0, at).trim();
    if (key) props[key] = chunk.slice(at + 1).trim();
  }
  return props;
}

/**
 * Read a saga flowchart back into the editable model.
 *
 * Steps come out in the order the edges chain them, so a document written by
 * hand — or by an earlier version of this editor — still opens in the order it
 * runs rather than in directive order.
 */
export function parseSagaFlow(diagram: string): SagaFlow {
  const declared = new Map<string, SagaStep>();
  const labels = new Map<string, string>();
  const next = new Map<string, string>();
  const hasIncoming = new Set<string>();

  const nodeLabel =
    /(?:^|[^\w])([A-Za-z_]\w*)\s*(?:\(\[([^\]]*)\]\)|\[([^\]]*)\]|\{([^}]*)\}|\(([^)]*)\))/g;
  const edge =
    /([A-Za-z_]\w*)\s*(?:\(\[[^\]]*\]\)|\[[^\]]*\]|\{[^}]*\}|\([^)]*\))?\s*(?:-->|---|==>)(?:\|[^|]*\|)?\s*([A-Za-z_]\w*)/g;

  for (const rawLine of (diagram ?? "").split("\n")) {
    const line = rawLine.trim();
    if (!line) continue;

    const step = line.match(/^%%step\s+([A-Za-z_]\w*)\s+([A-Za-z]\w*)\s*(.*)$/);
    if (step) {
      const [, nodeId, typeName, rest] = step as unknown as [string, string, string, string];
      if (!SAGA_STEP_TYPES.includes(typeName as SagaStepType)) continue;
      if (declared.has(nodeId)) continue;
      declared.set(nodeId, {
        id: nextSagaStepId(),
        type: typeName as SagaStepType,
        label: "",
        props: parseStepProps(rest ?? ""),
      });
      continue;
    }
    if (line.startsWith("%%")) continue;

    for (const match of line.matchAll(nodeLabel)) {
      const id = match[1]!;
      const text = (match[2] ?? match[3] ?? match[4] ?? match[5] ?? "").trim();
      if (text && !labels.has(id)) labels.set(id, text);
    }

    edge.lastIndex = 0;
    let match: RegExpExecArray | null;
    // Not matchAll: the body rewinds lastIndex so a chained `A --> B --> C`
    // yields both edges, and matchAll owns the cursor.
    // standard exec-loop idiom
    while ((match = edge.exec(line)) !== null) {
      const from = match[1]!;
      const to = match[2]!;
      if (!next.has(from)) next.set(from, to);
      hasIncoming.add(to);
      edge.lastIndex = match.index + match[0].length - to.length;
    }
  }

  // Walk the chain from its head so the list opens in execution order.
  const ordered: SagaStep[] = [];
  const seen = new Set<string>();
  const heads = [...next.keys()].filter((id) => !hasIncoming.has(id));
  for (const head of heads) {
    let cursor: string | undefined = head;
    while (cursor && !seen.has(cursor)) {
      seen.add(cursor);
      const step = declared.get(cursor);
      if (step) ordered.push({ ...step, label: labels.get(cursor) ?? step.label });
      cursor = next.get(cursor);
    }
  }
  for (const [id, step] of declared) {
    if (!seen.has(id)) ordered.push({ ...step, label: labels.get(id) ?? step.label });
  }

  return { steps: ordered, trigger: "rule", operation: "CREATE" };
}

/**
 * Write the editable model back out as a flowchart plus `%%step` directives.
 *
 * Emits a start and end terminal so the diagram reads as a process even before
 * any step is added, and so a reader can tell at a glance where it begins.
 */
export function emitSagaFlow(flow: SagaFlow): string {
  const lines = ["flowchart TD"];
  const ids = ["Start", ...flow.steps.map((_step, index) => stepNodeId(index)), "Done"];

  lines.push(`    Start([Start])`);
  flow.steps.forEach((step, index) => {
    const label = (step.label || step.type).replace(/[[\]{}()|]/g, " ").trim();
    lines.push(`    ${stepNodeId(index)}[${label}]`);
  });
  lines.push(`    Done([Done])`);
  lines.push("");
  for (let index = 0; index < ids.length - 1; index++) {
    lines.push(`    ${ids[index]} --> ${ids[index + 1]}`);
  }

  if (flow.steps.length) lines.push("");
  flow.steps.forEach((step, index) => {
    const JSON_PROPS = ["fields", "decisionTable"];
    const props = Object.entries(step.props)
      .filter(([key, value]) => value?.trim() && !JSON_PROPS.includes(key))
      .map(([key, value]) => `${key}: ${value.trim()}`);
    // JSON values go last — every other value ends at the next `key:` token,
    // and JSON is full of them. Only one of these is ever set on a step.
    for (const key of JSON_PROPS) {
      const value = step.props[key]?.trim();
      if (value) props.push(`${key}: ${value}`);
    }
    lines.push(
      `    %%step ${stepNodeId(index)} ${step.type}${props.length ? ` ${props.join(" ")}` : ""}`
    );
  });

  return lines.join("\n");
}

/**
 * The same requirements the checker enforces on the model and the executor
 * enforces at runtime, surfaced while the step is being drawn.
 */
export function validateSagaFlow(flow: SagaFlow): string[] {
  const problems: string[] = [];
  if (!flow.steps.length) return ["No steps yet — add the first one."];

  const published = new Set<string>();

  flow.steps.forEach((step, index) => {
    const at = `Step ${index + 1}`;
    const has = (key: string) => (step.props[key] ?? "").trim().length > 0;

    if (step.type === "Formula") {
      if (!has("target")) problems.push(`${at}: name the variable to store the result in.`);
      const operation = (step.props.operation ?? "").trim();
      if (!operation) problems.push(`${at}: choose an operation.`);
      else if (operation === "set" && !has("value")) problems.push(`${at}: give a value to stage.`);
      else if (operation === "copy" && !has("source"))
        problems.push(`${at}: name the variable to copy from.`);
      else if (operation !== "set" && operation !== "copy" && (!has("source") || !has("operand")))
        problems.push(`${at}: ${operation} needs both a source variable and an operand.`);
    }

    if (step.type === "CreateEntity") {
      if (!has("entity")) problems.push(`${at}: choose the entity to insert into.`);
      if (!has("fields")) problems.push(`${at}: set at least one column.`);
      else {
        try {
          const parsed = JSON.parse(step.props.fields!);
          if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error();
          if (!Object.keys(parsed).length) problems.push(`${at}: set at least one column.`);
        } catch {
          problems.push(`${at}: the columns must be a JSON object, e.g. {"status":"open"}.`);
        }
      }
    }

    if (step.type === "UpdateEntity") {
      if (!has("field")) problems.push(`${at}: choose the column to write.`);
      if (!has("value") && !has("source"))
        problems.push(`${at}: give a literal value or a variable to read from.`);
    }

    if (step.type === "REST" && !has("url")) problems.push(`${at}: give the URL to call.`);

    // The executor refuses a cross-entity write it cannot aim at a row.
    if (
      (step.type === "UpdateEntity" || step.type === "DeleteEntity") &&
      has("entity") &&
      !has("targetSource") &&
      (step.props.targetField ?? "id").trim() === "id"
    ) {
      problems.push(
        `${at}: say which row of ${step.props.entity} — a variable holding its id, or a foreign key column to match on.`
      );
    }

    const reference = (step.props.targetSource ?? "").trim();
    if (reference && !published.has(reference)) {
      problems.push(
        `${at}: nothing before it stores "${reference}" — unless that is a column of the triggering record.`
      );
    }

    if (step.type === "CreateEntity") {
      const bound =
        (step.props.as ?? "").trim() ||
        ((step.props.entity ?? "").trim()
          ? `${step.props.entity!.trim().replace(/^bus_/, "")}Id`
          : "");
      if (bound) published.add(bound);
    }
    if (step.type === "Formula" && has("target")) published.add(step.props.target!.trim());
  });

  return problems;
}

/**
 * What a rule's answer would do to the write, in a sentence.
 *
 * The application reads the final output row's `action` and nothing else
 * decides anything: a graph that computes a perfectly good `total` but never
 * says `action` refuses nothing, changes nothing and starts nothing. That is
 * the most likely way for a first rule to "not work", and it looks identical to
 * a rule that works and simply did not match — so the Try-it panel says which.
 */

export type OutcomeKind =
  | "blocks"
  | "workflow"
  | "changes"
  | "notifies"
  | "cascade"
  | "nothing"
  | "problem";

export interface Outcome {
  kind: OutcomeKind;
  text: string;
}

type Row = Record<string, unknown>;

const isRow = (value: unknown): value is Row =>
  typeof value === "object" && value !== null && !Array.isArray(value);

function asRecord(value: unknown): Row | null {
  if (isRow(value)) return value;
  if (typeof value === "string") {
    try {
      const parsed: unknown = JSON.parse(value);
      return isRow(parsed) ? parsed : null;
    } catch {
      return null;
    }
  }
  return null;
}

function describeRow(row: Row): Outcome {
  const raw = typeof row.action === "string" ? row.action.trim() : "";
  // The runtime accepts EML's word and its own; both mean "refuse".
  const action = raw === "validation-error" ? "prevent" : raw;
  const message = typeof row.message === "string" && row.message ? row.message : "";

  switch (action) {
    case "prevent":
      return {
        kind: "blocks",
        text: message ? `Blocks the write: “${message}”` : "Blocks the write (no message given).",
      };
    case "trigger-workflow": {
      const name = typeof row.workflowName === "string" ? row.workflowName.trim() : "";
      return name
        ? { kind: "workflow", text: `Starts the workflow “${name}” once the write is saved.` }
        : {
            kind: "problem",
            text: "Says trigger-workflow but names no Workflow Name, so nothing will start.",
          };
    }
    case "transform": {
      const data = asRecord(row.transformData);
      const keys = data ? Object.keys(data) : [];
      return keys.length
        ? { kind: "changes", text: `Changes ${keys.join(", ")} on the record.` }
        : {
            kind: "problem",
            text: "Says transform but carries no Transform Data (or Field and Value), so nothing will change.",
          };
    }
    case "notify":
    case "validate":
      return { kind: "notifies", text: message ? `Notes: “${message}”` : "Raises a note." };
    case "cascade-update":
    case "cascade-create":
    case "cascade-delete":
      return {
        kind: "cascade",
        text: `Runs ${action} on ${String(row.targetEntity ?? "a related record")}.`,
      };
    case "":
      return Object.keys(row).length
        ? {
            kind: "problem",
            text: "The rule returned values but no action, so the application does nothing with them. Add an output named action.",
          }
        : { kind: "nothing", text: "No row matched, so the write goes ahead." };
    case "allow":
      return { kind: "nothing", text: "Lets the write through." };
    default:
      return {
        kind: "problem",
        text: `The action “${action}” is not one the application knows (use validation-error, trigger-workflow or transform).`,
      };
  }
}

/** One line per row the rule returned; a single "nothing happens" line when none did. */
export function describeOutcome(result: unknown): Outcome[] {
  const rows = Array.isArray(result) ? result.filter(isRow) : isRow(result) ? [result] : [];
  if (!rows.length) return [{ kind: "nothing", text: "No row matched, so the write goes ahead." }];
  return rows.map(describeRow);
}

/**
 * What a rule or workflow must carry before it may be written into the model.
 *
 * A rule saved with no entity became `%%rule name on  event: …`, which the
 * checker reads as a rule on an entity called "event" — a warning, not an
 * error, so the model still checked clean while the rule could never fire.
 * The Logic page asks this before it sends, and the route asks it again
 * because the page is not its only caller.
 */

import { stateToken } from "./workflow-hooks";
import { parseStateFlow } from "./workflow-flow";

export interface SectionProblem {
  kind: "rule" | "workflow";
  index: number;
  message: string;
}

interface Named {
  name?: unknown;
  title?: unknown;
  entity?: unknown;
  kind?: unknown;
  /** Workflows only: the state this one is bound to. */
  status?: unknown;
  operation?: unknown;
  trigger?: unknown;
  /** A state machine's diagram, from which the states it enters are read. */
  diagram?: unknown;
}

const text = (value: unknown) => (typeof value === "string" ? value.trim() : "");

/**
 * A workflow bound to a state has to name one an arrow enters, and has to be one
 * an update starts — the same three conditions as EML243-EML245, in editor
 * words, so the page refuses it before the checker would.
 */
function statusProblems(workflows: readonly Named[]): SectionProblem[] {
  const problems: SectionProblem[] = [];
  workflows.forEach((workflow, index) => {
    const status = text(workflow.status);
    if (!status || workflow.kind === "state") return;
    const label = text(workflow.title) || text(workflow.name) || String(index + 1);
    const entity = text(workflow.entity);
    const wanted = stateToken(status);

    const machines = workflows.filter((w) => w.kind === "state" && text(w.entity) === entity);
    const entered = machines.flatMap((m) =>
      parseStateFlow(text(m.diagram)).transitions.map((t) => stateToken(t.to))
    );
    if (machines.length === 0) {
      problems.push({
        kind: "workflow",
        index,
        message: `Process "${label}" is bound to a status, but ${entity} has no status flow. Draw one, or remove the status.`,
      });
    } else if (!entered.includes(wanted)) {
      problems.push({
        kind: "workflow",
        index,
        message: `Process "${label}" is bound to "${status}", which no arrow in ${entity}'s status flow enters.`,
      });
    }
    if (workflow.kind === "saga" && (text(workflow.operation) !== "UPDATE" || workflow.trigger === "rule")) {
      problems.push({
        kind: "workflow",
        index,
        message: `Process "${label}" is bound to a status, so it must start on "Updated" — a move is an update.`,
      });
    }
  });
  return problems;
}

export function sectionProblems(
  rules: readonly Named[] = [],
  workflows: readonly Named[] = []
): SectionProblem[] {
  const problems: SectionProblem[] = [];
  const check = (kind: SectionProblem["kind"], items: readonly Named[]) => {
    const noun = kind === "rule" ? "Rule" : "Process";
    items.forEach((item, index) => {
      const label = text(item.title) || text(item.name);
      if (!label) {
        problems.push({ kind, index, message: `${noun} ${index + 1} has no name.` });
      }
      if (!text(item.entity)) {
        problems.push({
          kind,
          index,
          message: `${noun} "${label || index + 1}" has no entity. Choose the entity it runs on.`,
        });
      }
    });
  };
  check("rule", rules);
  check("workflow", workflows);
  problems.push(...statusProblems(workflows));
  return problems;
}

/**
 * What a rule may name, read from the model rather than typed.
 *
 * A rule's table says which field a check looks at, what a status may be, and
 * which process an answer starts. Each of those is something the model already
 * declares, so the editor offers exactly those and nothing else: the entity's
 * own fields, the values its enum or its state machine allows, and the
 * processes defined for it. A free-text cell lets a rule name a field or a
 * state that does not exist, and such a rule compiles, saves, and never fires.
 */

export interface RuleConstraints {
  /** The entity's own fields — what a check may look at. */
  fields: string[];
  /** Each field's JSON type, so the editor can complete and check what is written. */
  fieldTypes?: Record<string, "string" | "number" | "boolean">;
  /** Field → the only values it may hold: its enum, or its state machine's states. */
  values: Record<string, string[]>;
  /** Processes defined for the entity — what an answer may start. */
  workflowNames: string[];
}

export interface ConstraintWorkflow {
  name: string;
  title?: string;
  entity: string;
  kind: string;
  /** The states of a state machine, when `kind` is `state`. */
  stateNames?: string[];
}

/** Entity names and their attributes, read from the ERD for the pickers. */
export interface ReadEntity {
  name: string;
  attributes: string[];
  types: Record<string, "string" | "number" | "boolean">;
}

const jsonType = (erdType: string): "string" | "number" | "boolean" =>
  /^(int|integer|bigint|smallint|float|double|decimal|numeric|number|money)/i.test(erdType)
    ? "number"
    : /^bool/i.test(erdType)
      ? "boolean"
      : "string";

export function readEntities(erd: string): ReadEntity[] {
  const entities: ReadEntity[] = [];
  let current: ReadEntity | null = null;

  for (const rawLine of (erd ?? "").split("\n")) {
    const line = rawLine.trim();
    if (line.startsWith("%%")) continue;

    const open = line.match(/^([A-Za-z][A-Za-z0-9_]*)\s*\{$/);
    if (open?.[1]) {
      current = { name: open[1], attributes: [], types: {} };
      continue;
    }
    if (line === "}" && current) {
      entities.push(current);
      current = null;
      continue;
    }
    if (current) {
      const attribute = line.match(/^([A-Za-z][\w[\]]*)\s+([A-Za-z_]\w*)/);
      if (attribute?.[2]) {
        current.attributes.push(attribute[2]);
        current.types[attribute[2]] = jsonType(attribute[1] ?? "");
      }
    }
  }
  return entities;
}

/** `%%enum` values bound to a field by `%%field Entity.field … enum: Name`, per entity. */
export function readEnumValues(erd: string): Record<string, Record<string, string[]>> {
  const enums: Record<string, string[]> = {};
  const bound: Array<[string, string, string]> = [];

  for (const raw of (erd ?? "").split("\n")) {
    const line = raw.trim();
    const def = line.match(/^%%enum\s+(\w+)\s*:\s*(.+)$/);
    if (def?.[1] && def[2]) {
      enums[def[1]] = def[2]
        .split(",")
        .map((value) => value.trim())
        .filter(Boolean);
      continue;
    }
    const field = line.match(/^%%field\s+(\w+)\.(\w+)\s+.*?enum:\s*(\w+)/);
    if (field?.[1] && field[2] && field[3]) bound.push([field[1], field[2], field[3]]);
  }

  const result: Record<string, Record<string, string[]>> = {};
  for (const [entity, field, name] of bound) {
    const values = enums[name];
    if (!values) continue;
    result[entity] = { ...(result[entity] ?? {}), [field]: values };
  }
  return result;
}

/** The constraints for every entity in the model. */
export function ruleConstraints(
  erd: string,
  workflows: readonly ConstraintWorkflow[]
): Record<string, RuleConstraints> {
  const enums = readEnumValues(erd);
  const result: Record<string, RuleConstraints> = {};

  for (const entity of readEntities(erd)) {
    const values: Record<string, string[]> = { ...(enums[entity.name] ?? {}) };

    // A state machine is stricter than an enum: a status it never draws cannot be
    // reached, so only its states are offered for the status field.
    const machine = workflows.find((w) => w.entity === entity.name && w.kind === "state");
    if (machine?.stateNames?.length) {
      const states = new Set(machine.stateNames);
      // The column a machine writes to is the one whose enum shares its states —
      // `stage` on an Opportunity, not necessarily a column called `status`.
      let column: string | undefined;
      let best = 0;
      for (const [field, allowed] of Object.entries(enums[entity.name] ?? {})) {
        const overlap = allowed.filter((value) => states.has(value)).length;
        if (overlap > best) {
          best = overlap;
          column = field;
        }
      }
      column ??= entity.attributes.includes("status") ? "status" : undefined;
      if (column) values[column] = machine.stateNames;
    }

    result[entity.name] = {
      fields: entity.attributes,
      fieldTypes: entity.types,
      values,
      workflowNames: workflows
        .filter((w) => w.entity === entity.name)
        .map((w) => w.name)
        .filter(Boolean),
    };
  }
  return result;
}

/**
 * Somewhere to draw every node of a decision graph.
 *
 * A rule compiled from a model's `%%rule` flowchart is a GoRules graph whose
 * nodes carry no `position`: the rules engine evaluates nodes and edges and has
 * no use for coordinates, so the compiler writes none. The graph editor does —
 * React Flow reads `node.position.x` for every node — and opening such a rule
 * threw "Cannot read properties of undefined (reading 'x')" and took the whole
 * Rules and workflows screen down with it. Thirteen of the CRM's thirty rules
 * were like that.
 *
 * So the editor places what it is given without a place, here, from the graph's
 * own edges: a node's column is the longest path to it from a node nothing
 * points at, and nodes in one column stack in the order the graph lists them.
 * A node that already has a position keeps it, so a graph an author arranged
 * opens as they left it. Stored rules are not rewritten until somebody saves.
 */

interface PlacedNode {
  id: string;
  position?: { x?: unknown; y?: unknown } | null;
}

interface Graph<N extends PlacedNode> {
  nodes: N[];
  edges?: { sourceId?: string; targetId?: string }[];
}

const COLUMN_WIDTH = 320;
const ROW_HEIGHT = 140;
const ORIGIN = { x: 80, y: 80 };

function hasPosition(node: PlacedNode): boolean {
  const position = node.position;
  return (
    !!position &&
    typeof position.x === "number" &&
    Number.isFinite(position.x) &&
    typeof position.y === "number" &&
    Number.isFinite(position.y)
  );
}

/** The graph with every node placed. Returns the same object when none was missing. */
export function withNodePositions<N extends PlacedNode, G extends Graph<N>>(graph: G): G {
  if (!graph || !Array.isArray(graph.nodes) || graph.nodes.every(hasPosition)) return graph;

  const ids = new Set(graph.nodes.map((node) => node.id));
  const incoming = new Map<string, string[]>();
  for (const node of graph.nodes) incoming.set(node.id, []);
  for (const edge of graph.edges ?? []) {
    if (!edge.sourceId || !edge.targetId) continue;
    if (!ids.has(edge.sourceId) || !ids.has(edge.targetId)) continue;
    incoming.get(edge.targetId)?.push(edge.sourceId);
  }

  // Longest path from a source, guarded against a cycle (which a graph should
  // not have, but a hand-written one could): a node met again on the current
  // path counts as a source.
  const column = new Map<string, number>();
  const onPath = new Set<string>();
  const depth = (id: string): number => {
    const known = column.get(id);
    if (known !== undefined) return known;
    if (onPath.has(id)) return 0;
    onPath.add(id);
    const parents = incoming.get(id) ?? [];
    const value = parents.length === 0 ? 0 : Math.max(...parents.map(depth)) + 1;
    onPath.delete(id);
    column.set(id, value);
    return value;
  };

  const rowsUsed = new Map<number, number>();
  const nodes = graph.nodes.map((node) => {
    if (hasPosition(node)) return node;
    const col = depth(node.id);
    const row = rowsUsed.get(col) ?? 0;
    rowsUsed.set(col, row + 1);
    return {
      ...node,
      position: { x: ORIGIN.x + col * COLUMN_WIDTH, y: ORIGIN.y + row * ROW_HEIGHT },
    };
  });
  return { ...graph, nodes };
}

/**
 * Decision flows, both directions.
 *
 * A `%%rule` section in EML is a Mermaid flowchart whose node *shapes* carry
 * the decision role. The parser already turns that text into an AST; a visual
 * editor also needs the inverse, so what a designer draws on a canvas can go
 * back into the model as the same text a hand-written rule would use.
 *
 * The editable model here is deliberately narrower than GoRules JDM: it holds
 * exactly what an EML flowchart can express — a role, a label, and labelled
 * edges. Editing a richer structure and serialising it down would silently drop
 * whatever did not fit, and the first sign of that would be a rule behaving
 * differently in the generated app than it looked on screen.
 */

import { type FlowAST, type NodeShape, parseMermaidFlowchart } from "../mermaid-flowchart-parser";

/** What a node does, in the vocabulary a rule author thinks in. */
export type RuleNodeRole = "start" | "end" | "decision" | "action" | "compute";

export interface RuleFlowNode {
  id: string;
  role: RuleNodeRole;
  label: string;
  /** Canvas position. Absent for a rule authored as text. */
  position?: { x: number; y: number };
}

export interface RuleFlowEdge {
  id: string;
  source: string;
  target: string;
  /** Branch condition on edges leaving a decision; a transition name elsewhere. */
  label?: string;
}

export interface RuleFlow {
  nodes: RuleFlowNode[];
  edges: RuleFlowEdge[];
  /**
   * `%%` directive lines inside the section that the canvas does not model,
   * kept verbatim so they survive being edited.
   *
   * The canvas understands nodes and edges. A rule section can carry more than
   * that — `%%action` is the one that matters most, because it is how a rule
   * triggers a workflow. Re-emitting only what the canvas knows deleted those
   * lines on save: opening the Logic step and pressing Save was enough to drop
   * `%%action escalateCritical trigger-workflow …` from the model, after which
   * a critical deviation no longer opened a CAPA and nothing reported an error.
   *
   * The `.mmd` is the source of truth, so the editor must not quietly narrow it
   * to the subset it can draw.
   */
  directives?: string[];
}

/**
 * Directive lines a rule section carries alongside its flowchart.
 *
 * Anything starting `%%` that is not a plain `%%` comment. Mermaid ignores them
 * and the flowchart parser drops them, so they have to be collected separately.
 */
function extractDirectives(mermaid: string): string[] {
  return (mermaid ?? "")
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => /^%%[a-z]/i.test(line));
}

/** How each role renders as a Mermaid shape. Mirrors spec/02-business-rules.md. */
export const ROLE_SHAPES: Record<RuleNodeRole, { open: string; close: string; jdm: string }> = {
  start: { open: "([", close: "])", jdm: "inputNode" },
  end: { open: "([", close: "])", jdm: "outputNode" },
  decision: { open: "{", close: "}", jdm: "switchNode" },
  action: { open: "[", close: "]", jdm: "expressionNode" },
  compute: { open: "(", close: ")", jdm: "functionNode" },
};

export const ROLE_LABELS: Record<RuleNodeRole, string> = {
  start: "Start",
  end: "End",
  decision: "Decision",
  action: "Action",
  compute: "Compute",
};

export const ROLE_HINTS: Record<RuleNodeRole, string> = {
  start: "Where the rule begins — the input context.",
  decision: "A branch. Label each outgoing arrow with its condition.",
  action: "Set a value or apply an outcome.",
  compute: "Work out a value from the inputs.",
  end: "The rule's result.",
};

/**
 * Characters that would terminate a Mermaid shape early.
 *
 * A label is free text from a form field, so it has to be made safe before it
 * is written between `{` and `}`. Replacing rather than escaping keeps the
 * emitted document readable, and the substitutions read naturally in a label.
 */
function safeLabel(label: string): string {
  return (
    label
      .replace(
        /[[\]{}()|]/g,
        (char) =>
          ({ "[": "(", "]": ")", "{": "(", "}": ")", "(": "", ")": "", "|": "/" })[char] ?? ""
      )
      .replace(/["`]/g, "'")
      .replace(/\s+/g, " ")
      .trim() || "Step"
  );
}

/** Node ids must be Mermaid identifiers; canvas ids are free-form. */
function safeId(id: string, index: number): string {
  const cleaned = id.replace(/[^A-Za-z0-9_]/g, "_");
  return /^[A-Za-z_]/.test(cleaned) ? cleaned : `n${index}_${cleaned}`;
}

/**
 * Which role a parsed node plays.
 *
 * A stadium node is Start or End depending on direction: one with no outgoing
 * edges is the flow's result. That single-shape convention is what the EML spec
 * describes, so the reverse mapping has to look at the edges, not the shape.
 */
function roleFromShape(shape: NodeShape, hasOutgoing: boolean): RuleNodeRole {
  switch (shape) {
    case "stadium":
      return hasOutgoing ? "start" : "end";
    case "diamond":
      return "decision";
    case "circle":
    case "round":
      return "compute";
    default:
      return "action";
  }
}

/** Lay nodes out top-down in dependency order, so an imported rule reads well. */
function autoLayout(nodes: RuleFlowNode[], edges: RuleFlowEdge[]): void {
  const depth = new Map<string, number>();
  const incoming = new Map<string, number>();

  for (const node of nodes) incoming.set(node.id, 0);
  for (const edge of edges) incoming.set(edge.target, (incoming.get(edge.target) ?? 0) + 1);

  const queue = nodes.filter((node) => (incoming.get(node.id) ?? 0) === 0).map((node) => node.id);
  for (const id of queue) depth.set(id, 0);

  // Breadth-first over the DAG. Cycles keep whatever depth they were first
  // given rather than looping forever.
  while (queue.length) {
    const id = queue.shift();
    if (id === undefined) break;
    const currentDepth = depth.get(id) ?? 0;
    for (const edge of edges.filter((e) => e.source === id)) {
      if (depth.has(edge.target)) continue;
      depth.set(edge.target, currentDepth + 1);
      queue.push(edge.target);
    }
  }

  const perRow = new Map<number, number>();
  for (const node of nodes) {
    const row = depth.get(node.id) ?? 0;
    const column = perRow.get(row) ?? 0;
    perRow.set(row, column + 1);
    node.position = { x: 80 + column * 260, y: 60 + row * 130 };
  }
}

/** Read a rule's flowchart into the editable model. */
export function parseRuleFlow(mermaid: string): RuleFlow {
  const ast: FlowAST = parseMermaidFlowchart(mermaid ?? "");

  const withOutgoing = new Set(ast.edges.map((edge) => edge.source));
  const nodes: RuleFlowNode[] = [...ast.nodes.values()].map((node) => ({
    id: node.id,
    label: node.label,
    role: roleFromShape(node.shape, withOutgoing.has(node.id)),
  }));

  const edges: RuleFlowEdge[] = ast.edges.map((edge, index) => ({
    id: `e${index}_${edge.source}_${edge.target}`,
    source: edge.source,
    target: edge.target,
    label: edge.label,
  }));

  autoLayout(nodes, edges);
  return { nodes, edges, directives: extractDirectives(mermaid) };
}

/**
 * Write the editable model back out as a Mermaid flowchart.
 *
 * Node definitions come first, then edges, so every node survives even when it
 * is not yet connected — a half-drawn rule still round-trips instead of losing
 * the node the author just added.
 */
export function emitRuleFlow(flow: RuleFlow): string {
  const idMap = new Map<string, string>();
  flow.nodes.forEach((node, index) => {
    idMap.set(node.id, safeId(node.id, index));
  });

  const lines = ["flowchart TD"];

  for (const node of flow.nodes) {
    const { open, close } = ROLE_SHAPES[node.role];
    lines.push(`    ${idMap.get(node.id)}${open}${safeLabel(node.label)}${close}`);
  }

  for (const edge of flow.edges) {
    const source = idMap.get(edge.source);
    const target = idMap.get(edge.target);
    if (!source || !target) continue;
    const label = edge.label?.trim();
    lines.push(`    ${source} -->${label ? `|${safeLabel(label)}|` : ""} ${target}`);
  }

  // Directives last, after a blank line: they describe the section rather than
  // the diagram, and Mermaid renders the flowchart the same either way.
  if (flow.directives?.length) {
    lines.push("", ...flow.directives.map((directive) => `    ${directive}`));
  }

  return lines.join("\n");
}

/** Problems worth showing before a rule is saved. */
export function validateRuleFlow(flow: RuleFlow): string[] {
  const problems: string[] = [];
  if (!flow.nodes.length) return ["The rule has no steps yet."];

  const starts = flow.nodes.filter((node) => node.role === "start");
  const ends = flow.nodes.filter((node) => node.role === "end");
  if (!starts.length) problems.push("No Start step — add one so the rule has an input.");
  if (!ends.length) problems.push("No End step — add one so the rule produces a result.");

  const connected = new Set<string>();
  for (const edge of flow.edges) {
    connected.add(edge.source);
    connected.add(edge.target);
  }
  for (const node of flow.nodes) {
    if (!connected.has(node.id) && flow.nodes.length > 1) {
      problems.push(`"${node.label}" is not connected to anything.`);
    }
  }

  for (const decision of flow.nodes.filter((node) => node.role === "decision")) {
    const outgoing = flow.edges.filter((edge) => edge.source === decision.id);
    if (outgoing.length < 2) {
      problems.push(`Decision "${decision.label}" needs at least two branches.`);
    }
    if (outgoing.some((edge) => !edge.label?.trim())) {
      problems.push(`Every branch out of "${decision.label}" needs a condition label.`);
    }
  }

  return problems;
}

/**
 * Decision table model shared between the rule editor and the EML layer.
 *
 * Rules are authored as decision tables. The EML representation embeds the
 * table as a `%%decision-table` directive inside a minimal Mermaid flowchart
 * so the file round-trips without loss. The generator reads the directive and
 * compiles it to a GoRules JDM decision graph for the generated app.
 */

// Whole-record checks are evaluated by the copy the generated app ships too.
import { evaluateExpression, expressionFields } from "../workflow/bpmn-model";

export interface DecisionColumn {
  id: string;
  name: string;
  /** Context key read (inputs) or published (outputs). */
  field: string;
  /** When set, the cell renders as a dropdown constrained to these values. */
  options?: string[];
}

/** The output columns the generated rule engine recognises. */
export const KNOWN_OUTPUT_FIELDS = [
  { field: "action", label: "Action" },
  { field: "message", label: "Message" },
  { field: "ruleId", label: "Rule ID" },
  { field: "workflowName", label: "Workflow Name" },
  { field: "field", label: "Field" },
  { field: "value", label: "Value" },
  { field: "targetEntity", label: "Target Entity" },
  { field: "linkField", label: "Link Field" },
] as const;

/** Auto-applied options when a column field matches a known name. */
export const WELL_KNOWN_OPTIONS: Record<string, string[]> = {
  action: ["trigger-workflow", "validation-error", "transform"],
};

export function getColumnOptions(col: DecisionColumn): string[] | undefined {
  if (col.options && col.options.length > 0) return col.options;
  const key = col.field.trim().toLowerCase();
  return WELL_KNOWN_OPTIONS[key];
}

export interface DecisionRow {
  _id: string;
  [cell: string]: string;
}

export interface DecisionTable {
  hitPolicy: "first" | "collect";
  inputs: DecisionColumn[];
  outputs: DecisionColumn[];
  rules: DecisionRow[];
}

let rowCounter = 0;
export function newRowId(): string {
  return `r${(rowCounter++).toString(36)}${Date.now().toString(36)}`;
}

export function emptyDecisionTable(): DecisionTable {
  return {
    hitPolicy: "first",
    inputs: [{ id: "i1", name: "Input", field: "" }],
    outputs: [{ id: "o1", name: "Output", field: "" }],
    rules: [{ _id: newRowId(), i1: "", o1: "" }],
  };
}

export function parseDecisionTable(json: string | undefined): DecisionTable | null {
  if (!json?.trim()) return null;
  try {
    const parsed = JSON.parse(json) as Partial<DecisionTable>;
    if (!parsed || typeof parsed !== "object") return null;
    return {
      hitPolicy: parsed.hitPolicy === "collect" ? "collect" : "first",
      inputs: Array.isArray(parsed.inputs) ? parsed.inputs : [],
      outputs: Array.isArray(parsed.outputs) ? parsed.outputs : [],
      rules: Array.isArray(parsed.rules) ? (parsed.rules as DecisionRow[]) : [],
    };
  } catch {
    return null;
  }
}

export function validateDecisionTable(table: DecisionTable): string[] {
  const problems: string[] = [];
  if (table.inputs.length === 0) problems.push("Add at least one input column to test against.");
  if (table.outputs.length === 0) {
    problems.push("Add at least one output column — a table that publishes nothing does nothing.");
  }
  if (table.rules.length === 0) problems.push("Add at least one row.");
  for (const input of table.inputs) {
    // A `collect` table is the one `%%action` compiles to: its input reads the
    // whole record and each cell is an expression, so no field is correct.
    if (!input.field.trim() && table.hitPolicy !== "collect") {
      problems.push(`Input "${input.name || input.id}" reads no field.`);
    }
  }
  for (const output of table.outputs) {
    if (!output.field.trim()) {
      problems.push(`Output "${output.name || output.id}" publishes under no name.`);
    }
  }
  return problems;
}

/* -------------------------------------------------------------------------- */
/*  Evaluation                                                                  */
/* -------------------------------------------------------------------------- */

export interface TableTestResult {
  /** The first row that fits — under `first`, the answer. */
  rowIndex: number | null;
  outputs: Record<string, string>;
  /** Every row that fits, in order. Under `collect` each of them runs. */
  matches: Array<{ rowIndex: number; outputs: Record<string, string> }>;
}

export { evaluateExpression, expressionFields };

export function evaluateTable(
  table: DecisionTable,
  values: Record<string, string>
): TableTestResult {
  const matches: TableTestResult["matches"] = [];
  for (let i = 0; i < table.rules.length; i++) {
    const row = table.rules[i];
    if (!row) continue;
    const fits = table.inputs.every((col) => {
      const cell = (row[col.id] ?? "").trim();
      if (!cell) return true;
      // An input with no field holds whole-record checks, as `%%action`
      // writes them: `status == "withdrawn" and withdrawn_on == null`.
      if (!col.field.trim()) {
        const verdict = evaluateExpression(cell, values);
        if (verdict !== undefined) return verdict;
      }
      return cellMatches(cell, values[col.field] ?? "");
    });
    if (!fits) continue;
    const outputs: Record<string, string> = {};
    for (const col of table.outputs) outputs[col.field || col.name] = unquote(row[col.id] ?? "");
    matches.push({ rowIndex: i, outputs });
    if (table.hitPolicy !== "collect") break;
  }
  const first = matches[0];
  return { rowIndex: first?.rowIndex ?? null, outputs: first?.outputs ?? {}, matches };
}

function cellMatches(cell: string, typed: string): boolean {
  const m = cell.match(/^\s*(>=|<=|!=|=|>|<)?\s*(.+)$/);
  if (!m) return false;
  const op = m[1] ?? "=";
  const raw = unquote((m[2] ?? "").trim());
  // The cell is unquoted, so the value typed to test it must be too: a tester
  // copying the cell's own `"cancelled"` was told no row fits it.
  const value = unquote(typed);
  const a = Number(value);
  const b = Number(raw);
  const numeric = !Number.isNaN(a) && !Number.isNaN(b) && value.trim() !== "";
  switch (op) {
    case "=":
      return numeric ? a === b : value === raw;
    case "!=":
      return numeric ? a !== b : value !== raw;
    case ">":
      return numeric && a > b;
    case ">=":
      return numeric && a >= b;
    case "<":
      return numeric && a < b;
    case "<=":
      return numeric && a <= b;
    default:
      return false;
  }
}

function unquote(s: string): string {
  const t = s.trim();
  if (t.length >= 2 && (t.startsWith('"') || t.startsWith("'"))) {
    const q = t[0] as string;
    if (t.endsWith(q)) return t.slice(1, -1);
  }
  return t;
}

/* -------------------------------------------------------------------------- */
/*  Coverage                                                                    */
/* -------------------------------------------------------------------------- */

export interface CoverageNote {
  level: "ok" | "warn";
  message: string;
}

export function checkCoverage(table: DecisionTable): CoverageNote[] {
  const notes: CoverageNote[] = [];
  // Under `collect` every row that fits runs. A row with no check is not a
  // safety net there — it runs on every record, which is worth saying loudly.
  if (table.hitPolicy === "collect") {
    const blank = table.rules.findIndex((row) =>
      table.inputs.every((c) => !(row[c.id] ?? "").trim())
    );
    return [
      blank >= 0
        ? {
            level: "warn",
            message: `Row ${blank + 1} has no check, so its action runs on every record.`,
          }
        : {
            level: "ok",
            message:
              "Each row runs on its own when its check fits. A record that no row fits passes untouched.",
          },
    ];
  }
  const hasCatchAll = table.rules.some((row) =>
    table.inputs.every((c) => !(row[c.id] ?? "").trim())
  );
  notes.push(
    hasCatchAll
      ? { level: "ok", message: "Every combination of inputs reaches a row. No gaps." }
      : {
          level: "warn",
          message:
            "No catch-all row. If nothing fits, this table returns no answer. Add a row with every check left blank.",
        }
  );
  for (let i = 0; i < table.rules.length; i++) {
    for (let j = i + 1; j < table.rules.length; j++) {
      const earlier = table.rules[i];
      const later = table.rules[j];
      if (!earlier || !later) continue;
      const shadowed = table.inputs.every((c) => {
        const e = (earlier[c.id] ?? "").trim();
        const l = (later[c.id] ?? "").trim();
        return !e || e === l;
      });
      if (shadowed) {
        notes.push({
          level: "warn",
          message: `Row ${i + 1} already covers everything row ${j + 1} does, so row ${j + 1} can never fire.`,
        });
        return notes;
      }
    }
  }
  return notes;
}

/* -------------------------------------------------------------------------- */
/*  EML round-trip                                                              */
/* -------------------------------------------------------------------------- */

const DIRECTIVE_PREFIX = "%%decision-table ";

/**
 * Embed the decision table in a minimal EML-compatible Mermaid flowchart.
 *
 * The actual table JSON lives in a `%%decision-table` directive so it
 * survives the EML round-trip intact. The generator reads this directive when
 * compiling rules to GoRules JDM.
 */
export function tableToEmlFlowchart(table: DecisionTable): string {
  const json = JSON.stringify(table);
  return [
    "flowchart TD",
    "    Start([Rule table]) --> End([Result])",
    `    ${DIRECTIVE_PREFIX}${json}`,
  ].join("\n");
}

/**
 * Extract a decision table from an EML flowchart that was previously produced
 * by `tableToEmlFlowchart`. Returns null for flowcharts that were hand-authored
 * or produced by the old flowchart editor.
 */
export function parseTableFromFlowchart(flowchart: string): DecisionTable | null {
  const line = (flowchart ?? "")
    .split("\n")
    .map((l) => l.trim())
    .find((l) => l.startsWith(DIRECTIVE_PREFIX));
  if (!line) return null;
  return parseDecisionTable(line.slice(DIRECTIVE_PREFIX.length));
}

/* -------------------------------------------------------------------------- */
/*  JDM graph round-trip (full DecisionGraph with nodes + edges)              */
/* -------------------------------------------------------------------------- */

const JDM_GRAPH_PREFIX = "%%jdm-graph ";

/** Embed a full JDM graph (serialised JSON) in an EML-compatible Mermaid flowchart. */
export function graphToEmlFlowchart(graphJson: string): string {
  return [
    "flowchart TD",
    "    Start([Rule]) --> End([Result])",
    `    ${JDM_GRAPH_PREFIX}${graphJson}`,
  ].join("\n");
}

/**
 * Extract the JDM graph JSON string from a flowchart produced by
 * `graphToEmlFlowchart`. Returns null if the flowchart does not contain a
 * `%%jdm-graph` directive.
 */
export function parseGraphFromFlowchart(flowchart: string): string | null {
  const line = (flowchart ?? "")
    .split("\n")
    .map((l) => l.trim())
    .find((l) => l.startsWith(JDM_GRAPH_PREFIX));
  if (!line) return null;
  return line.slice(JDM_GRAPH_PREFIX.length);
}

/**
 * What running a rule against a sample record answers, and how an editor asks.
 *
 * Kept apart from the runner so the editors that show the answer can be the
 * same files in the modelling tool and in a generated application: each hands
 * them a `RuleDryRun` that reaches its own server, and the answer has one shape.
 */

import type { Outcome } from "./rule-outcome";

export interface DryRunTraceStep {
  node: string;
  output: unknown;
}

export type DryRunResult =
  | { ok: true; result: unknown; outcomes: Outcome[]; trace: DryRunTraceStep[] }
  | { ok: false; problems: string[] };

export interface RuleDryRunInput {
  /** The editor's graph, as JSON text or an object. */
  graph: unknown;
  /** The sample record the rule is run against. */
  record: Record<string, unknown>;
  /** The entity the rule is on. */
  entity: string;
}

/** Run a rule without saving anything. Rejects with an Error whose message is shown. */
export type RuleDryRun = (input: RuleDryRunInput) => Promise<DryRunResult>;

/**
 * Reading and writing what the rules API stores.
 *
 * Rules predate the rule-table editor, so `jdm_content` may hold either a
 * decision table or an older JDM decision graph. Anything that is not a table
 * opens as an empty one rather than a guessed conversion: a graph flattened by
 * assumption would look like a working table while deciding something different,
 * and visibly empty is the failure an author can actually see and fix.
 */

import { type DecisionRow, type DecisionTable, emptyDecisionTable } from "../workflow/bpmn-model";

/** What the rules API round-trips. Kept loose because older rows vary. */
export type StoredRuleContent = DecisionTable | Record<string, unknown>;

export function isDecisionTable(content: unknown): content is DecisionTable {
  if (!content || typeof content !== "object") return false;
  const c = content as Partial<DecisionTable>;
  return Array.isArray(c.inputs) && Array.isArray(c.outputs) && Array.isArray(c.rules);
}

/** A table to edit, whatever was stored. */
export function asDecisionTable(content: unknown): DecisionTable {
  // Parse JSON strings that came back from the API as raw text
  const parsed: unknown =
    typeof content === "string"
      ? (() => {
          try {
            return JSON.parse(content);
          } catch {
            return null;
          }
        })()
      : content;

  if (isDecisionTable(parsed)) {
    const t = parsed as DecisionTable;
    return {
      hitPolicy: t.hitPolicy === "collect" ? "collect" : "first",
      inputs: t.inputs,
      outputs: t.outputs,
      rules: t.rules,
    };
  }

  // JDM graph format: { name, nodes: [..., { type: "decisionTableNode", content: {...} }] }
  if (
    parsed &&
    typeof parsed === "object" &&
    Array.isArray((parsed as Record<string, unknown>).nodes)
  ) {
    const nodes = (parsed as { nodes: unknown[] }).nodes;
    for (const node of nodes) {
      if (
        node &&
        typeof node === "object" &&
        (node as Record<string, unknown>).type === "decisionTableNode"
      ) {
        const tableContent = (node as Record<string, unknown>).content;
        if (isDecisionTable(tableContent)) return editableGraphTable(tableContent as DecisionTable);
      }
    }
  }

  return emptyDecisionTable();
}

/** A whole zen string literal — `'prevent'`, `"a \"b\""` — and nothing after it. */
const ZEN_STRING = /^'(?:[^'\\]|\\.)*'$|^"(?:[^"\\]|\\.)*"$/;

/** The runtime's words for an action, in the editor's (EML's). */
const EDITOR_ACTION: Record<string, string> = { prevent: "validation-error" };

/**
 * A graph's table, as the editor edits it.
 *
 * A graph holds zen literals — `'prevent'`, `''` — because the engine reads
 * every cell as an expression. The editor edits plain text, and the engine
 * quotes a bare table's outcome cells again on the way in, so they are read
 * back unquoted here. Without this, a rule compiled from `%%action` opened
 * with its Action picker blank and nine quoted columns, and saving it after
 * any change wrote the blank back. Input cells are expressions and are left
 * as they are. `ruleId` and columns no row uses are dropped: the engine names
 * a violation after the stored rule, and the rest is noise.
 */
function editableGraphTable(t: DecisionTable): DecisionTable {
  const rules = t.rules.map((row) => {
    const next: DecisionRow = { _id: row._id };
    for (const column of t.inputs) next[column.id] = row[column.id] ?? "";
    for (const column of t.outputs) {
      const raw = String(row[column.id] ?? "").trim();
      const text = ZEN_STRING.test(raw) ? raw.slice(1, -1).replace(/\\(.)/g, "$1") : raw;
      next[column.id] = column.field === "action" ? (EDITOR_ACTION[text] ?? text) : text;
    }
    return next;
  });
  const outputs = t.outputs.filter(
    (column) =>
      column.field !== "ruleId" && rules.some((row) => (row[column.id] ?? "").trim() !== "")
  );
  return {
    hitPolicy: t.hitPolicy === "collect" ? "collect" : "first",
    inputs: t.inputs,
    outputs: outputs.length ? outputs : t.outputs,
    rules,
  };
}

/** The older decision-graph shape, still accepted on write for existing tooling. */
export function isJdmGraph(content: unknown): boolean {
  if (!content || typeof content !== "object") return false;
  const c = content as { name?: unknown; nodes?: unknown };
  return typeof c.name === "string" && Array.isArray(c.nodes) && c.nodes.length > 0;
}

/**
 * What is wrong with a rule someone is trying to save, in the words they would
 * use to fix it. Empty means it is fine.
 *
 * Both shapes are accepted: a decision table, which is what the rule table
 * editor writes, and a JDM graph, which is what older rules and any external
 * tooling still write. Validating only the graph shape is what made the table
 * editor unable to save at all.
 */
export function validateStoredRuleContent(content: unknown): string[] {
  if (!content || typeof content !== "object") {
    return ["The rule has no content. Add at least one row."];
  }

  if (isDecisionTable(content)) {
    const table = content as DecisionTable;
    const problems: string[] = [];
    if (table.inputs.length === 0) problems.push("Add at least one input column to test against.");
    if (table.outputs.length === 0) {
      problems.push("Add at least one outcome column — a table that decides nothing does nothing.");
    }
    if (table.rules.length === 0) problems.push("Add at least one row.");
    // A `collect` table's field-less input reads the whole record (`%%action`).
    const named =
      table.hitPolicy === "collect" ? table.outputs : [...table.inputs, ...table.outputs];
    for (const column of named) {
      if (!String(column.field ?? "").trim()) {
        problems.push(`Column "${column.name || column.id}" does not say which field it reads.`);
      }
    }
    return problems;
  }

  if (isJdmGraph(content)) return [];

  return [
    "The rule content is neither a decision table nor a decision graph. Build it in the rule table editor.",
  ];
}

/**
 * Whether opening this rule will lose what was stored.
 *
 * True for a rule saved as something other than a table — the editor shows an
 * empty table, and saving would replace the old content. The routes use this to
 * warn before that happens rather than after.
 */
export function wouldReplaceStoredContent(content: unknown): boolean {
  return content !== null && content !== undefined && !isDecisionTable(content);
}

/**
 * The automation model — one sentence, three parts.
 *
 * "When an Order is created, only if Order.total is greater than 1000, then
 * look up a rule table, set a field, and create an Invoice."
 *
 * That sentence is the whole model. A trigger, a flat list of conditions that
 * must all pass, and an ordered list of steps. There is deliberately no graph
 * here: the executor runs steps in order and stops at the first failure, so a
 * list is the honest representation and the one the builder can draw as a
 * ladder without inventing layout the author never asked for.
 *
 * Storage is unchanged. `serializeAutomation` writes the same mermaid
 * flowchart with `%%` directives the parser already reads, so automations
 * saved before this builder existed still open, and anything saved here still
 * runs through the existing executor.
 */

import {
  type DecisionTable,
  emptyDecisionTable,
  STEP_TYPES,
  type StepType,
} from "../workflow/bpmn-model";

export type { DecisionTable, StepType };
export { emptyDecisionTable, STEP_TYPES };

/* -------------------------------------------------------------------------- */
/*  Triggers                                                                   */
/* -------------------------------------------------------------------------- */

/**
 * The events an automation can start from.
 *
 * These are the entity lifecycle hooks the generated services already fire, so
 * a trigger is not a new concept — it is the hook, named the way someone
 * describing their business would name it.
 */
export const TRIGGER_EVENTS = [
  "created",
  "beforeCreated",
  "updated",
  "beforeUpdated",
  "deleted",
  "beforeDeleted",
] as const;

export type TriggerEvent = (typeof TRIGGER_EVENTS)[number];

/** How each event reads in the builder, and what it means for the write. */
export const TRIGGER_LABELS: Record<TriggerEvent, string> = {
  created: "is created",
  beforeCreated: "is about to be created",
  updated: "is updated",
  beforeUpdated: "is about to be updated",
  deleted: "is deleted",
  beforeDeleted: "is about to be deleted",
};

export const TRIGGER_HINTS: Record<TriggerEvent, string> = {
  created: "Runs after the record is written. The record already exists.",
  beforeCreated: "Runs before the record is written, so it can still block the write.",
  updated: "Runs after the change is saved.",
  beforeUpdated: "Runs before the change is saved, so it can still block it.",
  deleted: "Runs after the record is removed.",
  beforeDeleted: "Runs before the record is removed, so it can still block it.",
};

/** The hook name each trigger maps to on the generated service. */
export const TRIGGER_HOOKS: Record<TriggerEvent, string> = {
  created: "afterCreate",
  beforeCreated: "beforeCreate",
  updated: "afterUpdate",
  beforeUpdated: "beforeUpdate",
  deleted: "afterDelete",
  beforeDeleted: "beforeDelete",
};

const HOOK_TO_EVENT: Record<string, TriggerEvent> = {
  afterCreate: "created",
  beforeCreate: "beforeCreated",
  afterUpdate: "updated",
  beforeUpdate: "beforeUpdated",
  afterDelete: "deleted",
  beforeDelete: "beforeDeleted",
};

export interface Trigger {
  /** The entity this automation watches, e.g. "Order". */
  entity: string;
  event: TriggerEvent;
}

/* -------------------------------------------------------------------------- */
/*  Conditions                                                                 */
/* -------------------------------------------------------------------------- */

/**
 * Comparison operators, worded as a check reads rather than as an expression.
 *
 * `arity: 0` means the operator takes no value — "is empty" has nothing on the
 * right-hand side, and the builder hides the value box for it rather than
 * leaving an input that must stay blank to be correct.
 */
export const OPERATORS = [
  { id: "eq", label: "is", arity: 1 },
  { id: "neq", label: "is not", arity: 1 },
  { id: "gt", label: "is greater than", arity: 1 },
  { id: "gte", label: "is greater than or equal to", arity: 1 },
  { id: "lt", label: "is less than", arity: 1 },
  { id: "lte", label: "is less than or equal to", arity: 1 },
  { id: "contains", label: "contains", arity: 1 },
  { id: "startsWith", label: "starts with", arity: 1 },
  { id: "isEmpty", label: "is empty", arity: 0 },
  { id: "isNotEmpty", label: "is not empty", arity: 0 },
  { id: "changed", label: "changed", arity: 0 },
] as const;

export type OperatorId = (typeof OPERATORS)[number]["id"];

export function operatorLabel(id: string): string {
  return OPERATORS.find((o) => o.id === id)?.label ?? id;
}

export function operatorArity(id: string): number {
  return OPERATORS.find((o) => o.id === id)?.arity ?? 1;
}

export interface Condition {
  id: string;
  /** Dotted path read from the run context, e.g. "order.total". */
  field: string;
  operator: OperatorId | string;
  /** Ignored when the operator takes no value. */
  value: string;
}

/* -------------------------------------------------------------------------- */
/*  Steps                                                                      */
/* -------------------------------------------------------------------------- */

/**
 * How each step type reads in the ladder and what it is for.
 *
 * The vocabulary is the executor's — Decision, CreateEntity, UpdateEntity,
 * DeleteEntity, Formula, REST — relabelled so the palette answers "what do I
 * want to happen" rather than "which node class is this".
 */
export const STEP_LABELS: Record<StepType, string> = {
  Decision: "Look up a rule table",
  CreateEntity: "Create a record",
  UpdateEntity: "Update a field",
  DeleteEntity: "Delete a record",
  Formula: "Work out a value",
  REST: "Call a web service",
};

export const STEP_HINTS: Record<StepType, string> = {
  Decision: "Ask a table of rules for an answer, then use it in a later step.",
  CreateEntity: "Insert a row and remember its id for later steps.",
  UpdateEntity: "Write one field, on this record or a related one.",
  DeleteEntity: "Soft delete by default, so the audit trail still resolves.",
  Formula: "Set, copy, add, subtract, multiply or divide.",
  REST: "POST to an external URL and keep the response.",
};

/** A single glyph per step type. Kept text so it renders without an icon font. */
export const STEP_GLYPHS: Record<StepType, string> = {
  Decision: "▤",
  CreateEntity: "✚",
  UpdateEntity: "✎",
  DeleteEntity: "✕",
  Formula: "ƒ",
  REST: "↗",
};

export interface AutomationStep {
  id: string;
  type: StepType;
  /**
   * What later steps call this step's result. Empty means the step produces
   * nothing worth naming (a delete, usually).
   */
  resultName: string;
  /** Type-specific configuration. Keys are documented per type in STEP_FIELDS. */
  props: Record<string, string>;
  /**
   * The loop this step belongs to, if any. At most one: loops do not nest, so
   * a step is either inside exactly one repeat or outside them all.
   */
  loopId?: string;
  /** Only set on Decision steps that own an inline table rather than a shared one. */
  table?: DecisionTable;
}

/** Which property fields each step type shows, in the order they read. */
export const STEP_FIELDS: Record<StepType, readonly string[]> = {
  Decision: ["ruleTable", "inputs"],
  CreateEntity: ["entity", "values"],
  UpdateEntity: ["entity", "target", "field", "value"],
  DeleteEntity: ["entity", "target"],
  Formula: ["operation", "left", "right"],
  REST: ["method", "url", "body"],
};

/* -------------------------------------------------------------------------- */
/*  Loops                                                                      */
/* -------------------------------------------------------------------------- */

/**
 * Repeat while a rule holds — the steps run again and again until the check
 * fails.
 *
 * The check is re-evaluated before every pass against the record *as it stands
 * then*, which is the point: a step inside the loop changes the record, and
 * that change is what eventually ends the loop.
 *
 * This is genuinely unbounded, and an automation runs inside the write that
 * triggered it — so a check that never fails does not spin a harmless
 * background job, it holds a database transaction open until something times
 * out. `maxPasses` is the backstop, and every loop must state its own. It is
 * not a second way to say "how many times": reaching it means the automation
 * was wrong, so the run is marked failed and says so, rather than finishing
 * quietly as though the loop had ended on its own.
 */
export interface Loop {
  id: string;
  /** Re-checked before each pass. The loop ends the first time it fails. */
  condition: Condition;
  /**
   * Passes after which this loop is abandoned and the run reported as failed.
   *
   * Required, and deliberately per-loop rather than a constant: how many passes
   * is "obviously too many" is a property of the work, not of the engine. A
   * retry loop that should give up after 5 and a reconciliation that legitimately
   * runs 800 cannot share one number without the ceiling being meaningless for
   * one of them.
   *
   * Held as a string because it is bound to a text input; validation is what
   * turns it into a number.
   */
  maxPasses: string;
}

/**
 * Smallest sensible ceiling. There is no upper bound — the author owns the
 * number, and capping it here would be the hardcoded limit this replaced.
 */
export const LOOP_MIN_PASSES = 1;

/**
 * A tolerant read of `loops`.
 *
 * Automations stored before loops existed have no such field, and they are the
 * majority of what is in any database today. Defaulting here rather than at
 * each call site means an old record opens and serialises unchanged instead of
 * throwing in whichever function reaches it first.
 */
export function loopsOf(automation: Automation): Loop[] {
  return automation.loops ?? [];
}

/** The steps belonging to a loop, in ladder order. */
export function stepsInLoop(automation: Automation, loopId: string): AutomationStep[] {
  return automation.steps.filter((step) => step.loopId === loopId);
}

/** The loop a step sits in, if any. */
export function loopOf(automation: Automation, step: AutomationStep): Loop | undefined {
  return step.loopId ? loopsOf(automation).find((l) => l.id === step.loopId) : undefined;
}

/**
 * A loop's members must sit together in the ladder.
 *
 * The list is the running order, so members split by an outside step would mean
 * the workflow runs A, (something else), B and repeats only part of it — a
 * shape the drawn subgraph could not honestly represent either.
 */
export function loopIsContiguous(automation: Automation, loopId: string): boolean {
  const positions = automation.steps
    .map((step, i) => (step.loopId === loopId ? i : -1))
    .filter((i) => i >= 0);
  if (positions.length === 0) return true;
  const first = positions[0] as number;
  return positions.every((position, offset) => position === first + offset);
}

/* -------------------------------------------------------------------------- */
/*  The automation                                                             */
/* -------------------------------------------------------------------------- */

/* -------------------------------------------------------------------------- */
/*  Hook rungs — the multi-trigger case                                        */
/* -------------------------------------------------------------------------- */

/**
 * The thirteen lifecycle events, in the order they run.
 *
 * Wider than `TRIGGER_EVENTS`, which names only the six an automation can
 * *start* from. A hook workflow binds handlers to any of these, including the
 * read and list points that have no "when this happens, then do that" reading.
 */
export const HOOK_EVENTS = [
  "beforeCreate",
  "afterCreate",
  "beforeUpdate",
  "afterUpdate",
  "beforeDelete",
  "afterDelete",
  "beforeRead",
  "afterRead",
  "beforeQuery",
  "afterQuery",
  "beforeList",
  "afterList",
  "customValidate",
] as const;

export type HookEvent = (typeof HOOK_EVENTS)[number];

export const HOOK_EVENT_HINTS: Record<HookEvent, string> = {
  beforeCreate: "Runs before a record is written — hash a password, set a default.",
  afterCreate: "Runs once the record exists — send a welcome email, emit an event.",
  beforeUpdate: "Validate or transform before the write.",
  afterUpdate: "Audit the change, invalidate a cache.",
  beforeDelete: "Block the delete if the record is still referenced.",
  afterDelete: "Clean up related rows or files.",
  beforeRead: "Guard a single-record read.",
  afterRead: "Redact or enrich a record on the way out.",
  beforeQuery: "Scope the query — tenant filters, injected conditions.",
  afterQuery: "Post-process the rows that came back.",
  beforeList: "Adjust filtering, sorting or pagination.",
  afterList: "Post-process a page of results.",
  customValidate: "Cross-field or business validation on any write.",
};

/**
 * One named handler bound to one lifecycle event.
 *
 * This is the rung a hook workflow is made of, and the reason `trigger` alone
 * could not carry it: `ContactHygiene` binds twelve handlers across
 * beforeCreate, customValidate, afterUpdate and beforeList. That is not one
 * automation with twelve steps — it is twelve triggers, each with its own
 * handler, sharing a name and an entity. A single `trigger` field can only say
 * one of them, so reading such a workflow through the automation shape dropped
 * every handler.
 */
export interface AutomationHook {
  id: string;
  event: HookEvent;
  /** Generated function name — the handler the backend will call. */
  handler: string;
  /** Optional field the hook is scoped to. */
  field?: string;
}

/**
 * Which shape an automation is.
 *
 * `automation` is the original sentence: one trigger, conditions, ordered
 * steps. `hook` is the multi-trigger list above. `saga` is the same ordered
 * steps as an automation, started by a rule rather than by a lifecycle event.
 * They share a rail, a ladder and an inspector; they differ in what a rung
 * means and in how the run begins.
 */
export type AutomationKind = "automation" | "hook" | "saga";

/** How a saga is started. `rule` means a business rule's %%action names it. */
export type SagaTrigger = "automatic" | "rule";
export type SagaOperation = "CREATE" | "UPDATE" | "DELETE" | "ALL";

export type AutomationStatus = "draft" | "live" | "paused";

export interface Automation {
  id: string;
  name: string;
  description?: string;
  kind: AutomationKind;
  trigger: Trigger;
  conditions: Condition[];
  /** Bounded repeats. A step joins one by carrying its id in `loopId`. */
  loops: Loop[];
  steps: AutomationStep[];
  /**
   * The rungs, when `kind` is `hook`. Each carries its own event, so
   * `trigger.event` is not meaningful for a hook workflow — only
   * `trigger.entity` is, because every hook binds to the same record type.
   */
  hooks: AutomationHook[];
  /**
   * How a saga starts, when `kind` is `saga`.
   *
   * These live on the `%%workflow` directive, not in the diagram, so they are
   * carried here rather than inferred from `trigger`. Reading a saga into the
   * single-trigger shape mapped `operation` onto a lifecycle event and threw
   * both away: a `trigger: rule` saga came back as "runs when created", and
   * saving it said so in the model.
   */
  sagaTrigger?: SagaTrigger;
  sagaOperation?: SagaOperation;
  /**
   * The state of the entity's status machine this workflow is bound to, for a
   * hook or saga workflow: it runs in the second transaction of the button
   * press that moves the record into that state, not on an ordinary save.
   * Unset means it runs on every matching write, as before. Named for what it
   * binds to — `status` below is this automation's own publication state.
   */
  onStatus?: string;
  status: AutomationStatus;
  updatedAt?: string;
}

export function isHookWorkflow(automation: Automation): boolean {
  return automation.kind === "hook";
}

export function newHook(event: HookEvent = "beforeCreate"): AutomationHook {
  return { id: newId("hook"), event, handler: "", field: "" };
}

export function describeHook(hook: AutomationHook): string {
  return `${hook.event} → ${hook.handler || "(unnamed)"}${hook.field ? ` · ${hook.field}` : ""}`;
}

let seq = 0;
export function newId(prefix: string): string {
  seq += 1;
  return `${prefix}_${seq.toString(36)}${Date.now().toString(36)}`;
}

export function emptyAutomation(entity: string, kind: AutomationKind = "automation"): Automation {
  return {
    id: newId("auto"),
    name:
      kind === "hook"
        ? "Untitled process"
        : kind === "saga"
          ? "Untitled process"
          : "Untitled automation",
    kind,
    trigger: { entity, event: "created" },
    conditions: [],
    loops: [],
    steps: [],
    hooks: kind === "hook" ? [newHook()] : [],
    ...(kind === "saga" ? { sagaTrigger: "rule" as const, sagaOperation: "CREATE" as const } : {}),
    status: "draft",
  };
}

export function newCondition(): Condition {
  return { id: newId("cond"), field: "", operator: "eq", value: "" };
}

/**
 * A new loop, named `L1`, `L2`, … rather than with the opaque id every other
 * object gets. The id is what an author types in `{{L1.iteration}}` and what
 * they read in the serialised model, so it has to be short and predictable.
 */
export function newLoop(existing: Loop[]): Loop {
  let n = existing.length + 1;
  while (existing.some((loop) => loop.id === `L${n}`)) n += 1;
  // Empty rather than pre-filled: the ceiling is a decision about this
  // particular loop, and a default would be accepted unread by most authors.
  return { id: `L${n}`, condition: newCondition(), maxPasses: "" };
}

/** How a loop reads on its card: "Repeat while status is open". */
export function describeLoop(loop: Loop): string {
  const check = loop.condition.field
    ? describeCondition(loop.condition)
    : "a check that is not set yet";
  return `Repeat while ${check}`;
}

export function newStep(type: StepType): AutomationStep {
  return {
    id: newId("step"),
    type,
    resultName: defaultResultName(type),
    props: type === "Formula" ? { operation: "set" } : {},
  };
}

function defaultResultName(type: StepType): string {
  switch (type) {
    case "Decision":
      return "decision";
    case "CreateEntity":
      return "createdId";
    case "Formula":
      return "value";
    case "REST":
      return "response";
    default:
      return "";
  }
}

/* -------------------------------------------------------------------------- */
/*  Reading an automation back as a sentence                                   */
/* -------------------------------------------------------------------------- */

/** The trigger line, as the WHEN card shows it. */
export function describeTrigger(t: Trigger): string {
  return `${article(t.entity)} ${t.entity} ${TRIGGER_LABELS[t.event] ?? t.event}`;
}

/** One condition, as the IF card shows it. */
export function describeCondition(c: Condition): string {
  const op = operatorLabel(c.operator);
  return operatorArity(c.operator) === 0
    ? `${c.field || "a field"} ${op}`
    : `${c.field || "a field"} ${op} ${c.value || "…"}`;
}

/** One step, as the THEN card shows it. */
export function describeStep(s: AutomationStep): string {
  const p = s.props;
  switch (s.type) {
    case "Decision":
      return `Look up ${p.ruleTable || "a rule table"}${s.resultName ? ` → ${s.resultName}` : ""}`;
    case "CreateEntity":
      return `Create ${article(p.entity || "record")} ${p.entity || "record"}${
        s.resultName ? ` → ${s.resultName}` : ""
      }`;
    case "UpdateEntity":
      return `Set ${p.entity && p.field ? `${p.entity}.${p.field}` : p.field || "a field"} to ${
        p.value || "…"
      }`;
    case "DeleteEntity":
      return `Delete ${article(p.entity || "record")} ${p.entity || "record"}`;
    case "Formula":
      return `${p.operation || "Set"} ${p.left || "…"}${p.right ? ` and ${p.right}` : ""}${
        s.resultName ? ` → ${s.resultName}` : ""
      }`;
    case "REST":
      return `${p.method || "POST"} to ${p.url || "a URL"}${
        s.resultName ? ` → ${s.resultName}` : ""
      }`;
    default:
      return STEP_LABELS[s.type] ?? s.type;
  }
}

function article(word: string): string {
  return /^[aeiou]/i.test(word) ? "an" : "a";
}

/* -------------------------------------------------------------------------- */
/*  Values available at a point in the run                                     */
/* -------------------------------------------------------------------------- */

export interface AvailableValue {
  /** The reference an author types, without braces, e.g. "tier.discount_pct". */
  path: string;
  type: string;
  /** Where it came from, shown beside the path. */
  origin: string;
}

/**
 * Everything a step at `index` may reference.
 *
 * Only values produced *above* the step are returned, so the picker can never
 * offer a reference to a step that has not run yet — the single most common way
 * a hand-written workflow breaks in production.
 */
export function valuesAvailableAt(
  automation: Automation,
  index: number,
  entityFields: Record<string, string[]> = {}
): AvailableValue[] {
  const out: AvailableValue[] = [];
  const entity = automation.trigger.entity;
  const root = entity.toLowerCase();

  for (const field of entityFields[entity] ?? []) {
    out.push({ path: `${root}.${field}`, type: "field", origin: entity });
  }
  if (out.length === 0) {
    out.push({ path: `${root}.id`, type: "uuid", origin: entity });
  }

  // Only offered to steps actually inside the repeat — outside it the pass
  // number has no meaning, and a picker that offers it anyway teaches the
  // wrong model of when a loop variable exists.
  const own = automation.steps[index];
  const loop = own ? loopOf(automation, own) : undefined;
  if (loop) {
    out.push({
      path: `${loop.id}.iteration`,
      type: "number",
      origin: `repeat ${loop.id}`,
    });
  }

  automation.steps.slice(0, Math.max(0, index)).forEach((step, i) => {
    if (!step.resultName) return;
    const origin = `step ${i + 1}`;
    if (step.type === "Decision") {
      const outputs = step.table?.outputs ?? [];
      if (outputs.length === 0) {
        out.push({ path: step.resultName, type: "answer", origin });
      }
      for (const o of outputs) {
        out.push({ path: `${step.resultName}.${o.field || o.name}`, type: "answer", origin });
      }
    } else {
      out.push({ path: step.resultName, type: stepResultType(step.type), origin });
    }
  });

  return out;
}

function stepResultType(type: StepType): string {
  switch (type) {
    case "CreateEntity":
      return "uuid";
    case "Formula":
      return "value";
    case "REST":
      return "response";
    default:
      return "value";
  }
}

/* -------------------------------------------------------------------------- */
/*  Validation — stated as the author would fix it                             */
/* -------------------------------------------------------------------------- */

export interface Problem {
  /** Which card the problem belongs to, so the ladder can mark it. */
  target: string;
  message: string;
}

export function validateAutomation(automation: Automation): Problem[] {
  const problems: Problem[] = [];

  if (!automation.name.trim()) {
    problems.push({ target: "name", message: "Give the automation a name." });
  }
  if (!automation.trigger.entity.trim()) {
    problems.push({ target: "trigger", message: "Pick the record type this watches." });
  }

  // A hook workflow starts from one or more lifecycle rungs. It has no single
  // `trigger.event`, so validate the handlers, then fall through to check any
  // conditions and steps the author added after them.
  if (automation.kind === "hook") {
    if (automation.hooks.length === 0) {
      problems.push({ target: "hooks", message: "Add at least one lifecycle step." });
    }
    const seen = new Set<string>();
    for (const hook of automation.hooks) {
      if (automation.onStatus && !/update/i.test(hook.event)) {
        problems.push({
          target: hook.id,
          message: `${hook.event} cannot be bound to a status: a move is an update, so only before-update and after-update steps can.`,
        });
      }
      if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(hook.handler)) {
        problems.push({
          target: hook.id,
          message: `"${hook.handler || "(unnamed)"}" is not a valid handler name — letters, digits and underscore, not starting with a digit.`,
        });
      }
      const key = `${hook.event}:${hook.handler}`;
      if (seen.has(key)) {
        problems.push({
          target: hook.id,
          message: `${hook.event} ${hook.handler} is listed twice, so it would run twice.`,
        });
      }
      seen.add(key);
    }
  }

  for (const c of automation.conditions) {
    if (!c.field.trim()) {
      problems.push({ target: c.id, message: "This check does not say which field to look at." });
    } else if (operatorArity(c.operator) === 1 && !c.value.trim()) {
      problems.push({
        target: c.id,
        message: `"${c.field} ${operatorLabel(c.operator)}" needs a value to compare against.`,
      });
    }
  }

  // A hook's rungs are what it does, so an empty step list is not a problem
  // there the way it is for an automation — but steps it does carry are checked.
  if (automation.kind !== "hook" && automation.steps.length === 0) {
    problems.push({ target: "steps", message: "Add at least one thing for this to do." });
  }

  const named = new Set<string>();
  automation.steps.forEach((step, i) => {
    for (const field of STEP_FIELDS[step.type] ?? []) {
      if (field === "inputs" || field === "values" || field === "body") continue;
      // A Decision may carry its own table instead of naming a saved rule —
      // the shape every saga in the example models uses — and an UpdateEntity
      // with no record type writes the record that triggered the run. Demanding
      // either told authors their working process was broken.
      if (field === "ruleTable" && step.table) continue;
      if (field === "entity" && step.type === "UpdateEntity") continue;
      // Which row to write is only a question when the step writes another
      // record type: the executor refuses to guess one, and the checker says so
      // (EML265). On this record, or with no record type, there is no question.
      if (field === "target" && step.type === "UpdateEntity") {
        const entity = (step.props.entity ?? "").trim();
        if (entity && entity !== automation.trigger.entity && !(step.props.target ?? "").trim()) {
          problems.push({
            target: step.id,
            message: `Step ${i + 1} writes a ${entity} but does not say which one. Set Which record.`,
          });
        }
        continue;
      }
      // The Formula operation defaults to "set" when not stored — the inspector
      // displays "set" via the same fallback, so an unset operation is not missing.
      if (field === "operation" && step.type === "Formula") continue;
      // For Formula, "right" (And this value) is only required for arithmetic
      // operations — "set" and "copy" need only one value.
      if (field === "right" && step.type === "Formula") {
        const op = (step.props.operation ?? "set").trim();
        if (op === "set" || op === "copy") continue;
      }
      // "set" stores its value as written and "copy" reads one from the run, so
      // each is compiled from a different kind of value: a reference given to
      // "set" becomes a source with no value, and text given to "copy" a value
      // with no source. The checker refuses both (EML262), and so does
      // generation — reported here, at the step, rather than after saving.
      if (field === "left" && step.type === "Formula") {
        const op = (step.props.operation ?? "set").trim();
        const left = (step.props.left ?? "").trim();
        const isReference = /^\{\{[^}]+\}\}$/.test(left);
        if (left && op === "set" && isReference) {
          problems.push({
            target: step.id,
            message: `Step ${i + 1} sets a value from ${left}. "set" stores text as written — choose "copy" to take a value from the run.`,
          });
          continue;
        }
        if (left && op === "copy" && !isReference) {
          problems.push({
            target: step.id,
            message: `Step ${i + 1} copies "${left}", which is not a value from the run. Use a reference such as {{record.field}}, or choose "set" to store the text as written.`,
          });
          continue;
        }
      }
      if (!(step.props[field] ?? "").trim()) {
        problems.push({
          target: step.id,
          message: `Step ${i + 1} is missing ${humanField(field)}.`,
        });
      }
    }
    if (step.resultName) {
      if (named.has(step.resultName)) {
        problems.push({
          target: step.id,
          message: `Two steps both save their answer as "${step.resultName}". Rename one.`,
        });
      }
      named.add(step.resultName);
    }
  });

  for (const loop of loopsOf(automation)) {
    const members = stepsInLoop(automation, loop.id);
    if (members.length === 0) {
      problems.push({
        target: loop.id,
        message: `Repeat ${loop.id} has no steps in it. Add one, or remove the repeat.`,
      });
      continue;
    }

    if (!loopIsContiguous(automation, loop.id)) {
      problems.push({
        target: loop.id,
        message: `The steps in repeat ${loop.id} have something else between them. Move them together.`,
      });
    }

    const check = loop.condition;
    if (!check.field.trim()) {
      problems.push({
        target: loop.id,
        message: `Repeat ${loop.id} does not say what to check, so it would never stop.`,
      });
    } else if (operatorArity(check.operator) === 1 && !check.value.trim()) {
      problems.push({
        target: loop.id,
        message: `"${check.field} ${operatorLabel(check.operator)}" needs a value to compare against.`,
      });
    }

    const max = loop.maxPasses.trim();
    if (!max) {
      problems.push({
        target: loop.id,
        message: `Say how many passes ${loop.id} may run before it gives up. There is no default.`,
      });
    } else {
      const n = Number(max);
      if (!Number.isInteger(n)) {
        problems.push({
          target: loop.id,
          message: `"${max}" is not a whole number of passes for repeat ${loop.id}.`,
        });
      } else if (n < LOOP_MIN_PASSES) {
        problems.push({
          target: loop.id,
          message: `Repeat ${loop.id} must be allowed at least ${LOOP_MIN_PASSES} pass.`,
        });
      }
    }

    // A check on a field no step in the loop writes cannot change between
    // passes, so the loop either never runs or runs until the safety limit
    // aborts it. Both are bugs, and both are invisible until it is live.
    if (check.field.trim() && !membersCanChange(members, check.field)) {
      problems.push({
        target: loop.id,
        message:
          `Nothing inside repeat ${loop.id} changes "${check.field}", so the check will ` +
          `read the same every pass. Add a step that updates it, or the repeat will run ` +
          `until it is cut off at its limit of ${loop.maxPasses || "?"} passes.`,
      });
    }
  }

  return problems;
}

/**
 * Does any step in the loop write the field the loop checks?
 *
 * Deliberately shallow — it matches an `UpdateEntity` on the field by name and
 * treats every other step type as opaque. A `REST` call or a `Decision` can
 * change the world in ways this cannot see, so this only ever reports the case
 * it is certain about: a loop whose body contains no write to that field at all.
 */
function membersCanChange(members: AutomationStep[], field: string): boolean {
  const bare = field.includes(".") ? (field.split(".").pop() as string) : field;
  return members.some((step) => {
    if (step.type !== "UpdateEntity") return true;
    const written = (step.props.field ?? "").trim();
    return written === "" || written === bare || written === field;
  });
}

function humanField(field: string): string {
  switch (field) {
    case "ruleTable":
      return "a rule table to look up";
    case "entity":
      return "a record type";
    case "field":
      return "a field to write";
    case "value":
      return "a value to write";
    case "operation":
      return "an operation";
    case "left":
      return "a value to work from";
    case "url":
      return "a URL";
    case "method":
      return "a method";
    case "target":
      return "a record to delete";
    default:
      return field;
  }
}

/* -------------------------------------------------------------------------- */
/*  Storage — mermaid flowchart with %% directives, unchanged                  */
/* -------------------------------------------------------------------------- */

/**
 * Write the automation as the flowchart the existing parser and generator read.
 *
 * The diagram is a straight chain because the model is a list; the `%%`
 * directives carry the semantics and every renderer ignores them, so the
 * artifact stays valid, renderable mermaid.
 */
/**
 * Write a hook workflow.
 *
 * Byte-for-byte the shape a hand-written workflow uses, because the generator
 * reads these directives directly: the chain is drawn in run order so a reader
 * sees the sequence, and the `%%hook` lines carry the meaning. The diagram is
 * generated from the hooks rather than edited alongside them, so the picture
 * and the directives cannot disagree.
 */
/**
 * A Create step's values, as the JSON map the generated runtime parses.
 *
 * The inspector takes one `column: value` per line, and those lines used to be
 * written into the directive as they were typed. Every line after the first
 * then fell outside any `%%` directive — invalid Mermaid, dropped by every
 * reader — and the one that survived was not JSON, which `executeCreateEntity`
 * requires, so the step was skipped at run time as "invalid fields JSON". The
 * model's own sagas write the map (`fields: {"status":"draft"}`), which is what
 * is emitted here. `{{name}}` becomes `name`, the runtime's reference to a value
 * in the run; `true`, `false`, `null` and numbers are written as themselves.
 */
export function encodeCreateValues(text: string): string {
  const trimmed = text.trim();
  if (!trimmed) return "";
  if (trimmed.startsWith("{")) {
    try {
      const parsed: unknown = JSON.parse(trimmed);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        return JSON.stringify(parsed);
      }
    } catch {
      /* not JSON: read it as lines below */
    }
  }
  const map: Record<string, unknown> = {};
  for (const line of trimmed.split(/\r?\n/)) {
    const match = line.match(/^\s*([A-Za-z_][\w.]*)\s*[:=]\s*(.*?)\s*$/);
    if (!match?.[1]) continue;
    map[match[1]] = literalOf(match[2] ?? "");
  }
  return JSON.stringify(map);
}

function literalOf(raw: string): unknown {
  const reference = raw.match(/^\{\{\s*([^}]+?)\s*\}\}$/);
  if (reference?.[1]) return reference[1];
  if (/^(?:true|false|null)$/.test(raw) || /^-?\d+(?:\.\d+)?$/.test(raw)) {
    return JSON.parse(raw) as unknown;
  }
  if (raw.length >= 2 && raw.startsWith('"') && raw.endsWith('"')) {
    try {
      return JSON.parse(raw) as unknown;
    } catch {
      return raw.slice(1, -1);
    }
  }
  return raw;
}

/**
 * The stored map, back as the lines the inspector edits. A string that would
 * read back as something else — `"42"`, `"true"` — keeps its quotes, so a
 * round trip does not change its type.
 */
export function decodeCreateValues(stored: string): string {
  const trimmed = stored.trim();
  if (!trimmed.startsWith("{")) return stored;
  try {
    const parsed: unknown = JSON.parse(trimmed);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return stored;
    return Object.entries(parsed as Record<string, unknown>)
      .map(([column, value]) => {
        if (typeof value !== "string") return `${column}: ${JSON.stringify(value)}`;
        return `${column}: ${literalOf(value) === value ? value : JSON.stringify(value)}`;
      })
      .join("\n");
  } catch {
    return stored;
  }
}

/**
 * One property, on one line. A directive ends at the newline, so anything typed
 * across several — a JSON body laid out for reading — is written compact when
 * it parses and joined with spaces when it does not.
 */
function directiveValue(key: string, value: string): string {
  if (key === "values") return encodeCreateValues(value);
  if (!/[\r\n]/.test(value)) return value;
  try {
    return JSON.stringify(JSON.parse(value));
  } catch {
    return value
      .split(/\r?\n/)
      .map((line) => line.trim())
      .filter(Boolean)
      .join(" ");
  }
}

/** The `%%step` directives that describe one step, wherever it is emitted. */
function stepDirectives(step: AutomationStep, nodeId: string): string[] {
  const out = [
    `%%step ${nodeId} type: ${step.type}${step.resultName ? ` as: ${step.resultName}` : ""}`,
  ];
  for (const [k, v] of Object.entries(step.props)) {
    if (v) out.push(`%%step ${nodeId} ${k}: ${directiveValue(k, v)}`);
  }
  if (step.table) out.push(`%%step ${nodeId} table: ${JSON.stringify(step.table)}`);
  if (step.loopId) out.push(`%%step ${nodeId} in: ${step.loopId}`);
  return out;
}

function serializeHookWorkflow(a: Automation): string {
  const entity = a.trigger.entity || "Record";
  const lines = ["flowchart TD", `    request[Request] --> validate[Validate ${entity}]`];

  let previous = "validate";
  a.hooks.forEach((hook, index) => {
    const id = `hook${index + 1}`;
    lines.push(`    ${previous} --> ${id}[${hook.event}: ${hook.handler}]`);
    previous = id;
  });

  // The steps follow the hook chain, so the diagram reads as one run rather
  // than a trigger floating beside it.
  a.steps.forEach((step, index) => {
    const id = `s${index + 1}`;
    lines.push(`    ${previous} --> ${id}[${describeStep(step)}]`);
    previous = id;
  });

  lines.push(`    ${previous} --> done[Response]`, "");

  for (const hook of a.hooks) {
    lines.push(
      `    %%hook ${hook.event} ${hook.handler} on ${entity}` +
        (hook.field ? `[field: ${hook.field}]` : "")
    );
  }

  for (const c of a.conditions) {
    lines.push(`    %%guard ${c.field} ${c.operator} ${JSON.stringify(c.value)}`);
  }

  for (const loop of loopsOf(a)) {
    if (stepsInLoop(a, loop.id).length === 0) continue;
    const c = loop.condition;
    lines.push(
      `    %%loop ${loop.id} while: ${c.field} ${c.operator} ${JSON.stringify(c.value)} max: ${loop.maxPasses}`
    );
  }

  a.steps.forEach((step, index) => {
    for (const line of stepDirectives(step, `s${index + 1}`)) lines.push(`    ${line}`);
  });

  return lines.join("\n");
}

/** The `%%workflow` directive names an identifier, not a title. */
function pascalName(value: string): string {
  const cleaned = value.replace(/[^A-Za-z0-9]+/g, " ").trim();
  if (!cleaned) return "Workflow";
  return cleaned
    .split(" ")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join("");
}

export interface SerializeOptions {
  /**
   * Whether to write the `%%workflow` / `%%meta` header into the body.
   *
   * The automations screen stores this string as the whole record, so it needs
   * the header. The wizard's Logic step stores name, entity, kind, trigger and
   * operation as columns and lets language/composer.ts write the directive, so
   * including it there produces the header twice.
   */
  header?: boolean;
}

export function serializeAutomation(a: Automation, options: SerializeOptions = {}): string {
  if (a.kind === "hook") return serializeHookWorkflow(a);
  const header = options.header ?? true;

  const lines: string[] = [];
  lines.push("flowchart TD");
  if (header) lines.push(`%%meta kind: workflow`);

  if (!header) {
    // Nothing: the caller owns the directive.
  } else if (a.kind === "saga") {
    // The positional form, matching what language/composer.ts writes. `trigger`
    // and `operation` live here and nowhere else, so emitting the automation
    // form instead would silently demote a rule-triggered saga to a lifecycle
    // one. Both are written only when they differ from the default, which is
    // the composer's rule too.
    const trigger = a.sagaTrigger === "rule" ? " trigger: rule" : "";
    const operation =
      a.sagaOperation && a.sagaOperation !== "CREATE" ? ` operation: ${a.sagaOperation}` : "";
    const onStatus = a.onStatus ? ` status: ${a.onStatus}` : "";
    lines.push(
      `%%workflow ${pascalName(a.name)} entity: ${a.trigger.entity} kind: saga${trigger}${operation}${onStatus}`
    );
  } else {
    lines.push(`%%workflow name: ${a.name}`);
    lines.push(`%%hook ${TRIGGER_HOOKS[a.trigger.event]} on ${a.trigger.entity}`);
  }

  for (const c of a.conditions) {
    lines.push(`%%guard ${c.field} ${c.operator} ${JSON.stringify(c.value)}`);
  }

  for (const loop of loopsOf(a)) {
    if (stepsInLoop(a, loop.id).length === 0) continue;
    const c = loop.condition;
    lines.push(
      `%%loop ${loop.id} while: ${c.field} ${c.operator} ${JSON.stringify(c.value)} max: ${loop.maxPasses}`
    );
  }

  // The edge chain, where a loop contributes its subgraph id once rather than
  // each of its members — the repeat is one unit in the flow.
  const ids: string[] = ["start"];
  // A saga does not start from `trigger.event` — that field is only an
  // approximation of `operation`, so labelling the start node with it told a
  // rule-triggered saga it "is created". Say what actually begins the run.
  const startLabel =
    a.kind === "saga"
      ? a.sagaTrigger === "rule"
        ? `${a.trigger.entity} — a rule decides`
        : `${a.trigger.entity} ${SAGA_OPERATION_LABELS[a.sagaOperation ?? "CREATE"]}`
      : `${a.trigger.entity} ${TRIGGER_LABELS[a.trigger.event]}`;
  lines.push(`  start([${startLabel}])`);

  if (a.conditions.length > 0) {
    ids.push("guard");
    lines.push(`  guard{${a.conditions.map(describeCondition).join(" and ")}}`);
  }

  /** Directives for one step, kept out of the node loop so the subgraph body stays clean. */
  const directives: string[] = [];
  const emit = (step: AutomationStep, nodeId: string) => {
    directives.push(...stepDirectives(step, nodeId));
  };

  let openLoop: string | null = null;
  a.steps.forEach((step, i) => {
    const nodeId = `s${i + 1}`;

    if (step.loopId !== openLoop) {
      if (openLoop) lines.push("  end");
      openLoop = step.loopId ?? null;
      if (openLoop) {
        const loop = loopsOf(a).find((l) => l.id === openLoop);
        // A `subgraph` is real Mermaid, so the repeat is visible to any
        // renderer rather than being knowable only from the directives.
        lines.push(`  subgraph ${openLoop}[${loop ? describeLoop(loop) : "Repeat"}]`);
        ids.push(openLoop);
      }
    }

    lines.push(`  ${openLoop ? "  " : ""}${nodeId}[${describeStep(step)}]`);
    if (!openLoop) ids.push(nodeId);
    emit(step, nodeId);
  });
  if (openLoop) lines.push("  end");

  lines.push(...directives);

  ids.push("done");
  lines.push("  done([Done])");

  for (let i = 0; i < ids.length - 1; i++) {
    lines.push(`  ${ids[i]} --> ${ids[i + 1]}`);
  }

  return lines.join("\n");
}

/**
 * Read a flowchart back into the model.
 *
 * Anything the directives do not describe is dropped rather than guessed at —
 * a half-understood automation that silently loses a step is worse than one
 * that opens with the steps it could actually read.
 */
/**
 * Which trigger a saga's `operation:` denotes.
 *
 * A saga names the CRUD operation; an automation names the moment. Sagas run
 * after the write, so each maps to the corresponding `after` event.
 */
/** How each operation reads on a saga's start node. */
const SAGA_OPERATION_LABELS: Record<string, string> = {
  CREATE: "is created",
  UPDATE: "is updated",
  DELETE: "is deleted",
  ALL: "is written",
};

const SAGA_OPERATION_EVENTS: Record<string, TriggerEvent> = {
  CREATE: "created",
  UPDATE: "updated",
  DELETE: "deleted",
};

/**
 * Split a saga step's one-line property list.
 *
 * A value runs to the next `key:` token, so it may contain spaces — a title, a
 * URL, a JSON blob. This is the same rule the generator's own step compiler
 * uses, deliberately: two readers of one directive that disagree about where a
 * value ends is a bug waiting to happen.
 */
function parseSagaProps(rest: string): Record<string, string> {
  const props: Record<string, string> = {};
  // The `(?!\/\/)` is what keeps a URL whole: `url: https://host/path` would
  // otherwise split at `https:`, so a REST step opened in the builder with an
  // empty url. Kept identical in language/checker.ts (parseStepProps) and
  // packages/generator/src/workflows/steps.ts (PROP_SPLIT).
  for (const part of rest.trim().split(/\s+(?=[A-Za-z_]\w*:(?!\/\/))/)) {
    const match = part.match(/^([A-Za-z_]\w*):\s*(.*)$/s);
    if (match?.[1]) props[match[1]] = (match[2] ?? "").trim();
  }
  return props;
}

/**
 * Translate saga property names into the automation model's.
 *
 * The two dialects name the same things differently — a saga's `fields` is an
 * automation's `values`, its `target`/`source` pair on a Formula is `as` plus
 * `left`. Mapping rather than passing through matters: an unmapped key lands in
 * `props` where no inspector renders it, so the step opens looking empty and an
 * author who saves it silently drops the configuration.
 *
 * Anything with no counterpart is kept under its own name rather than dropped,
 * so nothing is lost on a round trip even where the builder cannot yet edit it.
 */
function applySagaProps(entry: AutomationStep, props: Record<string, string>): void {
  const take = (key: string): string | undefined => {
    const value = props[key];
    delete props[key];
    return value;
  };

  // `as:` names the result on every step type that publishes one.
  const as = take("as");
  if (as) entry.resultName = as;

  if (entry.type === "Decision") {
    const table = take("decisionTable");
    if (table) {
      try {
        entry.table = JSON.parse(table) as DecisionTable;
      } catch {
        /* an unreadable table is left off rather than replaced with an empty one */
      }
    }
  } else if (entry.type === "Formula") {
    // A saga writes its result name as `target:` and its operands as
    // `source:`/`value:` and `operand:`.
    const target = take("target");
    if (target && !entry.resultName) entry.resultName = target;
    const source = take("source");
    const value = take("value");
    if (source) entry.props.left = `{{${source}}}`;
    else if (value !== undefined) entry.props.left = value;
    const operand = take("operand");
    if (operand !== undefined) entry.props.right = operand;
  } else if (entry.type === "CreateEntity") {
    const fields = take("fields");
    if (fields !== undefined) entry.props.values = decodeCreateValues(fields);
  } else if (entry.type === "UpdateEntity") {
    // `source:` reads another step's published value; `value:` is a literal.
    const source = take("source");
    if (source) entry.props.value = `{{${source}}}`;
    // A saga aims at another row with targetSource/targetField; the automation
    // model has one `target`, so the row reference wins over the column.
    // Without the column, a model step such as `entity: FeeInvoice targetField:
    // fee_invoice_id` opened as "does not say which one" — on a step that does.
    const targetSource = take("targetSource");
    const targetField = take("targetField");
    if (targetSource) entry.props.target = `{{${targetSource}}}`;
    else if (targetField) entry.props.target = targetField;
  } else if (entry.type === "DeleteEntity") {
    const targetSource = take("targetSource");
    const targetField = take("targetField");
    if (targetSource) entry.props.target = `{{${targetSource}}}`;
    else if (targetField) entry.props.target = targetField;
  } else if (entry.type === "REST") {
    const body = take("bodyTemplate");
    if (body !== undefined) entry.props.body = body;
  }

  for (const [key, value] of Object.entries(props)) {
    if (value) entry.props[key] ??= value;
  }
}

export function parseAutomation(source: string, fallbackEntity = "Record"): Automation {
  const a = emptyAutomation(fallbackEntity);
  const stepsById = new Map<string, AutomationStep>();
  const order: string[] = [];

  for (const raw of source.split("\n")) {
    const line = raw.trim();

    const name = line.match(/^%%workflow\s+name:\s*(.+)$/);
    if (name?.[1]) {
      a.name = name[1].trim();
      continue;
    }

    // The saga form carries the name, entity and operation on one line. Read
    // before the generic %%workflow match so the positional form is not
    // mistaken for a name.
    const saga = line.match(/^%%workflow\s+(\w+)\s+entity:\s*(\w+)(.*)$/);
    if (saga?.[1] && saga[2]) {
      a.name = saga[1];
      const rest = saga[3] ?? "";
      const operation = rest.match(/operation:\s*(\w+)/)?.[1]?.toUpperCase();
      const trigger = rest.match(/trigger:\s*(\w+)/)?.[1];
      a.trigger = { entity: saga[2], event: SAGA_OPERATION_EVENTS[operation ?? ""] ?? "created" };

      // `kind: saga` carries how the run starts on the directive itself. The
      // event above is only an approximation of `operation`, and `trigger: rule`
      // has no lifecycle event at all — keep both verbatim so saving does not
      // rewrite "a rule decides when this runs" into "runs when created".
      if (/kind:\s*saga\b/.test(rest)) {
        a.kind = "saga";
        // Absent means automatic, because the writer only ever emits the token
        // for `rule` — language/composer.ts omits it otherwise. Defaulting the
        // other way turned every automatic saga into a rule-triggered one on
        // the first re-read.
        a.sagaTrigger = trigger === "rule" ? "rule" : "automatic";
        a.sagaOperation =
          operation === "UPDATE" || operation === "DELETE" || operation === "ALL"
            ? operation
            : "CREATE";
      }
      const bound = rest.match(/\bstatus:\s*(\S+)/)?.[1];
      if (bound) a.onStatus = bound;
      continue;
    }

    // The hook-workflow form names a handler between the event and the entity:
    //   %%hook beforeCreate normalizeAccountName on Account[field: name]
    // Matched before the automation form below, whose pattern requires `on`
    // directly after the event and so matches none of these — every handler in
    // a hook workflow was silently dropped, leaving an automation with a
    // default trigger and no steps.
    const handlerHook = line.match(
      /^%%hook\s+(\w+)\s+(\w+)\s+on\s+(\w+)(?:\[\s*field:\s*([^\]]+)\])?/
    );
    if (handlerHook?.[1] && handlerHook[2] && handlerHook[3]) {
      a.kind = "hook";
      a.trigger = { ...a.trigger, entity: handlerHook[3] };
      a.hooks.push({
        id: newId("hook"),
        event: handlerHook[1] as HookEvent,
        handler: handlerHook[2],
        field: handlerHook[4]?.trim() || undefined,
      });
      continue;
    }

    const hook = line.match(/^%%hook\s+(\w+)\s+on\s+(\w+)/);
    if (hook?.[1] && hook[2]) {
      a.trigger = { entity: hook[2], event: HOOK_TO_EVENT[hook[1]] ?? "created" };
      continue;
    }

    const loop = line.match(/^%%loop\s+(\w+)\s+while:\s*(\S+)\s+(\S+)\s*(.*)$/);
    if (loop?.[1] && loop[2] && loop[3]) {
      let rest = (loop[4] ?? "").trim();
      // `max:` closes the directive, so the check's value is whatever precedes it.
      const maxMatch = rest.match(/\s*max:\s*(\S+)\s*$/);
      const maxPasses = maxMatch?.[1] ?? "";
      if (maxMatch) rest = rest.slice(0, rest.length - maxMatch[0].length);
      let value = rest.trim();
      try {
        if (value.startsWith('"')) value = JSON.parse(value) as string;
      } catch {
        /* leave the raw text — better than dropping the check that ends the loop */
      }
      a.loops.push({
        id: loop[1],
        condition: { id: newId("cond"), field: loop[2], operator: loop[3], value },
        maxPasses,
      });
      continue;
    }

    // An RBAC restriction, not a condition. %%guard used to mean both; the
    // RBAC sense is now spelled %%rbac, but a model written before that would
    // otherwise be read as a check on a field literally called "role:admin"
    // with an operator of "on" — a condition that can never pass, silently
    // disabling the automation. Skipped rather than guessed at.
    if (/^%%guard\s+role:\S+\s+on\s+\w+\.\w+\s*$/.test(line)) continue;

    const guard = line.match(/^%%guard\s+(\S+)\s+(\S+)\s*(.*)$/);
    if (guard?.[1] && guard[2]) {
      let value = (guard[3] ?? "").trim();
      try {
        if (value.startsWith('"')) value = JSON.parse(value) as string;
      } catch {
        /* leave the raw text — better than dropping the check */
      }
      a.conditions.push({
        id: newId("cond"),
        field: guard[1],
        operator: guard[2],
        value,
      });
      continue;
    }

    // Saga form: the type sits where the automation form puts `type:`, and
    // every property shares the one line. Matched first because the automation
    // pattern below would read `Decision decisionTable:` as a property named
    // `decisionTable` on an untyped step.
    const sagaStep = line.match(/^%%step\s+(\S+)\s+([A-Za-z]\w*)\s+(.*)$/);
    if (sagaStep?.[2] && STEP_TYPES.includes(sagaStep[2] as StepType)) {
      const [, nodeId = "", typeName = "", rest = ""] = sagaStep;
      let entry = stepsById.get(nodeId);
      if (!entry) {
        entry = { id: newId("step"), type: "Formula", resultName: "", props: {} };
        stepsById.set(nodeId, entry);
        order.push(nodeId);
      }
      entry.type = typeName as StepType;
      applySagaProps(entry, parseSagaProps(rest));
      continue;
    }

    const step = line.match(/^%%step\s+(\S+)\s+(\w+):\s*(.*)$/);
    if (step?.[1] && step[2]) {
      const [, nodeId, key, rest = ""] = step;
      let entry = stepsById.get(nodeId);
      if (!entry) {
        entry = { id: newId("step"), type: "Formula", resultName: "", props: {} };
        stepsById.set(nodeId, entry);
        order.push(nodeId);
      }
      const value = rest.trim();
      if (key === "type") {
        const [typeName = "", ...tail] = value.split(/\s+as:\s*/);
        if (STEP_TYPES.includes(typeName.trim() as StepType)) {
          entry.type = typeName.trim() as StepType;
        }
        if (tail[0]) entry.resultName = tail[0].trim();
      } else if (key === "as") {
        entry.resultName = value;
      } else if (key === "table") {
        try {
          entry.table = JSON.parse(value) as DecisionTable;
        } catch {
          /* an unreadable table is left off rather than replaced with an empty one */
        }
      } else if (key === "in") {
        entry.loopId = value;
      } else if (key === "values") {
        entry.props[key] = decodeCreateValues(value);
      } else if (key === "targetSource") {
        // Which record, as the one-line saga form reads it (`applySagaProps`):
        // a reference wins over a column, whichever line comes first.
        entry.props.target = `{{${value}}}`;
      } else if (key === "targetField") {
        if (!entry.props.target?.startsWith("{{")) entry.props.target = value;
      } else {
        entry.props[key] = value;
      }
    }
  }

  a.steps = order.map((id) => stepsById.get(id)).filter((s): s is AutomationStep => Boolean(s));

  // A membership naming a loop that was never declared would render as a box
  // with no repeat count and execute once, which is not what the document says.
  // Dropping the membership keeps the step, which is the recoverable half.
  const declared = new Set(loopsOf(a).map((loop) => loop.id));
  for (const step of a.steps) {
    if (step.loopId && !declared.has(step.loopId)) step.loopId = undefined;
  }
  // An empty loop is not drawn and not run, so it is not kept either.
  a.loops = loopsOf(a).filter((loop) => a.steps.some((step) => step.loopId === loop.id));

  return a;
}

/**
 * Monaco, served by this application.
 *
 * The GoRules editor draws its code boxes — the Record schema, a function
 * node's source, the Simulator's request — with Monaco, and Monaco's loader
 * fetches itself from a public CDN unless an instance is already on `window`.
 * That put a third-party host between a person and their own rules: the boxes
 * sat on a spinner behind a firewall or offline. Importing it here makes Vite
 * bundle it and its workers beside the application.
 *
 * The loader is then told which Monaco to use with `loader.config({ monaco })`,
 * not left to find it on `window`. Its fallback, when it has neither, is a
 * script tag pointing at jsdelivr — reachable whenever an editor mounted before
 * this module ran. Configured, it has no CDN path at all. `@monaco-editor/loader`
 * holds that state and has no peer dependencies, so jdm-editor's copy of
 * `@monaco-editor/react` and this import share one instance of it.
 *
 * The workers are imported from the one-line entries in `monaco-workers/`, not
 * as `monaco-editor/editor/editor.worker?worker`. A query on a package subpath
 * reaches monaco's `exports` map, whose `"./*": "./esm/vs/*.js"` can swallow it:
 * on macOS the id came back as `editor.worker.js?worker.js`, Vite read
 * `worker.js` as no worker query at all, served the file as a plain module, and
 * the page failed with `does not provide an export named 'default'`. A relative
 * path never goes through `exports`, and each entry imports the worker with no
 * query, which resolves the same everywhere.
 *
 * Browser only. Import it from the same lazy chunk as the editor, never from a
 * module the server renders.
 */

import loader from "@monaco-editor/loader";
import * as monaco from "monaco-editor";
// @ts-expect-error — the language services, which have no type declarations of their own.
import * as jsonApi from "monaco-editor/language/json/monaco.contribution";
// @ts-expect-error — as above.
import * as typescriptApi from "monaco-editor/language/typescript/monaco.contribution";
import EditorWorker from "./monaco-workers/editor.worker?worker";
import JsonWorker from "./monaco-workers/json.worker?worker";
import TypeScriptWorker from "./monaco-workers/ts.worker?worker";

declare global {
  interface Window {
    monaco?: typeof monaco;
    MonacoEnvironment?: { getWorker: (moduleId: string, label: string) => Worker };
  }
}

if (typeof window !== "undefined" && !window.monaco) {
  // Monaco 0.55 moved the TypeScript and JSON language APIs out of
  // `monaco.languages`. The GoRules editor still reads them from there (a
  // function node's editor starts with `languages.typescript.javascriptDefaults`),
  // so they are put back where it looks.
  const languages = monaco.languages as unknown as Record<string, unknown>;
  languages.typescript ??= typescriptApi;
  languages.json ??= jsonApi;

  window.MonacoEnvironment = {
    getWorker(_moduleId, label) {
      if (label === "json") return new JsonWorker();
      if (label === "typescript" || label === "javascript") return new TypeScriptWorker();
      return new EditorWorker();
    },
  };
  window.monaco = monaco;
  loader.config({ monaco });
}

export { monaco };

/**
 * Picking a Date operator in a decision table must not blank the page.
 *
 * The GoRules editor ships its own copy of dayjs inside its bundle and hands
 * dates from it to Ant Design's date panel. The panel's calendar logic
 * (`rc-picker`'s dayjs adapter) calls `weekday()` on whatever date it is given,
 * and that plugin is only installed on the *other* copy — so the first click on
 * an operator such as "after" threw "clone.weekday is not a function", React
 * unmounted the Logic page, and the author saw "Something went wrong!".
 *
 * Every date the adapter receives is therefore re-made with the dayjs the
 * adapter itself was written against, when it came from a copy that lacks the
 * plugin. Dates it hands back are already that copy's own.
 */

import dayjs from "dayjs";
import generateConfig from "rc-picker/es/generate/dayjs";

type DateLike = { $d?: unknown; weekday?: unknown; valueOf: () => number; locale?: () => string };

const isForeign = (value: unknown): value is DateLike =>
  typeof value === "object" &&
  value !== null &&
  "$d" in value &&
  typeof (value as DateLike).weekday !== "function";

const adopt = (value: unknown): unknown =>
  isForeign(value) ? dayjs(value.valueOf()).locale(value.locale?.() ?? "en") : value;

const adapter = generateConfig as unknown as Record<string, unknown>;
const marker = "__appwithaiAdopts";

if (!adapter[marker]) {
  for (const key of Object.keys(adapter)) {
    const original = adapter[key];
    if (typeof original !== "function") continue;
    adapter[key] = (...args: unknown[]) =>
      (original as (...a: unknown[]) => unknown)(...args.map(adopt));
  }
  adapter[marker] = true;
}

/**
 * Reading and writing the workflow model that lives inside BPMN.
 *
 * bpmn-js owns the diagram; this owns what the diagram *means*. Every
 * executable step is a `bpmn:serviceTask` whose behaviour is carried by
 * `appwithai:property` extension elements, and the executor runs them in
 * sequence-flow order. These functions read that back out — in the same order
 * the executor will use — so the editor can show a workflow's variable wiring
 * without guessing.
 *
 * Kept free of React and of bpmn-js so both applications can share it and so
 * the analysis can be tested without a browser.
 */

/** Step types the generated executor knows how to run. */
export const STEP_TYPES = [
  "Decision",
  "CreateEntity",
  "UpdateEntity",
  "DeleteEntity",
  "Formula",
  "REST",
] as const;

export type StepType = (typeof STEP_TYPES)[number];

export const STEP_LABELS: Record<StepType, string> = {
  Decision: "Decision",
  CreateEntity: "Create",
  UpdateEntity: "Update",
  DeleteEntity: "Delete",
  Formula: "Formula",
  REST: "REST call",
};

export const STEP_HINTS: Record<StepType, string> = {
  Decision: "Run a decision table and publish what it decides.",
  CreateEntity: "Insert a row, and remember its id for later steps.",
  UpdateEntity: "Write one column, on this record or a related one.",
  DeleteEntity: "Delete a record. Soft by default, so the audit trail resolves.",
  Formula: "Work out a value, or stage a literal, for a later step.",
  REST: "Call an external endpoint.",
};

export interface WorkflowStep {
  /** The bpmn element id — stable, and what selection is keyed on. */
  id: string;
  name: string;
  type: StepType | string;
  props: Record<string, string>;
}

/* -------------------------------------------------------------------------- */
/*  Decision tables                                                            */
/* -------------------------------------------------------------------------- */

export interface DecisionColumn {
  id: string;
  name: string;
  /** Context key read (inputs) or published (outputs). */
  field: string;
  /** When set, the cell renders as a dropdown constrained to these values. */
  options?: string[];
}

/** The output columns the rule engine recognises. */
export const KNOWN_OUTPUT_FIELDS = [
  { field: "action", label: "Action" },
  { field: "message", label: "Message" },
  { field: "ruleId", label: "Rule ID" },
  { field: "workflowName", label: "Workflow Name" },
  { field: "field", label: "Field" },
  { field: "value", label: "Value" },
  { field: "targetEntity", label: "Target Entity" },
  { field: "linkField", label: "Link Field" },
] as const;

/** Auto-applied options when a column field matches a known name. */
export const WELL_KNOWN_OPTIONS: Record<string, string[]> = {
  action: ["trigger-workflow", "validation-error", "transform"],
};

export function getColumnOptions(col: DecisionColumn): string[] | undefined {
  if (col.options && col.options.length > 0) return col.options;
  const key = col.field.trim().toLowerCase();
  return WELL_KNOWN_OPTIONS[key];
}

export interface DecisionRow {
  _id: string;
  [cell: string]: string;
}

export interface DecisionTable {
  hitPolicy: "first" | "collect";
  inputs: DecisionColumn[];
  outputs: DecisionColumn[];
  rules: DecisionRow[];
}

export function emptyDecisionTable(): DecisionTable {
  return {
    hitPolicy: "first",
    inputs: [{ id: "i1", name: "Input", field: "" }],
    outputs: [{ id: "o1", name: "Output", field: "" }],
    rules: [{ _id: newRowId(), i1: "", o1: "" }],
  };
}

let rowCounter = 0;
export function newRowId(): string {
  return `r${(rowCounter++).toString(36)}${Date.now().toString(36)}`;
}

export function parseDecisionTable(json: string | undefined): DecisionTable | null {
  if (!json?.trim()) return null;
  try {
    const parsed = JSON.parse(json) as Partial<DecisionTable>;
    if (!parsed || typeof parsed !== "object") return null;
    return {
      hitPolicy: parsed.hitPolicy === "collect" ? "collect" : "first",
      inputs: Array.isArray(parsed.inputs) ? parsed.inputs : [],
      outputs: Array.isArray(parsed.outputs) ? parsed.outputs : [],
      rules: Array.isArray(parsed.rules) ? (parsed.rules as DecisionRow[]) : [],
    };
  } catch {
    return null;
  }
}

/**
 * Serialise a table, filling in the cells a row leaves blank.
 *
 * zen-engine silently discards a row that does not carry a value for every
 * output column the table declares — and one dropped row is enough to stop the
 * whole table matching. Rather than make that the author's problem, every
 * output cell is written, using `''` where they left it empty.
 */
export function serializeDecisionTable(table: DecisionTable): string {
  const rules = table.rules.map((row) => {
    const complete: DecisionRow = { _id: row._id || newRowId() };
    for (const input of table.inputs) complete[input.id] = row[input.id] ?? "";
    for (const output of table.outputs) {
      const cell = (row[output.id] ?? "").trim();
      complete[output.id] = cell || "''";
    }
    return complete;
  });
  return JSON.stringify({ ...table, rules });
}

/** Problems that make a table match nothing, stated as the author would see them. */
/* -------------------------------------------------------------------------- */
/*  Whole-record checks                                                         */
/* -------------------------------------------------------------------------- */

type Scalar = string | number | boolean | null;

const IDENTIFIER = /^[A-Za-z_][\w.]*$/;
const COMPARISON = /^\s*([A-Za-z_][\w.]*)\s*(==|!=|>=|<=|>|<)\s*(.+?)\s*$/;
const KEYWORDS = new Set(["true", "false", "null", "and", "or"]);

function plainText(s: string): string {
  const t = s.trim();
  if (t.length >= 2 && (t.startsWith('"') || t.startsWith("'")) && t.endsWith(t[0] as string)) {
    return t.slice(1, -1);
  }
  return t;
}

/** What a test box holds: blank is null, and numbers and booleans are read as such. */
function typedValue(raw: string | undefined): Scalar {
  const text = (raw ?? "").trim();
  if (!text || text === "null") return null;
  if (text === "true") return true;
  if (text === "false") return false;
  if (/^-?\d+(\.\d+)?$/.test(text)) return Number(text);
  return plainText(text);
}

function operand(text: string, values: Record<string, string>): Scalar | undefined {
  const t = text.trim();
  if (/^(["']).*\1$/.test(t)) return t.slice(1, -1);
  if (t === "null") return null;
  if (t === "true") return true;
  if (t === "false") return false;
  if (/^-?\d+(\.\d+)?$/.test(t)) return Number(t);
  if (IDENTIFIER.test(t)) return typedValue(values[t]);
  return undefined;
}

function compare(left: Scalar, op: string, right: Scalar): boolean {
  switch (op) {
    case "==":
      return left === right;
    case "!=":
      return left !== right;
    default: {
      if (typeof left !== "number" || typeof right !== "number") return false;
      if (op === ">") return left > right;
      if (op === ">=") return left >= right;
      if (op === "<") return left < right;
      return left <= right;
    }
  }
}

/**
 * Evaluate a check of the form `field op value`, joined by `and` / `or`
 * (`and` binding tighter), against typed test values. Returns `undefined`
 * for anything outside that shape, so the caller never claims a verdict on
 * an expression it could not read.
 */
export function evaluateExpression(
  expression: string,
  values: Record<string, string>
): boolean | undefined {
  let any = false;
  for (const clause of expression.split(/\s+or\s+/)) {
    let all = true;
    for (const part of clause.split(/\s+and\s+/)) {
      const m = part.match(COMPARISON);
      if (!m) return undefined;
      const right = operand(m[3] ?? "", values);
      if (right === undefined) return undefined;
      all = compare(typedValue(values[m[1] ?? ""]), m[2] ?? "==", right) && all;
    }
    any = any || all;
  }
  return any;
}

/** The fields a table's whole-record checks read, in the order they appear. */
export function expressionFields(table: DecisionTable): string[] {
  const fields = new Set<string>();
  for (const col of table.inputs) {
    if (col.field.trim()) continue;
    for (const row of table.rules) {
      const cell = row[col.id] ?? "";
      for (const part of cell.split(/\s+(?:and|or)\s+/)) {
        const m = part.match(COMPARISON);
        if (!m) continue;
        if (m[1]) fields.add(m[1]);
        const right = (m[3] ?? "").trim();
        if (IDENTIFIER.test(right) && !KEYWORDS.has(right)) fields.add(right);
      }
    }
  }
  return [...fields];
}

export function validateDecisionTable(table: DecisionTable): string[] {
  const problems: string[] = [];
  if (table.inputs.length === 0) problems.push("Add at least one input column to test against.");
  if (table.outputs.length === 0) {
    problems.push("Add at least one output column — a table that publishes nothing does nothing.");
  }
  if (table.rules.length === 0) problems.push("Add at least one row.");

  for (const input of table.inputs) {
    // Under `collect` (what `%%action` compiles to) an input with no field
    // reads the whole record, and each of its cells is a check on it.
    if (!input.field.trim() && table.hitPolicy !== "collect") {
      problems.push(`Input "${input.name || input.id}" reads no field.`);
    }
  }
  for (const output of table.outputs) {
    if (!output.field.trim()) {
      problems.push(`Output "${output.name || output.id}" publishes under no name.`);
    }
  }
  return problems;
}

/* -------------------------------------------------------------------------- */
/*  Variable flow                                                              */
/* -------------------------------------------------------------------------- */

export interface VariableFact {
  name: string;
  /** Step that publishes it, by name. */
  publishedBy?: string;
  publishedByIndex?: number;
  /** Steps that read it, by name. */
  usedBy: string[];
  /**
   * `unused`    published and never read
   * `late`      read by a step that runs before the one publishing it
   * `external`  read but never published — a column of the triggering record
   */
  problem?: "unused" | "late" | "external";
}

/** Variables a step makes available to the ones after it. */
export function publishedBy(step: WorkflowStep): string[] {
  const props = step.props;

  if (step.type === "CreateEntity") {
    const explicit = props.as?.trim();
    if (explicit) return [explicit];
    const entity = props.entity?.trim();
    return entity ? [`${entity.replace(/^bus_/, "")}Id`] : [];
  }

  if (step.type === "Formula") {
    const target = props.target?.trim();
    return target ? [target] : [];
  }

  if (step.type === "Decision") {
    const allowed = splitList(props.publish);
    if (allowed.length > 0) return allowed;
    const table = parseDecisionTable(props.decisionTable);
    if (!table) return [];
    return table.outputs.map((output) => output.field.trim()).filter(Boolean);
  }

  return [];
}

/** Variables a step reads. */
export function consumedBy(step: WorkflowStep): string[] {
  const props = step.props;
  const names = new Set<string>();

  for (const key of ["source", "targetSource"]) {
    const value = props[key]?.trim();
    if (value) names.add(value);
  }

  // A CreateEntity's field map is column -> context key or literal, and the
  // executor substitutes anything that names a key. Every value is therefore a
  // candidate; the caller decides which ones actually resolve.
  if (step.type === "CreateEntity" && props.fields) {
    try {
      const map = JSON.parse(props.fields) as Record<string, unknown>;
      for (const value of Object.values(map)) {
        if (typeof value === "string" && value.trim()) names.add(value.trim());
      }
    } catch {
      // A malformed map is reported elsewhere; it publishes no reads here.
    }
  }

  // REST bodies interpolate {{key}}.
  if (step.type === "REST" && props.bodyTemplate) {
    for (const match of props.bodyTemplate.matchAll(/\{\{\s*([\w.]+)\s*\}\}/g)) {
      if (match[1]) names.add(match[1]);
    }
  }

  // A decision reads whatever its input columns name.
  if (step.type === "Decision") {
    const table = parseDecisionTable(props.decisionTable);
    for (const input of table?.inputs ?? []) {
      if (input.field.trim()) names.add(input.field.trim());
    }
  }

  return [...names];
}

/**
 * The reads a step is definitely making, as opposed to might be.
 *
 * A CreateEntity field map holds column -> value, and the executor substitutes
 * a value that happens to name something in context. So `"internal"` is a
 * literal until the moment it isn't, and reporting every such literal as an
 * undefined variable buried the real warnings in noise. Those values still
 * count as reads when they *do* resolve — that is the useful half — but they
 * never raise "nothing publishes this".
 */
export function definitelyConsumedBy(step: WorkflowStep): string[] {
  const names = new Set<string>();
  for (const key of ["source", "targetSource"]) {
    const value = step.props[key]?.trim();
    if (value) names.add(value);
  }
  for (const name of consumedBy(step)) {
    if (step.type === "Decision" || step.type === "REST") names.add(name);
  }
  return [...names];
}

/**
 * Work out where every variable comes from and who reads it.
 *
 * This is the part a list of steps cannot show you. A workflow only does
 * something because one step hands a value to a later one, and the three ways
 * that silently fails — publishing something nobody reads, reading something
 * published later, reading something nobody publishes at all — all look
 * identical at runtime: the step just quietly does nothing.
 *
 * `entityColumns`, when known, separates "reads a column of the triggering
 * record" (fine, and the commonest case) from "reads a name nothing defines".
 */
export function analyzeVariables(
  steps: WorkflowStep[],
  entityColumns: string[] = []
): VariableFact[] {
  const columns = new Set(entityColumns.map((column) => column.toLowerCase()));
  const facts = new Map<string, VariableFact>();
  const publishIndex = new Map<string, number>();

  const fact = (name: string): VariableFact => {
    let existing = facts.get(name);
    if (!existing) {
      existing = { name, usedBy: [] };
      facts.set(name, existing);
    }
    return existing;
  };

  steps.forEach((step, index) => {
    for (const name of publishedBy(step)) {
      const entry = fact(name);
      // First publisher wins, which is what the executor does: a later write
      // overwrites the value, but the variable came into being here.
      if (entry.publishedByIndex === undefined) {
        entry.publishedBy = step.name || step.type;
        entry.publishedByIndex = index;
        publishIndex.set(name, index);
      }
    }
  });

  steps.forEach((step, index) => {
    const definite = new Set(definitelyConsumedBy(step));
    for (const name of consumedBy(step)) {
      const publishedAt = publishIndex.get(name);
      const isColumn = columns.has(name.toLowerCase());
      if (publishedAt === undefined && !isColumn && !looksLikeVariable(name)) continue;

      // A value in a create's field map that resolves to nothing is a literal,
      // not a broken read — record it only when something does publish it.
      if (publishedAt === undefined && !isColumn && !definite.has(name)) continue;

      const entry = fact(name);
      const reader = step.name || step.type;
      if (!entry.usedBy.includes(reader)) entry.usedBy.push(reader);

      if (publishedAt !== undefined && publishedAt > index) entry.problem = "late";
      else if (publishedAt === undefined && !isColumn) entry.problem ??= "external";
    }
  });

  for (const entry of facts.values()) {
    if (entry.publishedByIndex !== undefined && entry.usedBy.length === 0) {
      entry.problem = "unused";
    }
  }

  // Publishers first, in the order they run, so the table reads down the flow.
  // Ties keep insertion order — two outputs of one decision table should read
  // in the order the table declares them, not alphabetically.
  const seen = [...facts.values()];
  return seen
    .map((entry, order) => ({ entry, order }))
    .sort((a, b) => {
      const left = a.entry.publishedByIndex ?? Number.MAX_SAFE_INTEGER;
      const right = b.entry.publishedByIndex ?? Number.MAX_SAFE_INTEGER;
      return left - right || a.order - b.order;
    })
    .map(({ entry }) => entry);
}

export function describeProblem(fact: VariableFact): string | null {
  if (fact.problem === "unused") {
    return `${fact.name} is published but never read. Wire it into a later step, or drop it.`;
  }
  if (fact.problem === "late") {
    return `${fact.name} is read before ${fact.publishedBy} publishes it, so the step that reads it will be skipped. Move that step earlier.`;
  }
  if (fact.problem === "external") {
    return `${fact.name} is read but nothing publishes it — it has to be a column of the triggering record, or the step is skipped.`;
  }
  return null;
}

/** A bare identifier, which is what a context key looks like. */
function looksLikeVariable(value: string): boolean {
  return /^[A-Za-z_][\w.]*$/.test(value);
}

export function splitList(value: string | undefined): string[] {
  return (value ?? "")
    .split(",")
    .map((entry) => entry.trim())
    .filter(Boolean);
}

/* -------------------------------------------------------------------------- */
/*  Step requirements                                                          */
/* -------------------------------------------------------------------------- */

/**
 * What a step still needs before it will run.
 *
 * The executor skips a step missing these and writes a line to the log, which
 * is a bad place to find out that a workflow has been quietly doing nothing —
 * so the editor says so while it is being drawn.
 */
export function missingRequirements(step: WorkflowStep): string[] {
  const has = (key: string) => (step.props[key] ?? "").trim().length > 0;
  const missing: string[] = [];

  if (step.type === "Decision") {
    if (!has("decisionTable") && !has("rule")) {
      missing.push("a decision table, or the name of a rule to evaluate");
    } else if (has("decisionTable")) {
      const table = parseDecisionTable(step.props.decisionTable);
      if (!table) missing.push("a decision table that parses");
      else missing.push(...validateDecisionTable(table));
    }
  }

  if (step.type === "UpdateEntity") {
    if (!has("field")) missing.push("the column to write");
    if (!has("source") && !has("value")) missing.push("a value, or a variable to read it from");
    if (has("entity") && !has("targetSource") && (step.props.targetField ?? "id").trim() === "id") {
      missing.push("which row of that entity to write — name a variable holding its id");
    }
  }

  if (step.type === "CreateEntity") {
    if (!has("entity")) missing.push("the entity to insert into");
    let count = 0;
    try {
      count = Object.keys(JSON.parse(step.props.fields || "{}")).length;
    } catch {
      missing.push("a valid column map");
    }
    if (count === 0) missing.push("at least one column to set");
  }

  if (step.type === "DeleteEntity") {
    if (has("entity") && !has("targetSource") && (step.props.targetField ?? "id").trim() === "id") {
      missing.push("which row to delete — name a variable holding its id");
    }
  }

  if (step.type === "Formula") {
    if (!has("target")) missing.push("a variable to store the result in");
    const operation = (step.props.operation ?? "set").trim();
    if (operation === "set" && !has("value")) missing.push("a value to stage");
    else if (operation === "copy" && !has("source")) missing.push("a variable to copy from");
    else if (operation !== "set" && operation !== "copy" && (!has("source") || !has("operand"))) {
      missing.push(`${operation} needs both a source variable and an operand`);
    }
  }

  if (step.type === "REST" && !has("url")) missing.push("the URL to call");

  return missing;
}

/**
 * Hook Syntax Parser
 *
 * Parses hook definitions from Mermaid flowchart comments.
 * Syntax: %%hook <hookType> <hookName> on <EntityName>
 *
 * Examples:
 * %%hook beforeCreate hashPassword on User
 * %%hook afterCreate sendWelcomeEmail on User
 * %%hook beforeCreate generateSlug on Post[field: slug]
 */

export type HookType =
  | "beforeCreate"
  | "afterCreate"
  | "beforeUpdate"
  | "afterUpdate"
  | "beforeDelete"
  | "afterDelete"
  | "beforeQuery"
  | "afterQuery"
  | "customValidate"
  | "beforeRead"
  | "afterRead"
  | "beforeList"
  | "afterList";

export interface HookParameter {
  name: string;
  type: string;
}

export interface ParsedHookDefinition {
  type: HookType;
  name: string;
  entity: string;
  parameters?: HookParameter[];
  rawComment: string;
  order: number;
}

export interface ParseResult {
  hooks: ParsedHookDefinition[];
  errors: string[];
  warnings: string[];
}

const HOOK_TYPE_PATTERN =
  /^(beforeCreate|afterCreate|beforeUpdate|afterUpdate|beforeDelete|afterDelete|beforeQuery|afterQuery|customValidate|beforeRead|afterRead|beforeList|afterList)$/;

const HOOK_COMMENT_PATTERN =
  /%%hook\s+(\w+)\s+(\w+)\s+on\s+(\w+)(\[(?:field:\s*\w+(?:\s*,\s*field:\s*\w+)*)?\])?/;

/**
 * Parse a single hook comment line
 */
export function parseHookComment(comment: string, order: number): ParsedHookDefinition | null {
  const trimmedComment = comment.trim();

  if (!trimmedComment.startsWith("%%hook")) {
    return null;
  }

  const match = trimmedComment.match(HOOK_COMMENT_PATTERN);

  if (!match) {
    return null;
  }

  const [, hookTypeStr, hookName, entity, paramsStr] = match;

  // Validate hook type
  if (!hookTypeStr || !HOOK_TYPE_PATTERN.test(hookTypeStr)) {
    return null;
  }

  if (!hookName || !entity) {
    return null;
  }

  const hookType = hookTypeStr as HookType;

  // Parse parameters if present
  let parameters: HookParameter[] | undefined;
  if (paramsStr) {
    parameters = parseParameters(paramsStr);
  }

  return {
    type: hookType,
    name: hookName,
    entity,
    parameters,
    rawComment: trimmedComment,
    order,
  };
}

/**
 * Parse parameters from hook comment
 * Format: [field: password, field: email]
 */
function parseParameters(paramsStr: string): HookParameter[] {
  const parameters: HookParameter[] = [];

  // Remove brackets and split by comma
  const content = paramsStr.slice(1, -1).trim();

  if (!content) {
    return parameters;
  }

  const parts = content.split(",").map((p) => p.trim());

  for (const part of parts) {
    // Match "field: fieldName" or just "fieldName"
    const fieldMatch = part.match(/^field:\s*(\w+)$/);
    if (fieldMatch?.[1]) {
      parameters.push({ name: fieldMatch[1], type: "field" });
    } else if (part.match(/^\w+$/)) {
      parameters.push({ name: part, type: "unknown" });
    }
  }

  return parameters;
}

/**
 * Parse hook definitions from Mermaid flowchart code
 */
export function parseHooksFromFlowchart(flowchartCode: string): ParseResult {
  const hooks: ParsedHookDefinition[] = [];
  const errors: string[] = [];
  const warnings: string[] = [];

  const lines = flowchartCode.split("\n");
  let hookOrder = 0;

  for (const line of lines) {
    const trimmedLine = line.trim();

    // Skip empty lines and non-comments
    if (!trimmedLine?.startsWith("%%")) {
      continue;
    }

    // Try to parse as hook comment
    const hook = parseHookComment(trimmedLine, hookOrder);

    if (hook) {
      hooks.push(hook);
      hookOrder++;
    } else if (trimmedLine.startsWith("%%hook")) {
      // It looks like a hook comment but failed to parse
      errors.push(`Invalid hook syntax: "${trimmedLine}"`);
    }
  }

  return {
    hooks,
    errors,
    warnings,
  };
}

/**
 * Generate hook comment from hook definition
 */
export function generateHookComment(hook: ParsedHookDefinition): string {
  let comment = `%%hook ${hook.type} ${hook.name} on ${hook.entity}`;

  if (hook.parameters && hook.parameters.length > 0) {
    const params = hook.parameters.map((p) => `field: ${p.name}`).join(", ");
    comment += `[field: ${params}]`;
  }

  return comment;
}

/**
 * Generate Mermaid flowchart from hook definitions
 */
export function generateFlowchartFromHooks(
  entityName: string,
  hooks: ParsedHookDefinition[]
): string {
  let flowchart = `flowchart TD\n`;
  flowchart += `    A[Client Request] --> B[Validate Request]\n`;

  // Add hook nodes
  hooks.forEach((hook, index) => {
    const letter = String.fromCharCode(66 + index); // B, C, D, ...

    if (hook.type !== "customValidate") {
      flowchart += `    B --> ${letter}[${hook.type}: ${hook.name}]\n`;

      if (index === hooks.length - 1) {
        flowchart += `    ${letter} --> C[Process ${entityName}]\n`;
      } else {
        const nextLetter = String.fromCharCode(66 + index + 1);
        flowchart += `    ${letter} --> ${nextLetter}\n`;
      }
    }
  });

  if (hooks.length === 0) {
    flowchart += `    B --> C[Process ${entityName}]\n`;
  }

  flowchart += `    C --> D[Response]\n`;
  flowchart += `    D --> E[Return to Client]\n\n`;

  // Add hook comments
  hooks.forEach((hook) => {
    flowchart += `    ${generateHookComment(hook)}\n`;
  });
  flowchart += `\n`;

  // Add styling
  flowchart += `    style A fill:#e1f5fe\n`;
  flowchart += `    style E fill:#c8e6c9\n`;

  const hookColors: Record<HookType, string> = {
    beforeCreate: "#90caf9",
    afterCreate: "#a5d6a7",
    beforeUpdate: "#fff59d",
    afterUpdate: "#ffcc80",
    beforeDelete: "#ef9a9a",
    afterDelete: "#b0bec5",
    beforeQuery: "#ce93d8",
    afterQuery: "#9fa8da",
    customValidate: "#f48fb1",
    beforeRead: "#67e8f9",
    afterRead: "#14b8a6",
    beforeList: "#d9f99d",
    afterList: "#10b981",
  };

  hooks.forEach((hook, index) => {
    const letter = String.fromCharCode(66 + index);
    const color = hookColors[hook.type] || "#fff9c4";
    flowchart += `    style ${letter} fill:${color}\n`;
  });

  return flowchart;
}

/**
 * Validate hook definition
 */
export function validateHookDefinition(hook: ParsedHookDefinition): string[] {
  const errors: string[] = [];

  // Validate hook type
  if (!HOOK_TYPE_PATTERN.test(hook.type)) {
    errors.push(`Invalid hook type: ${hook.type}`);
  }

  // Validate hook name
  if (!hook.name || hook.name.length === 0) {
    errors.push("Hook name cannot be empty");
  }

  if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(hook.name)) {
    errors.push(
      `Invalid hook name: ${hook.name}. Must start with letter or underscore and contain only letters, numbers, and underscores`
    );
  }

  // Validate entity name
  if (!hook.entity || hook.entity.length === 0) {
    errors.push("Entity name cannot be empty");
  }

  if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(hook.entity)) {
    errors.push(
      `Invalid entity name: ${hook.entity}. Must start with letter or underscore and contain only letters, numbers, and underscores`
    );
  }

  return errors;
}

/**
 * Convert parsed hook to HookDefinition (for use in components)
 */
export interface HookDefinition {
  type: HookType;
  name: string;
  entity: string;
  enabled: boolean;
  code?: string;
  order: number;
}

export function toHookDefinition(
  parsedHook: ParsedHookDefinition,
  enabled: boolean = true
): HookDefinition {
  return {
    type: parsedHook.type,
    name: parsedHook.name,
    entity: parsedHook.entity,
    enabled,
    order: parsedHook.order,
  };
}

/**
 * Convert HookDefinition to ParsedHookDefinition
 */
export function fromHookDefinition(hook: HookDefinition): ParsedHookDefinition {
  const comment = `%%hook ${hook.type} ${hook.name} on ${hook.entity}`;

  return {
    type: hook.type,
    name: hook.name,
    entity: hook.entity,
    rawComment: comment,
    order: hook.order,
  };
}

// Minimal Mermaid flowchart TD → AST parser
// Supports: A([label]), B{label}, C[label], D((label)), edges with optional labels

export type NodeShape = "stadium" | "diamond" | "rect" | "circle" | "round";

export interface FlowNode {
  id: string;
  label: string;
  shape: NodeShape;
}

export interface FlowEdge {
  source: string;
  target: string;
  label?: string;
}

export interface FlowAST {
  nodes: Map<string, FlowNode>;
  edges: FlowEdge[];
}

function parseNodeDef(id: string, rest: string): FlowNode | null {
  let m: RegExpMatchArray | null;

  m = rest.match(/^\(\[(.+?)\]\)/);
  if (m?.[1]) return { id, label: m[1].trim(), shape: "stadium" };

  m = rest.match(/^\(\((.+?)\)\)/);
  if (m?.[1]) return { id, label: m[1].trim(), shape: "circle" };

  m = rest.match(/^\{(.+?)\}/);
  if (m?.[1]) return { id, label: m[1].trim(), shape: "diamond" };

  m = rest.match(/^\[(.+?)\]/);
  if (m?.[1]) return { id, label: m[1].trim(), shape: "rect" };

  m = rest.match(/^\((.+?)\)/);
  if (m?.[1]) return { id, label: m[1].trim(), shape: "round" };

  return null;
}

function ensureNode(ast: FlowAST, id: string, suffix: string | undefined) {
  if (ast.nodes.has(id)) return;
  if (suffix) {
    const node = parseNodeDef(id, suffix);
    if (node) {
      ast.nodes.set(id, node);
      return;
    }
  }
  ast.nodes.set(id, { id, label: id, shape: "rect" });
}

// A node's shape suffix. Longest forms first: ((circle)) and ([stadium]) both
// start with "(", so a bare \([^)]*\) placed earlier would claim just their
// opening half and mis-shape the node.
const NODE_SUFFIX = String.raw`\(\([^)]*\)\)|\(\[[^\]]*\]\)|\{[^}]*\}|\[[^\]]*\]|\([^)]*\)`;

// Matches: SrcId[optional-suffix] --> |optional-label| TgtId[optional-suffix]
//
// The edge label is only recognized when it is actually delimited by pipes.
// Written as an optional unanchored group it matched the empty-pipe case by
// greedily consuming the target node, then backtracking just far enough to
// leave one identifier character behind — so "A --> B{Status == draft?}"
// produced a node id of "t" (the tail of "draft") instead of "B".
const EDGE_RE = new RegExp(
  String.raw`^([A-Za-z_][A-Za-z0-9_]*)(${NODE_SUFFIX})?\s*(?:-->|---)\s*(?:\|([^|]*)\|)?\s*([A-Za-z_][A-Za-z0-9_]*)(${NODE_SUFFIX})?`
);

export function parseMermaidFlowchart(code: string): FlowAST {
  const ast: FlowAST = { nodes: new Map(), edges: [] };

  for (const rawLine of code.split("\n")) {
    const line = rawLine.trim();
    if (!line || line.startsWith("flowchart") || line.startsWith("graph") || line.startsWith("%%"))
      continue;

    const em = line.match(EDGE_RE);
    if (em) {
      const [, srcId, srcSuffix, edgeLabel, tgtId, tgtSuffix] = em;
      if (!srcId || !tgtId) continue;

      ensureNode(ast, srcId, srcSuffix);
      ensureNode(ast, tgtId, tgtSuffix);

      ast.edges.push({
        source: srcId,
        target: tgtId,
        label: edgeLabel?.trim() || undefined,
      });
      continue;
    }

    // Standalone node definition
    const nm = line.match(/^([A-Za-z_][A-Za-z0-9_]*)(.+)$/);
    if (nm?.[1] && nm[2]) {
      const node = parseNodeDef(nm[1], nm[2].trim());
      if (node && !ast.nodes.has(nm[1])) ast.nodes.set(nm[1], node);
    }
  }

  return ast;
}

