/* ─────────────────────────────────────────────────────────── main component */

interface UnifiedFieldLayoutProps {
  entityName: string;
  onEntityChange?: (name: string) => void;
}

export function UnifiedFieldLayout({ entityName }: UnifiedFieldLayoutProps) {
  const queryClient = useQueryClient();
  const [mode, setMode] = useState<"form" | "grid">("form");
  const [groups, setGroups] = useState<WorkingGroup[]>([]);
  const [gridList, setGridList] = useState<WorkingField[]>([]);
  const [isDirty, setIsDirty] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const { data: fieldGroupsData, isLoading: groupsLoading } = useFieldGroups(entityName);
  const { data: formFields, isLoading: formLoading } = useAllFormFields(entityName);
  const { data: gridFields, isLoading: gridLoading } = useAllGridFields(entityName);

  const isLoading = groupsLoading || (mode === "form" ? formLoading : gridLoading);

  // Build form working state (grouped)
  useEffect(() => {
    if (mode !== "form" || !formFields || !fieldGroupsData) return;
    const g = buildGroupedState(formFields, fieldGroupsData as any[]);
    setGroups(g);
    setIsDirty(false);
  }, [formFields, fieldGroupsData, mode]);

  // Build grid working state (flat list, ordered by seq_no_grid)
  useEffect(() => {
    if (mode !== "grid" || !gridFields) return;
    const sorted = [...(gridFields as any[])].sort(
      (a, b) =>
        ((a as any).seq_no_grid ?? a.seq_no ?? 999) - ((b as any).seq_no_grid ?? b.seq_no ?? 999)
    );
    setGridList(
      sorted.map((f: any) => ({
        ...f,
        seq_no: f.seq_no_grid ?? f.seq_no ?? 0,
        is_displayed: f.is_displayed_grid ?? f.is_displayed ?? false,
        originalGroupId: null,
        originalSeqNo: f.seq_no_grid ?? f.seq_no ?? 0,
        dirty: false,
      }))
    );
    setIsDirty(false);
  }, [gridFields, mode]);

  /* ── drag end */
  const onDragEnd = useCallback((result: DropResult) => {
    if (!result.destination) return;
    const { source, destination, draggableId } = result;
    if (source.droppableId === destination.droppableId && source.index === destination.index)
      return;

    setGroups((prev) => {
      const next = prev.map((g) => ({ ...g, fields: [...g.fields] }));
      const srcGroup = next.find((g) => g.id === source.droppableId)!;
      const dstGroup = next.find((g) => g.id === destination.droppableId)!;

      const [movedField] = srcGroup.fields.splice(source.index, 1);

      const newGroupId = destination.droppableId === "unassigned" ? null : destination.droppableId;
      const updatedField: WorkingField = {
        ...movedField,
        field_group_id: newGroupId ?? undefined,
        dirty:
          newGroupId !== movedField.originalGroupId ||
          source.droppableId !== destination.droppableId,
      };

      dstGroup.fields.splice(destination.index, 0, updatedField);

      // Recalculate seq_no within destination group
      dstGroup.fields = dstGroup.fields.map((f, i) => ({
        ...f,
        seq_no: (i + 1) * 10,
        dirty: f.dirty || f.seq_no !== (i + 1) * 10,
      }));

      return next;
    });
    setIsDirty(true);
  }, []);

  /* ── toggle visibility */
  const handleToggleVisibility = useCallback((fieldId: string, groupId: string) => {
    setGroups((prev) =>
      prev.map((g) => {
        if (g.id !== groupId) return g;
        return {
          ...g,
          fields: g.fields.map((f) =>
            f.sys_field_id === fieldId ? { ...f, is_displayed: !f.is_displayed, dirty: true } : f
          ),
        };
      })
    );
    setIsDirty(true);
  }, []);

  /* ── group editing */
  const handleEditToggle = useCallback((id: string) => {
    setGroups((prev) =>
      prev.map((g) =>
        g.id === id ? { ...g, isEditing: !g.isEditing } : { ...g, isEditing: false }
      )
    );
  }, []);

  const handleEditSave = useCallback(
    (id: string, name: string, columns: number, description: string) => {
      setGroups((prev) =>
        prev.map((g) =>
          g.id === id
            ? ({ ...g, name, columns, description, isEditing: false, dirty: true } as any)
            : g
        )
      );
      setIsDirty(true);
    },
    []
  );

  const handleEditCancel = useCallback((id: string) => {
    setGroups((prev) => prev.map((g) => (g.id === id ? { ...g, isEditing: false } : g)));
  }, []);

  const handleDeleteGroup = useCallback((id: string) => {
    setGroups((prev) => {
      const groupToDelete = prev.find((g) => g.id === id);
      if (!groupToDelete) return prev;
      // Move fields from deleted group to unassigned
      const movedFields = groupToDelete.fields.map((f) => ({
        ...f,
        field_group_id: undefined,
        dirty: true,
      }));
      return prev
        .filter((g) => g.id !== id)
        .map((g) => (g.id === "unassigned" ? { ...g, fields: [...g.fields, ...movedFields] } : g));
    });
    setIsDirty(true);
  }, []);

  /* ── toggle summary */
  const handleToggleSummary = useCallback((id: string) => {
    setGroups((prev) =>
      prev.map((g) =>
        g.id === id
          ? ({
              ...g,
              layout_type: g.layout_type === "summary" ? "single" : "summary",
              dirty: true,
            } as any)
          : g
      )
    );
    setIsDirty(true);
  }, []);

  /* ── add group */
  const handleAddGroup = useCallback(() => {
    const tempId = `new-${Date.now()}`;
    const newGroup: WorkingGroup = {
      id: tempId,
      name: "New Group",
      columns: 2,
      description: "",
      layout_type: "single",
      seq_no: (groups.filter((g) => g.id !== "unassigned").length + 1) * 10,
      isNew: true,
      isEditing: true,
      isDeleted: false,
      fields: [],
    };
    // Insert before unassigned
    setGroups((prev) => {
      const idx = prev.findIndex((g) => g.id === "unassigned");
      const next = [...prev];
      next.splice(idx, 0, newGroup);
      return next;
    });
    setIsDirty(true);
  }, [groups]);

  /* ── grid mode: drag-to-reorder flat list */
  const onGridDragEnd = useCallback((result: DropResult) => {
    if (!result.destination) return;
    const { source, destination } = result;
    if (source.index === destination.index) return;
    setGridList((prev) => {
      const next = [...prev];
      const [moved] = next.splice(source.index, 1);
      next.splice(destination.index, 0, moved);
      return next.map((f, i) => ({
        ...f,
        seq_no: (i + 1) * 10,
        dirty: f.dirty || f.originalSeqNo !== (i + 1) * 10,
      }));
    });
    setIsDirty(true);
  }, []);

  /* ── grid mode: visibility toggle */
  const handleGridToggleVisibility = useCallback((fieldId: string) => {
    setGridList((prev) =>
      prev.map((f) =>
        f.sys_field_id === fieldId ? { ...f, is_displayed: !f.is_displayed, dirty: true } : f
      )
    );
    setIsDirty(true);
  }, []);

  /* ── save all */
  const handleSaveAll = useCallback(async () => {
    setIsSaving(true);
    try {
      // Grid mode: save seq_no_grid and is_displayed_grid only
      if (mode === "grid") {
        const dirty = gridList.filter((f) => f.dirty);
        await Promise.all(
          dirty.map((f) =>
            apiClient.put(`/sys/fields/${f.sys_field_id}`, {
              seq_no_grid: f.seq_no,
              is_displayed_grid: f.is_displayed,
            })
          )
        );
        await queryClient.invalidateQueries({ queryKey: ["fields-all", entityName, "grid"] });
        toast.success("Grid layout saved successfully");
        setIsDirty(false);
        return;
      }

      // Form mode: save group assignments, seq_no, and is_displayed
      const fieldUpdates: Array<{
        id: string;
        sys_field_group_id: string | null;
        seq_no: number;
        is_displayed: boolean;
      }> = [];
      const groupCreates: WorkingGroup[] = [];
      const groupUpdates: WorkingGroup[] = [];

      for (const g of groups) {
        if (g.id === "unassigned") continue;
        if (g.isNew) {
          groupCreates.push(g);
        } else if ((g as any).dirty) {
          groupUpdates.push(g);
        }
        for (const f of g.fields) {
          if (f.dirty) {
            fieldUpdates.push({
              id: f.sys_field_id,
              sys_field_group_id: g.id === "unassigned" ? null : g.id,
              seq_no: f.seq_no,
              is_displayed: f.is_displayed,
            });
          }
        }
      }

      const unassigned = groups.find((g) => g.id === "unassigned");
      if (unassigned) {
        for (const f of unassigned.fields) {
          if (f.dirty) {
            fieldUpdates.push({
              id: f.sys_field_id,
              sys_field_group_id: null,
              seq_no: f.seq_no,
              is_displayed: f.is_displayed,
            });
          }
        }
      }

      const tempToRealId = new Map<string, string>();
      for (const g of groupCreates) {
        const created = await apiClient.post(`/sys/field-groups?entity=${entityName}`, {
          name: g.name,
          columns: g.columns,
          description: g.description,
          layout_type: g.layout_type ?? "single",
          seq_no: g.seq_no,
        });
        const realId = (created as any)?.sys_field_group_id;
        if (realId) tempToRealId.set(g.id, realId);
      }

      // Remap temp IDs to real UUIDs returned from the server
      for (const update of fieldUpdates) {
        if (update.sys_field_group_id && tempToRealId.has(update.sys_field_group_id)) {
          update.sys_field_group_id = tempToRealId.get(update.sys_field_group_id)!;
        }
      }

      for (const g of groupUpdates) {
        await apiClient.put(`/sys/field-groups/${g.id}?entity=${entityName}`, {
          name: g.name,
          columns: g.columns,
          description: g.description,
          layout_type: g.layout_type ?? "single",
          seq_no: g.seq_no,
        });
      }

      await Promise.all(
        fieldUpdates.map(({ id, ...data }) => apiClient.put(`/sys/fields/${id}`, data))
      );

      await queryClient.invalidateQueries({ queryKey: ["field-groups", entityName] });
      await queryClient.invalidateQueries({ queryKey: ["fields-all", entityName] });

      toast.success("Layout saved successfully");
      setIsDirty(false);
    } catch (err: any) {
      toast.error(`Save failed: ${err.message ?? "Unknown error"}`);
    } finally {
      setIsSaving(false);
    }
  }, [mode, groups, gridList, entityName, queryClient]);

  /* ── reset */
  const handleReset = useCallback(() => {
    if (mode === "grid") {
      if (!gridFields) return;
      const sorted = [...(gridFields as any[])].sort(
        (a, b) =>
          ((a as any).seq_no_grid ?? a.seq_no ?? 999) - ((b as any).seq_no_grid ?? b.seq_no ?? 999)
      );
      setGridList(
        sorted.map((f: any) => ({
          ...f,
          seq_no: f.seq_no_grid ?? f.seq_no ?? 0,
          is_displayed: f.is_displayed_grid ?? f.is_displayed ?? false,
          originalGroupId: null,
          originalSeqNo: f.seq_no_grid ?? f.seq_no ?? 0,
          dirty: false,
        }))
      );
    } else {
      if (!formFields || !fieldGroupsData) return;
      setGroups(buildGroupedState(formFields, fieldGroupsData as any[]));
    }
    setIsDirty(false);
  }, [mode, gridFields, formFields, fieldGroupsData]);

  /* ── computed stats */
  const dirtyFieldCount = useMemo(
    () =>
      mode === "grid"
        ? gridList.filter((f) => f.dirty).length
        : groups.flatMap((g) => g.fields).filter((f) => f.dirty).length,
    [mode, groups, gridList]
  );

  const visibleGroups = groups.filter((g) => g.id !== "unassigned");
  const unassignedGroup = groups.find((g) => g.id === "unassigned");

  if (isLoading) {
    return (
      <div className="space-y-4 p-6">
        <Skeleton className="h-8 w-64" />
        <div className="grid grid-cols-3 gap-4">
          {[1, 2, 3].map((i) => (
            <Skeleton key={i} className="h-48" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-5">
      {/* Toolbar */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div className="flex items-center gap-2">
          <div className="flex rounded-lg border border-border overflow-hidden">
            <button
              onClick={() => setMode("form")}
              className={cn(
                "px-4 py-1.5 text-sm font-medium transition-colors",
                mode === "form"
                  ? "bg-primary text-primary-foreground"
                  : "bg-background text-muted-foreground hover:bg-muted"
              )}
            >
              Form Fields
            </button>
            <button
              onClick={() => setMode("grid")}
              className={cn(
                "px-4 py-1.5 text-sm font-medium transition-colors border-l border-border",
                mode === "grid"
                  ? "bg-primary text-primary-foreground"
                  : "bg-background text-muted-foreground hover:bg-muted"
              )}
            >
              Grid Fields
            </button>
          </div>
          {isDirty && (
            <Badge variant="outline" className="text-amber-600 dark:text-amber-400 border-amber-300 dark:border-amber-800 bg-amber-50 dark:bg-amber-950/40">
              {dirtyFieldCount} unsaved change{dirtyFieldCount !== 1 ? "s" : ""}
            </Badge>
          )}
        </div>

        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={handleReset}
            disabled={!isDirty}
            className="h-8 gap-1.5"
          >
            <RotateCcw className="h-3.5 w-3.5" />
            Reset
          </Button>
          <Button
            size="sm"
            onClick={handleSaveAll}
            disabled={!isDirty || isSaving}
            className="h-8 gap-1.5 bg-emerald-600 hover:bg-emerald-700 text-white"
          >
            <Save className="h-3.5 w-3.5" />
            {isSaving ? "Saving…" : "Save Layout"}
          </Button>
        </div>
      </div>

      {mode === "grid" ? (
        /* ── Grid mode: flat reorderable list, no groups ── */
        <DragDropContext onDragEnd={onGridDragEnd}>
          <Droppable droppableId="grid-fields">
            {(provided) => (
              <div
                ref={provided.innerRef}
                {...provided.droppableProps}
                className="flex flex-col gap-1.5 max-w-xl"
              >
                {gridList.length === 0 && (
                  <p className="text-sm text-muted-foreground py-4 text-center">No fields found.</p>
                )}
                {gridList.map((field, index) => (
                  <Draggable
                    key={field.sys_field_id}
                    draggableId={field.sys_field_id}
                    index={index}
                  >
                    {(prov, snap) => (
                      <div
                        ref={prov.innerRef}
                        {...(prov.draggableProps as any)}
                        className={cn(
                          "flex items-center gap-2 px-3 py-2.5 rounded-md border text-sm transition-all",
                          snap.isDragging
                            ? "bg-primary/5 border-primary/40 shadow-lg"
                            : field.dirty
                              ? "bg-amber-50 dark:bg-amber-950/40 border-amber-200/60 dark:border-amber-800"
                              : "bg-card border-border hover:border-primary/30",
                          !field.is_displayed && "opacity-50"
                        )}
                      >
                        <span
                          {...prov.dragHandleProps}
                          className="text-muted-foreground/40 hover:text-muted-foreground cursor-grab active:cursor-grabbing flex-shrink-0"
                        >
                          <GripVertical className="h-4 w-4" />
                        </span>
                        <span className="w-6 text-xs text-muted-foreground font-mono text-center flex-shrink-0">
                          {index + 1}
                        </span>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-1.5">
                            <span className="font-medium truncate">{field.name}</span>
                            {field.is_mandatory && (
                              <span className="text-red-500 text-xs font-bold">*</span>
                            )}
                          </div>
                          <div className="flex items-center gap-1.5 mt-0.5">
                            <span className="text-[10px] text-muted-foreground font-mono">
                              {field.column_name}
                            </span>
                            <Badge variant="secondary" className="text-[10px] h-4 px-1 py-0">
                              {FIELD_TYPE_LABELS[field.sys_reference_id] ??
                                field.reference_name ??
                                String(field.sys_reference_id)}
                            </Badge>
                          </div>
                        </div>
                        <button
                          onClick={() => handleGridToggleVisibility(field.sys_field_id)}
                          className="flex-shrink-0 text-muted-foreground hover:text-foreground transition-colors"
                          title={field.is_displayed ? "Hide column" : "Show column"}
                        >
                          {field.is_displayed ? (
                            <Eye className="h-3.5 w-3.5 text-primary/70" />
                          ) : (
                            <EyeOff className="h-3.5 w-3.5" />
                          )}
                        </button>
                      </div>
                    )}
                  </Draggable>
                ))}
                {provided.placeholder}
              </div>
            )}
          </Droppable>
        </DragDropContext>
      ) : (
        /* ── Form mode: grouped panels ── */
        <DragDropContext onDragEnd={onDragEnd}>
          {visibleGroups.length > 0 ? (
            <div className="grid gap-4 grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
              {visibleGroups.map((group) => (
                <GroupPanel
                  key={group.id}
                  group={group}
                  onEditToggle={handleEditToggle}
                  onEditSave={handleEditSave}
                  onEditCancel={handleEditCancel}
                  onDelete={handleDeleteGroup}
                  onToggleVisibility={handleToggleVisibility}
                  onToggleSummary={handleToggleSummary}
                />
              ))}

              <button
                onClick={handleAddGroup}
                className="flex flex-col items-center justify-center gap-2 rounded-xl border-2 border-dashed border-primary/30 bg-primary/5 hover:bg-primary/10 hover:border-primary/50 transition-colors min-h-[120px] p-6 text-primary/70 hover:text-primary"
              >
                <Plus className="h-6 w-6" />
                <span className="text-sm font-medium">Add Group</span>
              </button>
            </div>
          ) : (
            <div className="flex items-center justify-center py-8">
              <button
                onClick={handleAddGroup}
                className="flex flex-col items-center gap-3 px-8 py-6 rounded-xl border-2 border-dashed border-primary/30 bg-primary/5 hover:bg-primary/10 transition-colors text-primary"
              >
                <Plus className="h-8 w-8" />
                <div className="text-center">
                  <p className="font-semibold">No field groups yet</p>
                  <p className="text-sm text-muted-foreground mt-1">
                    Create groups to organize fields into multi-column layouts
                  </p>
                </div>
              </button>
            </div>
          )}

          {unassignedGroup && (
            <div className="mt-2">
              <div className="flex items-center gap-2 mb-2">
                <div className="h-px flex-1 bg-border" />
                <span className="text-xs text-muted-foreground font-medium px-2">
                  Unassigned ({unassignedGroup.fields.length})
                </span>
                <div className="h-px flex-1 bg-border" />
              </div>
              <GroupPanel
                group={unassignedGroup}
                onEditToggle={handleEditToggle}
                onEditSave={handleEditSave}
                onEditCancel={handleEditCancel}
                onDelete={handleDeleteGroup}
                onToggleVisibility={handleToggleVisibility}
                onToggleSummary={handleToggleSummary}
              />
            </div>
          )}
        </DragDropContext>
      )}

      {/* Legend */}
      <div className="flex items-center gap-4 text-xs text-muted-foreground pt-2 border-t border-border flex-wrap">
        <span className="flex items-center gap-1.5">
          <GripVertical className="h-3.5 w-3.5" /> Drag to reorder or move between groups
        </span>
        <span className="flex items-center gap-1.5">
          <Eye className="h-3.5 w-3.5" /> Toggle field visibility
        </span>
        <span className="flex items-center gap-1.5">
          <Pencil className="h-3.5 w-3.5" /> Edit group name &amp; columns
        </span>
        <span className="flex items-center gap-1.5 text-amber-600 dark:text-amber-400">
          <Star className="h-3.5 w-3.5" /> Mark group as Summary (shown in record header)
        </span>
      </div>
    </div>
  );
}

import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import type { ConflictField } from "@/lib/version-conflict";

function show(value: unknown): string {
  if (value === null || value === undefined || value === "") return "—";
  if (typeof value === "object") return JSON.stringify(value);
  return String(value);
}

/**
 * What the form offers when someone else saved the record first.
 *
 * Two ways out, and neither is a default: Reload takes the saved record and
 * drops this user's edits; Overwrite saves this user's edits over it (checked
 * again against the version just read, so a third save in the meantime is
 * caught rather than overwritten too). Cancel keeps the edits on screen and
 * saves nothing, for a reader who wants to copy something out first.
 */
export function VersionConflictDialog({
  open,
  entityLabel,
  fields,
  labelOf,
  theirVersion,
  isSaving,
  onReload,
  onOverwrite,
  onCancel,
}: {
  open: boolean;
  entityLabel: string;
  fields: ConflictField[];
  labelOf: (field: string) => string;
  theirVersion?: number;
  isSaving?: boolean;
  onReload: () => void;
  onOverwrite: () => void;
  onCancel: () => void;
}) {
  const clashes = fields.filter((f) => f.clash).length;
  return (
    <AlertDialog open={open} onOpenChange={(next) => (!next ? onCancel() : undefined)}>
      <AlertDialogContent className="max-w-2xl" data-testid="version-conflict-dialog">
        <AlertDialogHeader>
          <AlertDialogTitle>This {entityLabel.toLowerCase()} was changed while you were editing</AlertDialogTitle>
          <AlertDialogDescription>
            Someone else saved it first{theirVersion ? ` (it is now at version ${theirVersion})` : ""}.
            {fields.length === 0
              ? " None of the fields you can see differ — saving yours will keep your changes."
              : clashes > 0
                ? ` ${clashes} of the fields below were changed by both of you.`
                : " They changed the fields below; you did not."}
          </AlertDialogDescription>
        </AlertDialogHeader>

        {fields.length > 0 && (
          <div className="max-h-72 overflow-auto rounded-md border">
            <table className="w-full text-sm">
              <thead className="bg-muted/50 text-left">
                <tr>
                  <th className="px-3 py-2 font-medium">Field</th>
                  <th className="px-3 py-2 font-medium">Their saved value</th>
                  <th className="px-3 py-2 font-medium">Your value</th>
                </tr>
              </thead>
              <tbody>
                {fields.map((f) => (
                  <tr key={f.field} className={f.clash ? "bg-amber-50 dark:bg-amber-950/30" : undefined}>
                    <td className="px-3 py-2 font-medium">
                      {labelOf(f.field)}
                      {f.clash && <span className="ml-2 text-xs text-amber-700 dark:text-amber-400">both changed</span>}
                    </td>
                    <td className="px-3 py-2 font-mono text-xs">{show(f.theirs)}</td>
                    <td className="px-3 py-2 font-mono text-xs">{show(f.mine)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        <AlertDialogFooter className="gap-2">
          <Button variant="ghost" onClick={onCancel} disabled={isSaving}>
            Keep editing
          </Button>
          <Button variant="outline" onClick={onReload} disabled={isSaving} data-testid="version-conflict-reload">
            Reload their version
          </Button>
          <Button onClick={onOverwrite} disabled={isSaving} data-testid="version-conflict-overwrite">
            {isSaving ? "Saving…" : "Overwrite with mine"}
          </Button>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

/**
 * The icon that represents an entity, set in the Application Dictionary.
 *
 * `sys_table.icon` holds one of two things and the application decides by
 * looking: a lucide icon id (`stethoscope`), or an image someone uploaded here,
 * carried as a `data:` URI. This is where both are set.
 *
 * Encoded in the browser rather than posted as multipart, because a data URI is
 * what the column stores and what the dashboard renders. Converting at every
 * hop — multipart in, bytes in a table, base64 out — would be three
 * representations of one small image and two more places for it to go wrong.
 *
 * The server validates independently in `SysService.validateIconValue`: nothing
 * checked here is trusted there. The checks below exist to tell the
 * administrator what is wrong before a round trip, not to decide it.
 */

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useRef, useState } from "react";
import { toast } from "sonner";
import { Icon } from "@/components/ui/icon";
import { Button } from "@/components/ui/button";
import { apiClient } from "@/lib/api-client";

/** Must match SysService.ICON_MAX_DECODED_BYTES. */
const MAX_BYTES = 64 * 1024;

/** Must match SysService.ICON_MEDIA_TYPES. */
const ACCEPTED = ["image/svg+xml", "image/png", "image/webp", "image/gif", "image/jpeg"];

interface TableRecord {
  sys_table_id: string;
  table_name: string;
  name: string;
  icon: string | null;
}

function isUploaded(icon: string | null): boolean {
  return !!icon && /^data:image\//i.test(icon);
}

export function EntityIconField({ tableId }: { tableId: string }) {
  const queryClient = useQueryClient();
  const fileInput = useRef<HTMLInputElement>(null);
  const [name, setName] = useState<string | null>(null);

  const { data: table } = useQuery({
    queryKey: ["sys_table", tableId],
    queryFn: () => apiClient.get<TableRecord>(`/sys/tables/${tableId}`),
  });

  // `null` while the record loads, then the stored value — so typing is not
  // thrown away by a refetch.
  const current = name ?? table?.icon ?? "";

  const save = useMutation({
    mutationFn: (icon: string | null) =>
      apiClient.put<TableRecord>(`/sys/tables/${tableId}/icon`, { icon }),
    onSuccess: (updated) => {
      setName(null);
      queryClient.setQueryData(["sys_table", tableId], updated);
      // The dashboard draws these, and it caches the dictionary for minutes.
      queryClient.invalidateQueries({ queryKey: ["dashboard"] });
      toast.success(updated.icon ? "Icon saved" : "Icon cleared");
    },
    onError: (error: unknown) =>
      toast.error(error instanceof Error ? error.message : "Could not save the icon"),
  });

  const onFile = (file: File) => {
    if (!ACCEPTED.includes(file.type)) {
      toast.error(`${file.type || "That file"} is not an image this accepts — use SVG, PNG, WEBP, GIF or JPEG`);
      return;
    }
    if (file.size > MAX_BYTES) {
      toast.error(
        `That image is ${Math.ceil(file.size / 1024)}KB; the limit is ${MAX_BYTES / 1024}KB. An icon is drawn at 20 pixels.`
      );
      return;
    }
    const reader = new FileReader();
    reader.onerror = () => toast.error("Could not read that file");
    reader.onload = () => {
      const result = typeof reader.result === "string" ? reader.result : "";
      if (!result.startsWith("data:image/")) {
        toast.error("Could not read that file as an image");
        return;
      }
      save.mutate(result);
    };
    reader.readAsDataURL(file);
  };

  const stored = table?.icon ?? null;

  return (
    <div className="swiss-card p-5 space-y-4">
      <div>
        <h3 className="text-sm font-semibold text-foreground">Entity icon</h3>
        <p className="text-xs text-muted-foreground mt-1">
          A{" "}
          <a
            href="https://lucide.dev/icons"
            target="_blank"
            rel="noreferrer"
            className="underline hover:text-foreground"
          >
            lucide icon name
          </a>{" "}
          , or an image you upload. Shown wherever this entity appears — the dashboard card, the
          window heading, the navigation.
        </p>
      </div>

      <div className="flex items-center gap-4">
        <div className="w-12 h-12 rounded-lg bg-primary/10 text-primary flex items-center justify-center flex-shrink-0">
          {stored ? (
            <Icon name={stored} size={24} className="text-primary" />
          ) : (
            <span className="text-xs text-muted-foreground">none</span>
          )}
        </div>
        <div className="text-xs text-muted-foreground min-w-0">
          {isUploaded(stored)
            ? `Uploaded image (${Math.ceil((stored?.length ?? 0) / 1024)}KB encoded)`
            : stored
              ? `Lucide icon: ${stored}`
              : "No icon set — a default is drawn"}
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-2">
        <input
          type="text"
          value={isUploaded(current) ? "" : current}
          placeholder="stethoscope"
          disabled={save.isPending}
          onChange={(event) => setName(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Enter") save.mutate(event.currentTarget.value.trim() || null);
          }}
          className="swiss-input h-9 w-56 text-sm"
          aria-label="Lucide icon name"
        />
        <Button
          size="sm"
          disabled={save.isPending || isUploaded(current)}
          onClick={() => save.mutate((name ?? "").trim() || null)}
        >
          Save name
        </Button>

        <input
          ref={fileInput}
          type="file"
          accept={ACCEPTED.join(",")}
          className="hidden"
          onChange={(event) => {
            const file = event.target.files?.[0];
            // Cleared so choosing the same file twice fires change again.
            event.target.value = "";
            if (file) onFile(file);
          }}
        />
        <Button
          size="sm"
          variant="outline"
          disabled={save.isPending}
          onClick={() => fileInput.current?.click()}
        >
          Upload image
        </Button>

        {stored && (
          <Button
            size="sm"
            variant="outline"
            disabled={save.isPending}
            onClick={() => save.mutate(null)}
          >
            Clear
          </Button>
        )}
      </div>

      <p className="text-xs text-muted-foreground">
        SVG, PNG, WEBP, GIF or JPEG, up to {MAX_BYTES / 1024}KB. The image is stored in the
        dictionary itself, so it travels with a database backup and needs no file storage.
      </p>
    </div>
  );
}

import { Link } from "@tanstack/react-router";
import { FileQuestion } from "lucide-react";
import { Skeleton } from "@/components/ui/skeleton";
import { buttonVariants } from "@/components/ui/button";
import { useBusEntityLevel } from "@/hooks/use-bus-entity-level";
import { ADListShell } from "./ad-list-shell";

interface BusEntityPageProps {
  entityName: string;
}

/**
 * Metadata-driven list page for any bus_ entity.
 * Reads the ADLevel (fields, labels, endpoint) entirely from the Application Dictionary.
 *
 * Generated route files import this and pass entityName — if you need a fully
 * custom window for a specific entity, replace the component body in the route
 * file instead of modifying this shared component.
 */
export function BusEntityPage({ entityName }: BusEntityPageProps) {
  const { level, isLoading, isUnknownEntity } = useBusEntityLevel(entityName);

  /*
   * An address that names no entity.
   *
   * `/$entity` catches every unmatched path, so this component is what answers
   * a typo — and it used to answer with a grid. The dictionary had no such
   * table, the field endpoints 404ed, and `formFields` fell back to `[]`, which
   * renders as a titled table with no columns and no rows: indistinguishable
   * from an entity nobody has created a record in yet. `/login` is the case
   * that made it worth fixing, because the sign-in screen is at `/auth/login`
   * and the shorter path is the one people type.
   */
  if (isUnknownEntity) {
    return (
      <div className="p-6">
        <div className="swiss-card mx-auto max-w-md p-8 text-center">
          <FileQuestion className="mx-auto mb-4 h-10 w-10 text-muted-foreground" />
          <h1 className="text-lg font-semibold text-foreground">No screen at this address</h1>
          <p className="mt-2 text-sm text-muted-foreground">
            This application has no entity called{" "}
            <span className="font-mono-display text-foreground">{entityName}</span>. It may have
            been renamed, or the address may be mistyped.
          </p>
          <Link to="/dashboard" className={`${buttonVariants({ size: "sm" })} mt-6`}>
            Back to the dashboard
          </Link>
        </div>
      </div>
    );
  }

  if (isLoading || !level) {
    return (
      <div className="p-6 space-y-4">
        <Skeleton className="h-10 w-64" />
        <Skeleton className="h-8 w-full" />
        <Skeleton className="h-8 w-full" />
        <Skeleton className="h-8 w-3/4" />
      </div>
    );
  }

  return <ADListShell level={level} parentContext={[]} />;
}

