import { useNavigate } from "@tanstack/react-router";
import { LogOut, Menu } from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { NotificationBell } from "@/components/notifications/notification-bell";
import { ThemeToggle } from "@/components/theme/theme-toggle";
import { useAuth } from "@/contexts/auth-context";

interface HeaderProps {
  className?: string;
  /** Opens the navigation drawer. The button shows only below `md`, where the sidebar is hidden. */
  onOpenNavigation?: () => void;
  isNavigationOpen?: boolean;
}

export function Header({ className, onOpenNavigation, isNavigationOpen }: HeaderProps) {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate({ to: "/auth/login" });
  };

  const getInitials = (name: string) => {
    return name
      .split(" ")
      .map((n) => n[0])
      .join("")
      .toUpperCase()
      .slice(0, 2);
  };

  return (
    <header
      className={`sticky top-0 z-30 flex h-16 items-center gap-4 border-b bg-background px-6 ${className || ""}`}
    >
      {onOpenNavigation && (
        <Button
          variant="ghost"
          size="icon"
          className="h-9 w-9 md:hidden"
          onClick={onOpenNavigation}
          aria-label="Open the navigation"
          aria-expanded={isNavigationOpen ?? false}
          aria-haspopup="dialog"
        >
          <Menu className="h-5 w-5" />
        </Button>
      )}

      {/*
       * No global search box here.
       *
       * There was one, and it did nothing: a form whose only handler was
       * `preventDefault()`, over an input bound to no state, placeholdered
       * "Search... (Ctrl+K)" — a shortcut that was never wired either. A
       * control that looks like it works and does not is worse than no
       * control, and this application already has the two searches that mean
       * something: the dashboard filters its own cards, and `ADToolbar`
       * searches the records of the entity on screen. There is no endpoint a
       * third, global one could call.
       */}
      <div className="flex-1" />

      {/* Actions */}
      <div className="flex items-center gap-2">
        {/* Notifications — the real list, read from this user's own audit
            trail. This used to be a bell with a permanent pulsing dot over a
            hard-coded "No new notifications", which told the user there was
            something to read and then that there was not. */}
        <NotificationBell />

        {/* Light / dark / system. The class lands on <html>, so this one
            control changes every screen rather than this header. */}
        <ThemeToggle />

        {/* User Menu */}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" className="relative h-9 w-9 rounded-full">
              <Avatar className="h-9 w-9">
                <AvatarImage src="" alt={user?.name || ""} />
                <AvatarFallback className="bg-primary text-primary-foreground">
                  {user ? getInitials(user.name) : "U"}
                </AvatarFallback>
              </Avatar>
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-56">
            <DropdownMenuLabel>
              <div className="flex flex-col space-y-1">
                <p className="text-sm font-medium leading-none">{user?.name}</p>
                <p className="text-xs leading-none text-muted-foreground">{user?.email}</p>
              </div>
            </DropdownMenuLabel>
            <DropdownMenuSeparator />
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={handleLogout}>
              <LogOut className="mr-2 h-4 w-4" />
              <span>Log out</span>
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </header>
  );
}

/**
 * Sidebar navigation, drawn from the Application Dictionary.
 *
 * Every entry here — which entities appear, what each is called, which icon it
 * carries, which admin screens are offered — comes from
 * `/sys/categories/dashboard`, the same single statement the dashboard reads.
 * Nothing about the navigation is baked in at generation time any more.
 *
 * It used to be. `mainEntities` was computed by the generator and written into
 * this file as a literal array, and each entry's icon came from
 * `getIconForEntity`, a hard-coded map of about twenty table names to lucide
 * components — `bus_patient → UserCircle`, `bus_order → ShoppingCart` — with
 * `FileText` for everything else. Three things followed:
 *
 * - **`%%entity <E> icon:` could not reach it.** The model's own answer was
 *   overruled by a map written months earlier, and so was any icon an
 *   administrator set or uploaded in Table and Column. The dictionary held the
 *   icon; the navigation drew a different one.
 * - **The list was a guess.** Two filters chose the ten entries: line items,
 *   which the model does declare, and "the table name has no underscore past
 *   `bus_`", which the model says nothing about — so `bus_lab_order` was
 *   excluded from the navigation of a hospital system for the shape of its
 *   name.
 * - **It was unscoped.** The array was the same for every reader, while the
 *   screens it linked to refuse anyone without `%%rbac … .read`. A nav that
 *   offers a window the application then refuses is worse than one that does
 *   not offer it.
 *
 * The query key is `['dashboard']`, deliberately the same one
 * `routes/dashboard.tsx` uses. React Query serves both readers from one cache
 * entry, so mounting this beside the dashboard costs no extra request.
 *
 * Generated: {{now}}
 */

import { useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate, useLocation } from '@tanstack/react-router';
import { useQuery } from '@tanstack/react-query';
import { cn } from '@/lib/utils';
import { apiClient } from '@/lib/api-client';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { Icon } from '@/components/ui/icon';
import {
  LayoutDashboard,
  Database,
  ChevronLeft,
  ChevronRight,
  Search,
  X,
} from 'lucide-react';

/** One entity as the dictionary describes it. */
interface DictionaryTable {
  sys_table_id: string;
  table_name: string;
  name: string;
  description?: string;
  /** A lucide icon id, or a `data:` URI for an uploaded image. May be absent. */
  icon?: string;
}

interface CategoryGroup {
  sys_category_id: string | null;
  name: string;
  code: string;
  icon: string | null;
  color: string | null;
  entities: DictionaryTable[];
}

interface DashboardResponse {
  data: CategoryGroup[];
  role: string;
  isMaster: boolean;
  windows: {
    sys_window_id: string;
    name: string;
    /** The window's route, held in `sys_window.description`. */
    route: string;
    icon: string | null;
    category: string;
    is_read_only: boolean;
  }[];
}

interface NavEntry {
  title: string;
  href: string;
  /**
   * What to draw, as the dictionary spells it — a lucide id or a `data:` URI.
   * Null when the dictionary says nothing, and a default is drawn.
   *
   * A string rather than a component type, which is what this used to be. The
   * imported-component form is what forced the hard-coded map: only names the
   * generator knew at build time could become an import.
   */
  icon: string | null;
  description?: string;
  /**
   * Everything this entry can be found by, beyond its title.
   *
   * The physical table name is in here on purpose: somebody who has been
   * reading the dictionary, a migration or a log line knows the entity as
   * `bus_lab_order`, and typing that should find "Lab Order" rather than
   * nothing. The category name is here for the same reason — "diagnostics"
   * is a real way to look for a screen whose name you have forgotten.
   */
  keywords: string;
}

/**
 * The same request the dashboard makes, under the same key.
 *
 * `staleTime` matches `routes/dashboard.tsx` for the same reason it has one at
 * all: the dictionary changes when an administrator edits it, not between two
 * screens.
 */
function useDashboard() {
  return useQuery({
    queryKey: ['dashboard'],
    queryFn: () => apiClient.get<DashboardResponse>('/sys/categories/dashboard'),
    staleTime: 5 * 60 * 1000,
  });
}

/**
 * Where an entity's screen lives.
 *
 * Derived exactly as `routes/dashboard.tsx` derives it, so a card and a nav
 * entry for one entity cannot point at two different addresses.
 */
function entityHref(table: DictionaryTable): string {
  return `/${table.name.toLowerCase().replace(/\s+/g, '-')}`;
}

/**
 * A flattened nav entry, with the heading it came from.
 *
 * Search results are a flat list rather than the grouped tree: when somebody
 * types "lab" they want the two screens that match, not seven headings with
 * one row under two of them. The group name rides along so the result can say
 * where the screen lives, which is the part the flattening would otherwise
 * throw away.
 */
interface SearchableEntry extends NavEntry {
  group: string;
}

/** Case- and punctuation-insensitive, so "Lab Order" is found by "laborder". */
function fold(value: string): string {
  return value.toLowerCase().replace(/[\s_-]+/g, '');
}

/**
 * Rank: title prefix, then title substring, then anything else.
 *
 * Three tiers rather than a score, because the list is short and a reader can
 * predict three. Typing "pa" should put Patient and Payment above Imaging
 * Report — all three contain the letters, only two start with them.
 */
function rank(entry: SearchableEntry, needle: string): number {
  const title = fold(entry.title);
  if (title.startsWith(needle)) return 0;
  if (title.includes(needle)) return 1;
  if (fold(entry.keywords).includes(needle)) return 2;
  return -1;
}

/**
 * The title with the matched run marked.
 *
 * Only the title is highlighted, and only when the match is actually in it —
 * a row matched on its table name has nothing to underline in the words on
 * screen, and inventing a highlight there would point at the wrong letters.
 */
function highlight(title: string, needle: string) {
  if (!needle) return title;
  const folded = fold(title);
  const at = folded.indexOf(needle);
  if (at < 0) return title;

  /*
   * `fold` removes characters, so an index into the folded string is not an
   * index into the original. Walk the original counting only the characters
   * that survived folding, and the marked run lands on the letters the reader
   * actually typed — "lab or" highlights "Lab Or", spaces included.
   */
  const bounds: number[] = [];
  for (let i = 0; i < title.length; i++) {
    if (!/[\s_-]/.test(title[i] as string)) bounds.push(i);
  }
  const start = bounds[at];
  const end = bounds[at + needle.length - 1];
  if (start === undefined || end === undefined) return title;

  return (
    <>
      {title.slice(0, start)}
      <mark className="bg-primary/20 text-inherit rounded-sm">
        {title.slice(start, end + 1)}
      </mark>
      {title.slice(end + 1)}
    </>
  );
}

/**
 * The one entry that is not from the dictionary.
 *
 * At module scope, not in the component body. A literal there is a new object
 * on every render, and every `useMemo` listing it as a dependency recomputes
 * on every keystroke — which is exactly what the memo was added to prevent.
 */
const DASHBOARD_ENTRY: NavEntry = {
  title: 'Dashboard',
  href: '/dashboard',
  icon: null,
  description: 'Overview and statistics',
  keywords: 'home overview start',
};

interface SidebarProps {
  className?: string;
  /** Drawn inside the mobile drawer: always shown, full width, never collapsed. */
  inDrawer?: boolean;
}

export function Sidebar({ className, inDrawer = false }: SidebarProps) {
  const location = useLocation();
  const pathname = location.pathname;
  const [collapsedRail, setIsCollapsed] = useState(false);
  const isCollapsed = !inDrawer && collapsedRail;
  const [query, setQuery] = useState('');
  const [activeIndex, setActiveIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const navigate = useNavigate();
  const { data: dashboard } = useDashboard();

  /*
   * Grouped the way the dashboard groups them, and for the same reason: on a
   * model of any size a flat list of every entity is a scroll, while the
   * categories the modeller already wrote are the headings they chose.
   *
   * No cap and no name-shape filter. The server has already dropped the line
   * items and scoped the list to what this reader may read, which is the whole
   * of what belongs in a navigation — anything further would be this file
   * second-guessing the dictionary again.
   */
  const groups = useMemo(() => (dashboard?.data ?? [])
    .map((group) => ({
      code: group.code,
      name: group.name,
      entries: group.entities.map<NavEntry>((table) => ({
        title: table.name,
        href: entityHref(table),
        icon: table.icon ?? null,
        description: table.description,
        keywords: `${table.table_name} ${group.name}`,
      })),
    }))
    .filter((group) => group.entries.length > 0), [dashboard]);

  /*
   * The admin section, from `sys_access` rather than from the session's role
   * string.
   *
   * This used to ask `useAuth().isAdmin()` and then render a fixed list of six
   * screens. Both halves were wrong in the same direction: the list named
   * windows that might not exist and omitted ones that did, and `isAdmin()` is
   * a different question from "may this caller open this window" — which is
   * what the screens themselves are guarded by. Asking the dictionary means the
   * navigation and the guard cannot disagree.
   */
  const adminEntries = useMemo(() => (dashboard?.windows ?? [])
    .filter((window) => window.category === 'admin' && !!window.route)
    .map<NavEntry>((window) => ({
      title: window.name,
      href: window.route,
      icon: window.icon,
      description: window.is_read_only ? 'View only' : undefined,
      keywords: `${window.route} administration admin`,
    })), [dashboard]);

  /*
   * Everything that can be navigated to, in the order it is drawn.
   *
   * Built once from the dictionary rather than per keystroke — the search is
   * client-side precisely because the data is already here, and re-flattening
   * twenty-eight entries on every character typed would throw that away.
   */
  const searchable = useMemo<SearchableEntry[]>(
    () => [
      { ...DASHBOARD_ENTRY, group: '' },
      ...groups.flatMap((group) =>
        group.entries.map((entry) => ({ ...entry, group: group.name }))
      ),
      ...adminEntries.map((entry) => ({ ...entry, group: 'Administration' })),
    ],
    [groups, adminEntries]
  );

  const needle = fold(query);
  const isSearching = needle.length > 0;

  const results = useMemo(() => {
    if (!isSearching) return [];
    return searchable
      .map((entry) => ({ entry, tier: rank(entry, needle) }))
      .filter((hit) => hit.tier >= 0)
      .sort((a, b) => a.tier - b.tier || a.entry.title.localeCompare(b.entry.title))
      .map((hit) => hit.entry);
  }, [searchable, needle, isSearching]);

  /* A new query means a new first result; leaving the old index would arm
     Enter to open whatever happened to be at that position before. */
  useEffect(() => {
    setActiveIndex(0);
  }, [needle]);

  const go = (href: string) => {
    setQuery('');
    navigate({ to: href });
  };

  /**
   * Arrow keys move, Enter opens, Escape backs out.
   *
   * Escape clears a query first and only blurs when there is nothing left to
   * clear — pressing it once should undo the typing, not throw away the focus
   * as well and make the reader click back in.
   */
  const onKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      if (results.length === 0) return;
      const step = event.key === 'ArrowDown' ? 1 : -1;
      setActiveIndex((current) => (current + step + results.length) % results.length);
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      const chosen = results[activeIndex];
      if (chosen) go(chosen.href);
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      if (query) setQuery('');
      else inputRef.current?.blur();
    }
  };

  return (
    <div
      className={cn(
        /* Hidden below `md`. The sidebar is a fixed 256px (64px collapsed) and
           a phone is 375px wide, so showing it there would leave 119px for the
           record being read. Below `md` the header's menu button opens this same
           sidebar in a drawer over the screen (`inDrawer`). */
        inDrawer
          ? 'flex w-full flex-1 flex-col bg-background'
          : 'relative hidden flex-col border-r bg-background md:flex',
        !inDrawer && (isCollapsed ? 'w-16' : 'w-64'),
        'transition-all duration-300',
        className
      )}
    >
      {/* Header */}
      {/* In the drawer, room on the right for its Close button. */}
      <div className={cn('flex h-16 items-center justify-between border-b px-4', inDrawer && 'pr-12')}>
        {!isCollapsed && (
          <div className="flex min-w-0 items-center gap-2">
            <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-primary">
              <Database className="h-4 w-4 text-primary-foreground" />
            </div>
            <span className="font-semibold">{{project.name}}</span>
          </div>
        )}
        {/* The drawer has its own Close in this corner; a rail toggle means nothing there. */}
        {!inDrawer && (
          <Button
            variant="ghost"
            size="icon"
            onClick={() => setIsCollapsed(!isCollapsed)}
            className="h-8 w-8"
            aria-label={isCollapsed ? 'Expand the navigation' : 'Collapse the navigation'}
          >
            {isCollapsed ? (
              <ChevronRight className="h-4 w-4" />
            ) : (
              <ChevronLeft className="h-4 w-4" />
            )}
          </Button>
        )}
      </div>

      {/*
        * The search box. Expanded only — 64px of collapsed rail has no room
        * for an input, and a search that silently did nothing there would be
        * the third dead control this layout has had.
        */}
      {!isCollapsed && (
        <div className="border-b px-3 py-3">
          <div className="relative">
            <Search className="pointer-events-none absolute left-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            <input
              ref={inputRef}
              type="text"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              onKeyDown={onKeyDown}
              placeholder="Search screens..."
              className="h-9 w-full rounded-md border border-input bg-background pl-8 pr-8 text-sm outline-none focus:border-primary"
              /* Combobox semantics, so a screen reader is told there is a list
                 below and which row is current — without them this is an input
                 that mysteriously changes the page when you press Enter. */
              role="combobox"
              aria-expanded={isSearching}
              aria-controls="sidebar-search-results"
              aria-activedescendant={
                isSearching && results[activeIndex]
                  ? `sidebar-result-${activeIndex}`
                  : undefined
              }
              aria-label="Search the navigation"
              autoComplete="off"
            />
            {query && (
              <button
                type="button"
                onClick={() => {
                  setQuery('');
                  inputRef.current?.focus();
                }}
                aria-label="Clear the search"
                className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              >
                <X className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
        </div>
      )}

      {/* Navigation */}
      <ScrollArea className="flex-1 px-2 py-4">
        {isSearching ? (
          /*
           * Results are a flat, ranked list — not the tree with rows hidden.
           * Filtering the tree in place leaves the headings of groups that
           * matched nothing, and the reader counts empty sections looking for
           * the one hit.
           */
          <div id="sidebar-search-results" role="listbox" aria-label="Search results" className="space-y-1">
            {results.length === 0 ? (
              <p className="px-4 py-6 text-center text-xs text-muted-foreground">
                No screen matches <span className="font-medium text-foreground">{query}</span>.
              </p>
            ) : (
              results.map((item, index) => (
                <SearchResultRow
                  key={item.href}
                  item={item}
                  needle={needle}
                  index={index}
                  isActive={index === activeIndex}
                  onHover={() => setActiveIndex(index)}
                  onChoose={() => go(item.href)}
                />
              ))
            )}
          </div>
        ) : (
          <nav className="space-y-6">
          <div className="space-y-1">
            <NavItemRow
              item={DASHBOARD_ENTRY}
              isActive={pathname === DASHBOARD_ENTRY.href}
              isCollapsed={isCollapsed}
              fallback={LayoutDashboard}
            />
          </div>

          {/* One block per dictionary category, in the order the server sent. */}
          {groups.map((group) => (
            <div key={group.code} className="space-y-1">
              {!isCollapsed && (
                <p className="mb-2 px-4 text-xs font-semibold text-muted-foreground">
                  {group.name}
                </p>
              )}
              {group.entries.map((item) => (
                <NavItemRow
                  key={item.href}
                  item={item}
                  isActive={pathname === item.href}
                  isCollapsed={isCollapsed}
                />
              ))}
            </div>
          ))}

          {adminEntries.length > 0 && (
            <div className="space-y-1">
              {!isCollapsed && (
                <p className="mb-2 px-4 text-xs font-semibold text-muted-foreground">
                  Administration
                </p>
              )}
              {adminEntries.map((item) => (
                <NavItemRow
                  key={item.href}
                  item={item}
                  isActive={pathname === item.href}
                  isCollapsed={isCollapsed}
                />
              ))}
            </div>
          )}
          </nav>
        )}
      </ScrollArea>
    </div>
  );
}

interface SearchResultRowProps {
  item: SearchableEntry;
  needle: string;
  index: number;
  isActive: boolean;
  onHover: () => void;
  onChoose: () => void;
}

/**
 * One search result: the icon, the title with the match marked, and where it
 * lives.
 *
 * `isActive` here is the keyboard cursor, not the current route — during a
 * search the reader is choosing, and highlighting the page they are already
 * on would fight the thing the arrow keys are moving.
 *
 * `onMouseEnter` moves that cursor too, so the mouse and the arrow keys never
 * disagree about which row Enter would open.
 */
function SearchResultRow({
  item,
  needle,
  index,
  isActive,
  onHover,
  onChoose,
}: SearchResultRowProps) {
  return (
    <button
      type="button"
      id={`sidebar-result-${index}`}
      role="option"
      aria-selected={isActive}
      onMouseEnter={onHover}
      onClick={onChoose}
      className={cn(
        'flex w-full items-center gap-2 rounded-md px-3 py-2 text-left text-sm transition-colors',
        isActive ? 'bg-accent text-accent-foreground' : 'hover:bg-accent/50'
      )}
    >
      {item.icon ? (
        <Icon name={item.icon} size={16} className="flex-shrink-0" />
      ) : (
        <Database className="h-4 w-4 flex-shrink-0" />
      )}
      <span className="min-w-0 flex-1 truncate">{highlight(item.title, needle)}</span>
      {item.group && (
        <span className="flex-shrink-0 text-xs text-muted-foreground">{item.group}</span>
      )}
    </button>
  );
}

interface NavItemRowProps {
  item: NavEntry;
  isActive: boolean;
  isCollapsed: boolean;
  /** Drawn when the dictionary names no icon. */
  fallback?: React.ElementType;
}

function NavItemRow({ item, isActive, isCollapsed, fallback }: NavItemRowProps) {
  const navigate = useNavigate();
  const Fallback = fallback ?? Database;

  const button = (
    <Button
      variant={isActive ? 'secondary' : 'ghost'}
      className={cn(
        'w-full justify-start gap-2',
        isCollapsed && 'justify-center px-2'
      )}
      onClick={() => navigate({ to: item.href })}
      aria-current={isActive ? 'page' : undefined}
      aria-label={item.title}
      title={item.description}
    >
      {/* `Icon` resolves a lucide id or renders an uploaded `data:` image; the
          fallback is for a dictionary row that names neither. */}
      {item.icon ? (
        <Icon name={item.icon} size={16} className={cn(!isCollapsed && 'mr-2')} />
      ) : (
        <Fallback className={cn('h-4 w-4', !isCollapsed && 'mr-2')} />
      )}
      {!isCollapsed && <span className="flex-1 truncate text-left">{item.title}</span>}
    </Button>
  );

  if (!isCollapsed) return button;

  return (
    <TooltipProvider delayDuration={0}>
      <Tooltip>
        <TooltipTrigger asChild>{button}</TooltipTrigger>
        <TooltipContent side="right">{item.title}</TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

/**
 * The bell beside Log out.
 *
 * Every write to a business entity is two transactions — the save that commits
 * the record as a draft, and the background one that finalises it or explains
 * why it could not — and this is where a user finds out how theirs ended. The
 * list is read from `/notifications`, which serves that user's own rows of the
 * audit trail and nothing else.
 *
 * Three behaviours are the point of it and are easy to lose in a refactor:
 *
 *   - newest first, because the transaction a user is waiting on is the one
 *     they just started;
 *   - unread items look different from read ones — a tinted row, a solid dot
 *     and a heavier title, not a subtler shade of the same thing;
 *   - opening the panel marks what it shows as read, so the badge means
 *     "things you have not seen" rather than "things that have ever happened".
 */

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useNavigate } from "@tanstack/react-router";
import { AlertCircle, Bell, CheckCircle2, Clock } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { apiClient } from "@/lib/api-client";

export type TransactionOutcome = "pending" | "succeeded" | "failed";

export interface TransactionNotification {
  id: string;
  at: string;
  read: boolean;
  outcome: TransactionOutcome;
  phase: "draft" | "finalize";
  operation: "create" | "update" | "delete" | "save";
  entityTable: string;
  entityLabel: string;
  recordId: string | null;
  recordLabel: string;
  title: string;
  detail: string;
  href: string | null;
}

interface NotificationPage {
  data: TransactionNotification[];
  meta: { unread: number; limit: number; nextCursor: string | null };
}

/** "just now", "4 min ago", "2 h ago", then the date. */
function relativeTime(iso: string): string {
  const then = new Date(iso).getTime();
  if (Number.isNaN(then)) return "";
  const seconds = Math.max(0, Math.round((Date.now() - then) / 1000));
  if (seconds < 45) return "just now";
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return `${minutes} min ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `${hours} h ago`;
  const days = Math.round(hours / 24);
  if (days < 7) return `${days} d ago`;
  return new Date(iso).toLocaleDateString();
}

function OutcomeIcon({ outcome }: { outcome: TransactionOutcome }) {
  if (outcome === "succeeded") {
    return <CheckCircle2 className="h-4 w-4 shrink-0 text-emerald-600 dark:text-emerald-400" aria-hidden />;
  }
  if (outcome === "failed") {
    return <AlertCircle className="h-4 w-4 shrink-0 text-destructive" aria-hidden />;
  }
  return <Clock className="h-4 w-4 shrink-0 text-amber-600 dark:text-amber-400" aria-hidden />;
}

const OUTCOME_LABEL: Record<TransactionOutcome, string> = {
  pending: "In progress",
  succeeded: "Succeeded",
  failed: "Failed",
};

export function NotificationBell() {
  const [open, setOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const { data, isLoading, isError } = useQuery({
    queryKey: ["notifications"],
    queryFn: () => apiClient.get<NotificationPage>("/notifications", { limit: 30 }),
    // The finalising transaction runs in the background and finishes without
    // the browser being told, so the list has to look again rather than wait
    // for a user action that will never come.
    refetchInterval: open ? 5_000 : 30_000,
    refetchOnWindowFocus: true,
  });

  const markRead = useMutation({
    mutationFn: (ids: string[]) => apiClient.post("/notifications/read", { ids }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ["notifications"] }),
  });

  const markAllRead = useMutation({
    mutationFn: () => apiClient.post("/notifications/read-all", {}),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ["notifications"] }),
  });

  const items = data?.data ?? [];
  const unread = data?.meta.unread ?? 0;

  // Close on an outside click or Escape — the panel is a plain popover rather
  // than a menu, because its rows contain a title, a body and a timestamp and
  // a menu item is a single line.
  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: MouseEvent) => {
      if (!containerRef.current?.contains(event.target as Node)) setOpen(false);
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("mousedown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [open]);

  // Opening the panel reads what it shows. Marking on the *shown* ids rather
  // than "all" keeps a notification that arrives while the panel is open
  // unread until the user has actually had it in front of them.
  useEffect(() => {
    if (!open || items.length === 0) return;
    const unreadIds = items.filter((item) => !item.read).map((item) => item.id);
    if (unreadIds.length === 0) return;
    markRead.mutate(unreadIds);
    // `markRead` is a stable mutation object; re-running on it would loop.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, items]);

  const openRecord = (item: TransactionNotification) => {
    if (!item.href) return;
    setOpen(false);
    navigate({ to: item.href as never });
  };

  return (
    <div ref={containerRef} className="relative">
      <button
        type="button"
        onClick={() => setOpen((value) => !value)}
        aria-label={unread > 0 ? `Notifications, ${unread} unread` : "Notifications"}
        aria-expanded={open}
        aria-haspopup="dialog"
        className="relative p-1.5 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
        title="Notifications"
      >
        <Bell className="w-4 h-4" />
        {unread > 0 && (
          <span className="absolute -right-0.5 -top-0.5 flex h-4 min-w-[1rem] items-center justify-center rounded-full bg-destructive px-1 text-[10px] font-semibold leading-none text-foreground">
            {unread > 99 ? "99+" : unread}
          </span>
        )}
      </button>

      {open && (
        <div
          role="dialog"
          aria-label="Notifications"
          className="absolute right-0 z-50 mt-2 w-[min(24rem,calc(100vw-2rem))] overflow-hidden rounded-lg border border-border bg-card shadow-lg"
        >
          <div className="flex items-center justify-between border-b border-border px-4 py-3">
            <div>
              <p className="text-sm font-semibold text-foreground">Your transactions</p>
              <p className="text-xs text-muted-foreground">
                {unread > 0 ? `${unread} unread` : "All caught up"}
              </p>
            </div>
            {items.length > 0 && (
              <button
                type="button"
                onClick={() => markAllRead.mutate()}
                disabled={markAllRead.isPending || unread === 0}
                className="text-xs font-medium text-primary hover:underline disabled:cursor-not-allowed disabled:text-muted-foreground disabled:no-underline"
              >
                Mark all read
              </button>
            )}
          </div>

          <div className="max-h-[26rem] overflow-y-auto">
            {/* A refresh that fails keeps what was last loaded on screen. React
                Query holds the previous data and sets `isError` for a failed
                refetch, and the panel refetches every five seconds while open:
                one dropped request used to replace a list the reader already
                had with an error. Only a panel with nothing to show says so. */}
            {isError && data && (
              <p className="border-b border-border px-4 py-2 text-xs text-muted-foreground">
                Could not refresh — showing what was last loaded.
              </p>
            )}
            {isLoading ? (
              <p className="px-4 py-6 text-sm text-muted-foreground">Loading…</p>
            ) : isError && !data ? (
              <p className="px-4 py-6 text-sm text-destructive">
                Your transactions could not be loaded.
              </p>
            ) : items.length === 0 ? (
              <p className="px-4 py-6 text-sm text-muted-foreground">
                Nothing yet. Saving or updating a record will show its progress here.
              </p>
            ) : (
              <ul className="divide-y divide-border">
                {items.map((item) => (
                  <li key={item.id}>
                    <button
                      type="button"
                      onClick={() => openRecord(item)}
                      disabled={!item.href}
                      className={[
                        "flex w-full gap-3 px-4 py-3 text-left transition-colors",
                        item.href ? "hover:bg-muted/60 cursor-pointer" : "cursor-default",
                        // Read and unread are deliberately far apart: an unread
                        // row is tinted and its title is heavier, so the two
                        // are distinguishable at a glance and without colour
                        // alone doing the work.
                        item.read ? "bg-card" : "bg-primary/5",
                      ].join(" ")}
                    >
                      <span className="pt-0.5">
                        <OutcomeIcon outcome={item.outcome} />
                      </span>
                      <span className="min-w-0 flex-1">
                        <span className="flex items-baseline justify-between gap-2">
                          <span
                            className={[
                              "truncate text-sm text-foreground",
                              item.read ? "font-normal" : "font-semibold",
                            ].join(" ")}
                          >
                            {item.title}
                          </span>
                          <span className="shrink-0 text-[11px] text-muted-foreground">
                            {relativeTime(item.at)}
                          </span>
                        </span>
                        <span className="mt-1 block text-xs leading-snug text-muted-foreground">
                          {item.detail}
                        </span>
                        <span className="mt-1.5 flex items-center gap-2">
                          <span
                            className={[
                              "rounded-full border px-1.5 py-0.5 text-[10px] font-medium",
                              item.outcome === "succeeded"
                                ? "border-emerald-200/60 dark:border-emerald-800 bg-emerald-50 dark:bg-emerald-950/40 text-emerald-700 dark:text-emerald-300"
                                : item.outcome === "failed"
                                  ? "border-destructive/30 bg-destructive/10 text-destructive"
                                  : "border-amber-200/60 dark:border-amber-800 bg-amber-50 dark:bg-amber-950/40 text-amber-700 dark:text-amber-300",
                            ].join(" ")}
                          >
                            {OUTCOME_LABEL[item.outcome]}
                          </span>
                          {!item.read && (
                            <span
                              className="h-1.5 w-1.5 rounded-full bg-primary"
                              aria-label="Unread"
                            />
                          )}
                        </span>
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * The rule editor of the generated application — the modelling tool's own.
 *
 * `GoRulesEditorPanel` and `RuleTryIt` are the files the Logic step runs,
 * byte for byte. What is this application's is what they are handed: the
 * fields, values and processes this model declares (`lib/rule-model.ts`, written
 * when it was generated) and the route that runs a rule (`POST /rules/simulate`).
 *
 * The panel draws with the GoRules editor and Monaco, which touch `window`, so
 * it is loaded in the browser only, after the first render.
 */

import { lazy, Suspense, useEffect, useMemo, useState } from "react";
import { RuleTryIt } from "@/editors/components/eml/RuleTryIt";
import { asDecisionTable } from "@/editors/lib/automation/rule-content";
import { simulateRule as dryRun } from "@/lib/logic-host";
import { sampleRecord } from "@/editors/lib/eml/rule-templates";
import { RULE_MODEL } from "@/lib/rule-model";

const GoRulesEditorPanel = lazy(() =>
  import("@/editors/components/eml/GoRulesEditorPanel").then((m) => ({ default: m.GoRulesEditorPanel }))
);

/** Graph nodes a plain decision table is made of; anything else is the author's own graph. */
const TABLE_ONLY = new Set(["inputNode", "outputNode", "decisionTableNode"]);

interface RuleGraphEditorProps {
  /** The table the rule is filed under, e.g. `bus_student`. */
  entityName: string;
  /** What the rule is called. */
  ruleName: string;
  /** The stored rule: a graph, or a bare decision table. Read once, when the editor opens. */
  initialContent: string;
  /** The columns the dictionary shows, for an entity the model does not describe. */
  fallbackFields?: string[];
  /** Every edit, as the graph's JSON. */
  onChange: (graphJson: string) => void;
}

/** The rule as a graph to open, when it is more than a table; otherwise as the table. */
function readContent(content: string): { jdmGraph?: string } {
  try {
    const parsed = JSON.parse(content) as { nodes?: Array<{ type?: string }> };
    if (Array.isArray(parsed?.nodes) && parsed.nodes.some((node) => !TABLE_ONLY.has(node.type ?? ""))) {
      return { jdmGraph: content };
    }
  } catch {
    // not JSON: open an empty table
  }
  return {};
}

export function RuleGraphEditor({
  entityName,
  ruleName,
  initialContent,
  fallbackFields = [],
  onChange,
}: RuleGraphEditorProps) {
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);

  const entity = RULE_MODEL.find((candidate) => candidate.table === entityName);
  // Keyed by what the list says, not by the array: a parent that builds it on
  // every render would otherwise hand the editor "new" fields each time it
  // re-rendered, which redraws the graph under whatever the author has open.
  const fallbackKey = fallbackFields.join("\u0000");
  const fields = useMemo(
    () => (entity ? entity.fields.map((field) => field.name) : fallbackKey ? fallbackKey.split("\u0000") : []),
    [entity, fallbackKey]
  );
  const fieldTypes = useMemo(
    () => Object.fromEntries((entity?.fields ?? []).map((field) => [field.name, field.type])),
    [entity]
  );
  const values = useMemo(() => entity?.values ?? {}, [entity]);
  const processes = useMemo(() => entity?.processes ?? [], [entity]);
  const [seed] = useState(() => ({
    table: asDecisionTable(initialContent),
    graph: readContent(initialContent).jdmGraph,
  }));
  // The graph as the editor last drew it. It goes back into the panel on every
  // edit, as the Logic step does: the panel derives from it what it offers next —
  // the Record's schema on a Record just added, the fields a table may read, the
  // names that do not exist — and the Try-it panel runs it, saved or not.
  const [current, setCurrent] = useState<string | undefined>(seed.graph);

  if (!entityName) {
    return (
      <p className="px-6 py-8 text-sm text-muted-foreground">
        Choose the record type first: the editor offers only its fields.
      </p>
    );
  }
  if (!mounted) {
    return <div className="py-8 text-center text-sm text-muted-foreground">Loading editor…</div>;
  }

  return (
    <div className="p-4">
      <Suspense
        fallback={<div className="py-8 text-center text-sm text-muted-foreground">Loading editor…</div>}
      >
        <GoRulesEditorPanel
          jdmGraph={current}
          table={seed.table}
          entityFields={fields}
          entityEnums={values}
          entityWorkflows={processes}
          fieldTypes={fieldTypes}
          ruleName={ruleName}
          entity={entityName}
          dryRun={dryRun}
          sampleRecord={JSON.stringify(sampleRecord(fields, values, fieldTypes), null, 2)}
          onChange={(json) => {
            setCurrent(json);
            onChange(json);
          }}
        />
      </Suspense>
      <RuleTryIt
        entity={entityName}
        dryRun={dryRun}
        entityFields={fields}
        entityEnums={values}
        fieldTypes={fieldTypes}
        getGraph={() => current ?? initialContent}
      />
    </div>
  );
}

/**
 * Help, and the only shape it takes.
 *
 * Every piece of help in this application — a window's overview, a tab, a
 * field's dictionary text, the automation builder's guide — arrives as one
 * toaster pinned to the top right, opened by a `?` button and closed by its
 * own close button. Nothing else shows help: no centred modal over the record
 * you were reading, no popover that vanishes when the pointer moves, no pane
 * that takes the screen away from the work.
 *
 * Three properties are the whole contract, and each replaced something that
 * used to be true here:
 *
 * 1. **It does not dismiss itself.** No timeout, no click-outside, no Escape.
 *    Help is read while the form it describes is being filled in, and a panel
 *    that closes on the next keystroke cannot be read at all. The close button
 *    is the only way out — which is also why the button is always rendered and
 *    always reachable.
 * 2. **It never covers the page.** No backdrop and no focus trap, so the
 *    record stays visible and editable with the help open beside it.
 * 3. **There is one of it.** Opening a second topic replaces the first rather
 *    than stacking, because a tower of panels down the right edge of the
 *    screen is the thing a toaster is supposed to avoid.
 */

import { HelpCircle, X } from "lucide-react";
import {
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useMemo,
  useState,
} from "react";
import { cn } from "@/lib/utils";

export interface HelpTopic {
  /**
   * Identifies the topic so pressing the same `?` twice is a no-op rather than
   * a flicker. Two buttons describing the same window share a key.
   */
  key: string;
  title: string;
  /** Rendered inside the scrolling body. Plain text is the common case. */
  body: ReactNode;
}

interface HelpContextValue {
  topic: HelpTopic | null;
  showHelp: (topic: HelpTopic) => void;
  closeHelp: () => void;
}

const HelpContext = createContext<HelpContextValue | null>(null);

/**
 * Outside a `HelpProvider` the hook returns a working no-op rather than
 * throwing. A `?` button is not worth crashing a screen over, and the
 * standalone screens (sign-in, the error boundary) render outside the
 * provider on purpose.
 */
const NO_HELP: HelpContextValue = {
  topic: null,
  showHelp: () => {},
  closeHelp: () => {},
};

export function useHelp(): HelpContextValue {
  return useContext(HelpContext) ?? NO_HELP;
}

export function HelpProvider({ children }: { children: ReactNode }) {
  const [topic, setTopic] = useState<HelpTopic | null>(null);

  const showHelp = useCallback((next: HelpTopic) => setTopic(next), []);
  const closeHelp = useCallback(() => setTopic(null), []);

  const value = useMemo(() => ({ topic, showHelp, closeHelp }), [topic, showHelp, closeHelp]);

  return (
    <HelpContext.Provider value={value}>
      {children}
      <HelpToaster />
    </HelpContext.Provider>
  );
}

/**
 * The toaster itself. Rendered once, by the provider — a screen never places
 * it, so no screen can put help anywhere else.
 */
function HelpToaster() {
  const { topic, closeHelp } = useHelp();
  if (!topic) return null;

  return (
    <div
      // `aria-live` rather than `role="dialog"`: this is not modal, the page
      // behind it stays usable, and announcing it without stealing focus is
      // the behaviour that matches what it looks like.
      aria-live="polite"
      // `top-20` rather than `top-4`, and the number is a header's height.
      // Every screen here carries a sticky header 3.5–4rem tall whose
      // right-hand end holds the theme control, the notification bell and the
      // account menu — at `top-4` this panel sat over them, so the one surface
      // whose whole point is that the application stays usable behind it was
      // the thing making three of its controls unclickable. Found by driving
      // it in a browser; nothing in the markup says so.
      className="fixed right-4 top-20 z-[70] flex max-h-[calc(100vh-6rem)] w-[min(26rem,calc(100vw-2rem))] flex-col rounded-xl border border-border bg-popover text-popover-foreground shadow-2xl"
    >
      <div className="flex items-start justify-between gap-3 border-b border-border px-4 py-3">
        <div className="flex min-w-0 items-center gap-2">
          <HelpCircle className="h-4 w-4 flex-shrink-0 text-primary" />
          <h2 className="truncate text-sm font-semibold">{topic.title}</h2>
        </div>
        <button
          type="button"
          onClick={closeHelp}
          aria-label="Close help"
          title="Close help"
          className="-mr-1 -mt-1 rounded-md p-1 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          <X className="h-4 w-4" />
        </button>
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto px-4 py-3 text-sm leading-relaxed">
        {topic.body}
      </div>
    </div>
  );
}

/**
 * The `?` button. The only thing in the application that opens help.
 *
 * It is deliberately the same control everywhere — beside a window title,
 * beside a field label, in a toolbar — so that "press the question mark" is
 * true of every screen.
 */
export function HelpButton({
  topic,
  label,
  className,
  size = "sm",
}: {
  topic: HelpTopic;
  /** For the accessible name: "Help for Sales Order". */
  label: string;
  className?: string;
  size?: "sm" | "md";
}) {
  const { showHelp } = useHelp();
  return (
    <button
      type="button"
      onClick={() => showHelp(topic)}
      aria-label={`Help for ${label}`}
      title={`Help for ${label}`}
      className={cn(
