/**
 * Dictionary sync provider.
 *
 * Starts the Application Dictionary syncing once a session exists, and reports
 * when it has landed. Screens do not read this directly — the `use-sys-electric`
 * hooks do, to decide whether to answer from the local collections or fall back
 * to HTTP.
 *
 * Scoping happens on the server: the shape proxy reads the caller's roles from
 * the session and filters before streaming, so this component passes no role of
 * its own. It does watch the role for *changes*: a different role means a
 * different slice of the dictionary, so the collections are torn down and rebuilt
 * rather than left holding rows from the previous session.
 *
 * A failed sync is not a failed app. The dictionary stays reachable over HTTP,
 * so a sync error is recorded and warned about, never thrown.
 */

import React, {
  createContext,
  type ReactNode,
  useContext,
  useEffect,
  useState,
} from "react";
import {
  getSysCollections,
  isShapeSyncUnavailable,
  resetSysCollections,
  SYNC_ENABLED,
  whenSysCollectionsReady,
} from "@/lib/sys-collections";

/* -------------------------------------------------------------------------- */
/*  Context                                                                    */
/* -------------------------------------------------------------------------- */

interface ElectricContextValue {
  /** True once every dictionary collection has completed its first sync. */
  isSynced: boolean;
  isSyncing: boolean;
  error: Error | null;
  /**
   * False when VITE_ELECTRIC_SYNC is off, and false once the shape proxy has
   * said this deployment has no Electric server behind it — hooks read over
   * HTTP instead. Both are the same answer to the same question; only one of
   * them was configured in advance.
   */
  isEnabled: boolean;
}

const ElectricContext = createContext<ElectricContextValue>({
  isSynced: false,
  isSyncing: false,
  error: null,
  isEnabled: false,
});

export function useElectric(): ElectricContextValue {
  return useContext(ElectricContext);
}

/* -------------------------------------------------------------------------- */
/*  Provider                                                                   */
/* -------------------------------------------------------------------------- */

export interface ElectricProviderProps {
  children: ReactNode;
  /**
   * The signed-in user's role. Used only to detect a change of identity — the
   * value is never sent to the server, which derives the role from the session.
   */
  role: string;
}

export function ElectricProvider({ children, role }: ElectricProviderProps) {
  const [isSynced, setIsSynced] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    // No session yet: a shape request now would be unauthenticated and
    // rejected. And once the proxy has answered "no Electric upstream", asking
    // again on each navigation is six requests for an answer already held.
    if (!SYNC_ENABLED || isShapeSyncUnavailable() || !role) {
      setIsSynced(false);
      return;
    }

    let cancelled = false;

    async function sync() {
      try {
        setIsSyncing(true);
        setError(null);

        getSysCollections();
        const ready = await whenSysCollectionsReady();
        if (cancelled) return;

        setIsSynced(ready);
      } catch (err) {
        if (cancelled) return;
        const failure = err instanceof Error ? err : new Error(String(err));
        console.warn(
          "[ElectricProvider] dictionary sync unavailable, falling back to HTTP:",
          failure.message
        );
        setError(failure);
        setIsSynced(false);
      } finally {
        if (!cancelled) setIsSyncing(false);
      }
    }

    void sync();

    return () => {
      cancelled = true;
      // The rows in these collections were filtered for the role that just went
      // away. Dropping them is what keeps the next session from reading them.
      resetSysCollections();
      setIsSynced(false);
    };
  }, [role]);

  return (
    <ElectricContext.Provider
      value={{
        isSynced,
        isSyncing,
        error,
        isEnabled: SYNC_ENABLED && !isShapeSyncUnavailable(),
      }}
    >
      {children}
    </ElectricContext.Provider>
  );
}

/**
 * TanStack Query Provider
 *
 * Wraps the app with TanStack Query (React Query) for server state management.
 */

import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { ReactQueryDevtools } from "@tanstack/react-query-devtools";
import React, { type ReactNode, useState } from "react";

interface ProvidersProps {
  children: ReactNode;
}

export function QueryProvider({ children }: ProvidersProps) {
  const [queryClient] = useState(
    () =>
      new QueryClient({
        defaultOptions: {
          queries: {
            staleTime: 60 * 1000, // 1 minute
            gcTime: 5 * 60 * 1000, // 5 minutes (formerly cacheTime)
            refetchOnWindowFocus: false,
            retry: (failureCount, error) => {
              const apiError = error as { statusCode?: number };
              // Don't retry on 4xx client errors
              if (apiError.statusCode && apiError.statusCode >= 400 && apiError.statusCode < 500) {
                return false;
              }
              // Don't retry on network failures (ERR_CONNECTION_REFUSED, offline)
              // — backend won't recover in milliseconds, so retrying just floods the console
              if (!apiError.statusCode) {
                return false;
              }
              // Retry once on transient 5xx server errors
              return failureCount < 1;
            },
          },
          mutations: {
            retry: false,
          },
        },
      })
  );

  return (
    <QueryClientProvider client={queryClient}>
      {children}
      <ReactQueryDevtools initialIsOpen={false} />
    </QueryClientProvider>
  );
}

/**
 * Application Providers
 *
 * Provider order (outer → inner):
 * 1. ThemeProvider  — light / dark / system, applied to <html>. Outermost so
 *                     every screen below it, including the ones that render
 *                     before a session exists, can read and change it.
 * 2. QueryProvider  — TanStack Query server state
 * 3. AuthProvider   — session / user object
 * 4. ElectricProvider — syncs the Application Dictionary into TanStack DB
 *                       collections over ElectricSQL. The server scopes the
 *                       shape to the session's roles, so a client only ever
 *                       holds the part of the dictionary it may see.
 * 5. TranslationProvider — i18n
 * 6. HelpProvider   — the help toaster, and the only surface help appears on.
 *                     Innermost, so a `?` anywhere inside opens it; it renders
 *                     the toaster itself, so no screen places one.
 *
 */

import React, { startTransition, type ReactNode, useEffect, useState } from 'react';
import { QueryProvider } from './query-provider';
import { ElectricProvider } from './electric-provider';
import { HelpProvider } from '@/components/help/help-toaster';
import { ThemeProvider } from '@/components/theme/theme-provider';
import { AuthProvider, useAuth } from '@/contexts/auth-context';
import { TranslationProvider } from '@/lib/translations';
import { Toaster } from 'sonner';

interface ProvidersProps {
  children: ReactNode;
}

function ClientToaster() {
  const [mounted, setMounted] = useState(false);
  // Non-urgent on purpose. This sits at the root of every route, so an urgent
  // update here lands while the page is still hydrating and React throws away
  // the server HTML for the whole boundary — "received an update before it
  // finished hydrating". Nothing is waiting on the toaster, so it can arrive a
  // tick late.
  useEffect(() => startTransition(() => setMounted(true)), []);
  // Bottom right: the top right is the help toaster's, and it stays open.
  return mounted ? <Toaster position="bottom-right" richColors /> : null;
}

/**
 * Inner wrapper so ElectricProvider can read the role from AuthContext.
 * Sits inside AuthProvider so useAuth() is always available.
 */
function ElectricBridge({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const role = (user as { role?: string } | null)?.role ?? '';
  return (
    <ElectricProvider role={role}>
      {children}
    </ElectricProvider>
  );
}

export function Providers({ children }: ProvidersProps) {
  return (
    <ThemeProvider>
      <QueryProvider>
        <AuthProvider>
          <ElectricBridge>
            <TranslationProvider>
              <HelpProvider>{children}</HelpProvider>
              <ClientToaster />
            </TranslationProvider>
          </ElectricBridge>
        </AuthProvider>
      </QueryProvider>
    </ThemeProvider>
  );
}

