/**
 * Give the administrator's assistant this application's model.
 *
 * The application ships with the `.eml.mmd` it was generated from, and the
 * backend embeds it at startup. This hook is the other end: a CopilotKit
 * action the model calls when it needs to know what the application actually
 * declares — which entities exist, what a rule decides, what a process does on
 * delete — rather than answering from what it remembers about ERDs in general.
 *
 * A search rather than a preloaded prompt for two reasons. The model is far
 * too large to send with every message, and making the lookup visible means an
 * administrator can see what the assistant consulted before acting on advice
 * about their production data.
 *
 */

import { useCopilotAction, useCopilotReadable } from '@copilotkit/react-core'
import { useCallback, useEffect, useState } from 'react'
import { apiClient } from '../lib/api-client'

interface RetrievedChunk {
  kind: string
  name: string
  text: string
  score: number
}

interface SearchResponse {
  chunks: RetrievedChunk[]
  ready?: boolean
}

export function useModelAssistant() {
  const [ready, setReady] = useState<boolean | null>(null)

  // Embedding happens in the background at startup, so the assistant needs to
  // know whether the model is searchable yet — otherwise an empty result early
  // in the application's life reads as "this application declares nothing".
  useEffect(() => {
    let cancelled = false
    apiClient
      .get<{ ready: boolean }>('/model-context/status')
      .then((response) => {
        if (!cancelled) setReady(Boolean(response?.ready))
      })
      .catch(() => {
        if (!cancelled) setReady(false)
      })
    return () => {
      cancelled = true
    }
  }, [])

  useCopilotReadable({
    description:
      "Whether this application's model has been indexed and can be searched with the " +
      'searchModel action.',
    value: { modelSearchable: ready },
    available: ready === null ? 'disabled' : 'enabled',
  })

  const search = useCallback(async ({ question }: { question: string }) => {
    try {
      const response = await apiClient.post<SearchResponse>('/model-context/search', {
        question,
        topK: 8,
      })

      if (!response?.chunks?.length) {
        return response?.ready === false
          ? "This application's model has not finished indexing yet. Say so rather than guessing."
          : 'Nothing in this application\'s model matches that. Say so rather than inventing an answer.'
      }

      return response.chunks
        .map((chunk) => `--- ${chunk.kind}: ${chunk.name} ---\n${chunk.text}`)
        .join('\n\n')
    } catch (error) {
      // Returned rather than thrown: the assistant can report that it could not
      // look something up and carry on, where a throw ends the turn.
      const message = error instanceof Error ? error.message : 'unknown error'
      return `The model search failed (${message}). Do not guess at the answer.`
    }
  }, [])

  useCopilotAction({
    name: 'searchModel',
    description:
      "Search this application's data model — its entities and their fields, the business " +
      'rules that run on them, and the multi-step processes that create, update and delete ' +
      'records. Use it before answering any question about how this application behaves, and ' +
      'before proposing a change to an entity, a rule or a workflow.',
    parameters: [
      {
        name: 'question',
        type: 'string',
        description:
          "What you need to know, in plain language — for example 'which processes write to " +
          "CAPA' or 'what happens when a stability test is deleted'.",
        required: true,
      },
    ],
    handler: search,
  })
}

import { useQuery } from "@tanstack/react-query";
import { useCallback, useMemo, useState } from "react";
import { apiClient, type PaginatedResponse } from "@/lib/api-client";

interface UseRecordNavigationOptions {
  endpoint: string;
  params?: Record<string, unknown>;
  limit?: number;
  enabled?: boolean;
}

interface RecordNavigationResult<T = Record<string, unknown>> {
  records: T[];
  totalCount: number;
  currentIndex: number;
  currentRecord: T | null;
  isLoading: boolean;
  error: Error | null;
  page: number;
  totalPages: number;
  setCurrentIndex: (index: number) => void;
  goFirst: () => void;
  goPrev: () => void;
  goNext: () => void;
  goLast: () => void;
  goToPage: (page: number) => void;
  canGoPrev: boolean;
  canGoNext: boolean;
  refetch: () => void;
}

export function useRecordNavigation<T = Record<string, unknown>>({
  endpoint,
  params,
  limit = 100,
  enabled = true,
}: UseRecordNavigationOptions): RecordNavigationResult<T> {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [page, setPage] = useState(1);

  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ["ad-records", endpoint, params, page, limit],
    queryFn: () =>
      apiClient.get<PaginatedResponse<T>>(endpoint, {
        ...params,
        page,
        limit,
      }),
    enabled,
  });

  const records = useMemo(() => data?.data || [], [data]);
  const totalCount = data?.meta?.total || 0;
  const totalPages = data?.meta?.totalPages || 1;

  const currentRecord = records[currentIndex] || null;

  const goFirst = useCallback(() => {
    if (page > 1) {
      setPage(1);
      setCurrentIndex(0);
    } else {
      setCurrentIndex(0);
    }
  }, [page]);

  const goPrev = useCallback(() => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    } else if (page > 1) {
      setPage(page - 1);
      setCurrentIndex(limit - 1);
    }
  }, [currentIndex, page, limit]);

  const goNext = useCallback(() => {
    if (currentIndex < records.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else if (page < totalPages) {
      setPage(page + 1);
      setCurrentIndex(0);
    }
  }, [currentIndex, records.length, page, totalPages]);

  const goLast = useCallback(() => {
    if (page < totalPages) {
      setPage(totalPages);
      setCurrentIndex(0);
    } else {
      setCurrentIndex(records.length - 1);
    }
  }, [page, totalPages, records.length]);

  const goToPage = useCallback((newPage: number) => {
    setPage(newPage);
    setCurrentIndex(0);
  }, []);

  const globalIndex = (page - 1) * limit + currentIndex;
  const canGoPrev = globalIndex > 0;
  const canGoNext = globalIndex < totalCount - 1;

  return {
    records,
    totalCount,
    currentIndex,
    currentRecord,
    isLoading,
    error: error as Error | null,
    page,
    totalPages,
    setCurrentIndex,
    goFirst,
    goPrev,
    goNext,
    goLast,
    goToPage,
    canGoPrev,
    canGoNext,
    refetch,
  };
}

/**
 * The Application Dictionary as the user sees it: windows, their tabs, and
 * the fields on each tab.
 *
 * `sys_table` and `sys_column` are the storage layer, where a value is kept.
 * `sys_window`, `sys_tab` and `sys_field` are the view layer: which screens
 * exist, what they are called, which fields they show, in what order and
 * under what label. Every screen that names an entity or a field to a person
 * (the rule editor, Report Designs, the document designer) names it from here.
 *
 * Each field still carries the key the runtime reads (`table_name`,
 * `column_name`): rules and report bindings are stored against those, because
 * that is what the engine evaluates. The key travels as a value and is never
 * the label.
 */

import { useQuery } from "@tanstack/react-query";
import { apiClient } from "@/lib/api-client";

interface SysWindowRow {
  sys_window_id: string;
  name: string;
  help?: string | null;
}

interface SysTabRow {
  sys_tab_id: string;
  sys_window_id: string;
  name: string;
  help?: string | null;
  tab_level: number;
  seq_no: number;
  is_active?: boolean;
}

interface SysFieldRow {
  sys_field_id: string;
  sys_tab_id: string;
  name: string;
  seq_no: number;
  is_active?: boolean;
  column_name: string;
  table_name: string;
}

export interface DictionaryField {
  /** The key the runtime reads. Stored, never shown. */
  value: string;
  /** The field's label, as the window shows it. */
  label: string;
}

export interface DictionaryTab {
  tabId: string;
  windowId: string;
  /** "Fee Invoice", or "Fee Invoice › Invoice Line" for a tab below the first level. */
  label: string;
  help: string;
  level: number;
  /** The storage key rules and report designs are filed under. Never shown. */
  tableName: string;
  fields: DictionaryField[];
}

async function loadDictionary(): Promise<DictionaryTab[]> {
  const [windows, tabs, fields] = await Promise.all([
    apiClient.get<{ data?: SysWindowRow[] }>("/sys/windows?limit=1000"),
    apiClient.get<{ data?: SysTabRow[] }>("/sys/tabs?limit=5000"),
    apiClient.get<{ data?: SysFieldRow[] }>("/sys/fields?limit=100000"),
  ]);
  const windowById = new Map((windows.data ?? []).map((w) => [w.sys_window_id, w]));

  const fieldsByTab = new Map<string, SysFieldRow[]>();
  for (const field of fields.data ?? []) {
    if (field.is_active === false) continue;
    const list = fieldsByTab.get(field.sys_tab_id) ?? [];
    list.push(field);
    fieldsByTab.set(field.sys_tab_id, list);
  }

  return (tabs.data ?? [])
    .filter((tab) => tab.is_active !== false && windowById.has(tab.sys_window_id))
    .map((tab): DictionaryTab | null => {
      const window = windowById.get(tab.sys_window_id);
      const own = [...(fieldsByTab.get(tab.sys_tab_id) ?? [])].sort((a, b) => a.seq_no - b.seq_no);
      const tableName = own[0]?.table_name;
      if (!window || !tableName) return null;
      return {
        tabId: tab.sys_tab_id,
        windowId: tab.sys_window_id,
        label: tab.tab_level > 0 ? `${window.name} › ${tab.name}` : window.name,
        help: (tab.tab_level > 0 ? tab.help : window.help) ?? "",
        level: tab.tab_level,
        tableName,
        fields: own.map((field) => ({ value: field.column_name, label: field.name })),
      };
    })
    .filter((tab): tab is DictionaryTab => tab !== null)
    .sort((a, b) => a.label.localeCompare(b.label));
}

/** Every tab of every window, with its fields in window order. */
export function useDictionaryTabs() {
  return useQuery({
    queryKey: ["dictionary", "tabs"],
    queryFn: loadDictionary,
    staleTime: 5 * 60 * 1000,
  });
}

/** The tab a storage key is shown as — its first-level tab when there are several. */
export function tabForTable(
  tabs: DictionaryTab[] | undefined,
  tableName: string | undefined
): DictionaryTab | undefined {
  if (!tabs || !tableName) return undefined;
  const matches = tabs.filter((tab) => tab.tableName === tableName);
  return matches.find((tab) => tab.level === 0) ?? matches[0];
}

/**
 * TanStack Query Hooks for Entity CRUD Operations
 *
 */

import {
  useQuery,
  useMutation,
  useQueryClient,
  type UseQueryOptions,
} from '@tanstack/react-query';
