/**
 * What this application is called, and where its API lives.
 *
 * The only file in the front end that a model changes. Everything else — every
 * screen, hook and provider — is the same code in every generated application
 * and imports its identity from here.
 *
 * That is not a tidiness point. Before this file existed, twenty components were
 * Handlebars templates because each carried a project name in a heading or a
 * comment, which meant none of them could be type-checked, linted or opened in
 * an editor that understood TSX: a broken component was found by a person
 * running the generated application, not by `tsc`. Substituting one constant
 * instead of twenty files buys all of that back.
 */

export const APP_NAME = "{{project.name}}";
export const APP_VERSION = "{{project.version}}";
export const APP_DESCRIPTION = "{{project.description}}";

/** The NestJS backend, as reached from the browser. */
export const BACKEND_PORT = {{config.backendPort}};
export const BACKEND_URL = "{{config.baseUrl}}";

/**
 * The accounts the seed creates, so the sign-in screen can offer them.
 *
 * A generated application seeds one account per functional role, and an
 * administrator who bypasses every restriction the model wrote. Listing only
 * the administrator — or listing nothing, which is what this screen did — means
 * the access control the model declared can be read in the seed and never seen
 * in the application.
 *
 * This is demonstration data. `SEEDED_PASSWORD` is what
 * `seeds/00_users_and_roles.ts` writes for every one of them, and the seed says
 * so at the top: change it before the application runs anywhere real, at which
 * point these accounts stop existing and the list empties itself.
 */
export interface SeededAccount {
  email: string;
  role: string;
  isAdmin: boolean;
  /** How many entities this role may read; equal to the total for an admin. */
  entities: number;
}

export const SEEDED_PASSWORD = "admin123";
export const TOTAL_ENTITIES = {{entities.length}};

/**
 * The entities that are line items of another (`%%entity … parent:`). They are
 * counted in `TOTAL_ENTITIES` and in each role's `entities`, but have no card or
 * sidebar entry of their own: they open as a tab of their parent. The sign-in
 * screen says so, because its count and the sidebar's would otherwise disagree.
 */
export const LINE_ITEM_ENTITIES: string[] = [{{#each entities}}{{#if this.parentEntity}}"{{this.name}}", {{/if}}{{/each}}];

export const SEEDED_ACCOUNTS: SeededAccount[] = [
{{#each access.users}}
  {
    email: "{{this.email}}",
    role: "{{this.roleName}}",
    isAdmin: {{#if this.isAdmin}}true{{else}}false{{/if}},
    entities: {{lookup ../access.entityCounts this.roleName}},
  },
{{/each}}
];

/** True when the model restricted `read`, so the counts above differ. */
export const ACCESS_IS_SCOPED = {{#if access.scoped}}true{{else}}false{{/if}};

/**
 * Which theme this application starts in before anyone has chosen one.
 *
 * `--dark-mode` at generation time used to put `className="dark"` on `<html>`
 * and that was the end of it: the application was dark, permanently, and no
 * reader of it could ask for anything else. The flag now names the *default*,
 * and the reader's own choice — stored per browser, applied before first paint
 * — outranks it.
 *
 * `"system"` is the third value the reader can pick; a generated default is
 * only ever one of the two explicit ones, because a flag that said "follow the
 * machine" would make `--dark-mode` mean nothing on a light machine.
 */
export const DEFAULT_THEME = "{{#if config.enableDarkMode}}dark{{else}}light{{/if}}";

