function formatEntity(name: string): string {
  return name
    .replace(/^bus_/, '')
    .split('_')
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
}

function AdminWorkflowsPage() {
  const [searchQuery, setSearchQuery] = useState('');
