          )}
          {step.props['updateField'] && (
            <div>
              <span className="text-xs uppercase tracking-widest text-muted-foreground/70 block mb-0.5">Field</span>
              <code className="font-mono text-foreground">{step.props['updateField']}</code>
            </div>
          )}
