  const [errors, setErrors] = useState<Record<string, string>>({});

  const { data: rule, isLoading } = useQuery({
    queryKey: ["admin", "rules", id],
    queryFn: async () => {
      return await apiClient.get<Rule>(`/rules/${id}`);
