})

/**
 * The application shell, or nothing, depending on where you are.
 *
 * `AppLayout` carries the sidebar, the header and the sign-in redirect, and it
 * must not wrap the sign-in screen itself: that page has no session by
 * definition, so the redirect inside the layout would bounce it back to
 * itself. Keying on the path rather than moving every route under a pathless
 * `_authed` layout keeps the route tree — and therefore every generated route
 * file — untouched.
 *
 * `/auth/*` is the whole of the unauthenticated surface. `/` is not listed
 * because it redirects to `/dashboard` in `beforeLoad` and never renders.
 */
function AppChrome() {
  const { pathname } = useLocation();

  if (pathname.startsWith('/auth/')) {
    return (
      <main className="min-h-screen bg-background">
        <Outlet />
      </main>
    );
  }

  return (
    <AppLayout>
      <Outlet />
    </AppLayout>
  );
}

function RootLayout() {
  return (
    // `suppressHydrationWarning` because the boot script below has already put
    // `class="dark"` and `style="color-scheme:dark"` on this element by the
    // time React hydrates, and the server had no way to know it would. The
    // alternative is not a clean tree — it is applying the theme one paint
    // late, which is a white flash on every load of a dark application.
    <html lang="en" suppressHydrationWarning>
      <head>
        <title>{{project.name}}</title>
        <meta name="description" content="{{project.description}}" />
        {/* Before the stylesheet paints anything, and before any module has
            loaded. This is the only reason the theme does not flash. */}
        <ThemeBootScript />
        <Meta />
      </head>
      <body className="font-sans antialiased">
        <Providers>
          <AppChrome />
        </Providers>
        {/* No Toaster here: `ClientToaster` in the providers is the one. A
            second one drew every toast twice and made React warn when a toast
            closed, because sonner's dismiss reaches every mounted Toaster. */}
        <Scripts />
      </body>
    </html>
  )
}

