// unusable in a browser while the backend is perfectly healthy.
//
// Two calls over one shared, non-exported handlers object satisfies both: each
// export is a direct CallExpression, and neither reads the other.
export const Route = createAPIFileRoute('/api/$')(handlers)
export const APIRoute = createAPIFileRoute('/api/$')(handlers)

/**
 * The assistant's sub-paths.
 *
 * The runtime itself lives in src/lib/copilot-runtime.ts, and the address the
 * client actually posts to — /api/copilotkit, with nothing after it — is served
