/**
 * Dictionary Write Guard — reading the Application Dictionary is for everyone,
 * changing it is for administrators.
 *
 * The `/sys` controller carries `RolesGuard` but almost no `@Roles`, and
 * `RolesGuard` allows anything with no roles declared. The result was that a
 * signed-in user with no privileges could `PATCH /sys/fields/:id` or
 * `DELETE /sys/tables/:id` — and because every screen in a generated
 * application is drawn from those rows rather than from page code, editing them
 * changes what every other user sees. One ordinary account could hide a column
 * from the whole company.
 *
 * The split is not "lock the controller": ordinary screens genuinely need to
 * read the dictionary. `use-entities.ts` calls `/sys/tables`, `/sys/fields/form`
 * and `/sys/fields/grid` to render a list or a form at all, so gating reads
 * would leave a non-admin looking at empty pages. Only the writes are
 * administrative, which is the same line the frontend already draws by calling
 * reads from hooks and writes from `components/admin/*`.
 *
 * Method-based rather than a decorator on each route, deliberately: there are
 * twenty-eight write routes today and a new one added later would otherwise be
 * open by default. Here the default is closed and a route has to be a GET to be
 * public.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import {
  CanActivate,
  ExecutionContext,
  ForbiddenException,
  Inject,
  Injectable,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { IS_PUBLIC_KEY } from '../decorators/public.decorator';

/** Verbs that only read. Everything else changes the dictionary. */
const READ_METHODS = new Set(['GET', 'HEAD', 'OPTIONS']);

/** Roles allowed to change the dictionary, beyond a master role. */
const ADMIN_ROLES = ['admin', 'administrator'];

@Injectable()
export class DictionaryWriteGuard implements CanActivate {
  constructor(@Inject(Reflector) private readonly reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) return true;

    const request = context.switchToHttp().getRequest();
    if (READ_METHODS.has(String(request.method).toUpperCase())) return true;

    const user = request.user ?? {};
    if (user.isMaster === true) return true;

    // Every place a role can arrive, matched case-insensitively — the seeded
    // role is `Administrator`, Better Auth's field says `admin`.
    const held = new Set<string>();
    for (const value of [...(user.sysRoles ?? []), ...(user.roles ?? [])]) {
      if (typeof value === 'string' && value) held.add(value.toLowerCase());
    }
    if (typeof user.role === 'string' && user.role) held.add(user.role.toLowerCase());

    if (ADMIN_ROLES.some((role) => held.has(role))) return true;

    throw new ForbiddenException(
      'Changing the Application Dictionary requires an administrator. ' +
        `Your roles: ${[...held].join(', ') || 'none'}.`,
    );
  }
}

/**
 * Roles Guard - Role-Based Access Control
 *
 * Enforces role-based access control for protected routes.
 * Works in conjunction with SessionAuthGuard (must be applied first).
 *
 * Usage:
 * @Roles('admin', 'doctor')
 * @UseGuards(SessionAuthGuard, RolesGuard)
 * async getPatients() { ... }
 */

import { Injectable, CanActivate, ExecutionContext, ForbiddenException, Inject } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ROLES_KEY } from '../decorators/roles.decorator';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(@Inject(Reflector) private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    // Get required roles from decorator metadata
    const requiredRoles = this.reflector.getAllAndOverride<string[]>(ROLES_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    // If no roles required, allow access
    if (!requiredRoles || requiredRoles.length === 0) {
      return true;
    }

    // Get user from request (set by SessionAuthGuard)
    const request = context.switchToHttp().getRequest();
    const user = request.user;

    if (!user) {
      throw new ForbiddenException('User not authenticated. Please sign in.');
    }

    // Collect roles from every source a caller can arrive with:
    // - user.sysRoles: application roles read out of sys_user_roles by
    //   SessionAuthGuard. This is the field that guard actually sets; this
    //   guard read `user.roles`, which nothing ever populated, so a user whose
    //   only roles came from sys_user_roles was refused by every @Roles()
    //   endpoint no matter what roles they held.
    // - user.roles: kept for any caller enriched by other middleware.
    // - user.role: BetterAuth's own role field ('admin', 'user', etc.).
    const userRoles: string[] = [];
    for (const value of [...(user.sysRoles || []), ...(user.roles || [])]) {
      if (typeof value === 'string' && value && !userRoles.includes(value)) {
        userRoles.push(value);
      }
    }
    if (user.role && !userRoles.includes(user.role)) {
      userRoles.push(user.role);
    }

    // A master role is the dictionary's administrator escape hatch; it would be
    // surprising for it to hold everywhere except here.
    if (user.isMaster === true) {
      return true;
    }

    // Check if user has any of the required roles
    // Case-insensitive: the seeded role is `Administrator` and a decorator
    // writes `admin`/`administrator`. Matching exactly refuses a user who holds
    // precisely the role the endpoint asks for, which is the failure this guard
    // exists to prevent.
    const held = new Set(userRoles.map((role) => role.toLowerCase()));
    const hasRole = requiredRoles.some((role) => held.has(role.toLowerCase()));

    if (!hasRole) {
      throw new ForbiddenException(
        `Access denied. Required roles: ${requiredRoles.join(', ')}. Your roles: ${userRoles.join(', ') || 'none'}.`
      );
    }

    return true;
  }
}

/**
 * JWT Auth Guard - BetterAuth Integration
 *
 * Protects routes by validating session tokens from BetterAuth
 *
 * Generated: {{now}}
 */

import { Injectable, CanActivate, ExecutionContext, UnauthorizedException, Inject } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { getAuth } from '../../../lib/better-auth';
import { IS_PUBLIC_KEY } from '../decorators/public.decorator';
import { setRequestContext } from '../../../common/logging/logger.service';

@Injectable()
export class JwtAuthGuard implements CanActivate {
  constructor(@Inject(Reflector) private readonly reflector: Reflector) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    // Check if route is marked as public
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    if (isPublic) {
      return true;
    }

    const request = context.switchToHttp().getRequest();
    const headers = request.headers;

    try {
      const auth = getAuth();
      const session = await auth.api.getSession({
        headers,
      });

      if (!session) {
        throw new UnauthorizedException('Invalid or expired session');
      }

      // Attach user and session to request
      request.user = session.user;
      setRequestContext({
        userId: (session.user as any)?.sys_user_id ?? (session.user as any)?.id ?? null,
        // The identity the audit trail is keyed on — see RequestContext.actor.
        actor: {
          id: (session.user as any)?.id ?? null,
          name: (session.user as any)?.name ?? null,
          email: (session.user as any)?.email ?? null,
          sessionId: (session as any)?.session?.id ?? null,
        },
      });
      request.session = session;

      return true;
    } catch (error) {
      throw new UnauthorizedException('Authentication failed');
    }
  }
}

/**
 * Session Auth Guard - BetterAuth Integration
 *
 * Protects routes by validating session tokens from BetterAuth.
 * Replaces JWT-based authentication with session-based auth.
 *
 * This guard extracts the session token from cookies or Authorization header
 * and validates it against BetterAuth's session store.
 */

import { Injectable, CanActivate, ExecutionContext, UnauthorizedException, ServiceUnavailableException, Logger, Inject, Optional } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { getAuth } from '../../../lib/better-auth';
import { IS_PUBLIC_KEY } from '../decorators/public.decorator';
import { DatabaseService } from '../../../database/database.service';
import { setRequestContext } from '../../../common/logging/logger.service';
import { CapabilityService } from '../capability.service';

@Injectable()
export class SessionAuthGuard implements CanActivate {
  private readonly logger = new Logger(SessionAuthGuard.name);

  constructor(
    @Inject(Reflector) private reflector: Reflector,
    @Optional() private readonly db?: DatabaseService,
    @Optional() private readonly capabilities?: CapabilityService,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    if (isPublic) return true;

    const request = context.switchToHttp().getRequest();

    try {
      const auth = getAuth();
      const session = await auth.api.getSession({ headers: request.headers });

      if (!session) {
        throw new UnauthorizedException('Invalid or expired session. Please sign in again.');
      }

      // Attach base user from Better Auth
      request.user = { ...session.user };

      // Every line logged for the rest of this request now says who caused it,
      // without the rules engine or the entity service having to be handed a
      // user they have no other use for.
      setRequestContext({
        userId: (session.user as any)?.sys_user_id ?? (session.user as any)?.id ?? null,
        // The identity the audit trail is keyed on — see RequestContext.actor.
        actor: {
          id: (session.user as any)?.id ?? null,
          name: (session.user as any)?.name ?? null,
          email: (session.user as any)?.email ?? null,
          sessionId: (session as any)?.session?.id ?? null,
        },
      });
      request.session = session;

      // Everything the user's roles grant, in one query through
      // sys_user_capability and cached per user (CapabilityService). The guards
      // after this one — entity access, the moves — only look it up.
      const sysUserId = session.user.sysUserId as string | undefined;
      // A deactivated or deleted account is refused here, on every request —
      // not when its session cookie next goes back to the database.
      if (sysUserId && this.capabilities && !(await this.capabilities.isActive(sysUserId))) {
        throw new UnauthorizedException('This account has been deactivated.');
      }
      if (this.capabilities) {
        try {
          const capabilities = await this.capabilities.forUser({
            sysUserId,
            id: (session.user as any)?.id ?? null,
            roles: (session.user as any)?.roles,
            role: (session.user as any)?.role,
          });
          request.capabilities = capabilities;
          request.user.sysRoles = capabilities.roles;
          request.user.isMaster = capabilities.isMaster;
        } catch (error) {
          // Not knowing what a user may do is not the same as their holding
          // nothing: the access guard refuses on a missing answer.
          this.logger.error(
            `Could not read the caller's access: ${error instanceof Error ? error.message : String(error)}`
          );
        }
      } else if (sysUserId && this.db) {
        try {
          const roles = await this.db.kysely
            .selectFrom('sys_user_roles as ur')
            .innerJoin('sys_role as r', 'r.sys_role_id', 'ur.sys_role_id')
            .select(['r.name as role_name', 'r.is_master_role'])
            .where('ur.sys_user_id', '=', sysUserId)
            .where('ur.is_active', '=', true)
            .execute();
          request.user.sysRoles = roles.map((r: any) => r.role_name);
          request.user.isMaster = roles.some((r: any) => r.is_master_role);
        } catch {
          // non-fatal — proceed without enrichment
        }
      }

      this.logger.debug(`User authenticated: ${session.user.email}`);
      return true;
    } catch (error) {
      if (error instanceof UnauthorizedException) throw error;
      // Not being able to *check* a session says nothing about whether it is valid. A 401 here
      // — a database that was busy, a connection that dropped — tells the front end to sign the
      // person out, and every screen they had open bounces to the sign-in page for a fault that
      // was never theirs. Say the service could not answer, and let the request be retried.
      this.logger.error(
        `Could not check the session: ${error instanceof Error ? error.message : String(error)}`
      );
      throw new ServiceUnavailableException('Could not check your session. Try again.');
    }
  }
}

/**
 * Entity Access Guard — enforces the model's `%%rbac` directives.
 *
 * Runs after SessionAuthGuard, which is what puts the caller's capabilities on
 * the request — every grant of every role they hold, read in one query through
 * `sys_user_capability` and cached (CapabilityService). For each call naming an
 * entity it asks one question: does some grant close this (table, operation)
 * pair, and if so does the caller hold it? It also holds two things that are
 * the model's shape rather than anyone's access: a record's state moves only by
 * its action buttons, and a Final record is locked.
 *
 * ## It is not only /bus
 *
 * Any route carrying the entity in its path is covered, because a read
 * restriction that a sibling route ignores is not a restriction. Denying
 * `Customer.read` on /bus while /workflows/entity/Customer/:id still returns
 * that customer's history — old and new values of every field it touched — is
 * the restriction being bypassed by changing the URL. The parameter is spelled
 * `entity` on the bus routes and `entityName` on the workflow routes, so both
 * are read.
 *
 * ## Open unless closed
 *
 * A pair with no rows is unrestricted. This is what makes `%%rbac` additive:
 * an application generated from a model that declares none behaves exactly as
 * it did before this guard existed. Denying by default would lock every user
 * out of every existing model on the next regeneration.
 *
 * ## Role names are matched case-insensitively
 *
 * The seeded roles are title-cased (`Manager`, `Administrator`) and a model
 * author writes `%%rbac role:manager`. Matching exactly would make that
 * directive unsatisfiable — a restriction that locks out precisely the people
 * it was written to admit, which is worse than no restriction at all, and
 * invisible until someone is refused. Role names are names, not identifiers;
 * nothing distinguishes `manager` from `Manager`. The grants keep the author's
 * spelling so the admin UI shows what was written; the comparison is on
 * `role_key`, which the database folds (case, and `_`/`-`/space as one
 * separator) on both sides of the join.
 *
 * ## The table name must match the service's
 *
 * The rules are stored against physical table names (`bus_order`), and the URL
 * carries whatever the client wrote — `order`, `orders`, `bus_order`. If this
 * guard normalised differently from `BusService.getTableName`, a request for
 * the plural would resolve to a table with no rules here and to the real table
 * there, and the restriction would be bypassed by pluralising a URL. The
 * normalisation below is therefore a deliberate copy of that method, and the
 * two must be changed together.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import {
  CanActivate,
  ConflictException,
  ExecutionContext,
  ForbiddenException,
  Inject,
  Injectable,
  Logger,
  Optional,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { DatabaseService } from '../../../database/database.service';
import { IS_PUBLIC_KEY } from '../decorators/public.decorator';
import { getLogger } from '../../../common/logging/logger.service';
import { STATE_FIELD_REFUSAL_CODE, stateFieldOf } from '../../../common/state-fields';
import { isLocked, lifecycleOf } from '../../../common/lifecycle';
import { CapabilityService, type Capabilities } from '../capability.service';

/** `details.code` of the 409 a write to a Final record receives. */
export const RECORD_FINAL_CODE = 'RECORD_FINAL';

type Operation = 'create' | 'read' | 'update' | 'delete';

/** HTTP verb → the operation a `%%rbac` directive names. */
const METHOD_OPERATION: Record<string, Operation> = {
  GET: 'read',
  HEAD: 'read',
  POST: 'create',
  PUT: 'update',
  PATCH: 'update',
  DELETE: 'delete',
};

@Injectable()
export class EntityAccessGuard implements CanActivate {
  private readonly logger = new Logger(EntityAccessGuard.name);

  constructor(
    @Inject(Reflector) private readonly reflector: Reflector,
    @Optional() private readonly db?: DatabaseService,
    @Optional() private readonly capabilities?: CapabilityService,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) return true;

    /*
     * No database wired means the rules cannot be read — which is not the same
     * as there being none, and used to be treated as if it were.
     *
     * "Open unless closed" is the deliberate design for a table with *no rows*:
     * it is what makes `%%rbac` additive, and an application generated from a
     * model that declares none behaves as it did before this guard existed.
     * That reasoning is about an answered question with an empty answer. It
     * does not extend to an unanswered one.
     *
     * So a missing database is refused rather than waved through. It is a
     * misconfiguration at startup, not a per-request condition to degrade
     * around, and the previous behaviour meant one unwired dependency silently
     * disabled every entity restriction in the application.
     */
    if (!this.db) {
      this.logger.error(
        'EntityAccessGuard has no DatabaseService, so %%rbac rules cannot be read. ' +
          'Refusing rather than allowing — check the module wiring.',
      );
      throw new ForbiddenException(
        'Access rules are unavailable. This is a server misconfiguration, not a permission you lack.',
      );
    }

    const request = context.switchToHttp().getRequest();
    const entity: string | undefined = request.params?.entity ?? request.params?.entityName;
    if (!entity) return true;

    const operation = this.operationOf(request);
    if (!operation) return true;

    const tableName = this.getTableName(entity);

    // What the caller's roles grant: put on the request by SessionAuthGuard from
    // one query through sys_user_capability, cached per user. Read here, never
    // queried — the decision is set membership.
    let capabilities: Capabilities | undefined = request.capabilities;
    try {
      if (!capabilities && this.capabilities) {
        capabilities = await this.capabilities.forUser(request.user ?? {});
      }
    } catch (error: any) {
      capabilities = undefined;
      this.logger.error(`Could not read the caller's access: ${error?.message ?? error}`);
    }
    if (!capabilities || !this.capabilities) {
      // An access decision that cannot be made is a refusal.
      throw new ForbiddenException(
        'Access rules could not be read, so the request was refused. Please retry.',
      );
    }

    // A master role is the administrator escape hatch the dictionary already
    // recognises (CapabilityService.decide). It is an escape hatch from *access*
    // rules, not from the model's own shape: the state field and the Final lock
    // below hold for everyone.
    const decision = await this.capabilities.decide(capabilities, 'op', tableName, operation);
    if (!decision.allowed) {
      getLogger('auth').event('auth.access.denied', {
        resource: tableName,
        operation,
        requiredRoles: decision.roles,
      });
      throw new ForbiddenException(
        `Access denied. "${operation}" on "${tableName}" requires one of: ` +
          `${decision.roles.join(', ')}. Your roles: ${capabilities.roles.join(', ') || 'none'}.`,
      );
    }

    // A state field is system-managed: whoever is calling, a person never
    // writes it. Checked after the operation rule, because a caller refused the
    // write outright never gets this far.
    if (operation === 'create' || operation === 'update') {
      await this.checkStateFieldWrite(request, tableName, operation);
    }

    // The end of a flow is Final: such a record is neither edited nor deleted.
    // Reopen (POST …/transition) is the way back, so only a record write is
    // held here. A record with no flow is never locked — saving it is how it changes.
    const method = String(request.method).toUpperCase();
    if (['PUT', 'PATCH', 'DELETE'].includes(method)) {
      await this.checkFinalLock(request, tableName);
    }

    return true;
  }

  /**
   * POST is a create, except on a record's own routes. Re-running the save
   * pipeline (`…/:id/promote`) changes a record, so it needs update. Pressing a
   * move (`…/:id/transition`) needs the record to be visible here, and the
   * move's own grant in TransitionService: a role granted `close_won` may press
   * it without being allowed to edit the record, and a move no grant names falls
   * back to update permission there.
   */
  private operationOf(request: any): Operation | undefined {
    const method = String(request.method).toUpperCase();
    const url = String(request.url ?? '');
    if (method === 'POST' && request.params?.id) {
      if (/\/transition(\?|$)/.test(url)) return 'read';
      if (/\/promote(\?|$)/.test(url)) return 'update';
    }
    return METHOD_OPERATION[method];
  }

  /** 409 RECORD_FINAL on a write to a record at the end of its flow. */
  private async checkFinalLock(request: any, tableName: string): Promise<void> {
    if (!String(request.url ?? '').includes('/bus/') || !request.params?.id) return;
    const lifecycle = lifecycleOf(tableName);
    if (!lifecycle) return;
    let current: Record<string, any> | undefined;
    try {
      current = await this.db!.kysely
        .selectFrom(tableName as any)
        .select([lifecycle.column] as any)
        .where('id' as any, '=', request.params.id)
        .executeTakeFirst();
    } catch (error: any) {
      this.logger.warn(
        `Could not read the lifecycle of ${tableName}/${request.params.id}: ${error?.message ?? error}`,
      );
      return;
    }
    if (!current || !isLocked(lifecycle, current[lifecycle.column])) return;
    throw new ConflictException({
      message:
        'This record is Final and cannot be changed. Reopen it to make changes — ' +
        'an administrator, or a role allowed to reopen it, can.',
      error: 'Conflict',
      details: {
        code: RECORD_FINAL_CODE,
        entity: tableName,
        id: request.params.id,
        state: current[lifecycle.column],
      },
    });
  }

  /**
   * Keep a person's request from changing a record's state.
   *
   * A state field — the column an entity's `kind: state` machine drives — is
   * changed only by background workflows: a saga's UpdateEntity step, a rule
   * that starts one, a hook, the application's own code. None of those passes
   * through this guard, so anything that arrives here is a person's request,
   * and the master role is no exception: the rule is about who writes a state,
   * not about who is allowed to.
   *
   *   create   the value is dropped; the bus service starts the record in its
   *            machine's initial state
   *   update   a value equal to the stored one is dropped, so a form or a
   *            client that sends the whole record back still saves; any other
   *            value is refused with 403 and `STATE_FIELD_SYSTEM_MANAGED`
   *
   * A person moves a record by pressing one of its moves — POST
   * `/bus/:entity/:id/transition`, which checks the edge, the role and the
   * record's rules (TransitionService) — never by writing the column.
   */
  private async checkStateFieldWrite(
    request: any,
    tableName: string,
    operation: 'create' | 'update',
  ): Promise<void> {
    // Only /bus writes carry a record body; the workflow routes name an entity
    // too, and their bodies are not records.
    if (!String(request.url ?? '').includes('/bus/')) return;
    const body = request.body;
    if (!body || typeof body !== 'object' || Array.isArray(body)) return;

    const state = stateFieldOf(tableName);
    if (!state || !(state.field in body)) return;

    if (operation === 'create' || !request.params?.id) {
      delete body[state.field];
      return;
    }

    let current: Record<string, any> | undefined;
    try {
      current = await this.db!.kysely
        .selectFrom(tableName as any)
        .select([state.field] as any)
        .where('id' as any, '=', request.params.id)
        .executeTakeFirst();
    } catch (error: any) {
      this.logger.warn(
        `Could not read the state of ${tableName}/${request.params.id}: ${error?.message ?? error}`,
      );
      current = undefined;
    }

    const stored = current ? String(current[state.field] ?? '') : undefined;
    const sent = String(body[state.field] ?? '');
    if (stored !== undefined && stored === sent) {
      delete body[state.field];
      return;
    }

    getLogger('workflow').event('workflow.transition.refused', {
      entity: tableName,
      recordId: request.params.id,
      statusField: state.field,
      from: stored ?? null,
      to: sent,
      reason: 'system-managed',
    });
    throw new ForbiddenException({
      message:
        `"${state.field}" on "${tableName}" is changed only by the record's moves, ` +
        `never through a form. Use one of the record's action buttons (POST …/transition).`,
      error: 'Forbidden',
      details: {
        code: STATE_FIELD_REFUSAL_CODE,
        entity: tableName,
        field: state.field,
        current: stored ?? null,
      },
    });
  }

  /** Deliberate copy of BusService.getTableName — see the note at the top. */
  /**
   * The tables the model declares. A bare name that is already one of them is
   * not a plural: `dangerous_goods` is a table, and singularizing it to
   * `dangerous_good` pointed the list, the form and the access check at a table
   * that does not exist.
   */
  private static readonly MODEL_TABLES = new Set<string>([
{{#each entities}}
    '{{tableName}}',
{{/each}}
  ]);

  private getTableName(entity: string): string {
    const normalized = entity.toLowerCase().replace(/-/g, '_');
    if (normalized.startsWith('bus_')) return normalized;
    if (EntityAccessGuard.MODEL_TABLES.has(`bus_${normalized}`)) return `bus_${normalized}`;
    return `bus_${this.singularize(normalized)}`;
  }

  private singularize(word: string): string {
    if (word.endsWith('ies')) return word.slice(0, -3) + 'y';
    if (
      word.endsWith('ses') ||
      word.endsWith('xes') ||
      word.endsWith('zes') ||
      word.endsWith('ches') ||
      word.endsWith('shes')
    ) {
      return word.slice(0, -2);
    }
    if (word.endsWith('s') && !word.endsWith('ss')) return word.slice(0, -1);
    return word;
  }
}

import { Controller, Get, Param, ParseUUIDPipe, Query, UseGuards } from "@nestjs/common";
import { ApiBearerAuth, ApiOperation, ApiTags } from "@nestjs/swagger";
import { Roles } from "../auth/decorators/roles.decorator";
import { RolesGuard } from "../auth/guards/roles.guard";
import { SessionAuthGuard } from "../auth/guards/session-auth.guard";
import { AuditService } from "./audit.service";
import type { AuditSearchParams, AuditSource } from "./audit.types";

@ApiTags("audit")
@ApiBearerAuth()
// The audit trail is administrative. It had SessionAuthGuard alone, so any
// signed-in account could page through every mutation in the application —
// including the old and new value of each changed field, which is the record
// contents of every table regardless of who may read those tables. Filtering it
// per caller would mean row-level rules the model has no way to express; the
// surface is reached from /admin/audit in the UI, so an administrator gate is
// the honest boundary.
@UseGuards(SessionAuthGuard, RolesGuard)
@Roles("admin", "administrator")
@Controller("audit")
export class AuditController {
  constructor(private readonly auditService: AuditService) {}

  @Get()
  @ApiOperation({ summary: "Search and filter audit log" })
  async search(
    @Query('page') page?: string,
    @Query('limit') limit?: string,
    @Query('from') from?: string,
    @Query('to') to?: string,
    @Query('user_id') user_id?: string,
    @Query('user_email') user_email?: string,
    @Query('action') action?: string,
    @Query('entity_type') entity_type?: string,
    @Query('entity_id') entity_id?: string,
    @Query('source') source?: string,
    @Query('success') success?: string,
    @Query('search') search?: string
  ) {
    const params: AuditSearchParams = {
      page: page ? parseInt(page, 10) : 1,
      limit: limit ? Math.min(500, parseInt(limit, 10)) : 50,
      from,
      to,
      user_id: user_id || undefined,
      user_email: user_email || undefined,
      action: action || undefined,
      entity_type: entity_type || undefined,
      entity_id: entity_id || undefined,
      source: source as AuditSource | undefined,
      success: success === "true" ? true : success === "false" ? false : undefined,
      search: search || undefined,
    };
    return this.auditService.search(params);
  }

  @Get("entity-types")
  @ApiOperation({ summary: "List distinct entity types in audit log" })
  async getEntityTypes() {
    return this.auditService.getEntityTypes();
  }

  @Get(':id/verify')
  @ApiOperation({ summary: 'Verify an audit record against immudb (tamper check)' })
  async verify(@Param('id', ParseUUIDPipe) id: string) {
    return this.auditService.verify(id);
  }
}

import { Injectable, Logger, type OnModuleDestroy, type OnModuleInit } from "@nestjs/common";
import { ConfigService } from "@nestjs/config";

interface ImmudbVerifyResult {
  key: string;
  value: string;
  txId: string | number;
  verified: boolean;
}

interface ImmudbScanEntry {
  key: string;
  value: string;
}

/**
 * immudb client wrapper.
 *
 * Uses immudb-node (gRPC client). Falls back to no-op when
 * IMMUDB_ENABLED=false so the app runs without immudb in dev/CI.
 */
@Injectable()
export class ImmudbService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(ImmudbService.name);
  private client: any = null;
  private enabled: boolean;

  constructor(private readonly config: ConfigService) {
    this.enabled = config.get<string>("IMMUDB_ENABLED", "true") !== "false";
  }

  async onModuleInit(): Promise<void> {
    if (!this.enabled) {
      this.logger.warn(
        "immudb disabled via IMMUDB_ENABLED=false — audit writes go to PostgreSQL only"
      );
      return;
    }

    try {
      // immudb-node is an optional dependency. The specifier is held in a
      // variable so TypeScript does not try to resolve it: a literal needs a
      // suppression comment, and that comment is itself an error once the
      // package *is* installed, so the project failed to compile either way.
      const moduleName = "immudb-node";
      const ImmudbClient = (await import(moduleName)).default;

      const host = this.config.get<string>("IMMUDB_HOST", "127.0.0.1");
      const port = this.config.get<number>("IMMUDB_PORT", 8088);

      this.client = new ImmudbClient({ host, port, rootPath: "/tmp/immudb-root" });

      await this.client.login({
        user: this.config.get<string>("IMMUDB_USER", "immudb"),
        password: this.config.get<string>("IMMUDB_PASSWORD", "immudb"),
      });

      const db = this.config.get<string>("IMMUDB_DATABASE", "defaultdb");
      await this.client.useDatabase({ databasename: db }).catch(() => {
        // Database may already be selected; ignore
      });

      this.logger.log(`immudb connected at ${host}:${port} (db: ${db})`);
    } catch (err) {
      this.logger.error(
        `immudb connection failed: ${err instanceof Error ? err.message : String(err)}`
      );
      this.logger.warn(
        "Continuing without immudb — set IMMUDB_ENABLED=false to suppress this warning"
      );
      this.client = null;
    }
  }

  async onModuleDestroy(): Promise<void> {
    if (this.client) {
      try {
        await this.client.logout();
      } catch {
        // Ignore logout errors on shutdown
      }
    }
  }

  get isConnected(): boolean {
    return this.client !== null;
  }

  /**
   * Write a key-value pair with cryptographic verification.
   * Returns the immudb transaction ID (or key if tx unavailable).
   */
  async verifiedSet(key: string, value: string): Promise<string> {
    if (!this.client) return key;
    try {
      const result = await this.client.verifiedSet({ key, value });
      return String(result?.id ?? result?.index ?? key);
    } catch (err) {
      this.logger.error(
        `immudb verifiedSet failed for key ${key}: ${err instanceof Error ? err.message : String(err)}`
      );
      return key;
    }
  }

  /**
   * Read and verify a key. Returns null when key not found or immudb unavailable.
   */
  async verifiedGet(key: string): Promise<ImmudbVerifyResult | null> {
    if (!this.client) return null;
    try {
      const result = await this.client.verifiedGet({ key });
      return {
        key: result.key ?? key,
        value: result.value ?? "",
        txId: result.id ?? result.index ?? "",
        verified: true,
      };
    } catch (err: any) {
      if (err?.clientErr === "proof") {
        return { key, value: "", txId: "", verified: false };
      }
      this.logger.error(
        `immudb verifiedGet failed for key ${key}: ${err instanceof Error ? err.message : String(err)}`
      );
      return null;
    }
  }

  /**
   * Scan entries by prefix. Used to query audit events by time range.
   */
  async scan(prefix: string, limit = 100): Promise<ImmudbScanEntry[]> {
    if (!this.client) return [];
    try {
      const result = await this.client.scan({ seekKey: prefix, prefix, limit, desc: false });
      return (result?.entries ?? []).map((e: any) => ({ key: e.key, value: e.value }));
    } catch (err) {
      this.logger.error(`immudb scan failed: ${err instanceof Error ? err.message : String(err)}`);
      return [];
    }
  }
}

import {
  type CallHandler,
  type ExecutionContext,
  Injectable,
  Logger,
  type NestInterceptor,
} from "@nestjs/common";
import { type Observable, throwError } from "rxjs";
import { catchError, tap } from "rxjs/operators";
import { AuditService } from "./audit.service";
import type { AuditEvent, AuditSource } from "./audit.types";
import { diffFields } from "./audit.types";

/** Methods that mutate data. Always audited. */
const MUTATING_METHODS = new Set(["POST", "PUT", "PATCH", "DELETE"]);

/**
 * Audit reads as well as writes.
 *
 * Off by default: every list and detail view would land in the table, and on a
 * busy app the reads bury the changes. Turn it on where the regime requires
 * proof of who looked at what (GxP, HIPAA, SOX) and budget for the volume.
 */
const AUDIT_READS = process.env.AUDIT_READS === "true";

/**
 * What each API surface is, for the audit trail.
 *
 * Anything not listed is still audited under its first path segment — a new
 * module is recorded from the day it ships rather than silently missing until
 * someone remembers to add it here. Ordered longest-prefix first so
 * `/sys/roles` does not match as plain `sys`.
 */
const RESOURCES: Array<{ prefix: RegExp; resource: string; subject: string }> = [
  { prefix: /^\/?api\/auth\b/, resource: "auth", subject: "AUTH" },
  { prefix: /^\/?bus\/([^/?]+)/, resource: "", subject: "ENTITY" },
  { prefix: /^\/?sys\/roles\b/, resource: "sys/roles", subject: "ROLE" },
  { prefix: /^\/?sys\/user-roles\b/, resource: "sys/user-roles", subject: "ROLE_ASSIGNMENT" },
  { prefix: /^\/?sys\/users\b/, resource: "sys/users", subject: "USER" },
  { prefix: /^\/?sys\/access\b/, resource: "sys/access", subject: "PERMISSION" },
  { prefix: /^\/?sys\b/, resource: "sys", subject: "DICTIONARY" },
  { prefix: /^\/?rules\b/, resource: "rules", subject: "RULE" },
  { prefix: /^\/?workflow-definitions\b/, resource: "workflow-definitions", subject: "WORKFLOW" },
  { prefix: /^\/?workflows\b/, resource: "workflows", subject: "WORKFLOW_RUN" },
  { prefix: /^\/?jobs\b/, resource: "jobs", subject: "JOB" },
  { prefix: /^\/?api\/ai\b/, resource: "api/ai", subject: "AI" },
  { prefix: /^\/?me\b/, resource: "me", subject: "PROFILE" },
];

/** Paths that would audit themselves into a loop, or say nothing worth keeping. */
const IGNORED = [/^\/?audit\b/, /^\/?health\b/, /^\/?v1\/shape\b/, /^\/?favicon/];

/** Verb suffix for an action name. */
function verbFor(method: string): string {
  if (method === "DELETE") return "DELETE";
  if (method === "POST") return "CREATE";
  if (method === "PUT" || method === "PATCH") return "UPDATE";
  return "READ";
}

export interface AuditTarget {
  /** Recorded as `entity_type` — the thing acted on. */
  entityType: string;
  /** Recorded as `action`, e.g. `RULE_UPDATE`. */
  action: string;
}

/**
 * Classify a request into what the audit page shows.
 *
 * Returns null only for paths in IGNORED. Everything else is recorded: a trail
 * that quietly omits business rule edits, role grants or logins is not an audit
 * trail, and those were exactly the paths the old `/bus/` and `/sys/` match
 * dropped on the floor.
 */
export function classifyRequest(path: string, method: string): AuditTarget | null {
  const clean = (path.split("?")[0] ?? "").replace(/^\/api\//, "/");
  if (IGNORED.some((re) => re.test(clean))) return null;

  const verb = verbFor(method);

  for (const { prefix, resource, subject } of RESOURCES) {
    const match = clean.match(prefix);
    if (!match) continue;
    // `/bus/:entity` records the entity itself, so the trail reads
    // `bus_compound` rather than a uniform `bus`.
    const entityType = resource || match[1] || "bus";
    return { entityType, action: `${subject}_${verb}` };
  }

  // Unknown surface: record it under its first segment rather than lose it.
  const segment = clean.replace(/^\//, "").split("/")[0] || "root";
  return { entityType: segment, action: `${segment.toUpperCase().replace(/[^A-Z0-9]/g, "_")}_${verb}` };
}

function resolveEntityId(params: Record<string, string>): string | null {
  return params?.id ?? params?.entityId ?? null;
}

/**
 * Response envelope keys that describe the request rather than the record.
 * Bus mutations append a `promotion` report from the rules engine; leaving it in
 * makes every update look like it changed a `promotion` column that does not
 * exist, and stores a copy of the report in the audit trail.
 */
const ENVELOPE_KEYS = new Set(["promotion", "meta", "workflow", "rules"]);

/** Strip envelope keys so before/after hold the record and nothing else. */
function recordOnly(value: unknown): Record<string, unknown> | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
    if (!ENVELOPE_KEYS.has(k)) out[k] = v;
  }
  return out;
}

@Injectable()
export class AuditInterceptor implements NestInterceptor {
  private readonly logger = new Logger(AuditInterceptor.name);

  constructor(private readonly auditService: AuditService) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const http = context.switchToHttp();
    const req = http.getRequest();
    const method: string = req.method?.toUpperCase() ?? "";

    const mutating = MUTATING_METHODS.has(method);
    if (!mutating && !AUDIT_READS) return next.handle();

    const path: string = req.url ?? req.path ?? "";
    const target = classifyRequest(path, method);
    if (!target) return next.handle();

    const user = req.user;
    const params = req.params ?? {};
    const headers = req.headers ?? {};

    const base: Partial<AuditEvent> = {
      user_id: user?.id ?? null,
      user_name: user?.name ?? null,
      user_email: user?.email ?? null,
      session_id: req.session?.session?.id ?? null,
      entity_type: target.entityType,
      entity_id: resolveEntityId(params),
      action: target.action,
      ip_address:
        (headers["x-forwarded-for"] as string)?.split(",")[0]?.trim() ??
        req.socket?.remoteAddress ??
        null,
      user_agent: (headers["user-agent"] as string) ?? null,
      source: (headers["x-source"] as AuditSource) ?? "WEB_UI",
      request_id: (headers["x-request-id"] as string) ?? null,
    };

    return next.handle().pipe(
      tap((responseData: any) => {
        // Read __auditBefore here (after handler ran) — controller sets it before its mutation
        const beforeValue = recordOnly(req.__auditBefore);
        const after = recordOnly(responseData?.data ?? responseData);
        const changed = diffFields(beforeValue, after);
        // For POST (CREATE), extract entity_id from the response body
        const entityId = base.entity_id ?? (after?.id as string | undefined) ?? null;
        this.auditService.log({
          ...base,
          entity_id: entityId,
          before_value: beforeValue,
          after_value: method === "DELETE" ? null : after,
          changed_fields: changed,
          success: true,
        } as AuditEvent);
      }),
      catchError((err) => {
        const beforeValue = recordOnly(req.__auditBefore);
        this.auditService.log({
          ...base,
          before_value: beforeValue,
          after_value: null,
          changed_fields: [],
          success: false,
          error_message: err?.message ?? String(err),
        } as AuditEvent);
        return throwError(() => err);
      })
    );
  }
}

import { ForbiddenException, Inject, Injectable, Logger } from "@nestjs/common";
import { type Kysely, sql } from "kysely";
import { KYSELY_CONNECTION } from "../../database/database.constants";

/**
 * One record's history, and the notes people have left on it.
 *
 * Both surfaces are *per record* and both are scoped to the entity the record
 * belongs to, which is what separates them from `AuditController`. That
 * controller serves the whole log — every table, every sign-in attempt, the
 * before and after of every changed field — and is administrator-only for
 * exactly that reason. Narrowed to one record of one table, the same data is
 * simply what happened to something the caller is already looking at, so the
 * gate is the entity's own `read` rather than an admin role. A trail only
 * administrators can see is a trail nobody consults.
 *
 * Notes are kept in `sys_note` rather than in the audit log. The trail records
 * what the system observed and must not be editable; a note is somebody's
 * sentence about the same record. One table for both would make the history
 * writable, which is the one thing an audit trail may not be.
 */
@Injectable()
export class RecordHistoryService {
  private readonly logger = new Logger(RecordHistoryService.name);

  constructor(@Inject(KYSELY_CONNECTION) private readonly kysely: Kysely<any>) {}

  /**
   * Refuse unless the caller's roles may perform `operation` on the entity.
   *
   * Mirrors `EntityAccessGuard`: restrictions live in `sys_operation_access`, a
   * target with no rows is open to any authenticated caller, and a master role
   * bypasses. A failed lookup means "no rules" rather than "deny", so an
   * application whose database predates the table keeps serving.
   */
  async assertAccess(user: any, entity: string, operation: "read" | "update"): Promise<void> {
    const tableName = this.getTableName(entity);

    let allowedRoles: string[];
    try {
      const rows = await this.kysely
        .selectFrom("sys_operation_access")
        .select("role_name")
        .where("table_name", "=", tableName)
        .where("operation", "=", operation)
        .where("is_active", "=", true)
        .execute();
      allowedRoles = rows.map((row: any) => row.role_name);
    } catch (error: any) {
      this.logger.warn(
        `Operation access lookup failed for ${tableName}.${operation}: ${error?.message ?? error}`,
      );
      return;
    }

    if (allowedRoles.length === 0) return;
    if (user?.isMaster === true) return;

    const held = this.rolesOf(user);
    const heldFolded = new Set(held.map((role) => role.toLowerCase()));
    if (allowedRoles.some((role) => heldFolded.has(role.toLowerCase()))) return;

    throw new ForbiddenException(
      `Access denied. "${operation}" on "${tableName}" requires one of: ` +
        `${allowedRoles.join(", ")}. Your roles: ${held.join(", ") || "none"}.`,
    );
  }

  /**
   * What has been done to one record, newest first.
   *
   * `entity_type` in the log is the route segment the interceptor saw, so it is
   * matched against the segment rather than the table name — the two differ
   * (`invoice-line` against `bus_invoice_line`) and matching the wrong one
   * returns an empty trail for every record, forever, with nothing to say so.
   */
  async historyFor(entity: string, recordId: string, limit = 50) {
    const rows = await this.kysely
      .selectFrom("audit_log")
      .select([
        "id",
        "timestamp",
        "user_name",
        "user_email",
        "action",
        "changed_fields",
        "before_value",
        "after_value",
        "success",
        "error_message",
      ])
      .where("entity_type", "=", entity)
      .where("entity_id", "=", String(recordId))
      .orderBy("timestamp", "desc")
      .limit(limit)
      .execute();

    /* Column names, not a re-spelling of them. The one consumer is the trail at
       the foot of the record screen, which was written against `audit_log`; a
       second vocabulary here would buy nothing and cost a rename in the JSX. */
    return rows.map((row: any) => ({
      id: row.id,
      timestamp: row.timestamp,
      user_name: row.user_name,
      user_email: row.user_email,
      action: row.action,
      changed_fields: this.asArray(row.changed_fields),
      before_value: this.asObject(row.before_value),
      after_value: this.asObject(row.after_value),
      success: row.success !== false,
      error_message: row.error_message,
    }));
  }

  async notesFor(entity: string, recordId: string, limit = 100) {
    const rows = await this.kysely
      .selectFrom("sys_note")
      .select(["sys_note_id", "note", "user_name", "user_email", "created_at"])
      .where("table_name", "=", this.getTableName(entity))
      .where("record_id", "=", String(recordId))
      .orderBy("created_at", "desc")
      .limit(limit)
      .execute();

    return rows.map((row: any) => ({
      id: row.sys_note_id,
      note: row.note,
      userName: row.user_name,
      userEmail: row.user_email,
      at: row.created_at,
    }));
  }

  /** Append-only: there is no update path and no delete path, by design. */
  async addNote(entity: string, recordId: string, note: string, user: any) {
    const row = await this.kysely
      .insertInto("sys_note")
      .values({
        table_name: this.getTableName(entity),
        record_id: String(recordId),
        note,
        user_id: user?.id ?? null,
        user_name: user?.name ?? user?.username ?? null,
        user_email: user?.email ?? null,
      })
      .returningAll()
      .executeTakeFirstOrThrow();

    return {
      id: (row as any).sys_note_id,
      note: (row as any).note,
      userName: (row as any).user_name,
      userEmail: (row as any).user_email,
      at: (row as any).created_at,
    };
  }

  /**
   * `changed_fields` is `TEXT[]`, which the driver hands back as an array — but
   * a build that stored it as JSON hands back a string. Accepting both is what
   * stops the list silently arriving empty and every entry reading as though
   * nothing had changed.
   */
  private asArray(value: unknown): string[] {
    if (Array.isArray(value)) return value as string[];
    if (typeof value !== "string") return [];
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  private asObject(value: unknown): Record<string, unknown> | null {
    if (value == null) return null;
    if (typeof value === "object") return value as Record<string, unknown>;
    if (typeof value !== "string") return null;
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === "object" ? parsed : null;
    } catch {
      return null;
    }
  }

  private rolesOf(user: any): string[] {
    const roles = user?.roles ?? user?.role ?? [];
    if (Array.isArray(roles)) {
      return roles
        .map((role: any) => (typeof role === "string" ? role : role?.name))
        .filter((role: any): role is string => typeof role === "string");
    }
    return typeof roles === "string" ? [roles] : [];
  }

  /** Deliberate copy of BusService.getTableName — the same rule, stated twice. */
  private getTableName(entity: string): string {
    const normalized = entity.toLowerCase().replace(/-/g, "_");
    if (normalized.startsWith("bus_")) return normalized;
    return `bus_${this.singularize(normalized)}`;
  }

  private singularize(word: string): string {
    if (word.endsWith("ies")) return `${word.slice(0, -3)}y`;
    if (
      word.endsWith("ses") ||
      word.endsWith("xes") ||
      word.endsWith("zes") ||
      word.endsWith("ches") ||
      word.endsWith("shes")
    ) {
      return word.slice(0, -2);
    }
    if (word.endsWith("s") && !word.endsWith("ss")) return word.slice(0, -1);
    return word;
  }
}

import { Inject, Injectable, Logger, type OnModuleInit } from "@nestjs/common";
import { randomUUID } from "crypto";
import { type Kysely, sql } from "kysely";
import { KYSELY_CONNECTION } from "../../database/database.constants";
import type { AuditEvent, AuditSearchParams } from "./audit.types";
import { maskSensitive } from "./audit.types";
import { ImmudbService } from "./immudb.service";

@Injectable()
export class AuditService implements OnModuleInit {
  private readonly logger = new Logger(AuditService.name);

  constructor(
    @Inject(KYSELY_CONNECTION) private readonly kysely: Kysely<any>,
    private readonly immudb: ImmudbService,
  ) {}

  async onModuleInit(): Promise<void> {
    await this.ensureTable();
  }

  /** Ensure audit_log table exists (idempotent). */
  private async ensureTable(): Promise<void> {
    try {
      await sql`
        CREATE TABLE IF NOT EXISTS audit_log (
          id                UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
          immudb_key        VARCHAR(200),
          timestamp         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          user_id           VARCHAR(200),
          user_name         VARCHAR(200),
          user_email        VARCHAR(200),
          session_id        VARCHAR(200),
          action            VARCHAR(100) NOT NULL,
          entity_type       VARCHAR(100),
          entity_id         VARCHAR(200),
          before_value      JSONB,
          after_value       JSONB,
          changed_fields    TEXT[]       DEFAULT '{}',
          ip_address        VARCHAR(45),
          user_agent        TEXT,
          source            VARCHAR(50)  DEFAULT 'WEB_UI',
          success           BOOLEAN      NOT NULL DEFAULT TRUE,
          error_message     TEXT,
          request_id        VARCHAR(200),
          correlation_id    VARCHAR(200),
          created_at        TIMESTAMPTZ  NOT NULL DEFAULT NOW()
        )
      `.execute(this.kysely);

      await sql`CREATE INDEX IF NOT EXISTS idx_audit_timestamp   ON audit_log (timestamp DESC)`.execute(
        this.kysely
      );
      await sql`CREATE INDEX IF NOT EXISTS idx_audit_user_id     ON audit_log (user_id)`.execute(
        this.kysely
      );
      await sql`CREATE INDEX IF NOT EXISTS idx_audit_action      ON audit_log (action)`.execute(
        this.kysely
      );
      await sql`CREATE INDEX IF NOT EXISTS idx_audit_entity_type ON audit_log (entity_type)`.execute(
        this.kysely
      );
      await sql`CREATE INDEX IF NOT EXISTS idx_audit_entity_id   ON audit_log (entity_id)`.execute(
        this.kysely
      );
      await sql`CREATE INDEX IF NOT EXISTS idx_audit_success     ON audit_log (success)`.execute(
        this.kysely
      );

      this.logger.log("audit_log table ready");
    } catch (err) {
      this.logger.error(
        `Failed to create audit_log table: ${err instanceof Error ? err.message : String(err)}`
      );
    }
  }

  /** Fill in the derived fields every stored event carries. */
  private prepare(event: AuditEvent): AuditEvent & { id: string; immudb_key: string } {
    const id = randomUUID();
    return {
      ...event,
      id,
      timestamp: new Date().toISOString(),
      before_value: maskSensitive(event.before_value ?? null),
      after_value: maskSensitive(event.after_value ?? null),
      changed_fields: event.changed_fields ?? [],
      success: event.success ?? true,
      source: event.source ?? "WEB_UI",
      immudb_key: `audit:${Date.now()}:${id}`,
    } as AuditEvent & { id: string; immudb_key: string };
  }

  /**
   * Log an audit event. Non-blocking — failures are logged but do not
   * throw so they never break the business operation being audited.
   */
  async log(event: AuditEvent): Promise<void> {
    const safeEvent = this.prepare(event);

    // Fire-and-forget immudb write (non-blocking)
    setImmediate(async () => {
      try {
        const txId = await this.immudb.verifiedSet(safeEvent.immudb_key, JSON.stringify(safeEvent));
        const resolvedKey = txId !== safeEvent.immudb_key ? txId : safeEvent.immudb_key;
        await this.insertPostgres({ ...safeEvent, immudb_key: resolvedKey });
      } catch (err) {
        this.logger.error(
          `Audit log write failed: ${err instanceof Error ? err.message : String(err)}`
        );
        await this.insertPostgres(safeEvent).catch((e) =>
          this.logger.error(`Audit PG fallback also failed: ${e.message}`)
        );
      }
    });
  }

  /**
   * Log an audit event and wait for it to be stored.
   *
   * `log` defers its write to `setImmediate`, which is right inside an HTTP
   * request — the response should not wait on the trail — and wrong inside a
   * background task, where the process can be torn down the moment the task
   * returns and take the pending write with it. The record-transaction events
   * are the user's only notification that their save finished, so those are
   * written on this path instead: Postgres first and awaited, then the immudb
   * proof best-effort behind it.
   *
   * Returns the stored row's id so a caller can correlate the two halves of a
   * transaction. Never throws — a trail that breaks the operation it records is
   * worse than a gap in the trail.
   */
  async logAndWait(event: AuditEvent): Promise<string | null> {
    const safeEvent = this.prepare(event);

    try {
      await this.insertPostgres(safeEvent);
    } catch (err) {
      this.logger.error(
        `Audit log write failed: ${err instanceof Error ? err.message : String(err)}`
      );
      return null;
    }

    setImmediate(async () => {
      try {
        const txId = await this.immudb.verifiedSet(safeEvent.immudb_key, JSON.stringify(safeEvent));
        if (txId && txId !== safeEvent.immudb_key) {
          await this.kysely
            .updateTable("audit_log" as any)
            .set({ immudb_key: txId } as any)
            .where("id" as any, "=", safeEvent.id)
            .execute();
        }
      } catch (err) {
        this.logger.warn(
          `immudb proof not written for ${safeEvent.id}: ${err instanceof Error ? err.message : String(err)}`
        );
      }
    });

    return safeEvent.id;
  }

  private async insertPostgres(
    event: AuditEvent & { id: string; immudb_key?: string }
  ): Promise<void> {
    await this.kysely
      .insertInto("audit_log" as any)
      .values({
        id: event.id,
        immudb_key: event.immudb_key ?? null,
        timestamp: event.timestamp ?? new Date().toISOString(),
        user_id: event.user_id ?? null,
        user_name: event.user_name ?? null,
        user_email: event.user_email ?? null,
        session_id: event.session_id ?? null,
        action: event.action,
        entity_type: event.entity_type ?? null,
        entity_id: event.entity_id ?? null,
        before_value: event.before_value ? JSON.stringify(event.before_value) : null,
        after_value: event.after_value ? JSON.stringify(event.after_value) : null,
        changed_fields: event.changed_fields ?? [],
        ip_address: event.ip_address ?? null,
        user_agent: event.user_agent ?? null,
        source: event.source ?? "WEB_UI",
        success: event.success ?? true,
        error_message: event.error_message ?? null,
        request_id: event.request_id ?? null,
        correlation_id: event.correlation_id ?? null,
      } as any)
      .execute();
  }

  /**
   * Search audit log with filters. Returns paginated results from PostgreSQL.
   */
  async search(
    params: AuditSearchParams
  ): Promise<{ data: AuditEvent[]; meta: { total: number; page: number; limit: number } }> {
    const page = Math.max(1, params.page ?? 1);
    const limit = Math.min(500, Math.max(1, params.limit ?? 50));
    const offset = (page - 1) * limit;

    let query = this.kysely.selectFrom("audit_log" as any).selectAll();
    let countQuery = this.kysely
      .selectFrom("audit_log" as any)
      .select((eb) => eb.fn.countAll<string>().as("total"));

    const applyFilters = (q: any) => {
      if (params.from) q = q.where("timestamp", ">=", params.from);
      if (params.to) q = q.where("timestamp", "<=", params.to);
      if (params.user_id) q = q.where("user_id", "=", params.user_id);
      if (params.user_email) q = q.where("user_email", "ilike", `%${params.user_email}%`);
      if (params.action) q = q.where("action", "=", params.action);
      if (params.entity_type) q = q.where("entity_type", "=", params.entity_type);
      if (params.entity_id) q = q.where("entity_id", "=", params.entity_id);
      if (params.source) q = q.where("source", "=", params.source);
      if (params.success !== undefined) q = q.where("success", "=", params.success);
      if (params.search) {
        const term = `%${params.search}%`;
        q = q.where((eb: any) =>
          eb.or([
            eb("user_email", "ilike", term),
            eb("user_name", "ilike", term),
            eb("entity_type", "ilike", term),
            eb("entity_id", "ilike", term),
            eb("action", "ilike", term),
          ])
        );
      }
      return q;
    };

    query = applyFilters(query).orderBy("timestamp", "desc").limit(limit).offset(offset);
    countQuery = applyFilters(countQuery);

    const [rows, countResult] = await Promise.all([query.execute(), countQuery.executeTakeFirst()]);

    return {
      data: rows as AuditEvent[],
      meta: { total: parseInt(String(countResult?.total ?? 0), 10), page, limit },
    };
  }

  /**
   * Verify a single audit record against immudb.
   * Returns { verified: true } when the stored value matches and proof is valid.
   */
  async verify(id: string): Promise<{
    verified: boolean;
    immudb_key?: string;
    txId?: string | number;
    mismatch?: boolean;
    reason?: string;
  }> {
    const row = await this.kysely
      .selectFrom("audit_log" as any)
      .selectAll()
      .where("id" as any, "=", id)
      .executeTakeFirst();

    if (!row) return { verified: false, reason: "Record not found" };
    if (!(row as any).immudb_key)
      return { verified: false, reason: "No immudb key stored for this record" };

    if (!this.immudb.isConnected) {
      return { verified: false, reason: "immudb not connected" };
    }

    const result = await this.immudb.verifiedGet((row as any).immudb_key);
    if (!result) return { verified: false, reason: "immudb lookup failed" };

    if (!result.verified)
      return {
        verified: false,
        immudb_key: result.key,
        txId: result.txId,
        reason: "Cryptographic proof failed — data may be tampered",
      };

    // Optionally compare stored JSON to what's in PG for a content match
    try {
      const storedEvent = JSON.parse(result.value ?? "{}");
      const pgEvent = row as any;
      if (storedEvent.action !== pgEvent.action || storedEvent.entity_id !== pgEvent.entity_id) {
        return {
          verified: false,
          immudb_key: result.key,
          txId: result.txId,
          mismatch: true,
          reason: "Content mismatch between immudb and PostgreSQL",
        };
      }
    } catch {
      // If parse fails, still return the immudb verification result
    }

    return { verified: true, immudb_key: result.key, txId: result.txId };
  }

  /** Return distinct entity_type values for the filter dropdown. */
  async getEntityTypes(): Promise<string[]> {
    const rows = await this.kysely
      .selectFrom("audit_log" as any)
      .select("entity_type")
      .distinct()
      .where("entity_type", "is not", null)
      .orderBy("entity_type", "asc")
      .execute();
    return rows.map((r: any) => r.entity_type).filter(Boolean);
  }
}

export const AuditAction = {
  // Authentication
  AUTH_LOGIN: "AUTH_LOGIN",
  AUTH_LOGOUT: "AUTH_LOGOUT",
  AUTH_LOGIN_FAILED: "AUTH_LOGIN_FAILED",
  AUTH_PASSWORD_RESET: "AUTH_PASSWORD_RESET",
  AUTH_SESSION_EXPIRED: "AUTH_SESSION_EXPIRED",

  // Business entity
  ENTITY_CREATE: "ENTITY_CREATE",
  ENTITY_UPDATE: "ENTITY_UPDATE",
  ENTITY_DELETE: "ENTITY_DELETE",
  ENTITY_BULK_CREATE: "ENTITY_BULK_CREATE",

  // Record transactions — the two halves of a write.
  //
  // A save commits the row as a draft and stops there; a second transaction,
  // run by Trigger.dev, executes the record's rules and workflows and either
  // finalises it or leaves it a draft carrying the reason. Both halves are
  // recorded here because the second one runs outside any HTTP request, where
  // the audit interceptor cannot see it — and because the user who saved the
  // record has no other way to learn how it ended up.
  ENTITY_DRAFT: "ENTITY_DRAFT",
  ENTITY_FINALIZE: "ENTITY_FINALIZE",

  // System dictionary
  SYS_FIELD_UPDATE: "SYS_FIELD_UPDATE",
  SYS_FIELD_GROUP_CHANGE: "SYS_FIELD_GROUP_CHANGE",
  SYS_TABLE_CHANGE: "SYS_TABLE_CHANGE",
  SYS_WINDOW_CHANGE: "SYS_WINDOW_CHANGE",

  // AI agent
  AI_SQL_GENERATED: "AI_SQL_GENERATED",
  AI_SQL_EXECUTED: "AI_SQL_EXECUTED",
  AI_REPORT_GENERATED: "AI_REPORT_GENERATED",
  AI_WORKFLOW_APPROVED: "AI_WORKFLOW_APPROVED",
  AI_WORKFLOW_REJECTED: "AI_WORKFLOW_REJECTED",
} as const;

export type AuditActionType = (typeof AuditAction)[keyof typeof AuditAction];

export type AuditSource = "WEB_UI" | "API" | "AGENT" | "SYSTEM";

/**
 * The actions a user sees in their notification list.
 *
 * The notification feed is read from the audit trail and from nowhere else, so
 * this set is what separates "a transaction of mine" from the rest of the
 * trail — logins, reads, dictionary edits — which belong on the audit page
 * rather than in a personal notification list.
 */
export const TRANSACTION_ACTIONS: readonly string[] = [
  "ENTITY_DRAFT",
  "ENTITY_FINALIZE",
];

export interface AuditEvent {
  id?: string;
  immudb_key?: string;
  timestamp?: string;
  user_id?: string | null;
  user_name?: string | null;
  user_email?: string | null;
  session_id?: string | null;
  action: AuditActionType | string;
  entity_type?: string | null;
  entity_id?: string | null;
  before_value?: Record<string, unknown> | null;
  after_value?: Record<string, unknown> | null;
  changed_fields?: string[];
  ip_address?: string | null;
  user_agent?: string | null;
  source?: AuditSource;
  request_id?: string | null;
  correlation_id?: string | null;
  success?: boolean;
  error_message?: string | null;
}

export interface AuditSearchParams {
  page?: number;
  limit?: number;
  from?: string;
  to?: string;
  user_id?: string;
  user_email?: string;
  action?: string;
  entity_type?: string;
  entity_id?: string;
  source?: AuditSource;
  success?: boolean;
  search?: string;
}

/** Fields whose values are masked before storage. */
export const SENSITIVE_FIELDS = new Set([
  "password",
  "password_hash",
  "token",
  "access_token",
  "refresh_token",
  "api_key",
  "secret",
  "private_key",
  "credit_card",
  "card_number",
  "cvv",
  "ssn",
  "national_id",
]);

export function maskSensitive(
  obj: Record<string, unknown> | null | undefined
): Record<string, unknown> | null {
  if (!obj) return null;
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(obj)) {
    out[k] = SENSITIVE_FIELDS.has(k.toLowerCase()) ? "[REDACTED]" : v;
  }
  return out;
}

export function diffFields(
  before: Record<string, unknown> | null | undefined,
  after: Record<string, unknown> | null | undefined
): string[] {
  if (!before || !after) return [];
  return Object.keys(after).filter((k) => JSON.stringify(before[k]) !== JSON.stringify(after[k]));
}

import {
  BadRequestException,
  Body,
  Controller,
  Get,
  Param,
  Post,
  Req,
  UseGuards,
} from "@nestjs/common";
import { ApiBearerAuth, ApiOperation, ApiParam, ApiTags } from "@nestjs/swagger";
import { SessionAuthGuard } from "../auth/guards/session-auth.guard";
import { RecordHistoryService } from "./record-history.service";

/**
 * One record's history and its notes, shown at the foot of that record's screen.
 *
 * Deliberately *not* under `AuditController`, which is administrator-only.
 * That gate is right for the whole log — it spans every table and carries the
 * before and after of every changed field, which is the contents of tables the
 * caller may have no business reading. Narrowed to one record of one table, the
 * same rows are just what happened to something already on the caller's screen,
 * so the gate is that entity's own `read`. A trail only an administrator can
 * see is a trail nobody consults, which is the same as not having one.
 *
 * Writing a note needs `update` on the entity rather than `read`: leaving a
 * note is saying something about the record, and someone who may only look at
 * it should not be able to.
 */
@ApiTags("record-history")
@ApiBearerAuth()
@UseGuards(SessionAuthGuard)
@Controller("records")
export class RecordHistoryController {
  constructor(private readonly history: RecordHistoryService) {}

  @Get(":entity/:id/history")
  @ApiOperation({ summary: "What has been done to one record, newest first" })
  @ApiParam({ name: "entity", description: "Entity route segment, e.g. invoice-line" })
  @ApiParam({ name: "id", description: "The record's id" })
  async recordHistory(
    @Param("entity") entity: string,
    @Param("id") id: string,
    @Req() request: any,
  ) {
    await this.history.assertAccess(request.user, entity, "read");
    const data = await this.history.historyFor(entity, id);
    // `meta.total` because the trail's count badge reads it, the same way the
    // paged /audit response supplies it.
    return { data, meta: { total: data.length, page: 1, limit: data.length } };
  }

  @Get(":entity/:id/notes")
  @ApiOperation({ summary: "The notes people have left on one record" })
  async recordNotes(@Param("entity") entity: string, @Param("id") id: string, @Req() request: any) {
    await this.history.assertAccess(request.user, entity, "read");
    return { data: await this.history.notesFor(entity, id) };
  }

  @Post(":entity/:id/notes")
  @ApiOperation({ summary: "Leave a note on one record" })
  async addNote(
    @Param("entity") entity: string,
    @Param("id") id: string,
    @Body() body: { note?: string },
    @Req() request: any,
  ) {
    await this.history.assertAccess(request.user, entity, "update");

    const note = String(body?.note ?? "").trim();
    if (!note) throw new BadRequestException("A note needs some text.");
    if (note.length > 4000) throw new BadRequestException("A note is at most 4000 characters.");

    return this.history.addNote(entity, id, note, request.user);
  }
}

