/**
 * Retrieval over this application's own model.
 *
 * The application ships with the `.eml.mmd` it was generated from, in
 * `model/model.eml.mmd`. This service chunks that document along its own
 * structure, embeds the chunks, and stores them in pgvector beside the
 * business data — so an administrator extending the application has an
 * assistant that can answer from what the application actually declares
 * rather than from what a language model remembers about ERDs in general.
 *
 * The chunker is `rag.ts` next to this file, copied verbatim from the
 * generator's `language/` folder. It is dependency-free precisely so that copy
 * is possible: the definition of what an EML document means should not fork
 * between the tool that writes models and the applications that run them.
 *
 * Everything here degrades rather than throws. An application whose vector
 * store is unreachable should serve its business data exactly as before and
 * simply have a less useful assistant.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { Inject, Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { sql, type Kysely } from 'kysely';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { InjectDatabase } from '../../database/database.service.decorator';
import { chunkModel, extractEnums, type RagChunk } from './rag';
import { SystemConfigService } from '../sys/services/system-config.service';

export interface RetrievedChunk {
  kind: string;
  name: string;
  text: string;
  score: number;
}

@Injectable()
export class ModelContextService implements OnModuleInit {
  private readonly logger = new Logger(ModelContextService.name);
  private ready = false;

  constructor(
    @InjectDatabase() private readonly db: Kysely<any>,
    private readonly config: SystemConfigService,
  ) {}

  private get EMBEDDING_DIMENSIONS(): number { return this.config.getNumber('AI_EMBEDDING_DIMENSIONS', 384); }
  private get EMBEDDING_MODEL(): string { return this.config.get('AI_EMBEDDING_MODEL', 'bge-small-en-v1.5'); }
  private get AI_BASE_URL(): string { return this.config.get('AI_BASE_URL', 'http://localhost:8000/v1'); }
  private get AI_API_KEY(): string { return this.config.get('AI_API_KEY', 'local'); }

  /**
   * Ingest at startup, in the background.
   *
   * Awaiting it would hold the application's boot on an embedding endpoint
   * that may not be running — an assistant is not worth refusing to serve
   * requests over. A first search before ingest finishes returns nothing,
   * which the assistant reports honestly.
   */
  async onModuleInit(): Promise<void> {
    void this.ingest().catch((error) => {
      this.logger.warn(`Model context unavailable: ${error?.message ?? error}`);
    });
  }

  /** Chunk and embed the shipped model. Safe to call again; it replaces. */
  async ingest(): Promise<{ ingested: number }> {
    const document = await this.readModel();
    if (!document) {
      this.logger.warn('No model/model.eml.mmd shipped with this application.');
      return { ingested: 0 };
    }

    await this.ensureTable();

    const chunks = this.chunk(document);
    if (!chunks.length) return { ingested: 0 };

    const vectors = await this.embed(chunks.map((chunk) => chunk.text));

    await this.db.transaction().execute(async (trx) => {
      // Replace rather than upsert by id: a model that loses an entity should
      // lose its chunk, and an upsert leaves the old one to be retrieved as
      // though that entity still existed.
      await sql`DELETE FROM sys_model_context`.execute(trx);

      for (const [index, chunk] of chunks.entries()) {
        const vector = vectors[index];
        if (!vector) continue;
        await sql`
          INSERT INTO sys_model_context (chunk_id, kind, name, entity, text, embedding)
          VALUES (
            ${chunk.id}, ${chunk.kind}, ${chunk.name},
            ${chunk.metadata.entity ?? null}, ${chunk.text},
            ${`[${vector.join(',')}]`}::vector
          )
        `.execute(trx);
      }
    });

    this.ready = true;
    this.logger.log(`Model context ready: ${chunks.length} chunks embedded.`);
    return { ingested: chunks.length };
  }

  /**
   * The chunks most relevant to a question.
   *
   * Ordered by cosine distance, which is what the index is built for.
   */
  async search(question: string, topK = 8, kinds?: string[]): Promise<RetrievedChunk[]> {
    if (!question.trim()) return [];

    const [vector] = await this.embed([question]);
    if (!vector) return [];

    const literal = `[${vector.join(',')}]`;
    const rows = await sql<{
      kind: string;
      name: string;
      text: string;
      distance: number;
    }>`
      SELECT kind, name, text, (embedding <=> ${literal}::vector) AS distance
      FROM sys_model_context
      ${kinds?.length ? sql`WHERE kind = ANY(${kinds})` : sql``}
      ORDER BY embedding <=> ${literal}::vector
      LIMIT ${topK}
    `.execute(this.db);

    return rows.rows.map((row) => ({
      kind: row.kind,
      name: row.name,
      text: row.text,
      score: 1 - Number(row.distance),
    }));
  }

  isReady(): boolean {
    return this.ready;
  }

  /* ---------------------------------------------------------------------- */

  private async readModel(): Promise<string | null> {
    // The backend runs from `backend/`, so the model sits one level up.
    for (const candidate of ['../model/model.eml.mmd', 'model/model.eml.mmd']) {
      try {
        return await readFile(join(process.cwd(), candidate), 'utf-8');
      } catch {
        // try the next location
      }
    }
    return null;
  }

  private chunk(document: string): RagChunk[] {
    // Parsing here is deliberately shallow: the generated application does not
    // carry the generator's Mermaid parser, and the chunker only needs the
    // shape of the model rather than a compilable one. Entities and their
    // fields come from the erDiagram block; rules and processes come from the
    // directives that declare them.
    const { entities, relationships } = parseErd(document);

    return chunkModel(
      {
        name: '{{project.name}}',
        entities,
        relationships,
        enums: extractEnums(document),
        rules: parseRules(document),
        sagas: parseSagas(document),
      },
      '{{project.name}}'
    );
  }

  /** Embed via the OpenAI-compatible endpoint the application is configured with. */
  private async embed(texts: string[]): Promise<number[][]> {
    if (!texts.length) return [];

    const response = await fetch(`${this.AI_BASE_URL}/embeddings`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${this.AI_API_KEY}`,
      },
      // `encoding_format: float` asked for explicitly: without it a client may
      // negotiate base64 and read the response four values to one.
      body: JSON.stringify({ model: this.EMBEDDING_MODEL, input: texts, encoding_format: 'float' }),
    });

    if (!response.ok) {
      throw new Error(`Embedding endpoint returned ${response.status}`);
    }

    const payload = (await response.json()) as {
      data: { index: number; embedding: number[] }[];
    };
    const ordered = [...payload.data].sort((a, b) => a.index - b.index);
    const vectors = ordered.map((item) => item.embedding);

    const width = vectors[0]?.length;
    if (width && width !== this.EMBEDDING_DIMENSIONS) {
      throw new Error(
        `Embedding model "${this.EMBEDDING_MODEL}" returned ${width}-dimension vectors but the ` +
          `table expects ${this.EMBEDDING_DIMENSIONS}. Set AI_EMBEDDING_DIMENSIONS=${width} and re-ingest.`
      );
    }
    return vectors;
  }

  private async ensureTable(): Promise<void> {
    await sql`CREATE EXTENSION IF NOT EXISTS vector`.execute(this.db);
    await sql`
      CREATE TABLE IF NOT EXISTS sys_model_context (
        id          bigserial PRIMARY KEY,
        chunk_id    text NOT NULL,
        kind        text NOT NULL,
        name        text NOT NULL,
        entity      text,
        text        text NOT NULL,
        embedding   vector(${sql.raw(String(this.EMBEDDING_DIMENSIONS))}) NOT NULL,
        created_at  timestamptz NOT NULL DEFAULT now()
      )
    `.execute(this.db);
    await sql`
      CREATE INDEX IF NOT EXISTS sys_model_context_embedding_idx
      ON sys_model_context USING hnsw (embedding vector_cosine_ops)
    `.execute(this.db);
    await sql`
      CREATE INDEX IF NOT EXISTS sys_model_context_kind_idx ON sys_model_context (kind)
    `.execute(this.db);
  }
}

/* -------------------------------------------------------------------------- */
/*  Shallow EML readers                                                        */
/* -------------------------------------------------------------------------- */

/** Entities and relationships from the `erDiagram` block. */
function parseErd(document: string) {
  const entities: Parameters<typeof chunkModel>[0]['entities'] = [];
  const relationships: Parameters<typeof chunkModel>[0]['relationships'] = [];

  let current: (typeof entities)[number] | null = null;

  for (const raw of document.split('\n')) {
    const line = raw.trim();
    if (!line || line.startsWith('%%')) continue;

    const open = /^(\w+)\s*\{$/.exec(line);
    if (open?.[1]) {
      current = {
        name: open[1],
        tableName: `bus_${toSnake(open[1])}`,
        attributes: [],
        primaryKey: 'id',
      };
      continue;
    }

    if (line === '}' && current) {
      entities.push(current);
      current = null;
      continue;
    }

    if (current) {
      const [type, name, ...rest] = line.split(/\s+/);
      if (!type || !name) continue;
      const flags = rest.join(' ');
      current.attributes.push({
        name,
        type,
        required: !/OPTIONAL/i.test(flags),
        unique: /\bUK\b/.test(flags),
        isForeignKey: /\bFK\b/.test(flags),
      });
      if (/\bPK\b/.test(flags)) current.primaryKey = name;
      continue;
    }

    const relation = /^(\w+)\s+([|}o][|o{-]+[|o{])\s+(\w+)\s*:\s*"?([^"]*)"?$/.exec(line);
    if (relation) {
      relationships.push({
        sourceEntity: relation[1] ?? '',
        targetEntity: relation[3] ?? '',
        cardinality: cardinalityOf(relation[2] ?? ''),
        name: relation[4],
      });
    }
  }

  return { entities, relationships };
}

function cardinalityOf(glyph: string): string {
  if (glyph.includes('||--o{') || glyph.includes('||--|{')) return 'oneToMany';
  if (glyph.includes('}o--||') || glyph.includes('}|--||')) return 'manyToOne';
  if (glyph.includes('||--||')) return 'oneToOne';
  if (glyph.includes('}o--o{')) return 'manyToMany';
  return 'relatesTo';
}

/** `%%rule <name> on <Entity> event: <event> priority: <n>` */
function parseRules(document: string): Parameters<typeof chunkModel>[0]['rules'] {
  const rules: NonNullable<Parameters<typeof chunkModel>[0]['rules']> = [];
  for (const raw of document.split('\n')) {
    const match = /^\s*%%rule\s+(\S+)\s+on\s+(\S+)(.*)$/.exec(raw);
    if (!match) continue;
    const rest = match[3] ?? '';
    const event = /event:\s*(\S+)/.exec(rest)?.[1] ?? 'beforeCreate';
    rules.push({
      name: match[1] ?? '',
      entity: match[2] ?? '',
      event,
      operation: event.toLowerCase().includes('update')
        ? 'UPDATE'
        : event.toLowerCase().includes('delete')
          ? 'DELETE'
          : 'CREATE',
      priority: Number(/priority:\s*(\d+)/.exec(rest)?.[1] ?? 100),
    });
  }
  return rules;
}

/** `%%workflow <Name> entity: <Entity> kind: saga ...` plus its `%%step` lines. */
function parseSagas(document: string): Parameters<typeof chunkModel>[0]['sagas'] {
  const sagas: NonNullable<Parameters<typeof chunkModel>[0]['sagas']> = [];
  const lines = document.split('\n');

  for (let index = 0; index < lines.length; index++) {
    const header = /^\s*%%workflow\s+(\S+)\s+entity:\s*(\S+)\s+kind:\s*saga(.*)$/.exec(
      lines[index] ?? ''
    );
    if (!header) continue;

    const rest = header[3] ?? '';
    const saga = {
      name: header[1] ?? '',
      entity: header[2] ?? '',
      trigger: /trigger:\s*rule/.test(rest) ? 'rule' : 'automatic',
      operation: /operation:\s*(\S+)/.exec(rest)?.[1] ?? 'CREATE',
      steps: [] as NonNullable<Parameters<typeof chunkModel>[0]['sagas']>[number]['steps'],
    };

    // Steps run to the next %%workflow or %%rule header.
    for (let cursor = index + 1; cursor < lines.length; cursor++) {
      const line = lines[cursor] ?? '';
      if (/^\s*%%(workflow|rule)\s/.test(line)) break;
      const step = /^\s*%%step\s+(\S+)\s+(\S+)\s*(.*)$/.exec(line);
      if (!step) continue;
      saga.steps.push({
        nodeId: step[1] ?? '',
        type: step[2] ?? '',
        props: parseProps(step[3] ?? ''),
      });
    }

    sagas.push(saga);
  }
  return sagas;
}

/** `key: value` pairs where a value runs to the next `key:` token. */
function parseProps(rest: string): Record<string, string> {
  const props: Record<string, string> = {};
  const parts = rest.split(/\s+(?=[A-Za-z_][\w-]*:)/);
  for (const part of parts) {
    const at = part.indexOf(':');
    if (at <= 0) continue;
    const key = part.slice(0, at).trim();
    if (key) props[key] = part.slice(at + 1).trim();
  }
  return props;
}

function toSnake(value: string): string {
  return value
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/[-\s]+/g, '_')
    .toLowerCase();
}

/**
 * Model Context Module
 *
 * Retrieval over the `.eml.mmd` this application was generated from, so an
 * administrator extending it has an assistant that can answer from what the
 * application declares.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { Module } from '@nestjs/common';
import { DatabaseModule } from '../../database/database.module';
import { SysModule } from '../sys/sys.module';
import { ModelContextController } from './model-context.controller';
import { ModelContextService } from './model-context.service';

@Module({
  imports: [DatabaseModule, SysModule],
  controllers: [ModelContextController],
  providers: [ModelContextService],
  exports: [ModelContextService],
})
export class ModelContextModule {}

/**
 * EML → retrieval chunks.
 *
 * A model is a structured document, and the useful thing about Docling's
 * approach to RAG is that it refuses to forget that: it splits along a
 * document's own structure — headings, tables, list items — rather than every
 * N characters, and it writes the surrounding context into each piece so a
 * retrieved chunk still says what it is. A table row arrives with its headers
 * attached; a paragraph arrives knowing its section.
 *
 * Splitting an `.eml.mmd` by character count produces the opposite. A 512-char
 * window cuts an `erDiagram` block through the middle of an entity, severs a
 * decision table's JSON, and separates a `%%step` directive from the flowchart
 * node it annotates. What comes back from the vector store is unparseable
 * Mermaid with no indication of which entity or workflow it belonged to — and
 * an assistant asked "what happens when a Sample is deleted?" gets fragments
 * that cannot answer it.
 *
 * So the unit here is the unit the model already has. One chunk per entity,
 * per rule, per workflow, per spec section. Each is complete — an entity chunk
 * carries its fields, its relationships in both directions, and the rules and
 * workflows bound to it — and each opens with a line naming what it is, so the
 * text embeds meaningfully on its own rather than depending on a neighbour.
 *
 * Deliberately dependency-free and structurally typed. `language/` is the
 * source of truth for both the generator and the applications it generates, and
 * this file is copied into generated apps verbatim; an import of
 * `@appwithai/*` here would not survive the trip.
 */

/* -------------------------------------------------------------------------- */
/*  Input shapes — structural, so any caller with the same fields can pass in  */
/* -------------------------------------------------------------------------- */

export interface RagAttribute {
  name: string;
  type: string;
  required: boolean;
  unique?: boolean;
  isForeignKey?: boolean;
}

export interface RagEntity {
  name: string;
  tableName: string;
  description?: string;
  attributes: RagAttribute[];
  primaryKey: string;
}

export interface RagRelationship {
  sourceEntity: string;
  targetEntity: string;
  cardinality: string;
  name?: string;
  foreignKey?: string;
}

export interface RagCategory {
  name: string;
  description?: string;
  entities: string[];
}

export interface RagRule {
  name: string;
  entity: string;
  tableName?: string;
  event: string;
  operation: string;
  priority?: number;
  /** The JDM decision graph, serialised. Read for a human summary, not embedded raw. */
  jdmContent?: string;
}

export interface RagStep {
  /** Flowchart node the step is bound to — `nodeId`, as the compiler spells it. */
  nodeId: string;
  type: string;
  props: Record<string, string>;
}

export interface RagSaga {
  name: string;
  entity: string;
  trigger: string;
  operation: string;
  steps: RagStep[];
}

export interface RagWorkflow {
  name: string;
  entity: string;
  /** State machines and lifecycle-hook sets, which have no ordered steps. */
  states?: string[];
  hooks?: { type: string; handler: string }[];
}

export interface RagModel {
  name?: string;
  version?: string;
  description?: string;
  entities: RagEntity[];
  relationships: RagRelationship[];
  categories?: RagCategory[];
  enums?: { name: string; values: string[] }[];
  rules?: RagRule[];
  sagas?: RagSaga[];
  workflows?: RagWorkflow[];
}

/* -------------------------------------------------------------------------- */
/*  Output                                                                     */
/* -------------------------------------------------------------------------- */

export type ChunkKind =
  | "overview"
  | "entity"
  | "enums"
  | "rule"
  | "workflow"
  | "spec";

export interface RagChunk {
  /**
   * Stable across re-ingests of the same model, so re-embedding replaces a
   * chunk rather than accumulating a second copy of it.
   */
  id: string;
  kind: ChunkKind;
  /** What this chunk is about — the entity, rule or workflow name. */
  name: string;
  /** The text that gets embedded. Self-contained by construction. */
  text: string;
  /** Filterable facts. Kept flat: vector stores filter on scalars, not trees. */
  metadata: {
    kind: ChunkKind;
    name: string;
    /** The entity this concerns, when it concerns exactly one. */
    entity?: string;
    /** CREATE / UPDATE / DELETE / ALL, for rules and sagas. */
    operation?: string;
    /** Lifecycle event, for rules. */
    event?: string;
    /** Entities this chunk touches, including through workflow steps. */
    touches?: string[];
    /** Where it came from, so an answer can cite it. */
    source: string;
  };
}

/* -------------------------------------------------------------------------- */
/*  Rendering helpers                                                          */
/* -------------------------------------------------------------------------- */

/** Cardinality glyphs and camelCase names read badly in prose. */
function cardinalityPhrase(cardinality: string): string {
  switch (cardinality) {
    case "oneToMany":
      return "has many";
    case "manyToOne":
      return "belongs to";
    case "oneToOne":
      return "has one";
    case "manyToMany":
      return "relates to many";
    default:
      return "relates to";
  }
}

function attributeLine(attribute: RagAttribute): string {
  const flags = [
    attribute.required ? "required" : "optional",
    attribute.unique ? "unique" : null,
    attribute.isForeignKey ? "foreign key" : null,
  ].filter(Boolean);
  return `  - ${attribute.name} (${attribute.type}, ${flags.join(", ")})`;
}

interface DecisionTableContent {
  hitPolicy?: string;
  inputs?: { name?: string; field?: string }[];
  outputs?: { name?: string; field?: string }[];
  rules?: Record<string, string>[];
}

/**
 * A decision table, row by row.
 *
 * The rows are the whole point: "critical deviations get a one-day containment
 * window" lives in a table cell, and a chunk that says "there is a decision
 * table here" cannot answer a question about it. Rendered as prose rather than
 * as the raw JSON, because a serialised table is mostly punctuation and cell
 * ids — it embeds close to every other serialised table and reads as noise.
 */
function describeDecisionTable(content: DecisionTableContent, label: string): string[] {
  if (!content.rules?.length) return [];
  const inputs = content.inputs ?? [];
  const outputs = content.outputs ?? [];

  const lines = [
    `${label} (hit policy: ${content.hitPolicy ?? "first"}):`,
    `  reads ${inputs.map((i) => i.field || i.name).join(", ") || "the record"}, ` +
      `writes ${outputs.map((o) => o.field || o.name).join(", ") || "nothing"}`,
  ];

  for (const row of content.rules) {
    const condition = inputs
      .map((_input, index) => row[`i${index + 1}`])
      .filter((cell) => cell?.trim())
      .join(" and ");
    const results = outputs
      .map((output, index) => {
        const cell = row[`o${index + 1}`];
        if (!cell?.trim() || cell === "''") return null;
        return `${output.field || output.name} = ${cell}`;
      })
      .filter(Boolean)
      .join(", ");
    lines.push(`  - when ${condition || "no earlier row matched"} → ${results || "nothing"}`);
  }
  return lines;
}

/** A readable summary of a rule's decision graph. */
function describeJdm(jdmContent: string | undefined): string[] {
  if (!jdmContent?.trim()) return [];
  let graph: { nodes?: { name?: string; type?: string; content?: unknown }[] };
  try {
    graph = JSON.parse(jdmContent);
  } catch {
    return [];
  }

  const lines: string[] = [];
  for (const node of graph.nodes ?? []) {
    if (node.type === "decisionTableNode") {
      lines.push(
        ...describeDecisionTable(
          node.content as DecisionTableContent,
          `Decision table "${node.name ?? "table"}"`
        )
      );
    } else if (node.type === "switchNode" || node.type === "expressionNode") {
      lines.push(
        `  ${node.type === "switchNode" ? "decides" : "does"}: ${node.name ?? ""}`.trimEnd()
      );
    }
  }
  return lines;
}

/** One workflow step, in the order it runs, saying what it touches. */
function describeStep(step: RagStep, index: number, ownEntity: string): string {
  const props = step.props ?? {};
  const target = props.entity?.trim() || ownEntity;
  const parts: string[] = [`  ${index + 1}. ${step.type}`];

  switch (step.type) {
    case "Decision": {
      if (props.rule) {
        parts.push(`evaluates the rule "${props.rule}"`);
      } else {
        parts.push("evaluates a decision table declared inside the step");
      }
      if (props.publish) parts.push(`publishing ${props.publish}`);

      // Spell the table out. Its rows are the policy — leaving them as a
      // reference to "a decision table" makes the step unanswerable.
      if (props.decisionTable) {
        try {
          const rows = describeDecisionTable(
            JSON.parse(props.decisionTable) as DecisionTableContent,
            "     table"
          );
          if (rows.length) return [parts.join(" "), ...rows.map((row) => `   ${row}`)].join("\n");
        } catch {
          // A table that does not parse is a model defect the checker reports;
          // the step still describes itself without it.
        }
      }
      break;
    }
    case "CreateEntity":
      parts.push(`creates a ${target}`);
      if (props.as) parts.push(`and remembers its id as "${props.as}"`);
      if (props.fields) parts.push(`with fields ${props.fields}`);
      break;
    case "UpdateEntity":
      parts.push(`updates ${target}.${props.field ?? "?"}`);
      if (props.source) parts.push(`from the variable "${props.source}"`);
      else if (props.value) parts.push(`to "${props.value}"`);
      if (props.targetSource) parts.push(`on the row remembered as "${props.targetSource}"`);
      break;
    case "DeleteEntity":
      parts.push(`deletes ${target} rows`);
      if (props.targetField) parts.push(`matched on ${props.targetField}`);
      if (props.targetSource) parts.push(`= the variable "${props.targetSource}"`);
      break;
    case "Formula":
      parts.push(
        `computes "${props.target ?? "?"}" as ${props.source ?? "?"} ${props.operation ?? "?"} ${props.operand ?? ""}`.trimEnd()
      );
      break;
    case "REST":
      parts.push(`calls ${props.method ?? "POST"} ${props.url ?? "?"}`);
      break;
    default:
      parts.push(
        Object.entries(props)
          .map(([key, value]) => `${key}: ${value}`)
          .join(", ")
      );
  }
  return parts.join(" ");
}

/** Every entity a saga writes to, so "what touches CAPA?" is answerable. */
function entitiesTouchedBySaga(saga: RagSaga): string[] {
  const touched = new Set<string>([saga.entity]);
  for (const step of saga.steps ?? []) {
    const entity = step.props?.entity?.trim();
    if (entity) touched.add(entity);
  }
  return [...touched];
}

/* -------------------------------------------------------------------------- */
/*  Chunkers                                                                   */
/* -------------------------------------------------------------------------- */

/**
 * The whole model in one chunk.
 *
 * Answers "what is this application?" and "which entities exist?", neither of
 * which any single entity chunk can answer. Deliberately a list rather than
 * detail — the detail lives in the per-entity chunks, and duplicating it here
 * would make this chunk win searches it should lose.
 */
function overviewChunk(model: RagModel, source: string): RagChunk {
  const lines: string[] = [
    `Application model: ${model.name ?? "unnamed"}${model.version ? ` (version ${model.version})` : ""}.`,
  ];
  if (model.description) lines.push(model.description);

  lines.push("", `Entities (${model.entities.length}):`);
  for (const entity of model.entities) {
    lines.push(`  - ${entity.name} (table ${entity.tableName}, ${entity.attributes.length} fields)`);
  }

  if (model.categories?.length) {
    lines.push("", "Grouped into:");
    for (const category of model.categories) {
      lines.push(`  - ${category.name}: ${category.entities.join(", ")}`);
    }
  }

  if (model.relationships.length) {
    lines.push("", `Relationships (${model.relationships.length}):`);
    for (const relationship of model.relationships) {
      lines.push(
        `  - ${relationship.sourceEntity} ${cardinalityPhrase(relationship.cardinality)} ${relationship.targetEntity}`
      );
    }
  }

  const counts = [
    model.rules?.length ? `${model.rules.length} business rules` : null,
    model.sagas?.length ? `${model.sagas.length} multi-step processes` : null,
    model.workflows?.length ? `${model.workflows.length} lifecycle workflows` : null,
  ].filter(Boolean);
  if (counts.length) lines.push("", `It declares ${counts.join(", ")}.`);

  return {
    id: "overview",
    kind: "overview",
    name: model.name ?? "model",
    text: lines.join("\n"),
    metadata: { kind: "overview", name: model.name ?? "model", source },
  };
}

/**
 * One entity, with everything bound to it.
 *
 * The relationships are rendered from both directions and the rules and
 * workflows that name the entity are listed here too, because the question
 * people actually ask is "tell me about Sample" — and an answer that omits the
 * workflow that deletes Samples is wrong in the way that matters.
 */
function entityChunks(model: RagModel, source: string): RagChunk[] {
  return model.entities.map((entity) => {
    const lines: string[] = [
      `Entity ${entity.name} (database table ${entity.tableName}).`,
    ];
    if (entity.description) lines.push(entity.description);

    const category = model.categories?.find((c) => c.entities.includes(entity.name));
    if (category) lines.push(`Belongs to the "${category.name}" group.`);

    lines.push("", `Fields (primary key ${entity.primaryKey}):`);
    for (const attribute of entity.attributes) lines.push(attributeLine(attribute));

    const outgoing = model.relationships.filter((r) => r.sourceEntity === entity.name);
    const incoming = model.relationships.filter((r) => r.targetEntity === entity.name);
    if (outgoing.length || incoming.length) {
      lines.push("", "Relationships:");
      for (const relationship of outgoing) {
        lines.push(
          `  - ${entity.name} ${cardinalityPhrase(relationship.cardinality)} ${relationship.targetEntity}`
        );
      }
      for (const relationship of incoming) {
        lines.push(
          `  - ${relationship.sourceEntity} ${cardinalityPhrase(relationship.cardinality)} ${entity.name}`
        );
      }
    }

    const rules = (model.rules ?? []).filter((rule) => rule.entity === entity.name);
    if (rules.length) {
      lines.push("", "Business rules on this entity:");
      for (const rule of rules) lines.push(`  - ${rule.name}, runs on ${rule.event}`);
    }

    const sagas = (model.sagas ?? []).filter((saga) =>
      entitiesTouchedBySaga(saga).includes(entity.name)
    );
    if (sagas.length) {
      lines.push("", "Processes that read or write this entity:");
      for (const saga of sagas) {
        const own = saga.entity === entity.name;
        lines.push(
          `  - ${saga.name} (${own ? `runs on ${entity.name} ${saga.operation}` : `writes to ${entity.name} from a ${saga.entity} process`})`
        );
      }
    }

    return {
      id: `entity:${entity.name}`,
      kind: "entity" as const,
      name: entity.name,
      text: lines.join("\n"),
      metadata: {
        kind: "entity" as const,
        name: entity.name,
        entity: entity.name,
        source,
      },
    };
  });
}

/** Enums together — each is a line, and one per chunk would be noise. */
function enumChunk(model: RagModel, source: string): RagChunk | null {
  if (!model.enums?.length) return null;
  const lines = ["Enumerations declared by this model. Each lists the values a field may take.", ""];
  for (const declaration of model.enums) {
    lines.push(`  - ${declaration.name}: ${declaration.values.join(", ")}`);
  }
  return {
    id: "enums",
    kind: "enums",
    name: "enumerations",
    text: lines.join("\n"),
    metadata: { kind: "enums", name: "enumerations", source },
  };
}

/** One rule, with its decision logic spelled out. */
function ruleChunks(model: RagModel, source: string): RagChunk[] {
  return (model.rules ?? []).map((rule) => {
    const lines: string[] = [
      `Business rule "${rule.name}" on ${rule.entity}.`,
      `Runs on ${rule.event} (${rule.operation})${rule.priority !== undefined ? `, priority ${rule.priority}` : ""}.`,
    ];
    const logic = describeJdm(rule.jdmContent);
    if (logic.length) {
      lines.push("", "Logic:");
      lines.push(...logic);
    }
    return {
      id: `rule:${rule.name}`,
      kind: "rule" as const,
      name: rule.name,
      text: lines.join("\n"),
      metadata: {
        kind: "rule" as const,
        name: rule.name,
        entity: rule.entity,
        operation: rule.operation,
        event: rule.event,
        source,
      },
    };
  });
}

/** One process, its steps in order, and the entities it reaches. */
function sagaChunks(model: RagModel, source: string): RagChunk[] {
  return (model.sagas ?? []).map((saga) => {
    const touched = entitiesTouchedBySaga(saga);
    const lines: string[] = [
      `Multi-step process "${saga.name}" on ${saga.entity}.`,
      saga.trigger === "rule"
        ? "Runs only when a business rule triggers it by name."
        : `Runs automatically on ${saga.entity} ${saga.operation}.`,
    ];

    lines.push("", "Steps, in order:");
    for (const [index, step] of (saga.steps ?? []).entries()) {
      lines.push(describeStep(step, index, saga.entity));
    }

    if (touched.length > 1) {
      lines.push("", `Entities written by this process: ${touched.join(", ")}.`);
    }

    return {
      id: `workflow:${saga.name}`,
      kind: "workflow" as const,
      name: saga.name,
      text: lines.join("\n"),
      metadata: {
        kind: "workflow" as const,
        name: saga.name,
        entity: saga.entity,
        operation: saga.operation,
        touches: touched,
        source,
      },
    };
  });
}

/** State machines and lifecycle-hook sets. */
function workflowChunks(model: RagModel, source: string): RagChunk[] {
  return (model.workflows ?? []).map((workflow) => {
    const lines: string[] = [`Lifecycle workflow "${workflow.name}" on ${workflow.entity}.`];
    if (workflow.states?.length) {
      lines.push("", `Statuses: ${workflow.states.join(" → ")}.`);
    }
    if (workflow.hooks?.length) {
      lines.push("", "Lifecycle handlers:");
      for (const hook of workflow.hooks) lines.push(`  - ${hook.type}: ${hook.handler}`);
    }
    return {
      id: `workflow:${workflow.name}`,
      kind: "workflow" as const,
      name: workflow.name,
      text: lines.join("\n"),
      metadata: {
        kind: "workflow" as const,
        name: workflow.name,
        entity: workflow.entity,
        source,
      },
    };
  });
}

/* -------------------------------------------------------------------------- */
/*  Entry points                                                               */
/* -------------------------------------------------------------------------- */

/**
 * Read `%%enum` declarations straight from the document.
 *
 * The parsed model does not carry them — the generator resolves enums into
 * column constraints and has no reason to keep the list. Retrieval does: "which
 * statuses can a Sample have?" is answered by the declaration and by nothing
 * else in the model.
 */
export function extractEnums(eml: string): { name: string; values: string[] }[] {
  const enums: { name: string; values: string[] }[] = [];
  for (const line of eml.split("\n")) {
    const match = /^\s*%%enum\s+([A-Za-z_][\w]*)\s*:\s*(.+)$/.exec(line);
    if (!match) continue;
    const values = (match[2] ?? "")
      .split(",")
      .map((value) => value.trim())
      .filter(Boolean);
    if (match[1] && values.length) enums.push({ name: match[1], values });
  }
  return enums;
}

/**
 * Chunk a parsed model.
 *
 * `source` is recorded on every chunk so an answer can say where it came from —
 * a project's own model, or the language specification.
 */
export function chunkModel(model: RagModel, source = "model"): RagChunk[] {
  const chunks: RagChunk[] = [overviewChunk(model, source), ...entityChunks(model, source)];
  const enums = enumChunk(model, source);
  if (enums) chunks.push(enums);
  chunks.push(...ruleChunks(model, source), ...sagaChunks(model, source), ...workflowChunks(model, source));
  return chunks;
}

/**
 * Chunk a markdown document by heading.
 *
 * Used for the EML specification, which is what an assistant needs in order to
 * write a `%%step` or a `%%rule` correctly rather than inventing a directive
 * that looks plausible and does not parse. Sections carry their heading trail
 * so a chunk taken from deep in a document still says what it is about.
 */
export function chunkMarkdown(markdown: string, source: string): RagChunk[] {
  const lines = markdown.split("\n");
  const chunks: RagChunk[] = [];

  let heading = source;
  let trail: string[] = [];
  let buffer: string[] = [];
  let index = 0;

  const flush = () => {
    const body = buffer.join("\n").trim();
    buffer = [];
    if (!body) return;
    chunks.push({
      id: `spec:${source}:${index++}`,
      kind: "spec",
      name: heading,
      // The heading trail leads the text, so the embedding carries the context
      // the words alone would lose.
      text: `${trail.join(" › ")}\n\n${body}`,
      metadata: { kind: "spec", name: heading, source },
    });
  };

  for (const line of lines) {
    const match = /^(#{1,6})\s+(.*)$/.exec(line);
    if (match) {
      flush();
      const depth = match[1]?.length ?? 1;
      heading = (match[2] ?? "").trim();
      trail = [...trail.slice(0, depth - 1), heading];
      continue;
    }
    buffer.push(line);
  }
  flush();

  return chunks;
}

