/**
 * System Service (Application Dictionary)
 *
 * Provides data access for all sys_ tables using Kysely.
 *
 * Generated: {{now}}
 */

import {
  BadRequestException,
  ConflictException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { sql } from 'kysely';
import { randomUUID } from 'crypto';
import { DatabaseService } from '../../database/database.service';
import { BusService } from '../bus/bus.service';
import { parseLogic } from '../../common/field-logic';
import { createCache } from '../../common/ttl-cache';

/**
 * The database table behind a sys_table row. The model's tables are recorded
 * with their prefix (`bus_contract`) and a table created here without one, so
 * prefixing unconditionally sent every column change on a generated table to
 * `bus_bus_contract`, which does not exist: changing a column's length,
 * mandatory flag or default in Table and Column failed with a 409.
 */
function physicalTableName(tableName: unknown): string {
  const name = String(tableName);
  return name.startsWith('bus_') ? name : `bus_${name}`;
}
import type { Kysely } from 'kysely';

interface PaginationOptions {
  page?: number;
  limit?: number;
  prefix?: string;
}

@Injectable()
export class SysService {
  // The dictionary's field lists, each for CACHE_TTL_DICTIONARY_FIELDS_MS
  // (common/ttl-cache.ts), dropped at once by a dictionary edit made here.
  private readonly fieldCache = createCache<string, unknown>('dictionaryFields');

  constructor(
    private readonly db: DatabaseService,
    private readonly busService: BusService,
  ) {}

  private async getCached<T>(key: string, factory: () => Promise<T>): Promise<T> {
    const cached = this.fieldCache.get(key);
    if (cached !== undefined) return cached as T;
    const data = await factory();
    this.fieldCache.set(key, data);
    return data;
  }

  private invalidateFieldCache(tableName?: string) {
    if (tableName) {
      for (const key of this.fieldCache.keys()) {
        if (key.includes(tableName)) this.fieldCache.delete(key);
      }
    } else {
      this.fieldCache.clear();
    }
  }

  private formatTableName(tableName: string): string {
    return tableName.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  }

  private formatColumnName(columnName: string): string {
    return columnName.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  }

  private applyFilters(query: any, filters: Record<string, any>): any {
    for (const [key, value] of Object.entries(filters)) {
      if (value && typeof value === 'object' && 'operator' in value) {
        query = query.where(sql.ref(key), value.operator, value.value);
      } else if (typeof value === 'string' && (value.startsWith('%') || value.endsWith('%'))) {
        query = query.where(sql.ref(key), 'ilike', value);
      } else {
        query = query.where(sql.ref(key), '=', value);
      }
    }
    return query;
  }

  // ============================================================
  // SYS_TABLE
  // ============================================================

  /**
   * The `bus_` tables a caller may read, or `null` for "everything".
   *
   * `%%rbac … .read` decides which entities a role's application is made of.
   * `EntityAccessGuard` already refuses a read the caller's roles do not
   * permit, but a navigation full of entries that answer 403 is a worse
   * application than a shorter one: the reader cannot tell a permission from a
   * bug. Only `bus_` tables are ever narrowed — the dictionary's own `sys_`
   * tables are what the administrative screens are made of, and no `%%rbac`
   * directive names them.
   *
   * A failed lookup means "no rules", matching `EntityAccessGuard`'s fail-open
   * on a database that predates the migration.
   */
  private async readableBusTables(
    user?: { isMaster?: boolean; roles?: string[]; sysRoles?: string[]; role?: string },
  ): Promise<{ restricted: Set<string>; allowed: Set<string> } | null> {
    if (!user || user.isMaster === true) return null;

    /* Case and separators both — `sys_operation_access` holds the model's
       spelling (`computational_chemist`) and `sys_role` the displayed one
       (`Computational Chemist`). Folding case alone makes every multi-word role
       unequal to itself; see the same rule in EntityAccessGuard. */
    const foldRole = (role: string) => role.trim().toLowerCase().replace(/[\s\-_]+/g, '');
    const held = new Set<string>();
    for (const value of [...(user.sysRoles ?? []), ...(user.roles ?? [])]) {
      if (typeof value === 'string' && value) held.add(foldRole(value));
    }
    if (typeof user.role === 'string' && user.role) held.add(foldRole(user.role));

    let rows: Array<{ table_name: string; role_name: string }>;
    try {
      rows = (await this.db.kysely
        .selectFrom('sys_operation_access')
        .select(['table_name', 'role_name'])
        .where('operation', '=', 'read')
        .where('is_active', '=', true)
        .execute()) as Array<{ table_name: string; role_name: string }>;
    } catch {
      return null;
    }
    if (rows.length === 0) return null;

    return {
      restricted: new Set(rows.map((row) => row.table_name)),
      allowed: new Set(
        rows
          .filter((row) => held.has(foldRole(String(row.role_name))))
          .map((row) => row.table_name),
      ),
    };
  }

  /** A table is visible unless a %%rbac read rule names it and excludes the caller. */
  private visibleToScope(
    tableName: string,
    scope: { restricted: Set<string>; allowed: Set<string> } | null,
  ): boolean {
    if (!scope) return true;
    if (!String(tableName).startsWith('bus_')) return true;
    return !scope.restricted.has(tableName) || scope.allowed.has(tableName);
  }

  async findAllTables(
    options: PaginationOptions & { search?: string } = {},
    filters: Record<string, any> = {},
    user?: { isMaster?: boolean; roles?: string[]; sysRoles?: string[]; role?: string },
  ) {
    const { page = 1, limit = 100, search, prefix } = options;
    const offset = (page - 1) * limit;

    let query = this.db.kysely.selectFrom('sys_table').selectAll().where('is_active', '=', true);

    if (prefix) query = query.where('table_name', 'like', `${prefix}%`);
    if (search) query = query.where('name', 'like', `%${search}%`);
    if (Object.keys(filters).length > 0) query = this.applyFilters(query, filters);

    const scope = await this.readableBusTables(user);

    // Paginated after the scope filter, not before it, so a caller who may read
    // three of nine entities gets three rows rather than whatever survives the
    // first page.
    const all = await query.orderBy('name').execute();
    const visible = all.filter((row: any) => this.visibleToScope(String(row.table_name), scope));
    const data = visible.slice(Number(offset), Number(offset) + Number(limit));

    return { data, meta: { total: visible.length, page, pageSize: limit } };
  }

  async findAllDatabaseTables(options: PaginationOptions & { search?: string } = {}) {
    const { page = 1, limit = 100, search, prefix } = options;
    const offset = (page - 1) * limit;

    const allTables = await sql<{ table_name: string }[]>`
      SELECT table_name FROM information_schema.tables
      WHERE table_schema = 'public' AND table_type = 'BASE TABLE'
      ${prefix ? sql`AND table_name LIKE ${prefix + '%'}` : sql``}
      ${search ? sql`AND table_name LIKE ${'%' + search + '%'}` : sql``}
      ORDER BY table_name
    `.execute(this.db.kysely);

    const rows = (allTables as any).rows as { table_name: string }[];
    const count = rows.length;
    const paginatedRows = rows.slice(offset, offset + limit);
    const tableNames = paginatedRows.map(t => t.table_name);

    const sysTableData = tableNames.length > 0
      ? await this.db.kysely.selectFrom('sys_table').selectAll()
          .where('table_name', 'in', tableNames).where('is_active', '=', true).execute()
      : [];

    const data = paginatedRows.map(t => {
      const sysTable = sysTableData.find(st => st.table_name === t.table_name);
      return {
        sys_table_id: sysTable?.sys_table_id ?? null,
        table_name: t.table_name,
        name: sysTable?.name ?? this.formatTableName(t.table_name),
        description: sysTable?.description ?? null,
        is_active: sysTable?.is_active ?? true,
      };
    });

    return { data, meta: { total: count, page, pageSize: limit } };
  }

  async findTableById(id: string) {
    const table = await this.db.kysely.selectFrom('sys_table').selectAll()
      .where('sys_table_id', '=', id).executeTakeFirst();
    if (!table) throw new NotFoundException(`Table with ID ${id} not found`);
    return table;
  }

  async findTableByName(tableName: string) {
    const table = await this.db.kysely.selectFrom('sys_table').selectAll()
      .where('table_name', '=', tableName).executeTakeFirst();
    if (!table) throw new NotFoundException(`Table ${tableName} not found`);
    return table;
  }

  async createTable(data: Record<string, unknown>) {
    const now = new Date().toISOString();
    const dbTableName = physicalTableName(data.table_name);

    const table = await this.db.kysely.transaction().execute(async (trx) => {
      const [inserted] = await trx.insertInto('sys_table')
        .values({ is_active: true, entity_type: 'U', ...data, created_at: now, updated_at: now, created_by: 'system', updated_by: 'system' } as any)
        .returningAll()
        .execute();

      // Create actual Postgres table with standard bus columns
      try {
        await sql`
          CREATE TABLE IF NOT EXISTS ${sql.id(dbTableName)} (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
            deleted_at TIMESTAMPTZ,
            created_by VARCHAR(100),
            updated_by VARCHAR(100),
            version INTEGER NOT NULL DEFAULT 0
          )
        `.execute(trx);
      } catch (error: any) {
        throw new ConflictException(error?.message ?? 'Could not create the table');
      }

      return inserted;
    });

    // Auto-bootstrap sys_window / sys_tab / sys_field for the new entity
    try {
      await this.busService.setupEntityDictionary(data.table_name as string);
    } catch (_e) {
      // Dictionary may already exist or table has no columns yet — non-fatal
    }

    return table;
  }

  private mapRefToSqlType(refId: number, fieldLength?: number): string {
    const length = typeof fieldLength === 'number' && fieldLength > 0 ? fieldLength : undefined;
    const map: Record<number, string> = {
      10: length ? `VARCHAR(${length})` : 'VARCHAR(255)',
      11: 'INTEGER',
      12: 'DECIMAL(20,2)',
      13: 'UUID',
      14: 'TEXT',
      15: 'DATE',
      16: 'TIMESTAMPTZ',
      17: length ? `VARCHAR(${length})` : 'VARCHAR(40)',
      18: 'UUID',
      19: 'UUID',
      20: 'BOOLEAN',
      24: length ? `VARCHAR(${length})` : 'VARCHAR(255)',
    };
    return map[refId] ?? 'TEXT';
  }

  /** Safely embed a dictionary-supplied default value as a quoted SQL literal.
   *  Postgres implicitly casts a quoted literal to the target column's type,
   *  so a single quoting strategy covers strings, numbers, booleans and dates. */
  private formatSqlLiteral(value: unknown): string {
    return `'${String(value).replace(/'/g, "''")}'`;
  }

  async createColumn(data: Record<string, unknown>) {
    // Accept either sys_table_id or tableId (parentField param from ADListShell)
    const tableId = (data.sys_table_id ?? data.tableId) as string;
    if (!tableId) throw new NotFoundException('sys_table_id is required');
    const parentTable = await this.findTableById(tableId);
    const dbTableName = physicalTableName(parentTable.table_name);
    const columnName = data.column_name as string;
    const sqlType = this.mapRefToSqlType(data.sys_reference_id as number, data.field_length as number | undefined);

    const constraints: string[] = [];
    if (data.default_value !== undefined && data.default_value !== null && data.default_value !== '') {
      constraints.push(`DEFAULT ${this.formatSqlLiteral(data.default_value)}`);
    }
    if (data.is_mandatory) constraints.push('NOT NULL');
    const constraintSql = constraints.length ? ` ${constraints.join(' ')}` : '';

    const now = new Date().toISOString();
    const column = await this.db.kysely.transaction().execute(async (trx) => {
      // ALTER TABLE ADD COLUMN on the actual Postgres table — DDL and the
      // dictionary metadata insert share a transaction so they can't desync
      // if either half fails partway through.
      try {
        await sql`
          ALTER TABLE ${sql.id(dbTableName)}
          ADD COLUMN IF NOT EXISTS ${sql.id(columnName)} ${sql.raw(sqlType + constraintSql)}
        `.execute(trx);
      } catch (error: any) {
        throw new ConflictException(error?.message ?? 'Could not add the column to the table');
      }

      // Insert sys_column metadata
      const [inserted] = await trx.insertInto('sys_column')
        .values({
          sys_column_id: randomUUID(),
          sys_table_id: tableId,
          column_name: columnName,
          name: data.name ?? columnName,
          description: data.description ?? null,
          sys_reference_id: data.sys_reference_id,
          field_length: data.field_length ?? null,
          default_value: data.default_value ?? null,
          is_key: data.is_key ?? false,
          is_parent: data.is_parent ?? false,
          is_mandatory: data.is_mandatory ?? false,
          is_updateable: data.is_updateable ?? true,
          is_identifier: data.is_identifier ?? false,
          is_selection_column: data.is_selection_column ?? false,
          is_encrypted: data.is_encrypted ?? false,
          seq_no: data.seq_no ?? 0,
          entity_type: data.entity_type ?? 'U',
          is_active: true,
          created_by: 'system',
          updated_by: 'system',
          created_at: now,
          updated_at: now,
        } as any)
        .returningAll()
        .execute();
      return inserted;
    });

    // Bootstrap a sys_field for the new column so it shows up in the entity's
    // form/grid immediately, the same way createTable bootstraps window/tab.
    // setupEntityDictionary is incremental — it only inserts fields for
    // columns that don't have one yet — so this is safe to call every time.
    try {
      await this.busService.setupEntityDictionary(parentTable.table_name as string);
    } catch (_e) {
      // Non-fatal — the column and its sys_column metadata already exist.
    }

    this.busService.clearMetadataCache();
    return column;
  }

  /* ------------------------------------------------------------------ *
   *  Entity icons                                                       *
   * ------------------------------------------------------------------ */

  /**
   * What `sys_table.icon` is allowed to contain.
   *
   * Two shapes and nothing else: a lucide icon id, or a small image someone
   * uploaded through the dictionary screens as a `data:` URI.
   *
   * This exists because the column stopped being small. It was VARCHAR(100),
   * which put a ceiling on the damage; it is TEXT now so that an uploaded image
   * fits, and `updateTable` spreads the request body straight into the UPDATE.
   * Without a check here, any administrator could put a megabyte of anything in
   * a column that the dashboard renders into an `<img src>` on every page load.
   *
   * What is refused, and why:
   *
   *   an http(s) URL   would make every dashboard a request to somebody else's
   *                    server: a tracking pixel on every page, and a way to
   *                    probe hosts the browser can reach that this server
   *                    cannot. A `data:` URI carries its own bytes.
   *   any other scheme `javascript:` is the obvious one. The allowlist is
   *                    positive, so nothing has to be enumerated.
   *   an unlisted type SVG, PNG, WEBP, GIF and JPEG. SVG is allowed because it
   *                    is what an icon should be, and it is rendered through
   *                    `<img>` rather than inlined — a script inside an SVG
   *                    does not run when the SVG is the source of an img.
   *   anything large   64KB decoded. An icon is drawn at 20 pixels; a file
   *                    bigger than this is a photograph by mistake, and every
   *                    row of it is carried in the dashboard's response.
   */
  private static readonly ICON_MAX_DECODED_BYTES = 64 * 1024;
  private static readonly ICON_MEDIA_TYPES = new Set([
    'image/svg+xml',
    'image/png',
    'image/webp',
    'image/gif',
    'image/jpeg',
  ]);

  validateIconValue(value: unknown): string | null {
    // Clearing the icon is a legitimate edit: the entity falls back to the
    // default one.
    if (value === null || value === undefined || value === '') return null;
    if (typeof value !== 'string') {
      throw new BadRequestException('icon must be a string, or null to clear it');
    }

    const icon = value.trim();

    if (!icon.startsWith('data:')) {
      /*
       * A lucide id. Not checked against lucide's catalogue — this server does
       * not carry it, and the front end already draws a placeholder for a name
       * it cannot resolve. What is checked is that it is a *name*: short, and
       * made of the characters a name is made of. That is what keeps a URL, a
       * script, or a paragraph of text out of the column.
       */
      if (icon.length > 64 || !/^[A-Za-z][A-Za-z0-9 _-]*$/.test(icon)) {
        throw new BadRequestException(
          'icon must be a lucide icon name (letters, digits, spaces, - and _; 64 characters at most) or an uploaded image',
        );
      }
      return icon;
    }

    const match = /^data:([a-z+/-]+);base64,([A-Za-z0-9+/=]+)$/i.exec(icon);
    if (!match?.[1] || !match[2]) {
      throw new BadRequestException(
        'an uploaded icon must be a base64 data URI, e.g. data:image/svg+xml;base64,...',
      );
    }

    const [, mediaType, payload] = match;
    if (!SysService.ICON_MEDIA_TYPES.has(mediaType.toLowerCase())) {
      throw new BadRequestException(
        `unsupported image type '${mediaType}'; use SVG, PNG, WEBP, GIF or JPEG`,
      );
    }

    // Decoded length from the base64 length, without allocating the buffer:
    // four characters carry three bytes, minus whatever the padding stands in
    // for. A caller does not get to make the server materialise a large buffer
    // just to be told it is too large.
    const padding = payload.endsWith('==') ? 2 : payload.endsWith('=') ? 1 : 0;
    const decoded = Math.floor((payload.length * 3) / 4) - padding;
    if (decoded > SysService.ICON_MAX_DECODED_BYTES) {
      throw new BadRequestException(
        `the icon is ${Math.ceil(decoded / 1024)}KB; the limit is ${SysService.ICON_MAX_DECODED_BYTES / 1024}KB`,
      );
    }

    return icon;
  }

  /** Set or clear one entity's icon. `null` restores the default. */
  async setTableIcon(id: string, value: unknown) {
    const icon = this.validateIconValue(value);
    await this.findTableById(id);
    await this.db.kysely
      .updateTable('sys_table')
      .set({ icon, updated_at: new Date().toISOString(), updated_by: 'system' } as any)
      .where('sys_table_id', '=', id)
      .execute();
    this.busService.clearMetadataCache();
    return this.findTableById(id);
  }

  async updateTable(id: string, data: Record<string, unknown>) {
    const table = await this.findTableById(id);
    if ('table_name' in data && data.table_name !== table.table_name) {
      // Renaming the live bus_ table would desync it from the NestJS
      // controllers/services already generated against the old name.
      throw new ConflictException('The database table name cannot be changed after creation');
    }
    /*
     * This method spreads the caller's body into the UPDATE, so a dedicated
     * endpoint for one column is only a real check if the general one honours
     * it too. `icon` is the column that matters: it is TEXT, and the dashboard
     * renders it into an `<img src>`.
     */
    const patch = { ...data };
    if ('icon' in patch) patch.icon = this.validateIconValue(patch.icon);
    await this.db.kysely.updateTable('sys_table')
      .set({ ...patch, updated_at: new Date().toISOString(), updated_by: 'system' } as any)
      .where('sys_table_id', '=', id)
      .execute();
    return this.findTableById(id);
  }

  async deleteTable(id: string) {
    const table = await this.findTableById(id);
    const now = new Date().toISOString();

    const tabs = await (this.db.kysely.selectFrom('sys_tab' as any)
      .select(['sys_tab_id' as any])
      .where('sys_table_id' as any, '=', id) as any).execute();
    for (const tab of tabs as any[]) {
      await (this.db.kysely.updateTable('sys_field' as any)
        .set({ is_active: false, updated_at: now, updated_by: 'system' } as any)
        .where('sys_tab_id' as any, '=', tab.sys_tab_id) as any).execute();
    }
    await (this.db.kysely.updateTable('sys_tab' as any)
      .set({ is_active: false, updated_at: now, updated_by: 'system' } as any)
      .where('sys_table_id' as any, '=', id) as any).execute();
    await this.db.kysely.updateTable('sys_column')
      .set({ is_active: false, updated_at: now, updated_by: 'system' } as any)
      .where('sys_table_id', '=', id).execute();
    await this.db.kysely.updateTable('sys_table')
      .set({ is_active: false, updated_at: now, updated_by: 'system' } as any)
      .where('sys_table_id', '=', id).execute();

    const dbTableName = physicalTableName(table.table_name);
    await sql`DROP TABLE IF EXISTS ${sql.id(dbTableName)}`.execute(this.db.kysely);

    this.invalidateFieldCache();
    this.busService.clearMetadataCache();
    return { success: true };
  }

