  async getWindowHelp(tableName: string) {
    const table = await this.db.kysely
      .selectFrom('sys_table')
      .select(['sys_table_id', 'sys_window_id'])
      .where('table_name', '=', tableName)
      .where('is_active', '=', true)
      .executeTakeFirst();

    // The Application Dictionary windows — Business Rules, Workflow Designer,
    // Audit Log and the rest — describe how the application is built rather
    // than an entity, so they have no sys_table row to look up. Fall back to
    // the window's own name, which is what those screens pass, so they can
    // carry help like every other window instead of being the only screens in
    // the application that cannot explain themselves. A route (`/admin/roles`,
    // an administrative window's description) is accepted too, and an
    // administrative window wins a tie: a model may declare an entity named
    // like one, and the seed then names the administrative window
    // "Role Management", so the plain name would find the model's window.
    const windowId =
      table?.sys_window_id ??
      (
        await this.db.kysely
          .selectFrom('sys_window')
          .select(['sys_window_id'])
          .where((eb) => eb.or([eb('name', '=', tableName), eb('description', '=', tableName)]))
          .where('is_active', '=', true)
          .orderBy(sql`entity_type = 'S'`, 'desc')
          .executeTakeFirst()
      )?.sys_window_id;

    if (!windowId) return null;

    const [window, tabs, fields] = await Promise.all([
      this.db.kysely
        .selectFrom('sys_window')
        .select(['sys_window_id', 'name', 'description', 'help'])
        .where('sys_window_id', '=', windowId)
        .executeTakeFirst(),
      this.db.kysely
        .selectFrom('sys_tab')
        .select(['sys_tab_id', 'name', 'description', 'help', 'seq_no', 'tab_level'])
        .where('sys_window_id', '=', windowId)
        .where('is_active', '=', true)
        .orderBy('seq_no')
        .execute(),
      // Field help completes the picture the window and tab text only sketches:
      // which columns are mandatory, unique, or lookups into another entity.
      this.db.kysely
        .selectFrom('sys_field')
        .innerJoin('sys_tab', 'sys_tab.sys_tab_id', 'sys_field.sys_tab_id')
        .innerJoin('sys_column', 'sys_column.sys_column_id', 'sys_field.sys_column_id')
        .select([
          'sys_field.sys_field_id',
          'sys_field.sys_tab_id',
          'sys_field.name',
          'sys_field.help',
          'sys_field.seq_no',
          'sys_column.column_name',
          'sys_column.is_mandatory',
        ])
        .where('sys_tab.sys_window_id', '=', windowId)
        .where('sys_field.is_active', '=', true)
        .where('sys_field.is_displayed', '=', true)
        .where('sys_field.help', 'is not', null)
        .orderBy('sys_field.seq_no')
        .execute(),
    ]);

    return { window, tabs, fields };
  }

  async findAllSysUsers() {
    const rows = await this.db.kysely
      .selectFrom('sys_user as u')
      .leftJoin('sys_user_roles as ur', (join) =>
        join.onRef('ur.sys_user_id', '=', 'u.sys_user_id').on('ur.is_active', '=', true),
      )
      .leftJoin('sys_role as r', 'r.sys_role_id', 'ur.sys_role_id')
      .select([
        'u.sys_user_id',
        'u.name',
        'u.email',
        'u.is_active',
        'u.created_at',
        'r.name as role_name',
      ])
      .orderBy('u.name')
      .execute();

    const map = new Map<string, any>();
    for (const row of rows) {
      if (!map.has(row.sys_user_id)) {
        map.set(row.sys_user_id, {
          sys_user_id: row.sys_user_id,
          name: row.name,
          email: row.email,
          is_active: row.is_active,
          created_at: row.created_at,
          roles: [],
        });
      }
      if (row.role_name) map.get(row.sys_user_id).roles.push(row.role_name);
    }

    return { data: Array.from(map.values()) };
  }

  /**
   * Create a user account.
   *
   * There is no self-service sign-up: an administrator creates accounts here.
   * That means this has to do everything the bootstrap does for the first admin
   * — a Better Auth identity so the person can sign in, a `sys_user` row so the
   * dictionary and audit trail have somebody to attribute work to, the link
   * between the two, and a role.
   *
   * Better Auth owns the password. Rather than reimplement its hashing, this
   * calls its server-side sign-up directly — the public HTTP sign-up route is
   * blocked in main.ts, which closes the door to the outside without closing
   * this one, so there is exactly one place a credential is ever written.
   */
  async createSysUser(input: {
    name: string;
    email: string;
    password: string;
    roleName?: string;
  }) {
    const email = input.email.trim().toLowerCase();
    const name = input.name.trim();

    if (!email || !name) throw new ConflictException('A name and an email address are required');
    if ((input.password ?? '').length < 8) {
      throw new ConflictException('The password must be at least 8 characters');
    }

    const existing = await this.db.kysely
      .selectFrom('sys_user')
      .select('sys_user_id')
      .where('email', '=', email)
      .executeTakeFirst();
    if (existing) throw new ConflictException(`${email} already has an account`);

    // `auth` is the getter, not the instance — it throws if initAuth has not run.
    const { getAuth } = await import('../../lib/better-auth');
    try {
      await getAuth().api.signUpEmail({ body: { email, password: input.password, name } });
    } catch (error: any) {
      // Better Auth refuses duplicates itself; anything else is worth showing.
      throw new ConflictException(error?.message ?? 'Could not create the sign-in account');
    }

    const sysUserId = randomUUID();
    await this.db.kysely
      .insertInto('sys_user')
      .values({
        sys_user_id: sysUserId,
        name,
        email,
        password_hash: 'managed-by-better-auth',
        is_system_user: false,
        is_active: true,
        created_by: 'admin',
        updated_by: 'admin',
      } as any)
      .execute();

    await this.db.kysely
      .updateTable('user' as any)
      .set({ sysUserId } as any)
      .where('email' as any, '=', email)
      .execute();

    const role = await this.db.kysely
      .selectFrom('sys_role')
      .select(['sys_role_id'])
      .where('name', '=', input.roleName ?? 'User')
      .executeTakeFirst();

    if (role) {
      await this.db.kysely
        .insertInto('sys_user_roles')
        .values({
          sys_user_roles_id: randomUUID(),
          sys_user_id: sysUserId,
          sys_role_id: role.sys_role_id,
          entity_type: 'S',
          is_active: true,
          created_by: 'admin',
          updated_by: 'admin',
        } as any)
        .execute();
    }

    return { data: { sys_user_id: sysUserId, name, email, is_active: true } };
  }

  /**
   * Create a role. Administrators only (the controller's `@Roles('admin')`).
   *
   * A new role starts active and with no access of its own: what it may read
   * or change is granted afterwards, and a role nobody has granted anything
   * is a role that sees nothing — the safe default for a freshly made one.
   */
  async createSysRole(input: { name: string; description?: string; isMasterRole?: boolean }) {
    const name = (input.name ?? '').trim();
    if (!name) throw new ConflictException('A role needs a name');
    if (name.length > 100) throw new ConflictException('A role name is at most 100 characters');

    const existing = await this.db.kysely
      .selectFrom('sys_role')
      .select('sys_role_id')
      .where(sql`lower(name)`, '=', name.toLowerCase())
      .executeTakeFirst();
    if (existing) throw new ConflictException(`A role named "${name}" already exists`);

    const sysRoleId = randomUUID();
    const isMasterRole = input.isMasterRole === true;
    const description = input.description?.trim() || null;
    await this.db.kysely
      .insertInto('sys_role')
      .values({
        sys_role_id: sysRoleId,
        name,
        description,
        user_level: isMasterRole ? 'S' : 'C',
        is_master_role: isMasterRole,
        is_active: true,
        entity_type: 'D',
        created_by: 'admin',
        updated_by: 'admin',
      } as any)
      .execute();

    return {
      data: {
        sys_role_id: sysRoleId,
        name,
        description,
        is_master_role: isMasterRole,
        is_active: true,
      },
    };
  }

  async findAllSysRoles() {
    const roles = await this.db.kysely
      .selectFrom('sys_role')
      .select([
        'sys_role_id',
        'name',
        'description',
        'is_master_role',
        'is_active',
        'created_at',
      ])
      .where('is_active', '=', true)
      .orderBy('name')
      .execute();

    return { data: roles };
  }

  /** The two roles every generated application has, which the platform itself relies on. */
  private static readonly BUILT_IN_ROLES = new Set(['administrator', 'user']);

  /** Active accounts holding a role that makes them an administrator. */
  private administrators() {
    return this.db.kysely
      .selectFrom('sys_user as u')
      .innerJoin('sys_user_roles as ur', 'ur.sys_user_id', 'u.sys_user_id')
      .innerJoin('sys_role as r', 'r.sys_role_id', 'ur.sys_role_id')
      .select('u.sys_user_id')
      .distinct()
      .where('u.is_active', '=', true)
      .where('ur.is_active', '=', true)
      .where((eb) => eb.or([eb('r.is_master_role', '=', true), eb(sql`lower(r.name)`, '=', 'administrator')]));
  }

  /**
   * Tell every instance that an account's access changed, so its cached
   * answers go now. Role and grant tables announce themselves by trigger;
   * `sys_user` has none, so activating or removing an account says it here.
   */
  private async announceAccessChanged(): Promise<void> {
    await sql`select pg_notify('access_changed', 'sys_user')`.execute(this.db.kysely);
  }

  /** Refuse a change that would leave no active administrator at all. */
  private async keepAnAdministrator(id: string): Promise<void> {
    const admins = (await this.administrators().execute()).map((r) => r.sys_user_id);
    if (admins.includes(id) && admins.length === 1) {
      throw new ConflictException('This is the last administrator; give another account the role first');
    }
  }

  /**
   * Change an account. Every field is optional; what is sent is changed.
   *
   * - `email` changes the sign-in address too, so the person signs in with the
   *   new one from then on.
   * - `isActive: false` ends every session the account has, and SessionAuthGuard
   *   refuses an inactive account — deactivating is how to stop somebody now.
   * - `roleNames` replaces the account's roles. Better Auth's own `role` follows
   *   it (`admin` while Administrator is held), as the seed sets it.
   * - `password` sets a new one, hashed by Better Auth's own `hashPassword`.
   *
   * An administrator cannot deactivate themselves or take away the last
   * administrator's role: either would leave nobody able to undo it.
   */
  async updateSysUser(
    id: string,
    input: {
      name?: string;
      email?: string;
      password?: string;
      isActive?: boolean;
      roleNames?: string[];
    },
    callerSysUserId?: string,
  ) {
    const current = await this.db.kysely
      .selectFrom('sys_user')
      .select(['sys_user_id', 'name', 'email', 'is_active'])
      .where('sys_user_id', '=', id)
      .executeTakeFirst();
    if (!current) throw new NotFoundException('No such user');

    const changes: Record<string, any> = {};
    if (input.name !== undefined) {
      const name = input.name.trim();
      if (!name) throw new BadRequestException('A name is required');
      changes.name = name;
    }
    if (input.email !== undefined) {
      const email = input.email.trim().toLowerCase();
      if (!email) throw new BadRequestException('An email address is required');
      if (email !== current.email) {
        const taken = await this.db.kysely
          .selectFrom('sys_user')
          .select('sys_user_id')
          .where('email', '=', email)
          .where('sys_user_id', '!=', id)
          .executeTakeFirst();
        if (taken) throw new ConflictException(`${email} already has an account`);
        changes.email = email;
      }
    }
    if (input.password !== undefined && input.password.length < 8) {
      throw new BadRequestException('The password must be at least 8 characters');
    }

    let roleIds: string[] | undefined;
    let grantsAdmin: boolean | undefined;
    if (input.roleNames !== undefined) {
      const wanted = [...new Set(input.roleNames.map((n) => n.trim()).filter(Boolean))];
      const roles = wanted.length
        ? await this.db.kysely
            .selectFrom('sys_role')
            .select(['sys_role_id', 'name', 'is_master_role'])
            .where('is_active', '=', true)
            .where(sql`lower(name)`, 'in', wanted.map((n) => n.toLowerCase()))
            .execute()
        : [];
      const missing = wanted.filter((n) => !roles.some((r) => r.name.toLowerCase() === n.toLowerCase()));
      if (missing.length) throw new BadRequestException(`No such role: ${missing.join(', ')}`);
      roleIds = roles.map((r) => r.sys_role_id);
      grantsAdmin = roles.some((r) => r.is_master_role || r.name.toLowerCase() === 'administrator');
    }

    const deactivating = input.isActive === false && current.is_active;
    const losingAdmin = grantsAdmin === false;
    if ((deactivating || losingAdmin) && id === callerSysUserId) {
      throw new ConflictException(
        deactivating
          ? 'You cannot deactivate your own account'
          : 'You cannot remove the administrator role from your own account',
      );
    }
    if (deactivating || losingAdmin) await this.keepAnAdministrator(id);

    await this.db.kysely.transaction().execute(async (trx) => {
      const authUser = await trx
        .selectFrom('user' as any)
        .select(['id' as any])
        .where((eb: any) => eb.or([eb('sysUserId', '=', id), eb('email', '=', current.email)]))
        .executeTakeFirst() as { id: string } | undefined;

      const sysChanges: Record<string, any> = { updated_by: callerSysUserId ?? 'admin', updated_at: new Date() };
      if (changes.name !== undefined) sysChanges.name = changes.name;
      if (changes.email !== undefined) sysChanges.email = changes.email;
      if (input.isActive !== undefined) sysChanges.is_active = input.isActive;
      await trx.updateTable('sys_user').set(sysChanges as any).where('sys_user_id', '=', id).execute();

      if (authUser) {
        const authChanges: Record<string, any> = { updatedAt: new Date() };
        if (changes.name !== undefined) authChanges.name = changes.name;
        if (changes.email !== undefined) authChanges.email = changes.email;
        if (grantsAdmin !== undefined) authChanges.role = grantsAdmin ? 'admin' : 'user';
        await trx.updateTable('user' as any).set(authChanges as any).where('id' as any, '=', authUser.id).execute();

        if (input.password !== undefined) {
          const { hashPassword } = await import('better-auth/crypto');
          await trx
            .updateTable('account' as any)
            .set({ password: await hashPassword(input.password), updatedAt: new Date() } as any)
            .where('userId' as any, '=', authUser.id)
            .where('providerId' as any, '=', 'credential')
            .execute();
        }
        // A new password or a deactivation ends the sessions already open.
        if (deactivating || input.password !== undefined) {
          await trx.deleteFrom('session' as any).where('userId' as any, '=', authUser.id).execute();
        }
      }

      if (roleIds !== undefined) {
        await trx.deleteFrom('sys_user_roles').where('sys_user_id', '=', id).execute();
        for (const roleId of roleIds) {
          await trx
            .insertInto('sys_user_roles')
            .values({
              sys_user_roles_id: randomUUID(),
              sys_user_id: id,
              sys_role_id: roleId,
              entity_type: 'S',
              is_active: true,
              created_by: callerSysUserId ?? 'admin',
              updated_by: callerSysUserId ?? 'admin',
            } as any)
            .execute();
        }
      }
    });

    if (input.isActive !== undefined && input.isActive !== current.is_active) await this.announceAccessChanged();

    const users = await this.findAllSysUsers();
    return { data: users.data.find((u: any) => u.sys_user_id === id) };
  }

  /**
   * Delete an account: its sign-in identity, sessions and role links go with
   * it, and the change log keeps its rows with the person set to null. Never
   * the caller's own account, and never the last administrator.
   */
  async deleteSysUser(id: string, callerSysUserId?: string) {
    if (id === callerSysUserId) throw new ConflictException('You cannot delete your own account');
    const current = await this.db.kysely
      .selectFrom('sys_user')
      .select(['sys_user_id', 'email'])
      .where('sys_user_id', '=', id)
      .executeTakeFirst();
    if (!current) throw new NotFoundException('No such user');

    await this.keepAnAdministrator(id);

    await this.db.kysely.transaction().execute(async (trx) => {
      // session and account cascade from "user".
      await trx
        .deleteFrom('user' as any)
        .where((eb: any) => eb.or([eb('sysUserId', '=', id), eb('email', '=', current.email)]))
        .execute();
      await trx.updateTable('sys_user').set({ supervisor_id: null } as any).where('supervisor_id', '=', id).execute();
      await trx.deleteFrom('sys_user').where('sys_user_id', '=', id).execute();
    });
    await this.announceAccessChanged();
    return { success: true };
  }

  /**
   * Change a role. The description and master flag can always change. The name
   * can change only on a role no access rule names: `%%rbac` rules match a
   * role by name (sys_operation_access.role_name), so renaming one the model
   * declared would silently take its access away. Administrator and User keep
   * their names for the same reason — the platform looks them up by name.
   */
  async updateSysRole(id: string, input: { name?: string; description?: string; isMasterRole?: boolean }) {
    const role = await this.db.kysely
      .selectFrom('sys_role')
      .select(['sys_role_id', 'name', 'description', 'is_master_role', 'is_active'])
      .where('sys_role_id', '=', id)
      .executeTakeFirst();
    if (!role) throw new NotFoundException('No such role');

    const changes: Record<string, any> = { updated_at: new Date() };
    if (input.name !== undefined && input.name.trim() !== role.name) {
      const name = input.name.trim();
      if (!name) throw new BadRequestException('A role needs a name');
      if (name.length > 100) throw new BadRequestException('A role name is at most 100 characters');
      if (SysService.BUILT_IN_ROLES.has(role.name.toLowerCase())) {
        throw new ConflictException(`"${role.name}" is built in and keeps its name`);
      }
      const fold = (s: string) => s.trim().toLowerCase().replace(/[\s\-_]+/g, '');
      const ruleNames = await this.db.kysely
        .selectFrom('sys_operation_access' as any)
        .select('role_name' as any)
        .distinct()
        .execute()
        .catch(() => [] as any[]);
      if ((ruleNames as any[]).some((r) => fold(r.role_name) === fold(role.name))) {
        throw new ConflictException(
          `"${role.name}" is named by the model's access rules, so renaming it would take its access away. Change the model instead.`,
        );
      }
      const taken = await this.db.kysely
        .selectFrom('sys_role')
        .select('sys_role_id')
        .where(sql`lower(name)`, '=', name.toLowerCase())
        .where('sys_role_id', '!=', id)
        .executeTakeFirst();
      if (taken) throw new ConflictException(`A role named "${name}" already exists`);
      changes.name = name;
    }
    if (input.description !== undefined) changes.description = input.description.trim() || null;
    if (input.isMasterRole !== undefined) {
      if (role.name.toLowerCase() === 'administrator' && input.isMasterRole === false) {
        throw new ConflictException('Administrator stays a master role');
      }
      changes.is_master_role = input.isMasterRole;
      changes.user_level = input.isMasterRole ? 'S' : 'C';
    }

    await this.db.kysely.updateTable('sys_role').set(changes as any).where('sys_role_id', '=', id).execute();
    const updated = await this.db.kysely
      .selectFrom('sys_role')
      .select(['sys_role_id', 'name', 'description', 'is_master_role', 'is_active', 'created_at'])
      .where('sys_role_id', '=', id)
      .executeTakeFirstOrThrow();
    return { data: updated };
  }

  /**
   * Delete a role. Administrator and User are built in and stay. A role
   * somebody still holds is refused with how many, rather than quietly taking
   * their access away — reassign them first. Its grants go with it.
   */
  async deleteSysRole(id: string) {
    const role = await this.db.kysely
      .selectFrom('sys_role')
      .select(['sys_role_id', 'name', 'role_key'])
      .where('sys_role_id', '=', id)
      .executeTakeFirst();
    if (!role) throw new NotFoundException('No such role');
    if (SysService.BUILT_IN_ROLES.has(role.name.toLowerCase())) {
      throw new ConflictException(`"${role.name}" is built in and cannot be deleted`);
    }

    const held = await this.db.kysely
      .selectFrom('sys_user_roles')
      .select(sql<number>`count(*)`.as('n'))
      .where('sys_role_id', '=', id)
      .where('is_active', '=', true)
      .executeTakeFirst();
    const holders = Number(held?.n ?? 0);
    if (holders > 0) {
      throw new ConflictException(
        `${holders} ${holders === 1 ? 'account holds' : 'accounts hold'} "${role.name}"; give them another role first`,
      );
    }

    await this.db.kysely.transaction().execute(async (trx) => {
      await trx.updateTable('sys_user').set({ default_sys_role_id: null } as any).where('default_sys_role_id', '=', id).execute();
      if (role.role_key) {
        const sharing = await trx
          .selectFrom('sys_role')
          .select('sys_role_id')
          .where('role_key', '=', role.role_key)
          .where('sys_role_id', '!=', id)
          .executeTakeFirst();
        if (!sharing) {
          await (trx as any).deleteFrom('sys_access_grant').where('role_key', '=', role.role_key).execute();
        }
      }
      // sys_user_roles and sys_access cascade from sys_role.
      await trx.deleteFrom('sys_role').where('sys_role_id', '=', id).execute();
    });
    return { success: true };
  }

  // ============================================================
  // SYS_ELEMENT
  // ============================================================

  async findAllElements(options: PaginationOptions = {}, filters: Record<string, any> = {}) {
    const { page = 1, limit = 100 } = options;
    const offset = (page - 1) * limit;

    let query = (this.db.kysely as any).selectFrom('sys_element').selectAll();
    if (Object.keys(filters).length > 0) query = this.applyFilters(query, filters);

    const [data, countRow] = await Promise.all([
      query.orderBy('name').limit(limit).offset(offset).execute(),
      query.clearSelect().select((eb: any) => eb.fn.countAll().as('count')).executeTakeFirst(),
    ]);

    return { data, meta: { total: Number(countRow?.count ?? 0), page, pageSize: limit } };
  }

  async findElementById(id: string) {
    const el = await (this.db.kysely as any).selectFrom('sys_element').selectAll()
      .where('sys_element_id', '=', id).executeTakeFirst();
    if (!el) throw new NotFoundException(`Element with ID ${id} not found`);
    return el;
  }

  async createElement(data: Record<string, unknown>) {
    const row = await (this.db.kysely as any).insertInto('sys_element')
      .values({ ...data, created_at: new Date(), updated_at: new Date() })
      .returningAll()
      .executeTakeFirstOrThrow();
    return row;
  }

  async updateElement(id: string, data: Record<string, unknown>) {
    const row = await (this.db.kysely as any).updateTable('sys_element')
      .set({ ...data, updated_at: new Date() })
      .where('sys_element_id', '=', id)
      .returningAll()
      .executeTakeFirst();
    if (!row) throw new NotFoundException(`Element with ID ${id} not found`);
    return row;
  }

  async deleteElement(id: string) {
    await (this.db.kysely as any).deleteFrom('sys_element')
      .where('sys_element_id', '=', id)
      .execute();
  }

  /**
   * Empty every business table, and nothing else.
   *
   * A generated application arrives with seeded rows so that it can be looked
   * at, and whoever has finished looking wants their own data in it — which
   * otherwise meant deleting every record by hand, entity by entity, or
   * re-running the whole setup and losing everything else they had done.
   *
   * **Business tables only.** The dictionary, the roles, the users, the rules
   * and the workflow definitions are what the application *is*, not what it
   * holds; emptying those leaves a running application with no screens.
   *
   * One `TRUNCATE` naming every `bus_` table at once, so the foreign keys
   * between them need no ordering — and deliberately no `CASCADE`, which would
   * reach the audit trail. A purge that erased the record of itself would be
   * the wrong shape entirely.
   *
   * Administrator-only, and not by a decorator: `DictionaryWriteGuard` already
   * refuses every non-GET on this controller from anyone else.
   */
  async purgeBusinessData(): Promise<{ deleted: number; tables: number }> {
    const tables = [{{#each entities}}'{{tableName}}'{{#unless @last}}, {{/unless}}{{/each}}];
    if (tables.length === 0) return { deleted: 0, tables: 0 };

    let deleted = 0;
    for (const table of tables) {
      const row = await sql<{ count: string }>`
        SELECT COUNT(*)::int AS count FROM ${sql.id(table)}
      `.execute(this.db.kysely as any);
      deleted += Number(row.rows[0]?.count ?? 0);
    }

    await sql`
      TRUNCATE TABLE ${sql.join(tables.map((table) => sql.id(table)), sql`, `)}
    `.execute(this.db.kysely as any);

    return { deleted, tables: tables.length };
  }

  // ============================================================================
  // Report Design methods
  // ============================================================================

  async findAllReportDesigns() {
    const rows = await this.db.kysely
      .selectFrom('sys_report_designs')
      .selectAll()
      .orderBy('table_name', 'asc')
      .execute();
    return rows;
  }

  async findReportDesignByTable(tableName: string) {
    const row = await this.db.kysely
      .selectFrom('sys_report_designs')
      .selectAll()
      .where('table_name', '=', tableName)
      .executeTakeFirst();
    return row ?? null;
  }

  async upsertReportDesign(data: { table_name: string; name?: string; layout?: object }) {
    const existing = await this.findReportDesignByTable(data.table_name);
    if (existing) {
      const updated = await this.db.kysely
        .updateTable('sys_report_designs')
        .set({
          name: data.name ?? existing.name,
          layout: data.layout !== undefined ? JSON.stringify(data.layout) : existing.layout,
          updated_at: new Date(),
        })
        .where('table_name', '=', data.table_name)
        .returningAll()
        .executeTakeFirst();
      return updated;
    }
    const created = await this.db.kysely
      .insertInto('sys_report_designs')
      .values({
        table_name: data.table_name,
        name: data.name ?? 'Default Report',
        layout: data.layout !== undefined ? JSON.stringify(data.layout) : null,
      })
      .returningAll()
      .executeTakeFirst();
    return created;
  }

  async deleteReportDesign(tableName: string) {
    await this.db.kysely
      .deleteFrom('sys_report_designs')
      .where('table_name', '=', tableName)
      .execute();
    return { success: true };
  }
}

/**
 * System Module (Application Dictionary)
 *
 * Handles all sys_ prefixed tables:
 * - sys_table, sys_column, sys_field
 * - sys_category (entity grouping for the dashboard)
 *
 * Generated: {{now}}
 */

import { Module } from '@nestjs/common';
import { DatabaseModule } from '../../database/database.module';
import { BusModule } from '../bus/bus.module';
import { SysCategoryController } from './controllers/sys-category.controller';
import { SysReportController } from './controllers/sys-report.controller';
import { SysController } from './sys.controller';
import { SysCategoryService } from './services/sys-category.service';
import { SysReportService } from './services/sys-report.service';
import { SystemConfigService } from './services/system-config.service';
import { SysService } from './sys.service';

@Module({
  imports: [DatabaseModule, BusModule],
  controllers: [SysController, SysCategoryController, SysReportController],
  providers: [SysService, SysCategoryService, SysReportService, SystemConfigService],
  exports: [SysService, SysCategoryService, SysReportService, SystemConfigService],
})
export class SysModule {}

import { BadRequestException, ConflictException, Injectable, NotFoundException } from "@nestjs/common";
import { type Kysely, sql } from "kysely";
import { InjectDatabase } from "../../database/database.service.decorator";
import {
  LIFECYCLES,
  lifecycleFromDiagram,
  lifecycleOf,
  modelLifecycleOf,
  normalizeLifecycleEvent,
  type Lifecycle,
} from "../../common/lifecycle";
import { compileAutomationBpmn, tableForEntity } from "./automation-compiler";
import { LifecycleStore } from "./lifecycle-store.service";

/** Who switched a move grant off because its edge left the flow — and may switch it back on. */
const LIFECYCLE_EDIT = "lifecycle-edit";

/**
 * The table a status flow belongs to, by any spelling of its entity
 * (`BookingChange`, `booking_change`, `bus_booking_change`).
 */
export function lifecycleTableFor(entity: string): string {
  const direct = tableForEntity(entity ?? "");
  if (LIFECYCLES[direct]) return direct;
  const flat = (name: string) => name.toLowerCase().replace(/^bus_/, "").replace(/_/g, "");
  const wanted = flat(entity ?? "");
  return Object.keys(LIFECYCLES).find((table) => flat(table) === wanted) ?? direct;
}

export type WorkflowDefinitionDto = {
  name: string;
  entityName: string;
  /**
   * Which write runs it. `ENTER:<STATE>` binds it to the move into a state of the
   * record type's status flow (and `TRANSITION:<EVENT>` to one drawn move): it
   * runs in the second transaction of the button press, never on a plain save.
   */
  operation: "CREATE" | "UPDATE" | "DELETE" | "ALL" | `ENTER:${string}` | `TRANSITION:${string}`;
  /** BPMN diagrams carry XML; automations carry mermaid. Exactly one is required. */
  bpmnXml?: string;
  /** Mermaid with `%%` directives, as the automation builder writes it. */
  mermaid?: string;
  /**
   * "bpmn", "automation", or "state". Defaults to bpmn, which is what every older row is.
   * A "state" definition is a record type's status flow: saving it is what the
   * application runs from then on (LifecycleStore), in place of the model's.
   */
  kind?: "bpmn" | "automation" | "state";
  /** Ignored for a status flow: its column is the model's (common/lifecycle.ts). */
  statusField?: string;
  /** Ignored for a status flow: `mermaid` is read, the same way the generator reads the model's. */
  transitions?: Array<{ from: string; to: string; name?: string }>;
  description?: string;
  isActive?: boolean;
  /**
   * How the definition is reached.
   *   automatic  run on every write matching entityName + operation
   *   rule       run only when a rule's trigger-workflow action names it
   * Defaults to automatic, which is what an unmarked definition has always done.
   */
  triggerType?: "automatic" | "rule";
};

const OPERATION = /^(CREATE|UPDATE|DELETE|ALL|ENTER:[A-Z0-9_]+|TRANSITION:[A-Z0-9_]+)$/;

/**
 * An operation is one of the four writes, or a binding to a move. A binding has
 * to name something the record type's status flow draws: stored against a state
 * that is not there, it would be accepted, listed in Rules and workflows, and
 * never run.
 */
export function assertOperation(entityName: string, operation: string): void {
  if (!OPERATION.test(operation)) {
    throw new BadRequestException(
      `"${operation}" is not an operation. Use CREATE, UPDATE, DELETE, ALL, ENTER:<STATE> or TRANSITION:<EVENT>.`,
    );
  }
  const [kind, wanted] = operation.split(":");
  if (!wanted) return;
  const lifecycle = lifecycleOf(lifecycleTableFor(entityName));
  if (!lifecycle?.hasMachine) {
    throw new BadRequestException(
      `${entityName} has no status flow, so ${operation} can never run. Draw one, or use UPDATE.`,
    );
  }
  const drawn =
    kind === "ENTER"
      ? lifecycle.edges.some((edge) => normalizeLifecycleEvent(edge.to).toUpperCase() === wanted)
      : lifecycle.edges.some((edge) => edge.event.toUpperCase() === wanted);
  if (!drawn) {
    const names = lifecycle.edges.map((edge) => (kind === "ENTER" ? edge.to : edge.event));
    throw new BadRequestException(
      `${entityName}'s status flow does not draw "${wanted.toLowerCase()}". It draws: ${[...new Set(names)].join(", ")}.`,
    );
  }
}

/**
 * Content fields a model-owned definition will not accept through the API.
 *
 * `isActive` is deliberately absent: switching a workflow off is an operational
 * decision an admin should be able to take without editing the model. The next
 * generation turns it back on, which is the honest outcome — the model says it
 * should be running.
 */
const MODEL_OWNED_FIELDS = [
  "name",
  "entityName",
  "operation",
  "bpmnXml",
  "mermaid",
  "description",
  "triggerType",
  "transitions",
] as const;

@Injectable()
export class WorkflowDefinitionsService {
  constructor(
    @InjectDatabase() private readonly db: Kysely<any>,
    private readonly lifecycles: LifecycleStore,
  ) {}

  /**
   * A page of definitions, newest first.
   *
   * Paged rather than unbounded: an app that has been running a while
   * accumulates definitions faster than anyone deletes them, and a list
   * endpoint that returns all of them eventually times out the page that
   * depends on it. 200 is the default because it fills the longest rail the
   * builder draws without a second request.
   */
  async findAll(filters?: {
    entityName?: string;
    operation?: string;
    isActive?: boolean;
    kind?: string;
    limit?: number;
    offset?: number;
  }) {
    const limit = Math.min(Math.max(filters?.limit ?? 200, 1), 200);
    const offset = Math.max(filters?.offset ?? 0, 0);

    const where = <T extends { where: any }>(q: T): T => {
      let query: any = q;
      if (filters?.entityName) query = query.where("entity_name", "=", filters.entityName);
      if (filters?.operation) query = query.where("operation", "=", filters.operation);
      if (filters?.isActive !== undefined) query = query.where("is_active", "=", filters.isActive);
      if (filters?.kind) query = query.where("kind", "=", filters.kind);
      return query as T;
    };

    const items = await where(this.db.selectFrom("sys_workflow_definitions").selectAll())
      .orderBy("created_at", "desc")
      .limit(limit)
      .offset(offset)
      .execute();

    const counted = await where(
      this.db
        .selectFrom("sys_workflow_definitions")
        .select((eb: any) => eb.fn.countAll().as("total"))
    ).executeTakeFirst();

    const total = Number((counted as { total?: number | string })?.total ?? items.length);
    return { items, total, limit, offset, hasMore: offset + items.length < total };
  }

  async findOne(id: string) {
    const def = await this.db
      .selectFrom("sys_workflow_definitions")
      .selectAll()
      .where("id", "=", id)
      .executeTakeFirst();
    if (!def) throw new NotFoundException(`Workflow definition ${id} not found`);
    return def;
  }

  async findActiveForEntity(entityName: string, operation: string) {
    // Match definitions stored under either the singular base name (e.g. 'account')
    // or the full bus_ table name (e.g. 'bus_account').
    const flat = entityName.toLowerCase().replace(/^bus_/, "").replace(/_/g, "");
    return this.db
      .selectFrom("sys_workflow_definitions")
      .selectAll()
      .where((eb) => eb(sql<string>`replace(lower(entity_name), '_', '')`, "in", [flat, `bus${flat}`]))
      .where((eb) =>
        eb.or([eb("operation", "=", operation.toUpperCase()), eb("operation", "=", "ALL")])
      )
      .where("is_active", "=", true)
      .orderBy("created_at", "asc")
      .execute();
  }

  async create(dto: WorkflowDefinitionDto, userId?: string) {
    // A definition is either a BPMN diagram or a mermaid automation. Demanding
    // BPMN of both is what stopped the automation builder saving anything.
    const kind = dto.kind ?? (dto.mermaid?.trim() ? "automation" : "bpmn");

    if (kind === "state") return this.createFlow(dto, userId);
    if (kind === "automation") {
      if (!dto.mermaid?.trim()) throw new BadRequestException("mermaid is required");
      if (!/^\s*(flowchart|graph)\b/m.test(dto.mermaid)) {
        throw new BadRequestException("An automation must be a mermaid flowchart");
      }
    } else {
      if (!dto.bpmnXml?.trim()) throw new BadRequestException("bpmnXml is required");
      if (!dto.bpmnXml.includes("<bpmn:")) throw new BadRequestException("Invalid BPMN XML");
    }

    assertOperation(dto.entityName, dto.operation ?? "ALL");

    const [result] = await this.db
      .insertInto("sys_workflow_definitions")
      .values({
        name: dto.name,
        entity_name: dto.entityName,
        operation: dto.operation ?? "ALL",
        // An automation built in the application stores its flowchart; what the
        // executor runs is the BPMN compiled from it, written here so that
        // publishing the automation is what makes it do something.
        bpmn_xml:
          dto.bpmnXml ??
          (kind === "automation" && dto.mermaid
            ? compileAutomationBpmn(dto.mermaid, tableForEntity(dto.entityName), tableForEntity)
            : null),
        mermaid_code: dto.mermaid ?? null,
        kind,
        description: dto.description ?? null,
        trigger_type: dto.triggerType ?? "automatic",
        // Anything created through the API was built in the app, so the model
        // seed leaves it alone.
        source: "designer",
        is_active: dto.isActive ?? true,
        created_by: userId ?? null,
      } as any)
      .returningAll()
      .execute();
    return result;
  }

  async update(id: string, dto: Partial<WorkflowDefinitionDto>) {
    const existing = await this.findOne(id);

    // A definition declared by a %%workflow section belongs to the model. The
    // next generation rewrites it, so accepting an edit here would look like it
    // worked and then quietly vanish.
    if ((existing as any).kind === "state") return this.updateFlow(existing as any, dto);
    if ((existing as any).source === "model") {
      const attempted = MODEL_OWNED_FIELDS.filter((field) => dto[field] !== undefined);
      if (attempted.length > 0) {
        throw new BadRequestException(
          `"${(existing as any).name}" is declared in the model — edit the %%workflow section and regenerate. ` +
            `Rejected: ${attempted.join(", ")}.`,
        );
      }
    }

    const updates: Record<string, unknown> = { updated_at: new Date() };
    if (dto.name !== undefined) updates.name = dto.name;
    if (dto.entityName !== undefined) updates.entity_name = dto.entityName;
    if (dto.operation !== undefined) {
      assertOperation(dto.entityName ?? (existing as any).entity_name, dto.operation);
      updates.operation = dto.operation;
    }
    if (dto.bpmnXml !== undefined) updates.bpmn_xml = dto.bpmnXml;
    // The automation builder's whole document. Leaving it out of the update
    // meant every save — the draft and Publish alike — kept the steps the
    // automation was created with, which for a new one is none at all.
    if (dto.mermaid !== undefined) {
      if (!/^\s*(flowchart|graph)\b/m.test(dto.mermaid)) {
        throw new BadRequestException("An automation must be a mermaid flowchart");
      }
      updates.mermaid_code = dto.mermaid;
      // Recompiled with it, or a saved edit would keep running the steps it was
      // created with. An explicit `bpmnXml` in the same call wins.
      if (dto.bpmnXml === undefined && (existing as any).kind === "automation") {
        updates.bpmn_xml = compileAutomationBpmn(
          dto.mermaid,
          tableForEntity(dto.entityName ?? (existing as any).entity_name),
          tableForEntity,
        );
      }
    }
    if (dto.description !== undefined) updates.description = dto.description;
    if (dto.isActive !== undefined) updates.is_active = dto.isActive;
    if (dto.triggerType !== undefined) updates.trigger_type = dto.triggerType;

    const [result] = await this.db
      .updateTable("sys_workflow_definitions")
      .set(updates as any)
      .where("id", "=", id)
      .returningAll()
      .execute();
    return result;
  }

  async remove(id: string) {
    const existing = await this.findOne(id);
    if ((existing as any).kind === "state") return this.removeFlow(existing as any);
    if ((existing as any).source === "model") {
      throw new BadRequestException(
        `"${(existing as any).name}" is declared in the model — remove the %%workflow section and regenerate. ` +
          "Deactivate it instead if you need it off now.",
      );
    }
    await this.db.deleteFrom("sys_workflow_definitions").where("id", "=", id).execute();
    return { deleted: true };
  }

  // ── Status flows ─────────────────────────────────────────────────────────
  //
  // A kind = 'state' row is the flow of record for its table: LifecycleStore
  // loads it into common/lifecycle.ts, and every reader — the action buttons, the
  // transition API, the save pipeline, the guard — follows it. A table with no
  // row runs the model's flow, so removing the row is how an edited flow goes
  // back. Rows are filed under the table name and always `source = 'designer'`:
  // the seed never writes one, so regenerating never overwrites an edit.

  /** The diagram compiled for its table, or a 400 saying why it cannot be a flow. */
  private compileFlow(table: string, mermaid: string | undefined): Lifecycle {
    if (!mermaid?.trim()) throw new BadRequestException("mermaid is required");
    const { lifecycle, problems } = lifecycleFromDiagram(table, mermaid);
    if (!lifecycle) throw new BadRequestException(problems.join(" "));
    return lifecycle;
  }

  private async createFlow(dto: WorkflowDefinitionDto, userId?: string) {
    const table = lifecycleTableFor(dto.entityName);
    const next = this.compileFlow(table, dto.mermaid);
    const taken = await this.db
      .selectFrom("sys_workflow_definitions")
      .select("id")
      .where("kind", "=", "state")
      .where("entity_name", "in", [table, dto.entityName])
      .executeTakeFirst();
    if (taken) throw new BadRequestException(`${dto.entityName} already has a status flow — edit that one.`);

    const created = await this.db.transaction().execute(async (trx) => {
      await this.moveTo(trx, table, next);
      const [row] = await trx
        .insertInto("sys_workflow_definitions")
        .values({
          name: dto.name,
          entity_name: table,
          operation: "UPDATE",
          bpmn_xml: null,
          mermaid_code: dto.mermaid,
          kind: "state",
          lifecycle: JSON.stringify(next),
          description: dto.description ?? null,
          trigger_type: "automatic",
          source: "designer",
          is_active: dto.isActive ?? true,
          created_by: userId ?? null,
        } as any)
        .returningAll()
        .execute();
      return row;
    });
    await this.lifecycles.reload();
    return created;
  }

  private async updateFlow(existing: Record<string, any>, dto: Partial<WorkflowDefinitionDto>) {
    const table = lifecycleTableFor(existing.entity_name);
    const mermaid = dto.mermaid ?? existing.mermaid_code ?? "";
    const active = dto.isActive ?? existing.is_active !== false;
    // Switched off, the table runs the model's flow again.
    const next = active ? this.compileFlow(table, mermaid) : modelLifecycleOf(table);
    const saved = await this.db.transaction().execute(async (trx) => {
      if (next) await this.moveTo(trx, table, next);
      const [row] = await trx
        .updateTable("sys_workflow_definitions")
        .set({
          updated_at: new Date(),
          entity_name: table,
          mermaid_code: mermaid,
          lifecycle: active && next ? JSON.stringify(next) : null,
          is_active: active,
          source: "designer",
          ...(dto.name !== undefined ? { name: dto.name } : {}),
          ...(dto.description !== undefined ? { description: dto.description } : {}),
        } as any)
        .where("id", "=", existing.id)
        .returningAll()
        .execute();
      return row;
    });
    await this.lifecycles.reload();
    return saved;
  }

  private async removeFlow(existing: Record<string, any>) {
    const table = lifecycleTableFor(existing.entity_name);
    const model = modelLifecycleOf(table);
    await this.db.transaction().execute(async (trx) => {
      if (model?.hasMachine) await this.moveTo(trx, table, model);
      else await sql`DELETE FROM sys_workflow_transitions WHERE table_name = ${table}`.execute(trx);
      await trx.deleteFrom("sys_workflow_definitions").where("id", "=", existing.id).execute();
    });
    await this.lifecycles.reload();
    return { deleted: true, revertedToModel: !!model?.hasMachine };
  }

  /**
   * Everything that has to agree with a table's flow before it runs, in the
   * caller's transaction:
   *
   *   - no record may sit in a state the new flow drops (409 LIFECYCLE_STATES_IN_USE,
   *     naming each state and how many records are in it) — a record must always
   *     have a way out of where it is
   *   - move grants follow the edges: a grant is keyed by from → to, so one on a
   *     kept edge keeps working and takes the edge's new event name; one on an
   *     edge the flow drops is switched off, not deleted, so drawing the edge
   *     again restores the restriction instead of opening the move to everyone
   *     who may update (the change fires `access_changed`)
   *   - `sys_workflow_transitions`, the edges GET /workflows/transitions lists
   */
  private async moveTo(trx: Kysely<any>, table: string, next: Lifecycle) {
    const current = lifecycleOf(table);
    if (current) {
      const dropped = current.values.filter((value) => !next.values.includes(value));
      if (dropped.length > 0) {
        const column = sql.ref(current.column);
        const { rows } = await sql<{ state: string; n: number }>`
          SELECT ${column} AS state, count(*)::int AS n FROM ${sql.table(table)}
          WHERE ${column} IN (${sql.join(dropped)}) AND deleted_at IS NULL
          GROUP BY ${column}`.execute(trx);
        const inUse = rows.filter((row) => row.n > 0);
        if (inUse.length > 0) {
          const listed = inUse.map((row) => `"${row.state}" (${row.n})`).join(", ");
          throw new ConflictException({
            message:
              `Records are still in ${listed}, which this flow no longer has. ` +
              "Move them to a state the flow keeps, then save it again.",
            error: "Conflict",
            details: {
              code: "LIFECYCLE_STATES_IN_USE",
              table,
              states: inUse.map((row) => ({ state: row.state, records: row.n })),
            },
          });
        }
      }
    }

    const grants = (await trx
      .selectFrom("sys_access_grant" as any)
      .select(["sys_access_grant_id", "action", "from_state", "to_state", "role_name", "is_active", "updated_by"] as any)
      .where("kind" as any, "=", "move")
      .where("table_name" as any, "=", table)
      .execute()) as Array<Record<string, any>>;
    for (const grant of grants) {
      const edges = next.edges.filter((edge) => edge.from === grant.from_state && edge.to === grant.to_state);
      if (edges.length === 0) {
        if (grant.is_active) {
          await trx
            .updateTable("sys_access_grant" as any)
            .set({ is_active: false, updated_by: LIFECYCLE_EDIT, updated_at: new Date() } as any)
            .where("sys_access_grant_id" as any, "=", grant.sys_access_grant_id)
            .execute();
        }
        continue;
      }
      const edge = edges.find((candidate) => candidate.event === grant.action) ?? edges[0]!;
      const action = edge.event || `${edge.from}->${edge.to}`;
      const revive = !grant.is_active && grant.updated_by === LIFECYCLE_EDIT;
      if (action === grant.action && !revive) continue;
      const clash = await trx
        .selectFrom("sys_access_grant" as any)
        .select("sys_access_grant_id" as any)
        .where("kind" as any, "=", "move")
        .where("table_name" as any, "=", table)
        .where("action" as any, "=", action)
        .where("from_state" as any, "=", grant.from_state)
        .where("to_state" as any, "=", grant.to_state)
        .where("sys_access_grant_id" as any, "!=", grant.sys_access_grant_id)
        .where("role_name" as any, "=", grant.role_name)
        .executeTakeFirst();
      await trx
        .updateTable("sys_access_grant" as any)
        .set({
          ...(clash ? {} : { action }),
          ...(revive ? { is_active: true } : {}),
          updated_by: LIFECYCLE_EDIT,
          updated_at: new Date(),
        } as any)
        .where("sys_access_grant_id" as any, "=", grant.sys_access_grant_id)
        .execute();
    }

    await sql`DELETE FROM sys_workflow_transitions WHERE table_name = ${table}`.execute(trx);
    for (const edge of next.edges) {
      await sql`
        INSERT INTO sys_workflow_transitions (table_name, status_field, from_state, to_state, transition_name)
        VALUES (${table}, ${next.column}, ${edge.from}, ${edge.to}, ${edge.event || null})
        ON CONFLICT (table_name, status_field, from_state, to_state) DO NOTHING`.execute(trx);
    }
  }
}

import { Module } from "@nestjs/common";
import { DatabaseModule } from "../../database/database.module";
import { LifecycleStore } from "./lifecycle-store.service";
import { LifecyclesController } from "./lifecycles.controller";
import { WorkflowDefinitionsController } from "./workflow-definitions.controller";
import { WorkflowDefinitionsService } from "./workflow-definitions.service";

@Module({
  imports: [DatabaseModule],
  controllers: [WorkflowDefinitionsController, LifecyclesController],
  providers: [WorkflowDefinitionsService, LifecycleStore],
  exports: [WorkflowDefinitionsService, LifecycleStore],
})
export class WorkflowDefinitionsModule {}

import {
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  Post,
  Put,
  Query,
  UseGuards,
} from "@nestjs/common";
import { SessionAuthGuard } from "../auth/guards/session-auth.guard";
import { RolesGuard } from "../auth/guards/roles.guard";
import { WorkflowDefinitionsService } from "./workflow-definitions.service";
import type { WorkflowDefinitionDto } from "./workflow-definitions.service";

/**
 * Workflow definitions decide what runs on every write, so they are guarded the
 * same way business rules are. This controller shipped with no guards at all:
 * `GET /api/workflow-definitions` returned every definition to anyone who
 * asked, and PUT/POST/DELETE let them be rewritten without signing in.
 */
@UseGuards(SessionAuthGuard, RolesGuard)
@Controller("workflow-definitions")
export class WorkflowDefinitionsController {
  constructor(private readonly service: WorkflowDefinitionsService) {}

  /**
   * A page of definitions. Defaults to 200, which is also the ceiling — a list
   * endpoint that can be asked for everything eventually is, and then times out.
   */
  @Get()
  findAll(
    @Query('entityName') entityName?: string,
    @Query('operation') operation?: string,
    @Query('isActive') isActive?: string,
    @Query('kind') kind?: string,
    @Query('limit') limit?: string,
    @Query('offset') offset?: string
  ) {
    return this.service.findAll({
      entityName,
      operation,
      isActive: isActive !== undefined ? isActive === "true" : undefined,
      kind,
      limit: limit ? Number(limit) : undefined,
      offset: offset ? Number(offset) : undefined,
    });
  }

  @Get(':id')
  findOne(@Param('id') id: string) {
    return this.service.findOne(id);
  }

  @Post()
  create(@Body() dto: WorkflowDefinitionDto) {
    return this.service.create(dto);
  }

  @Put(":id")
  update(@Param('id') id: string, @Body() dto: Partial<WorkflowDefinitionDto>) {
    return this.service.update(id, dto);
  }

  @Delete(':id')
  @HttpCode(HttpStatus.OK)
  remove(@Param('id') id: string) {
    return this.service.remove(id);
  }
}

/**
 * An automation the builder saved, as the BPMN the executor runs.
 *
 * The builder stores one thing: a Mermaid flowchart with `%%step` directives.
 * The executor reads another: `bpmn_xml`, one service task per step. The
 * generator bridges the two for the workflows a model declares
 * (`compileSagas` + `buildSagaBpmn` in `packages/generator/src/workflows`), but
 * nothing bridged them for one authored in the running application — so it
 * saved, published, showed "Live" and, on every write, recorded a successful
 * run that changed nothing.
 *
 * This is that bridge, run when the definition is saved. It mirrors the
 * generator's reading of the automation dialect (`type:`/`as:` on the first
 * line, one property per line, `in:` for a loop member) and its translation of
 * property names, so the same flowchart means the same thing in both places.
 */

export interface AutomationGuard {
  field: string;
  operator: string;
  value: string;
}

interface CompiledStep {
  nodeId: string;
  type: string;
  label: string;
  props: Record<string, string>;
}

const STEP_TYPES = ['UpdateEntity', 'CreateEntity', 'DeleteEntity', 'Decision', 'Formula', 'REST'];

const AUTO_TYPE = /^%%step\s+([A-Za-z_]\w*)\s+type:\s*([A-Za-z]\w*)\s*(.*)$/;
const AUTO_PROP = /^%%step\s+([A-Za-z_]\w*)\s+([A-Za-z_]\w*):\s*(.*)$/;
/** `key:` starts a property; `(?!\/\/)` keeps `https://host` whole. */
const PROP_SPLIT = /\s+(?=[A-Za-z_]\w*:(?!\/\/))/;
const NODE_LABEL =
  /(?:^|[^\w])([A-Za-z_]\w*)\s*(?:\(\[([^\]]*)\]\)|\(\(([^)]*)\)\)|\[([^\]]*)\]|\{([^}]*)\}|\(([^)]*)\))/g;
const EDGE =
  /([A-Za-z_]\w*)\s*(?:\(\[[^\]]*\]\)|\(\([^)]*\)\)|\[[^\]]*\]|\{[^}]*\}|\([^)]*\))?\s*(?:-->|---|-\.->|==>)(?:\|[^|]*\|)?\s*([A-Za-z_]\w*)/g;

function parseProps(rest: string): Record<string, string> {
  const props: Record<string, string> = {};
  const trimmed = rest.trim();
  if (!trimmed) return props;
  for (const chunk of trimmed.split(PROP_SPLIT)) {
    const at = chunk.indexOf(':');
    if (at <= 0) continue;
    const key = chunk.slice(0, at).trim();
    if (key) props[key] = chunk.slice(at + 1).trim();
  }
  return props;
}

function nodeLabels(diagram: string): Map<string, string> {
  const labels = new Map<string, string>();
  for (const line of diagram.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('%%')) continue;
    for (const match of trimmed.matchAll(NODE_LABEL)) {
      const label = (match[2] ?? match[3] ?? match[4] ?? match[5] ?? match[6] ?? '').trim();
      if (label && !labels.has(match[1]!)) labels.set(match[1]!, label);
    }
  }
  return labels;
}

function edges(diagram: string): { next: Map<string, string[]>; hasIncoming: Set<string> } {
  const next = new Map<string, string[]>();
  const hasIncoming = new Set<string>();
  for (const line of diagram.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('%%')) continue;
    EDGE.lastIndex = 0;
    let match: RegExpExecArray | null = EDGE.exec(trimmed);
    while (match !== null) {
      const from = match[1]!;
      const to = match[2]!;
      next.set(from, [...(next.get(from) ?? []), to]);
      hasIncoming.add(to);
      EDGE.lastIndex = match.index + match[0].length - to.length;
      match = EDGE.exec(trimmed);
    }
  }
  return { next, hasIncoming };
}

/** Node ids inside each `subgraph`, in the order written — how a loop is drawn. */
function subgraphs(diagram: string): Map<string, string[]> {
  const out = new Map<string, string[]>();
  let open: string | null = null;
  for (const raw of diagram.split('\n')) {
    const line = raw.trim();
    if (line.startsWith('%%')) continue;
    const start = line.match(/^subgraph\s+([A-Za-z_]\w*)/);
    if (start?.[1]) {
      open = start[1];
      out.set(open, []);
      continue;
    }
    if (line === 'end') {
      open = null;
      continue;
    }
    if (!open) continue;
    const node = line.match(/^([A-Za-z_]\w*)\s*[[({]/);
    if (node?.[1]) out.get(open)?.push(node[1]);
  }
  return out;
}

/** An automation's property names, as the executor reads them. */
function executorProps(type: string, props: Record<string, string>): Record<string, string> {
  const out: Record<string, string> = { ...props };
  const ref = (value?: string): string | null =>
    value?.trim().match(/^\{\{\s*([^}]+?)\s*\}\}$/)?.[1] ?? null;
  const move = (from: string, to: string) => {
    const value = out[from];
    if (value !== undefined && out[to] === undefined) out[to] = value;
    delete out[from];
  };

  if (type === 'Decision') {
    move('ruleTable', 'rule');
    move('table', 'decisionTable');
    delete out.inputs;
  } else if (type === 'CreateEntity') {
    move('values', 'fields');
  } else if (type === 'UpdateEntity' || type === 'DeleteEntity') {
    const target = ref(out.target);
    if (target) {
      out.targetSource = out.targetSource ?? target;
      delete out.target;
    } else move('target', 'targetField');
    const value = ref(out.value);
    if (value) {
      out.source = out.source ?? value;
      delete out.value;
    }
  } else if (type === 'Formula') {
    move('as', 'target');
    const left = ref(out.left);
    if (left) out.source = out.source ?? left;
    else if (out.left !== undefined) out.value = out.value ?? out.left;
    delete out.left;
    move('right', 'operand');
  } else if (type === 'REST') {
    move('body', 'bodyTemplate');
  }
  return out;
}

const escapeAttr = (value: string): string =>
  value.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

/** `%%guard <field> <operator> <json>` — an automation's conditions, all of which must hold. */
export function automationGuards(mermaid: string): AutomationGuard[] {
  const guards: AutomationGuard[] = [];
  for (const raw of (mermaid ?? '').split('\n')) {
    const match = raw.trim().match(/^%%guard\s+(\S+)\s+(\S+)\s*(.*)$/);
    if (!match?.[1] || !match[2]) continue;
    let value = (match[3] ?? '').trim();
    try {
      if (value.startsWith('"')) value = JSON.parse(value) as string;
    } catch {
      // keep the text as written
    }
    guards.push({ field: match[1], operator: match[2], value });
  }
  return guards;
}

/**
 * The BPMN for a saved automation, or `null` when it has no steps to run (a
 * hook ladder with nothing after it is handlers only).
 *
 * `resolveTable` turns the entity a step names (`Lead`) into its table
 * (`bus_lead`), because the executor reads `entity` as a table name.
 */
export function compileAutomationBpmn(
  mermaid: string,
  tableName: string,
  resolveTable: (entity: string) => string,
): string | null {
  const diagram = mermaid ?? '';
  const labels = nodeLabels(diagram);
  const declared = new Map<string, CompiledStep>();
  const loops = new Map<string, { field: string; operator: string; value: string; max: string }>();

  for (const raw of diagram.split('\n')) {
    const match = raw.trim().match(/^%%loop\s+(\w+)\s+while:\s*(\S+)\s+(\S+)\s*(.*)$/);
    if (!match?.[1] || !match[2] || !match[3]) continue;
    let rest = (match[4] ?? '').trim();
    const maxMatch = rest.match(/\s*max:\s*(\S+)\s*$/);
    const max = maxMatch?.[1] ?? '';
    if (maxMatch) rest = rest.slice(0, rest.length - maxMatch[0].length);
    let value = rest.trim();
    try {
      if (value.startsWith('"')) value = JSON.parse(value) as string;
    } catch {
      // keep the text as written
    }
    loops.set(match[1], { field: match[2], operator: match[3], value, max });
  }

  for (const raw of diagram.split('\n')) {
    const line = raw.trim();
    if (!line.startsWith('%%step')) continue;
    const typed = line.match(AUTO_TYPE);
    if (typed?.[1] && typed[2]) {
      if (!STEP_TYPES.includes(typed[2])) continue;
      const existing = declared.get(typed[1]);
      declared.set(typed[1], {
        nodeId: typed[1],
        type: typed[2],
        label: labels.get(typed[1]) ?? typed[1],
        props: { ...existing?.props, ...parseProps(typed[3] ?? '') },
      });
      continue;
    }
    const prop = line.match(AUTO_PROP);
    if (prop?.[1] && prop[2] && prop[2] !== 'type') {
      const existing = declared.get(prop[1]);
      declared.set(prop[1], {
        nodeId: prop[1],
        type: existing?.type ?? 'Formula',
        label: labels.get(prop[1]) ?? prop[1],
        props: { ...existing?.props, [prop[2]]: (prop[3] ?? '').trim() },
      });
    }
  }
  if (declared.size === 0) return null;

  for (const step of declared.values()) {
    step.props = executorProps(step.type, step.props);
    const loopId = (step.props.in ?? '').trim();
    delete step.props.in;
    const loop = loopId ? loops.get(loopId) : undefined;
    if (loop) {
      step.props.loopId = loopId;
      step.props.loopField = loop.field;
      step.props.loopOperator = loop.operator;
      step.props.loopValue = loop.value;
      step.props.loopMax = loop.max;
    }
  }

  // Order as drawn: walk the edges from each root, a loop's subgraph standing
  // for its members; a step with no edge still runs, after the rest.
  const { next, hasIncoming } = edges(diagram);
  const groups = subgraphs(diagram);
  const ordered: CompiledStep[] = [];
  const seen = new Set<string>();
  const walk = (id: string): void => {
    if (seen.has(id)) return;
    seen.add(id);
    for (const member of groups.get(id) ?? []) {
      if (seen.has(member)) continue;
      seen.add(member);
      const step = declared.get(member);
      if (step) ordered.push(step);
    }
    const step = declared.get(id);
    if (step) ordered.push(step);
    for (const child of next.get(id) ?? []) walk(child);
  };
  for (const root of new Set([...next.keys()].filter((id) => !hasIncoming.has(id)))) walk(root);
  for (const [id, step] of declared) if (!seen.has(id)) ordered.push(step);

  const processId = `${tableName}_automation`.replace(/[^A-Za-z0-9_]/g, '_');
  const tasks = ordered
    .map((step) => {
      const entries: Array<[string, string]> = [['nodeType', step.type]];
      for (const [key, value] of Object.entries(step.props)) {
        entries.push([key, key === 'entity' && value ? resolveTable(value) : value]);
      }
      const properties = entries
        .map(([k, v]) => `          <appwithai:property name="${escapeAttr(k)}" value="${escapeAttr(v)}" />`)
        .join('\n');
      return `    <bpmn:serviceTask id="${escapeAttr(step.nodeId)}" name="${escapeAttr(step.label)}">
      <bpmn:extensionElements>
        <appwithai:properties xmlns:appwithai="http://appwithai.io/schema/1.0">
${properties}
        </appwithai:properties>
      </bpmn:extensionElements>
    </bpmn:serviceTask>`;
    })
    .join('\n');
  const ids = ['start', ...ordered.map((s) => s.nodeId), 'end'];
  const flows = ids
    .slice(0, -1)
    .map(
      (from, i) =>
        `    <bpmn:sequenceFlow id="flow_${i}" sourceRef="${escapeAttr(from)}" targetRef="${escapeAttr(ids[i + 1]!)}" />`,
    )
    .join('\n');

  return `<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" id="defs_${processId}" targetNamespace="http://appwithai.dev/bpmn">
  <bpmn:process id="${processId}" isExecutable="true">
    <bpmn:startEvent id="start" name="Record written" />
${tasks}
${flows}
    <bpmn:endEvent id="end" name="Done" />
  </bpmn:process>
</bpmn:definitions>
`;
}

/** `Lead` → `bus_lead`, `SupportCase` → `bus_support_case`; a table name passes through. */
export function tableForEntity(entity: string): string {
  const snake = entity
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1_$2')
    .toLowerCase();
  return snake.startsWith('bus_') || snake.startsWith('sys_') ? snake : `bus_${snake}`;
}

import { Controller, Get, UseGuards } from "@nestjs/common";
import { SessionAuthGuard } from "../auth/guards/session-auth.guard";
import { LifecycleStore } from "./lifecycle-store.service";

/**
 * `GET /api/lifecycles` — every status flow as the application runs it now,
 * keyed by table: the model's, or the one an administrator redrew. The front
 * end's badge, list and form read lifecycles from its compiled
 * `lib/lifecycle.ts`; this is what it overlays so they follow an edit too.
 * Any signed-in user: it says where a record can go, never who may move it.
 */
@UseGuards(SessionAuthGuard)
@Controller("lifecycles")
export class LifecyclesController {
  constructor(private readonly store: LifecycleStore) {}

  @Get()
  findAll() {
    return this.store.effective();
  }
}

import { Injectable, Logger, type OnModuleDestroy, type OnModuleInit } from "@nestjs/common";
import type { Kysely } from "kysely";
import { InjectDatabase } from "../../database/database.service.decorator";
import {
  applyLifecycleOverrides,
  LIFECYCLES,
  lifecycleFromDiagram,
  lifecycleOf,
  type Lifecycle,
} from "../../common/lifecycle";

/**
 * The status flows an administrator redrew, loaded into `common/lifecycle.ts`.
 *
 * Every reader of a lifecycle — the transition service and its action buttons,
 * the bus service's save pipeline, promotion, the workflow engine, the access
 * guard — asks `lifecycleOf`. This service is what makes that answer the
 * administrator's: at start, on `pg_notify('lifecycle_changed')` from any
 * instance, and straight after a save on this one. A table with no stored flow,
 * a stored flow that no longer compiles, or a database that cannot be read all
 * leave the model's flow in force — never no flow at all.
 */
@Injectable()
export class LifecycleStore implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(LifecycleStore.name);
  private listener: { end(): Promise<void> } | null = null;
  private stopped = false;

  constructor(@InjectDatabase() private readonly db: Kysely<any>) {}

  async onModuleInit(): Promise<void> {
    await this.reload();
    await this.listen();
  }

  async onModuleDestroy(): Promise<void> {
    this.stopped = true;
    await this.listener?.end().catch(() => undefined);
  }

  /** Every table with a status flow, as the application runs it now. */
  effective(): Record<string, Lifecycle> {
    const result: Record<string, Lifecycle> = {};
    for (const tableName of Object.keys(LIFECYCLES)) {
      if (!LIFECYCLES[tableName]?.hasMachine) continue;
      const lifecycle = lifecycleOf(tableName);
      if (lifecycle) result[tableName] = lifecycle;
    }
    return result;
  }

  /** Read every stored flow and run them. */
  async reload(): Promise<void> {
    let rows: Array<{ entity_name: string; mermaid_code: string | null; lifecycle: unknown }>;
    try {
      rows = (await this.db
        .selectFrom("sys_workflow_definitions")
        .select(["entity_name", "mermaid_code", "lifecycle"] as any)
        .where("kind", "=", "state")
        .where("is_active", "=", true)
        .orderBy("updated_at", "asc")
        .execute()) as any;
    } catch (error: any) {
      this.logger.warn(`Could not read the stored status flows (${error?.message ?? error}); running the model's.`);
      return;
    }
    const next: Record<string, Lifecycle> = {};
    for (const row of rows) {
      // The diagram is the source; the stored compilation is what it compiled to
      // when saved. Recompiling here means a flow written by an older build, or
      // by hand, runs exactly as this build reads it.
      const { lifecycle, problems } = lifecycleFromDiagram(row.entity_name, row.mermaid_code ?? "");
      if (!lifecycle) {
        this.logger.warn(`The stored status flow of ${row.entity_name} is not used: ${problems.join(" ")}`);
        continue;
      }
      next[row.entity_name] = lifecycle;
    }
    applyLifecycleOverrides(next);
  }

  /** Listen on a connection of its own. Best-effort, like CapabilityService's. */
  private async listen(): Promise<void> {
    const url = process.env.DATABASE_URL;
    if (!url || this.stopped) return;
    try {
      const pg: any = await import("pg");
      const Client = pg.Client ?? pg.default?.Client;
      if (!Client) return;
      const client = new Client({ connectionString: url });
      await client.connect();
      client.on?.("notification", () => void this.reload());
      const reconnect = () => {
        this.listener = null;
        if (!this.stopped) setTimeout(() => void this.reload().then(() => this.listen()), 5000).unref?.();
      };
      client.on?.("error", reconnect);
      client.on?.("end", () => {
        if (!this.stopped) reconnect();
      });
      await client.query("LISTEN lifecycle_changed");
      this.listener = client;
    } catch (error: any) {
      this.logger.warn(
        `Not listening for status flow changes (${error?.message ?? error}); ` +
          "another instance's edit is picked up when this one restarts.",
      );
    }
  }
}

import { Module } from "@nestjs/common";
import { Reflector } from "@nestjs/core";
import { DatabaseModule } from "../../database/database.module";
import { NotificationsController } from "./notifications.controller";
import { NotificationsService } from "./notifications.service";

/**
 * Reads the audit trail; writes only read marks.
 *
 * `Reflector` and `DatabaseModule` are what SessionAuthGuard resolves against —
 * the same pair AuditModule provides for the same reason.
 */
@Module({
  imports: [DatabaseModule],
  providers: [Reflector, NotificationsService],
  controllers: [NotificationsController],
  exports: [NotificationsService],
})
export class NotificationsModule {}

import { Inject, Injectable, Logger } from "@nestjs/common";
import { type Kysely, sql } from "kysely";
import { KYSELY_CONNECTION } from "../../database/database.constants";
import { TRANSACTION_ACTIONS } from "../audit/audit.types";
import type {
  NotificationPage,
  TransactionNotification,
  TransactionOutcome,
} from "./notifications.types";

/**
 * A user's own record transactions, read out of the audit trail.
 *
 * Every write to a business entity is two transactions — the save that commits
 * the row as a draft, and the background one that finalises it or explains why
 * it could not — and both are recorded in `audit_log` against the user who
 * made them. This service reads those rows back for one user and turns them
 * into sentences.
 *
 * It reads the trail and nothing else. There is no notification table to fall
 * out of step with what happened, no second copy of a failure message, and
 * nothing to reconcile: if the trail does not say it, the user is not told it.
 * The only thing stored alongside is a read mark per (user, row).
 */
@Injectable()
export class NotificationsService {
  private readonly logger = new Logger(NotificationsService.name);

  /** table_name → display name, from the Application Dictionary. */
  private entityLabels: Map<string, string> | null = null;

  constructor(@Inject(KYSELY_CONNECTION) private readonly kysely: Kysely<any>) {}

  /**
   * One page of this user's transactions, newest first.
   *
   * Paged on the timestamp rather than an offset: the trail is append-only and
   * grows while a user is scrolling, and an offset would show them the same row
   * twice as new ones arrive above it.
   */
  async list(userId: string, limit = 30, before?: string): Promise<NotificationPage> {
    const pageSize = Math.min(100, Math.max(1, limit));

    let query = this.kysely
      .selectFrom("audit_log as a")
      .leftJoin("sys_notification_read as r", (join) =>
        join.onRef("r.audit_id", "=", "a.id").on("r.user_id", "=", userId as any)
      )
      .select([
        "a.id as id",
        "a.timestamp as timestamp",
        "a.action as action",
        "a.entity_type as entity_type",
        "a.entity_id as entity_id",
        "a.after_value as after_value",
        "a.before_value as before_value",
        "a.changed_fields as changed_fields",
        "a.success as success",
        "a.error_message as error_message",
        "r.read_at as read_at",
      ])
      .where("a.user_id", "=", userId)
      .where("a.action", "in", TRANSACTION_ACTIONS as string[])
      .orderBy("a.timestamp", "desc")
      // The trail can record two rows in the same millisecond — the draft and a
      // finalisation that needed no work. Without a tiebreaker the cursor can
      // loop on them; with one the order is total.
      .orderBy("a.id", "desc")
      .limit(pageSize + 1);

    if (before) {
      query = query.where("a.timestamp", "<", before);
    }

    const [rows, unread, labels] = await Promise.all([
      query.execute(),
      this.unreadCount(userId),
      this.labels(),
    ]);

    const hasMore = rows.length > pageSize;
    const page = hasMore ? rows.slice(0, pageSize) : rows;
    const last = page[page.length - 1] as any;

    return {
      data: page.map((row) => this.present(row as any, labels)),
      meta: {
        unread,
        limit: pageSize,
        nextCursor: hasMore && last ? new Date(last.timestamp).toISOString() : null,
      },
    };
  }

  /** How many of this user's transactions they have not opened yet. */
  async unreadCount(userId: string): Promise<number> {
    const row = await this.kysely
      .selectFrom("audit_log as a")
      .leftJoin("sys_notification_read as r", (join) =>
        join.onRef("r.audit_id", "=", "a.id").on("r.user_id", "=", userId as any)
      )
      .select((eb) => eb.fn.countAll<string>().as("total"))
      .where("a.user_id", "=", userId)
      .where("a.action", "in", TRANSACTION_ACTIONS as string[])
      .where("r.audit_id", "is", null)
      .executeTakeFirst();

    return Number.parseInt(String((row as any)?.total ?? 0), 10);
  }

  /**
   * Mark specific notifications read.
   *
   * Scoped to the caller's own rows in the same statement that writes the mark,
   * so a caller cannot mark another user's notification read by guessing its id
   * — the insert selects from the trail rather than trusting the request.
   */
  async markRead(userId: string, auditIds: string[]): Promise<{ marked: number }> {
    if (auditIds.length === 0) return { marked: 0 };

    const result = await sql<{ audit_id: string }>`
      INSERT INTO sys_notification_read (user_id, audit_id)
      SELECT ${userId}, a.id
        FROM audit_log a
       WHERE a.id = ANY(${auditIds}::uuid[])
         AND a.user_id = ${userId}
      ON CONFLICT (user_id, audit_id) DO NOTHING
      RETURNING audit_id
    `.execute(this.kysely);

    return { marked: result.rows.length };
  }

  /** Mark every transaction this user has as read. */
  async markAllRead(userId: string): Promise<{ marked: number }> {
    const result = await sql<{ audit_id: string }>`
      INSERT INTO sys_notification_read (user_id, audit_id)
      SELECT ${userId}, a.id
        FROM audit_log a
       WHERE a.user_id = ${userId}
         AND a.action = ANY(${TRANSACTION_ACTIONS as string[]})
      ON CONFLICT (user_id, audit_id) DO NOTHING
      RETURNING audit_id
    `.execute(this.kysely);

    return { marked: result.rows.length };
  }

  /* ------------------------------------------------------------------------ */
  /*  Presentation                                                             */
  /* ------------------------------------------------------------------------ */

  /**
   * Entity display names, read once per process.
   *
   * `bus_opportunity_line_item` is not what anybody calls it. The dictionary
   * already holds the name an administrator gave the table, and it is the same
   * name every screen shows, so the notification list uses that rather than
   * inventing a second way of writing entity names.
   */
  private async labels(): Promise<Map<string, string>> {
    if (this.entityLabels) return this.entityLabels;

    const map = new Map<string, string>();
    try {
      const rows = await this.kysely
        .selectFrom("sys_table")
        .select(["table_name", "name"])
        .execute();
      for (const row of rows as Array<{ table_name: string; name: string }>) {
        if (row.table_name && row.name) map.set(row.table_name, row.name);
      }
    } catch (err) {
      this.logger.warn(
        `Could not read entity names from the dictionary: ${err instanceof Error ? err.message : String(err)}`
      );
    }

    this.entityLabels = map;
    return map;
  }

  /** Columns that name a record, in the order a reader would recognise it by. */
  private static readonly LABEL_COLUMNS = [
    "name",
    "title",
    "subject",
    "label",
    "code",
    "reference",
    "number",
    "email",
    "description",
  ];

  private recordLabel(after: Record<string, unknown> | null, recordId: string | null): string {
    if (after) {
      for (const column of NotificationsService.LABEL_COLUMNS) {
        const value = after[column];
        if (typeof value === "string" && value.trim()) return value.trim();
      }
      // A `*_name` or `*_number` column is just as good a name and is what most
      // generated schemas actually carry — `account_name`, `case_number`.
      for (const [key, value] of Object.entries(after)) {
        if (!/(_name|_number|_code|_title)$/.test(key)) continue;
        if (typeof value === "string" && value.trim()) return value.trim();
      }
    }
    return recordId ? `#${recordId.slice(0, 8)}` : "a record";
  }

  private entitySlug(table: string): string {
    return table.replace(/^bus_/, "").replace(/_/g, "-");
  }

  private present(
    row: {
      id: string;
      timestamp: string | Date;
      action: string;
      entity_type: string | null;
      entity_id: string | null;
      after_value: unknown;
      before_value: unknown;
      changed_fields: string[] | null;
      success: boolean;
      error_message: string | null;
      read_at: string | Date | null;
    },
    labels: Map<string, string>
  ): TransactionNotification {
    const table = row.entity_type ?? "";
    const entityLabel = labels.get(table) ?? this.titleCase(this.entitySlug(table));
    // A delete keeps the record on the `before` side, so the name has to be
    // read from whichever side the transaction actually populated.
    const record = (row.after_value ?? row.before_value ?? null) as Record<
      string,
      unknown
    > | null;
    const recordLabel = this.recordLabel(record, row.entity_id);

    const operation = this.operationOf(row.changed_fields);
    const phase = row.action === "ENTITY_DRAFT" ? "draft" : "finalize";
    const outcome: TransactionOutcome =
      phase === "draft" ? "pending" : row.success ? "succeeded" : "failed";

    // A deleted record has no page left to open, and neither has a record whose
    // table we could not identify.
    const isGone = operation === "delete" && outcome === "succeeded";
    const href =
      table.startsWith("bus_") && row.entity_id && !isGone
        ? `/${this.entitySlug(table)}/${row.entity_id}`
        : null;

    return {
      id: row.id,
      at: new Date(row.timestamp).toISOString(),
      read: row.read_at !== null && row.read_at !== undefined,
      outcome,
      phase,
      operation,
      entityTable: table,
      entityLabel,
      recordId: row.entity_id,
      recordLabel,
      title: this.title(entityLabel, recordLabel, phase, operation, outcome),
      detail: this.detail(phase, operation, outcome, row.error_message),
      href,
    };
  }

  /** The operation is stored in `changed_fields`, which the two writers set to it. */
  private operationOf(changedFields: string[] | null): TransactionNotification["operation"] {
    const first = changedFields?.[0];
    return first === "create" || first === "update" || first === "delete" ? first : "save";
  }

  private title(
    entityLabel: string,
    recordLabel: string,
    phase: "draft" | "finalize",
    operation: TransactionNotification["operation"],
    outcome: TransactionOutcome
  ): string {
    const subject = `${entityLabel} “${recordLabel}”`;

    if (phase === "draft") {
      if (operation === "delete") return `${subject} — delete in progress`;
      return `${subject} saved as a draft`;
    }

    if (outcome === "succeeded") {
      if (operation === "delete") return `${subject} was deleted`;
      return `${subject} is now final`;
    }

    if (operation === "delete") return `${subject} could not be deleted`;
    return `${subject} could not be finalised`;
  }

  private detail(
    phase: "draft" | "finalize",
    operation: TransactionNotification["operation"],
    outcome: TransactionOutcome,
    errorMessage: string | null
  ): string {
    if (phase === "draft") {
      if (operation === "delete") {
        return "The delete was accepted. Its workflows are running now — the record is removed once they finish.";
      }
      return (
        "Your changes are saved. The record's business rules and workflows are running now, " +
        "and it becomes final once they all pass."
      );
    }

    if (outcome === "succeeded") {
      if (operation === "delete") return "Every workflow the delete had to run completed.";
      return "Every business rule and workflow passed, so the record is final.";
    }

    return (
      errorMessage?.trim() ||
      "The record was kept as a draft. Open it to see what needs correcting, then save again."
    );
  }

  private titleCase(slug: string): string {
    return slug
      .split("-")
      .filter(Boolean)
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(" ");
  }
}

/**
 * What a user sees in the bell beside the Log out button.
 *
 * A notification is not a stored object — it is one row of the audit trail,
 * rendered for the person who caused it. Nothing here is written anywhere; the
 * only thing this module stores is whether a user has read a given row.
 */

/** What became of the transaction. */
export type TransactionOutcome = "pending" | "succeeded" | "failed";

export interface TransactionNotification {
  /** The `audit_log` row this came from. Also the id a read mark is keyed on. */
  id: string;
  /** ISO timestamp of the audit row — the list is ordered on this, newest first. */
  at: string;
  read: boolean;
  outcome: TransactionOutcome;
  /** `draft` (the save) or `finalize` (the second transaction). */
  phase: "draft" | "finalize";
  operation: "create" | "update" | "delete" | "save";
  /** Physical table, e.g. `bus_account`. */
  entityTable: string;
  /** What that table is called in the Application Dictionary, e.g. `Account`. */
  entityLabel: string;
  recordId: string | null;
  /** The record's own name, where it has one; otherwise a short form of its id. */
  recordLabel: string;
  /** One line, written for a person: "Account “Acme Corp” is now final". */
  title: string;
  /** The detail under it — for a failure, why it failed and what to do. */
  detail: string;
  /** Where to go to see the record. Null when the record no longer exists. */
  href: string | null;
}

export interface NotificationPage {
  data: TransactionNotification[];
  meta: {
    /** Unread transactions for this user across the whole trail, not just this page. */
    unread: number;
    limit: number;
    /** Pass as `before` to fetch the next, older page. Null when at the end. */
    nextCursor: string | null;
  };
}

import {
  Body,
  Controller,
  Get,
  HttpCode,
  HttpStatus,
  Post,
  Query,
  Req,
  UnauthorizedException,
  UseGuards,
} from "@nestjs/common";
import { ApiBearerAuth, ApiOperation, ApiTags } from "@nestjs/swagger";
import { SessionAuthGuard } from "../auth/guards/session-auth.guard";
import { NotificationsService } from "./notifications.service";

/**
 * A user's own transaction notifications.
 *
 * Deliberately *not* behind the administrator gate the audit controller uses.
 * That gate is there because `/audit` serves the whole trail — every user's
 * changes, before and after values included. This surface serves one user their
 * own rows and nobody else's, and the scoping is not a filter the caller passes
 * but the session: there is no parameter here that names a user, so there is
 * nothing to tamper with.
 */
@ApiTags("notifications")
@ApiBearerAuth()
@UseGuards(SessionAuthGuard)
@Controller("notifications")
export class NotificationsController {
  constructor(private readonly notifications: NotificationsService) {}

  /** The id the audit trail records — see AuditInterceptor, which writes the same one. */
  private userId(req: any): string {
    const id = req?.user?.id;
    if (!id) throw new UnauthorizedException("No signed-in user");
    return String(id);
  }

  @Get()
  @ApiOperation({ summary: "This user's record transactions, newest first" })
  async list(
    @Req() req: any,
    @Query("limit") limit?: string,
    @Query("before") before?: string
  ) {
    return this.notifications.list(
      this.userId(req),
      limit ? Number.parseInt(limit, 10) : 30,
      before || undefined
    );
  }

  @Get("unread-count")
  @ApiOperation({ summary: "How many transactions this user has not read" })
  async unreadCount(@Req() req: any) {
    return { unread: await this.notifications.unreadCount(this.userId(req)) };
  }

  @Post("read")
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: "Mark specific notifications read" })
  async markRead(@Req() req: any, @Body() body: { ids?: string[] }) {
    const ids = Array.isArray(body?.ids) ? body.ids.filter((id) => typeof id === "string") : [];
    return this.notifications.markRead(this.userId(req), ids);
  }

  @Post("read-all")
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: "Mark every one of this user's notifications read" })
  async markAllRead(@Req() req: any) {
    return this.notifications.markAllRead(this.userId(req));
  }
}

import { z } from 'zod';

/**
 * JDM content arrives either as a JSON string (older callers, and anything that
 * serialises before posting) or as the object the rule table editor holds in
 * state. Accepting only the string meant a table built in the editor was
 * rejected at the door with "Validation failed" and no way to tell why.
 */
const JdmContent = z.union([z.string(), z.record(z.unknown())]);

export const CreateRuleSchema = z.object({
  entityName: z.string().min(1),
  ruleName: z.string().min(1),
  operation: z.enum(['CREATE', 'READ', 'UPDATE', 'DELETE', 'ALL']),
  jdmContent: JdmContent,
  /** What the rule is called in words; `ruleName` is the identifier made of it. */
  title: z.string().max(200).nullable().optional(),
});

export type CreateRuleDto = z.infer<typeof CreateRuleSchema>;

export const UpdateRuleSchema = z.object({
  jdmContent: JdmContent.optional(),
  /** The write the rule judges — set by attaching it to a workflow's hook. */
  operation: z.enum(['CREATE', 'UPDATE', 'DELETE', 'ALL']).optional(),
  isActive: z.boolean().optional(),
  title: z.string().max(200).nullable().optional(),
});

export type UpdateRuleDto = z.infer<typeof UpdateRuleSchema>;

export const ValidateJdmSchema = z.object({
  jdmContent: JdmContent,
});

export type ValidateJdmDto = z.infer<typeof ValidateJdmSchema>;

export const DryRunSchema = z.object({
  ruleId: z.string(),
  testData: z.record(z.unknown()),
});

export const SimulateRuleSchema = z.object({
  /** The graph as the editor holds it — JSON text, or the object itself. */
  jdmContent: z.union([z.string(), z.record(z.unknown())]),
  testData: z.record(z.unknown()),
  entityName: z.string().optional(),
});

export type SimulateRuleDto = z.infer<typeof SimulateRuleSchema>;

export type DryRunDto = z.infer<typeof DryRunSchema>;

export const EvaluateRulesSchema = z.object({
  entityName: z.string(),
  operation: z.enum(['CREATE', 'READ', 'UPDATE', 'DELETE']),
  data: z.record(z.unknown()),
});

export type EvaluateRulesDto = z.infer<typeof EvaluateRulesSchema>;

/**
 * Rules Service - Database-Persistent Business Rules
 *
 * Provides CRUD operations for managing business rules in the database.
 * Integrates with GoRules Zen Engine for rule evaluation.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { Injectable, Logger, NotFoundException, BadRequestException, Inject, forwardRef } from '@nestjs/common';
import type { Kysely } from 'kysely';
import { InjectDatabase } from '../../database/database.service.decorator';
import { RulesEngine } from './rules-engine.service';
import type { RuleEvaluationResult } from './rules-engine.service';
import { readFileSync } from 'fs';
import { WorkflowService } from '../workflow/workflow.service';
import { getLogger } from '../../common/logging/logger.service';
import { stateFieldOf } from '../../common/state-fields';
import { join } from 'path';

export interface CreateRuleDto {
  entityName: string;
  ruleName: string;
  operation: 'CREATE' | 'READ' | 'UPDATE' | 'DELETE' | 'ALL';
  jdmContent: string | Record<string, unknown>;
  title?: string | null;
}

export interface UpdateRuleDto {
  jdmContent?: string | Record<string, unknown>;
  title?: string | null;
  isActive?: boolean;
  operation?: 'CREATE' | 'UPDATE' | 'DELETE' | 'ALL';
}

/** Rule action types that write to the database — the ones a promotion must run atomically. */
export const SIDE_EFFECTING_ACTIONS = [
  'cascade-update',
  'cascade-delete',
  'cascade-create',
  'transform',
  'trigger-workflow',
] as const;

export interface RuleActionOptions {
  /** Run every write on this connection. Pass a transaction to make the batch atomic. */
  db?: Kysely<any>;
  /** Throw on the first failing action instead of logging it and carrying on. */
  throwOnError?: boolean;
  /**
   * How many state writes deep this evaluation is. A workflow that moves a
   * record into a new state is itself a write, so the entity's rules run again
   * against the record it produced — that is how a rule keyed on the new state
   * fires, now that no person writes a state. Bounded, because a model can draw
   * a cycle.
   */
  depth?: number;
  /**
   * Run only the workflow-starting actions. Set when the rules are re-run after
   * a workflow's state write: that write is already made, so a refusal cannot
   * apply to it, and a transform would rewrite a record nobody is editing.
   */
  triggersOnly?: boolean;
}

/** How many workflow state writes may chain from one person's write. */
const MAX_STATE_WRITE_DEPTH = 8;

export interface MatchedAction {
  ruleName: string;
  type: string;
  config: Record<string, unknown>;
}

export interface Rule {
  id: string;
  entityName: string;
  ruleName: string;
  title?: string;
  operation: string;
  jdmContent: string | Record<string, unknown>;
  version: number;
  isActive: boolean;
  createdBy: string;
  updatedBy?: string;
  createdAt: Date;
  updatedAt: Date;
}

@Injectable()
export class RulesService {
  private readonly logger = new Logger(RulesService.name);

  constructor(
    private readonly rulesEngine: RulesEngine,
    @InjectDatabase() private readonly db: Kysely<any>,
    @Inject(forwardRef(() => WorkflowService)) private readonly workflowService: WorkflowService,
  ) {}

  /**
   * Get all rules with optional filtering
   */
  /**
   * A page of rules, capped at 200.
   *
   * Rules accumulate — one per entity per operation, plus every table an
   * automation looks up — so the list endpoint has to be bounded or the admin
   * page that reads it eventually stops loading.
   */
  async findAll(filters?: {
    entityName?: string;
    operation?: string;
    isActive?: boolean;
    limit?: number;
    offset?: number;
  }): Promise<Rule[]> {
    let query = this.db.selectFrom('sys_rule_definitions').selectAll();

    if (filters?.entityName) {
      query = query.where('entity_name', '=', filters.entityName);
    }

    if (filters?.operation) {
      query = query.where('operation', '=', filters.operation.toUpperCase());
    }

    if (filters?.isActive !== undefined) {
      query = query.where('is_active', '=', filters.isActive);
    }

    const limit = Math.min(Math.max(filters?.limit ?? 200, 1), 200);
    const offset = Math.max(filters?.offset ?? 0, 0);

    const rules = await query
      .orderBy('entity_name', 'asc')
      .orderBy('operation', 'asc')
      .orderBy('rule_name', 'asc')
      .limit(limit)
      .offset(offset)
      .execute();

    return rules.map((rule) => this.mapDbRuleToRule(rule));
  }

  /**
   * Get rule by ID
   */
  async findById(id: string): Promise<Rule> {
    const rule = await this.db
      .selectFrom('sys_rule_definitions')
      .selectAll()
      .where('id', '=', id)
      .executeTakeFirst();

    if (!rule) {
      throw new NotFoundException(`Rule with ID ${id} not found`);
    }

    return this.mapDbRuleToRule(rule);
  }

  /**
   * Create a new rule
   */
  async create(dto: CreateRuleDto, userId: string): Promise<Rule> {
    const existing = await this.db
      .selectFrom('sys_rule_definitions')
      .selectAll()
      .where('entity_name', '=', dto.entityName)
      .where('operation', '=', dto.operation)
      .where('rule_name', '=', dto.ruleName)
      .executeTakeFirst();

    if (existing) {
      throw new BadRequestException(
        `Rule ${dto.ruleName} already exists for ${dto.entityName}:${dto.operation}`
      );
    }

    const validation = await this.validateJDM(dto.jdmContent);
    if (!validation.valid) {
      throw new BadRequestException({ message: 'Invalid JDM content', errors: validation.errors });
    }

    const rule = await this.db
      .insertInto('sys_rule_definitions')
      .values({
        entity_name: dto.entityName,
        rule_name: dto.ruleName,
        operation: dto.operation.toUpperCase(),
        jdm_content: this.serializeJdm(dto.jdmContent),
        title: dto.title ?? null,
        version: 1,
        is_active: true,
        created_by: userId,
        created_at: new Date(),
        updated_at: new Date(),
      } as any)
      .returningAll()
      .executeTakeFirst();

    this.logger.log(`Created rule ${rule.rule_name} for ${rule.entity_name}:${rule.operation}`);

    return this.mapDbRuleToRule(rule);
  }

  /**
   * Update an existing rule
   */
  async update(id: string, dto: UpdateRuleDto, userId: string): Promise<Rule> {
    const rule = await this.findById(id);

    if (dto.jdmContent) {
      const validation = await this.validateJDM(dto.jdmContent);
      if (!validation.valid) {
        throw new BadRequestException({ message: 'Invalid JDM content', errors: validation.errors });
      }
    }

    const updateData: Record<string, unknown> = {
      updated_at: new Date(),
      updated_by: userId,
    };

    if (dto.jdmContent) {
      updateData.jdm_content = dto.jdmContent;
      updateData.version = rule.version + 1;
    }

    if (dto.isActive !== undefined) {
      updateData.is_active = dto.isActive;
    }

    if (dto.title !== undefined) {
      updateData.title = dto.title;
    }

    if (dto.operation && dto.operation !== rule.operation) {
      // A rule is filed under its record type, its name and the write it judges;
      // moving it onto a write that already has one by this name would make two.
      const taken = await this.db
        .selectFrom('sys_rule_definitions')
        .select('id')
        .where('entity_name', '=', rule.entityName)
        .where('operation', '=', dto.operation)
        .where('rule_name', '=', rule.ruleName)
        .executeTakeFirst();
      if (taken) {
        throw new BadRequestException(
          `Rule ${rule.ruleName} already exists for ${rule.entityName}:${dto.operation}`,
        );
      }
      updateData.operation = dto.operation;
    }

    const updated = await this.db
      .updateTable('sys_rule_definitions')
      .set(updateData)
      .where('id', '=', id)
      .returningAll()
      .executeTakeFirst();

    this.logger.log(`Updated rule ${updated.rule_name} (version ${updated.version})`);

    return this.mapDbRuleToRule(updated);
  }

  /**
   * Delete a rule (soft delete by setting is_active = false)
   */
  async delete(id: string): Promise<void> {
    const rule = await this.findById(id);

    await this.db
      .updateTable('sys_rule_definitions')
      .set({
        is_active: false,
        updated_at: new Date(),
      })
      .where('id', '=', id)
      .execute();

    this.logger.log(`Deactivated rule ${rule.ruleName}`);
  }

  /**
   * Remove a rule for good.
   *
   * Deleting only ever deactivated a rule, so a list that was meant to hold the
   * rules an application runs filled up with every one ever switched off — and
   * the screen reads at most 200. Only an inactive rule can be removed: taking
   * one away is a second, deliberate step after turning it off, never the
   * first.
   */
  async purge(id: string): Promise<void> {
    const rule = await this.findById(id);
    if (rule.isActive) {
      throw new BadRequestException('Deactivate the rule before deleting it permanently');
    }
    await this.db.deleteFrom('sys_rule_definitions').where('id', '=', id).execute();
    this.logger.log(`Deleted rule ${rule.ruleName} permanently`);
  }

  /**
   * Get rule history (all versions of a rule)
   */
  async getHistory(ruleId: string): Promise<Rule[]> {
    return [await this.findById(ruleId)];
  }


  /**
   * Store JDM as text, whichever way it arrived.
   *
   * The column is text and the engine parses it, so an object from the rule
   * table editor and a string from an older caller have to converge here —
   * otherwise the same rule reads back differently depending on who wrote it.
   */
  private serializeJdm(content: string | Record<string, unknown>): string {
    return typeof content === 'string' ? content : JSON.stringify(content);
  }

  /**
   * Validate JDM content
   */
  async validateJDM(jdmContent: string | Record<string, unknown>): Promise<{
    valid: boolean;
    errors: string[];
  }> {
    try {
      const parsed = typeof jdmContent === 'string' ? JSON.parse(jdmContent) : jdmContent;

      // A decision table is a complete rule on its own — it is what the rule
      // table editor writes. Demanding a node graph of it is what stopped the
      // editor being able to save anything at all.
      if (
        Array.isArray(parsed?.inputs) &&
        Array.isArray(parsed?.outputs) &&
        Array.isArray(parsed?.rules)
      ) {
        const errors: string[] = [];
        if (parsed.inputs.length === 0) errors.push('Add at least one input column to test against.');
        if (parsed.outputs.length === 0) {
          errors.push('Add at least one outcome column — a table that decides nothing does nothing.');
        }
        if (parsed.rules.length === 0) errors.push('Add at least one row.');
        // A `collect` table's field-less input reads the whole record: it is
        // what `%%action` compiles to, and each cell is a check such as
        // `status == "completed" and final_grade == null`. Demanding a field
        // of it refused every edit to a rule the model itself declared.
        const named = parsed.hitPolicy === 'collect' ? parsed.outputs : [...parsed.inputs, ...parsed.outputs];
        for (const column of named) {
          if (!String(column?.field ?? '').trim()) {
            errors.push(`Column "${column?.name ?? column?.id}" does not say which field it reads.`);
          }
        }
        return { valid: errors.length === 0, errors };
      }

      if (!parsed.nodes || !Array.isArray(parsed.nodes)) {
        return { valid: false, errors: ['JDM must have a nodes array'] };
      }

      if (!parsed.edges || !Array.isArray(parsed.edges)) {
        return { valid: false, errors: ['JDM must have an edges array'] };
      }

      const columnErrors = this.findIncompleteDecisionRows(parsed);
      if (columnErrors.length > 0) {
        return { valid: false, errors: columnErrors };
      }

      const graphErrors = this.rulesEngine.graphProblems(this.serializeJdm(jdmContent));
      if (graphErrors.length > 0) {
        return { valid: false, errors: graphErrors };
      }

      const engine = this.rulesEngine.getEngine();
      const decision = engine.createDecision(
        Buffer.from(this.rulesEngine.prepare(this.serializeJdm(jdmContent))),
      );
      // Run it once, to catch what only running shows (an expression that does
      // not parse, a function that throws). With nothing to run it on, field
      // arithmetic — `amount * probability` — fails on null, which says nothing
      // about the rule: it refused every graph with an expression node. So the
      // run uses a record built from the Record node's own schema, when the
      // editor wrote one; and without a schema a failure inside a node is
      // taken to be about the missing data, not the rule.
      const sample = this.sampleFromSchema(parsed);
      try {
        await decision.evaluate(sample ?? {});
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        const dataDependent = !sample && /"type"\s*:\s*"NodeError"/.test(message);
        if (!dataDependent) throw error;
      }

      return { valid: true, errors: [] };
    } catch (error) {
      return {
        valid: false,
        errors: [error instanceof Error ? error.message : String(error)],
      };
    }
  }

  /**
   * A record that fits the Record node's JSON schema — "", 0, false, or an enum's first value.
   * The editor writes a number as `["null", "number"]` so a blank field is a valid record, so a
   * `type` is read as its first non-null member.
   */
  private sampleFromSchema(graph: {
    nodes?: Array<{ type?: string; content?: { schema?: string } }>;
  }): Record<string, unknown> | null {
    try {
      const text = graph.nodes?.find((node) => node.type === 'inputNode')?.content?.schema;
      if (!text) return null;
      const properties = (JSON.parse(text) as {
        properties?: Record<string, { type?: string | string[]; enum?: unknown[] }>;
      }).properties;
      if (!properties) return null;
      return Object.fromEntries(
        Object.entries(properties).map(([field, spec]) => {
          const type = Array.isArray(spec.type)
            ? spec.type.find((member) => member !== 'null')
            : spec.type;
          return [
            field,
            spec.enum?.length ? spec.enum[0] : type === 'number' ? 0 : type === 'boolean' ? false : '',
          ];
        }),
      );
    } catch {
      return null;
    }
  }

  /**
   * Catch the one JDM mistake that fails silently.
   *
   * zen-engine drops any decision-table row that does not carry a value for
   * every output column the table declares. It does not throw — `evaluate()`
   * just returns `[]`, which is indistinguishable from "no rules matched" and
   * from "no rules configured". Add an output column to an existing table
   * without backfilling the rows and every rule in it stops firing, with
   * nothing anywhere to say why.
   *
   * Rather than leave that as a comment nobody reads at 2am, refuse to save the
   * rule and name the rows and columns involved.
   */
  private findIncompleteDecisionRows(parsed: any): string[] {
    const errors: string[] = [];

    for (const node of parsed.nodes ?? []) {
      if (node?.type !== 'decisionTableNode') continue;

      const outputs = (node.content?.outputs ?? []) as Array<{ id?: string; field?: string }>;
      const rows = (node.content?.rules ?? []) as Array<Record<string, unknown>>;
      if (outputs.length === 0 || rows.length === 0) continue;

      rows.forEach((row, index) => {
        const missing = outputs
          .filter((output) => output.id && row[output.id] === undefined)
          .map((output) => `${output.id}${output.field ? ` (${output.field})` : ''}`);

        if (missing.length > 0) {
          const rowId = (row._id as string) || `row ${index + 1}`;
          errors.push(
            `Decision table "${node.name ?? node.id}" row "${rowId}" is missing output ` +
              `${missing.join(', ')}. zen-engine silently discards rows that do not set ` +
              `every declared output column, so the whole table would stop matching. ` +
              `Set the column to '' if the row has no value for it.`,
          );
        }
      });
    }

    return errors;
  }

  /**
   * Dry run - evaluate rule with sample context
   */
  async dryRun(jdmContent: string | Record<string, unknown>, context: Record<string, unknown>): Promise<{
    success: boolean;
    result?: unknown;
    errors?: string[];
  }> {
    try {
      const engine = this.rulesEngine.getEngine();
      // The editor holds its table as an object and posts it as one. Buffer.from
      // needs the serialised form, so an object goes through the same helper
      // that writes it to the column rather than reaching the engine as
      // "[object Object]".
      const decision = engine.createDecision(
        Buffer.from(this.rulesEngine.prepare(this.serializeJdm(jdmContent))),
      );
      const result = await decision.evaluate(context);

      return { success: true, result };
    } catch (error) {
      return {
        success: false,
        errors: [error instanceof Error ? error.message : String(error)],
      };
    }
  }

  /**
   * Run a rule graph against a sample record and say what each node produced.
   *
   * The same preparation every stored rule goes through, so what the Simulator
   * shows is what a write would meet. Nothing is stored. The answer has the
   * shape the rule editor reads: either `ok` with the final result and a trace
   * of the nodes in the order they ran, or the reasons it could not run.
   */
  async simulate(
    jdmContent: string | Record<string, unknown>,
    record: Record<string, unknown>,
  ): Promise<
    | { ok: true; result: unknown; trace: Array<{ node: string; output: unknown }> }
    | { ok: false; problems: string[] }
  > {
    const text = this.serializeJdm(jdmContent);
    const problems = this.rulesEngine.graphProblems(text);
    if (problems.length > 0) return { ok: false, problems };
    try {
      const engine = this.rulesEngine.getEngine();
      const decision = engine.createDecision(Buffer.from(this.rulesEngine.prepare(text)));
      const evaluated = (await decision.evaluate(
        { ...record, _operation: 'create' },
        { trace: true },
      )) as { result: unknown; trace?: Record<string, { name?: string; output?: unknown }> };
      const trace = Object.values(evaluated.trace ?? {}).map((step) => ({
        node: step.name ?? '',
        output: step.output,
      }));
      return { ok: true, result: evaluated.result, trace };
    } catch (error) {
      return { ok: false, problems: [error instanceof Error ? error.message : String(error)] };
    }
  }

  /**
   * Migrate rules from JDM files to database
   */
  async migrateFromFileSystem(): Promise<{ migrated: number; errors: string[] }> {
    const errors: string[] = [];
    let migrated = 0;

    const entityOperations = [
      { file: 'bus_patient.jdm.json', entityName: 'bus_patient', operation: 'ALL' },
      { file: 'bus_practitioner.jdm.json', entityName: 'bus_practitioner', operation: 'ALL' },
      { file: 'bus_appointment.jdm.json', entityName: 'bus_appointment', operation: 'ALL' },
      { file: 'bus_encounter.jdm.json', entityName: 'bus_encounter', operation: 'ALL' },
      { file: 'bus_claim.jdm.json', entityName: 'bus_claim', operation: 'ALL' },
    ];

    for (const { file, entityName, operation } of entityOperations) {
      try {
        const jdmPath = join(__dirname, 'jdm', file);
        const jdmContent = readFileSync(jdmPath, 'utf-8');

        const parsed = JSON.parse(jdmContent);
        const ruleName = parsed.name || `${entityName}_${operation.toLowerCase()}_rule`;

        const existing = await this.db
          .selectFrom('sys_rule_definitions')
          .selectAll()
          .where('entity_name', '=', entityName)
          .where('operation', '=', operation)
          .where('rule_name', '=', ruleName)
          .executeTakeFirst();

        if (existing) {
          this.logger.log(`Rule ${ruleName} already exists, skipping migration`);
          continue;
        }

        await this.create(
          {
            entityName,
            ruleName,
            operation: operation as CreateRuleDto['operation'],
            jdmContent,
          },
          'system-migration'
        );

        migrated++;
        this.logger.log(`Migrated rule ${ruleName} from ${file}`);
      } catch (error) {
        const errorMsg = `Failed to migrate ${file}: ${error instanceof Error ? error.message : String(error)}`;
        this.logger.error(errorMsg);
        errors.push(errorMsg);
      }
    }

    return { migrated, errors };
  }

  /**
   * Validate data against business rules
   */
  async validate(
    entityType: string,
    data: Record<string, unknown>,
    action: 'create' | 'update' | 'delete' = 'create',
  ): Promise<{ valid: boolean; errors: string[]; warnings: string[] }> {
    const startedAt = Date.now();
    const results = await this.evaluate(entityType, data, action);
    const log = getLogger('rules');

    log.event('rules.evaluated', {
      entity: entityType,
      event: action,
      matched: results.filter((result) => result.matched).length,
      durationMs: Date.now() - startedAt,
    });

    const errors: string[] = [];
    const warnings: string[] = [];

    for (const result of results) {
      if (result.errors?.length) {
        warnings.push(`Rules engine error: ${result.errors.join('; ')}`);
      }
      if (!result.matched) continue;

      for (const ruleAction of result.actions) {
        if (ruleAction.type === 'prevent') {
          const message = ruleAction.config.message as string | undefined;
          // A refused write is the single most useful line this application
          // produces: it is what someone means when they say "the system would
          // not let me save it", and until now it existed only as a message in
          // an HTTP response nobody kept.
          log.event('rules.write.prevented', {
            entity: entityType,
            rule: result.ruleName,
            reason: message || 'no message declared',
          });
          errors.push(message || `Rule violation: ${result.ruleName}`);
        } else if (ruleAction.type === 'validate') {
          const message = ruleAction.config.message as string | undefined;
          warnings.push(message || `Validation warning: ${result.ruleName}`);
        } else if (ruleAction.type === 'notify') {
          warnings.push(`Notification: ${result.ruleName}`);
        }
      }
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings,
    };
  }

  /**
   * Execute rules and return results.
   *
   * `db` must be supplied when the caller already holds a transaction. Reading
   * the rule definitions off the pool instead would acquire a *second*
   * connection while the first is still held, and under concurrent writes that
   * exhausts the pool and deadlocks every in-flight request — each one holding
   * a connection while waiting for one that can never be released.
   */
  async evaluate(
    entityType: string,
    data: Record<string, unknown>,
    action: 'create' | 'update' | 'delete' = 'create',
    db: Kysely<any> = this.db,
  ): Promise<RuleEvaluationResult[]> {
    // Rules scoped to the specific operation plus rules that apply to ALL operations
    const rules = await db
      .selectFrom('sys_rule_definitions')
      .selectAll()
      .where('entity_name', '=', entityType)
      .where('operation', 'in', [action.toUpperCase(), 'ALL'])
      .where('is_active', '=', true)
      .execute();

    const results: RuleEvaluationResult[] = [];
    for (const rule of rules) {
      results.push(
        ...(await this.rulesEngine.evaluateRulesWithJDM(
          entityType,
          rule.jdm_content,
          data,
          action,
          rule.rule_name as string,
        ))
      );
    }
    return results;
  }

  /**
   * Report the side-effecting actions that would run for this record, without running them.
   * The promotion pipeline uses this to tell "nothing is associated with this entity" apart
   * from "something is associated and it succeeded" — the two lead to different doc_status paths.
   */
  async collectActionableActions(
    entityName: string,
    data: Record<string, unknown>,
    operation: 'create' | 'update' | 'delete',
  ): Promise<MatchedAction[]> {
    const results = await this.evaluate(entityName, data, operation);
    const actions: MatchedAction[] = [];

    for (const result of results) {
      if (!result.matched) continue;
      for (const action of result.actions) {
        if ((SIDE_EFFECTING_ACTIONS as readonly string[]).includes(action.type)) {
          actions.push({ ruleName: result.ruleName, type: action.type, config: action.config });
        }
      }
    }
    return actions;
  }

  /**
   * Execute the side-effecting rule actions (cascade, transform, trigger-workflow) for a record.
   *
   * Two modes:
   *   - default: log failures and carry on (the historical fire-and-forget behaviour)
   *   - options.throwOnError: rethrow the first failure so an enclosing transaction rolls back
   *
   * Pass options.db to run every write on a transaction.
   */
  /**
   * Re-run the rules of every record a workflow just moved into a new state.
   *
   * A state field is changed only by background workflows, and they write it
   * directly rather than through /bus, so nothing else would evaluate the
   * record's rules against its new state: a rule keyed on `status == "paid"`
   * would never fire. Only workflow-starting actions run (`triggersOnly`).
   */
  private async followStateWrites(
    mutations: Array<Record<string, unknown>> | void | undefined,
    options: RuleActionOptions,
    depth: number,
  ): Promise<void> {
    for (const mutation of mutations || []) {
      if (mutation?.nodeType !== 'UpdateEntity' || !(Number(mutation.rowsAffected) > 0)) continue;
      const table = String(mutation.table ?? '');
      const state = stateFieldOf(table);
      if (!state || mutation.field !== state.field) continue;
      const match = String(mutation.matchedOn ?? '').match(/^([A-Za-z_]\w*)=(.+)$/);
      if (!match) continue;
      const db = options.db ?? this.db;
      let rows: Array<Record<string, any>> = [];
      try {
        rows = await db
          .selectFrom(table as any)
          .selectAll()
          .where(match[1] as any, '=', match[2])
          .where('deleted_at' as any, 'is', null)
          .execute();
      } catch (err: any) {
        this.logger.warn(`followStateWrites: could not reload ${table}: ${err?.message ?? err}`);
        continue;
      }
      for (const row of rows) {
        await this.executeMatchedActions(table, String(row.id), row, 'update', {
          ...options,
          depth: depth + 1,
          triggersOnly: true,
        });
      }
    }
  }

  async executeMatchedActions(
    entityName: string,
    entityId: string,
    data: Record<string, unknown>,
    operation: 'create' | 'update' | 'delete',
    options: RuleActionOptions = {},
  ): Promise<void> {
    const db = options.db ?? this.db;
    const depth = options.depth ?? 0;
    if (depth > MAX_STATE_WRITE_DEPTH) {
      this.logger.warn(
        `executeMatchedActions: ${entityName}:${entityId} moved state ${depth} times from one write — stopping`,
      );
      return;
    }

    let results: RuleEvaluationResult[];
    try {
      // Pass `db` so a caller-supplied transaction is reused rather than a
      // second pool connection being taken while the first is still held.
      results = await this.evaluate(entityName, data, operation, db);
    } catch (err: any) {
      if (options.throwOnError) {
        throw new Error(`Could not evaluate business rules for ${entityName}: ${err?.message ?? err}`);
      }
      this.logger.warn(`executeMatchedActions: evaluate failed for ${entityName}: ${err?.message}`);
      getLogger('rules').event('rules.evaluation.failed', {
        entity: entityName,
        rule: null,
        err,
      });
      return;
    }

    for (const result of results) {
      if (!result.matched) continue;
      for (const action of result.actions) {
        try {
          if (action.type === 'trigger-workflow') {
            const wfName = action.config.workflowName as string | undefined;
            if (!wfName) {
              this.logger.warn(`trigger-workflow action in rule "${result.ruleName}" has no workflowName — skipping`);
              continue;
            }
            this.logger.log(`Rule "${result.ruleName}" triggering workflow "${wfName}" for ${entityName}:${entityId}`);
            // Only hand our connection over when the caller opened a transaction —
            // otherwise the workflow service uses its own, as it always has.
            const mutations = await this.workflowService.triggerByWorkflowName(
              wfName,
              entityName,
              entityId,
              operation,
              data,
              { db: options.db, throwOnError: options.throwOnError },
            );
            await this.followStateWrites(mutations, options, depth);
          } else if (options.triggersOnly) {
            continue;
          } else if (action.type === 'cascade-update') {
            const targetEntity = action.config.targetEntity as string | undefined;
            const linkField = action.config.linkField as string | undefined;
            const updateData = action.config.updateData as Record<string, unknown> | undefined;
            if (targetEntity && linkField && updateData) {
              await db
                .updateTable(targetEntity as any)
                .set(updateData as any)
                .where(linkField as any, '=', entityId)
                .execute();
              this.logger.log(`Cascade-update: updated ${targetEntity} where ${linkField}=${entityId}`);
            }
          } else if (action.type === 'cascade-delete') {
            const targetEntity = action.config.targetEntity as string | undefined;
            const linkField = action.config.linkField as string | undefined;
            if (targetEntity && linkField) {
              await db
                .deleteFrom(targetEntity as any)
                .where(linkField as any, '=', entityId)
                .execute();
              this.logger.log(`Cascade-delete: deleted from ${targetEntity} where ${linkField}=${entityId}`);
            } else {
              this.logger.warn(
                `cascade-delete in rule "${result.ruleName}" needs targetEntity and linkField — skipping`,
              );
            }
          } else if (action.type === 'cascade-create') {
            const targetEntity = action.config.targetEntity as string | undefined;
            const createData = action.config.createData as Record<string, unknown> | undefined;
            const linkField = action.config.linkField as string | undefined;
            if (targetEntity && createData) {
              const now = new Date();
              await db
                .insertInto(targetEntity as any)
                .values({
                  ...createData,
                  // Link the new row back at the record that triggered the rule.
                  ...(linkField ? { [linkField]: entityId } : {}),
                  created_at: now,
                  updated_at: now,
                } as any)
                .execute();
              this.logger.log(`Cascade-create: inserted into ${targetEntity} for ${entityName}:${entityId}`);
            } else {
              this.logger.warn(
                `cascade-create in rule "${result.ruleName}" needs targetEntity and createData — skipping`,
              );
            }
          } else if (action.type === 'transform') {
            const transformData = action.config.transformData as Record<string, unknown> | undefined;
            if (transformData && Object.keys(transformData).length > 0) {
              await db
                .updateTable(entityName as any)
                .set({ ...transformData, updated_at: new Date() } as any)
                .where('id' as any, '=', entityId)
                .execute();
              this.logger.log(
                `Transform: applied ${Object.keys(transformData).join(', ')} to ${entityName}:${entityId}`,
              );
            } else {
              this.logger.warn(`transform in rule "${result.ruleName}" has no transformData — skipping`);
            }
          }
        } catch (err: any) {
          if (options.throwOnError) {
            throw new Error(
              `Rule "${result.ruleName}" action "${action.type}" failed: ${err?.message ?? err}`,
            );
          }
          this.logger.error(`executeMatchedActions: action "${action.type}" failed for rule "${result.ruleName}": ${err?.message}`);
          getLogger('rules').event('rules.evaluation.failed', {
            entity: entityName,
            rule: result.ruleName,
            action: action.type,
            err,
          });
        }
      }
    }
  }

    private mapDbRuleToRule(record: Record<string, unknown>): Rule {
    return {
      id: record.id as string,
      entityName: record.entity_name as string,
      ruleName: record.rule_name as string,
      title: (record.title as string | null | undefined) ?? undefined,
      operation: record.operation as string,
      jdmContent: record.jdm_content as string,
      version: record.version as number,
      isActive: record.is_active as boolean,
      createdBy: record.created_by as string,
      updatedBy: record.updated_by as string | undefined,
      createdAt: record.created_at as Date,
      updatedAt: record.updated_at as Date,
    };
  }
}

/**
 * Business Rules Engine Service — GoRules (zen-engine)
 *
 * Evaluates business rules using the GoRules zen-engine and
 * JSON Decision Model (JDM) files stored in ./jdm/.
 *
 * Each entity type maps to a dedicated JDM file:
 {{#each entities}}
 *   {{tableName}}  → jdm/{{tableName}}.jdm.json
 {{/each}}
 *
 * Decision tables use hitPolicy "collect" so all matching rows are
 * returned, enabling multiple validation errors in a single call.
 *
 * NOTE: zen-engine silently drops any rule row that does not set a value for
 * every output column the table declares. When adding an output column to a
 * decision table, give every existing row an explicit "''" for it, or the whole
 * table stops matching.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { Injectable, Logger, OnModuleDestroy } from '@nestjs/common';
import { ZenEngine } from '@gorules/zen-engine';
import { readFileSync } from 'fs';
import { join } from 'path';

export interface RuleAction {
  type: 'validate' | 'notify' | 'prevent' | 'transform' | 'cascade-update' | 'cascade-delete' | 'cascade-create' | 'trigger-workflow';
  config: Record<string, unknown>;
}

export interface RuleEvaluationResult {
  ruleId: string;
  ruleName: string;
  matched: boolean;
  actions: RuleAction[];
  errors?: string[];
}

/**
 * Shape of each output row returned by a GoRules decision table.
 *
 * Everything past `ruleId` is action configuration: `workflowName` for
 * trigger-workflow, and `targetEntity` / `linkField` / `updateData` for the
 * cascade actions. Decision tables only need to emit the columns the action
 * they select actually uses.
 */
interface JdmViolation {
  action: string;
  message: string;
  ruleId: string;
  rule_id?: string;
  workflowName?: string;
  /** cascade-update | cascade-delete | cascade-create: table to act on */
  targetEntity?: string;
  /** cascade-update | cascade-delete: column on targetEntity holding this row's id */
  linkField?: string;
  /** cascade-update: column/value pairs to set (JSON object, or a JSON string) */
  updateData?: Record<string, unknown> | string;
  /** cascade-create: column/value pairs to insert (JSON object, or a JSON string) */
  createData?: Record<string, unknown> | string;
  /** transform: column/value pairs to apply to the row being written */
  transformData?: Record<string, unknown> | string;
}

/**
 * A record as zen reads it.
 *
 * What reaches a rule is often a row read back from the database, whose date
 * columns are Date objects — and a Date reaches zen as `{}`. A rule whose schema
 * types `due_on` as a string then failed on every such record ("/due_on: {} is
 * not of types null, string"), the failure was logged as a warning, and the
 * write went through: every rule on an entity with a date column was silently
 * off. The JSON form is what zen reads — a Date becomes its ISO string.
 */
function asZenInput(data: Record<string, unknown>): Record<string, unknown> {
  return JSON.parse(JSON.stringify(data ?? {})) as Record<string, unknown>;
}

@Injectable()
export class RulesEngine implements OnModuleDestroy {
  private readonly logger = new Logger(RulesEngine.name);

  /** Single ZenEngine instance — thread-safe, reused across requests */
  private readonly engine: ZenEngine;

  /** Maps entity type names to their JDM file names */
  private readonly jdmFiles: Record<string, string> = {
    {{#each entities}}
    {{tableName}}: '{{tableName}}.jdm.json',
    {{/each}}
  };

  constructor() {
    this.engine = new ZenEngine();
  }

  /** Release native resources when the NestJS module shuts down */
  onModuleDestroy(): void {
    this.engine.dispose();
  }

  /** Get the ZenEngine instance for external use */
  getEngine(): ZenEngine {
    return this.engine;
  }

  /**
   * Evaluate rules with provided JDM content (from database)
   */
  async evaluateRulesWithJDM(
    entityType: string,
    jdmContent: string,
    data: Record<string, unknown>,
    action: 'create' | 'update' | 'delete',
    dbRuleName?: string,
  ): Promise<RuleEvaluationResult[]> {
    this.logger.log(`Evaluating rules for ${entityType}:${action}`);

    // A %%rule drawn as a flowchart with no %%action rows is documentation: its
    // switch and expression nodes carry no `content`, which the engine rejects
    // with "missing field `content`". It decides nothing, so say nothing —
    // rather than logging an error on every write to the entity.
    if (this.isDiagramOnly(jdmContent)) {
      this.logger.debug(`Rule ${dbRuleName ?? ''} on ${entityType} is a diagram only; skipped`);
      return [];
    }

    try {
      const decision = this.engine.createDecision(Buffer.from(this.asJdmGraph(jdmContent)));
      // `_operation` carries the CRUD verb. It is deliberately not called
      // `action`: that name belongs to the record. A model with an `action`
      // column could never fire its own rules against it, because the engine
      // had already replaced the value with "create"/"update" — and a required
      // -field rule on such a column could never fire at all, since the
      // injected value made the field look present even when it was omitted.
      // Rules read the operation from `_operation`; the payload is passed
      // through untouched.
      const result = await decision.evaluate({ ...asZenInput(data), _operation: action });

      let violations: JdmViolation[] = [];

      if (Array.isArray(result.result)) {
        violations = result.result as JdmViolation[];
      } else if (result.result && typeof result.result === 'object') {
        violations = [result.result as JdmViolation];
      }

      return violations.map((v) => ({
        ruleId: dbRuleName || v.ruleId || v.rule_id || 'unknown',
        ruleName: dbRuleName || v.ruleId || v.rule_id || 'unknown',
        matched: true,
        actions: [{ type: this.actionType(v.action), config: this.toActionConfig(v) }],
      }));
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      this.logger.error(`Error evaluating rules for ${entityType}: ${message}`);
      return [
        {
          ruleId: 'engine-error',
          ruleName: 'Rules Engine Error',
          matched: false,
          actions: [],
          errors: [message],
        },
      ];
    }
  }

  /**
   * Evaluate all rules for a given entity type and action.
   *
   * @param entityType  The bus_ table name (e.g. 'bus_patient')
   * @param data        The entity data to validate
   * @param action      The CRUD operation being performed
   * @returns           Array of matched rule results (empty if no violations)
   */
  async evaluateRules(
    entityType: string,
    data: Record<string, unknown>,
    action: 'create' | 'update' | 'delete',
  ): Promise<RuleEvaluationResult[]> {
    this.logger.log(`Evaluating rules for ${entityType}:${action}`);

    const jdmFile = this.jdmFiles[entityType];
    if (!jdmFile) {
      this.logger.debug(`No JDM rules configured for entity: ${entityType}`);
      return [];
    }

    const jdmPath = join(__dirname, 'jdm', jdmFile);
    let content: Buffer;
    try {
      content = readFileSync(jdmPath);
    } catch {
      this.logger.warn(`JDM file not found for ${entityType}: ${jdmPath}`);
      return [];
    }

    let violations: JdmViolation[] = [];
    try {
      const decision = this.engine.createDecision(content);
      // `_operation` carries the CRUD verb. It is deliberately not called
      // `action`: that name belongs to the record. A model with an `action`
      // column could never fire its own rules against it, because the engine
      // had already replaced the value with "create"/"update" — and a required
      // -field rule on such a column could never fire at all, since the
      // injected value made the field look present even when it was omitted.
      // Rules read the operation from `_operation`; the payload is passed
      // through untouched.
      const result = await decision.evaluate({ ...asZenInput(data), _operation: action });

      // hitPolicy "collect" returns an array; single-match returns an object or null
      if (Array.isArray(result.result)) {
        violations = result.result as JdmViolation[];
      } else if (result.result && typeof result.result === 'object') {
        violations = [result.result as JdmViolation];
      }
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : String(error);
      this.logger.error(`Error evaluating rules for ${entityType}: ${message}`);
      return [
        {
          ruleId: 'engine-error',
          ruleName: 'Rules Engine Error',
          matched: false,
          actions: [],
          errors: [message],
        },
      ];
    }

    return violations.map((v) => ({
      ruleId: v.ruleId,
      ruleName: v.ruleId,
      matched: true,
      actions: [{ type: this.actionType(v.action), config: this.toActionConfig(v) }],
    }));
  }

  /**
   * A stored rule, as the graph the engine evaluates.
   *
   * The rule editor saves what it edits — a bare decision table, `{ inputs,
   * outputs, rules }` — while the engine needs a JDM graph with `nodes`. Every
   * rule created in the editor, and every model rule re-saved there, was
   * therefore reported as "missing field `nodes`" and refused nothing. A graph
   * is passed through untouched; a table is wrapped in one here, which also
   * mends the rows already saved that way.
   *
   * The editor writes cells as an author reads them: `"cancelled"` or `> 0`
   * under an input, and plain words under an outcome — `validation-error`, a
   * sentence of message. An input cell is a unary test against its field, so
   * a bare word is quoted to mean equality. An outcome cell is an expression,
   * where `validation-error` is a subtraction, so text is written as a string
   * literal unless it already is one or is a number, a boolean or an object.
   */
  /** True for a graph whose logic nodes carry no `content` (a drawn, inert rule). */
  isDiagramOnly(jdmContent: string): boolean {
    try {
      const nodes = (JSON.parse(jdmContent) as { nodes?: Array<{ type?: string; content?: unknown }> })
        .nodes;
      if (!Array.isArray(nodes)) return false;
      return nodes.some(
        (node) =>
          node.type !== 'inputNode' && node.type !== 'outputNode' && node.content === undefined,
      );
    } catch {
      return false;
    }
  }

  /** A stored rule as the graph the engine runs — what every reader goes through. */
  prepare(jdmContent: string): string {
    return this.asJdmGraph(jdmContent);
  }

  /** Source the function sandbox must never be handed. */
  private static readonly FORBIDDEN_FUNCTION_SOURCE = /\b(?:import|require|fetch|eval|process|globalThis)\b/;

  /**
   * Why a graph the rule editor drew cannot run, one sentence each.
   *
   * The same checks the modelling tool's compiler makes, so a graph refused
   * there is refused here: a function with no handler, or one reaching for the
   * network, the module system or the process; a node with no content; an edge
   * to a node that is not there.
   */
  graphProblems(jdmContent: string): string[] {
    let graph: { nodes?: Array<Record<string, any>>; edges?: Array<Record<string, any>> };
    try {
      graph = JSON.parse(jdmContent);
    } catch {
      return ['the rule is not valid JSON'];
    }
    if (!graph || !Array.isArray(graph.nodes)) return [];
    const problems: string[] = [];
    const ids = new Set<string>();
    for (const node of graph.nodes) {
      const label = String(node.name ?? node.id);
      ids.add(String(node.id));
      if (node.type === 'inputNode' || node.type === 'outputNode') continue;
      if (node.content === undefined || node.content === null) {
        problems.push(`${node.type} "${label}" has no content, so the engine would reject it`);
      }
      if (node.type === 'functionNode') {
        const content = node.content;
        const source =
          typeof content === 'string'
            ? content
            : typeof content?.source === 'string'
              ? content.source
              : '';
        if (!/\bhandler\b/.test(source)) {
          problems.push(
            `functionNode "${label}" defines no handler; write export const handler = async (input) => ({ ... })`,
          );
        }
        if (RulesEngine.FORBIDDEN_FUNCTION_SOURCE.test(source)) {
          problems.push(
            `functionNode "${label}" uses import, require, fetch, eval, process or globalThis, which the sandbox does not allow`,
          );
        }
      }
    }
    for (const edge of graph.edges ?? []) {
      if (!ids.has(String(edge.sourceId)) || !ids.has(String(edge.targetId))) {
        problems.push(`edge "${String(edge.id)}" joins a node that is not in the graph`);
      }
    }
    return problems;
  }

  /**
   * Speak the runtime's vocabulary in a graph the editor drew.
   *
   * zen runs a function node only from `content: { source }`: a bare string is
   * refused, or returns {} and decides nothing. A transform row needs the one
   * `transformData` object the runtime applies — the editor's Field and Value
   * columns are for the author to read, not for the runtime.
   */
  private normalizeGraph(graph: { nodes: Array<Record<string, any>> }): unknown {
    const literal = (cell: unknown): string | null => {
      const match = String(cell ?? '')
        .trim()
        .match(/^(?:'(.*)'|"(.*)")$/s);
      return match ? (match[1] ?? match[2] ?? '') : null;
    };
    return {
      ...graph,
      nodes: graph.nodes.map((node) => {
        if (node.type === 'functionNode' && typeof node.content === 'string') {
          return { ...node, content: { source: node.content } };
        }
        const original = node.content as
          | {
              outputs?: Array<{ id: string; name?: string; field?: string }>;
              rules?: Array<Record<string, unknown>>;
            }
          | undefined;
        if (node.type !== 'decisionTableNode' || !Array.isArray(original?.rules)) return node;
        // The editor's word for a refusal is `validation-error`; this engine's is
        // `prevent`. The Simulator should show the answer the application acts on,
        // so the cells are put in the engine's word here, as the compiler does.
        // An input cell that says only "is empty" (`null`) or "is not empty" (`!= null`) is
        // widened to cover a blank string too: a text field a person cleared arrives as "".
        const inputIds = new Set(((original as { inputs?: Array<{ id: string }> }).inputs ?? []).map((c) => c.id));
        const widen = (key: string, cell: string): string => {
          if (!inputIds.has(key)) return cell;
          const text = cell.trim();
          if (text === 'null') return 'null, ""';
          if (text === '!= null') return '!= null and != ""';
          return cell;
        };
        const table = {
          ...original,
          rules: original.rules.map((row) =>
            Object.fromEntries(
              Object.entries(row).map(([key, cell]) => [
                key,
                typeof cell === 'string' ? widen(key, cell.replace(/(["'])validation-error\1/g, '$1prevent$1')) : cell,
              ]),
            ),
          ),
        };
        const outputs = table.outputs ?? [];
        const fieldColumn = outputs.find((c) => c.field === 'field');
        const valueColumn = outputs.find((c) => c.field === 'value');
        const actionColumn = outputs.find((c) => c.field === 'action');
        if (
          !fieldColumn ||
          !valueColumn ||
          !actionColumn ||
          outputs.some((c) => c.field === 'transformData')
        ) {
          return { ...node, content: table };
        }
        const dataColumn = { id: 'transformData-auto', name: 'Transform Data', field: 'transformData' };
        return {
          ...node,
          content: {
            ...table,
            outputs: [...outputs, dataColumn],
            rules: table.rules.map((row) => {
              const target = literal(row[fieldColumn.id])?.trim();
              const isTransform = literal(row[actionColumn.id])?.trim() === 'transform';
              // Every row needs a cell in the new column: zen skips a row that has none.
              if (!isTransform || !target) return { ...row, [dataColumn.id]: row[dataColumn.id] ?? '' };
              const value = literal(row[valueColumn.id]) ?? String(row[valueColumn.id] ?? '');
              const data = JSON.stringify({ [target]: value }).replace(/'/g, "\\'");
              return { ...row, [dataColumn.id]: `'${data}'` };
            }),
          },
        };
      }),
    };
  }

  private asJdmGraph(jdmContent: string): string {
    let parsed: unknown;
    try {
      parsed = JSON.parse(jdmContent);
    } catch {
      return jdmContent;
    }
    const table = parsed as {
      nodes?: unknown;
      hitPolicy?: string;
      inputs?: Array<{ id: string; name?: string; field?: string }>;
      outputs?: Array<{ id: string; name?: string; field?: string }>;
      rules?: Array<Record<string, string>>;
    };
    if (table && typeof table === 'object' && table.nodes) {
      return JSON.stringify(this.normalizeGraph(parsed as { nodes: Array<Record<string, any>> }));
    }
    if (!table || typeof table !== 'object') return jdmContent;
    if (!Array.isArray(table.inputs) || !Array.isArray(table.outputs) || !Array.isArray(table.rules)) {
      return jdmContent;
    }

    const quote = (text: string) => `'${text.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
    const isLiteral = (text: string) =>
      /^'.*'$|^".*"$/.test(text) ||
      /^-?\d+(\.\d+)?$/.test(text) ||
      /^(true|false|null)$/.test(text) ||
      /^[[{]/.test(text);
    const inputCell = (raw: string) => {
      const text = (raw ?? '').trim();
      if (!text || isLiteral(text)) return text;
      return /^[A-Za-z_][\w-]*$/.test(text) ? quote(text) : text;
    };
    const outputCell = (raw: string) => {
      const text = (raw ?? '').trim();
      if (!text) return "''";
      return isLiteral(text) ? text : quote(text);
    };

    const rules = table.rules.map((row) => {
      const next: Record<string, string> = { _id: row._id ?? '' };
      for (const column of table.inputs ?? []) next[column.id] = inputCell(row[column.id] ?? '');
      for (const column of table.outputs ?? []) next[column.id] = outputCell(row[column.id] ?? '');
      return next;
    });

    return JSON.stringify({
      nodes: [
        { id: 'input', type: 'inputNode', name: 'Input', position: { x: 0, y: 0 } },
        {
          id: 'table',
          type: 'decisionTableNode',
          name: 'Decision table',
          position: { x: 300, y: 0 },
          content: {
            hitPolicy: table.hitPolicy === 'first' ? 'first' : 'collect',
            inputs: table.inputs.map((c) => ({ id: c.id, name: c.name ?? c.field ?? c.id, field: c.field ?? '' })),
            outputs: table.outputs.map((c) => ({ id: c.id, name: c.name ?? c.field ?? c.id, field: c.field || c.name || c.id })),
            rules,
          },
        },
        { id: 'output', type: 'outputNode', name: 'Output', position: { x: 600, y: 0 } },
      ],
      edges: [
        { id: 'e1', sourceId: 'input', targetId: 'table', type: 'edge' },
        { id: 'e2', sourceId: 'table', targetId: 'output', type: 'edge' },
      ],
    });
  }

  /**
   * A row's action, in this engine's vocabulary.
   *
   * The rule editor offers EML's words — the ones a model is written in and
   * the modelling tool's editor writes — and EML says `validation-error` where
   * this engine says `prevent`. The generator translates when it compiles a
   * model's rules, but a rule written in this application's own editor goes
   * straight into `sys_rule_definitions`, so an untranslated row matched and
   * was then dropped by `validate()`: the rule refused nothing. Accept both.
   */
  private actionType(raw: unknown): RuleAction['type'] {
    const type = typeof raw === 'string' ? raw.trim() : '';
    return (type === 'validation-error' ? 'prevent' : type) as RuleAction['type'];
  }

  /**
   * Carry the whole decision-table output row into the action config.
   *
   * Only `message` and `workflowName` used to survive this step, which left the
   * cascade actions permanently unconfigurable — they read `targetEntity`,
   * `linkField` and `updateData`, and those were always undefined no matter what
   * the decision table emitted.
   */
  private toActionConfig(v: JdmViolation): Record<string, unknown> {
    return {
      message: v.message,
      workflowName: v.workflowName,
      targetEntity: v.targetEntity,
      linkField: v.linkField,
      updateData: this.asObject(v.updateData),
      createData: this.asObject(v.createData),
      transformData: this.asObject(v.transformData),
    };
  }

  /** Decision tables can emit an object or a JSON string; accept either. */
  private asObject(value: Record<string, unknown> | string | undefined): Record<string, unknown> | undefined {
    if (!value) return undefined;
    if (typeof value !== 'string') return value;
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' ? (parsed as Record<string, unknown>) : undefined;
    } catch {
      this.logger.warn(`Rule action data is not valid JSON: ${value}`);
      return undefined;
    }
  }
}

{
  "nodes": [
    {
      "id": "input",
      "type": "inputNode",
      "name": "Input",
      "position": { "x": 0, "y": 0 }
    },
    {
      "id": "{{tableName}}-validation",
      "type": "decisionTableNode",
