  UpdateRuleSchema,
  ValidateJdmSchema,
  DryRunSchema,
  SimulateRuleSchema,
  EvaluateRulesSchema,
} from './dto/rules.dto';

@ApiTags('rules')
@ApiBearerAuth()
@UseGuards(SessionAuthGuard, RolesGuard)
@Controller('rules')
export class RulesController {
  private readonly logger = new Logger(RulesController.name);

  constructor(private readonly rulesService: RulesService) {}

  @Get()
  @ApiOperation({ summary: 'List all business rules' })
  @ApiResponse({ status: 200, description: 'Rules retrieved successfully' })
  async list(
    @Query('entityName') entityName?: string,
    @Query('operation') operation?: string,
    @Query('isActive') isActive?: string,
  ) {
    const filters: Record<string, unknown> = {};
    if (entityName) filters.entityName = entityName;
    if (operation) filters.operation = operation;
    if (isActive !== undefined) filters.isActive = isActive === 'true';

    return await this.rulesService.findAll(filters as any);
  }

  // NOTE: static routes must be declared before ':id' or they get shadowed
  @Get('entities')
  @ApiOperation({ summary: 'Get list of entities that have business rules configured' })
  @ApiResponse({ status: 200, description: 'Entity list retrieved' })
  getEntitiesWithRules() {
    return {
      entities: [
        {{#each entities}}
        { entityType: '{{tableName}}', entityName: '{{name}}' },
        {{/each}}
      ],
    };
  }

  @Get(':id')
  @ApiOperation({ summary: 'Get rule by ID' })
  @ApiResponse({ status: 200, description: 'Rule retrieved successfully' })
  @ApiResponse({ status: 404, description: 'Rule not found' })
  async get(@Param('id') id: string) {
    return await this.rulesService.findById(id);
  }

  @Post()
  @Roles('admin')
  @ApiOperation({ summary: 'Create a new business rule (admin only)' })
  @ApiResponse({ status: 201, description: 'Rule created successfully' })
  @ApiResponse({ status: 400, description: 'Invalid input' })
  @ApiResponse({ status: 409, description: 'Rule already exists' })
  async create(
    @Body(new ZodValidationPipe(CreateRuleSchema)) dto: {
      entityName: string;
      ruleName: string;
      operation: string;
      jdmContent: string;
      title?: string | null;
    },
    @CurrentUser() user: { id: string },
  ) {
    return await this.rulesService.create(
      {
        entityName: dto.entityName,
        ruleName: dto.ruleName,
        operation: dto.operation as any,
        jdmContent: dto.jdmContent,
        title: dto.title,
      },
      user.id,
    );
  }

  @Put(':id')
  @Roles('admin')
  @ApiOperation({ summary: 'Update an existing rule (admin only)' })
  @ApiResponse({ status: 200, description: 'Rule updated successfully' })
  @ApiResponse({ status: 404, description: 'Rule not found' })
  async update(
    @Param('id') id: string,
    @Body(new ZodValidationPipe(UpdateRuleSchema)) dto: {
      jdmContent?: string;
      isActive?: boolean;
      title?: string | null;
      operation?: 'CREATE' | 'UPDATE' | 'DELETE' | 'ALL';
    },
    @CurrentUser() user: { id: string },
  ) {
    return await this.rulesService.update(id, dto, user.id);
  }

  @Delete(':id')
  @Roles('admin')
  @ApiOperation({
    summary:
      'Deactivate a rule (admin only). With ?permanent=true, remove one that is already inactive.',
  })
  @ApiResponse({ status: 200, description: 'Rule deactivated, or removed' })
  async delete(@Param('id') id: string, @Query('permanent') permanent?: string) {
    if (permanent === 'true') {
      await this.rulesService.purge(id);
      return { message: 'Rule deleted permanently' };
    }
    await this.rulesService.delete(id);
    return { message: 'Rule deactivated successfully' };
  }

  @Get(':id/history')
  @ApiOperation({ summary: 'Get rule version history' })
  @ApiResponse({ status: 200, description: 'History retrieved successfully' })
  async history(@Param('id') id: string) {
    return await this.rulesService.getHistory(id);
  }

  @Post('validate')
  @ApiOperation({ summary: 'Validate JDM content' })
  @ApiResponse({ status: 200, description: 'Validation result' })
  async validate(@Body(new ZodValidationPipe(ValidateJdmSchema)) dto: { jdmContent: string }) {
    return await this.rulesService.validateJDM(dto.jdmContent);
  }

  @Post('dry-run')
  @ApiOperation({ summary: 'Dry run rule with test context' })
  @ApiResponse({ status: 200, description: 'Dry run completed' })
  async dryRun(@Body(new ZodValidationPipe(DryRunSchema)) dto: { ruleId: string; testData: Record<string, unknown> }) {
    const rule = await this.rulesService.findById(dto.ruleId);
    return await this.rulesService.dryRun(rule.jdmContent, dto.testData);
  }

  /**
   * Run a rule as the editor holds it — saved or not — and say what each node
   * produced. A function node is code and this runs it, so it is admin only,
   * like saving a rule.
   */
  @Post('simulate')
  @Roles('admin')
  @ApiOperation({ summary: 'Run an unsaved rule graph against a sample record (admin only)' })
  @ApiResponse({ status: 200, description: 'The result and a trace of each node' })
  async simulate(
    @Body(new ZodValidationPipe(SimulateRuleSchema)) dto: {
      jdmContent: string | Record<string, unknown>;
      testData: Record<string, unknown>;
      entityName?: string;
    },
  ) {
    return await this.rulesService.simulate(dto.jdmContent, dto.testData);
  }

  @Post('migrate')
  @Roles('admin')
  @ApiOperation({ summary: 'Migrate rules from files to database (admin only)' })
  @ApiResponse({ status: 200, description: 'Migration completed' })
  async migrate() {
    const result = await this.rulesService.migrateFromFileSystem();
    return {
      migrated: result.migrated,
      errors: result.errors,
      message: `Migrated ${result.migrated} rules from files to database`,
    };
  }

  @Post('evaluate')
  @ApiOperation({ summary: 'Evaluate business rules for an entity' })
  @ApiResponse({ status: 200, description: 'Rules evaluated successfully' })
  async evaluateRules(
    @Body(new ZodValidationPipe(EvaluateRulesSchema))
    body: {
      entityName: string;
      operation: 'CREATE' | 'READ' | 'UPDATE' | 'DELETE';
      data: Record<string, unknown>;
    },
  ) {
    const operationMap: Record<string, 'create' | 'update' | 'delete'> = {
      CREATE: 'create',
      UPDATE: 'update',
      DELETE: 'delete',
      READ: 'create',
    };

    const mappedOperation = operationMap[body.operation] || 'create';
    const results = await this.rulesService.evaluate(
      body.entityName,
      body.data,
      mappedOperation,
    );

    return {
      entityName: body.entityName,
      operation: body.operation,
      results,
    };
  }

}

