/**
 * A workflow that failed while its caller owns the transaction. The caller rolls
 * back, so the run row it wrote dies with the rollback; carrying the workflow and
 * the reason lets the caller put the failure back afterwards (recordFailedRun),
 * and show a person which workflow it was.
 */
export class WorkflowRunError extends Error {
  constructor(
    readonly workflow: string,
    readonly reason: string,
    readonly operation: string,
  ) {
    super(`Workflow "${workflow}" failed: ${reason}`);
    this.name = 'WorkflowRunError';
  }
}

export interface WorkflowRunOptions {
  /** Run every write on this connection. Pass a transaction to make the run atomic. */
  db?: Kysely<any>;
  /** Throw instead of swallowing a failure, so an enclosing transaction rolls back. */
  throwOnError?: boolean;
}

export interface WorkflowStatus {
