import { Module, Global, OnModuleDestroy, Inject } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { Kysely, PostgresDialect } from 'kysely';
import { Pool } from 'pg';
import { KYSELY_CONNECTION } from './database.constants';
import { DatabaseService } from './database.service';

function buildPoolConfig(configService: ConfigService) {
  const url = configService.get<string>('DATABASE_URL');
  if (url) {
    return { connectionString: url };
  }
  return {
    host: configService.get('DB_HOST', '127.0.0.1'),
    port: configService.get<number>('DB_PORT', 5432),
    user: configService.get('DB_USER', '{{snakeCase project.name}}'),
    password: configService.get('DB_PASSWORD', ''),
    database: configService.get('DB_NAME', '{{snakeCase project.name}}'),
  };
}

@Global()
@Module({
  providers: [
    {
      provide: KYSELY_CONNECTION,
      inject: [ConfigService],
      useFactory: async (configService: ConfigService) => {
        const pool = new Pool(buildPoolConfig(configService));
        const db = new Kysely<any>({ dialect: new PostgresDialect({ pool }) });

        try {
          await db.selectFrom('information_schema.tables' as any).limit(1).execute();
          console.log('✓ Database connection established');
        } catch (error) {
          console.warn('⚠ Database connection check failed:', error instanceof Error ? error.message : String(error));
        }

        return db;
      },
    },
    DatabaseService,
  ],
  exports: [KYSELY_CONNECTION, DatabaseService],
})
export class DatabaseModule implements OnModuleDestroy {
  constructor(@Inject(KYSELY_CONNECTION) private readonly db: Kysely<any>) {}

  async onModuleDestroy() {
    await this.db.destroy();
    console.log('✓ Database connection closed');
  }
}

/**
 * Database Service with Kysely
 *
 * Generated: {{now}}
 */

import { Injectable, Inject, NotFoundException, ConflictException } from '@nestjs/common';
import { Kysely, sql } from 'kysely';
import { v4 as uuidv4 } from 'uuid';
import { KYSELY_CONNECTION } from './database.constants';

export interface PaginationOptions {
  page?: number;
  limit?: number;
  orderBy?: string;
  orderDir?: 'asc' | 'desc';
  search?: string;
  searchFields?: string[];
}

export interface PaginatedResult<T> {
  data: T[];
  meta: {
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  };
}

@Injectable()
export class DatabaseService {
  public readonly kysely: Kysely<any>;

  constructor(@Inject(KYSELY_CONNECTION) kysely: Kysely<any>) {
    this.kysely = kysely;
  }

  /**
   * Start a transaction
   */
  async transaction<T>(callback: (trx: Kysely<any>) => Promise<T>): Promise<T> {
    return this.kysely.transaction().execute(callback);
  }

  /**
   * Find all records in a table with pagination
   */
  async findAll<T>(
    tableName: string,
    options: PaginationOptions = {},
    filters: Record<string, any> = {},
  ): Promise<PaginatedResult<T>> {
    const rawPage = options.page;
    const rawLimit = options.limit;
    const page = (typeof rawPage === 'number' && !isNaN(rawPage) && rawPage > 0) ? Math.floor(rawPage) : 1;
    const limit = (typeof rawLimit === 'number' && !isNaN(rawLimit) && rawLimit > 0) ? Math.floor(rawLimit) : 20;
    const orderBy = options.orderBy || 'created_at';
    const orderDir = options.orderDir || 'desc';

    const offset = (page - 1) * limit;

    let query = this.kysely
      .selectFrom(tableName as any)
      .selectAll()
      .where('deleted_at' as any, 'is', null);

    /*
     * Every filter arrives as `{ operator, value }` — see `parseFilters` in
     * bus.controller. It used to arrive as a bare value and the operator was
     * inferred from whether the string contained a `%`, which was wrong twice
     * over: an `equals` on a value that legitimately contains a percent sign
     * ("50% off") silently became a pattern match, and a `contains` on any
     * non-text column asked PostgreSQL for `uuid ~~* unknown` and got an error
     * instead of results.
     */
    for (const [key, raw] of Object.entries(filters)) {
      const spec =
        raw && typeof raw === 'object' && 'operator' in raw
          ? (raw as { operator: string; value: unknown })
          : { operator: '=', value: raw };

      // `is null` / `is not null` are the two clauses whose value is *meant*
      // to be null — a window filtering on `deleted_by=isNull` would otherwise
      // be dropped here as an empty filter and show every row.
      if (spec.operator === 'is' || spec.operator === 'is not') {
        query = query.where(key as any, spec.operator as any, null as any);
        continue;
      }

      if (spec.value === undefined || spec.value === null || spec.value === '') continue;

      // `in` over nothing matches nothing — a "waiting for me" list with no
      // moves to make is empty, not unfiltered.
      if (spec.operator === 'in' && Array.isArray(spec.value) && spec.value.length === 0) {
        query = query.where(sql<boolean>`false`);
        continue;
      }
      // Mine or nobody's: a record assigned to this person, or to no one.
      if (spec.operator === '= or null') {
        query = query.where((eb: any) =>
          eb.or([eb(key as any, '=', spec.value as any), eb(key as any, 'is', null)]),
        );
        continue;
      }

      if (spec.operator === 'ilike') {
        // Cast, so a pattern match works on any column the dictionary offers
        // rather than only the text ones.
        query = query.where(sql`${sql.ref(key)}::text`, 'ilike', spec.value as any);
      } else {
        query = query.where(key as any, spec.operator as any, spec.value as any);
      }
    }

    const countResult = await (query as any)
      .clearSelect()
      .select((eb: any) => eb.fn.countAll().as('count'))
      .executeTakeFirst();
    const total = Number(countResult?.count ?? 0);

    /*
     * The primary key is appended as a tiebreaker, always.
     *
     * `created_at` is the default sort and it is not unique: a seed inserts a
     * whole table in one statement, so every row shares a timestamp to the
     * microsecond. PostgreSQL is then free to return equal rows in any order it
     * likes, and it does — which makes LIMIT/OFFSET paging unsound. Page 1 and
     * page 2 came back sharing a row and between them missed another, so a
     * reader paging a list silently never saw part of it.
     *
     * Ordering by a unique column last makes the sequence total, so a page
     * boundary falls in the same place every time. Skipped when the caller
     * already sorted by the key, which would otherwise emit it twice.
     */
    const ordered =
      orderBy === 'id'
        ? query.orderBy(orderBy as any, orderDir)
        : query.orderBy(orderBy as any, orderDir).orderBy('id' as any, 'asc');

    const data = await ordered
      .limit(Number(limit))
      .offset(Number(offset))
      .execute();

    return {
      data: data as T[],
      meta: {
        total,
        page,
        limit,
        totalPages: Math.ceil(total / limit),
      },
    };
  }

  /**
   * Find a single record by ID
   */
  async findById<T>(tableName: string, id: string): Promise<T | null> {
    const record = await this.kysely
      .selectFrom(tableName as any)
      .selectAll()
      .where('id' as any, '=', id)
      .where('deleted_at' as any, 'is', null)
      .executeTakeFirst();

    return (record as T) ?? null;
  }

  /**
   * Find a single record by ID or throw NotFoundException
   */
  async findByIdOrFail<T>(tableName: string, id: string): Promise<T> {
    const record = await this.findById<T>(tableName, id);

    if (!record) {
      throw new NotFoundException(`Record not found in ${tableName} with id ${id}`);
    }

    return record;
  }

  /**
   * Find records by a specific field
   */
  async findBy<T>(tableName: string, field: string, value: any): Promise<T[]> {
    const records = await this.kysely
      .selectFrom(tableName as any)
      .selectAll()
      .where(field as any, '=', value)
      .where('deleted_at' as any, 'is', null)
      .execute();

    return records as T[];
  }

  /**
   * Create a new record
   */
  async create<T>(tableName: string, data: Partial<T>): Promise<T> {
    const id = (data as any).id || uuidv4();
    const now = new Date();

    const record = {
      ...data,
      id,
      version: 1,
      created_at: now,
      updated_at: now,
    };

    await this.kysely.insertInto(tableName as any).values(record).execute();

    return this.findByIdOrFail<T>(tableName, id);
  }

  /**
   * Update an existing record with optimistic concurrency control
   */
  async update<T>(
    tableName: string,
    id: string,
    data: Partial<T>,
    expectedVersion?: number,
  ): Promise<T> {
    const existing = await this.findByIdOrFail<T & { version: number }>(tableName, id);

    if (expectedVersion !== undefined && existing.version !== expectedVersion) {
      throw new ConflictException(
        `Record has been modified by another user. Expected version ${expectedVersion}, current version ${existing.version}`,
      );
    }

    await this.kysely
      .updateTable(tableName as any)
      .set({
        ...data,
        version: sql`version + 1`,
        updated_at: new Date(),
      } as any)
      .where('id' as any, '=', id)
      .execute();

    return this.findByIdOrFail<T>(tableName, id);
  }

  /**
   * Soft delete a record
   */
  async softDelete(tableName: string, id: string): Promise<boolean> {
    await this.findByIdOrFail(tableName, id);

    const result = await this.kysely
      .updateTable(tableName as any)
      .set({ deleted_at: new Date(), updated_at: new Date() } as any)
      .where('id' as any, '=', id)
      .executeTakeFirst();

    return Number(result.numUpdatedRows) > 0;
  }

  /**
   * Permanently delete a record
   */
  async hardDelete(tableName: string, id: string): Promise<boolean> {
    const result = await this.kysely
      .deleteFrom(tableName as any)
      .where('id' as any, '=', id)
      .executeTakeFirst();

    return Number(result.numDeletedRows) > 0;
  }

  /**
   * Restore a soft-deleted record
   */
  async restore(tableName: string, id: string): Promise<boolean> {
    const result = await this.kysely
      .updateTable(tableName as any)
      .set({ deleted_at: null, updated_at: new Date() } as any)
      .where('id' as any, '=', id)
      .where('deleted_at' as any, 'is not', null)
      .executeTakeFirst();

    return Number(result.numUpdatedRows) > 0;
  }

  /**
   * Count records in a table
   */
  async count(tableName: string, filters: Record<string, any> = {}): Promise<number> {
    let query = this.kysely
      .selectFrom(tableName as any)
      .select((eb: any) => eb.fn.countAll().as('count'))
      .where('deleted_at' as any, 'is', null);

    for (const [key, value] of Object.entries(filters)) {
      if (value !== undefined && value !== null) {
        query = query.where(key as any, '=', value);
      }
    }

    const result = await query.executeTakeFirst() as { count: string | number } | undefined;
    return Number(result?.count ?? 0);
  }

  /**
   * Check if a record exists
   */
  async exists(tableName: string, id: string): Promise<boolean> {
    const result = await this.kysely
      .selectFrom(tableName as any)
      .select('id' as any)
      .where('id' as any, '=', id)
      .where('deleted_at' as any, 'is', null)
      .executeTakeFirst();

    return !!result;
  }

  /**
   * Execute a raw SQL query
   */
  async raw<T>(sqlStr: string): Promise<T> {
    const result = await sql.raw(sqlStr).execute(this.kysely);
    return (result as any).rows as T;
  }
}

