/**
 * NestJS Application Entry Point with Fastify Adapter
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

// Loaded before anything else is imported. Nest's ConfigModule only runs once
// AppModule is being constructed, and modules imported below read
// `process.env` at their own load time — so without this, whether a variable
// is visible depends on import order rather than on being present in .env.
//
// The file is found by walking up rather than by a fixed `../`. This module
// runs from `src/` under `bun run src/main.ts` but from `dist/src/` after a
// Nest build, so any fixed depth is wrong in one of the two — which is how
// ELECTRIC_URL could sit in .env and still read as unset in a built server.
import { randomBytes } from 'crypto';
import { config as loadEnv } from 'dotenv';
import * as nodeFs from 'fs';
import * as nodePath from 'path';

function loadEnvFiles(): void {
  let dir = __dirname;
  for (let depth = 0; depth < 5; depth++) {
    if (nodeFs.existsSync(nodePath.join(dir, '.env'))) {
      loadEnv({ path: nodePath.join(dir, '.env') });
      loadEnv({ path: nodePath.join(dir, '.env.local'), override: true });
      return;
    }
    const parent = nodePath.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
}

loadEnvFiles();

import { NestFactory } from '@nestjs/core';
import { FastifyAdapter, NestFastifyApplication } from '@nestjs/platform-fastify';
import { ValidationPipe, Logger } from '@nestjs/common';
import { Kysely, PostgresDialect } from 'kysely';
import { Pool } from 'pg';
import { AppModule } from './app.module';
import {
  AppLoggerService,
  getLogger,
  installHttpLogging,
  installProcessLogging,
} from './common/logging/logger.service';
import { initAuth, getAuth } from './lib/better-auth';
import { AuditService } from './modules/audit/audit.service';

/**
 * The bootstrap administrator's password.
 *
 * `ADMIN_PASSWORD` when set, and otherwise a random one that is printed once
 * and stored nowhere it can be read back. It used to default to the literal
 * `admin123`, which every generated application shipped with and nothing
 * prompted anyone to change — a published password on every deployment.
 *
 * Must satisfy the `minPasswordLength` in src/lib/better-auth.ts. A shorter one
 * is rejected at sign-in with "Invalid email or password", which reads as a
 * wrong password rather than a password the server never allowed.
 */
function resolveAdminPassword(logger: Logger): { password: string; generated: boolean } {
  const configured = process.env.ADMIN_PASSWORD;
  if (configured && configured.length >= 8) return { password: configured, generated: false };

  if (configured) {
    logger.warn('ADMIN_PASSWORD is shorter than 8 characters and was ignored.');
  }

  return { password: randomBytes(18).toString('base64url'), generated: true };
}

async function ensureAdminUser(logger: Logger) {
  const adminEmail = process.env.ADMIN_EMAIL || 'admin@admin.com';
  const { password: adminPassword, generated: adminPasswordGenerated } =
    resolveAdminPassword(logger);

  const pool = process.env.DATABASE_URL
    ? new Pool({ connectionString: process.env.DATABASE_URL })
    : new Pool({
        host: process.env.DB_HOST ?? '127.0.0.1',
        port: Number(process.env.DB_PORT ?? 5432),
        user: process.env.DB_USER ?? process.env.USER ?? '{{snakeCase project.name}}',
        password: process.env.DB_PASSWORD ?? '',
        database: process.env.DB_NAME ?? '{{snakeCase project.name}}',
      });

  const db = new Kysely<any>({ dialect: new PostgresDialect({ pool }) });

  try {
    const auth = getAuth();

    // 1. Ensure Better Auth user exists with admin role
    let baUser = await db.selectFrom('user').select(['id', 'role', 'sysUserId']).where('email', '=', adminEmail).executeTakeFirst();

    if (!baUser) {
      await auth.api.signUpEmail({ body: { email: adminEmail, password: adminPassword, name: 'Admin User' } });
      baUser = await db.selectFrom('user').select(['id', 'role', 'sysUserId']).where('email', '=', adminEmail).executeTakeFirst();
      /*
       * The password is NOT logged.
       *
       * This line used to read `(password: ${adminPassword})`, writing the
       * administrator's credential in plaintext into whatever collects this
       * process's stdout — where it is shipped and retained under far weaker
       * access control than the row it came from.
       *
       * A generated password still has to reach the person who ran the
       * application, or the account is unreachable, so it is printed exactly
       * once and only when this process invented it. A password the operator
       * supplied is never echoed: they already have it.
       */
      logger.log(`Admin user created: ${adminEmail}`);
      if (adminPasswordGenerated) {
        logger.warn(
          `No ADMIN_PASSWORD was set. Generated one for ${adminEmail}: ${adminPassword}\n` +
            'This is shown once and is not recoverable. Sign in and change it, or set ' +
            'ADMIN_PASSWORD before first boot.',
        );
      }
    }

    if (!baUser) throw new Error('Could not find or create admin Better Auth user');

    if (baUser.role !== 'admin') {
      await db.updateTable('user').set({ role: 'admin' }).where('email', '=', adminEmail).execute();
    }

    // 2. Ensure sys_user record exists for admin
    let sysUser = await db.selectFrom('sys_user').select(['sys_user_id']).where('email', '=', adminEmail).executeTakeFirst();

    if (!sysUser) {
      const { randomUUID } = await import('crypto');
      const newSysUserId = randomUUID();
      await db.insertInto('sys_user').values({
        sys_user_id: newSysUserId,
        name: 'Admin User',
        email: adminEmail,
        password_hash: 'managed-by-better-auth',
        is_system_user: true,
        is_active: true,
        created_by: 'system',
        updated_by: 'system',
      }).execute();
      sysUser = { sys_user_id: newSysUserId };
      logger.log(`sys_user created for ${adminEmail}`);
    }

    // 3. Link sysUserId on the Better Auth user if not already set
    if (!baUser.sysUserId) {
      await db.updateTable('user').set({ sysUserId: sysUser.sys_user_id }).where('email', '=', adminEmail).execute();
    }

    // 4. Ensure Administrator role assignment (look up by name)
    const adminRole = await db.selectFrom('sys_role').select(['sys_role_id']).where('name', '=', 'Administrator').executeTakeFirst();

    if (adminRole) {
      const existing = await db.selectFrom('sys_user_roles')
        .select('sys_user_roles_id')
        .where('sys_user_id', '=', sysUser.sys_user_id)
        .where('sys_role_id', '=', adminRole.sys_role_id)
        .executeTakeFirst();

      if (!existing) {
        const { randomUUID } = await import('crypto');
        await db.insertInto('sys_user_roles').values({
          sys_user_roles_id: randomUUID(),
          sys_user_id: sysUser.sys_user_id,
          sys_role_id: adminRole.sys_role_id,
          entity_type: 'S',
          is_active: true,
          created_by: 'system',
          updated_by: 'system',
        }).execute();
        logger.log(`Administrator role assigned to sys_user ${adminEmail}`);
      }
    }

    logger.log(`Admin user ready: ${adminEmail} → sys_user ${sysUser.sys_user_id}`);
  } catch (err: any) {
    logger.warn(`Could not ensure admin user: ${err?.message ?? err}`);
  } finally {
    await db.destroy();
  }
}

/**
 * Record a sign-in, sign-out or sign-up on the audit trail.
 *
 * better-auth is mounted directly on Fastify to keep its cookie handling
 * intact, which puts it outside Nest's interceptor chain — so without this the
 * audit page showed every record change and not one login. Failures are
 * recorded too: a run of AUTH_LOGIN with success=false is what an attack looks
 * like from the trail.
 *
 * Never throws. An audit write must not be able to fail a login.
 */
async function recordAuthEvent(
  app: NestFastifyApplication,
  request: any,
  pathname: string,
  status: number,
): Promise<void> {
  const ACTIONS: Array<[RegExp, string]> = [
    [/sign-in/, 'AUTH_LOGIN'],
    [/sign-out/, 'AUTH_LOGOUT'],
    [/sign-up/, 'AUTH_REGISTER'],
    [/forget-password|reset-password/, 'AUTH_PASSWORD_RESET'],
    [/change-password/, 'AUTH_PASSWORD_CHANGE'],
    [/verify-email/, 'AUTH_EMAIL_VERIFY'],
  ];

  const matched = ACTIONS.find(([re]) => re.test(pathname));
  if (!matched) return;

  try {
    const audit = app.get(AuditService, { strict: false });
    if (!audit) return;

    const headers = request.headers ?? {};
    const body = typeof request.body === 'string' ? safeParse(request.body) : request.body;
    const success = status >= 200 && status < 400;

    await audit.log({
      user_id: null,
      user_name: null,
      // The only identifier available on a failed sign-in, and the one worth
      // having: it says which account was targeted.
      user_email: body?.email ?? null,
      session_id: null,
      action: matched[1],
      entity_type: 'auth',
      entity_id: null,
      before_value: null,
      after_value: null,
      changed_fields: [],
      ip_address:
        (headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ??
        request.socket?.remoteAddress ??
        null,
      user_agent: (headers['user-agent'] as string) ?? null,
      source: 'WEB_UI',
      request_id: (headers['x-request-id'] as string) ?? null,
      success,
      error_message: success ? null : `Authentication request failed with status ${status}`,
    } as any);
  } catch {
    // Swallowed on purpose — see the note above.
  }
}

function safeParse(value: string): any {
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

/**
 * TRUST_PROXY as Fastify wants it.
 *
 * Fastify accepts a boolean, a hop count, or a list of trusted addresses, and
 * they mean different things — so the string is mapped rather than coerced.
 * Anything unrecognised is handed through as an address list, which Fastify
 * validates itself; anything absent is `false`.
 */
function parseTrustProxy(value: string | undefined): boolean | number | string {
  if (!value) return false;
  const trimmed = value.trim();
  if (/^(true|yes|on)$/i.test(trimmed)) return true;
  if (/^(false|no|off)$/i.test(trimmed)) return false;
  if (/^\d+$/.test(trimmed)) return Number(trimmed);
  return trimmed;
}

async function bootstrap() {
  const logger = new Logger('Bootstrap');
  const log = getLogger('app');

  // Registered before anything can fail. An exception escaping an async
  // boundary used to take this process down with whatever the runtime printed
  // and nothing else; SIGTERM — how every orchestrator asks a container to stop
  // — was not recorded at all, which makes "why did it restart" unanswerable.
  installProcessLogging();

  log.event('app.starting', {
    name: '{{kebabCase project.name}}',
    version: '{{project.version}}',
    // `service` on every line carries the same name; this field is here
    // because a start-up line is where someone looks for it explicitly.
    env: process.env.NODE_ENV || 'development',
    nodeVersion: process.version,
  });

  /**
   * Configuration that is optional, and the feature that is off without it.
   *
   * Reported at boot rather than at first use. A feature quietly absent because
   * a variable was never set is the most common deployment mistake there is,
   * and it always presents as "the button does nothing".
   */
  for (const [key, feature] of [
    ['DATABASE_URL', 'the database connection'],
    ['BETTER_AUTH_SECRET', 'signed sessions'],
    ['CORS_ORIGIN', 'the browser origin allow-list'],
  ] as const) {
    if (!process.env[key]) log.event('app.config.missing', { key, feature });
  }

  // Initialize authentication system
  await initAuth();

  // Create NestJS app with Fastify adapter for high performance
  const app = await NestFactory.create<NestFastifyApplication>(
    AppModule,
    new FastifyAdapter({
      logger: process.env.NODE_ENV === 'development',
      /*
       * Whether `X-Forwarded-For` may be believed.
       *
       * Off unless TRUST_PROXY says otherwise, and that default is the
       * security-relevant half: with it on, any client can put whatever it
       * likes in the header, and `req.ip` — which the rate limiter falls back
       * to for anonymous callers, and which the audit trail records — becomes
       * whatever the caller claims. Turn it on only where a proxy you control
       * really does sit in front and overwrites the header.
       *
       * Off, `req.ip` behind a proxy is the proxy's own address. That is
       * blunt but safe: anonymous callers share one bucket, and signed-in ones
       * are tracked by session instead (see UserThrottlerGuard), so the case
       * that used to break — every user in a hospital sharing one limit — does
       * not depend on this setting being right.
       *
       * `TRUST_PROXY=1` trusts the immediate peer; a number trusts that many
       * hops; a CIDR or comma-separated list trusts those addresses.
       */
      trustProxy: parseTrustProxy(process.env.TRUST_PROXY),
    }),
    {
      // Nest's own output — route mapping, dependency errors, shutdown — goes
      // through the same Pino pipe as everything else. Without this a
      // deployment produces two log formats on one file descriptor and no
      // collector parses both.
      logger: new AppLoggerService(),
    },
  );



  // Global prefix for every route, the Electric shape proxy included. It used
  // to be excluded so it sat at /v1/shape, which put it outside the front end's
  // /api forwarder — the browser could only reach it cross-origin, without the
  // session cookie the proxy needs to know which roles to scope a shape to.
  // Under the prefix it is same-origin and credentialed like every other call.
  app.setGlobalPrefix('api');

  const port = process.env.PORT || {{config.port}};
  // Enable CORS BEFORE raw Fastify routes so all routes get CORS headers
  const corsOrigin = process.env.CORS_ORIGIN || 'http://localhost:{{config.frontendPort}}';
  const allowedOrigins = [...new Set([
    ...corsOrigin.split(','),
    'http://localhost:{{config.frontendPort}}',
    'http://localhost:{{config.port}}',
    'http://localhost:3000',
    'http://localhost:5173',
  ])];
  app.enableCors({
    origin: allowedOrigins,
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'If-Match', 'If-None-Match'],
    exposedHeaders: ['ETag', 'X-Total-Count'],
    credentials: true,
  });

  // Mount better-auth HTTP handler at /api/auth/*
  const fastifyInstance = app.getHttpAdapter().getInstance();

  // Registered on Fastify rather than as a Nest interceptor: interceptors run
  // after guards, so an interceptor never sees a request the auth guard
  // rejected — which silently excluded every 401 and 403 — nor the better-auth
  // routes mounted below, which sit outside Nest entirely.
  installHttpLogging(fastifyInstance);

  const auth = getAuth();

  // Patch credentials header: @fastify/cors v9 with function-based origin does not reliably
  // emit Access-Control-Allow-Credentials: true. This onRequest hook fires after the CORS
  // plugin's own onRequest hook (since we add it after app.enableCors) and overwrites the header.
  fastifyInstance.addHook('onRequest', async (request, reply) => {
    const origin = request.headers.origin;
    if (origin && allowedOrigins.includes(origin)) {
      reply.header('Access-Control-Allow-Credentials', 'true');
    }
  });

  fastifyInstance.all('/api/auth/*', async (request, reply) => {
    // Let @fastify/cors handle OPTIONS preflight — forwarding to better-auth strips credentials header
    if (request.method === 'OPTIONS') {
      reply.status(204).send();
      return;
    }

    // No self-service accounts: an administrator creates them from the user
    // management screen. The block belongs here, on the public HTTP surface,
    // rather than on better-auth's `disableSignUp` — that flag also disables
    // `auth.api.signUpEmail`, which is how the admin endpoint writes the
    // credential, so setting it leaves no way to create anyone at all.
    /*
     * Matched on the parsed pathname, not on a substring of the raw URL.
     *
     * `request.url.includes('/sign-up')` is a substring test over path AND
     * query string, which is wrong in both directions: a perfectly ordinary
     * request carrying `?redirect=/sign-up` was blocked, and anything that
     * reaches better-auth's route without that exact literal in the raw URL was
     * not. A denylist over an unparsed string is the weakest form this check
     * could take, and it guards account creation.
     */
    const authPath = new URL(request.url, `http://localhost:${port}`).pathname;
    if (authPath === '/api/auth/sign-up' || authPath.startsWith('/api/auth/sign-up/')) {
      reply.status(403).send({
        statusCode: 403,
        error: 'Forbidden',
        message: 'Accounts are created by an administrator, not by signing up.',
      });
      return;
    }
    try {
      const url = new URL(request.url, `http://localhost:${port}`);
      const headers = new Headers();
      for (const [key, value] of Object.entries(request.headers)) {
        if (value) {
          headers.set(key, Array.isArray(value) ? value.join(', ') : value);
        }
      }

      const init: RequestInit = { method: request.method, headers };
      if (request.body && !['GET', 'HEAD'].includes(request.method)) {
        init.body = typeof request.body === 'string'
          ? request.body
          : JSON.stringify(request.body);
      }

      const webResponse = await auth.handler(new Request(url.toString(), init));

      // Auth is mounted straight on Fastify, so Nest's audit interceptor never
      // sees it. Sign-in, sign-out and sign-up are the events an audit trail
      // exists for, so they are recorded here instead — including the failures,
      // which is where a break-in attempt shows up.
      void recordAuthEvent(app, request, url.pathname, webResponse.status);

      reply.status(webResponse.status);
      webResponse.headers.forEach((value, key) => {
        if (!['transfer-encoding', 'content-encoding'].includes(key.toLowerCase())) {
          reply.header(key, value);
        }
      });

      reply.send(await webResponse.text());
    } catch (error) {
      log.event('http.request.failed', {
        method: request.method,
        path: '/api/auth/*',
        status: 500,
        durationMs: null,
        requestId: request.headers['x-request-id'] ?? null,
        err: error,
      });
      reply.status(500).send({ error: 'Authentication service error' });
    }
  });

  // Global validation pipe for fallback validation
  // Primary validation approach: Zod schemas in sys, rules, and other structured modules
  // This pipe handles remaining class-validator decorators and dynamic entity validation.
  // Note: forbidNonWhitelisted is disabled to support dynamic business entity endpoints.
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: false,
      transform: true,
      transformOptions: {
        enableImplicitConversion: true,
      },
    }),
  );

  // Start server
  const host = process.env.HOST || '0.0.0.0';

  await app.listen(port, host);

  log.event('app.started', {
    url: await app.getUrl(),
    port,
    env: process.env.NODE_ENV || 'development',
  });

  // Ensure the default admin user exists with the correct role
  await ensureAdminUser(logger);
}

bootstrap().catch((err) => {
  // The logger is the first thing bootstrap installs, so by any realistic
  // failure it exists. `console.error` stays as the last resort for a failure
  // early enough that it does not.
  try {
    getLogger('app').event('app.uncaught', { err });
  } catch {
    console.error('Failed to start application:', err);
  }
  process.exit(1);
});

