      );

      expect(mutation.error).toContain('ECONNREFUSED');
    } finally {
      globalThis.fetch = originalFetch;
    }
  });
});

// ── 6. Decision ──────────────────────────────────────────────────────────────

/**
 * A decision table authored inside a step. The executor wraps this in the
 * input → table → output graph, so only the table itself is stored.
 *
 * Every row sets every output column: zen-engine silently discards a row that
 * leaves one unset, which makes the whole table stop matching.
 */
const SEVERITY_TABLE = {
  hitPolicy: 'collect',
  inputs: [{ id: 'i1', name: 'Severity', field: 'severity' }],
  outputs: [
    { id: 'o1', name: 'Priority', field: 'priority' },
    { id: 'o2', name: 'Owner', field: 'owner' },
  ],
  rules: [
    { _id: 'critical', i1: '"critical"', o1: '1', o2: "'QA'" },
    { _id: 'major', i1: '"major"', o1: '3', o2: "'Supervisor'" },
  ],
};

function attr(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/** Decision step, then an UpdateEntity step reading what the decision published. */
function decisionThenUpdateBpmn(
  decisionProps: Record<string, string>,
  updateProps: Record<string, string>,
): string {
  const render = (props: Record<string, string>) =>
    Object.entries(props)
      .map(([k, v]) => `<appwithai:property name="${k}" value="${attr(v)}"/>`)
      .join('\n        ');
  return `<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:appwithai="http://appwithai/schema">
  <bpmn:process id="p" isExecutable="true">
    <bpmn:startEvent id="start"/>
    <bpmn:serviceTask id="decide">
      <bpmn:extensionElements><appwithai:properties>
        ${render(decisionProps)}
      </appwithai:properties></bpmn:extensionElements>
    </bpmn:serviceTask>
    <bpmn:serviceTask id="apply">
      <bpmn:extensionElements><appwithai:properties>
        ${render(updateProps)}
      </appwithai:properties></bpmn:extensionElements>
    </bpmn:serviceTask>
    <bpmn:sequenceFlow id="f0" sourceRef="start"  targetRef="decide"/>
    <bpmn:sequenceFlow id="f1" sourceRef="decide" targetRef="apply"/>
  </bpmn:process>
</bpmn:definitions>`;
}

describe('WorkflowService — Decision', () => {
  it('publishes the outputs of a matched row as variables a later step reads', async () => {
    const { chain, updates } = createMockDb();
    const svc = new WorkflowService(chain, new RulesEngine());

    const mutations = await runBpmn(
      svc,
      decisionThenUpdateBpmn(
        { nodeType: 'Decision', decisionTable: JSON.stringify(SEVERITY_TABLE) },
        { nodeType: 'UpdateEntity', field: 'assigned_to', source: 'owner' },
      ),
      'bus_deviation_report',
      { id: 'dev-1', severity: 'critical' },
    );

    expect(mutations[0]).toMatchObject({
      nodeType: 'Decision',
      matchedRows: 1,
      published: { priority: 1, owner: 'QA' },
    });
    // The point of the step: the next one wrote a value it could not have known.
    expect(updates).toHaveLength(1);
    expect(updates[0].fields).toMatchObject({ assigned_to: 'QA' });
  });

  it('publishes nothing when no row matches, and does not fail the run', async () => {
    const { chain, updates } = createMockDb();
    const svc = new WorkflowService(chain, new RulesEngine());

    const mutations = await runBpmn(
      svc,
      decisionThenUpdateBpmn(
        { nodeType: 'Decision', decisionTable: JSON.stringify(SEVERITY_TABLE) },
        { nodeType: 'UpdateEntity', field: 'assigned_to', source: 'owner' },
      ),
      'bus_deviation_report',
      { id: 'dev-1', severity: 'minor' },
    );

    expect(mutations[0]).toMatchObject({ nodeType: 'Decision', matchedRows: 0 });
    // Nothing to write, so the update skips rather than writing undefined.
    expect(updates).toHaveLength(0);
  });

  it('honours the publish allow-list', async () => {
    const { chain } = createMockDb();
    const svc = new WorkflowService(chain, new RulesEngine());

    const [decision] = await runBpmn(
      svc,
      decisionThenUpdateBpmn(
        {
          nodeType: 'Decision',
          decisionTable: JSON.stringify(SEVERITY_TABLE),
          publish: 'owner',
        },
        { nodeType: 'UpdateEntity', field: 'assigned_to', source: 'owner' },
      ),
      'bus_deviation_report',
      { id: 'dev-1', severity: 'major' },
    );

    expect((decision as any).published).toEqual({ owner: 'Supervisor' });
  });

  it('skips a step configured with neither a table nor a rule', async () => {
    const { chain } = createMockDb();
    const svc = new WorkflowService(chain, new RulesEngine());

    const [mutation] = await runBpmn(
      svc,
      updateTaskBpmn({ nodeType: 'Decision' }),
      'bus_deviation_report',
      { id: 'dev-1' },
    );

    expect(mutation.skipped).toContain('no decision table');
  });

  it('reports malformed JSON instead of throwing', async () => {
    const { chain } = createMockDb();
    const svc = new WorkflowService(chain, new RulesEngine());

    const [mutation] = await runBpmn(
      svc,
      decisionThenUpdateBpmn(
        { nodeType: 'Decision', decisionTable: '{ not json' },
        { nodeType: 'UpdateEntity', field: 'assigned_to', source: 'owner' },
      ),
      'bus_deviation_report',
      { id: 'dev-1' },
    );

    expect(mutation.skipped).toContain('not valid JSON');
  });
});

