import { syncEntityTask, type SyncTaskPayload } from '../../src/trigger/sync.task';

describe('syncEntityTask', () => {
  it('is defined and exported', () => {
    expect(syncEntityTask).toBeDefined();
  });

  it('has an id property', () => {
