/**
 * Trigger-Workflow Integration Tests
 * Generated: {{generatedAt}}
 * Project: {{project.name}}
 *
 * Verifies the full chain: a business rule with action type "trigger-workflow"
 * causes the RulesService to invoke WorkflowService.triggerByWorkflowName,
 * which executes BPMN service tasks (UpdateEntity) and records the run.
 *
 * Tests are layered:
 *   1. RulesEngine   — evaluateRulesWithJDM returns trigger-workflow actions
 *   2. RulesService  — executeMatchedActions dispatches to WorkflowService
 *   3. WorkflowService — triggerByWorkflowName executes BPMN and updates entities
 */

import { describe, it, expect, beforeAll, afterAll } from 'bun:test';
import { RulesEngine } from '../src/modules/rules/rules-engine.service';
import { RulesService } from '../src/modules/rules/rules.service';
import { WorkflowService } from '../src/modules/workflow/workflow.service';

// ── JDM fixtures ─────────────────────────────────────────────────────────────

// A JDM decision table that emits a trigger-workflow action when appointment
// current_state transitions to 'completed'.
const TRIGGER_WORKFLOW_JDM = JSON.stringify({
  nodes: [
    { id: 'input', type: 'inputNode', name: 'Input', position: { x: 0, y: 0 } },
    {
      id: 'appointment-trigger-rule',
      type: 'decisionTableNode',
      name: 'Appointment Workflow Trigger',
      position: { x: 300, y: 0 },
      content: {
        hitPolicy: 'collect',
        inputs: [
          { id: 'i1', name: 'Current State', field: 'current_state' },
        ],
        outputs: [
          { id: 'o1', name: 'Action',        field: 'action' },
          { id: 'o2', name: 'Message',       field: 'message' },
          { id: 'o3', name: 'Rule ID',       field: 'ruleId' },
          { id: 'o4', name: 'Workflow Name', field: 'workflowName' },
        ],
        rules: [
          {
            _id: 'appointment-completed-trigger',
            i1:  '"completed"',
            o1:  "'trigger-workflow'",
            o2:  "'Appointment completed — trigger billing workflow'",
            o3:  "'appointment-completed-trigger'",
            o4:  "'GenerateClaimWorkflow'",
          },
        ],
      },
    },
    { id: 'output', type: 'outputNode', name: 'Output', position: { x: 600, y: 0 } },
  ],
  edges: [
    { id: 'e1', sourceId: 'input', targetId: 'appointment-trigger-rule' },
    { id: 'e2', sourceId: 'appointment-trigger-rule', targetId: 'output' },
  ],
});

// A JDM that is intentionally silent (no matching rows) for non-triggering states.
const SILENT_JDM = JSON.stringify({
  nodes: [
    { id: 'input', type: 'inputNode', name: 'Input', position: { x: 0, y: 0 } },
    {
      id: 'silent-rule',
      type: 'decisionTableNode',
      name: 'Silent Rule',
      position: { x: 300, y: 0 },
      content: {
        hitPolicy: 'collect',
        inputs: [{ id: 'i1', name: 'Current State', field: 'current_state' }],
        outputs: [
          { id: 'o1', name: 'Action',  field: 'action' },
          { id: 'o2', name: 'Message', field: 'message' },
          { id: 'o3', name: 'Rule ID', field: 'ruleId' },
        ],
        rules: [
          {
            _id: 'never-matches',
            i1: '"__never__"',
            o1: "'prevent'",
            o2: "'Should never fire'",
            o3: "'never-matches'",
          },
        ],
      },
    },
    { id: 'output', type: 'outputNode', name: 'Output', position: { x: 600, y: 0 } },
  ],
  edges: [
    { id: 'e1', sourceId: 'input', targetId: 'silent-rule' },
    { id: 'e2', sourceId: 'silent-rule', targetId: 'output' },
  ],
});

// BPMN XML with UpdateEntity service tasks for workflow execution testing.
const UPDATE_ENTITY_BPMN = `<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL"
                  xmlns:appwithai="http://appwithai.com/extensions">
  <bpmn:process id="GenerateClaimWorkflow" isExecutable="true">
    <bpmn:startEvent id="start"/>
    <bpmn:serviceTask id="updateDocStatus" name="Update doc_status">
      <bpmn:extensionElements>
        <appwithai:property name="nodeType" value="UpdateEntity"/>
        <appwithai:property name="entity"   value="bus_appointment"/>
        <appwithai:property name="field"    value="doc_status"/>
        <appwithai:property name="value"    value="processing"/>
      </bpmn:extensionElements>
    </bpmn:serviceTask>
    <bpmn:serviceTask id="updateWorkflowStatus" name="Update workflow_status">
      <bpmn:extensionElements>
        <appwithai:property name="nodeType" value="UpdateEntity"/>
        <appwithai:property name="entity"   value="bus_appointment"/>
        <appwithai:property name="field"    value="workflow_status"/>
        <appwithai:property name="value"    value="triggered"/>
      </bpmn:extensionElements>
    </bpmn:serviceTask>
    <bpmn:sequenceFlow id="f1" sourceRef="start"            targetRef="updateDocStatus"/>
    <bpmn:sequenceFlow id="f2" sourceRef="updateDocStatus"  targetRef="updateWorkflowStatus"/>
  </bpmn:process>
</bpmn:definitions>`;

// ── Mock helpers ──────────────────────────────────────────────────────────────

/**
 * Builds a Kysely-compatible fluent chain mock.  Each selectFrom / insertInto /
 * updateTable call records the table name; execute() / executeTakeFirst() look
 * up the registered response for the most-recently-set context.
 */
function createMockDb(responses: {
  select?: Record<string, any[]>;
  selectOne?: Record<string, any>;
  insert?: Record<string, any>;
  update?: Record<string, void>;
}) {
  const updates: Array<{ table: string; fields: Record<string, unknown>; whereId: string | null }> = [];
  const inserts: Array<{ table: string; values: Record<string, unknown> }> = [];

  let currentOp   = 'select';
  let currentTable = '';
  let pendingSet: Record<string, unknown> = {};
  let pendingValues: Record<string, unknown> = {};

  const chain: any = {};

  chain.selectFrom = (table: string) => { currentOp = 'select'; currentTable = table; return chain; };
  chain.insertInto = (table: string) => { currentOp = 'insert'; currentTable = table; return chain; };
  chain.updateTable = (table: string) => { currentOp = 'update'; currentTable = table; return chain; };
  chain.deleteFrom  = (table: string) => { currentOp = 'delete'; currentTable = table; return chain; };

  // fluent no-op methods
  for (const m of ['selectAll', 'where', 'orderBy', 'limit', 'select', 'returningAll']) {
    chain[m] = (..._args: any[]) => chain;
  }

  chain.set = (data: Record<string, unknown>) => { pendingSet = data; return chain; };
  chain.values = (data: Record<string, unknown>) => { pendingValues = data; return chain; };

  chain.execute = () => {
    if (currentOp === 'update') {
      updates.push({ table: currentTable, fields: pendingSet, whereId: null });
      pendingSet = {};
    }
    if (currentOp === 'insert') {
      inserts.push({ table: currentTable, values: pendingValues });
      pendingValues = {};
    }
    const result = responses.select?.[currentTable] ?? [];
    return Promise.resolve(result);
  };

  chain.executeTakeFirst = () => {
    if (currentOp === 'insert') {
      const row = responses.insert?.[currentTable];
      inserts.push({ table: currentTable, values: pendingValues });
      pendingValues = {};
      return Promise.resolve(row);
    }
    const result = responses.selectOne?.[currentTable] ?? responses.select?.[currentTable]?.[0];
    return Promise.resolve(result ?? undefined);
  };

  return { chain, updates, inserts };
}

// ── Layer 1: RulesEngine ─────────────────────────────────────────────────────

describe('RulesEngine — trigger-workflow action', () => {
  let engine: RulesEngine;

  beforeAll(() => { engine = new RulesEngine(); });
  afterAll(() => { engine.onModuleDestroy(); });

  it('returns a trigger-workflow action when the appointment is completed', async () => {
    const data = { current_state: 'completed' };
    const results = await engine.evaluateRulesWithJDM('bus_appointment', TRIGGER_WORKFLOW_JDM, data, 'update');

    expect(results.length).toBe(1);
    const [result] = results;
    expect(result.matched).toBe(true);
    expect(result.actions[0].type).toBe('trigger-workflow');
    expect(result.actions[0].config.workflowName).toBe('GenerateClaimWorkflow');
    expect(result.actions[0].config.message).toContain('billing workflow');
  });

  it('returns no results when appointment state does not match the trigger condition', async () => {
    const data = { current_state: 'scheduled' };
    const results = await engine.evaluateRulesWithJDM('bus_appointment', TRIGGER_WORKFLOW_JDM, data, 'update');

    expect(results.length).toBe(0);
  });

  it('returns no results for a null current_state (non-triggering)', async () => {
    const data = { current_state: null };
    const results = await engine.evaluateRulesWithJDM('bus_appointment', TRIGGER_WORKFLOW_JDM, data, 'update');

    expect(results.length).toBe(0);
  });

  it('does NOT fire trigger-workflow for an unrelated silent JDM', async () => {
    const data = { current_state: 'completed' };
    const results = await engine.evaluateRulesWithJDM('bus_appointment', SILENT_JDM, data, 'update');

    expect(results.length).toBe(0);
  });

  it('carries workflowName in the action config — accessible downstream', async () => {
    const data = { current_state: 'completed' };
    const [result] = await engine.evaluateRulesWithJDM('bus_appointment', TRIGGER_WORKFLOW_JDM, data, 'update');

    const wfAction = result.actions.find((a) => a.type === 'trigger-workflow');
    expect(wfAction).toBeDefined();
    expect(typeof wfAction!.config.workflowName).toBe('string');
    expect((wfAction!.config.workflowName as string).length).toBeGreaterThan(0);
  });
});

// ── Layer 2: RulesService.executeMatchedActions ───────────────────────────────

describe('RulesService — executeMatchedActions dispatches trigger-workflow', () => {
  let engine: RulesEngine;

  const RULE_ROW = {
    id: 'rule-1',
    entity_name: 'bus_appointment',
    rule_name: 'appointment_completed_rule',
    operation: 'ALL',
    jdm_content: TRIGGER_WORKFLOW_JDM,
    is_active: true,
    version: 1,
    created_by: 'test',
    created_at: new Date(),
    updated_at: new Date(),
  };

  beforeAll(() => { engine = new RulesEngine(); });
  afterAll(() => { engine.onModuleDestroy(); });

  it('calls workflowService.triggerByWorkflowName with the correct workflow name', async () => {
    const { chain: mockDb } = createMockDb({
      select: { sys_rule_definitions: [RULE_ROW] },
    });

    const calls: Array<{ name: string; entity: string; id: string }> = [];
    const mockWorkflowService = {
      triggerByWorkflowName: async (name: string, entity: string, id: string) => {
        calls.push({ name, entity, id });
      },
    } as unknown as WorkflowService;

    const svc = new RulesService(engine, mockDb, mockWorkflowService);

    await svc.executeMatchedActions(
      'bus_appointment',
      'appt-uuid-123',
      { current_state: 'completed', id: 'appt-uuid-123' },
      'update',
    );

    expect(calls.length).toBe(1);
    expect(calls[0].name).toBe('GenerateClaimWorkflow');
    expect(calls[0].entity).toBe('bus_appointment');
    expect(calls[0].id).toBe('appt-uuid-123');
  });

  it('does NOT call triggerByWorkflowName when the rule does not match', async () => {
    const { chain: mockDb } = createMockDb({
      select: { sys_rule_definitions: [RULE_ROW] },
    });

    const calls: string[] = [];
    const mockWorkflowService = {
      triggerByWorkflowName: async (name: string) => { calls.push(name); },
    } as unknown as WorkflowService;

    const svc = new RulesService(engine, mockDb, mockWorkflowService);

    // state = 'scheduled' doesn't match the trigger condition
    await svc.executeMatchedActions(
      'bus_appointment',
      'appt-uuid-456',
      { current_state: 'scheduled', id: 'appt-uuid-456' },
      'update',
    );

    expect(calls.length).toBe(0);
  });

  it('does NOT call triggerByWorkflowName when there are no active rules', async () => {
    const { chain: mockDb } = createMockDb({
      select: { sys_rule_definitions: [] },
    });

    const calls: string[] = [];
    const mockWorkflowService = {
      triggerByWorkflowName: async (name: string) => { calls.push(name); },
    } as unknown as WorkflowService;

    const svc = new RulesService(engine, mockDb, mockWorkflowService);

    await svc.executeMatchedActions(
      'bus_appointment',
      'appt-uuid-789',
      { current_state: 'completed', id: 'appt-uuid-789' },
      'update',
    );

    expect(calls.length).toBe(0);
  });

  it('skips trigger-workflow when workflowName is missing from rule action', async () => {
    // JDM that returns trigger-workflow but without a workflowName output
    const JDM_NO_WF_NAME = JSON.stringify({
      nodes: [
        { id: 'input',  type: 'inputNode',  name: 'Input',  position: { x: 0, y: 0 } },
        {
          id: 'rule-node',
          type: 'decisionTableNode',
          name: 'Trigger Without Name',
          position: { x: 300, y: 0 },
          content: {
            hitPolicy: 'collect',
            inputs:  [{ id: 'i1', name: 'State', field: 'current_state' }],
            outputs: [
              { id: 'o1', name: 'Action',  field: 'action' },
              { id: 'o2', name: 'Message', field: 'message' },
              { id: 'o3', name: 'Rule ID', field: 'ruleId' },
            ],
            rules: [{
              _id: 'no-wf-name',
              i1:  '"completed"',
              o1:  "'trigger-workflow'",
              o2:  "'Missing workflowName'",
              o3:  "'no-wf-name'",
            }],
          },
        },
        { id: 'output', type: 'outputNode', name: 'Output', position: { x: 600, y: 0 } },
      ],
      edges: [
        { id: 'e1', sourceId: 'input', targetId: 'rule-node' },
        { id: 'e2', sourceId: 'rule-node', targetId: 'output' },
      ],
    });

    const RULE_NO_WF = { ...RULE_ROW, jdm_content: JDM_NO_WF_NAME };
    const { chain: mockDb } = createMockDb({
      select: { sys_rule_definitions: [RULE_NO_WF] },
    });

    const calls: string[] = [];
    const mockWorkflowService = {
      triggerByWorkflowName: async (name: string) => { calls.push(name); },
    } as unknown as WorkflowService;

    const svc = new RulesService(engine, mockDb, mockWorkflowService);

    // Should not throw, should just warn and skip
    await svc.executeMatchedActions(
      'bus_appointment',
      'appt-uuid-999',
      { current_state: 'completed', id: 'appt-uuid-999' },
      'update',
    );

    expect(calls.length).toBe(0);
  });

  it('is resilient — does not throw when evaluate() fails internally', async () => {
    const badDb = {
      selectFrom: () => { throw new Error('DB connection lost'); },
    } as any;

    const mockWorkflowService = {
      triggerByWorkflowName: async () => {},
    } as unknown as WorkflowService;

    const svc = new RulesService(engine, badDb, mockWorkflowService);

    // Should not throw; executeMatchedActions swallows and logs errors
    await expect(
      svc.executeMatchedActions('bus_appointment', 'appt-1', {}, 'update'),
    ).resolves.toBeUndefined();
  });
});

// ── Layer 3: WorkflowService.triggerByWorkflowName ────────────────────────────

describe('WorkflowService — triggerByWorkflowName executes BPMN and updates entities', () => {
  const ENTITY_ID = 'appt-uuid-abc';
  const WORKFLOW_DEF = {
    id: 'wf-def-1',
    name: 'GenerateClaimWorkflow',
    entity_name: 'bus_appointment',
    operation: 'ALL',
    bpmn_xml: UPDATE_ENTITY_BPMN,
    is_active: true,
    created_by: 'seed',
    created_at: new Date(),
  };
  const RUN_ROW = { id: 'run-uuid-1', status: 'draft' };

  it('executes UpdateEntity BPMN tasks and records a success run', async () => {
    const { chain: mockDb, updates, inserts } = createMockDb({
      selectOne: { sys_workflow_definitions: WORKFLOW_DEF },
      insert:    { sys_workflow_runs: RUN_ROW },
    });

    const wfSvc = new WorkflowService(mockDb, new RulesEngine());

    await wfSvc.triggerByWorkflowName(
      'GenerateClaimWorkflow',
      'bus_appointment',
      ENTITY_ID,
      'update',
      { id: ENTITY_ID, current_state: 'completed' },
    );

    // Verify a workflow run was inserted
    const runInsert = inserts.find((i) => i.table === 'sys_workflow_runs');
    expect(runInsert).toBeDefined();
    expect(runInsert!.values.entity_name).toBe('bus_appointment');
    expect(runInsert!.values.entity_id).toBe(ENTITY_ID);
    expect(runInsert!.values.operation).toBe('UPDATE');
    expect(runInsert!.values.status).toBe('draft');
    expect(runInsert!.values.created_by).toBe('rules-engine');

    // Verify UpdateEntity tasks ran (2 service tasks in BPMN)
    const entityUpdates = updates.filter((u) => u.table === 'bus_appointment');
    expect(entityUpdates.length).toBe(2);

    const docStatusUpdate = entityUpdates.find(
      (u) => (u.fields as any).doc_status !== undefined,
    );
    expect(docStatusUpdate).toBeDefined();
    expect((docStatusUpdate!.fields as any).doc_status).toBe('processing');

    const wfStatusUpdate = entityUpdates.find(
      (u) => (u.fields as any).workflow_status !== undefined,
    );
    expect(wfStatusUpdate).toBeDefined();
    expect((wfStatusUpdate!.fields as any).workflow_status).toBe('triggered');

    // Verify the run was updated to success
    const runUpdate = updates.find((u) => u.table === 'sys_workflow_runs');
    expect(runUpdate).toBeDefined();
    expect((runUpdate!.fields as any).status).toBe('success');
  });

  it('records an error run when the workflow definition is not found', async () => {
    const { chain: mockDb, updates } = createMockDb({
      selectOne: { sys_workflow_definitions: undefined },
    });

    const wfSvc = new WorkflowService(mockDb, new RulesEngine());

    // Should not throw — logs a warning and returns
    await expect(
      wfSvc.triggerByWorkflowName(
        'NonExistentWorkflow',
        'bus_appointment',
        ENTITY_ID,
        'update',
        { id: ENTITY_ID },
      ),
    ).resolves.toBeUndefined();

    // No run should be inserted since the definition was not found
    const runUpdate = updates.find((u) => u.table === 'sys_workflow_runs' && (u.fields as any).status === 'error');
    expect(runUpdate).toBeUndefined();
  });

  it('marks the run as error when executeBpmn throws', async () => {
    const BPMN_WITH_UNKNOWN_TASK = `<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL"
                  xmlns:appwithai="http://appwithai.com/extensions">
  <bpmn:process id="TestWf" isExecutable="true">
    <bpmn:serviceTask id="t1" name="Update Missing Entity">
      <bpmn:extensionElements>
        <appwithai:property name="nodeType" value="UpdateEntity"/>
        <appwithai:property name="entity"   value="bus_appointment"/>
        <appwithai:property name="field"    value="doc_status"/>
        <appwithai:property name="value"    value="error-state"/>
      </bpmn:extensionElements>
    </bpmn:serviceTask>
  </bpmn:process>
</bpmn:definitions>`;

    const BAD_DEF = { ...WORKFLOW_DEF, bpmn_xml: BPMN_WITH_UNKNOWN_TASK };

    const { chain: mockDb, updates } = createMockDb({
      selectOne: { sys_workflow_definitions: BAD_DEF },
      insert: { sys_workflow_runs: RUN_ROW },
    });

    const wfSvc = new WorkflowService(mockDb, new RulesEngine());

    await wfSvc.triggerByWorkflowName(
      'GenerateClaimWorkflow',
      'bus_appointment',
      ENTITY_ID,
      'update',
      { id: ENTITY_ID, current_state: 'completed' },
    );

    // doc_status update should still be attempted (entity has id in payload)
    const docUpdate = updates.find(
      (u) => u.table === 'bus_appointment' && (u.fields as any).doc_status === 'error-state',
    );
    expect(docUpdate).toBeDefined();
  });

  it('is idempotent — multiple calls with the same args each create separate run records', async () => {
    let insertCount = 0;
    const { chain: mockDb, inserts } = createMockDb({
      selectOne: { sys_workflow_definitions: WORKFLOW_DEF },
      insert: { sys_workflow_runs: { id: 'run-uuid-seq', status: 'draft' } },
    });

    // Override insert to count
    const origInsertInto = mockDb.insertInto.bind(mockDb);
    mockDb.insertInto = (table: string) => {
      if (table === 'sys_workflow_runs') insertCount++;
      return origInsertInto(table);
    };

    const wfSvc = new WorkflowService(mockDb, new RulesEngine());

    await wfSvc.triggerByWorkflowName('GenerateClaimWorkflow', 'bus_appointment', ENTITY_ID, 'update', { id: ENTITY_ID });
    await wfSvc.triggerByWorkflowName('GenerateClaimWorkflow', 'bus_appointment', ENTITY_ID, 'update', { id: ENTITY_ID });

    // Two separate run records inserted
    const runInserts = inserts.filter((i) => i.table === 'sys_workflow_runs');
    expect(runInserts.length).toBeGreaterThanOrEqual(2);
  });
});

// ── Layer 4: End-to-end chain ─────────────────────────────────────────────────

describe('End-to-end: rule fires → workflow runs → entity updated', () => {
  let engine: RulesEngine;

  const RULE_ROW = {
    id: 'rule-e2e',
    entity_name: 'bus_appointment',
    rule_name: 'appointment_completed_e2e',
    operation: 'ALL',
    jdm_content: TRIGGER_WORKFLOW_JDM,
    is_active: true,
  };
  const WORKFLOW_DEF = {
    id: 'wf-e2e',
    name: 'GenerateClaimWorkflow',
    entity_name: 'bus_appointment',
    operation: 'ALL',
    bpmn_xml: UPDATE_ENTITY_BPMN,
    is_active: true,
  };
  const RUN_ROW = { id: 'run-e2e-1', status: 'draft' };

  beforeAll(() => { engine = new RulesEngine(); });
  afterAll(() => { engine.onModuleDestroy(); });

  it('appointment state change triggers workflow that updates doc_status and workflow_status', async () => {
    const { chain: rulesDb } = createMockDb({
      select: { sys_rule_definitions: [RULE_ROW] },
    });

    // Shared update tracker for the workflow service
    const updatesApplied: Array<{ table: string; fields: Record<string, unknown> }> = [];
    const wfInserts: any[] = [];

    // Workflow service needs its own db (different queries)
    let wfCurrentOp = 'select';
    let wfCurrentTable = '';
    let wfPendingSet: Record<string, unknown> = {};
    let wfPendingValues: Record<string, unknown> = {};

    const wfMockDb: any = {};
    wfMockDb.selectFrom = (t: string) => { wfCurrentOp = 'select'; wfCurrentTable = t; return wfMockDb; };
    wfMockDb.insertInto = (t: string) => { wfCurrentOp = 'insert'; wfCurrentTable = t; return wfMockDb; };
    wfMockDb.updateTable = (t: string) => { wfCurrentOp = 'update'; wfCurrentTable = t; return wfMockDb; };
    for (const m of ['selectAll', 'where', 'orderBy', 'limit', 'returningAll']) {
      wfMockDb[m] = (..._a: any[]) => wfMockDb;
    }
    wfMockDb.set = (d: any) => { wfPendingSet = d; return wfMockDb; };
    wfMockDb.values = (d: any) => { wfPendingValues = d; return wfMockDb; };
    wfMockDb.execute = () => {
      if (wfCurrentOp === 'update') {
        updatesApplied.push({ table: wfCurrentTable, fields: { ...wfPendingSet } });
        wfPendingSet = {};
      }
      return Promise.resolve([]);
    };
    wfMockDb.executeTakeFirst = () => {
      if (wfCurrentOp === 'insert') {
        wfInserts.push({ table: wfCurrentTable, values: { ...wfPendingValues } });
        wfPendingValues = {};
        if (wfCurrentTable === 'sys_workflow_runs') return Promise.resolve(RUN_ROW);
      }
      if (wfCurrentOp === 'select') {
        if (wfCurrentTable === 'sys_workflow_definitions') return Promise.resolve(WORKFLOW_DEF);
      }
      return Promise.resolve(undefined);
    };

    const wfSvc = new WorkflowService(wfMockDb, new RulesEngine());
    const rulesSvc = new RulesService(engine, rulesDb, wfSvc);

    // Simulate an appointment being updated to 'completed'
    await rulesSvc.executeMatchedActions(
      'bus_appointment',
      'appt-e2e-id',
      { current_state: 'completed', id: 'appt-e2e-id' },
      'update',
    );

    // Workflow run was created
    expect(wfInserts.some((i) => i.table === 'sys_workflow_runs')).toBe(true);

    // UpdateEntity tasks updated bus_appointment fields
    const apptUpdates = updatesApplied.filter((u) => u.table === 'bus_appointment');
    expect(apptUpdates.length).toBe(2);

    const docUpdate = apptUpdates.find((u) => (u.fields as any).doc_status !== undefined);
    expect(docUpdate).toBeDefined();
    expect((docUpdate!.fields as any).doc_status).toBe('processing');

    const wfUpdate = apptUpdates.find((u) => (u.fields as any).workflow_status !== undefined);
    expect(wfUpdate).toBeDefined();
    expect((wfUpdate!.fields as any).workflow_status).toBe('triggered');

    // Run was marked success
    const successUpdate = updatesApplied.find(
      (u) => u.table === 'sys_workflow_runs' && (u.fields as any).status === 'success',
    );
    expect(successUpdate).toBeDefined();
  });

  it('non-triggering state change produces no workflow run', async () => {
    const { chain: rulesDb } = createMockDb({
      select: { sys_rule_definitions: [RULE_ROW] },
    });

    const wfCalls: string[] = [];
    const mockWfSvc = {
      triggerByWorkflowName: async (name: string) => { wfCalls.push(name); },
    } as unknown as WorkflowService;

    const rulesSvc = new RulesService(engine, rulesDb, mockWfSvc);

    await rulesSvc.executeMatchedActions(
      'bus_appointment',
      'appt-no-trigger',
      { current_state: 'scheduled', id: 'appt-no-trigger' },
      'update',
    );

    expect(wfCalls.length).toBe(0);
  });
});

// ── JDM validation: the silent-drop footgun ──────────────────────────────────

describe('RulesService.validateJDM — incomplete decision-table rows', () => {
  let engine: RulesEngine;

  beforeAll(() => { engine = new RulesEngine(); });
  afterAll(() => { engine.onModuleDestroy(); });

  function tableWith(outputs: Array<{ id: string; field: string }>, rows: Array<Record<string, unknown>>) {
    // zen-engine requires a display name on every column.
    const named = outputs.map((o) => ({ ...o, name: o.field }));
    return JSON.stringify({
      nodes: [
        { id: 'input', type: 'inputNode', name: 'Input', position: { x: 0, y: 0 } },
        {
          id: 'table', type: 'decisionTableNode', name: 'Validation', position: { x: 300, y: 0 },
          content: {
            hitPolicy: 'collect',
            inputs: [{ id: 'i0', name: 'Action', field: 'action' }],
            outputs: named,
            rules: rows,
          },
        },
        { id: 'output', type: 'outputNode', name: 'Output', position: { x: 600, y: 0 } },
      ],
      edges: [
        { id: 'e1', sourceId: 'input', targetId: 'table' },
        { id: 'e2', sourceId: 'table', targetId: 'output' },
      ],
    });
  }

  const OUTPUTS = [
    { id: 'o1', field: 'action' },
    { id: 'o2', field: 'message' },
    { id: 'o3', field: 'ruleId' },
    { id: 'o4', field: 'workflowName' },
  ];

  function svc() {
    const { chain } = createMockDb({});
    return new RulesService(engine, chain, {} as unknown as WorkflowService);
  }

  // Regression: adding an output column without backfilling existing rows makes
  // zen-engine discard every row, so evaluate() returns [] with no error — which
  // reads exactly like "no rules configured". Catch it at save time instead.
  it('rejects a row that does not set every declared output column', async () => {
    const jdm = tableWith(OUTPUTS, [
      { _id: 'incomplete-row', i0: 'action == "create"', o1: "'prevent'", o2: "'Boom'", o3: "'incomplete-row'" },
    ]);

    const result = await svc().validateJDM(jdm);

    expect(result.valid).toBe(false);
    expect(result.errors.join(' ')).toContain('incomplete-row');
    expect(result.errors.join(' ')).toContain('o4');
  });

  it('names every missing column, not just the first', async () => {
    const jdm = tableWith(OUTPUTS, [
      { _id: 'bare-row', i0: 'action == "create"', o1: "'prevent'" },
    ]);

    const [error] = (await svc().validateJDM(jdm)).errors;

    expect(error).toContain('o2');
    expect(error).toContain('o3');
    expect(error).toContain('o4');
  });

  it('accepts rows that set every column, including empty strings', async () => {
    const jdm = tableWith(OUTPUTS, [
      { _id: 'complete-row', i0: 'action == "create"', o1: "'prevent'", o2: "'Boom'", o3: "'complete-row'", o4: "''" },
    ]);

    const result = await svc().validateJDM(jdm);

    expect(result.errors).toEqual([]);
    expect(result.valid).toBe(true);
  });

  it('reports the row identifier so the offending row can be found', async () => {
    const jdm = tableWith(OUTPUTS, [
      { _id: 'good', i0: 'action == "create"', o1: "'prevent'", o2: "'a'", o3: "'good'", o4: "''" },
      { _id: 'bad', i0: 'action == "update"', o1: "'prevent'", o2: "'b'", o3: "'bad'" },
    ]);

    const { errors } = await svc().validateJDM(jdm);

    expect(errors).toHaveLength(1);
    expect(errors[0]).toContain('"bad"');
  });
});

