/**
 * Multi-step workflows triggered by a business rule.
 *
 * The chain under test, end to end:
 *
 *   write a record  →  rule fires `trigger-workflow`  →  the workflow runs
 *     step 1  stage a value into a workflow variable
 *     step 2  compute a second variable from the first
 *     step 3  CREATE a row in another entity, capturing its id
 *     step 4  CREATE a second row in that entity, capturing its id
 *     step 5  UPDATE the record that triggered the workflow
 *     step 6  UPDATE the row created in step 3, using both the captured id and
 *             the computed value
 *     step 7  DELETE the row created in step 4, by its captured id
 *
 * That covers what a multi-step workflow has to get right: ordering,
 * create/update/delete against an entity other than the triggering one, and
 * values carried from one step into a later one. A workflow that could not
 * carry a created row's id forward could only ever touch the record it
 * started from.
 *
 * The suite also pins the negative case: a rule-triggered definition must NOT
 * run when its rule does not fire. Definitions used to be auto-run purely on
 * entity + operation, so a workflow gated on a condition ran regardless of it.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it, sleep } from "../harness/testing.ts";
import {
  buildRecord,
  buildWorkflowBpmn,
  createRule,
  createWorkflowDefinition,
  deleteWorkflowDefinition,
  entities,
  foreignKeyFields,
  harness,
  isFailure,
  isStateField,
  isTerminal,
  runsForEntity,
  updateRule,
  type EntityMeta,
  type FieldMeta,
  type WorkflowRun,
  type WorkflowStep,
} from "../harness/index.ts";

const suiteId = `ms${Date.now().toString(36).slice(-5)}`;

/**
 * Writable text columns the workflow can stamp a value into.
 *
 * Wide enough to hold the suite's marker strings — a `varchar(8)` column would
 * truncate them and turn every assertion into a mystery.
 */
/**
 * Columns the generated business rules constrain by *format*, which a marker
 * string cannot satisfy.
 *
 * Generation writes a decision-table row for any column named `email` —
 * `!contains(email, "@")` → prevent, see
 * backend/src/modules/rules/jdm/entity.jdm.json — so stamping `ms1a2b3-source`
 * into it is refused 400 before the workflow chain ever starts. On a model
 * whose first long string column is an email (Instructor, Member, …) that made
 * this suite unrunnable, and the failure pointed at the workflow rather than at
 * the column the suite had chosen.
 */
const FORMAT_CONSTRAINED_COLUMNS = new Set(["email"]);

function stampableFields(entity: EntityMeta): FieldMeta[] {
  return entity.fields.filter(
    (field) =>
      !field.isForeignKey &&
      !field.name.endsWith("_id") &&
      field.name !== "id" &&
      !FORMAT_CONSTRAINED_COLUMNS.has(field.name) &&
      // Only a background workflow writes a state field; a person's write that
      // stamps one is refused before the chain could start.
      !isStateField(entity, field.name) &&
      (field.type === "string" || field.type === "text") &&
      (field.maxLength === undefined || field.maxLength >= 24)
  );
}

/**
 * Pick a trigger entity and a different target entity.
 *
 * The target needs two writable columns: one holds the marker that identifies
 * the rows this suite created, the other receives the computed value. Reusing a
 * single column would erase the marker the assertions look the rows up by.
 *
 * The value column must not be unique. The workflow writes the same number into
 * it on every run, the suite leaves that row behind, and a second run against the
 * same database is then refused by the unique index on its first write — a
 * `code` column took `42` once and rejected it ever after.
 *
 * Returns null when the model has no such pair, so the suite skips rather than
 * asserting against a shape this model does not have.
 */
function pickColumns(entity: EntityMeta): [FieldMeta, FieldMeta] | null {
  const [marker, ...rest] = stampableFields(entity);
  const value = rest.find((field) => !field.unique);
  return marker && value ? [marker, value] : null;
}

function pickPair(): { trigger: EntityMeta; target: EntityMeta } | null {
  const target = entities.find((entity) => pickColumns(entity) !== null);
  if (!target) return null;
  const trigger = entities.find(
    (entity) => entity.tableName !== target.tableName && stampableFields(entity).length >= 1
  );
  return trigger ? { trigger, target } : null;
}

const pair = pickPair();

describe("multi-step workflows triggered by rules", () => {
  const registered: { ruleId?: string; definitionId?: string } = {};
  let triggerEntity: EntityMeta;
  let targetEntity: EntityMeta;
  let triggerField: FieldMeta;
  /** Carries the suite marker, so the rows the workflow created can be found. */
  let targetMarker: FieldMeta;
  /** Receives the value computed by steps 1–2. */
  let targetValue: FieldMeta;
  let workflowName: string;
  let setupFailure: string | null = null;

  beforeAll(async () => {
    if (!pair) return;
    await harness.setup();

    triggerEntity = pair.trigger;
    targetEntity = pair.target;
    triggerField = stampableFields(triggerEntity)[0]!;
    [targetMarker, targetValue] = pickColumns(targetEntity) as [FieldMeta, FieldMeta];
    workflowName = `${suiteId}-escalation`;

    try {
      const keptFields = await buildTargetPayload("kept");
      const doomedFields = await buildTargetPayload("doomed");

      const steps: WorkflowStep[] = [
        {
          id: "s1_stage",
          name: "Stage a value",
          props: { nodeType: "Formula", target: "stagedNumber", operation: "set", value: "6" },
        },
        {
          id: "s2_compute",
          name: "Compute from the staged value",
          props: {
            nodeType: "Formula",
            target: "computedNumber",
            source: "stagedNumber",
            operation: "multiply",
            operand: "7",
          },
        },
        {
          id: "s3_create_kept",
          name: `Create a ${targetEntity.displayName}`,
          props: {
            nodeType: "CreateEntity",
            entity: targetEntity.tableName,
            as: "keptId",
            fields: JSON.stringify(keptFields),
          },
        },
        {
          id: "s4_create_doomed",
          name: `Create a ${targetEntity.displayName} to retire`,
          props: {
            nodeType: "CreateEntity",
            entity: targetEntity.tableName,
            as: "doomedId",
            fields: JSON.stringify(doomedFields),
          },
        },
        {
          id: "s5_update_self",
          name: "Update the triggering record",
          props: {
            nodeType: "UpdateEntity",
            field: triggerField.name,
            value: `${suiteId}-touched`,
          },
        },
        {
          id: "s6_update_other",
          name: "Write the computed value onto the created row",
          props: {
            nodeType: "UpdateEntity",
            entity: targetEntity.tableName,
            targetSource: "keptId",
            field: targetValue.name,
            source: "computedNumber",
          },
        },
        {
          id: "s7_delete_other",
          name: "Retire the second created row",
          props: {
            nodeType: "DeleteEntity",
            entity: targetEntity.tableName,
            targetSource: "doomedId",
          },
        },
      ];

      const definition = await createWorkflowDefinition(harness.client, {
        name: workflowName,
        entityName: triggerEntity.tableName,
        operation: "CREATE",
        bpmnXml: buildWorkflowBpmn(`${suiteId}_process`, steps),
        description: "E2E: multi-step rule-triggered workflow",
        // Reached only through the rule, so the rule is what decides.
        triggerType: "rule",
      });
      registered.definitionId = definition.id;

      const rule = await createRule(harness.client, {
        entityName: triggerEntity.tableName,
        ruleName: `${suiteId}-trigger`,
        operation: "CREATE",
        jdmContent: buildTriggerJdm(workflowName),
      });
      registered.ruleId = rule.id;
      harness.trackRule(rule.id);
    } catch (error) {
      // Surface the reason in a failing assertion instead of an opaque
      // beforeAll crash that takes every test in the file with it.
      setupFailure = error instanceof Error ? error.message : String(error);
    }
  });

  afterAll(async () => {
    if (registered.definitionId) {
      await deleteWorkflowDefinition(harness.client, registered.definitionId);
    }
    await harness.teardown();
  });

  it.skipIf(!pair)("registers a rule-triggered definition", () => {
    expect(setupFailure).toBeNull();
    expect(registered.definitionId).toBeTruthy();
    expect(registered.ruleId).toBeTruthy();
  });

  it.skipIf(!pair)("runs the whole chain on a matching write", async () => {
    const created = await harness.createWithParents(triggerEntity, {
      [triggerField.name]: `${suiteId}-source`,
    });
    const triggerId = created?.id as string;
    expect(triggerId).toBeTruthy();

    const run = await waitForOurRun(triggerId);
    expect(run).not.toBeNull();
    expect(isFailure(run?.status)).toBe(false);

    // Step 5 — the triggering record was updated by its own workflow.
    const self = await readRecord(triggerEntity, triggerId);
    expect(String(self?.[triggerField.name])).toBe(`${suiteId}-touched`);
  });

  it.skipIf(!pair)("carries a computed value into a row an earlier step created", async () => {
    const rows = await listTargetRows();
    const kept = rows.find((row) => String(row[targetMarker.name]) === `${suiteId}-kept`);

    // Step 3 created it; step 6 found it again by the id step 3 captured and
    // wrote `computedNumber` — which step 2 derived from what step 1 staged:
    // 6 * 7 = 42. Nothing else in the chain could have produced that value.
    expect(kept).toBeDefined();
    expect(String(kept?.[targetValue.name])).toBe("42");
  });

  it.skipIf(!pair)("deletes a row a later step targeted by captured id", async () => {
    const rows = await listTargetRows();
    const doomed = rows.find((row) => String(row[targetMarker.name]) === `${suiteId}-doomed`);

    // The delete is soft, so dropping out of the list is the observable effect.
    expect(doomed).toBeUndefined();
  });

  it.skipIf(!pair)("does not run when the rule does not fire", async () => {
    // Deactivating the rule has the same shape as its condition evaluating
    // false: no `trigger-workflow` action is emitted for this write.
    await updateRule(harness.client, registered.ruleId!, { isActive: false });

    try {
      const before = (await listTargetRows()).length;
      const created = await harness.createWithParents(triggerEntity, {
        [triggerField.name]: `${suiteId}-nomatch`,
      });
      const triggerId = created?.id as string;
      expect(triggerId).toBeTruthy();
      await sleep(2000);

      const runs = await ourRuns(triggerId);
      const after = (await listTargetRows()).length;

      // A rule-triggered definition must not be auto-run on entity + operation.
      expect(runs.length).toBe(0);
      expect(after).toBe(before);
    } finally {
      await updateRule(harness.client, registered.ruleId!, { isActive: true });
    }
  });

  /**
   * A create payload for the target entity, as the literal field map the
   * CreateEntity steps insert. Built through the same factory the CRUD suites
   * use, so it stays valid for whatever this model is.
   */
  async function buildTargetPayload(stamp: string): Promise<Record<string, unknown>> {
    const foreignKeys: Record<string, string> = {};
    for (const fk of foreignKeyFields(targetEntity)) {
      const parent = harness.resolveParentEntity(fk.name);
      if (!parent) continue;
      const id = await harness.anyRecordId(parent);
      if (id) foreignKeys[fk.name] = id;
    }

    const record = buildRecord(targetEntity, {
      requiredOnly: true,
      foreignKeys,
      uniqueSalt: `${suiteId}${stamp}`,
      overrides: { [targetMarker.name]: `${suiteId}-${stamp}` },
    });

    // The executor writes these values straight into the column — it does not
    // go through the API's serialisation — so structured values have to arrive
    // as text the driver can store.
    for (const [key, value] of Object.entries(record)) {
      if (value !== null && typeof value === "object") record[key] = JSON.stringify(value);
    }
    return record;
  }

  /**
   * Runs of *this* suite's workflow. Filtering by name matters: the generator
   * also seeds automatic definitions per entity, and those produce runs of
   * their own against the same record.
   */
  async function ourRuns(triggerId: string): Promise<WorkflowRun[]> {
    const runs = await runsForEntity(harness.client, triggerEntity.tableName, triggerId);
    return runs.filter((run) => run.workflow_name === workflowName);
  }

  async function waitForOurRun(triggerId: string): Promise<WorkflowRun | null> {
    const deadline = Date.now() + 20_000;
    let last: WorkflowRun | null = null;
    while (Date.now() < deadline) {
      const [run] = await ourRuns(triggerId);
      if (run) {
        last = run;
        if (isTerminal(run.status)) return run;
      }
      await sleep(400);
    }
    return last;
  }

  async function readRecord(
    entity: EntityMeta,
    id: string
  ): Promise<Record<string, unknown> | null> {
    const response = await harness.client.get<Record<string, unknown>>(
      `/bus/${entity.route}/${id}`,
      { allowFailure: true }
    );
    if (!response.ok) return null;
    const body = response.data as Record<string, unknown> | undefined;
    return (body?.data as Record<string, unknown>) ?? body ?? null;
  }

  /**
   * The rows this suite's workflow created, found by the marker it stamps.
   *
   * Filtered server-side rather than paged through: the bulk-seed suite leaves
   * thousands of rows behind, and a fixed `limit` would quietly stop containing
   * the rows under test as the database fills up.
   */
  async function listTargetRows(): Promise<Array<Record<string, unknown>>> {
    const response = await harness.client.get<{ data?: Array<Record<string, unknown>> }>(
      `/bus/${targetEntity.route}?limit=100&filter.${targetMarker.name}=contains:${suiteId}`,
      { allowFailure: true }
    );
    return response.ok ? (response.data?.data ?? []) : [];
  }
});

/** A decision graph whose only row emits `trigger-workflow` naming one workflow. */
function buildTriggerJdm(workflowName: string): string {
  return JSON.stringify({
    nodes: [
      { id: "input", type: "inputNode", name: "Input", position: { x: 0, y: 0 } },
      {
        id: "trigger-table",
        type: "decisionTableNode",
        name: "Multi-step trigger",
        position: { x: 300, y: 0 },
        content: {
          hitPolicy: "collect",
          inputs: [{ id: "i1", name: "Record", field: "" }],
          outputs: [
            { id: "o1", name: "Action", field: "action" },
            { id: "o2", name: "Message", field: "message" },
            { id: "o3", name: "Rule ID", field: "ruleId" },
            { id: "o4", name: "Workflow Name", field: "workflowName" },
          ],
          rules: [
            {
              _id: `${workflowName}-row`,
              i1: "true",
              o1: "'trigger-workflow'",
              o2: "'Multi-step workflow triggered'",
              o3: `'${workflowName}'`,
              o4: `'${workflowName}'`,
            },
          ],
        },
      },
      { id: "output", type: "outputNode", name: "Output", position: { x: 600, y: 0 } },
    ],
    edges: [
      { id: "e1", sourceId: "input", targetId: "trigger-table" },
      { id: "e2", sourceId: "trigger-table", targetId: "output" },
    ],
  });
}

tanstack-start-nestjs/tests/suites/06b-w:
/**
 * State machines — the edges the model drew, and who moves a record along them.
 *
 * A state field is never written by a form: a person moves a record by pressing
 * one of its moves (POST /bus/:entity/:id/transition) along an edge the diagram
 * drew. A write that would change it is refused with 403 and
 * `STATE_FIELD_SYSTEM_MANAGED`, the administrator included; a create starts the
 * record in Draft and an accepted save moves it into the flow; an end state is
 * Final — locked, and reopened to Draft; and the list grid always shows the
 * state while the form never offers it as an input.
 *
 * `%%workflow … kind: state` declares a lifecycle: which state a record starts
 * in, which moves are legal from there, and which states it can end in. The
 * backend stores those edges in `sys_workflow_transitions` and the
 * entity-access guard refuses any status write with no matching edge.
 *
 * There are two ways for that to be wrong, and both look like a working
 * application from the outside:
 *
 *   the table is empty      — every transition is allowed, because the guard
 *                             only enforces a topology it can find. A record
 *                             jumps from draft straight to approved and no rule
 *                             or workflow in between ever runs.
 *   the table disagrees     — an edge the diagram drew is missing, so a move
 *     with the model           the model calls routine is refused in production.
 *
 * So this suite checks both directions: every edge the model declared is
 * offered and accepted, and a move the model never drew is refused. It walks
 * each machine breadth-first from its initial state rather than assuming a
 * record can be created directly in the state under test.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import {
  getEntity,
  harness,
  illegalTargetFrom,
  stateMachines,
  statesOf,
  successorsOf,
  type StateMachine,
} from "../harness/index.ts";

interface TransitionRow {
  table_name: string;
  status_field: string;
  from_state: string;
  to_state: string;
  transition_name?: string | null;
}

interface TransitionsResponse {
  data: TransitionRow[];
  byTable: Record<string, Array<{ from: string; to: string }>>;
}

/** `from→to`, the shape both the model and the API are reduced to for compare. */
function edgeKey(from: string, to: string): string {
  return `${from}→${to}`;
}

/**
 * The state a record is actually in, which is not always the one just written.
 *
 * A model's own rules and workflows may advance the status as a side effect of
 * the write: the CRM example's Lead moves itself from `qualified` straight on
 * to `converted`. Assuming the write sticks made this suite attempt an edge
 * from a state the record had already left, and read the resulting — entirely
 * correct — 403 as the guard refusing an edge the model had drawn.
 *
 * A write answers with the record it produced, so the state after a move is
 * usually already in hand. `stateOf` reads it out of whatever a create, patch
 * or read answered; `currentState` is the extra round trip, for the cases where
 * it is not — and each one of those costs the walk a request per step, which is
 * what put this suite over its timeout on the larger machines.
 */
function stateOf(payload: unknown, field: string): string | null {
  if (!payload || typeof payload !== "object") return null;
  const record = payload as Record<string, unknown>;
  const body = (record.data ?? record) as Record<string, unknown>;
  const value = body?.[field];
  return value === undefined || value === null ? null : String(value);
}

async function currentState(route: string, id: string, field: string): Promise<string | null> {
  const response = await harness.client.get<Record<string, unknown>>(`/bus/${route}/${id}`, {
    allowFailure: true,
  });
  if (!response.ok) return null;
  return stateOf(response.data, field);
}

describe("state machines", () => {
  let served: TransitionRow[] = [];
  let endpointAvailable = false;

  beforeAll(async () => {
    await harness.setup();
    const response = await harness.client.get<TransitionsResponse>("/workflows/transitions", {
      allowFailure: true,
    });
    endpointAvailable = response.ok;
    served = response.ok ? (response.data?.data ?? []) : [];
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("exposes the declared transitions", () => {
    expect(endpointAvailable).toBe(true);
  });

  // A model with no state diagrams is legitimate; the suite then has nothing
  // to assert and says so rather than passing silently on an empty loop.
  it("has a state machine to drive, or declares none", () => {
    if (stateMachines.length === 0) {
      console.log("  the model declares no state machines — nothing to drive");
      return;
    }
    expect(served.length).toBeGreaterThan(0);
  });

  for (const machine of stateMachines) {
    describe(machine.entity, () => {
      const entity = getEntity(machine.entity);

      it("stores every edge the model drew", () => {
        const declared = machine.edges.map((edge) => edgeKey(edge.from, edge.to)).sort();
        const stored = served
          .filter((row) => row.table_name === machine.tableName)
          .map((row) => edgeKey(row.from_state, row.to_state))
          .sort();
        expect([...new Set(stored)]).toEqual([...new Set(declared)]);
      });

      it("stores them against the status column the guard reads", () => {
        const fields = new Set(
          served
            .filter((row) => row.table_name === machine.tableName)
            .map((row) => row.status_field)
        );
        expect([...fields]).toEqual([machine.statusField]);
      });

      it("starts a new record in its initial state, whatever the request names", async () => {
        if (!machine.initial) return;
        // Ask for a state the record could not start in. The request is not
        // refused — a create is not a move — but the state it names is ignored.
        const asked = illegalTargetFrom(machine, machine.initial) ?? machine.terminal[0];
        if (!asked || asked === machine.initial) return;

        const record = await harness.createWithParents(entity, {
          [machine.statusField]: asked,
        });
        expect(record?.id).toBeTruthy();
        if (!record?.id) return;

        const settled =
          stateOf(record, machine.statusField) ??
          (await currentState(entity.route, String(record.id), machine.statusField));
        // The model's own workflows may already have moved it on from the
        // initial state; they may not have put it where the request asked.
        expect(settled).not.toBe(asked);
      });

      it("refuses a person's change to the state, the administrator included", async () => {
        const record = await harness.createWithParents(entity);
        if (!record?.id) return;
        const at =
          stateOf(record, machine.statusField) ??
          (await currentState(entity.route, String(record.id), machine.statusField));
        if (!at) return;
        // A move the model draws, so the only reason to refuse it is who is
        // asking: the harness signs in as the administrator.
        const target = successorsOf(machine, at)[0] ?? statesOf(machine).find((s) => s !== at);
        if (!target) return;

        const response = await harness.client.patch(
          `/bus/${entity.route}/${record.id}`,
          { [machine.statusField]: target },
          { allowFailure: true }
        );
        expect(response.status).toBe(403);
        const details = (response.data as { details?: { code?: string } } | undefined)?.details;
        expect(details?.code).toBe("STATE_FIELD_SYSTEM_MANAGED");

        // A refused write that still landed would be worse than one allowed:
        // the record would be in a state no workflow put it in.
        expect(await currentState(entity.route, String(record.id), machine.statusField)).toBe(at);
      });

      it("accepts the state sent back unchanged", async () => {
        const record = await harness.createWithParents(entity);
        if (!record?.id) return;
        const at = await currentState(entity.route, String(record.id), machine.statusField);
        if (!at) return;
        // A form or a client that sends the whole record back still saves: an
        // unchanged state is not a change.
        const response = await harness.client.patch(
          `/bus/${entity.route}/${record.id}`,
          { [machine.statusField]: at },
          { allowFailure: true }
        );
        expect(response.status).not.toBe(403);
      });

      it("shows the state in the list grid and never as a form input", async () => {
        const grid = await harness.client.get<Array<{ column_name: string }>>(
          `/bus/${entity.route}/fields/grid`,
          { allowFailure: true }
        );
        const form = await harness.client.get<Array<{ column_name: string }>>(
          `/bus/${entity.route}/fields/form`,
          { allowFailure: true }
        );
        expect(grid.status).toBe(200);
        expect(form.status).toBe(200);
        const columns = (payload: unknown) =>
          ((Array.isArray(payload) ? payload : ((payload as { data?: unknown })?.data ?? [])) as Array<{
            column_name: string;
          }>).map((field) => field.column_name);
        expect(columns(grid.data)).toContain(machine.statusField);
        expect(columns(form.data)).not.toContain(machine.statusField);
      });

      it("offers no way out of a terminal state", async () => {
        const terminal = machine.terminal[0];
        if (!terminal) return; // a machine that never ends

        const response = await harness.client.get<TransitionsResponse>(
          `/workflows/transitions?table=${machine.tableName}&from=${encodeURIComponent(terminal)}`,
          { allowFailure: true }
        );
        expect(response.status).toBe(200);

        // A terminal state is the model's statement that the record is done. An
        // edge out of one that the diagram never drew would let a closed record
        // reopen — and every rule and workflow keyed on "closed" would be
        // deciding about a record that had moved on.
        expect((response.data?.data ?? []).map((row) => row.to_state)).toEqual([]);
      });

      it("answers which moves are legal from a given state", async () => {
        const from = machine.initial || machine.edges[0]?.from;
        if (!from) return;

        const response = await harness.client.get<TransitionsResponse>(
          `/workflows/transitions?table=${machine.tableName}&from=${encodeURIComponent(from)}`,
          { allowFailure: true }
        );
        expect(response.status).toBe(200);

        const offered = (response.data?.data ?? []).map((row) => row.to_state).sort();
        expect([...new Set(offered)]).toEqual([...new Set(successorsOf(machine, from))].sort());
      });

      // ── The record's action buttons ────────────────────────────────────────
      // A person moves a record by pressing one of its moves. The harness signs
      // in as the administrator, so who may press is not what these test: the
      // edge, the version and the lock are.

      it("starts a new record in Draft and moves an accepted save into the flow", async () => {
        const record = await harness.createWithParents(entity);
        if (!record?.id) return;
        const settled =
          stateOf(record, machine.statusField) ??
          (await currentState(entity.route, String(record.id), machine.statusField));
        // Accepted: the first status of the flow (or wherever the model's own
        // workflows took it). Refused: Error, with the reason on the record.
        // A machine whose own first status is a draft keeps the record there.
        expect(settled).toBeTruthy();
        if (machine.initial.toLowerCase() !== "draft") expect(settled).not.toBe("draft");
      });

      it("offers exactly the drawn moves out of where the record is", async () => {
        const record = await harness.createWithParents(entity);
        if (!record?.id) return;
        const at = await currentState(entity.route, String(record.id), machine.statusField);
        if (!at || at === "error") return;
        const actions = await harness.client.get<Array<{ to: string; kind: string }>>(
          `/bus/${entity.route}/${record.id}/actions`,
          { allowFailure: true }
        );
        expect(actions.status).toBe(200);
        const offered = (actions.data ?? []).filter((a) => a.kind === "move").map((a) => a.to);
        expect([...new Set(offered)].sort()).toEqual([...new Set(successorsOf(machine, at))].sort());
      });

      it("moves along a drawn edge, refuses an undrawn one, and needs If-Match", async () => {
        const record = await harness.createWithParents(entity);
        if (!record?.id) return;
        const read = await harness.client.get<Record<string, unknown>>(
          `/bus/${entity.route}/${record.id}`
        );
        const at = stateOf(read.data, machine.statusField);
        const etag = read.headers.get("etag") ?? "";
        if (!at || at === "error") return;
        const path = `/bus/${entity.route}/${record.id}/transition`;

        const bare = await harness.client.post(path, { to: successorsOf(machine, at)[0] ?? at }, {
          allowFailure: true,
        });
        expect(bare.status).toBe(428);

        const illegal = illegalTargetFrom(machine, at);
        if (illegal) {
          const refused = await harness.client.post(path, { to: illegal }, {
            allowFailure: true,
            headers: { "If-Match": etag },
          });
          expect(refused.status).toBe(409);
          expect((refused.data as { details?: { code?: string } })?.details?.code).toBe(
            "INVALID_TRANSITION"
          );
        }

        const next = successorsOf(machine, at)[0];
        if (!next) return;
        const moved = await harness.client.post<Record<string, unknown>>(path, { to: next }, {
          allowFailure: true,
          headers: { "If-Match": etag },
        });
        // A rule of the model may refuse the move (422) — "a resolved case needs
        // its notes" — which is the model working. Anything else must be a move.
        if (moved.status === 422) return;
        expect(moved.status).toBe(200);
        expect(stateOf(moved.data, machine.statusField)).toBe(next);

        // The version moved with it: pressing again against the old one is a conflict.
        const stale = await harness.client.post(path, { to: next }, {
          allowFailure: true,
          headers: { "If-Match": etag },
        });
        expect(stale.status).toBe(409);
      });

      it("locks a Final record and reopens it to Draft", async () => {
        // Walk from where a new record lands to an end state, breadth-first.
        const record = await harness.createWithParents(entity);
        if (!record?.id) return;
        const id = String(record.id);
        let at = await currentState(entity.route, id, machine.statusField);
        if (!at || at === "error") return;
        const path = (from: string): string[] => {
          const seen = new Map<string, string[]>([[from, []]]);
          const queue = [from];
          while (queue.length) {
            const state = queue.shift()!;
            if (machine.terminal.includes(state)) return seen.get(state)!;
            for (const next of successorsOf(machine, state)) {
              if (seen.has(next)) continue;
              seen.set(next, [...seen.get(state)!, next]);
              queue.push(next);
            }
          }
          return [];
        };
        for (const next of path(at)) {
          const read = await harness.client.get(`/bus/${entity.route}/${id}`);
          const moved = await harness.client.post(`/bus/${entity.route}/${id}/transition`, { to: next }, {
            allowFailure: true,
            headers: { "If-Match": read.headers.get("etag") ?? "" },
          });
          if (moved.status !== 200) return; // a rule of the model stopped the walk
          at = next;
        }
        if (!machine.terminal.includes(at)) return;

        const read = await harness.client.get(`/bus/${entity.route}/${id}`);
        const etag = read.headers.get("etag") ?? "";
        const edit = await harness.client.patch(`/bus/${entity.route}/${id}`, {}, {
          allowFailure: true,
          headers: { "If-Match": etag },
        });
        expect(edit.status).toBe(409);
        expect((edit.data as { details?: { code?: string } })?.details?.code).toBe("RECORD_FINAL");

        const reopened = await harness.client.post<Record<string, unknown>>(
          `/bus/${entity.route}/${id}/transition`,
          { event: "reopen" },
          { allowFailure: true, headers: { "If-Match": etag } }
        );
        // A model may draw its own way out of an end state; reopen is the lifecycle's.
        if (reopened.status === 409) return;
        expect(reopened.status).toBe(200);
        expect(stateOf(reopened.data, machine.statusField)?.toLowerCase()).toBe("draft");
      });
    });
  }

  it("stores no transition for a table the model gave no state machine", () => {
    const modelled = new Set(stateMachines.map((machine: StateMachine) => machine.tableName));
    // A stray row here means something other than the model wrote the topology,
    // and the guard would be enforcing a lifecycle nobody declared.
    const stray = [...new Set(served.map((row) => row.table_name))].filter(
      (table) => !modelled.has(table)
    );
    expect(stray).toEqual([]);
  });
});

tanstack-start-nestjs/tests/suites/20-tr:
/**
 * The bell beside Log out, held to what it promises.
 *
 * Every write to a business entity is two transactions — the save that commits
 * the row as a draft, and the second one that finalises it or explains why it
 * could not — and a user's only account of how theirs ended is the notification
 * list. Four properties make that account trustworthy, and each is asserted
 * here because each can break without anything else failing:
 *
 *   - a write produces both halves, so a save that never finalises is visible
 *     rather than silent;
 *   - the list is the *caller's own*, read from the audit trail, so it can
 *     never carry another user's records;
 *   - newest first, because the transaction someone is waiting on is the one
 *     they just started;
 *   - read state sticks, so the unread badge means "not seen" rather than
 *     "never happened".
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import { entities, harness, HttpClient } from "../harness/index.ts";

interface Notification {
  id: string;
  at: string;
  read: boolean;
  outcome: "pending" | "succeeded" | "failed";
  phase: "draft" | "finalize";
  operation: "create" | "update" | "delete" | "save";
  entityTable: string;
  entityLabel: string;
  recordId: string | null;
  recordLabel: string;
  title: string;
  detail: string;
  href: string | null;
}

interface NotificationPage {
  data: Notification[];
  meta: { unread: number; limit: number; nextCursor: string | null };
}

/**
 * Poll for the two halves of one record's transaction.
 *
 * The finalising transaction runs after the save's response — in-process
 * before the response where Trigger.dev is not configured, and in another
 * process entirely where it is — so a read taken the instant a create returns
 * is racing a write that may not have been issued. The application is right to
 * behave that way, so the test is what waits.
 */
async function notificationsFor(recordId: string, phases: number): Promise<Notification[]> {
  for (let attempt = 0; attempt < 30; attempt++) {
    if (attempt > 0) await new Promise((resolve) => setTimeout(resolve, 100));

    const page = await harness.client.get<NotificationPage>("/notifications?limit=50", {
      allowFailure: true,
    });
    if (!page.ok) return [];

    const mine = (page.data.data ?? []).filter((item) => item.recordId === recordId);
    if (mine.length >= phases) return mine;
  }
  return [];
}

describe("transaction notifications", () => {
  beforeAll(async () => {
    await harness.setup();
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("answers the signed-in caller and nobody else", async () => {
    const page = await harness.client.get<NotificationPage>("/notifications?limit=5", {
      allowFailure: true,
    });
    expect(page.status).toBe(200);
    expect(Array.isArray(page.data.data)).toBe(true);
    expect(typeof page.data.meta.unread).toBe("number");
  });

  it("refuses a caller with no session", async () => {
    // A separate client, so it carries no cookie from the shared harness login.
    const anonymous = new HttpClient();
    const page = await anonymous.get("/notifications", { allowFailure: true });
    expect([401, 403]).toContain(page.status);
  });

  it("records both halves of a write, newest first", async () => {
    // One entity is enough: the pipeline is the same for all of them, and this
    // suite is about the notification contract rather than about each model.
    const entity = entities[0];
    if (!entity) return;

    const created = (await harness.createWithParents(entity)) as { id?: string } | null;
    if (!created?.id) return;

    const mine = await notificationsFor(created.id, 2);
    expect(mine.length).toBeGreaterThanOrEqual(2);

    // The list arrives newest first, so the draft — written first — is last.
    const draft = mine.find((item) => item.phase === "draft");
    const finalize = mine.find((item) => item.phase === "finalize");
    expect(draft).toBeDefined();
    expect(finalize).toBeDefined();

    expect(new Date(mine[0]!.at).getTime()).toBeGreaterThanOrEqual(
      new Date(mine[mine.length - 1]!.at).getTime()
    );

    // A notification is a sentence about a record, not a row of column names.
    expect(draft!.title.length).toBeGreaterThan(0);
    expect(draft!.detail.length).toBeGreaterThan(0);
    expect(draft!.entityTable).toBe(entity.tableName);
    expect(draft!.outcome).toBe("pending");

    // Succeeded or failed — never still pending, which is what "the second
    // transaction never ran" would look like.
    expect(["succeeded", "failed"]).toContain(finalize!.outcome);
  });

  it("agrees with the record it describes", async () => {
    const entity = entities[0];
    if (!entity) return;

    const created = (await harness.createWithParents(entity)) as
      | { id?: string; doc_status?: string }
      | null;
    if (!created?.id) return;

    const mine = await notificationsFor(created.id, 2);
    const finalize = mine.find((item) => item.phase === "finalize");
    if (!finalize) return;

    const fetched = await harness.client.get<{ doc_status?: string }>(
      `/bus/${entity.route}/${created.id}`,
      { allowFailure: true }
    );
    if (!fetched.ok) return;

    // The notification and the badge on the record cannot disagree: a record
    // reported done has moved on — into its flow, or to Final — and one
    // reported failed is in Error, carrying its reason.
    if (finalize.outcome === "succeeded") {
      expect(["active", "final"]).toContain(fetched.data.doc_status);
    } else {
      expect(fetched.data.doc_status).toBe("error");
    }
  });

  it("keeps a notification read once it has been read", async () => {
    const entity = entities[0];
    if (!entity) return;

    const created = (await harness.createWithParents(entity)) as { id?: string } | null;
    if (!created?.id) return;

    const mine = await notificationsFor(created.id, 1);
    const target = mine[0];
    if (!target) return;

    const marked = await harness.client.post<{ marked: number }>(
      "/notifications/read",
      { ids: [target.id] },
      { allowFailure: true }
    );
    expect(marked.status).toBe(200);

    const page = await harness.client.get<NotificationPage>("/notifications?limit=50", {
      allowFailure: true,
    });
    if (!page.ok) return;

    const again = (page.data.data ?? []).find((item) => item.id === target.id);
    expect(again?.read).toBe(true);
  });

  it("clears the unread count when everything is marked read", async () => {
    const cleared = await harness.client.post<{ marked: number }>(
      "/notifications/read-all",
      {},
      { allowFailure: true }
    );
    expect(cleared.status).toBe(200);

    const count = await harness.client.get<{ unread: number }>("/notifications/unread-count", {
      allowFailure: true,
    });
    expect(count.status).toBe(200);
    expect(count.data.unread).toBe(0);
  });
});

tanstack-start-nestjs/tests/suites/17-di:
/**
 * What a record is called.
 *
 * Every screen that names a record — the window header, the breadcrumb, the
 * record navigator, and every dropdown that points at it — asks the dictionary
 * which columns identify it, then reads those off the row. `is_identifier` is
 * the whole mechanism, and it travels in the field metadata.
 *
 * When it stopped travelling, nothing errored. The front end fell through to a
 * list of guessed column names, missed, and titled every record with its own
 * primary key:
 *
 *     ← List | 1a498937-ac17-421f-a427-1a2a329298c2
 *
 * on a Member whose dictionary row marks `full_name` as the identifier. Nine
 * entities out of nine, unreadable by name, and every existing test green.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import { entities, foreignKeyFields, harness } from "../harness/index.ts";

interface FormField {
  column_name: string;
  is_identifier?: boolean;
  is_key?: boolean;
  ref_table_name?: string | null;
  ref_label_fields?: string[] | null;
  sys_reference_id?: number;
  seq_no?: number;
}

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function rows<T>(body: unknown): T[] {
  if (Array.isArray(body)) return body as T[];
  if (body && typeof body === "object") {
    const record = body as Record<string, unknown>;
    if (Array.isArray(record.data)) return record.data as T[];
  }
  return [];
}

/** Every column the dictionary marks as naming the record, key excluded. */
function identifiersOf(fields: FormField[]): FormField[] {
  return fields
    .filter((field) => field.is_identifier && !field.is_key)
    .sort((a, b) => Number(a.seq_no ?? 0) - Number(b.seq_no ?? 0));
}

/**
 * The identifiers a value can be read straight off the row — not references.
 *
 * A join entity has no name of its own, so the dictionary marks its foreign
 * keys instead, and §3.7 says the label is those parents *resolved through
 * their own labels*. The NestJS stack does not do that second hop yet: it
 * reads the referenced row's identifier columns, which on a join entity are
 * more uuids. So an entity whose identifiers are all references legitimately
 * has no readable label here, and the assertions below say which case they are
 * in rather than failing on a gap this suite did not open.
 *
 * Tracked in TODOS.md — "a join entity's display value is two raw uuids".
 */
function literalIdentifiersOf(fields: FormField[]): FormField[] {
  return identifiersOf(fields).filter((field) => !field.ref_table_name);
}

/**
 * Whether the dictionary has anything to label a record with: a text column of
 * its own, or — for a join entity — two parents. A dated figure with one parent
 * has neither, and shows its id, which is the documented last resort.
 */
function hasLabelSource(entity: (typeof entities)[number]): boolean {
  return (
    foreignKeyFields(entity).length >= 2 ||
    entity.fields.some(
      (field) =>
        !field.isForeignKey &&
        field.name !== "id" &&
        (field.type === "string" || field.type === "text")
    )
  );
}

describe("display value", () => {
  const formFields = new Map<string, FormField[]>();
  const gridFields = new Map<string, FormField[]>();

  beforeAll(async () => {
    await harness.setup();
    for (const entity of entities) {
      const form = await harness.client.get<FormField[]>(
        `/bus/${entity.route}/fields/form?includeHidden=true`,
        { allowFailure: true }
      );
      if (form.ok) formFields.set(entity.route, form.data ?? []);

      const grid = await harness.client.get<FormField[]>(
        `/bus/${entity.route}/fields/grid?includeHidden=true`,
        { allowFailure: true }
      );
      if (grid.ok) gridFields.set(entity.route, grid.data ?? []);
    }
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("sends is_identifier in the form metadata", () => {
    // Absent, not false: a payload that never carries the property is the
    // failure this suite was written for, and `false` everywhere is a
    // different fault with a different fix.
    const silent = entities
      .filter((entity) => {
        const fields = formFields.get(entity.route) ?? [];
        return fields.length > 0 && fields.every((field) => field.is_identifier === undefined);
      })
      .map((entity) => entity.route);
    expect(silent).toEqual([]);
  });

  it("sends is_key in the form metadata", () => {
    const silent = entities
      .filter((entity) => {
        const fields = formFields.get(entity.route) ?? [];
        return fields.length > 0 && fields.every((field) => field.is_key === undefined);
      })
      .map((entity) => entity.route);
    expect(silent).toEqual([]);
  });

  it("sends is_identifier in the grid metadata too", () => {
    const silent = entities
      .filter((entity) => {
        const fields = gridFields.get(entity.route) ?? [];
        return fields.length > 0 && fields.every((field) => field.is_identifier === undefined);
      })
      .map((entity) => entity.route);
    expect(silent).toEqual([]);
  });

  it("never marks the primary key as the display value", () => {
    const offenders: string[] = [];
    for (const entity of entities) {
      for (const field of formFields.get(entity.route) ?? []) {
        if (field.is_key && field.is_identifier) {
          offenders.push(`${entity.route}.${field.column_name}`);
        }
      }
    }
    expect(offenders).toEqual([]);
  });

  for (const entity of entities) {
    describe(entity.name, () => {
      it("marks at least one column as the display value", () => {
        const fields = formFields.get(entity.route) ?? [];
        if (fields.length === 0 || !hasLabelSource(entity)) return;
        expect(identifiersOf(fields).length).toBeGreaterThan(0);
      });

      it("names a record from its own columns, or from parents that exist", () => {
        const fields = formFields.get(entity.route) ?? [];
        if (fields.length === 0 || !hasLabelSource(entity)) return;

        if (literalIdentifiersOf(fields).length > 0) return;

        // A join entity: every identifier is a reference, so the label has to
        // come from the parents. What is checkable today is that the chain is
        // *followable* — each identifier names a table the dictionary knows.
        // A `ref_table_name` pointing at nothing is a dead reference and the
        // label can never be resolved, however many hops are implemented.
        //
        // Whether the second hop happens is the gap in TODOS.md; how deep it
        // would have to go is model-dependent (Booking → ClassSession →
        // ClassOffering is two), so asserting a depth here would encode this
        // model's shape into every generated application's tests.
        const referenced = identifiersOf(fields)
          .map((field) => field.ref_table_name)
          .filter((table): table is string => Boolean(table));
        expect(referenced.length).toBeGreaterThan(0);

        const dangling = referenced.filter(
          (table) => !entities.some((item) => item.tableName === table)
        );
        expect(dangling).toEqual([]);
      });

      it("resolves a record to something other than its uuid", async () => {
        const fields = formFields.get(entity.route) ?? [];
        const identifiers = literalIdentifiersOf(fields);
        if (identifiers.length === 0) return;

        const listed = await harness.client.get(`/bus/${entity.route}?limit=5`, {
          allowFailure: true,
        });
        if (!listed.ok) return;

        const row = rows<Record<string, unknown>>(listed.data)[0];
        if (!row) return;

        const label = identifiers
          .map((field) => row[field.column_name])
          .filter((value) => value !== null && value !== undefined && value !== "")
          .map(String)
          .join(" ");

        expect(label.length).toBeGreaterThan(0);
        expect(UUID.test(label)).toBe(false);
      });

      it("gives every reference to it a label column to show", () => {
        // The other side of the same mechanism: a lookup pointing here has to
        // know what to display instead of the stored id.
        if (!hasLabelSource(entity)) return;
        const offenders: string[] = [];
        for (const other of entities) {
          for (const field of formFields.get(other.route) ?? []) {
            if (field.ref_table_name !== entity.tableName) continue;
            if (!field.ref_label_fields || field.ref_label_fields.length === 0) {
              offenders.push(`${other.route}.${field.column_name}`);
            }
          }
        }
        expect(offenders).toEqual([]);
      });
    });
  }
});

