/**
 * Static business rules — {{entity.displayName}}
 *
 * Generates a JDM validation rule set for this entity, registers it, then
 * proves it actually fires: valid records pass, invalid records are prevented.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import {
  buildMarkerRuleJdm,
  buildRecord,
  buildStaticValidationJdm,
  collectActions,
  createRule,
  dryRun,
  entities,
  evaluate,
  firstTextField,
  getEntity,
  getRule,
  harness,
  listRules,
  numericFields,
  scalarFields,
  validateJdm,
  writableFields,
  type RuleRecord,
} from "../harness/index.ts";

const entity = getEntity("{{entity.name}}");
const suiteId = `e2e-{{entity.tableName}}-${Date.now().toString(36)}`;

describe("{{entity.displayName}} business rules", () => {
  let rule: RuleRecord | null = null;

  beforeAll(async () => {
    await harness.setup();
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("builds valid JDM for the entity", async () => {
    const jdm = buildStaticValidationJdm(entity, writableFields(entity));

    // Well-formed JSON with the three-node input → table → output shape.
    const parsed = JSON.parse(jdm) as { nodes: unknown[]; edges: unknown[] };
    expect(parsed.nodes).toHaveLength(3);
    expect(parsed.edges).toHaveLength(2);

    const result = await validateJdm(harness.client, jdm);
    const isValid = result.valid ?? result.isValid;
    if (isValid !== undefined) expect(isValid).toBe(true);
  });

  it("registers the rule against the entity", async () => {
    const jdm = buildStaticValidationJdm(entity, writableFields(entity));

    rule = await createRule(harness.client, {
      entityName: entity.tableName,
      ruleName: `${suiteId}-validation`,
      operation: "ALL",
      jdmContent: jdm,
    });

    expect(rule.id).toBeTruthy();
    harness.trackRule(rule.id);
  });

  it("reads the rule back", async () => {
    expect(rule).not.toBeNull();

    const fetched = await getRule(harness.client, rule!.id);
    expect(fetched.id).toBe(rule!.id);
    expect(fetched.entity_name ?? fetched.entityName).toBeTruthy();
  });

  it("lists the rule under its entity", async () => {
    const rules = await listRules(harness.client, { entityName: entity.tableName });
    const ids = rules.map((r) => r.id);

    expect(ids).toContain(rule!.id);
  });

  it("evaluates a valid record without a prevent action", async () => {
    // buildValidRecord resolves foreign keys from real parents — a bare
    // buildRecord() leaves them unset and would trip the required-FK rule.
    const payload = await harness.buildValidRecord(entity);
    const outcome = await evaluate(harness.client, entity.tableName, "CREATE", payload);

    const prevents = collectActions(outcome.results).filter((a) => a.type === "prevent");
    expect(prevents.map((action) => action.config.message)).toEqual([]);
  });

  it("prevents a record missing a required field", async () => {
    const required = scalarFields(entity).filter((f) => f.required);
    if (required.length === 0) return; // nothing mandatory to violate

    // Start from a valid payload so the only violation is the one we introduce.
    const payload = await harness.buildValidRecord(entity);
    delete payload[required[0]!.name];

    const outcome = await evaluate(harness.client, entity.tableName, "CREATE", payload);
    const actions = collectActions(outcome.results);

    expect(actions.some((a) => a.type === "prevent")).toBe(true);
  });

  it("prevents a negative value on a numeric field", async () => {
    const numeric = numericFields(entity);
    if (numeric.length === 0) return;

    const payload = await harness.buildValidRecord(entity, { [numeric[0]!.name]: -42 });
    const outcome = await evaluate(harness.client, entity.tableName, "CREATE", payload);

    expect(collectActions(outcome.results).some((a) => a.type === "prevent")).toBe(true);
  });

  it("dry-runs the rule without touching data", async () => {
    expect(rule).not.toBeNull();

    const before = await harness.client.get<{ meta: { total: number } }>(
      `/bus/${entity.route}?limit=1`
    );

    const result = await dryRun(harness.client, rule!.id, buildRecord(entity));
    expect(result).toBeTruthy();

    const after = await harness.client.get<{ meta: { total: number } }>(
      `/bus/${entity.route}?limit=1`
    );
    expect(after.data.meta.total).toBe(before.data.meta.total);
  });

  it("blocks a real create that violates the rule", async () => {
    const numeric = numericFields(entity);
    if (numeric.length === 0) return;

    const payload = await harness.buildValidRecord(entity, { [numeric[0]!.name]: -1 });
    const response = await harness.client.post(`/bus/${entity.route}`, payload, {
      allowFailure: true,
    });

    // The rules engine runs inside the create path, so a prevent surfaces as 4xx.
    expect(response.ok).toBe(false);
    expect(response.status).toBeGreaterThanOrEqual(400);
    expect(response.status).toBeLessThan(500);
  });

  it("allows a real create that satisfies the rule", async () => {
    const created = await harness.createWithParents(entity);
    expect(created).not.toBeNull();
    expect(created?.id).toBeTruthy();
  });

  it("stops enforcing once deactivated", async () => {
    expect(rule).not.toBeNull();

    await harness.client.delete(`/rules/${rule!.id}`, { allowFailure: true });

    const rules = await listRules(harness.client, {
      entityName: entity.tableName,
      isActive: true,
    });
    expect(rules.map((r) => r.id)).not.toContain(rule!.id);
  });
});

/**
 * One rule, one value, one entity.
 *
 * Everything above shares its ground with the model's own compiled rules: a
 * negative number may be refused by this suite's rule, by a `%%action` the
 * model declares, or by both. These cases use a marker value nothing else has
 * an opinion about, so a refusal can only have come from the rule under test —
 * which is what makes it possible to say that deactivating a rule stops it
 * enforcing, rather than only that it left the listing.
 */
describe("{{entity.displayName}} rule scope", () => {
  const marker = `e2e-forbidden-${Date.now().toString(36)}`;
  /**
   * A second forbidden value, for the update case.
   *
   * The rule refuses both, but a suite that reused one value for the create
   * and the update would leave the update's row holding it — and the create
   * that follows collides on a unique column instead of being refused by the
   * rule, which is a 409 that looks like a rules failure and is not one.
   */
  const updateMarker = `${marker}-on-update`;
  const message = `${marker} is not allowed here`;

  let markerRule: RuleRecord | null = null;

  beforeAll(async () => {
    await harness.setup();
  });

  afterAll(async () => {
    if (markerRule) await harness.client.delete(`/rules/${markerRule.id}`, { allowFailure: true });
    await harness.teardown();
  });

  it("refuses the write it was written to refuse, in the author's words", async () => {
    const textField = firstTextField(entity);
    if (!textField) return;

    markerRule = await createRule(harness.client, {
      entityName: entity.tableName,
      ruleName: `${suiteId}-marker`,
      operation: "CREATE",
      jdmContent: buildMarkerRuleJdm(entity, textField, [marker, updateMarker], message),
    });
    harness.trackRule(markerRule.id);

    const payload = await harness.buildValidRecord(entity, { [textField.name]: marker });
    const response = await harness.client.post<{ message?: string; errors?: string[] }>(
      `/bus/${entity.route}`,
      payload,
      { allowFailure: true }
    );

    expect(response.status).toBe(400);

    // The message the rule's author wrote has to reach the caller. A refusal
    // that says only "validation failed" tells the person at the screen
    // nothing they can act on, and tells support nothing either.
    const reported = JSON.stringify(response.data);
    expect(reported).toContain(message);
  });

  it("says nothing about a value it was not written about", async () => {
    const textField = firstTextField(entity);
    if (!textField || !markerRule) return;

    const created = await harness.createWithParents(entity, {
      [textField.name]: `${marker}-but-longer`,
    });

    // Equality, not containment: a rule that matches a superstring is a rule
    // that will one day refuse a record nobody expected it to.
    expect(created).not.toBeNull();
  });

  it("is silent on an operation it is not scoped to", async () => {
    const textField = firstTextField(entity);
    if (!textField || !markerRule) return;

    const created = await harness.createWithParents(entity);
    if (!created) return;

    // The rule is registered for CREATE. An engine that evaluates every rule on
    // every write refuses this update too, and the scoping column in the rule
    // table means nothing.
    const response = await harness.client.patch(
      `/bus/${entity.route}/${created.id}`,
      { [textField.name]: updateMarker },
      { allowFailure: true }
    );

    expect(response.status).toBeLessThan(300);
  });

  it("says nothing about another entity's records", async () => {
    const textField = firstTextField(entity);
    if (!textField || !markerRule) return;

    const other = entities.find((candidate) => {
      if (candidate.tableName === entity.tableName) return false;
      const field = firstTextField(candidate);
      return field?.name === textField.name;
    });
    if (!other) return; // no other entity shares the column, nothing to confuse

    // Same column name, same forbidden value, different table. A rules engine
    // that keys on the column rather than on the entity refuses this one too,
    // and one entity's policy quietly becomes everybody's.
    const created = await harness.createWithParents(other, { [textField.name]: marker });
    expect(created).not.toBeNull();
  });

  it("stops refusing once it is deactivated", async () => {
    const textField = firstTextField(entity);
    if (!textField || !markerRule) return;

    await harness.client.delete(`/rules/${markerRule.id}`, { allowFailure: true });

    const payload = await harness.buildValidRecord(entity, { [textField.name]: marker });
    const response = await harness.client.post<Record<string, unknown>>(
      `/bus/${entity.route}`,
      payload,
      { allowFailure: true }
    );

    // The write that was refused a moment ago now goes through. Asserting only
    // that the rule left the listing would pass just as happily against an
    // engine holding a cached copy of it — which is the failure mode that
    // matters, because it survives a deploy.
    expect(response.status).toBeLessThan(300);
    if (response.data?.id) harness.track(entity.route, String(response.data.id));

    markerRule = null;
  });
});

tanstack-start-nestjs/tests/suites/02c-d:
/**
 * Application Dictionary — references.
 *
 * A reference is what turns a column into a control. `sys_reference_id` 13 on a
 * uuid column makes it read-only; a list reference makes a dropdown and carries
 * the values it offers; a table reference makes a lookup and carries the table
 * it searches and the column it shows instead of the stored id.
 *
 * Every failure here has the same shape on screen: the control degrades to a
 * plain text box. A dropdown that lost its list becomes free text, so `status`
 * accepts a value the state machine has no edge for. A lookup that lost its
 * table becomes a box asking a human to type a uuid. Neither errors, and both
 * are invisible to a test that only checks the column exists.
 *
 * So the assertions here compare the running application against the *model* —
 * `harness/model.ts`, generated from the `%%enum` directives — rather than
 * against the dictionary that the same generator wrote.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import {
  entities,
  foreignKeyFields,
  harness,
  modelEnums,
  writableFields,
} from "../harness/index.ts";

/** sys_reference ids the generator treats as built-in scalars. */
const STANDARD = {
  string: 10,
  integer: 11,
  amount: 12,
  id: 13,
  text: 14,
  date: 15,
  dateTime: 16,
  list: 17,
  table: 18,
  tableDirect: 19,
  yesNo: 20,
} as const;

/** Model enums are allocated from 1000 up; anything at or above is a dropdown. */
const FIRST_MODEL_REFERENCE = 1000;

interface FormField {
  column_name: string;
  name?: string;
  sys_reference_id?: number;
  is_mandatory?: boolean;
  /** Present on table references — the table the lookup searches. */
  ref_table_name?: string | null;
  /** Present on table references — the columns shown instead of the id. */
  ref_label_fields?: string[] | null;
  /** Present on list references — the dropdown's contents. */
  options?: Array<{ value: string; label: string }> | null;
}

interface ReferenceRow {
  sys_reference_id: number;
  name: string;
  validation_type?: string;
}

function rows<T>(body: unknown): T[] {
  if (Array.isArray(body)) return body as T[];
  if (body && typeof body === "object") {
    const record = body as Record<string, unknown>;
    if (Array.isArray(record.data)) return record.data as T[];
  }
  return [];
}

describe("application dictionary — references", () => {
  let references: ReferenceRow[] = [];
  let referenceIds = new Set<number>();
  /** entity route → its form fields, including the hidden ones. */
  const fieldsByRoute = new Map<string, FormField[]>();
  const registeredTables = new Set(entities.map((entity) => entity.tableName));

  beforeAll(async () => {
    await harness.setup();

    const response = await harness.client.get("/sys/references?limit=1000", {
      allowFailure: true,
    });
    references = response.ok ? rows<ReferenceRow>(response.data) : [];
    referenceIds = new Set(references.map((reference) => reference.sys_reference_id));

    for (const entity of entities) {
      const fields = await harness.client.get<FormField[]>(
        `/bus/${entity.route}/fields/form?includeHidden=true`,
        { allowFailure: true }
      );
      if (fields.ok) fieldsByRoute.set(entity.route, fields.data);
    }
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("serves the reference registry", () => {
    expect(references.length).toBeGreaterThan(0);
  });

  it("registers the standard scalar references", () => {
    const missing = Object.values(STANDARD).filter((id) => !referenceIds.has(id));
    expect(missing).toEqual([]);
  });

  // ── The model's enums ─────────────────────────────────────────────────────

  describe("model enums", () => {
    it("registers a reference for every enum the model declares", () => {
      const missing = modelEnums
        .filter((modelEnum) => !referenceIds.has(modelEnum.referenceId))
        .map((modelEnum) => modelEnum.name);
      expect(missing).toEqual([]);
    });

    for (const modelEnum of modelEnums) {
      it(`${modelEnum.name} offers exactly the values the model declares`, async () => {
        const response = await harness.client.get<Array<{ value: string; name?: string }>>(
          `/sys/ref-list?sys_reference_id=${modelEnum.referenceId}`,
          { allowFailure: true }
        );
        expect(response.status).toBe(200);

        const served = rows<{ value: string }>(response.data)
          .map((entry) => entry.value)
          .sort();
        expect(served).toEqual([...modelEnum.values].sort());
      });
    }
  });

  // ── Per entity ────────────────────────────────────────────────────────────

  for (const entity of entities) {
    describe(entity.displayName, () => {
      it("gives every field a reference that resolves", () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        expect(fields.length).toBeGreaterThan(0);

        const dangling = fields
          .filter((field) => typeof field.sys_reference_id === "number")
          .filter((field) => !referenceIds.has(field.sys_reference_id as number))
          .map((field) => `${field.column_name}→${field.sys_reference_id}`);
        expect(dangling).toEqual([]);
      });

      // The one that catches a lookup degraded to a uuid text box.
      it("points every foreign key at a table that exists", () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        const byColumn = new Map(fields.map((field) => [field.column_name, field]));

        const unresolved: string[] = [];
        for (const fk of foreignKeyFields(entity)) {
          const field = byColumn.get(fk.name);
          if (!field) continue; // absence is 02b's failure, not this one's
          // A reference to an entity the model never declares has no table to
          // point at; the application degrades it to a plain value on purpose.
          if (!harness.resolveParentEntity(fk.name)) continue;
          const target = field.ref_table_name;
          if (!target || !registeredTables.has(target)) {
            unresolved.push(`${fk.name}→${target ?? "unresolved"}`);
          }
        }
        expect(unresolved).toEqual([]);
      });

      it("gives every foreign key a column to display instead of the id", () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        const byColumn = new Map(fields.map((field) => [field.column_name, field]));

        const unlabelled: string[] = [];
        for (const fk of foreignKeyFields(entity)) {
          const field = byColumn.get(fk.name);
          if (!field?.ref_table_name) continue; // covered by the test above
          // The dictionary labels a record by a name-ish column, a code, the
          // first text column, or — for a join entity — its first two parents.
          // A target with none of those (a dated figure with one parent) has
          // nothing to show but its id, which is the documented last resort.
          const target = entities.find((item) => item.tableName === field.ref_table_name);
          const hasLabelSource =
            !target ||
            foreignKeyFields(target).length >= 2 ||
            target.fields.some(
              (item) =>
                !item.isForeignKey &&
                item.name !== "id" &&
                (item.type === "string" || item.type === "text")
            );
          if (!hasLabelSource) continue;
          const labels = field.ref_label_fields;
          if (!Array.isArray(labels) || labels.length === 0) unlabelled.push(fk.name);
        }
        expect(unlabelled).toEqual([]);
      });

      // A label column the target table does not have resolves to nothing at
      // render time, which puts the raw id back on screen.
      it("names label columns the target table actually has", () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        const byTable = new Map(entities.map((item) => [item.tableName, item]));

        const bad: string[] = [];
        for (const fk of foreignKeyFields(entity)) {
          const field = byColumn(fields, fk.name);
          const target = field?.ref_table_name;
          if (!target) continue;
          const targetEntity = byTable.get(target);
          if (!targetEntity) continue;
          const columns = new Set(targetEntity.fields.map((item) => item.name));
          for (const label of field?.ref_label_fields ?? []) {
            if (!columns.has(label)) bad.push(`${fk.name}→${target}.${label}`);
          }
        }
        expect(bad).toEqual([]);
      });

      it("feeds every dropdown with options", () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        const empty = fields
          .filter((field) => (field.sys_reference_id ?? 0) >= FIRST_MODEL_REFERENCE)
          .filter((field) => !Array.isArray(field.options) || field.options.length === 0)
          .map((field) => field.column_name);
        expect(empty).toEqual([]);
      });

      // A dropdown whose options are not among the model's values would let a
      // user pick something no rule or workflow was written for.
      it("offers only values the model declares", () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        const byReference = new Map(modelEnums.map((item) => [item.referenceId, item]));

        const strays: string[] = [];
        for (const field of fields) {
          const modelEnum = byReference.get(field.sys_reference_id ?? -1);
          if (!modelEnum || !Array.isArray(field.options)) continue;
          const allowed = new Set(modelEnum.values);
          for (const option of field.options) {
            if (!allowed.has(option.value)) {
              strays.push(`${field.column_name}=${option.value}`);
            }
          }
        }
        expect(strays).toEqual([]);
      });

      it("marks the model's required fields mandatory", () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        const byName = new Map(fields.map((field) => [field.column_name, field]));

        const wrong = writableFields(entity)
          .filter((field) => field.required)
          .filter((field) => byName.has(field.name))
          .filter((field) => byName.get(field.name)?.is_mandatory !== true)
          .map((field) => field.name);
        expect(wrong).toEqual([]);
      });
    });
  }
});

function byColumn(fields: FormField[], name: string): FormField | undefined {
  return fields.find((field) => field.column_name === name);
}

