});

tanstack-start-nestjs/tests/suites/16-ap:
/**
 * The list endpoint's contract.
 *
 * Every screen in the application is a page of a list, and every one of them
 * is drawn from `meta` — the total, the page, the size. A pager that computes
 * from a hard-coded 50 rather than from the server's echoed limit puts a reader
 * on page 3 of 2; a deep page that repeats rows from page 1 loses records
 * without erroring. Both look like working software from the outside.
 *
 * `10-benchmark` times these shapes. This one asserts they are *correct*, which
 * is the half a stopwatch cannot see.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import { entities, firstTextField, harness } from "../harness/index.ts";

interface Page {
  data?: Array<{ id?: string; [column: string]: unknown }>;
  meta?: { total?: number; page?: number; pageSize?: number; limit?: number };
}

const ABSENT_ID = "00000000-0000-0000-0000-000000000000";

describe("list endpoint contract", () => {
  /** route → how many rows it holds, so a test can tell an empty table from a broken one. */
  const counts = new Map<string, number>();

  beforeAll(async () => {
    await harness.setup();
    for (const entity of entities) {
      const response = await harness.client.get<Page>(`/bus/${entity.route}?limit=1`, {
        allowFailure: true,
      });
      counts.set(entity.route, response.ok ? Number(response.data.meta?.total ?? 0) : 0);
    }
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("answers 404 for an entity the dictionary does not know", async () => {
    const response = await harness.client.get("/bus/not_an_entity_at_all?limit=1", {
      allowFailure: true,
    });
    expect(response.status).toBe(404);
  });

  it("says which entity it could not find", async () => {
    const response = await harness.client.get("/bus/not_an_entity_at_all?limit=1", {
      allowFailure: true,
    });
    const body = JSON.stringify(response.data ?? "").toLowerCase();
    expect(body.includes("not_an_entity_at_all")).toBe(true);
  });

  it("refuses an anonymous caller", async () => {
    const entity = entities[0];
    if (!entity) return;
    const { HttpClient } = await import("../harness/http.ts");
    const anonymous = new HttpClient();
    const response = await anonymous.get(`/bus/${entity.route}?limit=1`, { allowFailure: true });
    expect(response.status).toBe(401);
  });

  for (const entity of entities) {
    describe(entity.name, () => {
      it("echoes the page size it was asked for", async () => {
        const response = await harness.client.get<Page>(`/bus/${entity.route}?page=1&limit=3`, {
          allowFailure: true,
        });
        expect(response.status).toBe(200);

        const size = response.data.meta?.pageSize ?? response.data.meta?.limit;
        expect(Number(size)).toBe(3);
        expect((response.data.data ?? []).length).toBeLessThanOrEqual(3);
      });

      it("reports a total consistent with what it returns", async () => {
        const response = await harness.client.get<Page>(`/bus/${entity.route}?page=1&limit=5`, {
          allowFailure: true,
        });
        expect(response.status).toBe(200);

        const total = Number(response.data.meta?.total ?? 0);
        const returned = (response.data.data ?? []).length;
        expect(total).toBeGreaterThanOrEqual(returned);
      });

      it("gives page 2 rows that page 1 did not", async () => {
        // The assertion that found the unstable sort. `created_at` is the
        // default order and a seed writes a whole table with one timestamp, so
        // without a unique tiebreaker the two pages shared a row and between
        // them missed another — a list a reader could page through and never
        // see all of.
        if ((counts.get(entity.route) ?? 0) < 4) return;

        const first = await harness.client.get<Page>(`/bus/${entity.route}?page=1&limit=2`, {
          allowFailure: true,
        });
        const second = await harness.client.get<Page>(`/bus/${entity.route}?page=2&limit=2`, {
          allowFailure: true,
        });
        if (!first.ok || !second.ok) return;

        const firstIds = new Set((first.data.data ?? []).map((row) => row.id));
        const overlap = (second.data.data ?? []).filter((row) => firstIds.has(row.id));
        expect(overlap).toEqual([]);
      });

      it("answers a page past the end with an empty list, not an error", async () => {
        const total = counts.get(entity.route) ?? 0;
        const page = Math.floor(total / 5) + 50;

        const response = await harness.client.get<Page>(
          `/bus/${entity.route}?page=${page}&limit=5`,
          { allowFailure: true }
        );
        expect(response.status).toBe(200);
        expect((response.data.data ?? []).length).toBe(0);
      });

      it("sorts ascending and descending differently", async () => {
        if ((counts.get(entity.route) ?? 0) < 3) return;
        const text = firstTextField(entity);
        if (!text) return;

        const ascending = await harness.client.get<Page>(
          `/bus/${entity.route}?limit=10&orderBy=${text.name}&orderDir=asc`,
          { allowFailure: true }
        );
        const descending = await harness.client.get<Page>(
          `/bus/${entity.route}?limit=10&orderBy=${text.name}&orderDir=desc`,
          { allowFailure: true }
        );
        if (!ascending.ok || !descending.ok) return;

        const up = (ascending.data.data ?? []).map((row) => String(row[text.name] ?? ""));
        const down = (descending.data.data ?? []).map((row) => String(row[text.name] ?? ""));
        if (up.length < 2 || down.length < 2) return;

        // Not a full sort assertion — collation is the database's business —
        // but the two orders must not be identical, which is what a sort
        // parameter silently ignored looks like.
        expect(up.join("|") === down.join("|")).toBe(false);
      });

      it("filters to rows that match", async () => {
        const text = firstTextField(entity);
        if (!text) return;

        const created = await harness.createWithParents(entity);
        const marker = created?.[text.name];
        if (!created || marker === null || marker === undefined || marker === "") return;

        const response = await harness.client.get<Page>(
          `/bus/${entity.route}?limit=25&${text.name}=${encodeURIComponent(String(marker))}`,
          { allowFailure: true }
        );
        if (!response.ok) return;

        const wrong = (response.data.data ?? []).filter(
          (row) => String(row[text.name] ?? "") !== String(marker)
        );
        expect(wrong).toEqual([]);
      });

      it("finds a record it just wrote by search", async () => {
        const text = firstTextField(entity);
        if (!text) return;

        const marker = `e2e-find-${Date.now().toString(36)}${Math.floor(Math.random() * 1e4)}`;
        const created = await harness.createWithParents(entity, { [text.name]: marker });
        if (!created) return;
        // The factory may have refused the override and fallen back; only
        // assert on a record that actually carries the marker.
        if (String(created[text.name] ?? "") !== marker) return;

        const response = await harness.client.get<Page>(
          `/bus/${entity.route}?limit=25&search=${encodeURIComponent(marker)}`,
          { allowFailure: true }
        );
        if (!response.ok) return;

        const ids = (response.data.data ?? []).map((row) => row.id);
        expect(ids.includes(created.id as string)).toBe(true);
      });

      it("refuses a malformed id rather than treating it as a filter", async () => {
        const response = await harness.client.get(`/bus/${entity.route}/not-a-uuid`, {
          allowFailure: true,
        });
        // 400 or 404 both say "no such record"; a 200 would mean the id was
        // parsed as something else entirely.
        expect(response.status).toBeGreaterThanOrEqual(400);
        expect(response.status).toBeLessThan(500);
      });

      it("survives a quote in a search term", async () => {
        // Not a claim that the driver is injectable — it parameterises — but
        // the one input a reader types by accident, and a 500 here is the
        // difference between a search box and a stack trace.
        const response = await harness.client.get(
          `/bus/${entity.route}?limit=5&search=${encodeURIComponent("' OR 1=1 --")}`,
          { allowFailure: true }
        );
        expect(response.status).toBeLessThan(500);
      });

      it("serves grid fields and form fields for the same entity", async () => {
        const grid = await harness.client.get(`/bus/${entity.route}/fields/grid`, {
          allowFailure: true,
        });
        const form = await harness.client.get(`/bus/${entity.route}/fields/form`, {
          allowFailure: true,
        });
        expect(grid.status).toBe(200);
        expect(form.status).toBe(200);
      });

      it("answers 404 for the metadata of an entity that does not exist", async () => {
        const response = await harness.client.get(`/bus/${entity.route}xyz/meta`, {
          allowFailure: true,
        });
        expect(response.status).toBe(404);
      });

      it("answers 404 rather than 500 for an absent record", async () => {
        const response = await harness.client.get(`/bus/${entity.route}/${ABSENT_ID}`, {
          allowFailure: true,
        });
        expect(response.status).toBe(404);
      });
    });
  }
});

tanstack-start-nestjs/tests/suites/02-di:
/**
 * Application Dictionary — the metadata that drives the generated UI.
 *
 * Every entity in the ERD must be registered with columns and field layouts,
 * otherwise the frontend renders an empty form for it.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import { entities, harness, writableFields } from "../harness/index.ts";

describe("application dictionary", () => {
  beforeAll(async () => {
    await harness.setup();
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("has at least one entity generated from the ERD", () => {
    expect(entities.length).toBeGreaterThan(0);
  });

  for (const entity of entities) {
    describe(entity.displayName, () => {
      it("exposes dictionary metadata", async () => {
        const response = await harness.client.get<{ columns: Array<Record<string, unknown>> }>(
          `/bus/${entity.route}/meta`
        );

        expect(response.status).toBe(200);
        expect(Array.isArray(response.data.columns)).toBe(true);
        expect(response.data.columns.length).toBeGreaterThan(0);
      });

      it("registers every ERD column in sys_column", async () => {
        const response = await harness.client.get<{
          columns: Array<{ column_name: string }>;
        }>(`/bus/${entity.route}/meta`);

        const registered = new Set(response.data.columns.map((c) => c.column_name));
        const missing = writableFields(entity)
          .map((f) => f.name)
          .filter((name) => !registered.has(name));

        expect(missing).toEqual([]);
      });

      it("returns ordered form fields", async () => {
        const response = await harness.client.get<Array<{ seq_no?: number }>>(
          `/bus/${entity.route}/fields/form`
        );

        expect(Array.isArray(response.data)).toBe(true);

        const sequences = response.data
          .map((field) => field.seq_no)
          .filter((seq): seq is number => typeof seq === "number");
        const sorted = [...sequences].sort((a, b) => a - b);
        expect(sequences).toEqual(sorted);
      });

      it("returns ordered grid fields", async () => {
        const response = await harness.client.get<Array<{ seq_no_grid?: number }>>(
          `/bus/${entity.route}/fields/grid`
        );

        expect(Array.isArray(response.data)).toBe(true);

        const sequences = response.data
          .map((field) => field.seq_no_grid)
          .filter((seq): seq is number => typeof seq === "number");
        const sorted = [...sequences].sort((a, b) => a - b);
        expect(sequences).toEqual(sorted);
      });
    });
  }
});

tanstack-start-nestjs/tests/suites/21-re:
/**
 * Every `%%report` the model declares, actually run.
 *
 * This is the only suite that executes a line of SQL the *model* authored. The
 * rest of the run drives an API the generator also wrote, so a mistake shared
 * between the two is invisible: the application agrees with itself and passes.
 * A report is different — the query is written by hand in the `.mmd` and run
 * verbatim against a schema a separate compiler emitted, and nothing type-checks
 * one against the other.
 *
 * Two readers already look at `%%report` and neither closes that gap. The
 * checker validates the directive's *shape* — that it names a query, that the
 * query reads rather than writes, that a chart declares both axes — and it
 * runs where the author is, with no database in sight. The compiler refuses a
 * non-SELECT before it can reach a seed file. Neither can tell you that
 * `bus_kyc_record.kyc_status` is spelled `status`, or that a column a migration
 * renamed still appears in a JOIN. That failure surfaces the first time
 * somebody opens the report, which on a published model is a reader, not a test.
 *
 * So: assert the model's list against `sys_report`, then run every one of them.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import { harness, HttpClient, modelReports } from "../harness/index.ts";

/** A row of `sys_report` as the list endpoint serves it — no SQL. */
interface ServedReport {
  id: string;
  name: string;
  title: string;
  entity_name?: string | null;
  table_name?: string | null;
  chart?: string | null;
  x_axis?: string | null;
  y_axis?: string | null;
  help?: string | null;
  sort_order?: number;
}

interface RunResult {
  report: ServedReport;
  columns: string[];
  rows: Array<Record<string, unknown>>;
  rowCount: number;
  truncated: boolean;
  durationMs: number;
}

const hasReports = modelReports.length > 0;

describe("reports", () => {
  let served: ServedReport[] = [];
  let byName = new Map<string, ServedReport>();

  beforeAll(async () => {
    if (!hasReports) return;
    await harness.setup();
    const response = await harness.client.get<ServedReport[]>("/sys/reports");
    expect(response.status).toBe(200);
    served = Array.isArray(response.data) ? response.data : [];
    byName = new Map(served.map((report) => [report.name, report]));
  });

  afterAll(async () => {
    if (!hasReports) return;
    await harness.teardown();
  });

  it("offers every report the model declares", async () => {
    if (!hasReports) return;
    const missing = modelReports
      .map((report) => report.name)
      .filter((name) => !byName.has(name));
    expect(missing).toEqual([]);
  });

  it("offers no report the model does not declare", async () => {
    if (!hasReports) return;
    const declared = new Set(modelReports.map((report) => report.name));
    const extra = served.map((report) => report.name).filter((name) => !declared.has(name));
    expect(extra).toEqual([]);
  });

  it("keeps each report's title and entity", async () => {
    if (!hasReports) return;
    const drifted: string[] = [];
    for (const report of modelReports) {
      const row = byName.get(report.name);
      if (!row) continue;
      if (row.title !== report.title) {
        drifted.push(`${report.name}: title "${row.title}" ≠ "${report.title}"`);
      }
      if (report.entity && (row.entity_name ?? "") !== report.entity) {
        drifted.push(`${report.name}: entity "${row.entity_name}" ≠ "${report.entity}"`);
      }
    }
    expect(drifted).toEqual([]);
  });

  /**
   * A chart with one axis renders nothing and reports no error. The checker
   * refuses that at authoring time (`EML295`); this asserts the pair survived
   * compilation and seeding, which is the half the checker cannot see.
   */
  it("carries both axes for every report drawn as a chart", async () => {
    if (!hasReports) return;
    const broken: string[] = [];
    for (const report of modelReports) {
      if (!report.chart) continue;
      const row = byName.get(report.name);
      if (!row) continue;
      if (!row.chart) broken.push(`${report.name}: chart type lost in seeding`);
      if (!row.x_axis || !row.y_axis) {
        broken.push(`${report.name}: chart with x="${row.x_axis}" y="${row.y_axis}"`);
      }
    }
    expect(broken).toEqual([]);
  });

  /**
   * The assertion this suite exists for.
   *
   * Every declared report is executed against the database this run migrated
   * and seeded. A column that does not exist, a table renamed since the query
   * was written, a JOIN across a foreign key the schema types differently —
   * each is a failing test here and nothing anywhere else.
   *
   * Zero rows is a pass. A report may legitimately ask a question this data
   * has no answer to ("encounters never billed" against a freshly seeded
   * database), and asserting on row counts would make the suite depend on
   * which sample rows the faker seed happened to write.
   */
  it("runs every declared report against the real schema", async () => {
    if (!hasReports) return;
    const failures: string[] = [];

    for (const report of modelReports) {
      if (!byName.has(report.name)) continue;
      const response = await harness.client.get<RunResult | { message?: string }>(
        `/sys/reports/${encodeURIComponent(report.name)}/run`,
        { allowFailure: true }
      );

      if (response.status !== 200) {
        const body = response.data as { message?: string };
        failures.push(`${report.name} → ${response.status}: ${body?.message ?? response.raw.slice(0, 200)}`);
        continue;
      }

      const result = response.data as RunResult;
      if (!Array.isArray(result.rows)) {
        failures.push(`${report.name}: no rows array in the result`);
        continue;
      }
      // Columns are read off the first row (so the order matches the SELECT),
      // which means a report with no rows legitimately reports none. Asserting
      // otherwise would fail on a question this data has no answer to.
      if (result.rowCount > 0 && (!Array.isArray(result.columns) || result.columns.length === 0)) {
        failures.push(`${report.name}: returned ${result.rowCount} rows and no columns`);
      }
    }

    expect(failures).toEqual([]);
  });

  /**
   * A chart plots two named result columns. If the query stops returning one
   * of them the chart renders empty and the table beside it still looks right,
   * so this is checked against the columns the query actually returned rather
   * than against the report row.
   *
   * Only where the query returned rows: the column list comes off the first
   * row, so an empty result names no columns and a missing axis cannot be
   * distinguished from no data.
   */
  it("returns the columns each chart says it plots", async () => {
    if (!hasReports) return;
    const missing: string[] = [];
    let checked = 0;
    let empty = 0;

    for (const report of modelReports) {
      if (!report.chart || !byName.has(report.name)) continue;
      const response = await harness.client.get<RunResult>(
        `/sys/reports/${encodeURIComponent(report.name)}/run`,
        { allowFailure: true }
      );
      if (response.status !== 200) continue; // already reported above
      if ((response.data?.rowCount ?? 0) === 0) {
        empty++;
        continue;
      }
      checked++;
      const columns = new Set(response.data?.columns ?? []);
      for (const axis of [report.x, report.y]) {
        if (axis && !columns.has(axis)) {
          missing.push(`${report.name}: plots "${axis}", query returns ${[...columns].join(", ")}`);
        }
      }
    }

    // Say what was covered. How much of this check actually ran depends on
    // which sample rows the seed wrote, and a check that silently covers two
    // reports out of eleven is indistinguishable from one that covers all of
    // them. Naming the number is what makes the gap visible in the log.
    console.log(`  charts: ${checked} axis-checked, ${empty} skipped (no rows to read columns from)`);

    expect(missing).toEqual([]);
  });

  it("refuses a report nobody declared", async () => {
    if (!hasReports) return;
    const response = await harness.client.get(
      "/sys/reports/no-such-report-{{project.id}}/run",
      { allowFailure: true }
    );
    expect(response.status).toBeGreaterThanOrEqual(400);
    expect(response.status).toBeLessThan(500);
  });

  it("does not serve a report's SQL to a caller", async () => {
    if (!hasReports) return;
    const first = modelReports[0];
    if (!first || !byName.has(first.name)) return;
    const response = await harness.client.get<Record<string, unknown>>(
      `/sys/reports/${encodeURIComponent(first.name)}`
    );
    expect(response.status).toBe(200);
    expect(response.data.sql_text).toBeUndefined();
    expect(response.data.sql).toBeUndefined();
  });

  it("needs a session", async () => {
    if (!hasReports) return;
    // A fresh client rather than a header on the authenticated one: the cookie
    // jar lives on the client, so clearing a header would not remove it.
    const anonymous = new HttpClient();
    const response = await anonymous.get("/sys/reports", { allowFailure: true });
    expect(response.status).toBeGreaterThanOrEqual(400);
    expect(response.status).toBeLessThan(500);
  });
});

tanstack-start-nestjs/tests/suites/10-be:
/**
 * Read performance against whatever volume the run seeded.
 *
 * Runs last, so the tables are as full as this run will make them. Each phase
 * is one query shape repeated enough times for a p99 to be an observation
 * rather than a guess, and every sample lands in the same report as the writes.
 *
 * The point is the shape of the curve, not the absolute milliseconds. A laptop
 * and a CI box will disagree about every number here; what neither can hide is
 * a phase whose cost grows in step with the row count, because that is a scan
 * where an index was expected.
 *
 * Which is why the entity benchmarked is the one with the most rows: a phase
 * measured against a hundred rows tells you nothing about a hundred thousand.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import { config, entities, firstTextField, harness, scalarFields, timed } from "../harness/index.ts";

/** Repetitions per phase. 30 is enough for a median and a believable p95. */
const REPS = Number(process.env.E2E_BENCH_REPS ?? 30);

/** Page size the phases read with — a realistic screenful, not a whole table. */
const PAGE = 25;

interface ListResponse {
  data: Array<Record<string, unknown>>;
  meta: { total: number; page?: number; limit?: number };
}

describe("read benchmark", () => {
  /** The entity with the most rows, and a text column to filter on. */
  let target: (typeof entities)[number] | null = null;
  let total = 0;
  let textField: string | null = null;
  let sortField: string | null = null;
  /** A value known to exist, so the filter phases match rather than miss. */
  let exactValue: string | null = null;

  beforeAll(async () => {
    await harness.setup();

    // Ask each entity how many rows it has and benchmark the largest. The
    // count is one request per entity and is not itself measured.
    let best = -1;
    for (const entity of entities) {
      const response = await harness.client.get<ListResponse>(
        `/bus/${entity.route}?page=1&limit=1`,
        { allowFailure: true }
      );
      if (!response.ok) continue;
      const rows = Number(response.data?.meta?.total ?? 0);
      if (rows > best) {
        best = rows;
        target = entity;
      }
    }

    total = Math.max(best, 0);
    if (!target) return;

    textField = firstTextField(target)?.name ?? null;
    sortField = scalarFields(target)[0]?.name ?? null;

    if (textField) {
      const sample = await harness.client.get<ListResponse>(
        `/bus/${target.route}?page=1&limit=1`,
        { allowFailure: true }
      );
      const value = sample.data?.data?.[0]?.[textField];
      if (typeof value === "string" && value.length > 0) exactValue = value;
    }

    console.log(
      `\n  benchmarking ${target.displayName}: ${total} rows, ${REPS} reps per phase\n`
    );
  });

  afterAll(async () => {
    await harness.teardown();
  });

  /** Run one phase `REPS` times. Skips cleanly when the data cannot support it. */
  async function phase(name: string, path: () => string): Promise<number> {
    let ok = 0;
    for (let index = 0; index < REPS; index++) {
      const response = await timed(name, () =>
        harness.client.get<ListResponse>(path(), { allowFailure: true })
      );
      if (response.ok) ok++;
    }
    return ok;
  }

  it("has a populated entity to measure", () => {
    expect(target).not.toBeNull();
    // Under `--fast` the bulk seed is skipped and only the CRUD fixtures exist.
    // The phases still run; they just describe a small table.
    expect(total).toBeGreaterThan(0);
  });

  it("list first page", async () => {
    if (!target) return;
    const ok = await phase("list first page", () => `/bus/${target!.route}?page=1&limit=${PAGE}`);
    expect(ok).toBe(REPS);
  });

  // The one phase whose work genuinely grows with the table: the last page sits
  // behind every row before it. Sublinear growth here means the pager is not
  // walking them one at a time.
  it("list deep page", async () => {
    if (!target) return;
    const lastPage = Math.max(1, Math.floor(total / PAGE));
    const ok = await phase(
      "list deep page",
      () => `/bus/${target!.route}?page=${lastPage}&limit=${PAGE}`
    );
    expect(ok).toBe(REPS);
  });

  it("count only", async () => {
    if (!target) return;
    const ok = await phase("count only", () => `/bus/${target!.route}?page=1&limit=1`);
    expect(ok).toBe(REPS);
  });

  it("sort by column", async () => {
    if (!target || !sortField) return;
    const ok = await phase(
      "sort by column",
      () => `/bus/${target!.route}?page=1&limit=${PAGE}&orderBy=${sortField}&orderDir=asc`
    );
    expect(ok).toBe(REPS);
  });

  it("filter exact", async () => {
    if (!target || !textField || !exactValue) return;
    const encoded = encodeURIComponent(exactValue);
    const ok = await phase(
      "filter exact",
      () => `/bus/${target!.route}?limit=${PAGE}&filter.${textField}=equals:${encoded}`
    );
    expect(ok).toBe(REPS);
  });

  // Contains and search are the two that cannot use a plain B-tree index, so
  // they are the ones to watch as the table grows.
  it("filter contains", async () => {
    if (!target || !textField || !exactValue) return;
    const needle = encodeURIComponent(exactValue.slice(0, Math.min(5, exactValue.length)));
    const ok = await phase(
      "filter contains",
      () => `/bus/${target!.route}?limit=${PAGE}&filter.${textField}=contains:${needle}`
    );
    expect(ok).toBe(REPS);
  });

  it("search substring", async () => {
    if (!target || !exactValue) return;
    const needle = encodeURIComponent(exactValue.slice(0, Math.min(5, exactValue.length)));
    const ok = await phase(
      "search substring",
      () => `/bus/${target!.route}?limit=${PAGE}&search=${needle}`
    );
    expect(ok).toBe(REPS);
  });

  it("records the volume it measured", () => {
    // Printed rather than asserted: the number is the run's context, and
    // failing on it would make a small run look broken.
    console.log(`  measured against ${total} ${target?.displayName ?? "?"} rows`);
    expect(config.recordsPerEntity).toBeGreaterThan(0);
  });
});

tanstack-start-nestjs/tests/suites/14-va:
/**
 * What the API refuses, and with which status.
 *
 * The generated backend validates in three places — the dictionary's own rules
 * (`is_mandatory`, `field_length`, the reference type), the model's compiled
 * business rules, and the database's constraints — and a reader only ever sees
 * the status code. So that is what this asserts: a bad write is refused, and
 * refused as the thing it is. A unique collision answering 400 instead of 409
 * is not a cosmetic difference; it is the difference between a client that can
 * retry with a new value and one that cannot tell what went wrong.
 *
 * Written per entity, from the dictionary the application serves, so it holds
 * for whatever the model declared rather than for a shape assumed here.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import {
  entities,
  firstTextField,
  harness,
  scalarFields,
  writableFields,
} from "../harness/index.ts";

interface FormField {
  column_name: string;
  is_mandatory?: boolean;
  field_length?: number | null;
  sys_reference_id?: number;
  default_value?: string | null;
}

/** A uuid that is well-formed and cannot exist. */
const ABSENT_ID = "00000000-0000-0000-0000-000000000000";

describe("validation", () => {
  /** route → the dictionary's form fields, which is what the server validates against. */
  const fieldsByRoute = new Map<string, FormField[]>();

  beforeAll(async () => {
    await harness.setup();
    for (const entity of entities) {
      const response = await harness.client.get<FormField[]>(
        `/bus/${entity.route}/fields/form?includeHidden=true`,
        { allowFailure: true }
      );
      if (response.ok) fieldsByRoute.set(entity.route, response.data ?? []);
    }
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("serves form metadata for every entity", () => {
    const missing = entities.filter((entity) => !fieldsByRoute.has(entity.route)).map((e) => e.route);
    expect(missing).toEqual([]);
  });

  for (const entity of entities) {
    describe(entity.name, () => {
      /** The mandatory column a test can leave out — one with no default to fall back on. */
      const droppable = (): FormField | undefined =>
        (fieldsByRoute.get(entity.route) ?? []).find(
          (field) =>
            field.is_mandatory === true &&
            !field.default_value &&
            field.column_name !== "id" &&
            writableFields(entity).some((writable) => writable.name === field.column_name)
        );

      it("refuses an empty payload", async () => {
        const required = (fieldsByRoute.get(entity.route) ?? []).filter(
          (field) => field.is_mandatory && !field.default_value && field.column_name !== "id"
        );
        // An entity with nothing mandatory legitimately accepts `{}`.
        if (required.length === 0) return;

        const response = await harness.client.post(`/bus/${entity.route}`, {}, {
          allowFailure: true,
        });
        if (response.ok) {
          const id = (response.data as { id?: string } | undefined)?.id;
          if (id) harness.track(entity.route, id);
        }
        expect(response.status).toBe(400);
      });

      it("refuses a payload missing a mandatory column", async () => {
        const field = droppable();
        if (!field) return;

        const payload = await harness.buildValidRecord(entity);
        delete payload[field.column_name];

        const response = await harness.client.post(`/bus/${entity.route}`, payload, {
          allowFailure: true,
        });
        if (response.ok) {
          const id = (response.data as { id?: string } | undefined)?.id;
          if (id) harness.track(entity.route, id);
        }
        expect(response.status).toBe(400);
      });

      it("names the column it refused", async () => {
        const field = droppable();
        if (!field) return;

        const payload = await harness.buildValidRecord(entity);
        delete payload[field.column_name];

        const response = await harness.client.post(`/bus/${entity.route}`, payload, {
          allowFailure: true,
        });
        if (response.ok) {
          const id = (response.data as { id?: string } | undefined)?.id;
          if (id) harness.track(entity.route, id);
          return;
        }

        // A 400 that does not say which field is a dead end for a form trying
        // to put the message beside the right input.
        const body = JSON.stringify(response.data ?? "").toLowerCase();
        expect(body.includes(field.column_name.toLowerCase())).toBe(true);
      });

      it("refuses a string longer than the column holds", async () => {
        const limited = (fieldsByRoute.get(entity.route) ?? []).find(
          (field) =>
            typeof field.field_length === "number" &&
            field.field_length > 0 &&
            field.field_length < 4000 &&
            scalarFields(entity).some(
              (scalar) =>
                scalar.name === field.column_name &&
                (scalar.type === "string" || scalar.type === "text")
            )
        );
        if (!limited || typeof limited.field_length !== "number") return;

        const payload = await harness.buildValidRecord(entity, {
          [limited.column_name]: "x".repeat(limited.field_length + 50),
        });
        const response = await harness.client.post(`/bus/${entity.route}`, payload, {
          allowFailure: true,
        });
        if (response.ok) {
          const id = (response.data as { id?: string } | undefined)?.id;
          if (id) harness.track(entity.route, id);
        }
        expect(response.status).toBeGreaterThanOrEqual(400);
      });

      it("refuses a foreign key pointing at nothing", async () => {
        const fk = writableFields(entity).find(
          (field) => field.isForeignKey || field.name.endsWith("_id")
        );
        if (!fk) return;
        // A reference to an entity the model never declares has no table to
        // check against; the schema carries no constraint for it by design.
        if (fk.isForeignKey && !harness.resolveParentEntity(fk.name)) return;

        const payload = await harness.buildValidRecord(entity, { [fk.name]: ABSENT_ID });
        const response = await harness.client.post(`/bus/${entity.route}`, payload, {
          allowFailure: true,
        });
        if (response.ok) {
          const id = (response.data as { id?: string } | undefined)?.id;
          if (id) harness.track(entity.route, id);
        }
        expect(response.status).toBeGreaterThanOrEqual(400);
      });

      it("answers 409 on a unique collision", async () => {
        const unique = writableFields(entity).find(
          (field) => field.unique && field.name !== "id" && field.type === "string"
        );
        if (!unique) return;

        const first = await harness.createWithParents(entity);
        if (!first) return;

        const taken = first[unique.name];
        if (taken === null || taken === undefined || taken === "") return;

        const payload = await harness.buildValidRecord(entity, { [unique.name]: taken });
        const response = await harness.client.post(`/bus/${entity.route}`, payload, {
          allowFailure: true,
        });
        if (response.ok) {
          const id = (response.data as { id?: string } | undefined)?.id;
          if (id) harness.track(entity.route, id);
        }
        expect(response.status).toBe(409);
      });

      it("answers 404 for a record that does not exist", async () => {
        const response = await harness.client.get(`/bus/${entity.route}/${ABSENT_ID}`, {
          allowFailure: true,
        });
        expect(response.status).toBe(404);
      });

      it("refuses an update to a record that does not exist", async () => {
        const text = firstTextField(entity);
        const patch = text ? { [text.name]: "e2e-absent" } : {};
        const response = await harness.client.patch(`/bus/${entity.route}/${ABSENT_ID}`, patch, {
          allowFailure: true,
        });
        expect(response.status).toBeGreaterThanOrEqual(400);
      });

      it("ignores or refuses a client-supplied server-managed column", async () => {
        const created = await harness.createWithParents(entity);
        if (!created) return;

        const id = created.id as string;
        const before = created.version;

        // `version` is the server's to move. A client that can set it can
        // defeat the optimistic-concurrency check for everyone else.
        const response = await harness.client.patch(
          `/bus/${entity.route}/${id}`,
          { version: 9999 },
          { allowFailure: true }
        );

        if (response.ok) {
          const after = await harness.client.get<Record<string, unknown>>(
            `/bus/${entity.route}/${id}`,
            { allowFailure: true }
          );
          if (after.ok) expect(after.data.version).not.toBe(9999);
        } else {
          expect(response.status).toBeGreaterThanOrEqual(400);
        }
        expect(before === undefined || typeof before === "number").toBe(true);
      });
    });
  }
});

tanstack-start-nestjs/tests/suites/12-ac:
/**
 * `%%rbac` — driven as each role it names.
 *
 * The model says which roles may read, create, update and delete each entity.
 * The guard reads `sys_operation_access` and refuses the rest. Between those
 * two there are three ways to be wrong, and this suite is written to catch all
 * three:
 *
 *   - the seed dropped a rule, so an entity nobody should reach is open;
 *   - the guard refuses a role the model admits, so a role cannot do its job;
 *   - the *navigation* is unscoped, so every role is offered every entity and
 *     the refusal only arrives after the click.
 *
 * The third is the one a dictionary test cannot see and the reason this suite
 * exists. `/sys/categories/with-entities` and `/sys/tables` are what the
 * dashboard is built from; if they answer with entities the caller may not
 * read, the application offers nine doors and opens four, and the reader
 * cannot tell a permission from a bug.
 *
 * Every assertion compares against `harness/access.ts` — the compiled
 * directives — not against the rows the same generator seeded.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import {
  config,
  entities,
  harness,
  HttpClient,
  login,
  modelAllows,
  rbacRules,
  readRestrictedRoutes,
  restrictedAccounts,
  roleAccounts,
  rolesFor,
  sameRole,
  type RoleAccount,
} from "../harness/index.ts";

/** Nothing to assert on a model that declares no restrictions. */
const declared = rbacRules.length > 0 && roleAccounts.length > 0;

interface CategoryGroup {
  name?: string;
  entities?: Array<{ table_name?: string; name?: string }>;
}

function rows<T>(body: unknown): T[] {
  if (Array.isArray(body)) return body as T[];
  if (body && typeof body === "object") {
    const record = body as Record<string, unknown>;
    if (Array.isArray(record.data)) return record.data as T[];
  }
  return [];
}

/** A signed-in client per role, built once — logging in per assertion is slow and pointless. */
const clients = new Map<string, HttpClient>();

async function clientFor(account: RoleAccount): Promise<HttpClient | null> {
  const cached = clients.get(account.email);
  if (cached) return cached;
  const client = new HttpClient();
  try {
    await login(client, account.email, config.admin.password);
  } catch {
    return null;
  }
  clients.set(account.email, client);
  return client;
}

describe("access control — %%rbac, as each role", () => {
  /** Route → an id that exists, so update and delete have something to aim at. */
  const sampleIds = new Map<string, string>();

  beforeAll(async () => {
    if (!declared) return;
    await harness.setup();

    for (const account of roleAccounts) await clientFor(account);

    for (const route of new Set(rbacRules.map((rule) => rule.route))) {
      const entity = entities.find((item) => item.route === route);
      if (!entity) continue;
      const id = await harness.anyRecordId(entity);
      if (id) sampleIds.set(route, id);
    }
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it.skipIf(!declared)("the model declares at least one restriction", () => {
    expect(rbacRules.length).toBeGreaterThan(0);
  });

  it.skipIf(!declared)("every role the directives name has a seeded account", () => {
    const named = new Set<string>();
    for (const rule of rbacRules) for (const role of rule.roles) named.add(role);

    const missing = [...named].filter(
      (role) =>
        !roleAccounts.some(
          (account) => sameRole(account.declaredAs, role) || sameRole(account.roleName, role)
        )
    );
    expect(missing).toEqual([]);
  });

  it.skipIf(!declared)("every seeded role account can sign in", () => {
    const failed = roleAccounts.filter((account) => !clients.has(account.email)).map((a) => a.email);
    expect(failed).toEqual([]);
  });

  // ── Reads, per role, per restricted entity ────────────────────────────────
  //
  // Split from the write operations because a read is the one a reader
  // *notices*: it decides which screens exist for them at all.

  describe("reads", () => {
    for (const account of restrictedAccounts()) {
      for (const route of readRestrictedRoutes()) {
        const allowed = modelAllows(account, route, "read");
        it.skipIf(!declared)(
          `${account.roleName} ${allowed ? "may" : "may not"} read ${route}`,
          async () => {
            const client = await clientFor(account);
            expect(client).toBeTruthy();
            const response = await client!.get(`/bus/${route}?limit=1`, { allowFailure: true });
            if (allowed) {
              expect(response.status).toBe(200);
            } else {
              expect(response.status).toBe(403);
            }
          }
        );
      }
    }
  });

  // ── Writes, per role, per restricted pair ─────────────────────────────────
  //
  // Only the refusals are asserted. A *permitted* create needs a payload that
  // satisfies every rule the model declares for that entity, which is the CRUD
  // suite's job; what belongs here is that the roles the model excludes are
  // actually excluded, and that the refusal is a 403 rather than a 400 that
  // happens to look like one.

  describe("writes the model forbids", () => {
    for (const account of restrictedAccounts()) {
      for (const rule of rbacRules) {
        if (rule.operation === "read") continue;
        if (modelAllows(account, rule.route, rule.operation)) continue;

        it.skipIf(!declared)(
          `${account.roleName} may not ${rule.operation} ${rule.route}`,
          async () => {
            const client = await clientFor(account);
            expect(client).toBeTruthy();

            const id = sampleIds.get(rule.route);
            const response =
              rule.operation === "create"
                ? await client!.post(`/bus/${rule.route}`, {}, { allowFailure: true })
                : rule.operation === "update"
                  ? await client!.patch(`/bus/${rule.route}/${id ?? "00000000-0000-0000-0000-000000000000"}`, { }, { allowFailure: true })
                  : await client!.delete(`/bus/${rule.route}/${id ?? "00000000-0000-0000-0000-000000000000"}`, { allowFailure: true });

            expect(response.status).toBe(403);
          }
        );
      }
    }
  });

  // ── The navigation the dashboard is built from ────────────────────────────

  describe("navigation is scoped to what the role may read", () => {
    for (const account of restrictedAccounts()) {
      it.skipIf(!declared)(
        `/sys/categories/with-entities offers ${account.roleName} nothing it may not read`,
        async () => {
          const client = await clientFor(account);
          expect(client).toBeTruthy();

          const response = await client!.get("/sys/categories/with-entities", {
            allowFailure: true,
          });
          expect(response.status).toBe(200);

          const offered = rows<CategoryGroup>(response.data)
            .flatMap((group) => group.entities ?? [])
            .map((table) => String(table.table_name ?? ""))
            .filter(Boolean);

          const forbidden = offered.filter((tableName) => {
            const entity = entities.find((item) => item.tableName === tableName);
            if (!entity) return false;
            return !modelAllows(account, entity.route, "read");
          });
          expect(forbidden).toEqual([]);
        }
      );

      it.skipIf(!declared)(
        `/sys/tables offers ${account.roleName} nothing it may not read`,
        async () => {
          const client = await clientFor(account);
          expect(client).toBeTruthy();

          const response = await client!.get("/sys/tables?prefix=bus_&limit=500", {
            allowFailure: true,
          });
          expect(response.status).toBe(200);

          const forbidden = rows<{ table_name?: string }>(response.data)
            .map((table) => String(table.table_name ?? ""))
            .filter((tableName) => {
              const entity = entities.find((item) => item.tableName === tableName);
              if (!entity) return false;
              return !modelAllows(account, entity.route, "read");
            });
          expect(forbidden).toEqual([]);
        }
      );

      it.skipIf(!declared)(
        `${account.roleName} is offered every entity it may read`,
        async () => {
          const client = await clientFor(account);
          expect(client).toBeTruthy();

          const response = await client!.get("/sys/categories/with-entities", {
            allowFailure: true,
          });
          expect(response.status).toBe(200);

          const offered = new Set(
            rows<CategoryGroup>(response.data)
              .flatMap((group) => group.entities ?? [])
              .map((table) => String(table.table_name ?? ""))
          );

          // Scoping too far is the mirror-image bug, and it hides a screen the
          // role is meant to work in — the sort of thing that reads as "the
          // feature is missing" rather than as a permission.
          //
          // A line item is the one entity legitimately absent here. `%%entity
          // <Child> parent: <Parent>` gives it no window and no dashboard card
          // on purpose: it is reached by opening a parent record, and a card
          // listing every invoice line ever written is the screen the directive
          // exists to prevent. `parentEntity` comes from the model rather than
          // from the dictionary this generator wrote, so this asks the same
          // question the model answered.
          const missing = entities
            .filter((entity) => !entity.parentEntity)
            .filter((entity) => modelAllows(account, entity.route, "read"))
            .map((entity) => entity.tableName)
            .filter((tableName) => !offered.has(tableName));
          expect(missing).toEqual([]);
        }
      );
    }
  });

  // ── The administrator, as the control ─────────────────────────────────────

  describe("the administrator", () => {
    it.skipIf(!declared)("reads every restricted entity", async () => {
      const admin = roleAccounts.find((account) => account.isAdmin);
      expect(admin).toBeTruthy();

      const client = await clientFor(admin!);
      expect(client).toBeTruthy();

      const refused: string[] = [];
      for (const route of readRestrictedRoutes()) {
        const response = await client!.get(`/bus/${route}?limit=1`, { allowFailure: true });
        if (response.status !== 200) refused.push(`${route} → ${response.status}`);
      }
      expect(refused).toEqual([]);
    });

    it.skipIf(!declared)("is offered every navigable entity in the navigation", async () => {
      const admin = roleAccounts.find((account) => account.isAdmin);
      const client = await clientFor(admin!);
      expect(client).toBeTruthy();

      const response = await client!.get("/sys/categories/with-entities", { allowFailure: true });
      expect(response.status).toBe(200);

      const offered = new Set(
        rows<CategoryGroup>(response.data)
          .flatMap((group) => group.entities ?? [])
          .map((table) => String(table.table_name ?? ""))
      );
      // Line items excluded for the same reason as above: the administrator is
      // offered every entity that has a window, and a child deliberately has
      // none. Asserting otherwise would demand the card the directive removes.
      const missing = entities
        .filter((entity) => !entity.parentEntity)
        .map((entity) => entity.tableName)
        .filter((name) => !offered.has(name));
      expect(missing).toEqual([]);
    });
  });

  // ── An anonymous caller ───────────────────────────────────────────────────

  it.skipIf(!declared)("refuses an anonymous caller every restricted entity", async () => {
    const anonymous = new HttpClient();
    const allowed: string[] = [];
    for (const route of readRestrictedRoutes()) {
      const response = await anonymous.get(`/bus/${route}?limit=1`, { allowFailure: true });
      if (response.status === 200) allowed.push(route);
    }
    expect(allowed).toEqual([]);
  });

  it.skipIf(!declared)("names the roles it requires when it refuses", async () => {
    const denial = rbacRules.find(
      (rule) => rule.operation === "read" && restrictedAccounts().some((a) => !modelAllows(a, rule.route, "read"))
    );
    if (!denial) return;

    const account = restrictedAccounts().find((a) => !modelAllows(a, denial.route, "read"));
    const client = await clientFor(account!);
    expect(client).toBeTruthy();

    const response = await client!.get(`/bus/${denial.route}?limit=1`, { allowFailure: true });
    expect(response.status).toBe(403);

    // A refusal that does not say what would have been enough is a dead end for
    // whoever has to configure the role.
    const message = JSON.stringify(response.data ?? "");
    const named = rolesFor(denial.route, "read") ?? [];
    expect(named.some((role) => message.toLowerCase().includes(role.toLowerCase()))).toBe(true);
  });
});

tanstack-start-nestjs/tests/suites/06c-s:
/**
 * A button press is two transactions, and a workflow bound to the status it
 * moves to decides whether the second one commits.
 *
 * Pressing a move with the form's values (`data`) first saves them — the record
 * stays in the status it is in — and then runs the move: the workflows bound to
 * the status it reaches (`operation: ENTER:<STATE>`), and, if every one succeeds,
 * the status write. This suite holds the API to the part that is easy to get
 * wrong, because every half of it looks fine from the outside:
 *
 *   - a bound workflow that fails refuses the move with 422 `WORKFLOW_FAILED`,
 *     naming the workflow and the half of the press it failed in
 *     (`details.phase: "workflow"`), and the status does not move;
 *   - what was typed is kept: the save committed first, so the value is on the
 *     record and the version moved on by exactly that save;
 *   - the failed run is recorded where Run History lists it — the rollback took
 *     the run row with it, so it is written back afterwards;
 *   - fixing the cause and pressing again moves the record, and the stale
 *     message goes with it;
 *   - a workflow bound to a status is never run by a plain save.
 *
 * The workflow it binds is built here through the API, from the status the
 * model's own machine draws, and removed again — so a model with no status
 * machine has nothing to drive and says so.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import {
  getEntity,
  firstTextField,
  harness,
  stateMachines,
  successorsOf,
} from "../harness/index.ts";

interface Row {
  id?: string;
  version?: number;
  doc_status_message?: string | null;
  [column: string]: unknown;
}

interface Refusal {
  statusCode?: number;
  message?: string;
  details?: {
    code?: string;
    phase?: string;
    workflow?: string;
    reason?: string;
    saved?: boolean;
    version?: number;
    to?: string;
  };
}

interface DefinitionRow {
  id?: string;
}

interface RunRow {
  workflow_name?: string;
  operation?: string;
  status?: string;
}

const RUN = Date.now().toString(36);

/**
 * A designer workflow that always fails: it creates a row with a column nothing
 * declares. It is bound to `status`, so only a move into it runs it.
 */
function breaker(entity: string, status: string, name: string) {
  const mermaid = [
    "flowchart TD",
    "    start([Moved]) --> s1[Create a row that cannot exist]",
    "    s1 --> done([Response])",
    `%%workflow name: ${name}`,
    `%%hook afterUpdate on ${entity}`,
    "%%step s1 type: CreateEntity",
    `%%step s1 entity: ${entity}`,
    '%%step s1 fields: {"e2e_no_such_column":"x"}',
  ].join("\n");
  return { name, kind: "automation", operation: `ENTER:${status.toUpperCase()}`, mermaid };
}

describe("a workflow bound to a status", () => {
  beforeAll(async () => {
    await harness.setup();
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("has a state machine to drive, or declares none", () => {
    if (stateMachines.length === 0) {
      console.log("  (no %%workflow … kind: state in this model — nothing to bind a status to)");
    }
    expect(Array.isArray(stateMachines)).toBe(true);
  });

  for (const machine of stateMachines.slice(0, 2)) {
    const entity = getEntity(machine.entity);
    if (!entity) continue;

    describe(`${machine.entity}`, () => {
      it("keeps the typing, the status and the reason when a bound workflow fails", async () => {
        const record = await harness.createWithParents(entity);
        if (!record?.id) return;
        const id = String(record.id);
        const route = `/bus/${entity.route}/${id}`;

        const read = await harness.client.get<Row>(route);
        const at = String(read.data?.[machine.statusField] ?? "");
        if (!at || at === "error") return;
        const next = successorsOf(machine, at)[0];
        if (!next) return;

        const name = `e2e-bound-${RUN}-${machine.entity}`;
        const created = await harness.client.post<DefinitionRow>(
          "/workflow-definitions",
          { ...breaker(entity.name, next, name), entityName: machine.tableName },
          { allowFailure: true }
        );
        // A model whose entity names cannot be bound this way is not the subject.
        if (!created.ok || !created.data?.id) return;
        const definitionId = String(created.data.id);

        try {
          const text = firstTextField(entity);
          const typed = `e2e-press-${RUN}`;
          const version = Number(read.data?.version);
          const refused = await harness.client.post<Refusal>(
            `${route}/transition`,
            { to: next, ...(text ? { data: { [text.name]: typed } } : {}) },
            { allowFailure: true, headers: { "If-Match": `"${version}"` } }
          );
          // A rule of the model may refuse the move before the workflow runs (422
          // RULE_REFUSED) — the model working, and not what is under test.
          if (refused.status === 422 && refused.data?.details?.code !== "WORKFLOW_FAILED") return;
          // Nor is a save the model's own rules would not accept.
          if (refused.data?.details?.phase === "save") return;

          expect(refused.status).toBe(422);
          expect(refused.data?.details?.code).toBe("WORKFLOW_FAILED");
          expect(refused.data?.details?.workflow).toBe(name);
          expect(refused.data?.details?.phase).toBe("workflow");
          expect(refused.data?.details?.saved).toBe(true);

          const after = await harness.client.get<Row>(route);
          // The move was undone ...
          expect(String(after.data?.[machine.statusField])).toBe(at);
          expect(after.data?.doc_status_message).toBeTruthy();
          // ... the save was not.
          if (text) {
            expect(after.data?.[text.name]).toBe(typed);
            expect(Number(after.data?.version)).toBe(version + 1);
            expect(refused.data?.details?.version).toBe(version + 1);
          }

          // The failed run is in Run History, written back after the rollback.
          const runs = await harness.client.get<{ items?: RunRow[] } | RunRow[]>(
            "/workflows/runs?limit=100",
            { allowFailure: true }
          );
          const listed = Array.isArray(runs.data) ? runs.data : (runs.data?.items ?? []);
          expect(
            listed.some(
              (run) =>
                run.workflow_name === name &&
                run.status === "error" &&
                run.operation === `ENTER:${next.toUpperCase()}`
            )
          ).toBe(true);
        } finally {
          await harness.client.delete(`/workflow-definitions/${definitionId}`, {
            allowFailure: true,
          });
        }

        // The cause is gone: the same press moves the record, and the reason with it.
        const again = await harness.client.get<Row>(route);
        const moved = await harness.client.post<Row>(
          `${route}/transition`,
          { to: next },
          { allowFailure: true, headers: { "If-Match": `"${Number(again.data?.version)}"` } }
        );
        if (moved.status === 422) return;
        expect(moved.status).toBe(200);
        expect(String(moved.data?.[machine.statusField])).toBe(next);
        expect(moved.data?.doc_status_message ?? null).toBeNull();
      });

      it("refuses a binding to a state the machine does not draw", async () => {
        const refused = await harness.client.post<Refusal>(
          "/workflow-definitions",
          {
            ...breaker(entity.name, "e2e_no_such_state", `e2e-unbound-${RUN}-${machine.entity}`),
            entityName: machine.tableName,
          },
          { allowFailure: true }
        );
        expect(refused.status).toBe(400);
        expect(String(refused.data?.message)).toContain("does not draw");
      });
    });
  }
});

tanstack-start-nestjs/tests/suites/23-wo:
/**
 * What the rules & workflows screen writes: the API behind it.
 *
 * The screen is the modelling tool's own `LogicWorkbench`; in a running application its
 * host saves through `/rules` and `/workflow-definitions`. A lifecycle or process is an
 * automation row; a status flow is a `state` row the application follows in place of the
 * model's flow for that record type (`GET /lifecycles` says which it follows), and whose
 * definition the executor must never try to run. This suite holds the API to that.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import { harness } from "../harness/index.ts";

interface Definition {
  id: string;
  name: string;
  kind: string;
  entity_name: string;
  is_active: boolean;
  mermaid_code?: string | null;
  bpmn_xml?: string | null;
}

interface Edges {
  data?: Record<string, Array<{ statusField: string; from: string; to: string }>>;
}

interface Flow {
  column: string;
  hasMachine: boolean;
  afterDraft: string;
  terminal: string[];
  edges: Array<{ from: string; to: string; event: string; label: string }>;
  values: string[];
}

const token = Date.now().toString(36);
const slug = token.replace(/[^a-z0-9]/gi, "").toLowerCase();
// A record type the model gave no status flow: there is no column to keep one in.
const unknownEntity = `E2eMachine${slug}`;
// The table of that record type, for what this suite files without a flow.
const scratchTable = `bus_e2e_machine${slug}`;
// The state this suite adds, and takes away again.
const held = `e2e_hold_${slug}`;

/** A flow as a diagram, the way the editor writes one. */
const diagramOf = (flow: Flow, ...extra: string[]) =>
  [
    "stateDiagram-v2",
    `  [*] --> ${flow.afterDraft}`,
    ...flow.edges.map((edge) => `  ${edge.from} --> ${edge.to}${edge.event ? ` : ${edge.event}` : ""}`),
    ...extra.map((line) => `  ${line}`),
    ...flow.terminal.map((state) => `  ${state} --> [*]`),
  ].join("\n");

describe("rules & workflows API", () => {
  const created: string[] = [];
  let table = "";
  let original: Flow | undefined;

  beforeAll(async () => {
    await harness.setup();
    // A table with a flow from the model that nobody has redrawn yet.
    const flows = (await harness.client.get<Record<string, Flow>>("/lifecycles")).data ?? {};
    const stored = await harness.client.get<{ items: Definition[] }>("/workflow-definitions?kind=state&limit=200");
    const redrawn = new Set((stored.data.items ?? []).map((item) => item.entity_name));
    table = Object.keys(flows).find((name) => flows[name]?.hasMachine && !redrawn.has(name)) ?? "";
    original = flows[table];
  });

  afterAll(async () => {
    for (const id of created) {
      await harness.client.delete(`/workflow-definitions/${id}`, { allowFailure: true });
    }
    await harness.teardown();
  });

  const edgesOf = async () => {
    const response = await harness.client.get<Edges & Record<string, unknown>>(
      `/workflows/transitions?table=${table}`
    );
    const body = response.data as unknown as { byTable?: Record<string, unknown[]> } & Edges;
    return ((body.byTable ?? body.data ?? {})[table] ?? []) as Array<{ from: string; to: string }>;
  };
  const flowOf = async () => (await harness.client.get<Record<string, Flow>>("/lifecycles")).data?.[table];

  it("refuses a status flow for a record type the model gave none", async () => {
    const refused = await harness.client.post<{ message?: string }>(
      "/workflow-definitions",
      {
        kind: "state",
        name: `Lifecycle ${token}`,
        entityName: unknownEntity,
        mermaid: "stateDiagram-v2\n  [*] --> open\n  open --> [*]",
      },
      { allowFailure: true }
    );
    expect(refused.status).toBe(400);
  });

  it("runs a redrawn flow in place of the model's", async () => {
    if (!original) return;
    const made = await harness.client.post<Definition>("/workflow-definitions", {
      kind: "state",
      name: `Lifecycle ${token}`,
      entityName: table,
      mermaid: diagramOf(
        original,
        `${original.afterDraft} --> ${held} : e2e hold`,
        `${held} --> ${original.afterDraft} : e2e resume`
      ),
    });
    expect(made.ok).toBe(true);
    created.push(made.data.id);
    expect(made.data.kind).toBe("state");
    // A flow is followed, not run: the executor has nothing to start.
    expect(made.data.bpmn_xml ?? null).toBeNull();

    const flow = await flowOf();
    expect(flow?.values).toContain(held);
    expect(flow?.edges.some((edge) => edge.event === "e2e_hold" && edge.to === held)).toBe(true);
    expect((await edgesOf()).some((edge) => edge.from === held)).toBe(true);
  });

  it("keeps a status flow out of the automation listing", async () => {
    const listed = await harness.client.get<{ items: Definition[] }>(
      "/workflow-definitions?kind=automation&limit=200"
    );
    expect(listed.data.items.some((item) => item.entity_name === table && item.kind === "state")).toBe(false);
  });

  it("refuses a second flow for the same record type", async () => {
    if (!original) return;
    const again = await harness.client.post<{ message?: string }>(
      "/workflow-definitions",
      { kind: "state", name: `Second ${token}`, entityName: table, mermaid: diagramOf(original) },
      { allowFailure: true }
    );
    expect(again.status).toBe(400);
  });

  it("puts the model's flow back when the redrawn one is removed", async () => {
    const id = created[0];
    if (!id || !original) return;
    const removed = await harness.client.delete(`/workflow-definitions/${id}`);
    expect(removed.ok).toBe(true);
    created.length = 0;
    expect(await flowOf()).toEqual(original);
    expect((await edgesOf()).some((edge) => edge.from === held)).toBe(false);
  });

  it("keeps a rule's title beside the identifier it is filed under", async () => {
    const jdm = JSON.stringify({
      hitPolicy: "first",
      inputs: [{ id: "i1", name: "status", field: "status" }],
      outputs: [{ id: "o1", name: "Output", field: "action" }],
      rules: [{ _id: "r1", i1: "", o1: "allow" }],
    });
    const made = await harness.client.post<{ id: string; title?: string; ruleName: string }>(
      "/rules",
      {
        entityName: scratchTable,
        ruleName: `titled${token.replace(/[^a-z0-9]/gi, "")}`,
        operation: "CREATE",
        title: "A rule with words",
        jdmContent: jdm,
      },
      { allowFailure: true }
    );
    if (!made.ok) return; // the model's own rules may refuse this entity; the title is what is held here
    expect(made.data.title).toBe("A rule with words");
    const renamed = await harness.client.put<{ title?: string }>(`/rules/${made.data.id}`, {
      title: "Another way to say it",
    });
    expect(renamed.data.title).toBe("Another way to say it");
    // This entity's rules only: the unfiltered list is capped at 200 and an
    // installation that has been tested a few times holds more than that, so
    // whether the new rule was on the page depended on the order it came back in.
    const listed = await harness.client.get<Array<{ id: string; title?: string }> | { rules?: Array<{ id: string; title?: string }> }>(`/rules?entityName=${encodeURIComponent(scratchTable)}&limit=200`);
    const rows = Array.isArray(listed.data) ? listed.data : (listed.data.rules ?? []);
    expect(rows.find((row) => row.id === made.data.id)?.title).toBe("Another way to say it");
    await harness.client.delete(`/rules/${made.data.id}`, { allowFailure: true });
    await harness.client.delete(`/rules/${made.data.id}?permanent=true`, { allowFailure: true });
  });

  it("stores a process as an automation, compiled for the engine", async () => {
    const made = await harness.client.post<Definition>("/workflow-definitions", {
      kind: "automation",
      name: `Process ${token}`,
      entityName: unknownEntity,
      operation: "CREATE",
      triggerType: "rule",
      isActive: false,
      mermaid: [
        "flowchart TD",
        "%%workflow Process kind: saga entity: " + unknownEntity + " trigger: rule operation: CREATE",
        "Start([Start]) --> s1[Wait]",
        "%%step s1 type: Formula operation: set left: 1 as: x",
        "s1 --> End([End])",
      ].join("\n"),
    });
    expect(made.ok).toBe(true);
    created.push(made.data.id);
    expect(made.data.kind).toBe("automation");
    expect(made.data.mermaid_code).toContain("%%step s1");
  });
});

tanstack-start-nestjs/tests/suites/13-en:
/**
 * Enums — the model's word against the data and the API.
 *
 * `02c` already checks that the dropdown offers what the model declares. This
 * suite checks the two things either side of that: the rows *in* the column,
 * and whether the API will accept something the model never named.
 *
 * Both were wrong at once and neither was visible from a dropdown. Every
 * enum-bound column was seeded from one hard-coded vocabulary — `Active`,
 * `Pending`, `In Progress`, `Completed` — whatever the model declared, so a
 * `%%enum MemberStatus: active, lapsed, suspended` column held four values none
 * of which the dictionary offers, the control cannot select, and no state
 * machine has an edge out of. The dropdown was right the whole time; the data
 * under it was not.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import { entities, harness, modelEnums, writableFields } from "../harness/index.ts";

interface FormField {
  column_name: string;
  sys_reference_id?: number;
  options?: Array<{ value: string; label: string }> | null;
}

interface Row {
  [column: string]: unknown;
}

function rows<T>(body: unknown): T[] {
  if (Array.isArray(body)) return body as T[];
  if (body && typeof body === "object") {
    const record = body as Record<string, unknown>;
    if (Array.isArray(record.data)) return record.data as T[];
  }
  return [];
}

/** entity route + column → the enum the model bound to it. */
interface BoundColumn {
  route: string;
  entityName: string;
  column: string;
  enumName: string;
  values: string[];
  referenceId: number;
}

const hasEnums = modelEnums.length > 0;

describe("enum integrity", () => {
  /** Columns the *application* says are bound to a model enum. */
  const bound: BoundColumn[] = [];

  beforeAll(async () => {
    if (!hasEnums) return;
    await harness.setup();

    for (const entity of entities) {
      // The grid as well as the form: a state field is never a form input (it
      // is shown read-only in the record's header) but is always a grid column.
      const [response, grid] = await Promise.all([
        harness.client.get<FormField[]>(`/bus/${entity.route}/fields/form?includeHidden=true`, {
          allowFailure: true,
        }),
        harness.client.get<FormField[]>(`/bus/${entity.route}/fields/grid`, { allowFailure: true }),
      ]);
      if (!response.ok) continue;

      const fields = [...(response.data ?? [])];
      for (const field of grid.ok ? (grid.data ?? []) : []) {
        if (!fields.some((known) => known.column_name === field.column_name)) fields.push(field);
      }
      for (const field of fields) {
        const declared = modelEnums.find(
          (item) => item.referenceId === field.sys_reference_id
        );
        if (!declared) continue;
        bound.push({
          route: entity.route,
          entityName: entity.name,
          column: field.column_name,
          enumName: declared.name,
          values: declared.values,
          referenceId: declared.referenceId,
        });
      }
    }
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it.skipIf(!hasEnums)("the model declares at least one enum", () => {
    expect(modelEnums.length).toBeGreaterThan(0);
  });

  it.skipIf(!hasEnums)("every declared enum reaches a column", () => {
    // An enum the model declares and no `%%field … enum:` binds is dead
    // vocabulary — the column it was meant for is a free-text box.
    const unbound = modelEnums
      .filter((item) => !bound.some((column) => column.referenceId === item.referenceId))
      .map((item) => item.name);
    expect(unbound).toEqual([]);
  });

  it.skipIf(!hasEnums)("no enum declares a duplicate value", () => {
    const offenders = modelEnums
      .filter((item) => new Set(item.values).size !== item.values.length)
      .map((item) => item.name);
    expect(offenders).toEqual([]);
  });

  it.skipIf(!hasEnums)("no enum is empty", () => {
    const empty = modelEnums.filter((item) => item.values.length === 0).map((item) => item.name);
    expect(empty).toEqual([]);
  });

  // ── The rows in the column ────────────────────────────────────────────────

  describe("stored values", () => {
    for (const declared of modelEnums) {
      it.skipIf(!hasEnums)(
        `every row bound to ${declared.name} holds a value the model declares`,
        async () => {
          const columns = bound.filter((item) => item.referenceId === declared.referenceId);
          // Nothing bound to it — the "reaches a column" test above owns that
          // failure; reporting it twice would name one fault as two.
          if (columns.length === 0) return;

          const allowed = new Set(declared.values);
          const offenders: string[] = [];

          for (const column of columns) {
            const response = await harness.client.get(
              `/bus/${column.route}?limit=200`,
              { allowFailure: true }
            );
            if (!response.ok) continue;

            for (const row of rows<Row>(response.data)) {
              const value = row[column.column];
              if (value === null || value === undefined || value === "") continue;
              if (!allowed.has(String(value))) {
                offenders.push(`${column.route}.${column.column} = ${JSON.stringify(value)}`);
              }
            }
          }

          expect([...new Set(offenders)].sort()).toEqual([]);
        }
      );
    }
  });

  // ── What the API will accept ──────────────────────────────────────────────

  describe("the API refuses an undeclared value", () => {
    for (const declared of modelEnums) {
      it.skipIf(!hasEnums)(`${declared.name} rejects a value it never named`, async () => {
        const column = bound.find((item) => item.referenceId === declared.referenceId);
        if (!column) return;

        const entity = entities.find((item) => item.route === column.route);
        if (!entity) return;

        const writable = writableFields(entity).some((field) => field.name === column.column);
        if (!writable) return;

        const payload = await harness.buildValidRecord(entity, {
          [column.column]: `not-a-${declared.name.toLowerCase()}-value`,
        });
        const response = await harness.client.post(`/bus/${entity.route}`, payload, {
          allowFailure: true,
        });

        if (response.ok) {
          // It was accepted — track it so teardown removes it, then fail with
          // the value that got through rather than with a bare boolean.
          const id = (response.data as { id?: string } | undefined)?.id;
          if (id) harness.track(entity.route, id);
        }

        expect(response.status).toBeGreaterThanOrEqual(400);
      });
    }
  });

  // ── The dictionary's own consistency ──────────────────────────────────────

  describe("the dictionary agrees with the model", () => {
    for (const declared of modelEnums) {
      it.skipIf(!hasEnums)(`${declared.name} keeps the model's declaration order`, async () => {
        const response = await harness.client.get<Array<{ value: string }>>(
          `/sys/ref-list?sys_reference_id=${declared.referenceId}`,
          { allowFailure: true }
        );
        if (!response.ok) return;

        // Order is not asserted — `/sys/ref-list` sorts by value — but the set
        // is, and a missing value is a control that cannot select a state the
        // model requires.
        const served = new Set(rows<{ value: string }>(response.data).map((row) => row.value));
        const missing = declared.values.filter((value) => !served.has(value));
        expect(missing).toEqual([]);
      });
    }
  });
});

