/**
 * CRUD — {{entity.displayName}}
 *
 * One file per entity, so a failure names the entity that broke.
 *
 * The assertions are about behaviour rather than about status codes wherever
 * the two can be told apart. A sort that answers 200 with the rows in their
 * natural order, a filter that answers 200 having ignored the filter, and a
 * replace that answers 200 having changed nothing all pass a suite written
 * around `status < 500` — and each of them is a defect a user would notice
 * before the suite did.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import {
  buildInvalidRecord,
  entities,
  type FieldMeta,
  firstTextField,
  firstUnruledNumericField,
  getEntity,
  harness,
  HttpClient,
  numericFields,
  relationships,
  scalarFields,
  writableFields,
} from "../harness/index.ts";

const entity = getEntity("{{entity.name}}");

/** A UUID that is well-formed and belongs to nothing. */
const ABSENT_ID = "00000000-0000-4000-8000-000000000000";

/**
 * A foreign key the database really constrains.
 *
 * The migration emits a constraint for a declared `oneToMany` relationship and
 * for nothing else, so a column the ERD marks `FK` but draws no line for — a
 * `manager_id` resolved to `bus_user` by naming convention — is a reference the
 * dictionary describes and the schema does not enforce. Testing integrity on
 * one of those would be asserting a property the generated application does
 * not have; this picks a column where the constraint exists.
 */
function constrainedForeignKey(): FieldMeta | undefined {
  for (const relationship of relationships) {
    if (relationship.cardinality !== "oneToMany") continue;
    if (relationship.targetEntity !== entity.name) continue;

    const source = entities.find((candidate) => candidate.name === relationship.sourceEntity);
    if (!source) continue;

    const column = `${source.tableName.replace(/^bus_/, "")}_id`;
    const field = entity.fields.find((candidate) => candidate.name === column);
    if (field) return field;
  }
  return undefined;
}

/** Comparable form of a cell, for ordering assertions. */
function sortable(value: unknown): number | string | null {
  if (value === null || value === undefined) return null;
  if (typeof value === "number") return value;
  const asNumber = Number(value);
  if (!Number.isNaN(asNumber) && String(value).trim() !== "") return asNumber;
  return String(value);
}

describe("{{entity.displayName}} CRUD", () => {
  /** Ids created here that later tests reuse. */
  let createdId = "";

  beforeAll(async () => {
    await harness.setup();
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("lists records with pagination metadata", async () => {
    const response = await harness.client.get<{
      data: unknown[];
      meta: { total: number; page?: number; limit?: number };
    }>(`/bus/${entity.route}?page=1&limit=10`);

    expect(response.status).toBe(200);
    expect(Array.isArray(response.data.data)).toBe(true);
    expect(typeof response.data.meta.total).toBe("number");
    expect(response.data.data.length).toBeLessThanOrEqual(10);
  });

  it("creates a record", async () => {
    const created = await harness.createWithParents(entity);

    expect(created).not.toBeNull();
    expect(created?.id).toBeTruthy();

    createdId = String(created?.id);
  });

  it("reads the record back by id", async () => {
    expect(createdId).toBeTruthy();

    const response = await harness.client.get<Record<string, unknown>>(
      `/bus/${entity.route}/${createdId}`
    );

    expect(response.status).toBe(200);
    expect(response.data.id).toBe(createdId);
  });

  it("persists the values it was given", async () => {
    const textField = firstTextField(entity);
    if (!textField) return; // nothing text-shaped to assert on

    const marker = `e2e-${Date.now()}`;
    const created = await harness.createWithParents(entity, { [textField.name]: marker });
    expect(created).not.toBeNull();

    const response = await harness.client.get<Record<string, unknown>>(
      `/bus/${entity.route}/${created?.id}`
    );
    expect(String(response.data[textField.name])).toBe(marker);
  });

  it("stamps its own timestamps rather than taking the client's", async () => {
    const created = await harness.createWithParents(entity, {
      created_at: "1999-01-01T00:00:00.000Z",
      updated_at: "1999-01-01T00:00:00.000Z",
    });
    expect(created).not.toBeNull();

    // A row whose audit columns are whatever the caller sent has no audit
    // trail. Both are written by the insert itself, so the year the client
    // asked for must not survive.
    expect(String(created?.created_at)).not.toContain("1999");
    expect(String(created?.updated_at)).not.toContain("1999");
  });

  it("updates a record with PATCH", async () => {
    expect(createdId).toBeTruthy();

    const textField = firstTextField(entity);
    if (!textField) return;

    const updated = `patched-${Date.now()}`;
    const response = await harness.client.patch<Record<string, unknown>>(
      `/bus/${entity.route}/${createdId}`,
      { [textField.name]: updated }
    );

    expect(response.status).toBeLessThan(300);
    expect(String(response.data[textField.name])).toBe(updated);
  });

  it("leaves the fields it was not asked to change", async () => {
    const textField = firstTextField(entity);
    const numeric = firstUnruledNumericField(entity);
    if (!textField || !numeric) return;

    const created = await harness.createWithParents(entity, {
      [textField.name]: `keep-${Date.now()}`,
      [numeric.name]: 7,
    });
    expect(created).not.toBeNull();

    await harness.client.patch(`/bus/${entity.route}/${created?.id}`, {
      [textField.name]: `changed-${Date.now()}`,
    });

    // A partial update that quietly nulls every column the caller did not
    // mention is data loss dressed as a successful write.
    const after = await harness.client.get<Record<string, unknown>>(
      `/bus/${entity.route}/${created?.id}`
    );
    expect(Number(after.data[numeric.name])).toBe(7);
  });

  it("bumps the version on update", async () => {
    const created = await harness.createWithParents(entity);
    expect(created).not.toBeNull();

    const before = Number(created?.version ?? 0);
    const textField = firstTextField(entity);
    if (!textField) return;

    const response = await harness.client.patch<Record<string, unknown>>(
      `/bus/${entity.route}/${created?.id}`,
      { [textField.name]: `v-${Date.now()}` }
    );

    expect(Number(response.data.version ?? 0)).toBeGreaterThan(before);
  });

  it("refuses a write against a version that is no longer current", async () => {
    const textField = firstTextField(entity);
    if (!textField) return;

    const created = await harness.createWithParents(entity);
    expect(created).not.toBeNull();

    const staleVersion = Number(created?.version ?? 0);

    // Somebody else's edit lands first.
    await harness.client.patch(`/bus/${entity.route}/${created?.id}`, {
      [textField.name]: `first-writer-${Date.now()}`,
    });

    // Ours still believes the record looks the way it did when the form
    // opened. Without the check, this is the write that silently discards
    // theirs — the classic lost update.
    const conflicted = await harness.client.patch<Record<string, unknown>>(
      `/bus/${entity.route}/${created?.id}`,
      { [textField.name]: `second-writer-${Date.now()}` },
      { headers: { "If-Match": `"v${staleVersion}"` }, allowFailure: true }
    );

    expect(conflicted.status).toBe(409);

    const after = await harness.client.get<Record<string, unknown>>(
      `/bus/${entity.route}/${created?.id}`
    );
    expect(String(after.data[textField.name])).toContain("first-writer");
  });

  it("accepts a write against the version the caller actually read", async () => {
    const textField = firstTextField(entity);
    if (!textField) return;

    const created = await harness.createWithParents(entity);
    expect(created).not.toBeNull();

    const marker = `matched-${Date.now()}`;
    const response = await harness.client.patch<Record<string, unknown>>(
      `/bus/${entity.route}/${created?.id}`,
      { [textField.name]: marker },
      { headers: { "If-Match": `"v${Number(created?.version ?? 0)}"` }, allowFailure: true }
    );

    // The counterweight to the test above: a check that refuses everything is
    // indistinguishable from one that works, until somebody tries to save.
    expect(response.status).toBeLessThan(300);
    expect(String(response.data[textField.name])).toBe(marker);
  });

  it("replaces a record with PUT", async () => {
    const textField = firstTextField(entity);
    if (!textField) return;

    const created = await harness.createWithParents(entity, {
      [textField.name]: `before-replace-${Date.now()}`,
    });
    expect(created).not.toBeNull();
    if (!created) return;

    // The replacement is the record as it stands with one field changed —
    // which is what a replace is: read, edit, put back. Building a fresh
    // payload from the factory instead invents every other value too, and an
    // invented value has to satisfy the model's own rules and state machine to
    // be accepted. On a model that refuses a discount over 40 percent, or an
    // entity whose status may only move along declared edges, the refusal was
    // correct and the test was wrong.
    const replacement: Record<string, unknown> = {};
    for (const field of writableFields(entity)) {
      if (field.name in created) replacement[field.name] = created[field.name];
    }

    const marker = `replaced-${Date.now()}`;
    replacement[textField.name] = marker;

    const response = await harness.client.put<Record<string, unknown>>(
      `/bus/${entity.route}/${created.id}`,
      replacement,
      { allowFailure: true }
    );
    expect(response.status, `PUT answered ${response.status}: ${response.raw.slice(0, 200)}`)
      .toBeLessThan(300);

    // Read back rather than trusting the echo: a handler that answers with the
    // payload it was sent looks identical to one that wrote it.
    const after = await harness.client.get<Record<string, unknown>>(
      `/bus/${entity.route}/${created.id}`
    );
    expect(String(after.data[textField.name])).toBe(marker);
    expect(after.data.id).toBe(created.id);
  });

  it("rejects a payload missing a required field", async () => {
    const invalid = buildInvalidRecord(entity);
    if (!invalid) return; // entity has no required scalar fields

    const response = await harness.client.post(`/bus/${entity.route}`, invalid.payload, {
      allowFailure: true,
    });

    expect(response.ok).toBe(false);
    expect(response.status).toBeGreaterThanOrEqual(400);
    expect(response.status).toBeLessThan(500);
  });

  it("rejects a value that is not the column's type", async () => {
    const numeric = numericFields(entity)[0];
    if (!numeric) return;

    const payload = await harness.buildValidRecord(entity, {
      [numeric.name]: "not-a-number-at-all",
    });
    const response = await harness.client.post(`/bus/${entity.route}`, payload, {
      allowFailure: true,
    });

    // 400, not 500: a column that rejects the value at the database instead of
    // at the dictionary reports a constraint violation the caller cannot read.
    expect(response.status).toBeGreaterThanOrEqual(400);
    expect(response.status).toBeLessThan(500);
  });

  it("rejects a value longer than the column holds", async () => {
    const bounded = scalarFields(entity).find(
      (field) => typeof field.maxLength === "number" && field.maxLength > 0
    );
    if (!bounded) return;

    const payload = await harness.buildValidRecord(entity, {
      [bounded.name]: "x".repeat((bounded.maxLength ?? 0) + 50),
    });
    const response = await harness.client.post(`/bus/${entity.route}`, payload, {
      allowFailure: true,
    });

    expect(response.status).toBeGreaterThanOrEqual(400);
    expect(response.status).toBeLessThan(500);
  });

  it("rejects a foreign key pointing at a record that does not exist", async () => {
    const link = constrainedForeignKey();
    if (!link) return;

    const payload = await harness.buildValidRecord(entity, { [link.name]: ABSENT_ID });
    const response = await harness.client.post(`/bus/${entity.route}`, payload, {
      allowFailure: true,
    });

    // The row must not be written. Which 4xx is a matter of taste; a 2xx is a
    // dangling reference, and a 5xx is the database's error text reaching the
    // client.
    expect(response.status).toBeGreaterThanOrEqual(400);
    expect(response.status).toBeLessThan(500);
  });

  it("returns 404 for an unknown id", async () => {
    const response = await harness.client.get(`/bus/${entity.route}/${ABSENT_ID}`, {
      allowFailure: true,
    });

    expect(response.ok).toBe(false);
    expect(response.status).toBe(404);
  });

  it("returns 404 when updating or deleting an unknown id", async () => {
    const textField = firstTextField(entity);

    const patched = await harness.client.patch(
      `/bus/${entity.route}/${ABSENT_ID}`,
      textField ? { [textField.name]: "nobody" } : {},
      { allowFailure: true }
    );
    expect(patched.status).toBe(404);

    const removed = await harness.client.delete(`/bus/${entity.route}/${ABSENT_ID}`, {
      allowFailure: true,
    });
    expect(removed.status).toBe(404);
  });

  it("rejects a malformed id", async () => {
    const response = await harness.client.get(`/bus/${entity.route}/not-a-uuid`, {
      allowFailure: true,
    });

    expect(response.ok).toBe(false);
    expect(response.status).toBeGreaterThanOrEqual(400);
  });

  it("refuses a caller with no session", async () => {
    // A separate client, so it carries no cookie from the shared harness login.
    const anonymous = new HttpClient();

    const attempts = [
      await anonymous.get(`/bus/${entity.route}?limit=1`, { allowFailure: true }),
      await anonymous.get(`/bus/${entity.route}/${createdId || ABSENT_ID}`, {
        allowFailure: true,
      }),
      await anonymous.post(`/bus/${entity.route}`, {}, { allowFailure: true }),
      await anonymous.delete(`/bus/${entity.route}/${ABSENT_ID}`, { allowFailure: true }),
    ];

    const served = attempts.filter((response) => response.status < 400).map((r) => r.status);
    expect(served).toEqual([]);
  });

  it("sorts by a numeric column", async () => {
    const sortableField = numericFields(entity)[0];
    if (!sortableField) return;

    const response = await harness.client.get<{ data: Array<Record<string, unknown>> }>(
      `/bus/${entity.route}?limit=20&orderBy=${sortableField.name}&orderDir=asc`,
      { allowFailure: true }
    );
    expect(response.status).toBe(200);

    const values = response.data.data
      .map((row) => sortable(row[sortableField.name]))
      .filter((value): value is number => typeof value === "number");

    // A numeric column, deliberately: text ordering belongs to the database's
    // collation, and asserting it here with a JavaScript comparator tests the
    // comparator. Numbers have one order, so an `orderBy` that is accepted and
    // then ignored — the rows come back in insertion order, 200 and all — has
    // nowhere to hide.
    for (let index = 1; index < values.length; index++) {
      const previous = values[index - 1] as number;
      const current = values[index] as number;
      expect(previous <= current, `${previous} came before ${current} under orderDir=asc`).toBe(
        true
      );
    }
  });

  it("reverses the order when asked to", async () => {
    const sortableField = numericFields(entity)[0] ?? scalarFields(entity)[0];
    if (!sortableField) return;

    const ascending = await harness.client.get<{
      data: Array<Record<string, unknown>>;
      meta: { total: number };
    }>(`/bus/${entity.route}?limit=20&orderBy=${sortableField.name}&orderDir=asc`);
    const descending = await harness.client.get<{
      data: Array<Record<string, unknown>>;
      meta: { total: number };
    }>(`/bus/${entity.route}?limit=20&orderBy=${sortableField.name}&orderDir=desc`);

    const first = ascending.data.data.map((row) => String(row[sortableField.name]));
    const second = descending.data.data.map((row) => String(row[sortableField.name]));

    if (first.length > 1 && new Set(first).size > 1) {
      expect(second).not.toEqual(first);

      // When the whole table fits on one page the two are exact mirrors, in
      // whatever collation the database uses — which is the assertion the
      // ordering test above cannot make about text without guessing at it.
      if (ascending.data.meta.total <= 20) {
        expect(second).toEqual([...first].reverse());
      }
    }
  });

  it("searches by text", async () => {
    const textField = firstTextField(entity);
    if (!textField) return;

    const needle = `find-${Date.now()}`;
    await harness.createWithParents(entity, { [textField.name]: needle });

    const response = await harness.client.get<{ data: Array<Record<string, unknown>> }>(
      `/bus/${entity.route}?search=${encodeURIComponent(needle)}&limit=10`,
      { allowFailure: true }
    );

    expect(response.status).toBeLessThan(500);
    if (response.ok) {
      const hit = response.data.data.some((row) => String(row[textField.name]).includes(needle));
      expect(hit).toBe(true);
    }
  });

  it("filters with an equals operator", async () => {
    const textField = firstTextField(entity);
    if (!textField) return;

    const value = `filter-${Date.now()}`;
    const created = await harness.createWithParents(entity, { [textField.name]: value });
    if (!created) return;

    const response = await harness.client.get<{
      data: Array<Record<string, unknown>>;
      meta: { total: number };
    }>(`/bus/${entity.route}?filter.${textField.name}=equals:${encodeURIComponent(value)}`, {
      allowFailure: true,
    });

    expect(response.status).toBe(200);

    // Both directions. A filter that is parsed and dropped returns every row —
    // including rows that do not match — and a filter that is too eager
    // returns none, and the record just written is the one that proves it.
    expect(response.data.data.map((row) => row.id)).toContain(created.id);
    const mismatched = response.data.data.filter(
      (row) => String(row[textField.name]) !== value
    );
    expect(mismatched.map((row) => String(row[textField.name]))).toEqual([]);
  });

  it("pages without repeating or losing a row", async () => {
    // Enough rows to have a second page of.
    for (let index = 0; index < 6; index++) await harness.createWithParents(entity);

    const first = await harness.client.get<{
      data: Array<{ id: string }>;
      meta: { total: number };
    }>(`/bus/${entity.route}?page=1&limit=5&orderBy=id&orderDir=asc`);
    const second = await harness.client.get<{
      data: Array<{ id: string }>;
      meta: { total: number };
    }>(`/bus/${entity.route}?page=2&limit=5&orderBy=id&orderDir=asc`);

    expect(first.status).toBe(200);
    expect(second.status).toBe(200);
    expect(first.data.data.length).toBeLessThanOrEqual(5);

    // A pagination bug that offsets by page instead of by page × limit shows up
    // as an overlap here, and one that offsets too far shows up as a gap in the
    // totals. Both look like a working list from a single page.
    const firstIds = new Set(first.data.data.map((row) => row.id));
    const overlap = second.data.data.filter((row) => firstIds.has(row.id));
    expect(overlap.map((row) => row.id)).toEqual([]);
    expect(second.data.meta.total).toBe(first.data.meta.total);
  });

  // A delete removes the row and reports the workflows that ran clearing it.
  // It used to stamp `deleted_at` and answer 204, which read the same from the
  // outside — the record was gone from every query either way — while leaving
  // the row and its foreign keys in the table.
  it("deletes a record and reports what ran", async () => {
    const created = await harness.createWithParents(entity);
    expect(created).not.toBeNull();

    const response = await harness.client.delete<{
      deleted: boolean;
      message?: string;
      promotion: { operation: string; docStatus: string; ranWorkflows: string[] };
    }>(`/bus/${entity.route}/${created?.id}`, { allowFailure: true });

    // A record another record depends on cannot be deleted, and 409 is the
    // right answer — the model may declare an `afterCreate` hook that creates a
    // child pointing back with a NOT NULL foreign key, so this record was born
    // undeletable. DeviationReport in the drug-discovery example is exactly
    // that: creating one runs a workflow whose CreateEntity step writes a CAPA.
    //
    // What this test is actually for is the delete that *lies*: one that stamps
    // `deleted_at`, answers 204, and leaves the row and its foreign keys in the
    // table. Both a real delete and an honest refusal are correct; neither
    // silently reports success it did not achieve.
    if (response.status === 409) {
      // The global exception filter normalises an error into
      // `{statusCode, message, error, ...}`, so the refusal is read from the
      // message rather than from a `deleted: false` field.
      expect(String(response.data.message ?? "")).not.toBe("");
      // Refused means unchanged: the record is still there to be read.
      const still = await harness.client.get(`/bus/${entity.route}/${created?.id}`, {
        allowFailure: true,
      });
      expect(still.ok).toBe(true);
      return;
    }

    expect(response.status).toBe(200);
    expect(response.data.deleted).toBe(true);
    expect(response.data.promotion.operation).toBe("delete");
    expect(response.data.promotion.docStatus).toBe("deleted");

    const after = await harness.client.get(`/bus/${entity.route}/${created?.id}`, {
      allowFailure: true,
    });
    expect(after.ok).toBe(false);
  });

  it("stops listing a record once it is deleted", async () => {
    const textField = firstTextField(entity);
    if (!textField) return;

    const marker = `deleted-${Date.now()}`;
    const created = await harness.createWithParents(entity, { [textField.name]: marker });
    if (!created) return;

    const deleted = await harness.client.delete(`/bus/${entity.route}/${created.id}`, {
      allowFailure: true,
    });
    // Nothing to assert about a record that is still there on purpose — see the
    // delete test above for why a 409 is a correct answer.
    if (deleted.status === 409) return;

    // Reachable by id and absent from the list is one bug; gone from the list
    // and still returned by a filter is another. The list is what a screen
    // shows, so it is the one that has to be right.
    const listed = await harness.client.get<{ data: Array<{ id: string }> }>(
      `/bus/${entity.route}?filter.${textField.name}=equals:${encodeURIComponent(marker)}`,
      { allowFailure: true }
    );
    if (listed.ok) {
      expect(listed.data.data.map((row) => row.id)).not.toContain(created.id);
    }
  });

  it("exposes every writable field through the API", async () => {
    const created = await harness.createWithParents(entity);
    expect(created).not.toBeNull();

    const response = await harness.client.get<Record<string, unknown>>(
      `/bus/${entity.route}/${created?.id}`
    );

    const returned = new Set(Object.keys(response.data));
    const missing = writableFields(entity)
      .map((f) => f.name)
      .filter((name) => !returned.has(name));

    expect(missing).toEqual([]);
  });
});

tanstack-start-nestjs/tests/suites/08-us:
/**
 * Users and roles.
 *
 * Covers the seeded role hierarchy, faker-generated user registration at
 * volume, and the access-control surface that role membership drives.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import {
  buildUser,
  config,
  faker,
  harness,
  HttpClient,
  login,
  permissions,
  register,
  reseed,
} from "../harness/index.ts";

interface SysRole {
  sys_role_id: string;
  name: string;
  is_master_role?: boolean;
  [key: string]: unknown;
}

interface SysUser {
  sys_user_id: string;
  email: string;
  name?: string;
  [key: string]: unknown;
}

function rows<T>(body: unknown): T[] {
  if (Array.isArray(body)) return body as T[];
  if (body && typeof body === "object") {
    const record = body as Record<string, unknown>;
    if (Array.isArray(record.data)) return record.data as T[];
  }
  return [];
}

describe("users and roles", () => {
  const createdUsers: Array<{ email: string; password: string }> = [];

  beforeAll(async () => {
    await harness.setup();
    reseed(config.fakerSeed + 2);
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("seeds the system roles", async () => {
    const response = await harness.client.get("/sys/roles", { allowFailure: true });
    if (!response.ok) return; // route naming differs across generator versions

    const roles = rows<SysRole>(response.data);
    expect(roles.length).toBeGreaterThan(0);

    const names = roles.map((role) => String(role.name).toLowerCase());
    expect(names).toContain("administrator");
  });

  it("seeds the administrator user", async () => {
    const response = await harness.client.get("/sys/users", { allowFailure: true });
    if (!response.ok) return;

    const users = rows<SysUser>(response.data);
    const emails = users.map((user) => String(user.email).toLowerCase());

    expect(emails).toContain(config.admin.email.toLowerCase());
  });

  it("grants the administrator master access", async () => {
    const perms = await permissions(harness.client);

    expect(perms.role).toBeTruthy();
    expect(Array.isArray(perms.windows)).toBe(true);
  });

  it(
    `registers ${config.usersToCreate} faker-generated users`,
    async () => {
      let succeeded = 0;

      for (let i = 0; i < config.usersToCreate; i++) {
        const candidate = buildUser(i);
        // The administrator's client, not a fresh one: accounts are created
        // through the admin-only endpoint, so an anonymous caller is refused.
        const result = await register(
          harness.client,
          candidate.email,
          candidate.password,
          candidate.name
        );

        if (result.ok) {
          succeeded += 1;
          createdUsers.push({ email: candidate.email, password: candidate.password });
        }
      }

      console.log(`    registered ${succeeded}/${config.usersToCreate} users`);
      expect(succeeded).toBeGreaterThan(0);
    },
    Math.max(60_000, config.usersToCreate * 3000)
  );

  it("signs in as a registered user", async () => {
    if (createdUsers.length === 0) return;

    const candidate = faker.helpers.arrayElement(createdUsers);
    const client = new HttpClient();
    const user = await login(client, candidate.email, candidate.password);

    expect(String(user.email).toLowerCase()).toBe(candidate.email.toLowerCase());
  });

  it("gives a fresh user narrower permissions than the administrator", async () => {
    if (createdUsers.length === 0) return;

    const candidate = createdUsers[0]!;
    const client = new HttpClient();
    await login(client, candidate.email, candidate.password);

    const theirs = await permissions(client);
    const admin = await permissions(harness.client);

    expect(theirs.isMaster).toBe(false);
    expect(theirs.windows.length).toBeLessThanOrEqual(admin.windows.length);
  });

  it("rejects duplicate registration", async () => {
    if (createdUsers.length === 0) return;

    const existing = createdUsers[0]!;
    const result = await register(
      harness.client,
      existing.email,
      existing.password,
      "Duplicate"
    );

    expect(result.ok).toBe(false);
  });

  it("refuses to create an account for an anonymous caller", async () => {
    // The reason there is no sign-up page: an account is something an
    // administrator grants, so the endpoint has to refuse everyone else.
    const candidate = buildUser(9_000);
    const anonymous = new HttpClient();
    const result = await register(
      anonymous,
      candidate.email,
      candidate.password,
      candidate.name
    );

    expect(result.ok).toBe(false);
    expect([401, 403]).toContain(result.status);
  });

  it("refuses to create an account for a signed-in non-administrator", async () => {
    if (createdUsers.length === 0) return;

    const candidate = createdUsers[0]!;
    const client = new HttpClient();
    await login(client, candidate.email, candidate.password);

    const fresh = buildUser(9_001);
    const result = await register(client, fresh.email, fresh.password, fresh.name);

    expect(result.ok).toBe(false);
    expect([401, 403]).toContain(result.status);
  });

  it("refuses rule creation for a non-admin user", async () => {
    if (createdUsers.length === 0) return;

    const candidate = createdUsers[0]!;
    const client = new HttpClient();
    await login(client, candidate.email, candidate.password);

    const response = await client.post(
      "/rules",
      {
        entityName: "bus_probe",
        ruleName: "should-not-exist",
        operation: "ALL",
        jdmContent: "{}",
      },
      { allowFailure: true }
    );

    // Admin-only route: a non-admin must not get a 2xx.
    expect(response.ok).toBe(false);
    expect([400, 401, 403]).toContain(response.status);
  });
});

tanstack-start-nestjs/tests/suites/07-wo:
/**
 * Randomised workflow chaos.
 *
 * Registers cascade rules that reach across relationships, then performs
 * `E2E_RANDOM_WORKFLOW_OPS` random creates and updates against random
 * entities. The point is to exercise rule → workflow → cross-entity write
 * paths in combinations no hand-written test would enumerate, and to prove the
 * app stays consistent afterwards.
 *
 * The faker seed is fixed, so a failing run replays exactly.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it, sleep } from "../harness/testing.ts";
import {
  buildRecord,
  buildWorkflowTriggerJdm,
  config,
  createRule,
  entities,
  type EntityMeta,
  faker,
  firstTextField,
  harness,
  isTerminal,
  listRuns,
  relationships,
  reseed,
  runsForEntity,
  type RuleRecord,
} from "../harness/index.ts";

const suiteId = `e2e-chaos-${Date.now().toString(36)}`;

/** How long to let in-flight workflow dispatch settle before judging it. */
const SETTLE_MS = Math.min(config.workflowTimeoutMs, 5000);

interface Operation {
  kind: "create" | "update";
  entity: EntityMeta;
  id?: string;
  ok: boolean;
  status: number;
}

/** Relationships we can cascade along: source holds an FK to target. */
function cascadePairs(): Array<{ from: EntityMeta; to: EntityMeta; linkField: string }> {
  const pairs: Array<{ from: EntityMeta; to: EntityMeta; linkField: string }> = [];

  for (const rel of relationships) {
    const source = entities.find((e) => e.name === rel.sourceEntity);
    const target = entities.find((e) => e.name === rel.targetEntity);
    if (!source || !target) continue;

    const linkField =
      rel.foreignKey ??
      source.fields.find((f) => f.name === `${target.route.replace(/^bus_/, "")}_id`)?.name;
    if (!linkField) continue;

    pairs.push({ from: source, to: target, linkField });
  }

  return pairs;
}

describe("randomised workflow chaos", () => {
  const operations: Operation[] = [];
  const rules: RuleRecord[] = [];

  beforeAll(async () => {
    await harness.setup();
    reseed(config.fakerSeed + 1);

    // A workflow trigger on every entity…
    for (const entity of entities) {
      const rule = await createRule(harness.client, {
        entityName: entity.tableName,
        ruleName: `${suiteId}-${entity.tableName}-any`,
        operation: "ALL",
        jdmContent: buildWorkflowTriggerJdm(entity, `${entity.tableName}-chaos-workflow`),
      });
      harness.trackRule(rule.id);
      rules.push(rule);
    }

    // …plus cascade rules that write into a related entity.
    for (const pair of cascadePairs().slice(0, 5)) {
      const textField = firstTextField(pair.from);
      if (!textField) continue;

      const rule = await createRule(harness.client, {
        entityName: pair.to.tableName,
        ruleName: `${suiteId}-${pair.to.tableName}-cascade-${pair.from.tableName}`,
        operation: "UPDATE",
        jdmContent: buildWorkflowTriggerJdm(
          pair.to,
          `${pair.to.tableName}-cascade-workflow`,
          {
            targetEntity: pair.from.tableName,
            linkField: pair.linkField,
            updateData: `{ ${textField.name}: 'cascaded-${suiteId}' }`,
          }
        ),
      });
      harness.trackRule(rule.id);
      rules.push(rule);
    }
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("registers chaos rules across the model", () => {
    expect(rules.length).toBeGreaterThanOrEqual(entities.length);
  });

  it(
    `performs ${config.randomWorkflowOps} random writes across random entities`,
    async () => {
      const ordered = harness.orderedEntities();

      for (let i = 0; i < config.randomWorkflowOps; i++) {
        const entity = faker.helpers.arrayElement(ordered);
        const doUpdate = faker.datatype.boolean() && operations.some((op) => op.ok && op.id);

        if (doUpdate) {
          const candidates = operations.filter(
            (op) => op.ok && op.id && op.entity.route === entity.route
          );
          const previous = candidates.length > 0 ? faker.helpers.arrayElement(candidates) : null;

          if (previous?.id) {
            const textField = firstTextField(entity);
            const payload = textField
              ? { [textField.name]: `chaos-${faker.string.alphanumeric(8)}` }
              : buildRecord(entity);

            const response = await harness.client.patch(
              `/bus/${entity.route}/${previous.id}`,
              payload,
              { allowFailure: true }
            );

            operations.push({
              kind: "update",
              entity,
              id: previous.id,
              ok: response.ok,
              status: response.status,
            });
            continue;
          }
        }

        const created = await harness.createWithParents(entity);
        operations.push({
          kind: "create",
          entity,
          id: created?.id ? String(created.id) : undefined,
          ok: created !== null,
          status: created ? 201 : 0,
        });
      }

      expect(operations).toHaveLength(config.randomWorkflowOps);
    },
    Math.max(120_000, config.randomWorkflowOps * 3000)
  );

  it("never responds with a server error", () => {
    const serverErrors = operations.filter((op) => op.status >= 500);

    expect(
      serverErrors.map((op) => `${op.kind} ${op.entity.route} → ${op.status}`)
    ).toEqual([]);
  });

  it("succeeds on the majority of random operations", () => {
    const succeeded = operations.filter((op) => op.ok).length;

    // Some rejections are legitimate — a rule preventing a write is the system
    // working. A collapse to near-zero is not.
    expect(succeeded).toBeGreaterThan(operations.length * 0.5);
  });

  it("records workflow activity for the records it touched", async () => {
    const touched = operations.filter((op) => op.ok && op.id).slice(0, 10);

    for (const op of touched) {
      const runs = await runsForEntity(harness.client, op.entity.tableName, op.id!);
      expect(Array.isArray(runs)).toBe(true);
    }
  });

  // The settle time below is 5s, which is exactly the default per-test
  // timeout — so without an explicit one this test could only pass if every
  // other line took no time at all, and it failed on timing alone.
  it("leaves every observed workflow run in a terminal state", async () => {
    // Give any in-flight dispatch a moment to settle before judging it.
    await sleep(SETTLE_MS);

    const runs = await listRuns(harness.client, { limit: 100 });
    const pending = runs.filter((run) => !isTerminal(run.status));

    // Recently-created runs are allowed to still be working.
    const stuck = pending.filter(
      (run) =>
        run.created_at !== undefined &&
        Date.now() - new Date(String(run.created_at)).getTime() > 30_000
    );

    expect(stuck.map((run) => `${run.workflow_name}:${run.status}`)).toEqual([]);
  }, SETTLE_MS * 4);

  it("keeps every touched record readable afterwards", async () => {
    const touched = operations.filter((op) => op.ok && op.id).slice(-20);

    for (const op of touched) {
      const response = await harness.client.get(`/bus/${op.entity.route}/${op.id}`, {
        allowFailure: true,
      });

      // 404 is acceptable only if a cascade-delete rule removed it.
      expect([200, 404]).toContain(response.status);
    }
  });
});

tanstack-start-nestjs/tests/suites/02b-d:
/**
 * Application Dictionary — the window, tab and field layout.
 *
 * `02-dictionary` checks that every column the ERD declares reached
 * `sys_column`. That is the data half. This is the presentation half: a column
 * nothing draws is a column nobody can edit, and the three tables that decide
 * what gets drawn are `sys_window` (the screen), `sys_tab` (the section of it
 * bound to a table) and `sys_field` (the control bound to a column).
 *
 * The failure this suite exists to catch is silent by construction. A missing
 * `sys_field` row does not error anywhere — the form simply renders without
 * that input, the API keeps accepting the column, and the only symptom is a
 * field a user cannot fill in. Same for a window with no tab: the screen opens
 * empty and the application looks like it has no data.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import { entities, harness, isStateField, writableFields } from "../harness/index.ts";

interface WindowRow {
  sys_window_id: string;
  name: string;
  description?: string | null;
  help?: string | null;
  window_type?: string | null;
  is_active?: boolean;
}

interface TabRow {
  sys_tab_id: string;
  sys_window_id: string;
  sys_table_id: string;
  name: string;
  seq_no?: number;
  is_active?: boolean;
  /** 0 for a master tab, 1 for a line item's tab inside its parent's window. */
  tab_level?: number;
  /** The column a detail tab links to its master on. */
  link_column_id?: string | null;
}

interface MetaResponse {
  table: { sys_table_id: string; table_name: string; name?: string };
  columns: Array<{
    sys_field_id?: string;
    column_name: string;
    name: string;
    seq_no?: number;
    seq_no_grid?: number;
    is_displayed?: boolean;
    is_displayed_grid?: boolean;
  }>;
  window?: WindowRow | null;
}

/** `/sys/...` list endpoints answer either a bare array or `{ data: [...] }`. */
function rows<T>(body: unknown): T[] {
  if (Array.isArray(body)) return body as T[];
  if (body && typeof body === "object") {
    const record = body as Record<string, unknown>;
    if (Array.isArray(record.data)) return record.data as T[];
  }
  return [];
}

describe("application dictionary — window, tab and field", () => {
  let windows: WindowRow[] = [];
  let tabs: TabRow[] = [];
  /** entity route → its `/meta` payload, fetched once and shared. */
  const metaByRoute = new Map<string, MetaResponse>();

  beforeAll(async () => {
    await harness.setup();

    const [windowResponse, tabResponse] = await Promise.all([
      harness.client.get("/sys/windows?limit=500", { allowFailure: true }),
      harness.client.get("/sys/tabs?limit=500", { allowFailure: true }),
    ]);
    windows = windowResponse.ok ? rows<WindowRow>(windowResponse.data) : [];
    tabs = tabResponse.ok ? rows<TabRow>(tabResponse.data) : [];

    for (const entity of entities) {
      const response = await harness.client.get<MetaResponse>(`/bus/${entity.route}/meta`, {
        allowFailure: true,
      });
      if (response.ok) metaByRoute.set(entity.route, response.data);
    }
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("serves the window registry", () => {
    expect(windows.length).toBeGreaterThan(0);
  });

  it("serves the tab registry", () => {
    expect(tabs.length).toBeGreaterThan(0);
  });

  it("registers a window for every entity", () => {
    const missing = entities.filter((entity) => !metaByRoute.get(entity.route)?.window).map(
      (entity) => entity.tableName
    );
    expect(missing).toEqual([]);
  });

  // A tab whose sys_table_id names no registered table draws a section bound
  // to nothing — the screen renders a heading and no rows.
  it("binds every tab to a registered table", () => {
    const tableIds = new Set(
      [...metaByRoute.values()].map((meta) => meta.table?.sys_table_id).filter(Boolean)
    );
    // Only tabs belonging to entity windows are checked: the Application
    // Dictionary's own screens (Audit Log, Workflow Designer…) describe how the
    // application is built and have no bus_ table behind them.
    const entityWindowIds = new Set(
      [...metaByRoute.values()].map((meta) => meta.window?.sys_window_id).filter(Boolean)
    );
    const orphans = tabs
      .filter((tab) => entityWindowIds.has(tab.sys_window_id))
      .filter((tab) => !tab.sys_table_id || !tableIds.has(tab.sys_table_id))
      .map((tab) => tab.name);
    expect(orphans).toEqual([]);
  });

  it("gives every window a distinct name", () => {
    const names = windows.map((window) => window.name);
    const duplicates = names.filter((name, index) => names.indexOf(name) !== index);
    expect([...new Set(duplicates)]).toEqual([]);
  });

  for (const entity of entities) {
    describe(entity.displayName, () => {
      it("has a window carrying a name and help", () => {
        const meta = metaByRoute.get(entity.route);
        expect(meta?.window).toBeTruthy();
        expect(typeof meta?.window?.name).toBe("string");
        expect((meta?.window?.name ?? "").length).toBeGreaterThan(0);
      });

      it("has at least one tab under that window", () => {
        const meta = metaByRoute.get(entity.route);
        const windowId = meta?.window?.sys_window_id;
        expect(windowId).toBeTruthy();
        const owned = tabs.filter((tab) => tab.sys_window_id === windowId);
        expect(owned.length).toBeGreaterThan(0);
      });

      it("has a tab of its own on that window", () => {
        const meta = metaByRoute.get(entity.route);
        const windowId = meta?.window?.sys_window_id;
        const owned = tabs.filter((tab) => tab.sys_window_id === windowId);
        // The entity's own tab must be there. It used to be asserted the other
        // way round — that *every* tab on the window pointed at this table —
        // which was right while a window held exactly one entity and wrong the
        // moment `%%entity <Child> parent: <Parent>` put a line item's tab
        // beside its master's. What matters is that the entity is represented,
        // and that anything else on the window is a declared child of it.
        const mine = owned.filter((tab) => tab.sys_table_id === meta?.table?.sys_table_id);
        expect(mine.length).toBeGreaterThan(0);
      });

      it("shares its window only with its own line items", () => {
        const meta = metaByRoute.get(entity.route);
        const windowId = meta?.window?.sys_window_id;
        const owned = tabs.filter((tab) => tab.sys_window_id === windowId);

        // A window belongs to one entity and may hold that entity's tab plus
        // the tabs of its line items — so the question is asked of the window's
        // *owner*, which for a child is its parent. Asking it of the child put
        // the master's own tab in the foreign list, which is the arrangement
        // working rather than failing.
        const owner = entity.parentEntity
          ? (entities.find((candidate) => candidate.name === entity.parentEntity) ?? entity)
          : entity;
        const permitted = new Set<string | undefined>([
          metaByRoute.get(owner.route)?.table?.sys_table_id,
        ]);
        for (const child of entities) {
          if (child.parentEntity !== owner.name) continue;
          permitted.add(metaByRoute.get(child.route)?.table?.sys_table_id);
        }

        const foreign = owned
          .filter((tab) => !permitted.has(tab.sys_table_id))
          .map((tab) => tab.name);
        expect(foreign).toEqual([]);
      });

      it("is a detail tab when the model declares a parent", () => {
        const meta = metaByRoute.get(entity.route);
        const own = tabs.filter((tab) => tab.sys_table_id === meta?.table?.sys_table_id);
        expect(own.length).toBeGreaterThan(0);

        if (entity.parentEntity) {
          // A line item lives inside its parent's window, one level down, and
          // links on the foreign key it declared. Without the link column the
          // tab would list every child in the table under whichever parent
          // happened to be open.
          const parentMeta = metaByRoute.get(
            entities.find((candidate) => candidate.name === entity.parentEntity)?.route ?? ""
          );
          expect(meta?.window?.sys_window_id).toBe(parentMeta?.window?.sys_window_id);
          expect(own[0]?.tab_level).toBe(1);
          expect(own[0]?.link_column_id).toBeTruthy();
        } else {
          expect(own[0]?.tab_level).toBe(0);
        }
      });

      it("draws a field for every column the model declares", async () => {
        const response = await harness.client.get<Array<{ column_name: string }>>(
          `/bus/${entity.route}/fields/form?includeHidden=true`
        );
        const drawn = new Set(response.data.map((field) => field.column_name));
        const missing = writableFields(entity)
          .map((field) => field.name)
          .filter((name) => !drawn.has(name));
        expect(missing).toEqual([]);
      });

      // Two fields sharing a sequence leave the form's order down to whatever
      // the database returns first, which is not stable between runs.
      it("gives its form fields distinct sequence numbers", async () => {
        const response = await harness.client.get<Array<{ seq_no?: number }>>(
          `/bus/${entity.route}/fields/form?includeHidden=true`
        );
        const sequences = response.data
          .map((field) => field.seq_no)
          .filter((seq): seq is number => typeof seq === "number");
        expect(sequences.length).toBe(new Set(sequences).size);
      });

      it("labels every field with something other than the raw column name", async () => {
        const response = await harness.client.get<
          Array<{ column_name: string; name?: string }>
        >(`/bus/${entity.route}/fields/form?includeHidden=true`);

        // `smiles` and `id` are already words; the check is that a column with
        // underscores in it was turned into a label, not printed as stored.
        const raw = response.data
          .filter((field) => field.column_name.includes("_"))
          .filter((field) => !field.name || field.name === field.column_name)
          .map((field) => field.column_name);
        expect(raw).toEqual([]);
      });

      // Grid columns are drawn from the same field rows as the form, so a grid
      // field that is not also a form field is a row the form cannot reach.
      it("draws its grid from fields the form also knows", async () => {
        const [form, grid] = await Promise.all([
          harness.client.get<Array<{ column_name: string }>>(
            `/bus/${entity.route}/fields/form?includeHidden=true`
          ),
          harness.client.get<Array<{ column_name: string }>>(`/bus/${entity.route}/fields/grid`),
        ]);
        const known = new Set(form.data.map((field) => field.column_name));
        // The state field is the one grid column the form does not carry: it is
        // shown read-only in the record's header, because only background
        // workflows change it.
        const unknown = grid.data
          .map((field) => field.column_name)
          .filter((name) => !known.has(name) && !isStateField(entity, name));
        expect(unknown).toEqual([]);
      });

      it("shows at least one column in the grid", async () => {
        const response = await harness.client.get<Array<unknown>>(
          `/bus/${entity.route}/fields/grid`
        );
        // A grid with no columns is a list screen that renders empty rows.
        expect(response.data.length).toBeGreaterThan(0);
      });

      it("answers the window-help request its screens make", async () => {
        const response = await harness.client.get<{
          window?: { name?: string };
          tabs?: unknown[];
          fields?: unknown[];
        }>(`/sys/window-help/${entity.tableName}`, { allowFailure: true });

        expect(response.status).toBe(200);
        expect(response.data?.window?.name).toBeTruthy();
      });
    });
  }
});

tanstack-start-nestjs/tests/suites/18-wr:
/**
 * Write throughput and tail latency — per entity, and under concurrency.
 *
 * `10-benchmark` measures reads on the largest table. Writes are the other half
 * of the picture and behave differently: every insert runs the model's rules
 * and workflows through the promotion pipeline, so an entity with a saga on it
 * costs several times one without, and no read benchmark shows that.
 *
 * Two things are measured here that the incidental instrumentation on the HTTP
 * client cannot give:
 *
 *   - **per entity**, so the expensive one is named rather than averaged away;
 *   - **under concurrency**, because a pool exhausted at eight parallel writers
 *     is invisible to any number of sequential ones.
 *
 * Every sample lands in the same collector as the rest of the run, so the
 * report tabulates these beside the read phases.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import { entities, firstTextField, harness, record, timed } from "../harness/index.ts";

/** Writes per entity per phase. Small: this runs for every entity in the model. */
const REPS = Number(process.env.E2E_WRITE_REPS ?? 5);

/** Parallel writers for the concurrency phase. */
const CONCURRENCY = Number(process.env.E2E_WRITE_CONCURRENCY ?? 8);

interface Row {
  id?: string;
  [column: string]: unknown;
}

describe("write benchmark", () => {
  /** Entities a payload could actually be built for — the rest are skipped, not failed. */
  const writable: Array<(typeof entities)[number]> = [];

  beforeAll(async () => {
    await harness.setup();
    for (const entity of entities) {
      const probe = await harness.createWithParents(entity);
      if (probe?.id) writable.push(entity);
    }
    console.log(
      `\n  write benchmark: ${writable.length}/${entities.length} entities, ` +
        `${REPS} writes each, ${CONCURRENCY} parallel\n`
    );
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("has at least one entity it can write to", () => {
    expect(writable.length).toBeGreaterThan(0);
  });

  for (const entity of entities) {
    describe(entity.name, () => {
      it("insert", async () => {
        if (!writable.includes(entity)) return;

        let created = 0;
        for (let index = 0; index < REPS; index++) {
          const payload = await harness.buildValidRecord(entity);
          const response = await timed(
            "insert (benchmark)",
            () =>
              harness.client.post<Row>(`/bus/${entity.route}`, payload, { allowFailure: true }),
            entity.route
          );
          if (response.ok) {
            created++;
            const id = response.data?.id;
            if (id) harness.track(entity.route, id);
          }
        }
        // A phase that wrote nothing measured nothing; say so rather than
        // reporting a confident zero.
        expect(created).toBeGreaterThan(0);
      });

      it("update", async () => {
        if (!writable.includes(entity)) return;
        const text = firstTextField(entity);
        if (!text) return;

        const seed = await harness.createWithParents(entity);
        const id = seed?.id as string | undefined;
        if (!id) return;

        let updated = 0;
        for (let index = 0; index < REPS; index++) {
          const response = await timed(
            "update (benchmark)",
            () =>
              harness.client.patch<Row>(
                `/bus/${entity.route}/${id}`,
                { [text.name]: `e2e-bench-${index}-${Date.now().toString(36)}` },
                { allowFailure: true }
              ),
            entity.route
          );
          if (response.ok) updated++;
        }
        expect(updated).toBeGreaterThan(0);
      });

      it("delete", async () => {
        if (!writable.includes(entity)) return;

        const ids: string[] = [];
        for (let index = 0; index < REPS; index++) {
          const created = await harness.createWithParents(entity);
          const id = created?.id as string | undefined;
          if (id) ids.push(id);
        }
        if (ids.length === 0) return;

        let removed = 0;
        for (const id of ids) {
          const response = await timed(
            "delete (benchmark)",
            () => harness.client.delete(`/bus/${entity.route}/${id}`, { allowFailure: true }),
            entity.route
          );
          if (response.ok) removed++;
        }
        expect(removed).toBeGreaterThan(0);
      });
    });
  }

  // ── Concurrency ───────────────────────────────────────────────────────────

  describe("under concurrency", () => {
    it(`sustains ${CONCURRENCY} parallel writers`, async () => {
      const entity = writable[0];
      if (!entity) return;

      const payloads = await Promise.all(
        Array.from({ length: CONCURRENCY }, () => harness.buildValidRecord(entity))
      );

      const startedAt = performance.now();
      const responses = await Promise.all(
        payloads.map((payload) =>
          harness.client.post<Row>(`/bus/${entity.route}`, payload, { allowFailure: true })
        )
      );
      const elapsed = performance.now() - startedAt;

      for (const response of responses) {
        const id = response.data?.id;
        if (response.ok && id) harness.track(entity.route, id);
      }

      const succeeded = responses.filter((response) => response.ok).length;

      // Recorded as one sample per successful write, so the phase's ops/sec is
      // computed from the wall-clock span the burst occupied rather than from
      // summed latencies — which, run in parallel, exceed the elapsed time.
      for (let index = 0; index < succeeded; index++) {
        record({ op: "insert (concurrent)", ms: elapsed / Math.max(succeeded, 1), name: entity.route });
      }

      // The claim is that concurrency does not *break* it — a pool that
      // deadlocks or a serialisation failure shows up as a refusal here. The
      // throughput itself belongs to the machine and is reported, not asserted.
      expect(succeeded).toBeGreaterThan(0);
      expect(succeeded).toBe(CONCURRENCY);
    });

    it("keeps every concurrent write distinct", async () => {
      const entity = writable[0];
      if (!entity) return;

      const payloads = await Promise.all(
        Array.from({ length: CONCURRENCY }, () => harness.buildValidRecord(entity))
      );
      const responses = await Promise.all(
        payloads.map((payload) =>
          harness.client.post<Row>(`/bus/${entity.route}`, payload, { allowFailure: true })
        )
      );

      const ids = responses
        .filter((response) => response.ok)
        .map((response) => response.data?.id)
        .filter((id): id is string => typeof id === "string");

      for (const id of ids) harness.track(entity.route, id);

      // Two writers handed the same id would mean one row silently replaced
      // another — the failure mode a sequential test can never produce.
      expect(new Set(ids).size).toBe(ids.length);
    });

    it("serialises concurrent updates to one record", async () => {
      const entity = writable[0];
      if (!entity) return;
      const text = firstTextField(entity);
      if (!text) return;

      const created = await harness.createWithParents(entity);
      const id = created?.id as string | undefined;
      if (!id) return;

      const responses = await Promise.all(
        Array.from({ length: CONCURRENCY }, (_, index) =>
          harness.client.patch<Row>(
            `/bus/${entity.route}/${id}`,
            { [text.name]: `e2e-race-${index}` },
            { allowFailure: true }
          )
        )
      );

      // Some may lose the race and that is correct; none may 500.
      const crashed = responses.filter((response) => response.status >= 500).length;
      expect(crashed).toBe(0);

      const after = await harness.client.get<Row>(`/bus/${entity.route}/${id}`, {
        allowFailure: true,
      });
      if (!after.ok) return;

      // Whoever won, the row is one of the values written — not a blend.
      const value = String(after.data[text.name] ?? "");
      expect(value.startsWith("e2e-race-")).toBe(true);
    });
  });
});

tanstack-start-nestjs/tests/suites/22-op:
/**
 * Optimistic locking: a save names the version it read, and a save made
 * against a version someone else has already moved past is refused.
 *
 * What the form does with the refusal — offer "Reload their version" or
 * "Overwrite with mine" — rests entirely on four things this suite holds the
 * API to:
 *
 *   - a stale `If-Match` is a 409 carrying `details.code: VERSION_CONFLICT`,
 *     not a generic error the form cannot tell apart from a duplicate key;
 *   - two saves racing from the same version produce exactly one winner. The
 *     backend used to compare the version and then update in a second
 *     statement, so both passed the comparison and the second silently
 *     replaced the first — the lost update the version column exists to stop;
 *   - "Overwrite" — a save naming the version the conflict reported — goes
 *     through, and is itself checked;
 *   - a malformed header is a 400, not a `NaN` that every save then "conflicts"
 *     with, and no header at all still saves (an API client that never read a
 *     version is not opted into locking).
 *
 * And one that lets a plain HTTP client take part without reading the body: a
 * read and a save answer with the version as an `ETag`, which is the value to
 * send back as `If-Match`.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "../harness/testing.ts";
import { entities, firstTextField, harness } from "../harness/index.ts";

interface Row {
  id?: string;
  version?: number;
  [column: string]: unknown;
}

interface ErrorBody {
  statusCode?: number;
  details?: { code?: string; expectedVersion?: number; currentVersion?: number };
}

const stamp = (label: string) => `e2e-lock-${label}-${Date.now().toString(36)}`;

describe("optimistic locking", () => {
  beforeAll(async () => {
    await harness.setup();
  });

  afterAll(async () => {
    await harness.teardown();
  });

  for (const entity of entities) {
    const text = firstTextField(entity);
    if (!text) continue;
    const path = (id: string) => `/bus/${entity.route}/${id}`;
    const ifMatch = (version: unknown) => ({ "If-Match": `"${version}"` });

    describe(entity.name, () => {
      it("refuses a save made against a version someone else moved past", async () => {
        const created = (await harness.createWithParents(entity)) as Row | null;
        if (!created?.id) return;
        const opened = Number(created.version);

        const first = await harness.client.patch<Row>(
          path(created.id),
          { [text.name]: stamp("first") },
          { headers: ifMatch(opened), allowFailure: true }
        );
        if (!first.ok) return; // the model's own rules may refuse any edit here

        const stale = await harness.client.patch<ErrorBody>(
          path(created.id),
          { [text.name]: stamp("stale") },
          { headers: ifMatch(opened), allowFailure: true }
        );
        expect(stale.status).toBe(409);
        expect(stale.data.details?.code).toBe("VERSION_CONFLICT");
        expect(stale.data.details?.expectedVersion).toBe(opened);
        expect(stale.data.details?.currentVersion).toBe(Number(first.data.version));
      });

      it("answers a read and a save with the record's version as its ETag", async () => {
        const created = (await harness.createWithParents(entity)) as Row | null;
        if (!created?.id) return;

        const read = await harness.client.get<Row>(path(created.id));
        expect(read.headers.get("etag")).toBe(`"${read.data.version}"`);

        const saved = await harness.client.patch<Row>(
          path(created.id),
          { [text.name]: stamp("etag") },
          { headers: ifMatch(read.data.version), allowFailure: true }
        );
        if (!saved.ok) return; // the model's own rules may refuse any edit here
        expect(saved.headers.get("etag")).toBe(`"${saved.data.version}"`);
      });

      it("lets exactly one of two parallel saves from the same version win", async () => {
        const created = (await harness.createWithParents(entity)) as Row | null;
        if (!created?.id) return;
        const opened = Number(created.version);
        const values = [stamp("a"), stamp("b")];

        const results = await Promise.all(
          values.map((value) =>
            harness.client.patch<Row>(
              path(created.id as string),
              { [text.name]: value },
              { headers: ifMatch(opened), allowFailure: true }
            )
          )
        );
        const statuses = results.map((r) => r.status).sort();
        // A rule refusing both is the model working, not a locking result.
        if (statuses.every((s) => s === 422 || s === 400)) return;
        expect(statuses).toEqual([200, 409]);

        const winner = results.find((r) => r.status === 200);
        const stored = await harness.client.get<Row>(path(created.id));
        expect(stored.data[text.name]).toBe(winner?.data[text.name]);
        expect(Number(stored.data.version)).toBe(opened + 1);
      });

      it("overwrites when the save names the version the conflict reported", async () => {
        const created = (await harness.createWithParents(entity)) as Row | null;
        if (!created?.id) return;
        const opened = Number(created.version);

        const theirs = await harness.client.patch<Row>(
          path(created.id),
          { [text.name]: stamp("theirs") },
          { headers: ifMatch(opened), allowFailure: true }
        );
        if (!theirs.ok) return;

        const conflict = await harness.client.patch<ErrorBody>(
          path(created.id),
          { [text.name]: stamp("mine") },
          { headers: ifMatch(opened), allowFailure: true }
        );
        expect(conflict.status).toBe(409);

        const mine = stamp("mine-again");
        const overwrite = await harness.client.patch<Row>(
          path(created.id),
          { [text.name]: mine },
          { headers: ifMatch(conflict.data.details?.currentVersion), allowFailure: true }
        );
        expect(overwrite.status).toBe(200);
        expect(overwrite.data[text.name]).toBe(mine);
      });

      it("refuses a malformed If-Match and still saves without one", async () => {
        const created = (await harness.createWithParents(entity)) as Row | null;
        if (!created?.id) return;

        const malformed = await harness.client.patch<{ message?: string }>(
          path(created.id),
          { [text.name]: stamp("bad-header") },
          { headers: { "If-Match": "not-a-version" }, allowFailure: true }
        );
        expect(malformed.status).toBe(400);
        expect(String(malformed.data.message)).toContain("If-Match");

        // Without a header the save is unconditional. The model's own
        // validation or rules may still refuse the value this suite invents —
        // that is the model working — but never as a version conflict.
        const unconditional = await harness.client.patch<Row>(
          path(created.id),
          { [text.name]: stamp("no-header") },
          { allowFailure: true }
        );
        expect(unconditional.status).not.toBe(409);
      });
    });
  }
});

