/**
 * What the model declared — as data.
 *
 * `entities.ts` describes the *shape* the suites have to build payloads for.
 * This file is the other half: the values a column is allowed to hold and the
 * states a record is allowed to move between, taken straight from the `%%enum`
 * and `%%workflow … kind: state` directives in the source model.
 *
 * The distinction matters. A suite that reads the running application's
 * dictionary and then asserts against that same dictionary proves only that
 * the application is self-consistent — it passes just as happily when the
 * generator dropped a value on the floor. Everything here is the model's own
 * word, so a dropdown that lost an option or a state machine that lost an edge
 * fails a test instead of quietly shipping.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

export interface ModelEnum {
  /** Name as the `%%enum` directive spells it. */
  name: string;
  /** sys_reference_id the generator allocated — 1000 and up. */
  referenceId: number;
  /** Allowed values, in declaration order. */
  values: string[];
}

export interface StateEdge {
  from: string;
  to: string;
  /** The `:` label on the diagram's arrow, where it carries one. */
  trigger: string;
}

export interface StateMachine {
  /** ERD entity name, e.g. "Program". */
  entity: string;
  /** Physical table the guard reads transitions for. */
  tableName: string;
  /** Column holding the state — `status` unless the entity has no such column. */
  statusField: string;
  /** The state a record starts in, from the `[*] --> x` edge. */
  initial: string;
  /** States with no outgoing edge. */
  terminal: string[];
  /** Every edge the diagram draws, minus the `[*]` start and end markers. */
  edges: StateEdge[];
}

export interface ModelReport {
  /** Name as the `%%report` directive spells it — and the row's key. */
  name: string;
  /** What the report is called on screen. */
  title: string;
  /** The entity it is about, where it names one; "" otherwise. */
  entity: string;
  /** Chart type, or "" for a table. */
  chart: string;
  /** Result columns the chart plots. Both set when `chart` is. */
  x: string;
  y: string;
}

/**
 * Every `%%report` the model declares.
 *
 * The SQL is deliberately absent: the point of the suite that reads this is
 * that the *application* holds the query and runs it. Carrying a second copy
 * here would let a suite assert a report against the string it was handed
 * rather than against the schema the query has to match.
 */
export const modelReports: ModelReport[] = [
{{#each modelReports}}
  {
    name: "{{name}}",
    title: {{{json title}}},
    entity: "{{entity}}",
    chart: "{{chart}}",
    x: "{{x}}",
    y: "{{y}}",
  },
{{/each}}
];

export const modelEnums: ModelEnum[] = [
{{#each modelEnums}}
  {
    name: "{{name}}",
    referenceId: {{referenceId}},
    values: [{{#each values}}"{{this}}"{{#unless @last}}, {{/unless}}{{/each}}],
  },
{{/each}}
];

/**
 * A condition under which the model's own rules refuse a write — the `when:` of
 * every `%%action validation-error`, whichever operation the rule is bound to.
 *
 * The factory invents values, and a model that says `status == "completed" and
 * final_grade == null` is refused will refuse a quarter of the records it draws.
 * Keeping a drawn record clear of these is the factory's job, not the model's.
 */
export interface Refusal {
  tableName: string;
  when: string;
}

export const refusals: Refusal[] = [
{{#each refusals}}
  { tableName: "{{tableName}}", when: {{{json when}}} },
{{/each}}
];

export const stateMachines: StateMachine[] = [
{{#each stateMachines}}
  {
    entity: "{{entity}}",
    tableName: "{{tableName}}",
    statusField: "{{statusField}}",
    initial: "{{initial}}",
    terminal: [{{#each terminal}}"{{this}}"{{#unless @last}}, {{/unless}}{{/each}}],
    edges: [
{{#each edges}}
      { from: "{{from}}", to: "{{to}}", trigger: "{{trigger}}" },
{{/each}}
    ],
  },
{{/each}}
];

/** The state machine declared for a table, if the model declared one. */
export function stateMachineFor(tableName: string): StateMachine | undefined {
  return stateMachines.find((machine) => machine.tableName === tableName);
}

/** Every state either end of an edge names, plus the initial state. */
export function statesOf(machine: StateMachine): string[] {
  const seen = new Set<string>();
  if (machine.initial) seen.add(machine.initial);
  for (const edge of machine.edges) {
    seen.add(edge.from);
    seen.add(edge.to);
  }
  return [...seen];
}

/** The states reachable from `from` in one step. */
export function successorsOf(machine: StateMachine, from: string): string[] {
  return machine.edges.filter((edge) => edge.from === from).map((edge) => edge.to);
}

/**
 * A state the model does *not* allow moving to from `from`, or null when the
 * machine allows every state from there and there is nothing illegal to try.
 */
export function illegalTargetFrom(machine: StateMachine, from: string): string | null {
  const allowed = new Set(successorsOf(machine, from));
  allowed.add(from);
  return statesOf(machine).find((state) => !allowed.has(state)) ?? null;
}

/**
 * A shortest path of edges from the machine's initial state to `target`,
 * or null when no path exists. Breadth-first, so a suite walking a record into
 * a given state takes the fewest writes that get it there.
 */
export function pathTo(machine: StateMachine, target: string): StateEdge[] | null {
  if (!machine.initial) return null;
  if (machine.initial === target) return [];

  const queue: Array<{ state: string; path: StateEdge[] }> = [
    { state: machine.initial, path: [] },
  ];
  const seen = new Set<string>([machine.initial]);

  while (queue.length > 0) {
    const current = queue.shift();
    if (!current) break;
    for (const edge of machine.edges) {
      if (edge.from !== current.state || seen.has(edge.to)) continue;
      const path = [...current.path, edge];
      if (edge.to === target) return path;
      seen.add(edge.to);
      queue.push({ state: edge.to, path });
    }
  }
  return null;
}

tanstack-start-nestjs/tests/harness/harn:
/**
 * The test harness.
 *
 * Every suite calls `harness.setup()` in `beforeAll` and `harness.teardown()`
 * in `afterAll`. Setup is idempotent and shared per process, so suites do not
 * each pay for a fresh login.
 *
 * The harness also owns cleanup: anything registered with `track()` is deleted
 * on teardown, in reverse creation order so children go before parents.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { randomUUID } from "node:crypto";
import { login, type SessionUser } from "./auth.ts";
import {
  distinctParentColumns,
  type EntityMeta,
  type FieldMeta,
  foreignKeyFields,
  parentEntityForColumn,
  topologicalEntities,
} from "./entities.ts";
import { buildRecord } from "./factory.ts";
import { HttpClient } from "./http.ts";
import { deleteRule } from "./rules.ts";
import { waitForServer } from "./server.ts";

export interface TrackedRecord {
  entity: string;
  id: string;
}

class TestHarness {
  readonly client = new HttpClient();

  private ready: Promise<void> | null = null;
  private records: TrackedRecord[] = [];
  private ruleIds: string[] = [];
  private parentCache = new Map<string, string[]>();

  user: SessionUser | null = null;

  /**
   * Wait for the server, sign in, and confirm the session works. Safe to call
   * from every suite — the work happens once per process.
   */
  setup(): Promise<void> {
    if (!this.ready) {
      this.ready = this.doSetup().catch((error) => {
        // Reset so a later suite can retry rather than inheriting a poisoned promise.
        this.ready = null;
        throw error;
      });
    }
    return this.ready;
  }

  private async doSetup(): Promise<void> {
    await waitForServer();
    this.user = await login(this.client);
  }

  /** Register a record for deletion at teardown. */
  track(entity: string, id: string): void {
    if (id) this.records.push({ entity, id });
  }

  /** Register a rule for deactivation at teardown. */
  trackRule(id: string): void {
    if (id) this.ruleIds.push(id);
  }

  /** Create a record through the API and track it. */
  async create(
    entity: EntityMeta,
    payload: Record<string, unknown>
  ): Promise<Record<string, unknown>> {
    const response = await this.client.post<Record<string, unknown>>(
      `/bus/${entity.route}`,
      payload
    );
    const id = response.data?.id as string | undefined;
    if (id) this.track(entity.route, id);
    return response.data;
  }

  /**
   * Create a record with its foreign keys satisfied, creating parent records
   * first when none exist yet. Returns null when a required parent could not
   * be produced (a cyclic or unsatisfiable model).
   */
  async createWithParents(
    entity: EntityMeta,
    overrides: Record<string, unknown> = {},
    depth = 0
  ): Promise<Record<string, unknown> | null> {
    if (depth > 4) return null;

    const foreignKeys: Record<string, string> = {};
    const distinct = distinctParentColumns(entity, overrides);
    for (const fk of foreignKeyFields(entity)) {
      const parent = this.resolveParentEntity(fk.name);
      if (!parent) {
        // A required reference whose parent the model never declared (EML502):
        // nothing to look up, and the column is NOT NULL, so give it a uuid.
        if (fk.required) foreignKeys[fk.name] = randomUUID();
        continue;
      }

      const existing = await this.parentIdFor(fk, parent, depth + 1, distinct.has(fk.name));
      if (existing) foreignKeys[fk.name] = existing;
    }

    const payload = buildRecord(entity, { foreignKeys, overrides });
    try {
      return await this.create(entity, payload);
    } catch {
      // Retry with only the required fields — some models reject optional
      // combinations that the factory happily invents.
      const minimal = buildRecord(entity, { foreignKeys, overrides, requiredOnly: true });
      try {
        return await this.create(entity, minimal);
      } catch {
        return null;
      }
    }
  }

  /**
   * A payload that should satisfy every validation rule: scalars from the
   * factory plus real foreign-key values resolved from existing parents.
   *
   * Use this instead of a bare `buildRecord()` whenever a test asserts that a
   * record is *valid* — `buildRecord()` deliberately leaves foreign keys unset,
   * which trips the required-field rule on entities that have mandatory FKs.
   */
  async buildValidRecord(
    entity: EntityMeta,
    overrides: Record<string, unknown> = {}
  ): Promise<Record<string, unknown>> {
    const foreignKeys: Record<string, string> = {};
    const distinct = distinctParentColumns(entity, overrides);

    for (const fk of foreignKeyFields(entity)) {
      const parent = this.resolveParentEntity(fk.name);
      if (!parent) {
        if (fk.required) foreignKeys[fk.name] = randomUUID();
        continue;
      }
      const id = await this.parentIdFor(fk, parent, 0, distinct.has(fk.name));
      if (id) foreignKeys[fk.name] = id;
    }

    return buildRecord(entity, { foreignKeys, overrides });
  }

  /**
   * The parent a foreign key should point at.
   *
   * A unique reference is a one-to-one extension (a Doctor *is* a Staff member):
   * each record needs a parent of its own, and reusing one answers the second
   * create with 409. Any other reference may share a parent — unless the entity
   * declares the reference unique *together with* others (`distinct`), where a
   * second record on the same parent writes the same pair and is refused too.
   */
  async parentIdFor(
    fk: FieldMeta,
    parent: EntityMeta,
    depth: number,
    distinct = false
  ): Promise<string | null> {
    if (fk.unique || distinct) {
      const created = await this.createWithParents(parent, {}, depth);
      const id = created?.id as string | undefined;
      return id ?? null;
    }
    return this.anyRecordId(parent, depth);
  }

  /** An existing record id for an entity, creating one if the table is empty. */
  async anyRecordId(entity: EntityMeta, depth = 0): Promise<string | null> {
    const cached = this.parentCache.get(entity.route);
    if (cached && cached.length > 0) {
      return cached[Math.floor(Math.random() * cached.length)] ?? null;
    }

    const listed = await this.client.get<{ data?: Array<{ id: string }> }>(
      `/bus/${entity.route}?limit=25`,
      { allowFailure: true }
    );
    const ids = (listed.ok ? (listed.data?.data ?? []) : []).map((row) => row.id).filter(Boolean);

    if (ids.length > 0) {
      this.parentCache.set(entity.route, ids);
      return ids[0] ?? null;
    }

    if (depth > 3) return null;
    const created = await this.createWithParents(entity, {}, depth + 1);
    const id = created?.id as string | undefined;
    if (id) this.parentCache.set(entity.route, [id]);
    return id ?? null;
  }

  /**
   * Map a foreign-key column (`customer_id`) to its entity.
   *
   * A `_by` column points at a user, so it resolves to the user entity rather
   * than to the table its name would suggest — there is no `bus_reported_by`.
   * Getting this wrong leaves a mandatory FK unset and every create in the
   * suite fails validation.
   *
   * The resolution itself lives in `entities.ts` because the seeding order is
   * derived from the same edges: whatever this maps a column to is the entity
   * that has to exist first.
   */
  resolveParentEntity(columnName: string): EntityMeta | null {
    return parentEntityForColumn(columnName);
  }

  /** Entities ordered parents-first — the safe creation order. */
  orderedEntities(): EntityMeta[] {
    return topologicalEntities();
  }

  /** Forget cached parent ids (call after a bulk delete). */
  invalidateCache(): void {
    this.parentCache.clear();
  }

  /**
   * Delete every tracked record and deactivate every tracked rule.
   * Failures are swallowed: teardown must not mask a real test failure.
   */
  async teardown(): Promise<void> {
    for (const id of this.ruleIds.splice(0).reverse()) {
      try {
        await deleteRule(this.client, id);
      } catch {
        // best effort
      }
    }

    for (const record of this.records.splice(0).reverse()) {
      try {
        await this.client.delete(`/bus/${record.entity}/${record.id}`, { allowFailure: true });
      } catch {
        // best effort
      }
    }

    this.invalidateCache();
  }

  get trackedCount(): number {
    return this.records.length;
  }
}

/** Shared per-process harness. */
export const harness = new TestHarness();

tanstack-start-nestjs/tests/harness/enti:
/**
 * Entity registry — generated from the ERD.
 *
 * This is the single source of truth the suites iterate over. Every entity in
 * the model appears here with the field metadata the factory needs to invent
 * realistic values and the relationship metadata the workflow suite needs to
 * wire records together.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { refusals, stateMachines } from "./model.ts";

export type FieldType =
  | "string"
  | "integer"
  | "decimal"
  | "boolean"
  | "date"
  | "datetime"
  | "text"
  | "json";

export interface FieldMeta {
  /** Physical column name — what the API expects in a payload. */
  name: string;
  /** Human-readable label from the Application Dictionary. */
  displayName: string;
  type: FieldType;
  required: boolean;
  unique: boolean;
  /** True for *_id columns that point at another bus_ table. */
  isForeignKey: boolean;
  maxLength?: number;
  /**
   * The values a `%%enum` binds to this column, in declaration order.
   *
   * The factory draws from these rather than inventing a status vocabulary of
   * its own. Without them it wrote `active` / `pending` / `closed` / `draft`
   * into every column called `status`, whatever the model declared — so a
   * suite's own fixtures put values in the database that the dictionary does
   * not offer and no state machine has an edge out of.
   */
  enumValues?: string[];
  /**
   * A ceiling the model's own rules put on this column: a `validation-error`
   * rule refuses any save above it, so a number the factory invents stays under.
   */
  maxValue?: number;
}

export interface EntityMeta {
  /** ERD entity name, e.g. "Customer". */
  name: string;
  /** Physical table, e.g. "bus_customer" — the identifier the rules API uses. */
  tableName: string;
  /** Path segment for /api/bus/:entity. */
  route: string;
  displayName: string;
  primaryKey: string;
  /**
   * The entity this one is a line item of, from `%%entity <E> parent: <P>`.
   *
   * Carried from the model rather than read back from the dictionary the same
   * generator wrote — a suite that asks the application what it did and then
   * checks that answer against itself proves only self-consistency.
   */
  parentEntity?: string;
  /** The child's foreign key back to `parentEntity`. */
  parentLinkColumn?: string;
  /**
   * Each unique index over more than one column, from `%%index E(a, b) unique`.
   * The pair is unique, not either column, so a suite has to vary one of them.
   */
  uniqueTogether?: string[][];
  fields: FieldMeta[];
}

export interface RelationshipMeta {
  name: string;
  sourceEntity: string;
  targetEntity: string;
  cardinality: "oneToOne" | "oneToMany" | "manyToOne" | "manyToMany";
  foreignKey?: string;
}

/**
 * Columns the server owns — never sent in a create/update payload.
 *
 * `is_active` is deliberately NOT here. The generator does not add it: when a
 * bus table has one it is because the model declared it, often as a required
 * field. Excluding it meant the harness could never build a valid payload for
 * those entities, and every create in the suite failed on a missing field the
 * factory was forbidden from supplying.
 */
export const SERVER_MANAGED_FIELDS = new Set([
  "id",
  "created_at",
  "updated_at",
  "deleted_at",
  "created_by",
  "updated_by",
  "version",
  "doc_status",
]);

export const entities: EntityMeta[] = [
{{#each entities}}
  {
    name: "{{name}}",
    tableName: "{{tableName}}",
    route: "{{tableName}}",
    displayName: "{{displayName}}",
    primaryKey: "{{primaryKey}}",
{{#if parentEntity}}
    parentEntity: "{{parentEntity}}",
{{/if}}
{{#if parentLinkColumn}}
    parentLinkColumn: "{{parentLinkColumn}}",
{{/if}}
{{#if uniqueTogether}}
    uniqueTogether: [{{#each uniqueTogether}}[{{#each this}}"{{this}}"{{#unless @last}}, {{/unless}}{{/each}}]{{#unless @last}}, {{/unless}}{{/each}}],
{{/if}}
    fields: [
{{#each attributes}}
      {
        name: "{{columnName}}",
        displayName: "{{displayName}}",
        type: "{{type}}",
        required: {{#if required}}true{{else}}false{{/if}},
        unique: {{#if unique}}true{{else}}false{{/if}},
        isForeignKey: {{#if isForeignKey}}true{{else}}false{{/if}},
{{#if maxLength}}
        maxLength: {{maxLength}},
{{/if}}
{{#if enumValues}}
        enumValues: [{{#each enumValues}}"{{this}}"{{#unless @last}}, {{/unless}}{{/each}}],
{{/if}}
{{#if maxValue}}
        maxValue: {{maxValue}},
{{/if}}
      },
{{/each}}
    ],
  },
{{/each}}
];

export const relationships: RelationshipMeta[] = [
{{#each relationships}}
  {
    name: "{{name}}",
    sourceEntity: "{{sourceEntity}}",
    targetEntity: "{{targetEntity}}",
    cardinality: "{{cardinality}}",
{{#if foreignKey}}
    foreignKey: "{{foreignKey}}",
{{/if}}
  },
{{/each}}
];

/**
 * The state field of every entity with a state machine, as `table.column`.
 * System-managed: only the application's workflows write it, so no client does.
 */
const STATE_FIELDS = new Set(
  stateMachines.map((machine) => `${machine.tableName}.${machine.statusField}`)
);

/** Is this the entity's state field — the column only workflows may change? */
export function isStateField(entity: EntityMeta, field: string): boolean {
  return STATE_FIELDS.has(`${entity.tableName}.${field}`);
}

/** Fields a client is allowed to write. A state field is not one of them. */
export function writableFields(entity: EntityMeta): FieldMeta[] {
  return entity.fields.filter(
    (f) => !SERVER_MANAGED_FIELDS.has(f.name) && !isStateField(entity, f.name)
  );
}

/** Writable fields excluding foreign keys — safe to populate without existing parents. */
export function scalarFields(entity: EntityMeta): FieldMeta[] {
  return writableFields(entity).filter((f) => !f.isForeignKey && !f.name.endsWith("_id"));
}

export function foreignKeyFields(entity: EntityMeta): FieldMeta[] {
  return writableFields(entity).filter((f) => f.isForeignKey || f.name.endsWith("_id"));
}

/** Every column that is part of a unique index spanning several columns. */
export function compositeUniqueColumns(entity: EntityMeta): Set<string> {
  return new Set((entity.uniqueTogether ?? []).flat());
}

/**
 * The reference columns that must point at a record of their own.
 *
 * `BookingShipment(booking_id, shipment_id) unique` made of references alone is
 * only satisfied by a pair no earlier record used, and the cheapest way to get
 * one is a new parent for the first column. A pair that includes a plain column
 * (`VoyageCall(voyage_id, sequence_number)`) is satisfied by varying that column
 * instead — the factory does — unless the caller has pinned it, in which case
 * the parent is what has to differ.
 */
export function distinctParentColumns(
  entity: EntityMeta,
  overrides: Record<string, unknown> = {}
): Set<string> {
  const references = new Set(foreignKeyFields(entity).map((field) => field.name));
  const distinct = new Set<string>();
  for (const columns of entity.uniqueTogether ?? []) {
    const first = columns.find((column) => references.has(column));
    if (!first) continue;
    const pinned = columns.some((column) => !references.has(column) && column in overrides);
    if (pinned || columns.every((column) => references.has(column))) distinct.add(first);
  }
  return distinct;
}

/**
 * Columns whose contents the model constrains to a shape. Tests write arbitrary
 * markers into a text field to assert round-tripping and search, so a column
 * with a format rule is the wrong one to pick — writing `e2e-1785…` into
 * `email` trips the email-format rule and the create is rejected.
 */
const FORMATTED_TEXT_COLUMNS = /email|url|website|link|phone|mobile|tel|slug|signature|^status$|^doc_status$/i;

/**
 * The first free-text field, used for search and update assertions.
 *
 * A column the model bound to a `%%enum` is never free text, whatever its
 * declared type: its values are a closed list, and a marker like
 * `patched-1788484020307` is not one of them. Suites stamp markers into
 * whatever this returns, so handing them an enum column means every such write
 * is refused — and, before the API validated enums, meant every such write
 * *succeeded* and put an illegal value in the column. Excluded outright rather
 * than ranked below the others: falling back to one is the same mistake made
 * later.
 *
 * An entity whose only text column is enumerated therefore has no free-text
 * field, and the suites that need one skip. That is a real gap in what can be
 * asserted about that entity, and a smaller one than writing values its own
 * dictionary refuses.
 */
export function firstTextField(entity: EntityMeta): FieldMeta | undefined {
  const textish = scalarFields(entity).filter(
    (f) =>
      (f.type === "string" || f.type === "text") &&
      !(f.enumValues && f.enumValues.length > 0)
  );
  // A column a refusing rule reads is not safe to overwrite with an invented
  // string: `status == "pending" and final_grade != null` is refused, so a suite
  // that patches `final_grade` on a pending record is testing the rule, not the
  // update. Prefer a column no refusal mentions.
  const ruled = columnsNamedByRefusals(entity.tableName);
  const calm = textish.filter((f) => !ruled.has(f.name));
  return (
    calm.find((f) => !FORMATTED_TEXT_COLUMNS.test(f.name)) ??
    calm[0] ??
    textish.find((f) => !FORMATTED_TEXT_COLUMNS.test(f.name)) ??
    // Every remaining text column is format-constrained — fall back rather
    // than skip the assertion entirely; a create that trips a format rule is a
    // smaller loss than a silent gap in coverage.
    textish[0]
  );
}

/** Every identifier the model's refusing rules for a table mention. */
function columnsNamedByRefusals(tableName: string): Set<string> {
  const named = new Set<string>();
  for (const refusal of refusals) {
    if (refusal.tableName !== tableName) continue;
    for (const word of refusal.when.match(/[A-Za-z_][A-Za-z0-9_]*/g) ?? []) named.add(word);
  }
  return named;
}

export function numericFields(entity: EntityMeta): FieldMeta[] {
  return scalarFields(entity).filter((f) => f.type === "integer" || f.type === "decimal");
}

/**
 * A number a suite may pin to an exact value.
 *
 * A column a refusing rule reads is not safe to overwrite: `planned_packages !=
 * delivered_packages + short_packages` is refused, so pinning one of the four
 * quantities on a delivery line makes the record the rule refuses, and no
 * choice of the others is guaranteed to put it right. Undefined when every
 * numeric column is ruled — the assertion that needs one skips, as it does for
 * an entity with no free-text column.
 */
export function firstUnruledNumericField(entity: EntityMeta): FieldMeta | undefined {
  const ruled = columnsNamedByRefusals(entity.tableName);
  return numericFields(entity).find((f) => !ruled.has(f.name));
}

export function getEntity(name: string): EntityMeta {
  const found = entities.find(
    (e) => e.name === name || e.tableName === name || e.route === name
  );
  if (!found) throw new Error(`Unknown entity "${name}"`);
  return found;
}

const FK_COLUMN_TABLE_MAP: Record<string, string> = {
{{#each fkOverrides}}
  '{{column}}': '{{table}}',
{{/each}}
};

export function parentEntityForColumn(columnName: string): EntityMeta | null {
  const findByTable = (table: string): EntityMeta | null =>
    entities.find((e) => e.tableName === table) ?? null;

  const findByStem = (stem: string): EntityMeta | null =>
    entities.find(
      (e) =>
        e.route === stem ||
        e.tableName === `bus_${stem}` ||
        e.name.toLowerCase() === stem.toLowerCase()
    ) ?? null;

  if (FK_COLUMN_TABLE_MAP[columnName]) {
    return findByTable(FK_COLUMN_TABLE_MAP[columnName]);
  }

  if (columnName.endsWith("_by_id") || columnName.endsWith("_by")) {
    for (const suffix of ["_by_id", "_by"]) {
      if (!columnName.endsWith(suffix)) continue;
      const stem = columnName.slice(0, -suffix.length);
      const entity = findByStem(stem);
      if (entity) return entity;
    }
    return findByStem("user") ?? findByStem("staff");
  }

  if (!columnName.endsWith("_id")) return null;
  return findByStem(columnName.slice(0, -3));
}

/**
 * Entities ordered so that a record's foreign-key targets are created first.
 * Falls back to declaration order for cycles.
 *
 * Edges come from the FK *columns*, not only from the ERD's declared
 * relationships: conventions like `registered_by_id → user` create a real
 * ordering constraint that no relationship line in the diagram records. Seeding
 * by the declared graph alone put the child first and every insert was rejected
 * for a missing required parent.
 */
export function topologicalEntities(): EntityMeta[] {
  const byName = new Map(entities.map((e) => [e.name, e]));
  const dependencies = new Map<string, Set<string>>();

  for (const entity of entities) {
    dependencies.set(entity.name, new Set());
  }
  for (const entity of entities) {
    for (const fk of foreignKeyFields(entity)) {
      const parent = parentEntityForColumn(fk.name);
      if (parent && parent.name !== entity.name) {
        dependencies.get(entity.name)?.add(parent.name);
      }
    }
  }
  for (const rel of relationships) {
    // manyToOne / oneToOne: the source holds the FK, so the target must exist first.
    if (rel.cardinality === "manyToOne" || rel.cardinality === "oneToOne") {
      dependencies.get(rel.sourceEntity)?.add(rel.targetEntity);
    } else if (rel.cardinality === "oneToMany") {
      dependencies.get(rel.targetEntity)?.add(rel.sourceEntity);
    }
  }

  const ordered: EntityMeta[] = [];
  const visited = new Set<string>();
  const visiting = new Set<string>();

  const visit = (name: string): void => {
    if (visited.has(name) || visiting.has(name)) return;
    visiting.add(name);
    for (const dep of dependencies.get(name) ?? []) {
      if (dep !== name) visit(dep);
    }
    visiting.delete(name);
    visited.add(name);
    const entity = byName.get(name);
    if (entity) ordered.push(entity);
  };

  for (const entity of entities) visit(entity.name);
  return ordered;
}

tanstack-start-nestjs/tests/harness/http:
/**
 * HTTP client with a cookie jar.
 *
 * better-auth issues an httpOnly session cookie on sign-in; `fetch` does not
 * persist cookies on its own, so the jar here is what keeps a suite logged in
 * across requests.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { config } from "./config.ts";
import { classify, record, recordPromotion } from "./metrics.ts";
import { sleep } from "./testing.ts";

export interface ApiResponse<T = unknown> {
  status: number;
  ok: boolean;
  data: T;
  headers: Headers;
  /** Raw body, kept for error reporting when the payload is not JSON. */
  raw: string;
}

export class HttpError extends Error {
  readonly status: number;
  readonly body: unknown;
  readonly method: string;
  readonly path: string;

  // Fields and assignments rather than parameter properties: Node runs these
  // files by stripping the types out, which can only remove syntax, and a
  // parameter property is syntax that also *does* something.
  constructor(message: string, status: number, body: unknown, method: string, path: string) {
    super(message);
    this.name = "HttpError";
    this.status = status;
    this.body = body;
    this.method = method;
    this.path = path;
  }
}

/** A minimal cookie jar — name → value, last write wins. */
export class CookieJar {
  private cookies = new Map<string, string>();

  absorb(headers: Headers): void {
    // getSetCookie() keeps multiple Set-Cookie headers separate; the joined
    // `get("set-cookie")` form would mangle cookies whose values contain commas.
    const raw =
      typeof headers.getSetCookie === "function"
        ? headers.getSetCookie()
        : [headers.get("set-cookie")].filter((v): v is string => !!v);

    for (const entry of raw) {
      const pair = entry.split(";", 1)[0];
      if (!pair) continue;
      const eq = pair.indexOf("=");
      if (eq <= 0) continue;
      const name = pair.slice(0, eq).trim();
      const value = pair.slice(eq + 1).trim();
      // An expired cookie is a deletion instruction, not a value to keep.
      if (value === "" || /expires=Thu, 01 Jan 1970/i.test(entry)) {
        this.cookies.delete(name);
      } else {
        this.cookies.set(name, value);
      }
    }
  }

  header(): string {
    return [...this.cookies.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
  }

  get size(): number {
    return this.cookies.size;
  }

  clear(): void {
    this.cookies.clear();
  }
}

export interface RequestOptions {
  /** Skip the api prefix — used for better-auth routes that sit at /api/auth/*. */
  absolute?: boolean;
  headers?: Record<string, string>;
  /** Do not throw on a non-2xx status; return the response for assertion. */
  allowFailure?: boolean;
  timeoutMs?: number;
  /**
   * Do not transparently retry a 429. Set this when a test is *asserting* on
   * throttling behaviour and wants the raw response.
   */
  noThrottleRetry?: boolean;
}

export class HttpClient {
  readonly jar = new CookieJar();

  private readonly baseUrl: string;

  constructor(baseUrl: string = config.baseUrl) {
    this.baseUrl = baseUrl;
  }

  private url(path: string, absolute = false): string {
    if (path.startsWith("http://") || path.startsWith("https://")) return path;
    const prefixed = absolute ? path : `${config.apiPrefix}${path.startsWith("/") ? path : `/${path}`}`;
    return `${this.baseUrl}${prefixed}`;
  }

  /**
   * Send a request, transparently waiting out the backend's rate limiter.
   *
   * The generated app throttles to `THROTTLE_LIMIT` requests per window
   * (1000/60s in development). Bulk seeding legitimately exceeds that, and a
   * 429 there is back-pressure, not a failure — so we honour `Retry-After` and
   * try again rather than reporting thousands of spurious rejections.
   */
  async request<T = unknown>(
    method: string,
    path: string,
    body?: unknown,
    options: RequestOptions = {}
  ): Promise<ApiResponse<T>> {
    // Timed here, around the whole call: this is the one place every suite's
    // traffic passes through, so instrumenting it cannot be forgotten in a
    // suite written later.
    const startedAt = performance.now();
    let throttled = false;
    let response = await this.send<T>(method, path, body, options);

    if (options.noThrottleRetry) {
      this.meter(method, path, response, startedAt);
      return this.finish(response, method, path, options);
    }

    for (let attempt = 0; response.status === 429 && attempt < config.throttleRetries; attempt++) {
      const header = Number(response.headers.get("retry-after"));
      // Retry-After is in seconds; fall back to a growing pause when absent.
      const waitMs = Number.isFinite(header) && header > 0
        ? header * 1000
        : Math.min(config.throttleBackoffMs * 2 ** attempt, 30_000);

      if (config.verbose) {
        console.log(`  ⏳ 429 on ${method} ${path} — waiting ${waitMs}ms (attempt ${attempt + 1})`);
      }
      await sleep(waitMs);
      throttled = true;
      response = await this.send<T>(method, path, body, options);
    }

    if (!throttled) this.meter(method, path, response, startedAt);
    return this.finish(response, method, path, options);
  }

  /**
   * Record what this call did, if it did anything worth averaging.
   *
   * Only successful business-entity writes: a rejected insert measures the
   * validator, not the insert, and averaging the two together would describe
   * neither. Requests that waited out a 429 are also skipped — their elapsed
   * time is mostly the back-off, which says nothing about how fast the
   * application is.
   */
  private meter(method: string, path: string, response: ApiResponse<unknown>, startedAt: number): void {
    if (!response.ok) return;

    const classified = classify(method, path);
    if (!classified) return;

    record({ op: classified.op, ms: performance.now() - startedAt, name: classified.name });
    // The server reports which rules and workflows the write set off, so they
    // are counted from its own account rather than inferred from the model.
    recordPromotion(response.data);
  }

  private finish<T>(
    response: ApiResponse<T>,
    method: string,
    path: string,
    options: RequestOptions
  ): ApiResponse<T> {
    if (!response.ok && !options.allowFailure) {
      const snippet = response.raw.length > 400 ? `${response.raw.slice(0, 400)}…` : response.raw;
      throw new HttpError(
        `${method} ${path} → ${response.status}: ${snippet}`,
        response.status,
        response.data,
        method,
        path
      );
    }
    return response;
  }

  private async send<T = unknown>(
    method: string,
    path: string,
    body: unknown,
    options: RequestOptions
  ): Promise<ApiResponse<T>> {
    const url = this.url(path, options.absolute);
    const headers: Record<string, string> = {
      Accept: "application/json",
      Origin: config.origin,
      ...options.headers,
    };

    if (body !== undefined && !headers["Content-Type"]) {
      headers["Content-Type"] = "application/json";
    }

    const cookie = this.jar.header();
    if (cookie) headers.Cookie = cookie;

    const controller = new AbortController();
    const timeout = setTimeout(
      () => controller.abort(),
      options.timeoutMs ?? config.requestTimeoutMs
    );

    let response: Response;
    try {
      response = await fetch(url, {
        method,
        headers,
        body: body === undefined ? undefined : JSON.stringify(body),
        signal: controller.signal,
        redirect: "manual",
      });
    } catch (error) {
      clearTimeout(timeout);
      const reason = error instanceof Error ? error.message : String(error);
      throw new HttpError(`${method} ${url} failed: ${reason}`, 0, null, method, path);
    }
    clearTimeout(timeout);

    this.jar.absorb(response.headers);

    const raw = await response.text();
    let data: unknown = null;
    if (raw.length > 0) {
      try {
        data = JSON.parse(raw);
      } catch {
        data = raw;
      }
    }

    if (config.verbose) {
      console.log(`  → ${method} ${path} ${response.status}`);
    }

    return {
      status: response.status,
      ok: response.ok,
      data: data as T,
      headers: response.headers,
      raw,
    };
  }

  get<T = unknown>(path: string, options?: RequestOptions) {
    return this.request<T>("GET", path, undefined, options);
  }

  post<T = unknown>(path: string, body?: unknown, options?: RequestOptions) {
    return this.request<T>("POST", path, body, options);
  }

  put<T = unknown>(path: string, body?: unknown, options?: RequestOptions) {
    return this.request<T>("PUT", path, body, options);
  }

  patch<T = unknown>(path: string, body?: unknown, options?: RequestOptions) {
    return this.request<T>("PATCH", path, body, options);
  }

  delete<T = unknown>(path: string, options?: RequestOptions) {
    return this.request<T>("DELETE", path, undefined, options);
  }
}

tanstack-start-nestjs/tests/harness/test:
/**
 * The test vocabulary these suites are written in.
 *
 * They used to import it from `bun:test`, which meant the application could not
 * be tested without Bun — awkward for a stack whose whole point is running under
 * Node with PostgreSQL compiled to WebAssembly, and the last thing keeping Bun
 * in a generated wasm application at all.
 *
 * `node:test` supplies the runner. What it does not supply is `expect`, so the
 * choice was to rewrite four hundred assertions into `assert.strictEqual` or to
 * write the twenty lines below. The assertions are the readable part of a test
 * suite; a mechanical rewrite of all of them would have been a large diff that
 * made every one of them worse.
 *
 * So this is `expect` with exactly the matchers these suites use — and it fails
 * loudly on any matcher it does not have, rather than quietly passing. Both
 * runners understand `node:test`, so `bun test` still works for anyone on the
 * Bun stack and `node --test` works for everyone else.
 */

import { after, before, beforeEach, describe, it as nodeIt } from "node:test";

// `before`/`after` in node:test run once per file, which is what `beforeAll`
// and `afterAll` meant in bun:test. Re-exported under both names so the suites
// read the same as they did.
export { describe, beforeEach, before as beforeAll, after as afterAll, before, after };

type TestBody = () => void | Promise<void>;

/**
 * `it`, in the two shapes these suites already use.
 *
 * bun:test takes a timeout as a third positional argument and offers
 * `it.skipIf(condition)`; node:test takes an options object and offers neither.
 * Translating here rather than rewriting sixty call sites keeps the suites
 * readable and keeps the difference between the two runners in one place — and
 * a suite that quietly lost its timeout would not fail, it would flake.
 */
interface It {
  (name: string, body: TestBody, timeoutMs?: number): void;
  skip: (name: string, body?: TestBody, timeoutMs?: number) => void;
  only: (name: string, body: TestBody, timeoutMs?: number) => void;
  todo: (name: string, body?: TestBody) => void;
  /** `it.skipIf(cond)("…", fn)` — skip when the condition holds. */
  skipIf: (condition: unknown) => It;
}

function make(runner: typeof nodeIt, skipAll: boolean): It {
  const call = ((name: string, body: TestBody, timeoutMs?: number) => {
    const options = {
      ...(typeof timeoutMs === "number" ? { timeout: timeoutMs } : {}),
      ...(skipAll ? { skip: true } : {}),
    };
    runner(name, options, body);
  }) as It;

  call.skip = (name, body, timeoutMs) =>
    runner(name, { skip: true, ...(typeof timeoutMs === "number" ? { timeout: timeoutMs } : {}) },
      body ?? (() => {}));
  call.only = (name, body, timeoutMs) =>
    runner(name, { only: true, ...(typeof timeoutMs === "number" ? { timeout: timeoutMs } : {}) },
      body);
  call.todo = (name, body) => runner(name, { todo: true }, body ?? (() => {}));
  call.skipIf = (condition) => (condition ? make(runner, true) : call);
  return call;
}

export const it: It = make(nodeIt, false);
/** Some suites spell it `test`; both are the same thing. */
export const test: It = it;

/** `Bun.sleep`, without Bun. */
export const sleep = (ms: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, ms));

function show(value: unknown): string {
  if (typeof value === "string") return JSON.stringify(value);
  if (value instanceof Error) return value.message;
  try {
    const text = JSON.stringify(value);
    return text === undefined ? String(value) : text.length > 300 ? `${text.slice(0, 300)}…` : text;
  } catch {
    return String(value);
  }
}

function fail(
  actual: unknown,
  matcher: string,
  expected?: unknown,
  negated = false,
  message?: string
): never {
  const not = negated ? "not " : "";
  const tail = expected === undefined ? "" : ` ${show(expected)}`;
  const because = message ? `${message}: ` : "";
  throw new Error(`${because}expected ${show(actual)} ${not}${matcher}${tail}`);
}

/** Structural equality, deep enough for JSON the API returned. */
function deepEqual(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null) return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const [ka, kb] = [Object.keys(a as object), Object.keys(b as object)];
  if (ka.length !== kb.length) return false;
  return ka.every((key) =>
    deepEqual((a as Record<string, unknown>)[key], (b as Record<string, unknown>)[key])
  );
}

function has(container: unknown, item: unknown): boolean {
  if (typeof container === "string") return container.includes(String(item));
  if (Array.isArray(container)) return container.some((entry) => deepEqual(entry, item));
  return false;
}

function lengthOf(value: unknown): number | null {
  if (typeof value === "string" || Array.isArray(value)) return value.length;
  return null;
}

function build(actual: unknown, negated: boolean, message?: string) {
  const check = (ok: boolean, matcher: string, expected?: unknown) => {
    if (ok === negated) fail(actual, matcher, expected, negated, message);
  };
  const asNumber = (matcher: string): number => {
    if (typeof actual !== "number") fail(actual, `be a number to ${matcher}`, undefined, false, message);
    return actual;
  };

  return {
    toBe: (expected: unknown) => check(Object.is(actual, expected), "to be", expected),
    toEqual: (expected: unknown) => check(deepEqual(actual, expected), "to equal", expected),
    toBeTruthy: () => check(Boolean(actual), "to be truthy"),
    toBeFalsy: () => check(!actual, "to be falsy"),
    toBeNull: () => check(actual === null, "to be null"),
    toBeUndefined: () => check(actual === undefined, "to be undefined"),
    toBeDefined: () => check(actual !== undefined, "to be defined"),
    toContain: (item: unknown) => check(has(actual, item), "to contain", item),
    toMatch: (pattern: RegExp | string) =>
      check(
        typeof pattern === "string"
          ? String(actual).includes(pattern)
          : pattern.test(String(actual)),
        "to match",
        String(pattern)
      ),
    toHaveLength: (length: number) =>
      check(lengthOf(actual) === length, "to have length", length),
    toBeGreaterThan: (n: number) => check(asNumber("compare") > n, "to be greater than", n),
    toBeGreaterThanOrEqual: (n: number) =>
      check(asNumber("compare") >= n, "to be greater than or equal to", n),
    toBeLessThan: (n: number) => check(asNumber("compare") < n, "to be less than", n),
    toBeLessThanOrEqual: (n: number) =>
      check(asNumber("compare") <= n, "to be less than or equal to", n),
    toBeInstanceOf: (constructor: abstract new (...args: never) => unknown) =>
      check(actual instanceof constructor, "to be an instance of", constructor.name),
    toThrow: () => {
      if (typeof actual !== "function") fail(actual, "be a function to throw");
      let threw = false;
      try {
        (actual as () => unknown)();
      } catch {
        threw = true;
      }
      check(threw, "to throw");
    },
  };
}

/**
 * `expect(value)`, optionally with a sentence saying what was being asserted.
 *
 * The message is the difference between "expected false to be true" — which
 * names neither the entity nor the property — and a line a reader can act on
 * without opening the suite. The signature matches the one every other runner
 * uses, so a case moved here from Vitest or Playwright keeps its message.
 */
export function expect(actual: unknown, message?: string) {
  return { ...build(actual, false, message), not: build(actual, true, message) };
}

tanstack-start-nestjs/tests/harness/mani:
/**
 * Seed manifest.
 *
 * The bulk-seed suite deliberately leaves its records in the database for the
 * rules and workflow suites that follow, so nothing tracks them for teardown.
 * This manifest is what makes that reversible: every id the seeder creates is
 * recorded here, and `cleanup.ts` deletes exactly those rows — leaving the
 * application's own seed data (roles, admin user, dictionary) untouched.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { existsSync } from "node:fs";
import { readFile, unlink, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

// `import.meta.dir` is Bun's; `import.meta.url` is the standard both runtimes
// provide, and this file has to load under either.
const here = dirname(fileURLToPath(import.meta.url));

export const MANIFEST_PATH = join(here, "..", ".e2e-seed-manifest.json");

export interface SeedManifest {
  /** ISO timestamp of the run that produced this manifest. */
  createdAt: string;
  /** Faker seed used, so a run can be reproduced. */
  fakerSeed: number;
  /** Records requested per entity. */
  recordsPerEntity: number;
  /** entity route → created record ids. */
  records: Record<string, string[]>;
  /** Rule ids created by the suites. */
  ruleIds: string[];
}

function empty(): SeedManifest {
  return {
    createdAt: new Date().toISOString(),
    fakerSeed: 0,
    recordsPerEntity: 0,
    records: {},
    ruleIds: [],
  };
}

export async function readManifest(): Promise<SeedManifest | null> {
  if (!existsSync(MANIFEST_PATH)) return null;
  try {
    const raw = await readFile(MANIFEST_PATH, "utf8");
    const parsed = JSON.parse(raw) as SeedManifest;
    // Tolerate a manifest written by an older version.
    return { ...empty(), ...parsed, records: parsed.records ?? {} };
  } catch {
    return null;
  }
}

/**
 * Merge ids into the manifest on disk. Merging rather than overwriting means a
 * partial re-run adds to the cleanup set instead of orphaning the previous run's
 * rows.
 */
export async function recordSeeded(
  entityRoute: string,
  ids: string[],
  meta: { fakerSeed: number; recordsPerEntity: number }
): Promise<void> {
  const manifest = (await readManifest()) ?? empty();

  manifest.createdAt = new Date().toISOString();
  manifest.fakerSeed = meta.fakerSeed;
  manifest.recordsPerEntity = meta.recordsPerEntity;

  const existing = new Set(manifest.records[entityRoute] ?? []);
  for (const id of ids) existing.add(id);
  manifest.records[entityRoute] = [...existing];

  await writeFile(MANIFEST_PATH, JSON.stringify(manifest, null, 2));
}

export async function recordRules(ids: string[]): Promise<void> {
  if (ids.length === 0) return;
  const manifest = (await readManifest()) ?? empty();
  const existing = new Set(manifest.ruleIds ?? []);
  for (const id of ids) existing.add(id);
  manifest.ruleIds = [...existing];
  await writeFile(MANIFEST_PATH, JSON.stringify(manifest, null, 2));
}

export async function clearManifest(): Promise<void> {
  if (existsSync(MANIFEST_PATH)) await unlink(MANIFEST_PATH);
}

export function totalRecords(manifest: SeedManifest): number {
  return Object.values(manifest.records).reduce((sum, ids) => sum + ids.length, 0);
}

tanstack-start-nestjs/tests/harness/acce:
/**
 * What `%%rbac` declared, and who the application seeded to hold it.
 *
 * Two halves, and the suites need both. `rbacRules` is the model's own word on
 * which roles an `(entity, operation)` pair admits — compiled from the
 * directives, not read back from `sys_operation_access`, so a rule the seed
 * dropped fails a test instead of agreeing with itself. `roleAccounts` is the
 * address the application created for each role, from the same derivation the
 * seed used, so a suite signing in as a role is using the account that exists.
 *
 * A model with no `%%rbac` directives leaves both empty and the access suite
 * skips itself. That is the honest outcome: there is nothing declared to check,
 * and inventing a restriction to test would be testing the test.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

export type RbacOperation = "create" | "read" | "update" | "delete";

export interface RbacRule {
  /** ERD entity name, as the model declares it. */
  entity: string;
  /** Physical table the guard matches on. */
  tableName: string;
  /** Route segment the API is addressed by. */
  route: string;
  operation: RbacOperation;
  /** Roles permitted. Never empty — an empty list would mean "nobody". */
  roles: string[];
}

export interface RoleAccount {
  email: string;
  name: string;
  /** Role as the dictionary spells it, e.g. `Class Manager`. */
  roleName: string;
  /** Role as the model spells it, e.g. `class_manager`. */
  declaredAs: string;
  /** Master roles bypass every operation rule. */
  isAdmin: boolean;
}

export const rbacRules: RbacRule[] = [
{{#each rbacRules}}
  {
    entity: "{{entity}}",
    tableName: "{{tableName}}",
    route: "{{route}}",
    operation: "{{operation}}",
    roles: [{{#each roles}}"{{this}}"{{#unless @last}}, {{/unless}}{{/each}}],
  },
{{/each}}
];

export const roleAccounts: RoleAccount[] = [
{{#each roleAccounts}}
  {
    email: "{{email}}",
    name: "{{name}}",
    roleName: "{{roleName}}",
    declaredAs: "{{declaredAs}}",
    isAdmin: {{#if isAdmin}}true{{else}}false{{/if}},
  },
{{/each}}
];

/** Role names compare case- and separator-insensitively: `class_manager` is `Class Manager`. */
export function sameRole(a: string, b: string): boolean {
  const fold = (value: string) => value.trim().toLowerCase().replace(/[\s\-_]+/g, "");
  return fold(a) === fold(b);
}

/**
 * The roles a pair admits, or `null` when the model restricts it to nobody in
 * particular.
 *
 * `null` is not "denied" — an `(entity, operation)` no directive names is
 * unrestricted, open to anyone the session guard already admitted. Callers that
 * treat the absence of a rule as a denial invert the whole scheme.
 */
export function rolesFor(route: string, operation: RbacOperation): string[] | null {
  const rule = rbacRules.find((item) => item.route === route && item.operation === operation);
  return rule ? rule.roles : null;
}

/** Whether an account may perform an operation, according to the model alone. */
export function modelAllows(
  account: RoleAccount,
  route: string,
  operation: RbacOperation
): boolean {
  if (account.isAdmin) return true;
  const roles = rolesFor(route, operation);
  if (!roles) return true;
  return roles.some((role) => sameRole(role, account.declaredAs) || sameRole(role, account.roleName));
}

/** Every route the model restricts for `read`, which is what scopes navigation. */
export function readRestrictedRoutes(): string[] {
  return [...new Set(rbacRules.filter((rule) => rule.operation === "read").map((r) => r.route))];
}

/** The non-admin accounts, which are the ones a restriction can be observed on. */
export function restrictedAccounts(): RoleAccount[] {
  return roleAccounts.filter((account) => !account.isAdmin);
}

