/**
 * Test harness configuration.
 *
 * Every knob is env-overridable so the same suites run against a locally
 * started app, a docker-compose stack, or CI.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

function int(name: string, fallback: number): number {
  const raw = process.env[name];
  if (!raw) return fallback;
  const parsed = Number(raw);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
}

function str(name: string, fallback: string): string {
  const raw = process.env[name];
  return raw && raw.length > 0 ? raw : fallback;
}

export const config = {
  /** Base URL of the running backend, without a trailing slash. */
  baseUrl: str("E2E_BASE_URL", "http://localhost:{{config.port}}").replace(/\/+$/, ""),

  /** Prefix applied by `app.setGlobalPrefix('api')` in the backend. */
  apiPrefix: "/api",

  /** Frontend origin — sent as the Origin header so CORS + better-auth accept us. */
  origin: str("E2E_ORIGIN", "http://localhost:{{config.frontendPort}}"),

  /**
   * Seeded administrator. Must match the backend bootstrap in `src/main.ts`,
   * which reads ADMIN_EMAIL / ADMIN_PASSWORD and defaults to these values.
   */
  admin: {
    email: str("E2E_ADMIN_EMAIL", process.env.ADMIN_EMAIL ?? "admin@admin.com"),
    password: str("E2E_ADMIN_PASSWORD", process.env.ADMIN_PASSWORD ?? "admin123"),
  },

  /**
   * Records created per entity by the bulk-seed suite.
   *
   * The default is the `--records-per-entity` the application was generated
   * with. It used to be hardcoded to 1000 here, which meant the flag was
   * computed, handed to this template and then dropped — so an application
   * generated with `--records-per-entity 25` still seeded a thousand rows per
   * entity, forty times the volume asked for, and the only way to get the
   * requested number was to say it again at run time.
   *
   * Two presets are wired into the runner:
   *   --small   10   quick smoke run
   *   --full  1000   the full volume run
   *
   * `--records <n>` or E2E_RECORDS_PER_ENTITY overrides it for one run.
   */
  recordsPerEntity: int("E2E_RECORDS_PER_ENTITY", {{config.recordsPerEntity}}),

  /** Named presets the runner exposes as --small / --full. */
  recordPresets: { small: 10, full: 1000 } as const,

  /** Records written per HTTP batch during bulk seeding. */
  seedBatchSize: int("E2E_SEED_BATCH_SIZE", 25),

  /** Extra users created by the users-and-roles suite. */
  usersToCreate: int("E2E_USERS_TO_CREATE", 25),

  /** How many random workflow-triggering mutations the chaos suite performs. */
  randomWorkflowOps: int("E2E_RANDOM_WORKFLOW_OPS", 50),

  /** Faker seed — fixed so a failing run reproduces exactly. */
  fakerSeed: int("E2E_FAKER_SEED", 20260731),

  /** Seconds to wait for the backend to answer its health check. */
  serverReadyTimeoutMs: int("E2E_SERVER_READY_TIMEOUT_MS", 120_000),

  /** Per-request timeout. */
  requestTimeoutMs: int("E2E_REQUEST_TIMEOUT_MS", 30_000),

  /**
   * Default per-test timeout, handed to whichever runner the suite runs under.
   * Both default to 5s, which is too tight once the database holds real volume.
   *
   * 60s was too tight as well, and for a reason worth writing down: a suite
   * that waits on the workflow queue scales with the model. 04-bulk-seed fires
   * every entity's `afterCreate` hooks, so 06-rules-workflow — which runs next
   * and waits for runs to reach a terminal state — queues behind that backlog.
   * On the 19-entity drug-discovery model it ran out of budget at 60s having
   * failed nothing: run alone against the same database it finishes in 2.2s.
   *
   * This is a budget, not a hang detector. `workflowTimeoutMs` below is the
   * guard against a run that never terminates, and `requestTimeoutMs` against a
   * request that never answers; both stay tight. This number only has to exceed
   * their sum for the largest model the suite is generated from.
   */
  suiteTimeoutMs: int("E2E_SUITE_TIMEOUT_MS", {{config.suiteTimeoutMs}}),

  /** Milliseconds to wait for an async workflow run to reach a terminal state. */
  workflowTimeoutMs: int("E2E_WORKFLOW_TIMEOUT_MS", 20_000),

  /**
   * How many times to wait out a 429 before giving up. The backend throttles to
   * THROTTLE_LIMIT requests per window (1000/60s in development), which bulk
   * seeding legitimately exceeds.
   */
  throttleRetries: int("E2E_THROTTLE_RETRIES", 12),

  /** Base backoff when a 429 carries no Retry-After header. */
  throttleBackoffMs: int("E2E_THROTTLE_BACKOFF_MS", 2000),

  /** Set E2E_VERBOSE=1 to log every request. */
  verbose: process.env.E2E_VERBOSE === "1",

  /**
   * How the runner starts the backend, when it starts one.
   *
   * Asked of the runtime rather than written down, because this suite now runs
   * under both: the ordinary stack is installed with Bun and the wasm stack with
   * npm, and naming either here would break the other. What is invoked is the
   * backend's own `start` script, which the wasm overlay has already rewritten
   * to node — so this decides who reads package.json, not what starting means.
   */
  startCommand: (process.env.E2E_START_COMMAND?.split(" ") ??
    (typeof process.versions.bun === "string"
      ? ["bun", "run", "start"]
      : ["npm", "run", "start"])) as string[],
} as const;

export type TestConfig = typeof config;

