/**
 * Business Tables Migration
 * Creates all business entity tables
 *
 * Generated: {{now}}
 */

import { Kysely, sql } from 'kysely';

export async function up(db: Kysely<any>): Promise<void> {
  {{#each entities}}
  // ==========================================================================
  // {{displayName}} ({{tableName}})
  // ==========================================================================
  await sql`
    CREATE TABLE IF NOT EXISTS {{tableName}} (
      {{primaryKey}} UUID PRIMARY KEY DEFAULT gen_random_uuid()
      {{#each attributes}}
      {{!-- The four columns appended below, plus the key: declaring one in the
            model would emit it twice and PostgreSQL refuses the CREATE TABLE. --}}
      {{#unless (or (eq name ../primaryKey) (eq name 'created_at') (eq name 'updated_at') (eq name 'deleted_at') (eq name 'version'))}}
      {{#switch (typeToReferenceId type)}}
        {{#case 10}}
      {{#if isForeignKey}}
      , {{name}} UUID{{#if required}} NOT NULL{{/if}}
      {{else}}
      , {{name}} VARCHAR({{#if maxLength}}{{maxLength}}{{else}}255{{/if}}){{#if required}} NOT NULL{{/if}}{{#if unique}} UNIQUE{{/if}}{{#if default}} DEFAULT '{{default}}'{{/if}}
      {{/if}}
        {{/case}}
        {{#case 11}}
      {{#if isForeignKey}}
      , {{name}} UUID{{#if required}} NOT NULL{{/if}}
      {{else}}
      , {{name}} INTEGER{{#if required}} NOT NULL{{/if}}{{#if default}} DEFAULT {{default}}{{/if}}
      {{/if}}
        {{/case}}
        {{#case 12}}
      , {{name}} DECIMAL(18,6){{#if required}} NOT NULL{{/if}}{{#if default}} DEFAULT {{default}}{{/if}}
        {{/case}}
        {{#case 13}}
      , {{name}} UUID{{#if required}} NOT NULL{{/if}}
        {{/case}}
        {{#case 14}}
      , {{name}} TEXT{{#if required}} NOT NULL{{/if}}
        {{/case}}
        {{#case 15}}
      , {{name}} DATE{{#if required}} NOT NULL{{/if}}
        {{/case}}
        {{#case 16}}
      , {{name}} TIMESTAMPTZ{{#if required}} NOT NULL{{/if}}
        {{/case}}
        {{#case 20}}
      , {{name}} BOOLEAN{{#if required}} NOT NULL{{/if}}{{#if default}} DEFAULT {{default}}{{/if}}
        {{/case}}
        {{#case 30}}
      , {{name}} VARCHAR(255){{#if required}} NOT NULL{{/if}}
        {{/case}}
        {{#case 31}}
      , {{name}} VARCHAR(40){{#if required}} NOT NULL{{/if}}
        {{/case}}
        {{#default}}
      , {{name}} VARCHAR(255){{#if required}} NOT NULL{{/if}}
        {{/default}}
      {{/switch}}
      {{/unless}}
      {{/each}}
      , created_at TIMESTAMPTZ DEFAULT NOW()
      , updated_at TIMESTAMPTZ DEFAULT NOW()
      , deleted_at TIMESTAMPTZ
      , version INTEGER NOT NULL DEFAULT 1
    )
  `.execute(db);

  {{!-- One list: the model's own %%index declarations, including composite
        ones, merged with the conventional single-column indexes. Merged in
        entityToBusEntity so both share a naming scheme without colliding. --}}
  {{#each indexes}}
  await sql`CREATE {{#if unique}}UNIQUE {{/if}}INDEX IF NOT EXISTS idx_{{../tableName}}_{{join columns '_'}} ON {{../tableName}} ({{join columns ', '}})`.execute(db);
  {{/each}}

  {{/each}}

  // Foreign key constraints (added after all tables to avoid ordering issues)
  {{!-- Only where the child really carries the column: see buildFkConstraints. --}}
  {{#each fkConstraints}}
  await sql`
    ALTER TABLE {{childTable}}
    ADD CONSTRAINT {{name}}
      FOREIGN KEY ({{column}})
      REFERENCES {{parentTable}}(id)
      ON DELETE SET NULL ON UPDATE CASCADE
  `.execute(db).catch(() => {});
  {{/each}}
}

export async function down(db: Kysely<any>): Promise<void> {
  {{#each entities}}
  await sql`DROP TABLE IF EXISTS {{tableName}} CASCADE`.execute(db);
  {{/each}}
}

