/**
 * Access grant seed — the model's `%%rbac` directives, made enforceable.
 *
 * Each row of `sys_access_grant` closes one `(table, operation)` pair, or one
 * move of a record's lifecycle, to one role. A pair with no rows is
 * unrestricted, so this seed only ever *narrows*, and only where the model asked
 * for it. A user holding several roles has the union of their grants.
 *
 * Two things happen here, in order:
 *
 *   1. Every role named by a directive is created in `sys_role` if absent, so
 *      an administrator can see and assign it. A rule naming a role that exists
 *      nowhere would otherwise be a restriction no user could ever satisfy.
 *   2. The rules themselves are written, replacing any previous model-declared
 *      set.
 *
 * Step 2 deletes only rows carrying `entity_type = 'D'` (declared by the
 * model). Rules an administrator adds in the running application are marked
 * 'U' and survive regeneration — the same ownership split the workflow
 * definitions use, and for the same reason: regenerating must not silently
 * discard access rules a human wrote.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { sql, type Kysely } from 'kysely';
import { v4 as uuidv4 } from 'uuid';

interface TransitionAccessSeed {
  tableName: string;
  transition: string;
  statusField: string;
  /** `move` along a drawn edge, or `reopen` — a Final record back to Draft. */
  edges: Array<{ from: string; to: string; kind: 'move' | 'reopen' }>;
  roles: string[];
}

interface OperationAccessSeed {
  tableName: string;
  operation: 'create' | 'read' | 'update' | 'delete';
  roles: string[];
}

/** Roles named by at least one rule. Created before the rules reference them. */
const RBAC_ROLES: string[] = [{{#each rbacRoles}}'{{this}}'{{#unless @last}}, {{/unless}}{{/each}}];

const OPERATION_ACCESS: OperationAccessSeed[] = [
{{#each compiledRbac}}
  {
    tableName: '{{tableName}}',
    operation: '{{operation}}',
    roles: [{{#each roles}}'{{this}}'{{#unless @last}}, {{/unless}}{{/each}}],
  },
{{/each}}
];

const TRANSITION_ACCESS: TransitionAccessSeed[] = [
{{#each compiledRbacTransitions}}
  {
    tableName: '{{tableName}}',
    transition: '{{transition}}',
    statusField: '{{statusField}}',
    edges: [{{#each edges}}{ from: '{{from}}', to: '{{to}}', kind: '{{kind}}' }{{#unless @last}}, {{/unless}}{{/each}}],
    roles: [{{#each roles}}'{{this}}'{{#unless @last}}, {{/unless}}{{/each}}],
  },
{{/each}}
];

export async function seed(db: Kysely<any>): Promise<void> {
  if (OPERATION_ACCESS.length === 0 && TRANSITION_ACCESS.length === 0) {
    console.log('  ⚠ No %%rbac directives declared — every operation stays open');
    return;
  }

  // ---------------------------------------------------------------------------
  // 1. Roles
  // ---------------------------------------------------------------------------
  for (const roleName of RBAC_ROLES) {
    // The guard folds case and treats `_`, `-` and spaces alike
    // (`entity-access.guard`), so this does too. The seeded roles are title-cased
    // with spaces (`Airport Manager`) and a model writes `role:airport_manager`:
    // comparing only case created a second role beside every real one — ten roles
    // seeded, nine more written here — and left an administrator guessing which
    // of each pair to assign.
    const existing = await db
      .selectFrom('sys_role')
      .select('sys_role_id')
      .where(
        sql`lower(regexp_replace(trim(name), '[[:space:]_-]+', ' ', 'g'))` as any,
        '=',
        roleName.trim().toLowerCase().replace(/[\s_-]+/g, ' ')
      )
      .executeTakeFirst();

    if (existing) continue;

    await db
      .insertInto('sys_role')
      .values({
        sys_role_id: uuidv4(),
        name: roleName,
        description: `Declared by %%rbac in the model`,
        user_level: 'C',
        is_master_role: false,
        is_active: true,
        entity_type: 'D',
        created_by: 'system',
        updated_by: 'system',
      } as any)
      .execute();
    console.log(`  ✓ Created role: ${roleName}`);
  }

  // ---------------------------------------------------------------------------
  // 2. Grants — operations and moves, in the one table
  // ---------------------------------------------------------------------------
  await db.deleteFrom('sys_access_grant').where('entity_type', '=', 'D').execute();

  const grant = (row: Record<string, string>) =>
    db
      .insertInto('sys_access_grant')
      .values({
        sys_access_grant_id: uuidv4(),
        status_field: '',
        from_state: '',
        to_state: '',
        ...row,
        entity_type: 'D',
        is_active: true,
        created_by: 'system',
        updated_by: 'system',
      } as any)
      .onConflict((oc: any) =>
        oc.columns(['kind', 'table_name', 'action', 'from_state', 'to_state', 'role_name']).doNothing()
      )
      .execute();

  let written = 0;
  for (const rule of OPERATION_ACCESS) {
    for (const roleName of rule.roles) {
      await grant({
        kind: 'op',
        table_name: rule.tableName,
        action: rule.operation,
        role_name: roleName,
      });
      written += 1;
    }
    console.log(
      `  ✓ ${rule.tableName}.${rule.operation} restricted to: ${rule.roles.join(', ')}`
    );
  }
  console.log(`  ✓ Seeded ${written} operation grant(s)`);

  // A move with no grant is open to anyone who may update the record; one with
  // grants is the button only those roles see. A reopen with none is the
  // administrator's alone.
  let movesWritten = 0;
  for (const rule of TRANSITION_ACCESS) {
    for (const edge of rule.edges) {
      for (const roleName of rule.roles) {
        await grant({
          kind: edge.kind,
          table_name: rule.tableName,
          action: rule.transition,
          status_field: rule.statusField,
          from_state: edge.from,
          to_state: edge.to,
          role_name: roleName,
        });
        movesWritten += 1;
      }
    }
    console.log(
      `  ✓ ${rule.tableName}.${rule.transition} granted to: ${rule.roles.join(', ')}`
    );
  }
  if (movesWritten > 0) {
    console.log(`  ✓ Seeded ${movesWritten} move grant(s)`);
  }
}

common/seeds/sys-dictionary.ts.hbs:
/**
 * System Dictionary Seed
 * Populates sys_ tables with metadata for business entities
 *
 * Generated: {{now}}
 *
 * This seed creates:
 * - sys_table entries for each business entity
 * - sys_column entries for each entity attribute
 * - sys_window entries for entity management
 * - sys_tab entries for window tabs
 * - sys_field entries with randomized seq_no for runtime modification demo
 */

import { Kysely, sql } from 'kysely';
import { v4 as uuidv4 } from 'uuid';

// ============================================================================
// Application Dictionary Help Text
// ============================================================================
// The modeller's own words come first. `%%entity <E> help:` and
// `%%field <E>.<c> help:` are the only place a model says what something is
// *for* rather than what shape it is, and where they are present they open the
// window, the tab and the field.
//
// Everything after that is composed from the dictionary itself rather than
// hand-written per project, so it cannot drift from the schema it describes:
// what is mandatory, what has to be unique, which records link to which, and
// the draft -> final lifecycle every business record goes through. A model with
// no help text still gets all of it; one that has help text gets both, because
// "the school's own identifier for the child" and "required, and must be
// unique" are different facts and the reader needs each.
//
// Administrators can overwrite any of this from Window, Tab and Field; the
// seed only supplies the starting text.

interface HelpColumn {
  columnName: string;
  displayName: string;
  type: string;
  isMandatory: boolean;
  isUnique: boolean;
  isForeignKey: boolean;
  maxLength?: number;
  /** Display label of the entity this column points at, once resolved. */
  fkTarget?: string;
  /** The entity's own <name>_id column carried over from the ERD. */
  isBusinessKey?: boolean;
  /** `%%field <E>.<c> help:` — what the modeller said this column is for. */
  help?: string;
}

interface HelpEntity {
  label: string;
  tableName: string;
  stem: string;
  columns: HelpColumn[];
  /** `%%entity <E> help:` — what the modeller said this entity is for. */
  help?: string;
}

/** Columns the framework maintains; never described as user input. */
const HELP_AUDIT_COLUMNS = [
  'created_at',
  'updated_at',
  'deleted_at',
  'created_by',
  'updated_by',
  'version',
];

/** 'a', 'a and b', 'a, b and c' */
function helpJoin(items: string[]): string {
  if (items.length === 0) return '';
  if (items.length === 1) return items[0];
  return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;
}

/** 'a Patient' / 'an Encounter' */
function helpArticle(word: string): string {
  return /^[aeiou]/i.test(word) ? 'an' : 'a';
}

function isAuditColumn(col: HelpColumn): boolean {
  return HELP_AUDIT_COLUMNS.includes(col.columnName);
}

/**
 * Resolve the cross-references the help text leans on: which columns point at
 * another entity, and which entities point back at this one.
 */
function resolveHelpModel(entities: HelpEntity[]): Map<string, { entity: HelpEntity; children: string[] }> {
  const byStem = new Map(entities.map((e) => [e.stem, e]));
  const resolved = new Map<string, { entity: HelpEntity; children: string[] }>();

  for (const entity of entities) {
    for (const col of entity.columns) {
      if (!col.columnName.endsWith('_id')) continue;
      const stem = col.columnName.slice(0, -'_id'.length);
      const target = byStem.get(stem);
      if (!target) continue;
      if (target.tableName === entity.tableName) {
        // The entity's own identifier from the ERD, not a link to anything.
        col.isBusinessKey = true;
      } else if (col.isForeignKey) {
        col.fkTarget = target.label;
      }
    }
  }

  for (const entity of entities) {
    const children = entities
      .filter((other) =>
        other.tableName !== entity.tableName &&
        other.columns.some((c) => c.fkTarget === entity.label),
      )
      .map((other) => other.label);
    resolved.set(entity.tableName, { entity, children });
  }

  return resolved;
}

function windowHelpText(entity: HelpEntity, children: string[]): string {
  const label = entity.label;
  const parents = [...new Set(entity.columns.filter((c) => c.fkTarget).map((c) => c.fkTarget!))];
  const uniques = entity.columns.filter((c) => c.isUnique).map((c) => c.displayName);
  const required = entity.columns
    .filter((c) => c.isMandatory && !isAuditColumn(c))
    .map((c) => c.displayName);

  const paragraphs: string[] = [];

  // The author's sentence, before anything derived. It answers "what is this
  // for", which nothing composed from column shapes can.
  if (entity.help) paragraphs.push(entity.help);

  paragraphs.push(
    `Create, find and maintain ${label} records. The list shows every ${label} you have access to — ` +
      `select a row to open it, or use New to add one. Each row is a single ${label}, described by ` +
      `${entity.columns.length} field${entity.columns.length === 1 ? '' : 's'}.`,
  );

  const identity: string[] = [];
  if (uniques.length > 0) {
    identity.push(
      `${helpJoin(uniques)} ${uniques.length === 1 ? 'is unique' : 'are unique'}: no two ${label} records ` +
        `may share the same value, and a save that would duplicate one is rejected.`,
    );
  }
  if (required.length > 0) {
    identity.push(`${helpJoin(required)} must be filled in before the record can be saved.`);
  }
  if (identity.length > 0) paragraphs.push(identity.join(' '));

  const links: string[] = [];
  if (parents.length > 0) {
    links.push(
      `Every ${label} points at ${helpJoin(parents)}. Choose the linked record from the lookup on those ` +
        `fields rather than typing an identifier.`,
    );
  }
  if (children.length > 0) {
    links.push(
      `${helpJoin(children)} ${children.length === 1 ? 'refers' : 'refer'} back to ${label}, so what you ` +
        `change here can affect ${children.length === 1 ? 'that record' : 'those records'}.`,
    );
  }
  if (links.length > 0) paragraphs.push(links.join(' '));

  paragraphs.push(
    `Every save starts as a Draft. The business rules and workflows attached to ${label} then run together ` +
      `in a single transaction: if all of them succeed the record becomes Final; if any of them fails, ` +
      `nothing they changed is kept — the record stays Draft and the reason is written onto it so you can ` +
      `fix the cause and retry. ${helpArticle(label) === 'an' ? 'An' : 'A'} ${label} with no rules or ` +
      `workflows attached is marked Final immediately.`,
  );

  return paragraphs.join('\n\n');
}

function tabHelpText(entity: HelpEntity): string {
  const label = entity.label;
  const required = entity.columns.filter((c) => c.isMandatory && !isAuditColumn(c));
  const lookups = entity.columns.filter((c) => c.fkTarget);
  const sentences: string[] = [];

  if (entity.help) sentences.push(entity.help);

  sentences.push(
    `Shows one ${label} at a time. Fields are grouped: General carries the identifying fields and Details ` +
      `carries the rest.`,
  );
  if (required.length > 0) {
    sentences.push(
      `${required.length} field${required.length === 1 ? '' : 's'} marked with a red asterisk (*) must have ` +
        `a value before Save will accept the record.`,
    );
  }
  if (lookups.length > 0) {
    sentences.push(
      `${helpJoin(lookups.map((c) => c.displayName))} ${lookups.length === 1 ? 'is a lookup' : 'are lookups'} — ` +
        `search the linked records instead of entering an identifier by hand.`,
    );
  }
  sentences.push(
    `Any field showing a ? beside its label has help of its own; click it for the rules that apply there.`,
  );

  return sentences.join(' ');
}

function fieldTypeSentence(entity: HelpEntity, col: HelpColumn): string {
  const noun = col.displayName.toLowerCase();
  switch (col.type) {
    case 'date':
      return `The ${noun} of this ${entity.label}, as a calendar date.`;
    case 'datetime':
      return `The ${noun} of this ${entity.label}, as a date and time.`;
    case 'integer':
      return `The ${noun} of this ${entity.label}, as a whole number.`;
    case 'decimal':
      return `The ${noun} of this ${entity.label}, as a decimal amount.`;
    case 'boolean':
      return `Whether this ${entity.label} is marked as ${noun}.`;
    case 'text':
      return `Free-form ${noun} for this ${entity.label}. The box grows as you type.`;
    case 'json':
      return `The ${noun} of this ${entity.label}, held as structured JSON.`;
    default:
      return `The ${noun} of this ${entity.label}.`;
  }
}

function fieldHelpText(entity: HelpEntity, col: HelpColumn): string {
  const parts: string[] = [];

  if (col.help) {
    // What the column is for, in the modeller's words. It replaces the derived
    // opening sentence rather than joining it: both describe the same thing,
    // and the derived one is a restatement of the column's type. The clauses
    // below still apply — they say what the author's sentence does not.
    parts.push(col.help);
  } else if (col.fkTarget) {
    parts.push(
      `Links this ${entity.label} to ${helpArticle(col.fkTarget)} ${col.fkTarget} record. Pick the ` +
        `${col.fkTarget} from the lookup — the identifier is stored for you.`,
    );
  } else if (col.isBusinessKey) {
    parts.push(
      `The ${entity.label} reference used outside this system. It identifies the ${entity.label} on ` +
        `documents and in exports, and stays with the record for its whole life.`,
    );
  } else if (isAuditColumn(col)) {
    parts.push(`Maintained by the system as part of the audit trail. It is set automatically, not entered here.`);
  } else {
    parts.push(fieldTypeSentence(entity, col));
  }

  if (col.isMandatory && !isAuditColumn(col)) {
    parts.push(`Required — the record cannot be saved while this is empty.`);
  }
  if (col.isUnique) {
    parts.push(`Must be unique: a save is rejected if another ${entity.label} already uses this value.`);
  }
  if (col.maxLength) {
    parts.push(`Up to ${col.maxLength} characters.`);
  }

  return parts.join(' ');
}

/*
 * Which columns a grid shows — and, by its absence below, what decides a
 * field's group.
 *
 * These are the columns that are real, queryable and useless in a grid: a uuid
 * nobody reads and the audit trail. Everything else the model declares is
 * shown, and all of them stay on the form.
 *
 * Two values used to be decided by a column's *position* in the list instead,
 * and both showed up as this application and the browser application generated
 * from the same model laying the same entity out differently:
 *
 *   sys_field_group_id: i < 3 ? fieldGroupGeneral : fieldGroupDetails
 *   is_displayed_grid:  !col.isKey && i < 8
 *
 * The first split every form after its third column into a "General" section
 * and a collapsed "Details" one — `dynamic-form.tsx` groups by `group_name`,
 * so those headings are what a reader saw, and where the cut fell had nothing
 * to do with the model. A thirteen-column entity got three fields and then ten
 * behind a heading nobody asked for.
 *
 * The second hid every column past the eighth from the list view. On
 * `bus_program` that is `annual_budget` and `objective`: columns the model
 * declares, the dictionary describes, the API returns and the grid did not
 * show, with nothing anywhere saying why.
 *
 * `sys_field_group_id` comes from the model's `%%section` lines or not at all,
 * and the grid is this set, both mirroring
 * `generators/wasm/model-bundle.ts` — the other producer of this same
 * dictionary, and the one a reader compares against. The same model has to
 * describe the same application whether it was generated as the full stack or
 * as the browser build.
 *
 * Four field groups are still seeded per tab, as empty targets for the Field
 * Layout Manager — a real screen in this stack, and one that was unreachable
 * until those groups were bound to a tab. An administrator groups the fields
 * that should be grouped; until someone does, the form is the flat list the
 * model's column order describes.
 *
 * Module scope, not per entity: every entity's dictionary block shares one
 * function scope, so a `const` inside one of them is a redeclaration by the
 * second entity.
 */
const GRID_NOISE = new Set(['id', 'created_by', 'updated_by', 'deleted_by', 'deleted_at', 'version']);

const dictionaryHelpEntities: HelpEntity[] = [
  {{#each entities}}
  {
    label: '{{displayName}}',
    tableName: '{{tableName}}',
    stem: '{{snakeCase name}}',
    {{#if description}}help: {{tsString description}},
    {{/if}}columns: [
      {{#each attributes}}
      { columnName: '{{columnName}}', displayName: '{{displayName}}', type: '{{type}}', isMandatory: {{#if (or (eq columnName 'created_at') (eq columnName 'updated_at') (eq columnName 'deleted_at'))}}false{{else}}{{#if required}}true{{else}}false{{/if}}{{/if}}, isUnique: {{#if unique}}true{{else}}false{{/if}}, isForeignKey: {{#if isForeignKey}}true{{else}}false{{/if}}{{#if maxLength}}, maxLength: {{maxLength}}{{/if}}{{#if description}}, help: {{tsString description}}{{/if}} },
      {{/each}}
    ],
  },
  {{/each}}
];

const dictionaryHelp = resolveHelpModel(dictionaryHelpEntities);

function windowHelpFor(tableName: string): string | null {
  const found = dictionaryHelp.get(tableName);
  return found ? windowHelpText(found.entity, found.children) : null;
}

function tabHelpFor(tableName: string): string | null {
  const found = dictionaryHelp.get(tableName);
  return found ? tabHelpText(found.entity) : null;
}

function fieldHelpFor(tableName: string, columnName: string): string | null {
  const found = dictionaryHelp.get(tableName);
  const col = found?.entity.columns.find((c) => c.columnName === columnName);
  return found && col ? fieldHelpText(found.entity, col) : null;
}

export async function seed(db: Kysely<any>): Promise<void> {
  const now = new Date();
  const createdBy = '{{config.createdBy}}';

  // Truncate sys_ tables so the seed is idempotent (safe to re-run)
  await sql`TRUNCATE sys_field, sys_tab, sys_window, sys_column, sys_table, sys_field_group CASCADE`.execute(db).catch(() => {});

  // ============================================================================
  // Create Default Roles (lookup-or-create so re-runs are safe)
  // ============================================================================
  let adminRoleId: string;
  const existingAdminRole = await db.selectFrom('sys_role').select('sys_role_id').where('name', '=', 'Administrator').executeTakeFirst();
  if (existingAdminRole) {
    adminRoleId = existingAdminRole.sys_role_id;
  } else {
    adminRoleId = uuidv4();
    await db.insertInto('sys_role').values({
      sys_role_id: adminRoleId,
      name: 'Administrator',
      description: 'System administrator with full access',
      user_level: 'S',
      is_master_role: true,
      is_can_export: true,
      is_can_report: true,
      is_personal_lock: false,
      is_personal_access: false,
      max_query_records: 0,
      is_show_accounting: true,
      entity_type: 'D',
      is_active: true,
      created_by: createdBy,
      updated_by: createdBy,
      created_at: now,
      updated_at: now,
    }).execute();
  }

  let userRoleId: string;
  const existingUserRole = await db.selectFrom('sys_role').select('sys_role_id').where('name', '=', 'User').executeTakeFirst();
  if (existingUserRole) {
    userRoleId = existingUserRole.sys_role_id;
  } else {
    userRoleId = uuidv4();
    await db.insertInto('sys_role').values({
      sys_role_id: userRoleId,
      name: 'User',
      description: 'Standard user with limited access',
      user_level: 'C',
      is_master_role: false,
      is_can_export: true,
      is_can_report: true,
      is_personal_lock: false,
      is_personal_access: false,
      max_query_records: 1000,
      is_show_accounting: false,
      entity_type: 'D',
      is_active: true,
      created_by: createdBy,
      updated_by: createdBy,
      created_at: now,
      updated_at: now,
    }).execute();
  }

  // Every role that is not the Administrator gets the business windows.
  //
  // Granting only 'User' was invisible while the dictionary was served
  // unfiltered over HTTP — every role saw every window regardless. Now that a
  // shape is scoped by role, a role with no grant syncs no dictionary at all,
  // and 00_users_and_roles seeds Manager and Analyst accounts that would open
  // to an empty application.
  const businessRoles = await db
    .selectFrom('sys_role')
    .select('sys_role_id')
    .where('sys_role_id', '!=', adminRoleId)
    .where('is_active', '=', true)
    .execute();
  const businessRoleIds: string[] = businessRoles.length > 0
    ? businessRoles.map((r: { sys_role_id: string }) => r.sys_role_id)
    : [userRoleId];

  /**
   * Role ids for the names a `%%rbac … .read` directive used.
   *
   * The model writes `support_agent` and the dictionary seeds `Support Agent`,
   * so the match normalises separators and case — the same rule the runtime
   * guard applies, and for the same reason: a name that resolves in the guard
   * and not here would hide a window from the very role allowed to read it.
   */
  const normalizeRole = (value: string) =>
    String(value ?? '').trim().toLowerCase().replace(/[\s-]+/g, '_');
  const allRoles = await db
    .selectFrom('sys_role')
    .select(['sys_role_id', 'name'])
    .where('is_active', '=', true)
    .execute();
  const roleIdsNamed = (names: string[]): string[] => {
    const wanted = new Set(names.map(normalizeRole));
    return allRoles
      .filter((r: { name: string }) => wanted.has(normalizeRole(r.name)))
      .map((r: { sys_role_id: string }) => r.sys_role_id);
  };

  // ============================================================================
  // Create Default Admin User (lookup-or-create so re-runs are safe)
  // ============================================================================
  const adminEmail = process.env.ADMIN_EMAIL || 'admin@admin.com';

  let adminUserId: string;
  const existingAdmin = await db.selectFrom('sys_user').select('sys_user_id').where('email', '=', adminEmail).executeTakeFirst();
  if (existingAdmin) {
    adminUserId = existingAdmin.sys_user_id;
  } else {
    adminUserId = uuidv4();
    await db.insertInto('sys_user').values({
      sys_user_id: adminUserId,
      name: 'System Administrator',
      email: adminEmail,
      password_hash: '$2b$10$rIC/7qZmzCi9F4g4OKL8wO4k5XYzJ5Z5Z5Z5Z5Z5Z5Z5Z5Z5Z5Z5', // replaced by ensureAdminUser on first boot
      description: 'Default system administrator',
      is_system_user: true,
      is_sales_rep: false,
      login_failure_count: 0,
      is_locked: false,
      is_account_verified: true,
      default_sys_role_id: adminRoleId,
      entity_type: 'D',
      is_active: true,
      created_by: createdBy,
      updated_by: createdBy,
      created_at: now,
      updated_at: now,
    }).execute();
  }

  // Assign admin role to admin user (idempotent)
  await db.insertInto('sys_user_roles').values({
    sys_user_roles_id: uuidv4(),
    sys_user_id: adminUserId,
    sys_role_id: adminRoleId,
    entity_type: 'D',
    is_active: true,
    created_by: createdBy,
    updated_by: createdBy,
    created_at: now,
    updated_at: now,
  }).onConflict((oc) => oc.doNothing()).execute();

  // ============================================================================
  // Business Entities Dictionary Entries
  // ============================================================================

  {{#each entities}}
  // --------------------------------------------------------------------------
  // {{displayName}} ({{tableName}})
  // --------------------------------------------------------------------------
  const {{camelCase name}}TableId = uuidv4();
  {{#unless parentEntity}}
  const {{camelCase name}}WindowId = uuidv4();
  {{/unless}}
  const {{camelCase name}}TabId = uuidv4();

  {{#unless parentEntity}}
  // Create sys_window entry FIRST (sys_table references it)
  await db.insertInto('sys_window').values({
    sys_window_id: {{camelCase name}}WindowId,
    name: '{{displayName}}',
    description: 'Maintain {{displayName}} records',
    help: windowHelpFor('{{tableName}}'),
    window_type: 'M',
    is_sales_transaction: false,
    is_default: true,
    // Which rows this window's lists show, and in what order. No filter to
    // begin with; ordered by most recent change, which is the order a reader
    // opening a list expects and the one a seeded table needs to be navigable
    // at all. Both are editable from the Window screen — neither is SQL; see
    // backend/src/modules/bus/window-list-defaults.ts for the grammars.
    where_clause: null,
    order_by_clause: 'updated_at DESC',
    entity_type: 'U',
    is_active: true,
    created_by: createdBy,
    updated_by: createdBy,
    created_at: now,
    updated_at: now,
  }).execute();
  {{/unless}}

  // Create sys_table entry AFTER sys_window
  await db.insertInto('sys_table').values({
    sys_table_id: {{camelCase name}}TableId,
    table_name: '{{tableName}}',
    name: '{{displayName}}',
    {{!-- tsString emits the whole literal, quotes included. The model's own
          words land here, and `%%entity Opportunity help: … the opportunity's
          amount …` used to close the string on its apostrophe and take the
          generated application's compile with it. --}}
    description: {{#if description}}{{tsString description}}{{else}}'Manage {{displayName}} records'{{/if}},
    {{!-- `%%entity <E> icon: <name>`, or null and the card draws a default.
          Null rather than a guess from the table's name: the model is the only
          thing that decides what an entity looks like, and an icon invented
          here would be indistinguishable from one the modeller chose. An
          administrator can still set or upload one afterwards — same column,
          through Table and Column. --}}
    icon: {{#if icon}}{{tsString icon}}{{else}}null{{/if}},
    access_level: 'A',
    is_view: false,
    is_document: false,
    is_high_volume: false,
    is_changelog: true,
    sys_window_id: {{camelCase windowOwner}}WindowId,
    entity_type: 'U',
    is_active: true,
    created_by: createdBy,
    updated_by: createdBy,
    created_at: now,
    updated_at: now,
  }).execute();

  // Create sys_tab entry
  await db.insertInto('sys_tab').values({
    sys_tab_id: {{camelCase name}}TabId,
    sys_window_id: {{camelCase windowOwner}}WindowId,
    sys_table_id: {{camelCase name}}TableId,
    name: '{{displayName}}',
    help: tabHelpFor('{{tableName}}'),
    tab_level: {{#if parentEntity}}1{{else}}0{{/if}},
    seq_no: {{#if parentEntity}}20{{else}}10{{/if}},
    is_single_row: true,
    has_tree: false,
    is_info_tab: false,
    is_translation_tab: false,
    is_read_only: false,
    is_insert_record: true,
    is_advanced_tab: false,
    entity_type: 'U',
    is_active: true,
    created_by: createdBy,
    updated_by: createdBy,
    created_at: now,
    updated_at: now,
  }).execute();

  // Create sys_column entries
  const {{camelCase name}}Columns: Array<{
    id: string;
    name: string;
    displayName: string;
    isKey: boolean;
    displayLogic: string | null;
    readOnlyLogic: string | null;
    mandatoryLogic: string | null;
    /** `%%section` placement — absent on an entity that declares no sections. */
    layout?: {
      group: string;
      seqNo: number;
      sameLine: boolean;
      columnSpan: number;
    };
  }> = [];

  let {{camelCase name}}ColumnSeqNo = 10;
  {{#each attributes}}
  const {{camelCase ../name}}_{{camelCase name}}_columnId = uuidv4();
  {{camelCase ../name}}Columns.push({
    id: {{camelCase ../name}}_{{camelCase name}}_columnId,
    name: '{{columnName}}',
    displayName: '{{displayName}}',
    isKey: {{#if (eq name ../primaryKey)}}true{{else}}false{{/if}},
    {{!-- `%%field <E>.<c> display: | readonly: | mandatory:` — Compiere's
          field logic, written to sys_field below. --}}
    displayLogic: {{#if displayLogic}}{{tsString displayLogic}}{{else}}null{{/if}},
    readOnlyLogic: {{#if readOnlyLogic}}{{tsString readOnlyLogic}}{{else}}null{{/if}},
    mandatoryLogic: {{#if mandatoryLogic}}{{tsString mandatoryLogic}}{{else}}null{{/if}},
    {{#if layout}}
    layout: {
      group: {{tsString layout.group}},
      seqNo: {{layout.seqNo}},
      sameLine: {{layout.sameLine}},
      columnSpan: {{layout.columnSpan}},
    },
    {{/if}}
  });

  await db.insertInto('sys_column').values({
    sys_column_id: {{camelCase ../name}}_{{camelCase name}}_columnId,
    sys_table_id: {{camelCase ../name}}TableId,
    column_name: '{{columnName}}',
    name: '{{displayName}}',
    {{!-- `%%field <E>.<c> help:`. sys_field.help below is what the form renders
          under the control; this is what the Application Dictionary shows
          beside the column, and it is the modeller's sentence unadorned. --}}
    description: {{#if description}}{{tsString description}}{{else}}null{{/if}},
    sys_reference_id: {{referenceId}}{{#if maxLength}},
    field_length: {{maxLength}}{{/if}}{{#if default}},
    default_value: {{tsString default}}{{/if}},
    is_key: {{#if (eq name ../primaryKey)}}true{{else}}false{{/if}},
    is_parent: false,
    is_mandatory: {{#if (or (eq columnName 'created_at') (eq columnName 'updated_at') (eq columnName 'deleted_at'))}}false{{else}}{{required}}{{/if}},
    is_updateable: {{#if (or (eq name ../primaryKey) (eq columnName 'created_at') (eq columnName 'updated_at') (eq columnName 'deleted_at'))}}false{{else}}true{{/if}},
    {{!-- Which columns make up the display value is decided once, in
          identifierColumnNames, and carried on the attribute. Deciding it here
          meant a table with both `name` and `code` marked both, and the record
          read "Acme ACME-01" wherever it was referenced. --}}
    is_identifier: {{#if isIdentifier}}true{{else}}false{{/if}},
    {{!-- Compiere's column logic, inherited by every window over this table. --}}
    read_only_logic: {{#if readOnlyLogic}}{{tsString readOnlyLogic}}{{else}}null{{/if}},
    mandatory_logic: {{#if mandatoryLogic}}{{tsString mandatoryLogic}}{{else}}null{{/if}},
    is_selection_column: {{#if (or (eq name 'name') unique)}}true{{else}}false{{/if}},
    is_translated: false,
    is_encrypted: false,
    is_allow_logging: true,
    is_allow_copy: {{#if (eq name ../primaryKey)}}false{{else}}true{{/if}},
    seq_no: {{camelCase ../name}}ColumnSeqNo,
    entity_type: 'U',
    is_active: true,
    created_by: createdBy,
    updated_by: createdBy,
    created_at: now,
    updated_at: now,
  }).execute();
  {{camelCase ../name}}ColumnSeqNo += 10;
  {{/each}}

  {{#if parentLinkColumn}}
  /* A line item links to its master on one column. Set after the columns
     exist, because the tab was written before them, and marked `is_parent` the
     way Compiere marks the column that ties a detail row to its master. */
  {
    const linkColumn = {{camelCase name}}Columns.find((c) => c.name === '{{parentLinkColumn}}');
    if (linkColumn) {
      await db.updateTable('sys_tab')
        .set({ link_column_id: linkColumn.id })
        .where('sys_tab_id', '=', {{camelCase name}}TabId)
        .execute();
      await db.updateTable('sys_column')
        .set({ is_parent: true })
        .where('sys_column_id', '=', linkColumn.id)
        .execute();
    }
  }
  {{/if}}

  /*
   * Field groups for this tab.
   *
   * Per tab, not once globally, because `GET /sys/field-groups?entity=<table>`
   * resolves the entity's tab and filters `sys_field_group.sys_tab_id` to it.
   * The four groups used to be inserted once with `sys_tab_id` unset, so that
   * query matched nothing for every entity: the Field Layout Manager showed an
   * "Unassigned" column and no group panels at all, which left the whole
   * drag-and-drop layout feature — and with it the Highlights panel in the
   * record header — visible in the code and unreachable in the application.
   *
   * `Highlights` carries `layout_type: 'summary'`, and that is what puts a
   * group in the record header rather than the form body:
   * `ad-detail-shell.tsx` filters the entity's columns for
   * `group_layout_type === "summary"` and renders them as the amber
   * **Highlights** panel at the top right of the window tab, beside the
   * record's title. The Star toggle on any group in the layout manager sets
   * the same flag.
   *
   * All four are seeded **empty**: a model does not say which two or three of
   * an entity's columns are worth reading at a glance, and that judgement is
   * what the layout manager is for. Until an administrator drags a field in,
   * every field stays unassigned and the form is the flat list the model's
   * column order describes — the parity with the browser build that the note
   * on GRID_NOISE is about.
   */
  {{#if formGroups}}
  /*
   * The model's `%%section` groups — headed sections of two-column rows, in the
   * model's order, after the Highlights panel the layout manager still offers.
   * Each field below is placed in its group, row and column; nothing here is
   * decided by position, so this form and the browser build's agree.
   */
  const {{camelCase name}}GroupIds = new Map<string, string>();
  await db.insertInto('sys_field_group').values([
    {
      sys_field_group_id: uuidv4(),
      sys_tab_id: {{camelCase name}}TabId,
      name: 'Highlights',
      description:
        'Shown in the record header, not the form. Drag the two or three fields worth reading at a glance into this group.',
      layout_type: 'summary',
      columns: 1,
      seq_no: 10,
      field_group_type: 'C',
      is_collapsed_by_default: false,
      entity_type: 'D',
      is_active: true,
      created_by: createdBy,
      updated_by: createdBy,
      created_at: now,
      updated_at: now,
    },
  ]).execute();
  {{#each formGroups}}
  {
    const groupId = uuidv4();
    {{camelCase ../name}}GroupIds.set({{tsString name}}, groupId);
    await db.insertInto('sys_field_group').values({
      sys_field_group_id: groupId,
      sys_tab_id: {{camelCase ../name}}TabId,
      name: {{tsString name}},
      description: {{#if description}}{{tsString description}}{{else}}null{{/if}},
      layout_type: 'single',
      columns: {{columns}},
      seq_no: {{seqNo}} + 10,
      field_group_type: 'C',
      is_collapsed_by_default: {{collapsed}},
      entity_type: 'D',
      is_active: true,
      created_by: createdBy,
      updated_by: createdBy,
      created_at: now,
      updated_at: now,
    }).execute();
  }
  {{/each}}
  {{else}}
  await db.insertInto('sys_field_group').values([
    {
      sys_field_group_id: uuidv4(),
      sys_tab_id: {{camelCase name}}TabId,
      name: 'Highlights',
      description:
        'Shown in the record header, not the form. Drag the two or three fields worth reading at a glance into this group.',
      layout_type: 'summary',
      columns: 1,
      seq_no: 10,
      field_group_type: 'C',
      is_collapsed_by_default: false,
      entity_type: 'D',
      is_active: true,
      created_by: createdBy,
      updated_by: createdBy,
      created_at: now,
      updated_at: now,
    },
    {
      sys_field_group_id: uuidv4(),
      sys_tab_id: {{camelCase name}}TabId,
      name: 'General',
      description: 'General information fields',
      layout_type: 'single',
      columns: 2,
      seq_no: 20,
      field_group_type: 'C',
      is_collapsed_by_default: false,
      entity_type: 'D',
      is_active: true,
      created_by: createdBy,
      updated_by: createdBy,
      created_at: now,
      updated_at: now,
    },
    {
      sys_field_group_id: uuidv4(),
      sys_tab_id: {{camelCase name}}TabId,
      name: 'Details',
      description: 'Detailed information fields',
      layout_type: 'single',
      columns: 2,
      seq_no: 30,
      field_group_type: 'C',
      is_collapsed_by_default: true,
      entity_type: 'D',
      is_active: true,
      created_by: createdBy,
      updated_by: createdBy,
      created_at: now,
      updated_at: now,
    },
    {
      sys_field_group_id: uuidv4(),
      sys_tab_id: {{camelCase name}}TabId,
      name: 'System',
      description: 'System fields (audit trail)',
      layout_type: 'single',
      columns: 2,
      seq_no: 40,
      field_group_type: 'C',
      is_collapsed_by_default: true,
      entity_type: 'D',
      is_active: true,
      created_by: createdBy,
      updated_by: createdBy,
      created_at: now,
      updated_at: now,
    },
  ]).execute();
  {{/if}}

  // sys_field: the `%%section` placement when the model declares one, else a
  // sequential seq_no and no group; the grid by GRID_NOISE either way. See the
  // note on GRID_NOISE for why none of this is decided by position.
  for (let i = 0; i < {{camelCase name}}Columns.length; i++) {
    const col = {{camelCase name}}Columns[i];
    await db.insertInto('sys_field').values({
      sys_field_id: uuidv4(),
      sys_tab_id: {{camelCase name}}TabId,
      sys_column_id: col.id,
      {{#if formGroups}}
      sys_field_group_id: col.layout ? {{camelCase name}}GroupIds.get(col.layout.group) : undefined,
      {{else}}
      sys_field_group_id: undefined,
      {{/if}}
      name: col.displayName,
      help: fieldHelpFor('{{tableName}}', col.name),
      seq_no: col.layout?.seqNo ?? (i + 1) * 10,
      seq_no_grid: (i + 1) * 10,
      is_displayed: !col.isKey,
      is_displayed_grid: !col.isKey && !GRID_NOISE.has(col.name),
      is_read_only: ['created_at', 'updated_at', 'deleted_at'].includes(col.name),
      is_encrypted: false,
      is_same_line: col.layout?.sameLine ?? false,
      column_span: col.layout?.columnSpan ?? null,
      is_heading: false,
      is_field_only: false,
      display_logic: col.displayLogic,
      read_only_logic: col.readOnlyLogic,
      mandatory_logic: col.mandatoryLogic,
      entity_type: 'U',
      is_active: true,
      created_by: createdBy,
      updated_by: createdBy,
      created_at: now,
      updated_at: now,
    }).execute();
  }

  // Grant access to admin role
  await db.insertInto('sys_access').values({
    sys_access_id: uuidv4(),
    sys_role_id: adminRoleId,
    sys_table_id: {{camelCase name}}TableId,
    sys_window_id: {{camelCase windowOwner}}WindowId,
    access_type_table: 'W',
    is_read_only: false,
    is_exclude: false,
    entity_type: 'U',
    is_active: true,
    created_by: createdBy,
    updated_by: createdBy,
    created_at: now,
    updated_at: now,
  }).execute();

  // Grant read access.
  //
  // To the roles the model says own this entity, when it restricted `read` on
  // it — that is what makes a functional role's application *its* application
  // rather than the whole system with most of it refusing to open. To every
  // role otherwise, which is the behaviour of every model that declares no read
  // restriction, and therefore of every model written before this existed.
  {{#if (lookup ../access.entityVisibility name)}}
  const {{camelCase name}}RoleIds = roleIdsNamed([{{#each (lookup ../access.entityVisibility name)}}'{{this}}'{{#unless @last}}, {{/unless}}{{/each}}]);
  {{else}}
  const {{camelCase name}}RoleIds = businessRoleIds;
  {{/if}}
  for (const roleId of {{camelCase name}}RoleIds) {
    await db.insertInto('sys_access').values({
      sys_access_id: uuidv4(),
      sys_role_id: roleId,
      sys_table_id: {{camelCase name}}TableId,
      sys_window_id: {{camelCase windowOwner}}WindowId,
      access_type_table: 'R',
      is_read_only: true,
      is_exclude: false,
      entity_type: 'U',
      is_active: true,
      created_by: createdBy,
      updated_by: createdBy,
      created_at: now,
      updated_at: now,
    }).execute();
  }

  console.log('✓ Created dictionary entries for {{displayName}}');

  {{/each}}

  // ============================================================================
  // Admin Windows (entity_type = 'S') — Application Dictionary section on dashboard
  // ============================================================================
  // Every business window carries help generated from the model. These seven do
  // not describe an entity, so nothing generated help for them and the Help
  // button hid itself — the six screens that explain how the application is put
  // together were the six with no explanation of their own. The text lives in
  // the dictionary rather than in the pages so an administrator can rewrite it
  // from Window, Tab and Field like any other help.
  const adminWindowDefs = [
    {
      name: 'Automations',
      route: '/admin/automations',
      icon: 'zap',
      help:
        'Business rules and workflows in one place. Rules are decision tables that run on every ' +
        'matching write — they can reject a save, overwrite a field, or trigger a workflow. ' +
        'Workflows list the steps that run automatically: look up a table, create a record, ' +
        'call a service, and more.\n\n' +
        'Rules and workflows share this screen because a workflow hook is what gives a rule its ' +
        'moment: attach a rule to a hook to choose when it runs.',
    },
    {
      name: 'Audit Log',
      route: '/admin/audit',
      icon: 'scroll-text',
      help:
        'The record of who changed what. One entry per insert, update and delete, holding the entity, ' +
        'the row, the user, the time and the before and after values of every column that moved.\n\n' +
        'Entries are written by the same transaction as the change, so the log cannot drift from the ' +
        'data. It is append-only: nothing here can be edited or deleted from the application.\n\n' +
        'Use it to answer who set this field, when did this record change state, and what did it look ' +
        'like before. Filter by entity to follow one table, or open a record to see its whole history.',
    },
    {
      name: 'Table and Column',
      route: '/admin/tables',
      icon: 'table-2',
      help:
        'The database as the application understands it. One row per table, with its columns, their ' +
        'types, and the flags that decide behaviour everywhere else: mandatory, unique, and which ' +
        'table a foreign key points at.\n\n' +
        'This is the layer the rest of the dictionary builds on. A column marked mandatory here is ' +
        'required in every form; a column with a reference is a lookup rather than a free-text box.\n\n' +
        'Tables are created from the model on generation. Editing a definition here changes how the ' +
        'application treats the column, not the database schema itself — a new column still needs a ' +
        'migration.',
    },
    {
      name: 'Window, Tab and Field',
      route: '/admin/windows',
      icon: 'app-window',
      help:
        'How each entity is presented. A window is one screen, a tab is one record view inside it, ' +
        'and a field is one column shown on that tab, in the order and grouping given by its sequence ' +
        'and field group.\n\n' +
        'Every screen in the application is drawn from these rows, so this is where you change what a ' +
        'form looks like without touching code: reorder fields, hide one, mark it read-only, or ' +
        'rewrite its label and help.\n\n' +
        'The help you are reading now lives here too. Window, tab and field help is what the Help ' +
        'button shows on every screen, so improving it here improves it everywhere it is read.',
    },
    {
      name: 'User',
      route: '/admin/users',
      icon: 'users',
      help:
        'The people who can sign in, and the role each of them holds. A user with no role can ' +
        'authenticate but reach nothing, and deactivating a user ends their access without deleting ' +
        'the records they created.\n\n' +
        'Role assignment is what decides which windows a user sees and whether they can write in ' +
        'them. Change the role here; change what the role allows under Role.',
    },
    {
      name: 'Role',
      route: '/admin/roles',
      icon: 'user-cog',
      help:
        'What each role is allowed to reach. Access is granted per window: a role either sees a ' +
        'window or does not, and can be given it read-only.\n\n' +
        'Roles are additive over users, not over each other — a user holds one role, and that role ' +
        'is the whole of their access. A window with no grant is invisible rather than forbidden, so ' +
        'removing access removes the screen from the dashboard as well.',
    },
    {
      name: 'System Configuration',
      route: '/admin/system-config',
      icon: 'settings',
      help:
        'Runtime configuration that can be changed without a redeploy. AI endpoints, feature toggles, ' +
        'rate limits, logging, and CORS are managed here.\n\n' +
        'Each setting falls back to its environment variable when deactivated or empty, so the .env ' +
        'file remains the bootstrap mechanism. The application description at the top is a detailed ' +
        'summary of what this application does — it appears in the manual and the dashboard header.',
    },
  ];

  for (const wd of adminWindowDefs) {
    /*
     * Found by its route, which an administrative window never changes, and
     * named so that no two windows share a name. A model may declare an entity
     * called User or Role, whose window is seeded above under that name. Matched
     * on the name, that business window was taken for this one and the screen
     * that manages sign-in was never created; created under the same name, the
     * dictionary held two windows called User. So where the plain name is
     * taken, the administrative window is "User Management" — what its screen
     * is headed anyway — and a row left with a clashing name is renamed.
     */
    const existing = await db
      .selectFrom('sys_window')
      .select(['sys_window_id', 'name', 'help', 'icon'])
      .where('description', '=', wd.route)
      .where('entity_type', '=', 'S')
      .executeTakeFirst();
    const windowId = existing?.sys_window_id ?? uuidv4();
    const clash = await db
      .selectFrom('sys_window')
      .select('sys_window_id')
      .where('name', '=', wd.name)
      .where('sys_window_id', '!=', windowId)
      .executeTakeFirst();
    const name = clash ? `${wd.name} Management` : wd.name;
    if (!existing) {
      await db.insertInto('sys_window').values({
        sys_window_id: windowId,
        name,
        description: wd.route,
        help: wd.help,
        icon: wd.icon,
        entity_type: 'S',
        is_active: true,
        created_by: createdBy,
        updated_by: createdBy,
        created_at: now,
        updated_at: now,
      }).execute();
    } else if (clash && existing.name === wd.name) {
      await db.updateTable('sys_window')
        .set({ name, updated_by: createdBy, updated_at: now })
        .where('sys_window_id', '=', windowId)
        .execute();
    }
    if (existing && (!existing.help || !existing.icon)) {
      /*
       * Backfill only, per field. An administrator who has rewritten the help
       * text or chosen their own icon keeps it — re-seeding is not a licence to
       * overwrite what someone edited. The icon matters here beyond looks: the
       * dashboard reads it straight from the dictionary now, so a window seeded
       * before this column existed would otherwise show a default icon forever.
       */
      const patch: Record<string, unknown> = { updated_by: createdBy, updated_at: now };
      if (!existing.help) patch.help = wd.help;
      if (!existing.icon) patch.icon = wd.icon;
      await db.updateTable('sys_window')
        .set(patch)
        .where('sys_window_id', '=', windowId)
        .execute();
    }
    const existingAccess = await db.selectFrom('sys_access').select('sys_access_id').where('sys_role_id', '=', adminRoleId).where('sys_window_id', '=', windowId).executeTakeFirst();
    if (!existingAccess) {
      await db.insertInto('sys_access').values({
        sys_access_id: uuidv4(),
        sys_role_id: adminRoleId,
        sys_window_id: windowId,
        access_type_table: 'W',
        is_read_only: false,
        is_exclude: false,
        entity_type: 'S',
        is_active: true,
        created_by: createdBy,
        updated_by: createdBy,
        created_at: now,
        updated_at: now,
      }).execute();
    }
  }

  console.log('✓ Created admin windows (Business Rules, Workflow Designer, etc.)');

  // ============================================================================
  // Summary
  // ============================================================================
  console.log('');
  console.log('Dictionary seed complete:');
  console.log('  - {{entities.length}} business entities');
  console.log(`  - ${businessRoleIds.length + 1} roles granted window access`);
  console.log('  - 1 admin user (admin@localhost)');
  console.log('  - 3 field groups');
  console.log('  - 8 admin windows (Application Dictionary)');
  console.log('');
  console.log('NOTE: Field seq_no values are sequential. Administrators can');
  console.log('      reorder fields via the admin interface.');
}

common/seeds/report-designs.ts.hbs:
/**
 * Default Report Designs Seed
 *
 * Seeds one AnkaReport layout per entity into sys_report_designs, so every
 * entity has a printable document from the moment the application is created.
 * Administrators refine any of them in Admin → Report Designs; the detail
 * screen's Print button renders whatever is stored here.
 *
 * The shape below is AnkaReport's own `ILayout`, and every part of it is load
 * bearing — the renderer reads the layout directly and silently ignores
 * anything shaped differently:
 *
 *   - `width` sets the page element's pixel width. Absent, the renderer writes
 *     `undefinedpx` and the document collapses to nothing.
 *   - style properties (`fontSize`, `color`, `fontWeight`, …) are flat on the
 *     item and inherit from the section and the layout. Nested under a `style`
 *     object they are read by nobody.
 *   - `fontSize` is a CSS length, not a number: `11` is not a valid value for
 *     `element.style.fontSize` and the browser drops the assignment.
 *   - every section carries a `binding`; the content section's names the array
 *     in the data that it repeats over, which is what makes one section render
 *     once per record.
 *
 * Generated: {{now}}
 */

import { type Kysely } from 'kysely';

interface FieldRow {
  label: string;
  field: string;
}

/** AnkaReport's flat style bag — inherited down layout → section → item. */
interface ReportStyle {
  color?: string;
  backgroundColor?: string;
  textAlign?: 'left' | 'center' | 'right';
  borderWidth?: number;
  borderStyle?: string;
  borderColor?: string;
  fontFamily?: string;
  fontSize?: string;
  fontWeight?: string;
}

interface ReportItem extends ReportStyle {
  type: 'text';
  name: string;
  x: number;
  y: number;
  width: number;
  height: number;
  text: string;
  binding?: string;
}

interface ReportSection extends ReportStyle {
  height: number;
  binding: string;
  items: ReportItem[];
}

interface ReportLayout extends ReportStyle {
  width: number;
  headerSection: ReportSection;
  contentSection: ReportSection;
  footerSection: ReportSection;
}

/** A4 at 96dpi is 794px; 760 leaves a printable margin either side. */
const PAGE_W = 760;
const ROW_H = 22;
const ROW_GAP = 4;
const LABEL_W = 220;
const MARGIN_X = 16;
const VALUE_W = PAGE_W - LABEL_W - MARGIN_X * 2 - 12;

function toLabel(columnName: string): string {
  return columnName
    .replace(/_id$/, '')
    .replace(/_/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

function buildLayout(entityName: string, fields: FieldRow[]): ReportLayout {
  const startY = 10;
  const items: ReportItem[] = [];

  fields.forEach((f, i) => {
    const y = startY + i * (ROW_H + ROW_GAP);
    items.push({
      type: 'text',
      name: `${f.field}_label`,
      x: MARGIN_X,
      y,
      width: LABEL_W,
      height: ROW_H,
      text: `${f.label}`,
      fontSize: '11px',
      fontWeight: 'bold',
      color: '#374151',
    });
    items.push({
      type: 'text',
      name: f.field,
      x: MARGIN_X + LABEL_W + 12,
      y,
      width: VALUE_W,
      height: ROW_H,
      text: '',
      binding: f.field,
      fontSize: '11px',
      color: '#111827',
    });
  });

  const contentHeight = Math.max(startY * 2 + fields.length * (ROW_H + ROW_GAP), 64);

  return {
    width: PAGE_W,
    fontFamily: 'Helvetica, Arial, sans-serif',
    fontSize: '11px',
    color: '#111827',
    headerSection: {
      height: 60,
      binding: '',
      items: [
        {
          type: 'text',
          name: 'title',
          x: MARGIN_X,
          y: 16,
          width: PAGE_W - MARGIN_X * 2,
          height: 30,
          text: `${entityName}`,
          fontSize: '20px',
          fontWeight: 'bold',
          color: '#0f4c75',
        },
      ],
    },
    contentSection: {
      height: contentHeight,
      // The renderer repeats this section once per element of `data.records`.
      binding: 'records',
      items,
    },
    footerSection: {
      height: 30,
      binding: '',
      items: [
        {
          type: 'text',
          name: 'footer',
          x: MARGIN_X,
          y: 8,
          width: PAGE_W - MARGIN_X * 2,
          height: 18,
          text: '{{project.name}}',
          fontSize: '9px',
          color: '#9ca3af',
          textAlign: 'center',
        },
      ],
    },
  };
}

const entityReports: Array<{ tableName: string; displayName: string; columns: string[] }> = [
  {{#each entities}}
  {
    tableName: '{{tableName}}',
    displayName: '{{displayName}}',
    columns: [
      {{#each attributes}}
      {{#unless (eq name ../primaryKey)}}
      {{#unless (eq name 'created_at')}}
      {{#unless (eq name 'updated_at')}}
      {{#unless (eq name 'deleted_at')}}
      {{#unless (eq name 'version')}}
      '{{name}}',
      {{/unless}}
      {{/unless}}
      {{/unless}}
      {{/unless}}
      {{/unless}}
      {{/each}}
    ],
  },
  {{/each}}
];

/**
 * The fields a document prints, as the window shows them: the form's own
 * fields, in its order, under its labels. The dictionary is seeded before this
 * (02_sys_dictionary), so a print layout matches the screen the record is
 * printed from instead of a label guessed from the column name. The column
 * list from the model is only the fallback for a table no window shows.
 */
async function windowFields(
  db: Kysely<any>,
  tableName: string,
  columns: string[],
): Promise<FieldRow[]> {
  const rows = (await db
    .selectFrom('sys_field as f')
    .innerJoin('sys_tab as t', 't.sys_tab_id', 'f.sys_tab_id')
    .innerJoin('sys_table as tb', 'tb.sys_table_id', 't.sys_table_id')
    .innerJoin('sys_column as c', 'c.sys_column_id', 'f.sys_column_id')
    .select(['f.name as label', 'c.column_name as field', 't.tab_level as level', 'f.seq_no as seq'])
    .where('tb.table_name', '=', tableName)
    .where('f.is_active', '=', true)
    .where('f.is_displayed', '=', true)
    .orderBy('t.tab_level')
    .orderBy('f.seq_no')
    .execute()
    .catch(() => [])) as Array<{ label: string; field: string; level: number }>;
  const firstLevel = rows[0]?.level;
  const own = rows.filter((row) => row.level === firstLevel);
  if (own.length > 0) return own.map(({ label, field }) => ({ label, field }));
  return columns.map((col) => ({ label: toLabel(col), field: col }));
}

export async function seed(db: Kysely<any>): Promise<void> {
  for (const entity of entityReports) {
    if (entity.columns.length === 0) continue;
    const fields = await windowFields(db, entity.tableName, entity.columns);
    const layout = buildLayout(entity.displayName, fields);
    await db
      .insertInto('sys_report_designs')
      .values({
        table_name: entity.tableName,
        name: `${entity.displayName} Default Report`,
        layout: JSON.stringify(layout),
      })
      .onConflict((oc) => oc.column('table_name').doNothing())
      .execute();
  }
  console.log('✓ Default report designs seeded');
}

