/**
 * System Reference Types Seed
 *
 * Generated: {{now}}
 */

import { Kysely } from 'kysely';
import { v4 as uuidv4 } from 'uuid';

export async function seed(db: Kysely<any>): Promise<void> {
  const now = new Date();
  const createdBy = 'system';

  const references = [
    { sys_reference_id: 10, name: 'String', description: 'Variable length string', validation_type: 'S' },
    { sys_reference_id: 11, name: 'Integer', description: 'Whole number', validation_type: 'S' },
    { sys_reference_id: 12, name: 'Amount', description: 'Decimal number for amounts', validation_type: 'S' },
    { sys_reference_id: 13, name: 'ID', description: 'Unique identifier (UUID)', validation_type: 'S' },
    { sys_reference_id: 14, name: 'Text', description: 'Long text/memo field', validation_type: 'S' },
    { sys_reference_id: 15, name: 'Date', description: 'Date only', validation_type: 'S' },
    { sys_reference_id: 16, name: 'DateTime', description: 'Date and time', validation_type: 'S' },
    { sys_reference_id: 17, name: 'List', description: 'Dropdown list from sys_ref_list', validation_type: 'L' },
    { sys_reference_id: 18, name: 'Table', description: 'Reference to another table', validation_type: 'T' },
    { sys_reference_id: 19, name: 'Table Direct', description: 'Direct reference using column name', validation_type: 'T' },
    { sys_reference_id: 20, name: 'Yes-No', description: 'Boolean yes/no', validation_type: 'S' },
    { sys_reference_id: 24, name: 'URL', description: 'Web URL', validation_type: 'S' },
    { sys_reference_id: 28, name: 'JSON', description: 'JSON data', validation_type: 'S' },
    { sys_reference_id: 30, name: 'Email', description: 'Email address', validation_type: 'S' },
    { sys_reference_id: 31, name: 'Phone', description: 'Phone number', validation_type: 'S' },
    { sys_reference_id: 100, name: 'EntityType', description: 'Entity type classification', validation_type: 'L' },
    { sys_reference_id: 101, name: 'AccessLevel', description: 'Access level for windows and tables', validation_type: 'L' },
  ];

  for (const ref of references) {
    await db.insertInto('sys_reference')
      .values({ ...ref, entity_type: 'S', is_active: true, created_by: createdBy, updated_by: createdBy, created_at: now, updated_at: now })
      .onConflict((oc) => oc.column('sys_reference_id').doNothing())
      .execute();
  }

  const refLists = [
    { sys_reference_id: 100, value: 'S', name: 'System Only' },
    { sys_reference_id: 100, value: 'C', name: 'Client' },
    { sys_reference_id: 100, value: 'O', name: 'Organization' },
    { sys_reference_id: 100, value: 'U', name: 'User Maintained' },
    { sys_reference_id: 101, value: 'M', name: 'Maintain' },
    { sys_reference_id: 101, value: 'T', name: 'Transaction' },
    { sys_reference_id: 101, value: 'Q', name: 'Query' },
    { sys_reference_id: 101, value: 'A', name: 'Admin Only' },
  ];

  for (const ref of refLists) {
    await db.insertInto('sys_ref_list')
      .values({ sys_ref_list_id: uuidv4(), ...ref, entity_type: 'S', is_active: true, created_by: createdBy, updated_by: createdBy, created_at: now, updated_at: now })
      .onConflict((oc) => oc.doNothing())
      .execute();
  }

  console.log(`✓ Seeded ${references.length} sys_reference types`);

  // ==========================================================================
  // Model enums — one list reference per `%%enum` a `%%field` binds a column to
  // ==========================================================================
  // Ids run from 1000 up. The generated forms render any reference at or above
  // 1000 as a dropdown fed by /sys/ref-list, so seeding these is what turns a
  // modelled enum into a select: before this, a column the model constrained to
  // six values was a free-text box, and `status` accepted anything typed into
  // it — including values the state machine has no transition for.
  const modelEnums = [
{{#each modelEnums}}
    { id: {{referenceId}}, name: '{{name}}', values: [{{#each values}}'{{this}}'{{#unless @last}}, {{/unless}}{{/each}}] },
{{/each}}
  ];

  for (const modelEnum of modelEnums) {
    await db.insertInto('sys_reference')
      .values({
        sys_reference_id: modelEnum.id,
        name: modelEnum.name,
        description: `Values allowed for ${modelEnum.name}`,
        validation_type: 'L',
        entity_type: 'U',
        is_active: true,
        created_by: createdBy,
        updated_by: createdBy,
        created_at: now,
        updated_at: now,
      })
      .onConflict((oc) => oc.column('sys_reference_id').doNothing())
      .execute();

    for (const value of modelEnum.values) {
      await db.insertInto('sys_ref_list')
        .values({
          sys_ref_list_id: uuidv4(),
          sys_reference_id: modelEnum.id,
          value,
          // `pending_review` reads as "Pending Review" in a dropdown; the raw
          // value is what is stored and what every rule and workflow compares.
          name: value.split('_').map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(' '),
          entity_type: 'U',
          is_active: true,
          created_by: createdBy,
          updated_by: createdBy,
          created_at: now,
          updated_at: now,
        })
        .onConflict((oc) => oc.doNothing())
        .execute();
    }
  }

  if (modelEnums.length > 0) {
    const valueCount = modelEnums.reduce((total, e) => total + e.values.length, 0);
    console.log(`✓ Seeded ${modelEnums.length} model enums (${valueCount} values)`);
  }
}

common/seeds/business-data.ts.hbs:
/**
 * Business Data Seed
 * Sample records for each business entity for E2E testing
 *
 * Generated: {{now}}
 */

import { Kysely, sql } from 'kysely';
import { v4 as uuidv4 } from 'uuid';

const SAMPLE_COUNT = 4;

/*
 * A column the model bound to a %%enum is seeded from that enum's own values —
 * `seedValue` takes them as its fourth argument and prefers them over the
 * name-keyed vocabulary it falls back to. Anything else puts a value in the column that the dictionary does not
 * offer, the dropdown cannot select, and — for a status backing a state
 * machine — no declared transition leads out of.
 */

/**
 * Primary keys are generated up front for every table so foreign key columns
 * can point at rows that actually exist, in either direction, regardless of the
 * order the tables are seeded in. Without this the sample data has no usable
 * relationships and nothing that traverses them (lookups, cascade rules,
 * cross-entity workflows) can be exercised on a freshly generated app.
 */
const ids: Record<string, string[]> = {
  {{#each entities}}
  '{{tableName}}': Array.from({ length: SAMPLE_COUNT }, () => uuidv4()),
  {{/each}}
};

const FK_COLUMN_TABLE_MAP: Record<string, string> = {
  {{#each fkOverrides}}
  '{{column}}': '{{table}}',
  {{/each}}
};

/*
 * Ids for a reference whose parent the model never declared. A column marked FK
 * whose entity is missing (the checker reports it as EML502 — `Document.
 * document_type_id` with no `DocumentType`) has no table to draw an id from and,
 * with no relationship drawn, no foreign key constraint to satisfy. Left null it
 * fails the NOT NULL the model asked for, one insert takes the whole seed down,
 * and the backend restarts until it gives up. A uuid no row has is the smaller
 * problem — only for a *required* column, and only when nothing declared could
 * have supplied one.
 */
const orphanIds: Record<string, string[]> = {};

function fk(column: string, index: number, required = false): string | null {
  if (FK_COLUMN_TABLE_MAP[column]) {
    const pool = ids[FK_COLUMN_TABLE_MAP[column]];
    if (pool && pool.length > 0) return pool[index % pool.length];
  }
  if (column.endsWith('_by_id') || column.endsWith('_by')) {
    for (const suffix of ['_by_id', '_by']) {
      if (!column.endsWith(suffix)) continue;
      const stem = `bus_${column.slice(0, -suffix.length)}`;
      const pool = ids[stem];
      if (pool && pool.length > 0) return pool[index % pool.length];
    }
    const userPool = ids['bus_user'] || ids['bus_staff'];
    if (userPool && userPool.length > 0) return userPool[index % userPool.length];
  }
  const parent = `bus_${column.replace(/_id$/, '')}`;
  const pool = ids[parent];
  if (pool && pool.length > 0) return pool[index % pool.length];
  // A column naming a person rather than a table — owner_id, manager_id,
  // assigned_to_id — has no `bus_owner` to resolve against. Point it at the
  // user pool, the same fallback `_by_id` already uses.
  if (/^(owner|manager|assignee|assigned_to|rep|agent|supervisor)_id$/.test(column)) {
    const userPool = ids['bus_user'] || ids['bus_staff'];
    if (userPool && userPool.length > 0) return userPool[index % userPool.length];
  }
  // Nothing to point at. An optional column stays null: that is honest, and a
  // fabricated code like 'CAM-0001' is not — it matches no row, so every join
  // through it silently returned nothing while looking like real data.
  if (!required) return null;
  // A required one cannot be null (see orphanIds), so it takes a stable uuid.
  const orphans = (orphanIds[column] ??= Array.from({ length: SAMPLE_COUNT }, () => uuidv4()));
  return orphans[index % orphans.length];
}

export async function seed(db: Kysely<any>): Promise<void> {
  const now = new Date();

  // Constraint checking is disabled so tables can be truncated and repopulated
  // in any order; the rows themselves are referentially consistent.
  await sql`SET session_replication_role = replica`.execute(db);

  {{#each entities}}
  // {{displayName}} ({{tableName}})
  await db.deleteFrom('{{tableName}}').execute();

  const {{camelCase name}}Records = [
    {{#each (range 1 4)}}
    {
      id: ids['{{../tableName}}'][{{@index}}],
      {{#each ../attributes}}
      {{#unless (eq name ../../primaryKey)}}
      {{#unless (eq name 'created_at')}}
      {{#unless (eq name 'updated_at')}}
      {{#unless (eq name 'deleted_at')}}
      {{#unless (eq name 'version')}}
      {{#if isMoveFact}}
        {{!-- A state machine's move fact (`<state>_at`): left empty, so the first edit of a seeded row starts no move nobody recorded. --}}
        {{name}}: null,
      {{else}}
      {{#switch (typeToReferenceId type)}}
        {{#case 10}}{{name}}: {{#if (or isForeignKey (endsWith name '_id'))}}fk('{{name}}', {{@../index}}, {{#if required}}true{{else}}false{{/if}}){{else}}'{{#if (eq name "email")}}test{{@../index}}@example.com{{else}}{{seedValue name @../index ../../displayName enumValues}}{{/if}}'{{/if}},{{/case}}
        {{#case 30}}{{name}}: 'test{{@../index}}@example.com',{{/case}}
        {{#case 31}}{{name}}: '555-{{@../index}}101',{{/case}}
        {{#case 11}}{{name}}: {{#if (or isForeignKey (endsWith name '_id'))}}fk('{{name}}', {{@../index}}, {{#if required}}true{{else}}false{{/if}}){{else}}{{seedNumber name @../index}}{{/if}},{{/case}}
        {{#case 12}}{{name}}: {{@../index}}.50,{{/case}}
        {{! Numeric args, not a string: '200X-0X-15' produced month 00 for the first record, which Postgres rejects. Month is 0-based here, so % 12 is always valid. }}
        {{#case 15}}{{name}}: new Date(2000 + {{@../index}}, {{@../index}} % 12, 15),{{/case}}
        {{#case 16}}{{name}}: new Date(Date.now() + {{@../index}} * 3600000),{{/case}}
        {{#case 20}}{{name}}: {{#if (eq @../index 2)}}false{{else}}true{{/if}},{{/case}}
        {{#case 13}}{{name}}: {{#if (or isForeignKey (endsWith name '_id'))}}fk('{{name}}', {{@../index}}, {{#if required}}true{{else}}false{{/if}}){{else}}uuidv4(){{/if}},{{/case}}
        {{#case 14}}{{name}}: 'Sample {{name}} text {{@../index}}',{{/case}}
        {{#default}}{{name}}: '{{seedValue name @../index ../../displayName enumValues}}',{{/default}}
      {{/switch}}
      {{/if}}
      {{/unless}}
      {{/unless}}
      {{/unless}}
      {{/unless}}
      {{/unless}}
      {{/each}}
      version: 1,
      // Inserted straight into the table, so the promotion that would normally
      // set this never runs and the column keeps its 'draft' default — which
      // put a DRAFT badge on the header of every sample record in the
      // application, on data that is complete. These rows are final.
      doc_status: 'final',
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
    {{/each}}
  ];

  await db.insertInto('{{tableName}}').values({{camelCase name}}Records).execute();

  {{/each}}

  // Re-enable FK constraint checking
  await sql`SET session_replication_role = DEFAULT`.execute(db);

  console.log('✓ Business sample data seeded');
}

